/***************************************************************************************
   BOOT SIM TEXT -- entry point
   Randomly selects one of three sequences each boot.
   Seeded from the Teensy 4.1 ARM DWT cycle counter (ARM_DWT_CYCCNT) — entropy
   without needing an analog pin.
****************************************************************************************/
void bootSimText(KCM_TFT &tft) {
  tft.fillScreen(TFT_BLACK);

  // Enable ARM cycle counter and seed random() from it.
  // The counter has genuine jitter from hardware init timing differences boot to boot.
  ARM_DEMCR |= ARM_DEMCR_TRCENA;
  ARM_DWT_CTRL |= ARM_DWT_CTRL_CYCCNTENA;
  randomSeed(ARM_DWT_CYCCNT ^ (micros() << 13) ^ (micros() * 31337UL));

  switch (random(3)) {
    case 0: _boot_B(tft); break;
    case 1: _boot_C(tft); break;
    case 2: _boot_E(tft); break;
  }
}

/***************************************************************************************
   Compass.ino -- Shared compass-rose renderer (ROVER and NAV)

   A rotating compass card: outer ring, 5° ticks with 30° majors, cardinal letters and
   numeric labels, a fixed nose triangle at 12 o'clock, and bearing markers placed by
   world heading. The card rotates under the nose, so the vessel's own heading is
   always straight up.

   Extracted verbatim from Screen_ROVR.ino when the NAV screen was added, rather than
   copied: this project has consolidated the reticle layer (MNVR/TGT/DOCK) and the EADI
   tape (SCFT/ACFT) the same way, and a second hand-maintained compass would be the
   third place to fix any bug found in the first.

   The split follows the same rule those two use. Everything here is geometry and
   pixels — it reads no telemetry and owns no state. The caller supplies a CompassGeom
   (its own radii) and a CompassCache (its own prev-drawn values, so the redraw gating
   stays per-screen), and decides what a marker means.

   Screen angle convention: measured from 12 o'clock, increasing clockwise. A world
   bearing appears on the card at (worldDeg - headingDeg), so with the card rotated to
   the vessel's heading, north sits at its true relative bearing.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


/***************************************************************************************
   POLAR -> SCREEN
   x = cx + r*sin(screenDeg), y = cy - r*cos(screenDeg): clockwise from 12 o'clock,
   with y inverted for screen coordinates.
****************************************************************************************/
void compassPolar(const CompassGeom &g, float screenDeg, int16_t r, int16_t &x, int16_t &y) {
  float rad = screenDeg * (float)DEG_TO_RAD;
  x = (int16_t)((float)g.cx + (float)r * sinf(rad));
  y = (int16_t)((float)g.cy - (float)r * cosf(rad));
}


/***************************************************************************************
   OUTER RING
   Stationary chrome. Ticks stop short of it (rTickOuter < rRing) so a tick erase can
   never reach the ring, which is what lets the ring be drawn once and left alone.

   Light grey, one step brighter than the minor ticks it encloses -- ROVER's shipped
   value, inherited here so the two navigation screens read the same.
****************************************************************************************/
void compassDrawRing(KCM_TFT &tft, const CompassGeom &g) {
  tft.drawCircle(g.cx, g.cy, g.rRing, TFT_LIGHT_GREY);
}


/***************************************************************************************
   TICKS — every 5°, with a longer lighter tick every 30°
****************************************************************************************/
void compassDrawTicks(KCM_TFT &tft, const CompassGeom &g, float headingDeg, bool erase) {
  for (int16_t worldDeg = 0; worldDeg < 360; worldDeg += 5) {
    float screenDeg = (float)worldDeg - headingDeg;
    int16_t x0, y0, x1, y1;
    if (worldDeg % 30 == 0) {
      compassPolar(g, screenDeg, g.rTickOuter,      x1, y1);
      compassPolar(g, screenDeg, g.rTickMajorInner, x0, y0);
      tft.drawLine(x0, y0, x1, y1, erase ? TFT_BLACK : TFT_LIGHT_GREY);
    } else {
      compassPolar(g, screenDeg, g.rTickOuter,      x1, y1);
      compassPolar(g, screenDeg, g.rTickMinorInner, x0, y0);
      tft.drawLine(x0, y0, x1, y1, erase ? TFT_BLACK : TFT_GREY);
    }
  }
}


/***************************************************************************************
   LABELS — N/E/S/W at the cardinals, two-digit tens elsewhere
   Erase fills each glyph box with a hardware fillRect rather than re-rendering the
   glyph in black: text rasterisation is the most expensive software primitive in this
   driver, and the fill covers the same box for a fraction of the cost.
****************************************************************************************/
void compassDrawLabels(KCM_TFT &tft, const CompassGeom &g, float headingDeg, bool erase) {
  tft.setFont(Roboto_Black_28);
  const int16_t capH = (int16_t)Roboto_Black_28.cap_height;

  struct LabelSpec { int16_t worldDeg; const char *text; uint16_t color; bool letter; };
  static const LabelSpec labels[] = {
    {   0, "N",  TFT_YELLOW,     true  },
    {  30, "03", TFT_LIGHT_GREY, false },
    {  60, "06", TFT_LIGHT_GREY, false },
    {  90, "E",  TFT_WHITE,      true  },
    { 120, "12", TFT_LIGHT_GREY, false },
    { 150, "15", TFT_LIGHT_GREY, false },
    { 180, "S",  TFT_WHITE,      true  },
    { 210, "21", TFT_LIGHT_GREY, false },
    { 240, "24", TFT_LIGHT_GREY, false },
    { 270, "W",  TFT_WHITE,      true  },
    { 300, "30", TFT_LIGHT_GREY, false },
    { 330, "33", TFT_LIGHT_GREY, false },
  };

  for (uint8_t i = 0; i < sizeof(labels) / sizeof(labels[0]); i++) {
    float screenDeg = (float)labels[i].worldDeg - headingDeg;
    int16_t x, y;
    compassPolar(g, screenDeg, labels[i].letter ? g.rLetter : g.rNumLabel, x, y);

    // Roboto_Black_28 metrics (empirical): glyph ~16 px wide, ~24 px tall.
    uint8_t textLen = strlen(labels[i].text);
    int16_t cursorX = x - (int16_t)(textLen * 16) / 2;
    int16_t cursorY = y - 24 / 2;

    if (erase) {
      int16_t realW = getFontStringWidth(&Roboto_Black_28, labels[i].text);
      tft.fillRect(cursorX - 1, cursorY, realW + 2, capH, TFT_BLACK);
    } else {
      tft.setTextColor(labels[i].color, TFT_BLACK);
      tft.setCursor(cursorX, cursorY);
      tft.print(labels[i].text);
    }
  }
}


/***************************************************************************************
   NOSE — fixed triangle outside the ring at 12 o'clock, pointing inward.
   Stationary: the card rotates beneath it, so it always marks vessel heading.
****************************************************************************************/
void compassDrawNose(KCM_TFT &tft, const CompassGeom &g) {
  int16_t tipX, tipY, blX, blY, brX, brY;
  compassPolar(g, 0.0f, g.noseRTip, tipX, tipY);
  float angOffset = (float)g.noseHalfW / (float)g.noseRBase * (180.0f / (float)PI);
  compassPolar(g, -angOffset, g.noseRBase, blX, blY);
  compassPolar(g,  angOffset, g.noseRBase, brX, brY);
  tft.fillTriangle(tipX, tipY, blX, blY, brX, brY, TFT_WHITE);
}


/***************************************************************************************
   BEARING MARKER — triangle inside the ring at a given screen bearing, tip outward.
   What it means is the caller's business: ROVER uses one for the target, NAV uses two
   (target and ground track).

   Erase fills the triangle's bounding rectangle rather than drawing a black triangle.
   A triangle-based erase left trails at certain angles, because the rasteriser's edge
   rules differ between the drawn and erased passes; a padded bounding rect cannot.
****************************************************************************************/
void compassDrawMarker(KCM_TFT &tft, const CompassGeom &g, float screenDeg,
                       uint16_t colour, bool erase) {
  int16_t tipX, tipY, blX, blY, brX, brY;
  compassPolar(g, screenDeg, g.mkRTip, tipX, tipY);
  float angOffset = (float)g.mkHalfW / (float)g.mkRBase * (180.0f / (float)PI);
  compassPolar(g, screenDeg - angOffset, g.mkRBase, blX, blY);
  compassPolar(g, screenDeg + angOffset, g.mkRBase, brX, brY);

  if (erase) {
    int16_t xMin = tipX, xMax = tipX, yMin = tipY, yMax = tipY;
    if (blX < xMin) xMin = blX;
    if (brX < xMin) xMin = brX;
    if (blX > xMax) xMax = blX;
    if (brX > xMax) xMax = brX;
    if (blY < yMin) yMin = blY;
    if (brY < yMin) yMin = brY;
    if (blY > yMax) yMax = blY;
    if (brY > yMax) yMax = brY;
    const int16_t pad = 3;
    tft.fillRect(xMin - pad, yMin - pad,
                 (xMax - xMin) + 2 * pad + 1, (yMax - yMin) + 2 * pad + 1, TFT_BLACK);
  } else {
    tft.fillTriangle(tipX, tipY, blX, blY, brX, brY, colour);
  }
}


/***************************************************************************************
   CARD UPDATE — rotate the ticks and labels when the heading has moved enough.
   Erase at the old heading, draw at the new one. The ring and nose are stationary and
   are not touched. Returns true if the card was redrawn, which the caller may need in
   order to re-stamp anything that overlaps.
****************************************************************************************/
bool compassUpdateCard(KCM_TFT &tft, const CompassGeom &g, CompassCache &c,
                       float headingDeg, float threshDeg) {
  if (c.prevHeading > -9000.0f &&
      fabsf(eadiHdgDelta(headingDeg, c.prevHeading)) < threshDeg) return false;

  if (c.prevHeading > -9000.0f) {
    compassDrawTicks(tft, g, c.prevHeading, true);
    compassDrawLabels(tft, g, c.prevHeading, true);
  }
  compassDrawTicks(tft, g, headingDeg, false);
  compassDrawLabels(tft, g, headingDeg, false);
  c.prevHeading = headingDeg;
  return true;
}


/***************************************************************************************
   MARKER PAIR UPDATE — two markers that share one annulus. Erases the old markers and
   draws the new ones when either has moved or its availability has changed. Screen
   bearing is the world bearing minus vessel heading, wrapped to +/-180.

   A single-marker update is correct on its own but not in company: each marker's erase is
   a bounding box a few pixels larger than the triangle, and two markers on the same ring
   pass through each other as the card turns. Whichever moves erases the other and does
   not put it back, so on NAVIGATION the moving target-bearing marker would sweep the
   ring once and take the stationary ground-track marker with it.

   The fix is the one the ascent ladder's two altitude markers use: when either has
   changed, erase both, then draw both. A proximity test asking "are they close enough to
   interfere?" is the version that leaves half a marker on the screen, because the answer
   depends on the erase pad, the triangle's bounding box and the angle between them.
   Two triangles per frame cost nothing.
****************************************************************************************/
bool compassUpdateMarkerPair(KCM_TFT &tft, const CompassGeom &g,
                             CompassMarkerCache &ca, bool availA, float degA, uint16_t colA,
                             CompassMarkerCache &cb, bool availB, float degB, uint16_t colB,
                             float threshDeg) {
  const bool chgA = (availA != ca.prevAvail) ||
                    (availA && fabsf(eadiHdgDelta(degA, ca.prevScreenDeg)) >= threshDeg);
  const bool chgB = (availB != cb.prevAvail) ||
                    (availB && fabsf(eadiHdgDelta(degB, cb.prevScreenDeg)) >= threshDeg);
  if (!chgA && !chgB) return false;

  if (ca.prevAvail) compassDrawMarker(tft, g, ca.prevScreenDeg, colA, true);
  if (cb.prevAvail) compassDrawMarker(tft, g, cb.prevScreenDeg, colB, true);

  if (availA) { compassDrawMarker(tft, g, degA, colA, false); ca.prevScreenDeg = degA; }
  if (availB) { compassDrawMarker(tft, g, degB, colB, false); cb.prevScreenDeg = degB; }
  ca.prevAvail = availA;
  cb.prevAvail = availB;
  // The caller may have its own artwork attached to one of these markers -- NAVIGATION's
  // track stalk runs into the ground-track triangle's base -- and a marker's erase box is
  // padded 3 px beyond the triangle, so a redraw here can take a bite out of it. Say so,
  // rather than leaving the caller to guess from its own change test.
  return true;
}


/***************************************************************************************
   ConsoleShared.ino -- Infrastructure shared by the three autopilot consoles
   (ASCENT AUTOPILOT, AIRCRAFT AUTOPILOT, ROVER AUTOPILOT).

   Three things live here so that every console uses one copy:
     1. The outbound command queue (InfoDisp -> Controller_Main). One command in flight
        at a time, sequence-numbered, acknowledged by the master echoing the sequence.
        Moved out of Screen_LNCH_AscentAP.ino unchanged when the second and third
        consoles arrived; the byte-level contract is unchanged
        (Documents/Developer/Ascent_Autopilot_Interface.md).
     2. The numeric keypad modal. A console opens it with a KpField descriptor and a
        commit callback; the keypad owns the touch surface until ENT / OFF / CANCEL.
     3. Drawing helpers for the shared console grid: column headers, mode buttons in
        their three states, value boxes, cached value text.

   This tab sorts after AAA_* (so TITLE_TOP and the row helpers exist) and before the
   Screen_* tabs that call it. API declarations are in KCMk1_InfoDisp.h.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// ── Palette (the ascent console's) ────────────────────────────────────────────────────
static const uint16_t CON_LBL = KDC_LABEL_COLOR;
static const uint16_t CON_HDR = TFT_WHITE;
static const uint16_t CON_BOX = TFT_GREY;
static const uint16_t CON_EDT = TFT_SKY;
#define CON_F_HDR (&Roboto_Black_28)
#define CON_F_VAL (&Roboto_Black_32)
#define CON_F_BTN (&Roboto_Black_24)


/***************************************************************************************
   1. OUTBOUND COMMAND CHANNEL
   Pilot edits and mode taps queue here as (opcode, float-payload) commands. The I2C
   master reads the head command from the outbound packet, applies it, then
   acknowledges it by echoing the command's sequence number in its next inbound packet,
   which pops the queue. Pending (cyan) cues clear separately, once the master echoes the
   accepted value or mode back in a status frame — so the UI confirms the round trip,
   not merely command delivery.
****************************************************************************************/
struct ApCmd { uint8_t op; float payload; };
static const uint8_t AP_CMDQ_LEN = 16;
static ApCmd   apCmdQ[AP_CMDQ_LEN];
static uint8_t apCmdHead = 0, apCmdTail = 0;   // ring-buffer indices (empty when equal)
static uint8_t apCmdCurSeq = 0;                // seq of head command in flight (0 = none)
static uint8_t apCmdSeqCtr = 0;                // monotonic seq generator, wraps 1..255

// Returns true when the command was actually queued. Callers that show a pending cue
// must gate it on this: a cue for a command that was never sent would never clear.
bool apEnqueueCmd(uint8_t op, float payload) {
#if INFO_DISP_IS_PFD_UNIT
  // Only the mission panel (unit 2) owns the autopilots. Unit 1 has no console key, so
  // it should never reach here — this is the backstop that makes the single-editor rule
  // a property of the command channel rather than of the navigation table.
  (void)op; (void)payload;
  return false;
#else
  // No master to drain the queue in demo — the demo applies the command to its own
  // autopilot models and publishes the result on the next frame, so the console's
  // round trip closes and its pending cue clears exactly as it does in flight.
  if (demoMode) return apDemoApplyCommand(op, payload) || hpDemoApplyCommand(op, payload);
  uint8_t next = (uint8_t)((apCmdTail + 1) % AP_CMDQ_LEN);
  if (next == apCmdHead) return false;         // full — drop (queue holds 15, never happens)
  apCmdQ[apCmdTail].op = op;
  apCmdQ[apCmdTail].payload = payload;
  apCmdTail = next;
  return true;
#endif
}

// Assign a sequence number to a newly-exposed head command. Main-thread only; called
// from updateI2CState() before outbound change-detection.
void apPumpCommandQueue() {
  if (apCmdCurSeq == 0 && apCmdHead != apCmdTail) {
    if (++apCmdSeqCtr == 0) apCmdSeqCtr = 1;   // seq is 1..255; 0 means "no command"
    apCmdCurSeq = apCmdSeqCtr;
  }
}

// Write the head command into a 6-byte field: [seq][op][payload float, little-endian].
// Pure read — safe to call for both the live and candidate packet buffers.
void apFillOutboundCmd(uint8_t *out6) {
  if (apCmdCurSeq != 0) {
    out6[0] = apCmdCurSeq;
    out6[1] = apCmdQ[apCmdHead].op;
    memcpy(&out6[2], &apCmdQ[apCmdHead].payload, 4);
  } else {
    out6[0] = 0;
    out6[1] = AP_CMD_NOP;
    memset(&out6[2], 0, 4);
  }
}

// Master acknowledged sequence `ackSeq` (0 = no ack); pop the head if it matches the
// in-flight command so the next queued command is exposed on the following pump.
void apAckCommand(uint8_t ackSeq) {
  if (ackSeq != 0 && ackSeq == apCmdCurSeq) {
    apCmdHead = (uint8_t)((apCmdHead + 1) % AP_CMDQ_LEN);
    apCmdCurSeq = 0;
  }
}


/***************************************************************************************
   2. NUMERIC KEYPAD
****************************************************************************************/
static bool       kpOpenFlag   = false;
static bool       kpRedraw     = false;
static bool       kpClosedFlag = false;
static KpField    kpField      = { "", "", 0.0f, 0.0f, false, false, 0 };
static int8_t     kpIdx        = -1;
static KpCommitFn kpCommit     = nullptr;
static char       kpBuf[12];
static uint8_t    kpLen        = 0;

static const int16_t KP_W = 480, KP_H = 384;
static const int16_t KP_X = (CONTENT_W - KP_W) / 2;                        // 230
static const int16_t KP_Y = TITLE_TOP + (SCREEN_H - TITLE_TOP - KP_H) / 2; // ~139
static const int16_t KP_HDR_H = 80;
static const int16_t KAX = KP_X + 6, KAY = KP_Y + KP_HDR_H;
static const int16_t KAW = KP_W - 12, KAH = KP_H - KP_HDR_H - 6;
static const int16_t KP_KEY_W = KAW / 4, KP_KEY_H = KAH / 4;
static const int16_t KP_CX = KP_X + KP_W - 74, KP_CY = KP_Y + 8, KP_CW = 66, KP_CH = 40;  // CANCEL

// Key labels (row-major).
static const char *const KP_KEYS[4][4] = {
  { "7",   "8", "9", "DEL" },
  { "4",   "5", "6", "CLR" },
  { "1",   "2", "3", "OFF" },
  { "+/-", "0", ".", "ENT" },
};

void kpOpen(const KpField &f, int8_t idx, KpCommitFn onCommit) {
  kpField = f; kpIdx = idx; kpCommit = onCommit;
  kpLen = 0; kpBuf[0] = '\0';
  kpOpenFlag = true; kpRedraw = true;
}

static void kpClose() { kpOpenFlag = false; kpClosedFlag = true; }

bool kpIsOpen()     { return kpOpenFlag; }
bool kpTakeClosed() { bool c = kpClosedFlag; kpClosedFlag = false; return c; }
void kpForceClose() { kpOpenFlag = false; kpRedraw = false; kpClosedFlag = false; kpLen = 0; kpIdx = -1; }

// Format the live entry with thousands separators in the integer part, preserving a
// leading sign and any decimal portion being typed.
static String kpCommaEntry(const char *buf) {
  String work(buf), sign;
  if (work.length() && work[0] == '-') { sign = "-"; work = work.substring(1); }
  int dot = work.indexOf('.');
  String ip = (dot >= 0) ? work.substring(0, dot) : work;
  String fp = (dot >= 0) ? work.substring(dot)    : String("");
  String out; int len = ip.length();
  for (int i = 0; i < len; i++) {
    if (i > 0 && (len - i) % 3 == 0) out += ",";
    out += ip[i];
  }
  return sign + out + fp;
}

void kpDraw(KCM_TFT &tft) {
  if (!kpOpenFlag || !kpRedraw) return;
  kpRedraw = false;
  const KpField &e = kpField;
  tft.fillRect(KP_X, KP_Y, KP_W, KP_H, TFT_OFF_BLACK);
  tft.drawRect(KP_X, KP_Y, KP_W, KP_H, TFT_SKY);
  tft.drawRect(KP_X + 1, KP_Y + 1, KP_W - 2, KP_H - 2, TFT_SKY);
  // Header: field name, range, live entry
  textLeft(tft, &Roboto_Black_24, KP_X + 10, KP_Y + 4, KP_W - 90, 28, e.name, TFT_WHITE, TFT_OFF_BLACK);
  { char r[48];
    if (e.mx >= 100000.0f) snprintf(r, sizeof(r), "enter in %s (min %g)", e.units, e.mn);
    else                   snprintf(r, sizeof(r), "range %g to %g %s", e.mn, e.mx, e.units);
    textLeft(tft, &Roboto_Black_16, KP_X + 10, KP_Y + 34, KP_W - 90, 20, r, TFT_LIGHT_GREY, TFT_OFF_BLACK); }
  { String ent = (kpLen ? kpCommaEntry(kpBuf) : String("_")) + " " + e.units;
    textRight(tft, &Roboto_Black_28, KP_X + 6, KP_Y + 50, KP_W - 12, 28, ent, TFT_SKY, TFT_OFF_BLACK); }
  // CANCEL
  tft.fillRect(KP_CX, KP_CY, KP_CW, KP_CH, TFT_OFF_BLACK);
  tft.drawRect(KP_CX, KP_CY, KP_CW, KP_CH, TFT_RED);
  textCenter(tft, &Roboto_Black_24, KP_CX, KP_CY, KP_CW, KP_CH, "X", TFT_RED, TFT_OFF_BLACK);
  // Keys
  for (uint8_t r = 0; r < 4; r++)
    for (uint8_t c = 0; c < 4; c++) {
      const char *k = KP_KEYS[r][c];
      bool dis = (strcmp(k, "OFF") == 0 && !e.allowOff) || (strcmp(k, "+/-") == 0 && !e.allowSign);
      int16_t kx = KAX + c * KP_KEY_W, ky = KAY + r * KP_KEY_H;
      uint16_t kb = dis ? TFT_OFF_BLACK : TFT_GREY;
      uint16_t kf = dis ? TFT_DARK_GREY : (strcmp(k, "ENT") == 0 ? TFT_NEON_GREEN :
                    strcmp(k, "OFF") == 0 ? TFT_ORANGE : TFT_WHITE);
      tft.drawRect(kx, ky, KP_KEY_W - 4, KP_KEY_H - 4, kb);
      textCenter(tft, &Roboto_Black_28, kx, ky, KP_KEY_W - 4, KP_KEY_H - 4, k, kf, TFT_OFF_BLACK);
    }
}

static void kpDoCommit(bool off) {
  float v = (kpLen ? atof(kpBuf) : 0.0f);
  if (v < kpField.mn) v = kpField.mn;
  if (v > kpField.mx) v = kpField.mx;
  KpCommitFn fn = kpCommit;
  int8_t idx = kpIdx;
  kpClose();
  if (fn) fn(idx, v, off);
}

void kpTouch(uint16_t x, uint16_t y) {
  if (!kpOpenFlag) return;
  // CANCEL
  if (x >= KP_CX && x < KP_CX + KP_CW && y >= KP_CY && y < KP_CY + KP_CH) { kpClose(); return; }
  // Key grid
  if (x < KAX || y < KAY) return;
  int16_t c = (x - KAX) / KP_KEY_W, r = (y - KAY) / KP_KEY_H;
  if (c < 0 || c > 3 || r < 0 || r > 3) return;
  const char *k = KP_KEYS[r][c];
  if (strcmp(k, "ENT") == 0) { kpDoCommit(false); return; }
  if (strcmp(k, "CLR") == 0) { kpLen = 0; kpBuf[0] = '\0'; kpRedraw = true; return; }
  if (strcmp(k, "DEL") == 0) { if (kpLen) { kpBuf[--kpLen] = '\0'; kpRedraw = true; } return; }
  if (strcmp(k, "OFF") == 0) { if (kpField.allowOff) kpDoCommit(true); return; }
  if (strcmp(k, "+/-") == 0) {                      // sign toggle
    if (!kpField.allowSign) return;
    if (kpLen && kpBuf[0] == '-') { memmove(kpBuf, kpBuf + 1, kpLen); kpLen--; }
    else if (kpLen < sizeof(kpBuf) - 1) { memmove(kpBuf + 1, kpBuf, kpLen + 1); kpBuf[0] = '-'; kpLen++; }
    kpRedraw = true; return;
  }
  // digit or '.'
  if (kpLen < sizeof(kpBuf) - 1) {
    if (k[0] == '.' && strchr(kpBuf, '.')) return;   // one decimal point
    kpBuf[kpLen++] = k[0]; kpBuf[kpLen] = '\0'; kpRedraw = true;
  }
}


/***************************************************************************************
   3. DRAWING HELPERS
****************************************************************************************/
// Pick a legible text colour for an arbitrary RGB565 background by its perceived
// luminance (Rec. 601). White washes out on the light colours (CYAN, SKY); on those we
// use TFT_DARK_GREY — the standard dark-on-light button text used elsewhere.
uint16_t conTextOn(uint16_t bg) {
  uint16_t r = ((bg >> 11) & 0x1F) * 255 / 31;
  uint16_t g = ((bg >> 5)  & 0x3F) * 255 / 63;
  uint16_t b = ( bg        & 0x1F) * 255 / 31;
  uint16_t lum = (uint16_t)((r * 299 + g * 587 + b * 114) / 1000);
  return (lum > 140) ? TFT_DARK_GREY : TFT_WHITE;
}

// Banner rule, column dividers and the three column headers.
void conDrawColumns(KCM_TFT &tft, const char *h1, const char *h2, const char *h3) {
  tft.fillRect(0, CON_BANNER_Y + CON_BANNER_H, CONTENT_W, 2, TFT_GREY);
  tft.drawLine(CON_DIV1_X, CON_COL_Y, CON_DIV1_X, CON_COL_BOT, TFT_GREY);
  tft.drawLine(CON_DIV2_X, CON_COL_Y, CON_DIV2_X, CON_COL_BOT, TFT_GREY);
  textLeft(tft, CON_F_HDR, CON_C1X, CON_COL_Y, CON_COLW, 32, h1, CON_HDR, TFT_BLACK);
  textLeft(tft, CON_F_HDR, CON_C2X, CON_COL_Y, CON_COLW, 32, h2, CON_HDR, TFT_BLACK);
  textLeft(tft, CON_F_HDR, CON_C3X, CON_COL_Y, CON_COLW, 32, h3, CON_HDR, TFT_BLACK);
}

// A mode button in one of its three states. Off: grey outline, white caption.
// Pending: cyan 3 px outline, cyan caption (tap sent, not yet echoed). Engaged: green fill.
void conDrawModeButton(KCM_TFT &tft, int16_t x, int16_t y, int16_t w, int16_t h,
                       const char *label, ConBtnState st) {
  tft.fillRect(x, y, w, h, TFT_BLACK);
  uint16_t fg;
  switch (st) {
    case CON_BTN_ON:
      tft.fillRect(x, y, w, h, TFT_DARK_GREEN);
      fg = TFT_WHITE;
      break;
    case CON_BTN_PENDING:
      tft.drawRect(x, y, w, h, TFT_CYAN);
      tft.drawRect(x + 1, y + 1, w - 2, h - 2, TFT_CYAN);
      tft.drawRect(x + 2, y + 2, w - 4, h - 4, TFT_CYAN);
      fg = TFT_CYAN;
      break;
    default:
      tft.drawRect(x, y, w, h, TFT_GREY);
      fg = TFT_WHITE;
      break;
  }
  textCenter(tft, CON_F_BTN, x, y, w, h, label, fg, st == CON_BTN_ON ? TFT_DARK_GREEN : TFT_BLACK);
}

// The outlined value box at the right of a row.
void conDrawValueBox(KCM_TFT &tft, int16_t colX, uint8_t row) {
  tft.drawRect(conValX(colX), conRowY(row) + 4, CON_VALW - 2, CON_VALH, CON_BOX);
}

// Cached value draw. The cache compare allocates nothing; the String is built only for
// a value about to be drawn.
void conPut(KCM_TFT &tft, ScreenType screen, uint8_t slot, int16_t x, int16_t y,
            int16_t w, int16_t h, const char *val, uint16_t fg) {
  RowCache &rc = rowCache[(uint8_t)screen][slot];
  if (rc.fg == fg && rc.value == val) return;
  String v(val);
  printValue(tft, CON_F_VAL, x, y, w, h, "", v, fg, TFT_BLACK, TFT_BLACK, printState[(uint8_t)screen][slot]);
  rc.value = v; rc.fg = fg; rc.bg = TFT_BLACK;
}

/***************************************************************************************
   Demo.ino -- Demo mode for Kerbal Controller Mk1 Information Display
   Exercises all AppState fields and all conditional colour bands on every screen.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


static const uint32_t DEMO_UPDATE_MS = 100;
static uint32_t _demoLast  = 0;
static float    _demoPhase = 0.0f;

/***************************************************************************************
   DEMO-SIDE ASCENT AUTOPILOT
   In demo mode there is no Controller_Main to accept the console's commands and echo
   the accepted values back, so the demo plays that part. Console taps arrive here via
   apDemoApplyCommand(); stepDemoState() publishes these fields into state.ap* instead
   of the literals it used to hardcode, which closes the round trip the console expects
   — command out, accepted value back. Without it, an ARM/DISARM tap or a parameter
   edit would raise a pending cue that nothing could ever clear, because the demo would
   overwrite the field with its own literal on the very next frame.

   The ascent animation is gated on the armed state rather than driving it: the demo
   boots armed so the guidance outputs animate as they always have, DISARM parks it in
   IDLE, and ARM starts it running again from where it left off.
****************************************************************************************/
static bool     _demoApArmed   = true;      // boots armed so the animation runs as before
static float    _demoApT       = 0.0f;      // ascent timer, advances only while armed
static float    _demoApTgtAlt  = 80000.0f;
static float    _demoApIncl    = 6.0f;
static bool     _demoApSouth   = false;
static float    _demoApLoft    = 1.0f;
static bool     _demoApRollEn  = false;
static float    _demoApRollDeg = 0.0f;
static float    _demoApMaxG    = 4.0f;

// Applied from apEnqueueCmd() when demoMode is set. Returns true when the opcode was
// recognised, which is what raises the console's pending cue — cleared a frame later
// when stepDemoState() publishes the new value and apReconcilePending() sees it match.
bool apDemoApplyCommand(uint8_t op, float payload) {
  switch (op) {
    case AP_CMD_SET_TARGET_ALT:  _demoApTgtAlt = payload; return true;
    case AP_CMD_SET_INCLINATION: _demoApIncl   = payload; return true;
    case AP_CMD_SET_LAUNCH_DIR:  _demoApSouth  = (payload != 0.0f); return true;
    case AP_CMD_SET_LOFT:        _demoApLoft   = payload; return true;
    case AP_CMD_SET_MAXG:        _demoApMaxG   = payload; return true;
    case AP_CMD_SET_ROLL:
      // AP_ROLL_OFF is the disable sentinel, outside the +/-180 range.
      _demoApRollEn  = (fabsf(payload) <= 180.0f);
      if (_demoApRollEn) _demoApRollDeg = payload;
      return true;
    case AP_CMD_ARM:             _demoApArmed = true;  return true;
    case AP_CMD_DISARM:          _demoApArmed = false; return true;
    default: return false;
  }
}


/***************************************************************************************
   DEMO-SIDE HOLD-MODE AUTOPILOT
   Same idea for the AIRCRAFT AP / ROVER AP consoles: the demo plays Controller_Main,
   applying engage / setpoint commands to a small model and publishing it into
   state.hp* / state.rv* so the consoles' pending cues close. Engaging captures the
   demo's live value, as the master does.
****************************************************************************************/
static uint8_t _demoHpPitch = 0, _demoHpLat = 0, _demoHpThr = 0;
static float   _demoHpAtt = 5.0f, _demoHpAoa = 3.0f, _demoHpVs = 0.0f, _demoHpAlt = 6000.0f;
static float   _demoHpRoll = 0.0f, _demoHpHdg = 90.0f, _demoHpIas = 180.0f, _demoHpMach = 0.85f;
static uint8_t _demoHpReason = 0; static uint32_t _demoHpReasonMs = 0;
static bool    _demoRvCruise = false, _demoRvHdg = false, _demoRvTgt = false;
static float   _demoRvCruiseSp = 12.0f, _demoRvHdgSp = 45.0f;
static float   _demoRvMaxSpd = 20.0f, _demoRvMaxSlope = 20.0f, _demoRvMaxRoll = 25.0f;
static uint8_t _demoRvReason = 0; static uint32_t _demoRvReasonMs = 0;
static float   _demoHpGs = 3.0f, _demoRvFollow = 30.0f, _demoRvStop = 15.0f;
static bool    _demoRvFollowOn = false;
// Orbital / landing models (Mission_Autopilot.md)
static uint8_t _demoObMode = 0, _demoObPhase = 0; static uint32_t _demoObPhaseMs = 0;
static bool    _demoObAppr = false, _demoObWarp = true, _demoObStage = true;
static float   _demoObAp = 250000.0f, _demoObPe = 80000.0f, _demoObInc = 0.0f, _demoObRate = -2.0f, _demoObDist = 50.0f;
static uint8_t _demoObReason = 0; static uint32_t _demoObReasonMs = 0;
static uint8_t _demoLdMode = 0; static bool _demoLdEntry = false, _demoLdRadial = false;
static float   _demoLdRate = -4.0f, _demoLdAlt = 50.0f, _demoLdTwr = 0.0f, _demoLdMargin = 150.0f, _demoLdAoa = 8.0f, _demoLdRoll = 0.0f;
static uint8_t _demoLdReason = 0; static uint32_t _demoLdReasonMs = 0;

bool hpDemoApplyCommand(uint8_t op, float payload) {
  bool on = (payload != 0.0f);
  switch (op) {
    case HP_CMD_AP_OFF: _demoHpPitch = _demoHpLat = _demoHpThr = 0; _demoRvCruise = _demoRvHdg = _demoRvTgt = false;
                        _demoRvFollowOn = false; _demoObMode = 0; _demoObPhase = 0; _demoObAppr = false; _demoLdMode = 0; _demoLdEntry = false; return true;
    case HP_CMD_LVL:    _demoHpLat = 1; _demoHpRoll = 0.0f; _demoHpPitch = 3; _demoHpVs = 0.0f; return true;
    case HP_CMD_ENGAGE_ATT:  if (on) { _demoHpPitch = 1; _demoHpAtt = state.pitch; } else if (_demoHpPitch == 1) _demoHpPitch = 0; return true;
    case HP_CMD_ENGAGE_AOA:  if (on) { _demoHpPitch = 2; _demoHpAoa = state.pitch - state.srfVelPitch; } else if (_demoHpPitch == 2) _demoHpPitch = 0; return true;
    case HP_CMD_ENGAGE_VS:   if (on) { _demoHpPitch = 3; _demoHpVs = roundf(state.verticalVel); } else if (_demoHpPitch == 3) _demoHpPitch = 0; return true;
    case HP_CMD_ENGAGE_ALT:  if (on) { _demoHpPitch = 4; _demoHpAlt = roundf(state.altitude / 10.0f) * 10.0f; } else if (_demoHpPitch == 4) _demoHpPitch = 0; return true;
    case HP_CMD_ENGAGE_ROLL: if (on) { _demoHpLat = 1; _demoHpRoll = state.roll; } else if (_demoHpLat == 1) _demoHpLat = 0; return true;
    case HP_CMD_ENGAGE_HDG:  if (on) { _demoHpLat = 2; _demoHpHdg = roundf(state.heading); } else if (_demoHpLat == 2) _demoHpLat = 0; return true;
    case HP_CMD_ENGAGE_IAS:  if (on) { _demoHpThr = 1; _demoHpIas = state.IAS; } else if (_demoHpThr == 1) _demoHpThr = 0; return true;
    case HP_CMD_ENGAGE_MACH: if (on) { _demoHpThr = 2; _demoHpMach = state.machNumber; } else if (_demoHpThr == 2) _demoHpThr = 0; return true;
    case HP_CMD_SET_ATT:  _demoHpAtt = payload;  return true;
    case HP_CMD_SET_AOA:  _demoHpAoa = payload;  return true;
    case HP_CMD_SET_VS:   _demoHpVs = payload;   return true;
    case HP_CMD_SET_ALT:  _demoHpAlt = payload;  return true;
    case HP_CMD_SET_ROLL: _demoHpRoll = payload; return true;
    case HP_CMD_SET_HDG:  _demoHpHdg = payload;  return true;
    case HP_CMD_SET_IAS:  _demoHpIas = payload;  return true;
    case HP_CMD_SET_MACH: _demoHpMach = payload; return true;
    case HP_CMD_ENGAGE_CRUISE: _demoRvCruise = on; if (on) _demoRvCruiseSp = roundf(state.surfaceVel * 2.0f) * 0.5f; return true;
    case HP_CMD_ENGAGE_RHDG:   _demoRvHdg = on; if (on) { _demoRvTgt = false; _demoRvHdgSp = roundf(state.heading); } return true;
    case HP_CMD_ENGAGE_RTGT:
      if (on && !state.targetAvailable) { _demoRvReason = HP_REASON_REFUSED; _demoRvReasonMs = millis(); return true; }
      _demoRvTgt = on; if (on) _demoRvHdg = false; return true;
    case HP_CMD_SET_CRUISE:   _demoRvCruiseSp = payload; return true;
    case HP_CMD_SET_RHDG:     _demoRvHdgSp = payload;    return true;
    case HP_CMD_SET_MAXSPD:   _demoRvMaxSpd = payload;   return true;
    case HP_CMD_SET_MAXSLOPE: _demoRvMaxSlope = payload; return true;
    case HP_CMD_SET_MAXROLL:  _demoRvMaxRoll = payload;  return true;
    // ---- mission autopilot ----
    case HP_CMD_ENGAGE_NAV:  if (on && !state.targetAvailable) { _demoHpReason = HP_REASON_NO_TARGET; _demoHpReasonMs = millis(); return true; }
                             if (on) _demoHpLat = 3; else if (_demoHpLat == 3) _demoHpLat = 0; return true;
    case HP_CMD_ENGAGE_GS:   if (on && !state.targetAvailable) { _demoHpReason = HP_REASON_NO_TARGET; _demoHpReasonMs = millis(); return true; }
                             if (on) _demoHpPitch = 5; else if (_demoHpPitch == 5) _demoHpPitch = 0; return true;
    case HP_CMD_SET_GS:      _demoHpGs = payload; return true;
    case HP_CMD_ENGAGE_FOLLOW: _demoRvFollowOn = on; if (on) { _demoRvCruise = false; _demoRvHdg = _demoRvTgt = false; } return true;
    case HP_CMD_SET_FOLLOW_RANGE: _demoRvFollow = payload; return true;
    case HP_CMD_SET_STOP_DIST:    _demoRvStop = payload; return true;
    case OB_CMD_ARM_NODE: case OB_CMD_ARM_AP: case OB_CMD_ARM_PE: case OB_CMD_ARM_INC: {
      uint8_t m = (uint8_t)(op - OB_CMD_ARM_NODE + 1);
      if (on) { if (m == 1 && state.mnvrDeltaV <= 0.01f) { _demoObReason = HP_REASON_NO_NODE; _demoObReasonMs = millis(); return true; }
                _demoObMode = m; _demoObPhase = 1; _demoObAppr = false; }
      else if (_demoObMode == m) { _demoObMode = 0; _demoObPhase = 0; }
      return true;
    }
    case OB_CMD_ENGAGE_APPR: _demoObAppr = on; if (on) { _demoObMode = 0; _demoObPhase = 0; } return true;
    case OB_CMD_SET_AP: _demoObAp = payload; return true;
    case OB_CMD_SET_PE: _demoObPe = payload; return true;
    case OB_CMD_SET_INC: _demoObInc = payload; return true;
    case OB_CMD_SET_APPR_RATE: _demoObRate = payload; return true;
    case OB_CMD_SET_APPR_DIST: _demoObDist = payload; return true;
    case OB_CMD_SET_WARP: _demoObWarp = on; return true;
    case OB_CMD_SET_AUTOSTAGE: _demoObStage = on; return true;
    case OB_CMD_EXEC:
      if (_demoObPhase == 1) { _demoObPhase = 2; _demoObPhaseMs = millis(); }
      else if (_demoObPhase == 3 && _demoObWarp) { _demoObPhase = 4; _demoObPhaseMs = millis(); }
      return true;
    case LD_CMD_ENGAGE_DESC: case LD_CMD_ENGAGE_HOVR: case LD_CMD_ENGAGE_BRAKE: {
      uint8_t m = (uint8_t)(op - LD_CMD_ENGAGE_DESC + 1);
      if (on) _demoLdMode = m; else if (_demoLdMode == m) _demoLdMode = 0;
      return true;
    }
    case LD_CMD_ENGAGE_ENTRY: _demoLdEntry = on; return true;
    case LD_CMD_SET_DESC_RATE: _demoLdRate = payload; return true;
    case LD_CMD_SET_HOVR_ALT: _demoLdAlt = payload; return true;
    case LD_CMD_SET_TWR: _demoLdTwr = payload; return true;
    case LD_CMD_SET_MARGIN: _demoLdMargin = payload; return true;
    case LD_CMD_SET_ENTRY_AOA: _demoLdAoa = payload; return true;
    case LD_CMD_SET_ENTRY_ROLL: _demoLdRoll = payload; return true;
    case LD_CMD_SET_ATT_REF: _demoLdRadial = on; return true;
    default: return false;
  }
}


void initDemoMode() {
  state.vesselName      = "Jeb's Rocket";
  state.vesselType      = type_Ship;
  state.ctrlLevel       = 3;
  state.situation       = sit_Flying;
  state.isRecoverable   = false;
  state.gameSOI         = "Kerbin";
  state.crewCount       = 3;
  state.crewCapacity    = 4;
  state.commNetSignal   = 85;
  state.targetAvailable = true;
  state.rcs_on          = false;
  state.gear_on         = false;
  state.brakes_on       = false;
  state.drogueDeploy    = false;
  state.drogueCut       = false;
  state.mainDeploy      = false;
  state.mainCut         = false;
  state.heading         = 90.0f;
  state.pitch           = 15.0f;
  state.roll            = 0.0f;
  state.sasMode         = 0;     // STABILITY
  state.inAtmo          = false;
  state.airDensity      = 0.0f;
  currentBody           = getBodyParams(state.gameSOI);
}


void stepDemoState() {
  if (!demoMode) return;   // guard: no-op when called outside demo mode
  uint32_t now = millis();
  if (now - _demoLast < DEMO_UPDATE_MS) return;
  _demoLast = now;

  _demoPhase += 0.015f;

  // -----------------------------------------------------------------------
  // LNCH / APSI — altitude sweeps -75km..+75km, exercises:
  //   Alt: red (< 0), yellow (< 500m), green
  //   Vel switch: orbital above ~36km, surface below ~33km
  // -----------------------------------------------------------------------
  // Altitude: sweep independently so non-ORB screens (LNCH etc) exercise red/yellow bands.
  // When the ORB screen is active, override with the orbitally-consistent value below.
  state.altitude = 75000.0f * sinf(_demoPhase * 0.4f);

  // Orbital velocity — goes slightly negative to exercise red band
  state.orbitalVel  = 2000.0f * sinf(_demoPhase * 0.35f);   // -2000..+2000 m/s
  state.surfaceVel  = 1800.0f * sinf(_demoPhase * 0.38f);
  state.wheelThrottle = sinf(_demoPhase * 0.2f);   // -1..1: drives ROVER's FWD / REV blocks
  // verticalVel: large enough to drive ORB/SRF hysteresis switch, but also
  // sweeps through small negative values for realistic T_GRND calculation
  state.verticalVel = 15.0f * sinf(_demoPhase * 0.8f);      // -15..+15 m/s

  // Apoapsis/periapsis derived from orbital elements below — not set independently
  state.timeToAp    = 600.0f  * sinf(_demoPhase * 0.4f + 0.5f);
  state.timeToPe    = 2700.0f * sinf(_demoPhase * 0.38f + 1.5f);

  // Orbital elements
  state.orbitalPeriod = 3600.0f + 300.0f * sinf(_demoPhase + 0.8f);
  state.inclination   = 6.0f   + 4.0f   * sinf(_demoPhase + 1.2f);
  state.eccentricity  = 0.05f  + 0.04f  * sinf(_demoPhase + 0.3f);
  state.semiMajorAxis = 700000.0f + 80000.0f * sinf(_demoPhase * 0.1f);  // ~700km orbit
  state.LAN           = 180.0f * (0.5f  + 0.5f * sinf(_demoPhase * 0.1f));
  state.argOfPe       = 180.0f * (0.5f  + 0.5f * sinf(_demoPhase * 0.12f));
  state.trueAnomaly   = 180.0f * (0.5f  + 0.5f * sinf(_demoPhase * 0.08f));
  state.meanAnomaly   = 180.0f * (0.5f  + 0.5f * sinf(_demoPhase * 0.09f));

  // Apoapsis and periapsis derived from sma + ecc for orbital consistency
  state.apoapsis  = state.semiMajorAxis * (1.0f + state.eccentricity) - currentBody.radius;
  state.periapsis = state.semiMajorAxis * (1.0f - state.eccentricity) - currentBody.radius;

  // When viewing the ORB screen, override altitude with the orbitally-consistent value
  // so the position marker label matches the displayed orbit geometry.
  if (activeScreen == screen_ORB) {
    float ta_rad = state.trueAnomaly * DEG_TO_RAD;
    float e = state.eccentricity, a = state.semiMajorAxis;
    float r = a * (1.0f - e*e) / (1.0f + e * cosf(ta_rad));
    state.altitude = fmaxf(0.0f, r - currentBody.radius);
  }


  // Attitude — heading sweeps 0-360, pitch -30..+30, roll -45..+45
  state.heading       = 180.0f + 179.0f * sinf(_demoPhase * 0.3f);

  state.pitch         = 30.0f  * sinf(_demoPhase * 0.5f);
  state.roll          = 45.0f  * sinf(_demoPhase * 0.4f);

  state.orbVelHeading = 180.0f + 170.0f * sinf(_demoPhase * 0.28f);
  state.orbVelPitch   = 10.0f  * sinf(_demoPhase * 0.45f);
  state.srfVelHeading = 180.0f + 175.0f * sinf(_demoPhase * 0.32f);
  state.srfVelPitch   = 8.0f   * sinf(_demoPhase * 0.42f);

  // SAS mode cycles 0-9 then briefly shows 255 (SAS OFF) — one state per 5s, full cycle ~55s
  {
    uint8_t sasTick = (uint8_t)((millis() / 5000) % 11);  // 0-10
    state.sasMode = (sasTick == 10) ? 255 : sasTick;       // 10 → 255 (OFF)
  }
  // Atmosphere toggles every 20s (simulates ascent through atmosphere)
  state.inAtmo  = ((millis() / 20000) % 2 == 0);

  // RCS toggles every 12 seconds
  state.rcs_on = ((millis() / 12000) % 2 == 0);

  // Gear and Brakes — toggle every ~10 seconds
  state.gear_on     = ((millis() / 10000) % 2 == 0);
  state.brakes_on   = ((millis() / 15000) % 2 == 0);
  state.airbrake_on = ((millis() / 12000) % 2 == 0);
  state.trimEnabled = ((millis() / 8000)  % 2 == 0);

  // (AppState.intercept1/2 Dist/Time are unread future-KSP2 stubs — not driven here.)

  // Parachute demo: walks stowed -> deployed -> cut over 30 s. The RE-ENTRY screen's
  // chute states latch the way KSP's do (a cut chute stays cut until repacked, which
  // only a vessel switch resets), so the demo shows the sequence once, not on a loop.
  uint32_t chutePhase = (millis() / 10000) % 3;
  state.drogueDeploy = (chutePhase >= 1);
  state.drogueCut    = (chutePhase >= 2);
  state.mainDeploy   = (chutePhase >= 1) && ((millis() / 5000) % 2 == 0);
  state.mainCut      = false;  // main rarely cut in demo

  // -----------------------------------------------------------------------
  // LNCH — stage burn time: sweeps 0..150s through red(<60), yellow(<120), green
  // -----------------------------------------------------------------------
  state.stageBurnTime = 75.0f + 75.0f * sinf(_demoPhase * 0.3f);  // 0..150s

  // -----------------------------------------------------------------------
  // LNCH — stage ΔV: sweeps 0..450 through red(<150), yellow(<300), green
  // -----------------------------------------------------------------------
  state.stageDeltaV = 225.0f + 225.0f * sinf(_demoPhase * 0.25f);  // 0..450 m/s

  // MNVR — mnvrTime goes negative (past node), totalDeltaV crosses below mnvrDeltaV
  state.mnvrTime     = 400.0f  * sinf(_demoPhase * 0.7f);           // -400..+400s
  state.mnvrDeltaV   = 300.0f  + 250.0f * sinf(_demoPhase * 0.5f);  // 50..550 m/s
  state.mnvrTotalDeltaV = state.mnvrDeltaV + 200.0f + 150.0f * sinf(_demoPhase * 0.3f);  // plan total >= next node
  state.mnvrDuration = 45.0f   + 40.0f  * sinf(_demoPhase * 0.6f);
  state.totalDeltaV  = 300.0f  + 250.0f * sinf(_demoPhase * 0.4f);  // different phase crosses mnvrDeltaV
  state.mnvrHeading  = 180.0f  + 175.0f * sinf(_demoPhase * 0.22f); // 0-360 burn heading
  state.mnvrPitch    = 20.0f   * sinf(_demoPhase * 0.38f);           // -20..+20 burn pitch

  // LNDG — radarAlt sweeps low, verticalVel goes negative to exercise T_GRND thresholds
  // T_GRND = radarAlt / |verticalVel|
  //   radarAlt ~10m,  vel -20 m/s → ~0.5s  (white-on-red,  < 10s)
  //   radarAlt ~100m, vel -5 m/s  → ~20s   (yellow,        < 30s)
  //   radarAlt ~490m, vel -5 m/s  → ~98s   (green)
  state.radarAlt   = 250.0f + 240.0f * sinf(_demoPhase * 0.4f);  // 10..490m

  // -----------------------------------------------------------------------
  // ACFT
  // -----------------------------------------------------------------------
  state.throttle      = 0.5f + 0.5f * sinf(_demoPhase * 0.5f);  // 0..1 (0-100%)
  state.machNumber = 1.5f + 1.2f * sinf(_demoPhase * 0.5f);
  state.IAS        = 180.0f + 150.0f * sinf(_demoPhase * 0.45f);
  state.gForce     = 7.0f   * sinf(_demoPhase * 0.6f);
  // Air density sweeps 0..1.2 kg/m3 in atmosphere (0 outside) to exercise the
  // parachute safety thresholds: at v=100 m/s the peak is q = 0.5 * 1.2 * 10000 =
  // 6000 Pa, above the main-chute limit.
  state.airDensity = (state.inAtmo) ? (0.6f + 0.6f * sinf(_demoPhase * 0.25f)) : 0.0f;

  // -----------------------------------------------------------------------
  // ASCENT AUTOPILOT — cycles the phase through a launch so the panel animates
  // -----------------------------------------------------------------------
  {
    // The ascent runs only while armed; DISARM parks it in IDLE and holds the timer, so
    // ARM resumes where it left off. Phase never returns to IDLE while armed — IDLE is
    // what disarmed looks like — so the bands below start at VERTICAL.
    if (_demoApArmed) _demoApT = fmodf(_demoApT + 0.015f, 8.0f);
    float t = _demoApT;
    uint8_t ph = !_demoApArmed ? 0
               : (t < 0.8f) ? 1 : (t < 3.4f) ? 2 : (t < 4.9f) ? 3 : (t < 6.4f) ? 4 : 5;
    state.apPhase       = ph;
    state.apArmed       = _demoApArmed;
    state.apTargetAlt   = _demoApTgtAlt;
    state.apInclination = _demoApIncl;
    state.apSoutherly   = _demoApSouth;
    state.apLoft        = _demoApLoft;
    state.apRollEnable  = _demoApRollEn;
    state.apRollDeg     = _demoApRollDeg;
    state.apMaxG        = _demoApMaxG;
    float prog = (t - 1.0f) / 3.0f;                 // 0..1 across the gravity turn
    if (prog < 0.0f) prog = 0.0f;
    if (prog > 1.0f) prog = 1.0f;
    state.apCmdPitch    = 90.0f - 65.0f * prog;
    state.apCmdHeading  = 90.0f;
    state.apCmdThrottle = (ph == 3) ? 0.0f : (ph == 4) ? 0.6f : 1.0f;
    state.apDynPressure = 18000.0f * sinf(t * 0.5f);
    if (state.apDynPressure < 0.0f) state.apDynPressure = 0.0f;
  }

  // -----------------------------------------------------------------------
  // HOLD-MODE AUTOPILOT — publishes the demo's aircraft / rover models
  // -----------------------------------------------------------------------
  {
    bool any = _demoHpPitch || _demoHpLat || _demoHpThr;
    bool leverDriven = ((millis() / 30000) % 2 == 0);     // exercises the LEVER OFF note
    state.hpPitchMode = _demoHpPitch; state.hpLatMode = _demoHpLat; state.hpThrMode = _demoHpThr;
    state.hpFlags = (any ? 0x01 : 0) | (_demoHpThr ? 0x02 : 0) | (leverDriven ? 0x08 : 0) | (_demoApArmed ? 0x10 : 0);
    state.hpReason = _demoHpReason;
    state.hpReasonAge = _demoHpReason ? (uint8_t)min((millis() - _demoHpReasonMs) / 1000UL, 255UL) : 255;
    state.hpAtt = _demoHpAtt; state.hpAoa = _demoHpAoa; state.hpVs = _demoHpVs; state.hpAlt = _demoHpAlt;
    state.hpRoll = _demoHpRoll; state.hpHdg = _demoHpHdg; state.hpIas = _demoHpIas; state.hpMach = _demoHpMach;
    state.hpGs = _demoHpGs;
    state.hpCmdThrottle = state.throttle;

    bool slopeGuard = _demoRvCruise && fabsf(state.pitch) > _demoRvMaxSlope * 0.5f;
    state.rvFlags = (_demoRvCruise ? 0x01 : 0) | (_demoRvHdg ? 0x02 : 0) | (_demoRvTgt ? 0x04 : 0) |
                    (state.brakes_on ? 0x08 : 0) | (slopeGuard ? 0x10 : 0) | (state.targetAvailable ? 0x20 : 0) |
                    (_demoRvFollowOn ? 0x40 : 0);
    state.rvFollowRange = _demoRvFollow; state.rvStopDist = _demoRvStop;
    state.rvReason = _demoRvReason;
    state.rvReasonAge = _demoRvReason ? (uint8_t)min((millis() - _demoRvReasonMs) / 1000UL, 255UL) : 255;
    state.rvCruise = _demoRvCruiseSp; state.rvHdg = _demoRvHdgSp;
    state.rvMaxSpeed = _demoRvMaxSpd; state.rvMaxSlope = _demoRvMaxSlope; state.rvMaxRoll = _demoRvMaxRoll;
    state.rvCmdWheel = (_demoRvCruise || _demoRvFollowOn) ? 0.4f * sinf(_demoPhase * 0.3f) : 0.0f;
  }

  // -----------------------------------------------------------------------
  // ORBITAL / LANDING AUTOPILOT — walk a burn through its phases; publish both models
  // -----------------------------------------------------------------------
  {
    uint32_t now = millis();
    // Burn phases advance on a timer: ALIGN 4 s -> WARP READY (waits for EXEC if WARP on,
    // else 4 s) -> WARP 4 s -> BURN 8 s -> DONE 5 s -> IDLE.
    switch (_demoObPhase) {
      case 2: if (now - _demoObPhaseMs > 4000) { _demoObPhase = 3; _demoObPhaseMs = now; } break;
      case 3: if (!_demoObWarp && now - _demoObPhaseMs > 4000) { _demoObPhase = 5; _demoObPhaseMs = now; } break;
      case 4: if (now - _demoObPhaseMs > 4000) { _demoObPhase = 5; _demoObPhaseMs = now; } break;
      case 5: if (now - _demoObPhaseMs > 8000) { _demoObPhase = 6; _demoObPhaseMs = now; } break;
      case 6: if (now - _demoObPhaseMs > 5000) { _demoObPhase = 0; _demoObMode = 0; } break;
      default: break;
    }
    bool armed = _demoObMode != 0 && _demoObPhase >= 1 && _demoObPhase <= 5;
    bool exec  = _demoObPhase >= 2 && _demoObPhase <= 5;
    state.obFlags = (armed ? 0x01 : 0) | (exec ? 0x02 : 0) | (_demoObWarp ? 0x04 : 0) | (_demoObStage ? 0x08 : 0) |
                    (state.targetAvailable ? 0x10 : 0) | (state.mnvrDeltaV > 0.01f ? 0x20 : 0) | (_demoObAppr ? 0x40 : 0);
    state.obMode = _demoObMode; state.obPhase = _demoObPhase;
    state.obReason = _demoObReason;
    state.obReasonAge = _demoObReason ? (uint8_t)min((now - _demoObReasonMs) / 1000UL, 255UL) : 255;
    state.obTargetAp = _demoObAp; state.obTargetPe = _demoObPe; state.obTargetInc = _demoObInc;
    state.obApprRate = _demoObRate; state.obApprDist = _demoObDist;
    float dv = (_demoObMode == 1) ? state.mnvrDeltaV : 842.0f;
    state.obDvTotal = armed ? dv : 0.0f;
    float burnFrac = (_demoObPhase == 5) ? (now - _demoObPhaseMs) / 8000.0f : 0.0f;
    state.obDvRemaining = armed ? dv * (1.0f - burnFrac) : 0.0f;
    state.obTIgnition = armed ? ((_demoObPhase >= 5) ? 0.0f : 252.0f - (now - _demoObPhaseMs) * 0.001f) : 0.0f;
    state.obBurnDuration = armed ? 98.0f : 0.0f;
    state.obAccelEst = 8.6f;
    state.obCmdThrottle = (_demoObPhase == 5) ? 1.0f : 0.0f;

    bool ldEngaged = _demoLdMode != 0 || _demoLdEntry;
    float ignAlt = 2140.0f + 800.0f * sinf(_demoPhase * 0.2f);
    bool brakeFiring = (_demoLdMode == 3) && state.radarAlt < ignAlt;
    state.ldFlags = (ldEngaged ? 0x01 : 0) | ((_demoLdMode == 3 && !brakeFiring) ? 0x02 : 0) | (brakeFiring ? 0x04 : 0) |
                    (_demoLdRadial ? 0x08 : 0) | (_demoObStage ? 0x10 : 0) | ((millis() / 40000) % 2 ? 0x40 : 0);
    state.ldMode = _demoLdMode; state.ldEntry = _demoLdEntry ? 1 : 0;
    state.ldReason = _demoLdReason;
    state.ldReasonAge = _demoLdReason ? (uint8_t)min((now - _demoLdReasonMs) / 1000UL, 255UL) : 255;
    state.ldAccelSource = (_demoLdTwr > 0.0f) ? 2 : ((millis() / 20000) % 2);
    state.ldDescRate = _demoLdRate; state.ldHovrAlt = _demoLdAlt; state.ldTwr = _demoLdTwr; state.ldMargin = _demoLdMargin;
    state.ldEntryAoa = _demoLdAoa; state.ldEntryRoll = _demoLdRoll;
    state.ldIgnAlt = ignAlt; state.ldAccelEst = 14.2f;
    state.ldCmdThrottle = brakeFiring ? 1.0f : (_demoLdMode ? 0.5f + 0.3f * sinf(_demoPhase) : 0.0f);
  }

  // -----------------------------------------------------------------------
  // TGT — toggles targetAvailable periodically
  // -----------------------------------------------------------------------
  state.tgtDistance   = 5000.0f + 4000.0f * sinf(_demoPhase * 0.3f);
  state.tgtVelocity   = 25.0f   * sinf(_demoPhase * 0.35f);   // -25..+25 m/s (neg=closing)
  state.tgtHeading    = 90.0f   + 85.0f   * sinf(_demoPhase * 0.25f);
  state.tgtPitch      = 5.0f    * sinf(_demoPhase * 0.4f);
  state.tgtVelHeading = 180.0f  + 170.0f  * sinf(_demoPhase * 0.27f);
  state.tgtVelPitch   = 8.0f    * sinf(_demoPhase * 0.38f);

  // -----------------------------------------------------------------------
  // VEH — cycle all vessel types (all 17), ctrl levels (0-3),
  //        situations, and isRecoverable.
  // Use millis() directly for time-based cycling independent of phase speed.
  // -----------------------------------------------------------------------
  uint32_t tick2s = millis() / 2000;   // advances every 2 seconds

  // Ctrl level: 0-3, changes every 2s (~8s full cycle)
  state.ctrlLevel     = tick2s % 4;
  // CommNet signal cycles through strong, weak, and lost
  state.commNetSignal = (uint8_t)constrain((int)(70.0f + 70.0f * sinf(_demoPhase * 0.2f)), 0, 100);
  // Electric charge % — sweeps through the pre-launch board's red/yellow/green bands
  state.electricChargePercent = constrain(70.0f + 45.0f * sinf(_demoPhase * 0.22f), 0.0f, 100.0f);
  state.coreTempPct = (uint8_t)constrain(55.0f + 45.0f * sinf(_demoPhase * 0.18f),        0.0f, 100.0f);
  state.skinTempPct = (uint8_t)constrain(60.0f + 40.0f * sinf(_demoPhase * 0.18f + 0.6f), 0.0f, 100.0f);

  // All 17 vessel types, one per 2s (~34s full cycle)
  static const VesselType typeCycle[] = {
    type_Ship, type_Probe, type_Relay, type_Rover, type_Lander,
    type_Plane, type_Station, type_Base, type_EVA, type_Flag,
    type_Debris, type_Object, type_Unknown, type_SciCtrlr, type_SciPart,
    type_Part, type_GndPart
  };
  state.vesselType = typeCycle[(tick2s / 4) % 17];

  // Situations + isRecoverable, one per 2s (~18s full cycle)
  uint8_t sitTick = (tick2s / 2) % 9;
  state.isRecoverable = (sitTick == 8);
  static const VesselSituation sitCycle[] = {
    sit_PreLaunch, sit_Flying, sit_SubOrb, sit_Orbit,
    sit_Escaping, sit_Landed, sit_Splashed, sit_Docked, sit_Flying
  };
  state.situation = sitCycle[sitTick % 9];

  // targetAvailable: 30s with target, 3s NO TARGET
  // Use modulo 33000ms; NO TARGET only during the last 3000ms of each cycle
  state.targetAvailable = ((millis() % 33000) < 30000);

  // ─────────────────────────────────────────────────────────────────────────
  // LNCH ascent profile override — runs LAST so it supersedes the general
  // sinusoidal sweeps for fields that would otherwise conflict. When viewing
  // the LNCH screen (ascent mode), the altitude ladder, V.Vrt bar, and right-
  // panel numbers all move together in a way that mirrors a real Kerbin launch.
  // 180-second cycle then loops.
  //
  // Profile: pad → gravity turn → main ascent → MECO at ~90 km ApA →
  //          coast to apoapsis → circularization burn.
  // ─────────────────────────────────────────────────────────────────────────
  if (activeScreen == screen_LNCH) {
    float t = (float)(millis() % 180000UL) / 1000.0f;  // 0..180 s cycle

    float alt, vSrf, vVrt, apa, tToAp, thr, stgBrn, stgDV;

    // Altitude — piecewise curve through key waypoints
    if (t < 10.0f) {
      alt = 50.0f * t * t;                           // 0..5 km (rapid initial climb)
    } else if (t < 40.0f) {
      float p = (t - 10.0f) / 30.0f;
      alt = 500.0f + 9500.0f * powf(p, 1.3f);        // 500 m..10 km
    } else if (t < 100.0f) {
      alt = 10000.0f + 40000.0f * (t - 40.0f) / 60.0f;   // 10..50 km
    } else if (t < 130.0f) {
      alt = 50000.0f + 35000.0f * (t - 100.0f) / 30.0f;  // 50..85 km
    } else if (t < 160.0f) {
      alt = 85000.0f + 5000.0f * (t - 130.0f) / 30.0f;   // 85..90 km (coasting)
    } else {
      alt = 90000.0f + 1000.0f * sinf((t - 160.0f) / 20.0f * PI);  // near apoapsis
    }

    // V.Vrt — rises fast, peaks ~30 s, decays through coast, small again during circ
    if (t < 5.0f) {
      vVrt = 20.0f * t;                              // 0..100
    } else if (t < 40.0f) {
      vVrt = 100.0f + 250.0f * sinf((t - 5.0f) / 35.0f * (PI / 2.0f));
    } else if (t < 120.0f) {
      vVrt = 350.0f * cosf((t - 40.0f) / 80.0f * (PI / 2.0f));   // 350..0 decay
    } else if (t < 160.0f) {
      vVrt = 50.0f - 50.0f * (t - 120.0f) / 40.0f;   // 50..0
    } else {
      vVrt = 5.0f * sinf((t - 160.0f) / 10.0f * PI); // small oscillation at Ap
    }

    // V.Srf — total surface speed, builds throughout ascent.
    // Note: V.Srf includes horizontal + vertical components, so initially
    // (vertical phase) V.Srf ≈ V.Vrt. As the vessel pitches over for the
    // gravity turn, horizontal component grows and V.Srf grows faster.
    if (t < 0.5f) {
      // Truly stationary for first half second — FPA dial shows default "up"
      vSrf = 0.0f;
    } else if (t < 5.0f) {
      // Pure vertical phase: V.Srf ≈ V.Vrt
      vSrf = fmaxf(vVrt, 5.0f);
    } else if (t < 40.0f) {
      // Pitch-over phase: V.Srf grows faster than V.Vrt (horizontal builds)
      float p = (t - 5.0f) / 35.0f;
      vSrf = fmaxf(vVrt, 100.0f + 827.0f * powf(p, 1.2f));   // reaches ~927 at t=40
    } else if (t < 100.0f) {
      vSrf = 927.0f + 1123.0f * (t - 40.0f) / 60.0f;     // 927..2050
    } else if (t < 160.0f) {
      vSrf = 2050.0f + 200.0f * (t - 100.0f) / 60.0f;    // 2050..2250
    } else {
      vSrf = 2250.0f + 150.0f * (t - 160.0f) / 20.0f;    // circ adds ~150
    }

    // Apoapsis — rises to 90 km target by t=120, then small adjustments
    if (t < 5.0f) {
      apa = 100.0f * t;
    } else if (t < 120.0f) {
      apa = 500.0f + 89500.0f * (t - 5.0f) / 115.0f;
    } else if (t < 160.0f) {
      apa = 90000.0f;
    } else {
      apa = 90000.0f + 5000.0f * (t - 160.0f) / 20.0f;
    }

    // Throttle — burning during ascent, MECO 115-160s, circ burn after
    if (t < 115.0f)      thr = 1.0f;
    else if (t < 160.0f) thr = 0.0f;
    else                 thr = 1.0f;

    // Time to apoapsis — decreases as we approach Ap during coast
    if (t < 115.0f)      tToAp = 180.0f - 50.0f * (t / 115.0f);
    else if (t < 160.0f) tToAp = 130.0f * (1.0f - (t - 115.0f) / 45.0f);
    else                 tToAp = 1800.0f;   // post-circ orbital period is long

    // Stage burn time & ΔV — deplete during burns, reset on staging
    if (t < 115.0f) {
      stgBrn = 180.0f - 1.5f * t;
      stgDV  = 3500.0f - 30.0f * t;
    } else if (t < 160.0f) {
      stgBrn = 200.0f;                     // staged, engine off
      stgDV  = 1500.0f;
    } else {
      stgBrn = 200.0f - 3.0f * (t - 160.0f);
      stgDV  = 1500.0f - 7.0f * (t - 160.0f);
    }

    state.altitude      = alt;
    state.verticalVel   = vVrt;
    state.surfaceVel    = vSrf;
    state.apoapsis      = apa;
    state.timeToAp      = tToAp;
    state.throttle      = thr;
    state.stageBurnTime = stgBrn;
    state.stageDeltaV   = stgDV;

    // Orbital velocity for the V.Orb bar. On a surface-locked vessel on Kerbin's
    // equator, orbital velocity starts at ~175 m/s (rotation contribution) and
    // grows with V.Srf as the vessel accelerates east. Circular-orbit velocity
    // at 90 km on Kerbin is ~2270 m/s, so we target ~2270 by t~170.
    float vOrb;
    if (t < 1.0f) {
      vOrb = 175.0f;                                    // pad rotation
    } else if (t < 115.0f) {
      // Grows from ~175 toward ~2170 during ascent burn, tracking V.Srf
      vOrb = 175.0f + vSrf * 0.95f; // ≈ vSrf + small offset
      // Clamp to realistic progression
      if (vOrb < 175.0f) vOrb = 175.0f;
    } else if (t < 160.0f) {
      // Coast — orbital velocity decays slightly as altitude rises (energy traded)
      vOrb = 2170.0f - 50.0f * (t - 115.0f) / 45.0f;    // ~2170 → 2120
    } else {
      // Circ burn — push to ~2270 (target)
      vOrb = 2120.0f + 150.0f * (t - 160.0f) / 20.0f;   // 2120 → 2270
    }
    state.orbitalVel = vOrb;

    // Air density for the atmosphere gauge. Kerbin atmosphere follows a rough
    // exponential decay with altitude, sea-level density = 1.225 kg/m³, scale
    // height ≈ 5.6 km, atmosphere top = 70 km. Simple approximation:
    //   ρ(h) = ρ₀ × exp(-h / H_scale)   for h < atmosphere_top
    //   ρ = 0                           for h >= atmosphere_top
    {
      const float rho0 = 1.225f;           // Kerbin sea-level density
      const float scaleH = 5600.0f;        // Kerbin scale height (approximate)
      const float atmTop = 70000.0f;       // Kerbin atmosphere top
      if (alt >= atmTop) {
        state.airDensity = 0.0f;
        state.inAtmo = false;
      } else {
        state.airDensity = rho0 * expf(-alt / scaleH);
        state.inAtmo = true;
      }
    }

    // Orbital elements for the orbital-phase left-panel graphic. These only
    // matter once we cross into orbital mode (alt > ~36 km on Kerbin with the
    // auto-switch hysteresis), but we set them continuously for simplicity.
    // Pe stays just below the atmosphere (~65 km) so the orbit visibly needs
    // circularization — Ap growing during burn, Pe rising toward Ap.
    {
      // Pe: starts at 0 (pad) and rises as we ascend. Clamped at 65 km.
      float peaDemo = (alt < 10000.0f) ? 0.0f : fminf(65000.0f, alt - 10000.0f);
      state.periapsis = peaDemo;

      // argOfPe and trueAnomaly: slowly rotate for visual interest in the demo.
      state.argOfPe    = fmodf(t * 2.0f, 360.0f);        // 1 full rotation per 180s
      state.trueAnomaly = fmodf(t * 4.5f, 360.0f);       // vessel orbits faster

      // Eccentricity + sma for completeness. Derived from apa/pea.
      float rAp = apa + currentBody.radius;
      float rPe = peaDemo + currentBody.radius;
      float sma = (rAp + rPe) * 0.5f;
      float ecc = (rAp > rPe + 1.0f) ? ((rAp - rPe) / (rAp + rPe)) : 0.0f;
      state.semiMajorAxis = sma;
      state.eccentricity  = ecc;
    }

    // Ensure situation isn't PreLaunch/Landed during ascent so V.Vrt isn't
    // suppressed by the "dead-band" logic in the draw functions.
    if (t > 1.0f) {
      state.situation = sit_Flying;
    } else {
      state.situation = sit_PreLaunch;
    }
  }
}

/***************************************************************************************
   EADIBall.ino -- Shared EADI attitude-ball renderer for the SPACECRAFT (SCFT) and
   AIRCRAFT (ACFT) screens.

   SCFT and ACFT draw a pixel-identical attitude ball (same centre, radius, colours);
   historically each carried its own private copy of the whole renderer (~1000 duplicate
   lines). These functions are the shared implementation. Because every .ino compiles into
   one translation unit, non-static functions here are callable from both screens, and the
   EADI_* constants below are visible throughout the sketch.

   Geometry MUST stay identical to the per-screen SCFT_ / ACFT_ constants (all == the
   values below). The screens keep their own SCFT_ / ACFT_ copies for their tapes/panels;
   these EADI_ values are the single source of truth for the shared ball code.

   This file now holds the complete shared ball renderer: the stateless leaf primitives
   (scanline fill, disc clip, fixed aircraft symbol), the pitch ladder (eadiDrawLadder),
   the ADI markers (eadiDrawAdiMarker), and the full/delta horizon fill (eadiFullDraw /
   eadiDeltaDraw).
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// ── Shared ball geometry / colours (mirror SCFT_*/ACFT_*) ────────────────────────────
static const int16_t  EADI_CX        = 345;
static const int16_t  EADI_CY        = 300;
static const int16_t  EADI_R         = 206;
static const uint16_t EADI_SKY       = TFT_ROYAL;
static const uint16_t EADI_GND       = TFT_UPS_BROWN;
static const uint16_t EADI_HORIZON   = TFT_WHITE;
static const uint16_t EADI_LADDER    = TFT_WHITE;
static const int16_t  EADI_BX_ALLSKY = INT16_MIN;   // scanline is entirely sky
static const int16_t  EADI_BX_ALLGND = INT16_MAX;   // scanline is entirely ground

// ── Shared attitude-ball geometry + delta-fill state ─────────────────────────────────
// SCFT and ACFT never run simultaneously (mutually-exclusive screens) and share identical
// geometry, so one set of buffers serves both; each screen resets them in its chrome via
// eadiBallResetState(). ~1.8 KB total.
static const int16_t  EADI_BALL_Y0     = EADI_CY - EADI_R;            // 94 (top scanline of ball)
static const uint16_t EADI_SCANLINES   = (uint16_t)(EADI_R * 2 + 1);  // 413
static const float    EADI_SCALE       = (float)EADI_R / 30.0f;       // px per degree
static const uint16_t EADI_DIRTY_WORDS = (EADI_SCANLINES + 15) / 16;  // 26

static int16_t  _eadiChordTable[EADI_SCANLINES];   // chord half-widths (built once)
static bool     _eadiChordTableReady = false;
static int16_t  _eadiPrevBx[EADI_SCANLINES];       // prev-frame per-scanline sky/gnd split
static bool     _eadiPrevGroundLeft  = false;
static uint16_t _eadiLadderDirty[EADI_DIRTY_WORDS];      // current-frame occupied scanlines
static uint16_t _eadiLadderDirtyPrev[EADI_DIRTY_WORDS];  // previous frame (delta erase mask)
static int16_t  _eadiPrevHorizLo = INT16_MAX;      // prev horizon-line dirty band
static int16_t  _eadiPrevHorizHi = INT16_MIN;

// Mark scanline y occupied in the current-frame dirty bitmap (ladder/markers call this).
void eadiLadderDirtySet(int16_t y) {
    int16_t i = y - EADI_BALL_Y0;
    if (i < 0 || i >= (int16_t)EADI_SCANLINES) return;
    _eadiLadderDirty[i >> 4] |= (uint16_t)(1u << (i & 15));
}
// Was scanline index i occupied last frame? (delta fill uses this to erase old pixels.)
static inline bool eadiLadderDirtyTest(uint16_t i) {
    return (_eadiLadderDirtyPrev[i >> 4] >> (i & 15)) & 1u;
}

// ── Draw one horizon scanline ────────────────────────────────────────────────────────
// bx is the sky/ground split x for row y (or the ALLSKY/ALLGND sentinel). groundLeft
// selects which side of bx is ground.
void eadiDrawScanline(KCM_TFT &tft, int16_t y, int16_t x0, int16_t x1,
                      int16_t bx, bool groundLeft) {
    if (bx == EADI_BX_ALLSKY) {
        tft.drawLine(x0, y, x1, y, EADI_SKY);
    } else if (bx == EADI_BX_ALLGND) {
        tft.drawLine(x0, y, x1, y, EADI_GND);
    } else if (groundLeft) {
        tft.drawLine(x0,   y, bx,   y, EADI_GND);
        tft.drawLine(bx+1, y, x1,   y, EADI_SKY);
    } else {
        tft.drawLine(x0,   y, bx-1, y, EADI_SKY);
        tft.drawLine(bx,   y, x1,   y, EADI_GND);
    }
}

// ── Aircraft symbol (fixed, horizontal) ──────────────────────────────────────────────
// The KSP "level indicator": gold wings with a centre dip and a nose dot at the ball
// centre. Drawn last so it sits above fill/horizon/ladder.
void eadiDrawAircraftSymbol(KCM_TFT &tft) {
    drawLevelIndicator(tft, EADI_CX, EADI_CY, 48, TFT_GOLD);
}

// ── Clip endpoint to disc ─────────────────────────────────────────────────────────────
// Given a segment p->q, return in (ox,oy) the point q clipped to the ball disc boundary.
void eadiClipToDisk(float px, float py, float qx, float qy,
                    float &ox, float &oy) {
    float cx = qx - EADI_CX, cy = qy - EADI_CY;
    if (cx*cx + cy*cy <= (float)EADI_R * EADI_R) { ox = qx; oy = qy; return; }
    float dx = qx-px, dy = qy-py;
    float ax = px-EADI_CX, ay = py-EADI_CY;
    float a = dx*dx + dy*dy;
    float b = 2.0f*(ax*dx + ay*dy);
    float c = ax*ax + ay*ay - (float)EADI_R*(float)EADI_R;
    float disc = b*b - 4.0f*a*c;
    if (disc < 0.0f || a < 0.001f) { ox = qx; oy = qy; return; }
    float sq = sqrtf(disc);
    float t  = (-b - sq) / (2.0f*a);
    if (t < 0.0f || t > 1.0f) t = (-b + sq) / (2.0f*a);
    t = max(0.0f, min(1.0f, t));
    ox = px + t*dx; oy = py + t*dy;
}


// ═══ Bank / roll arc ═════════════════════════════════════════════════════════════════
// The bank pointer + scale ticks/labels sit just outside the bezel. Shared by SCFT/ACFT.
static const int16_t EADI_PTR_TIP_R  = EADI_R + 3;    // tip clear of bezel (bezel outer = R+2)
static const int16_t EADI_PTR_BASE_R = EADI_R + 22;   // base beyond tick outer (R+16), below labels
static const int16_t EADI_PTR_W      = 12;            // half-width of pointer base

static float _eadiPrevRollIndicator = -9999.0f;       // last drawn pointer angle
void eadiResetRollIndicator() { _eadiPrevRollIndicator = -9999.0f; }

// Draw the roll pointer triangle for a given roll angle.
void eadiDrawRollPointer(KCM_TFT &tft, float roll, uint16_t colour) {
    float a    = (roll - 90.0f) * (float)DEG_TO_RAD;
    float cosA = cosf(a), sinA = sinf(a);
    int16_t tx  = (int16_t)(EADI_CX + EADI_PTR_TIP_R  * cosA);
    int16_t ty  = (int16_t)(EADI_CY + EADI_PTR_TIP_R  * sinA);
    int16_t bcx = (int16_t)(EADI_CX + EADI_PTR_BASE_R * cosA);
    int16_t bcy = (int16_t)(EADI_CY + EADI_PTR_BASE_R * sinA);
    int16_t b1x = bcx + (int16_t)(-sinA * EADI_PTR_W);
    int16_t b1y = bcy + (int16_t)( cosA * EADI_PTR_W);
    int16_t b2x = bcx - (int16_t)(-sinA * EADI_PTR_W);
    int16_t b2y = bcy - (int16_t)( cosA * EADI_PTR_W);
    tft.fillTriangle(tx, ty, b1x, b1y, b2x, b2y, colour);
}

// Erase the roll pointer — a generously expanded triangle to catch stray rotated-edge
// pixels. The wider erase reaches the R+28 bank labels, so the caller redraws any within.
void eadiEraseRollPointer(KCM_TFT &tft, float roll) {
    float a    = (roll - 90.0f) * (float)DEG_TO_RAD;
    float cosA = cosf(a), sinA = sinf(a);
    int16_t tx  = (int16_t)(EADI_CX + (EADI_PTR_TIP_R  - 1) * cosA);
    int16_t ty  = (int16_t)(EADI_CY + (EADI_PTR_TIP_R  - 1) * sinA);
    int16_t bcx = (int16_t)(EADI_CX + (EADI_PTR_BASE_R + 3) * cosA);
    int16_t bcy = (int16_t)(EADI_CY + (EADI_PTR_BASE_R + 3) * sinA);
    int16_t b1x = bcx + (int16_t)(-sinA * (EADI_PTR_W + 9));
    int16_t b1y = bcy + (int16_t)( cosA * (EADI_PTR_W + 9));
    int16_t b2x = bcx - (int16_t)(-sinA * (EADI_PTR_W + 9));
    int16_t b2y = bcy - (int16_t)( cosA * (EADI_PTR_W + 9));
    tft.fillTriangle(tx, ty, b1x, b1y, b2x, b2y, TFT_BLACK);
}

// Draw a single bank-scale angle label ("30" / "60") at R+28 along the bank radial.
void eadiDrawBankLabel(KCM_TFT &tft, int16_t bankDeg) {
    const char *txt = (bankDeg == 60 || bankDeg == -60) ? "60" : "30";
    float   a    = (bankDeg - 90.0f) * (float)DEG_TO_RAD;
    int16_t lc_x = (int16_t)(EADI_CX + (EADI_R + 28) * cosf(a));
    int16_t lc_y = (int16_t)(EADI_CY + (EADI_R + 28) * sinf(a));
    int16_t lw   = getFontStringWidth(&Roboto_Black_16, txt);
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(lc_x - lw / 2, lc_y - 9);   // 9 ~ cap-height/2 for Roboto_Black_16
    tft.print(txt);
}

// Draw a single bank scale tick at the given bank angle.
void eadiDrawBankTick(KCM_TFT &tft, int16_t bankDeg) {
    bool isMajor = (bankDeg == 0 || bankDeg == 30 || bankDeg == -30 ||
                                     bankDeg == 60 || bankDeg == -60);
    int16_t tOuter = EADI_R + 16;
    int16_t tInner = EADI_R + (isMajor ? 2 : 6);
    uint16_t col = (bankDeg == 0 || bankDeg == 60 || bankDeg == -60)
                   ? TFT_WHITE : TFT_LIGHT_GREY;   // 0 and +/-60 white, rest light grey
    float a    = (bankDeg - 90.0f) * (float)DEG_TO_RAD;
    float cosA = cosf(a), sinA = sinf(a);
    int16_t ox = (int16_t)(EADI_CX + tOuter * cosA);
    int16_t oy = (int16_t)(EADI_CY + tOuter * sinA);
    int16_t ix = (int16_t)(EADI_CX + tInner * cosA);
    int16_t iy = (int16_t)(EADI_CY + tInner * sinA);
    tft.drawLine(ox, oy, ix, iy, col);
}

// Update the roll pointer: erase old, redraw any tick/label it covered, draw new.
void eadiUpdateRollIndicator(KCM_TFT &tft, float roll) {
    if (fabsf(roll - _eadiPrevRollIndicator) < 0.2f) return;

    static const int16_t ticks[] = {-60,-45,-30,-20,-10,0,10,20,30,45,60};

    // Erase old pointer with expanded triangle to catch stray pixels
    if (_eadiPrevRollIndicator > -9000.0f) {
        float prevClamped = _eadiPrevRollIndicator;
        if      (prevClamped >  60.0f) prevClamped =  60.0f;
        else if (prevClamped < -60.0f) prevClamped = -60.0f;
        eadiEraseRollPointer(tft, prevClamped);
        // Redraw any bank label the (wider) erase reached into (+/-30/+/-60, within a
        // 12deg window) BEFORE the ticks, so a label's opaque box can't clip a tick.
        static const int16_t labelBanks[] = {-60, -30, 30, 60};
        for (uint8_t i = 0; i < 4; i++) {
            if (fabsf(_eadiPrevRollIndicator - labelBanks[i]) < 12.0f) {
                eadiDrawBankLabel(tft, labelBanks[i]);
            }
        }
        // Redraw every tick the (wider) erase region may have covered (within 7deg —
        // do NOT break, the enlarged erase can span two adjacent ticks).
        for (uint8_t i = 0; i < 11; i++) {
            if (fabsf(_eadiPrevRollIndicator - ticks[i]) < 7.0f) {
                eadiDrawBankTick(tft, ticks[i]);
            }
        }
    }

    // Draw new pointer — clamped to +/-60deg so it stays within the scale marks
    float clampedRoll = roll;
    if      (clampedRoll >  60.0f) clampedRoll =  60.0f;
    else if (clampedRoll < -60.0f) clampedRoll = -60.0f;
    eadiDrawRollPointer(tft, clampedRoll, TFT_YELLOW);
    _eadiPrevRollIndicator = roll;
}


// ═══ Pitch ladder ════════════════════════════════════════════════════════════════════
// ═══ Extreme-attitude chevrons ═══════════════════════════════════════════════════════
// Red chevrons pointing at the horizon once it has left the disc, on both attitude
// screens -- every modern PFD draws them (50 deg up / 30 deg down on the G1000, 60/40 on
// the G5) because at an extreme attitude the ball alone stops telling you which way is
// out.
//
// The onset is OUR geometry, not Garmin's numbers. The ball is scaled R/30, so the
// horizon leaves the disc at exactly +/-30 deg in both directions and the fill goes solid
// sky or solid ground -- the renderer already has EADI_BX_ALLSKY / ALLGND sentinels for
// that state. Symmetric, because our geometry is symmetric. The labelled ladder rungs
// still give the number; what the chevrons add is the direction of recovery at a glance,
// at the moment the pilot has least attention to spare. In KSP, where aeroplanes get
// flipped regularly, that is worth more than it is in a real cockpit.
//
// NOT decluttering past 30/20/65 the way a real PFD does. Our readout panel is a separate
// region rather than an overlay on the ball, so blanking it would remove numbers a KSP
// pilot still wants while inverted and gain nothing in legibility.
//
// Drawn inside eadiDrawLadder so they inherit its dirty-scanline bookkeeping and are
// erased by the same delta pass as the rungs.
static const float   EADI_CHEV_ON_DEG  = 32.0f;   // hysteresis, so the boundary cannot
static const float   EADI_CHEV_OFF_DEG = 28.0f;   //   flicker while levelling out
static const int16_t EADI_CHEV_D1      = 52;      // apex distance from disc centre
static const int16_t EADI_CHEV_D2      = 108;
static const int16_t EADI_CHEV_LEN     = 30;      // arm run-back along the pointing axis
static const int16_t EADI_CHEV_HW      = 30;      // arm half-width across it (45 deg)
static bool _eadiChevronOn = false;

void eadiDrawExtremeChevrons(KCM_TFT &tft, float BCX, float BCY) {
    // Distance from the disc centre to the horizon point IS the pitch, in pixels.
    const float dx = BCX - (float)EADI_CX, dy = BCY - (float)EADI_CY;
    const float distPx = sqrtf(dx*dx + dy*dy);
    const float pitchDeg = distPx / EADI_SCALE;

    if (_eadiChevronOn) { if (pitchDeg < EADI_CHEV_OFF_DEG) _eadiChevronOn = false; }
    else                { if (pitchDeg > EADI_CHEV_ON_DEG)  _eadiChevronOn = true;  }
    if (!_eadiChevronOn || distPx < 1.0f) return;

    // Unit vector from the disc centre toward the horizon: the way out.
    const float hx = dx / distPx, hy = dy / distPx;
    const float px = -hy, py = hx;              // perpendicular, for the arms; roll is
                                                // already carried by (hx,hy)

    const float rr = (float)EADI_R * (float)EADI_R;
    const int16_t dists[2] = { EADI_CHEV_D1, EADI_CHEV_D2 };
    for (uint8_t i = 0; i < 2; i++) {
        const float ax = (float)EADI_CX + hx * (float)dists[i];
        const float ay = (float)EADI_CY + hy * (float)dists[i];
        // Arms run back from the apex, opening away from the horizon.
        const float bx = ax - hx * (float)EADI_CHEV_LEN;
        const float by = ay - hy * (float)EADI_CHEV_LEN;
        const float e1x = bx + px * (float)EADI_CHEV_HW, e1y = by + py * (float)EADI_CHEV_HW;
        const float e2x = bx - px * (float)EADI_CHEV_HW, e2y = by - py * (float)EADI_CHEV_HW;

        // Skip a chevron that would fall outside the disc -- clipping a V leaves a shape
        // that reads as something else.
        const float m1 = (e1x-EADI_CX)*(e1x-EADI_CX) + (e1y-EADI_CY)*(e1y-EADI_CY);
        const float m2 = (e2x-EADI_CX)*(e2x-EADI_CX) + (e2y-EADI_CY)*(e2y-EADI_CY);
        if (m1 >= rr || m2 >= rr) continue;

        int16_t yLo = (int16_t)min(min(ay, e1y), e2y) - 2;
        int16_t yHi = (int16_t)max(max(ay, e1y), e2y) + 2;
        for (int16_t yd = yLo; yd <= yHi; yd++) eadiLadderDirtySet(yd);

        // Two passes one pixel apart, the same way the ladder thickens its rungs.
        for (int8_t o = 0; o <= 1; o++) {
            const int16_t ox = (int16_t)(hx * (float)o), oy = (int16_t)(hy * (float)o);
            tft.drawLine((int16_t)ax + ox, (int16_t)ay + oy,
                         (int16_t)e1x + ox, (int16_t)e1y + oy, TFT_RED);
            tft.drawLine((int16_t)ax + ox, (int16_t)ay + oy,
                         (int16_t)e2x + ox, (int16_t)e2y + oy, TFT_RED);
        }
    }
}


// Draw the pitch ladder. Rungs/labels are marked dirty for next frame's delta erase.
void eadiDrawLadder(KCM_TFT &tft, float BCX, float BCY, float sinR, float cosR) {
    static const int16_t HL_MAJ  = 47;   // major rung half-length
    static const int16_t HL_MIN  = 29;   // minor rung half-length
    static const int16_t LBL_GAP = 8;
    static const uint8_t FONT_W  = 9;    // Roboto_Black_16 digit advance
    static const uint8_t FONT_H  = 19;   // Roboto_Black_16 cap height

    tft.setFont(Roboto_Black_16);
    tft.setTextColor(EADI_LADDER);

    auto rnd = [](float v) -> int16_t {
        return (int16_t)(v + (v > 0.0f ? 0.5f : -0.5f));
    };
    int16_t spx = rnd(sinR), spy = rnd(-cosR);

    auto clampToDisc = [](int16_t &px, int16_t &py) {
        float dx = (float)px - EADI_CX, dy = (float)py - EADI_CY;
        float d2 = dx*dx + dy*dy;
        if (d2 > (float)(EADI_R-1) * (float)(EADI_R-1)) {
            float s = (float)(EADI_R-1) / sqrtf(d2);
            px = EADI_CX + (int16_t)(dx*s);
            py = EADI_CY + (int16_t)(dy*s);
        }
    };

    auto boxInDisc = [](int16_t lx, int16_t ly, uint8_t lw, uint8_t lh) -> bool {
        for (int8_t cx = 0; cx <= 1; cx++)
            for (int8_t cy = 0; cy <= 1; cy++) {
                float dx = (float)(lx + cx*(int16_t)lw) - EADI_CX;
                float dy = (float)(ly + cy*(int16_t)lh) - EADI_CY;
                if (dx*dx + dy*dy >= (float)EADI_R * EADI_R) return false;
            }
        return true;
    };

    float R2 = (float)EADI_R * (float)EADI_R;

    // Pitch clamped +/-90deg in KSP. Step in 5deg increments.
    for (int16_t lad_p_x2 = -180; lad_p_x2 <= 180; lad_p_x2 += 10) {
        if (lad_p_x2 == 0) continue;   // skip horizon (drawn separately)
        float  lad_p = (float)lad_p_x2 * 0.5f;
        float  delta = lad_p * EADI_SCALE;

        // Rung foot = ball centre + lad_p offset along sky-ward (sinR,-cosR)
        float rfx = BCX + delta * sinR;
        float rfy = BCY - delta * cosR;

        float fd2 = (rfx-EADI_CX)*(rfx-EADI_CX) + (rfy-EADI_CY)*(rfy-EADI_CY);
        if (fd2 >= R2) continue;

        bool is_major = (lad_p_x2 % 20 == 0);   // divisible by 10deg
        float hl = is_major ? (float)HL_MAJ : (float)HL_MIN;

        // Rung line along horizon direction (cosR, sinR)
        float rx1 = rfx - hl*cosR, ry1 = rfy - hl*sinR;
        float rx2 = rfx + hl*cosR, ry2 = rfy + hl*sinR;

        float cx1, cy1, cx2, cy2;
        eadiClipToDisk(rfx, rfy, rx1, ry1, cx1, cy1);
        eadiClipToDisk(rfx, rfy, rx2, ry2, cx2, cy2);

        int16_t lx1 = (int16_t)cx1, ly1 = (int16_t)cy1;
        int16_t lx2 = (int16_t)cx2, ly2 = (int16_t)cy2;
        int16_t lx1b = lx1+spx, ly1b = ly1+spy;
        int16_t lx2b = lx2+spx, ly2b = ly2+spy;
        clampToDisc(lx1b, ly1b);
        clampToDisc(lx2b, ly2b);

        // Mark every scanline the rung touches as dirty for next frame's delta erase.
        {
            int16_t y_lo = min(min(ly1, ly2), min(ly1b, ly2b));
            int16_t y_hi = max(max(ly1, ly2), max(ly1b, ly2b));
            for (int16_t yd = y_lo; yd <= y_hi; yd++) eadiLadderDirtySet(yd);
        }

        tft.drawLine(lx1,  ly1,  lx2,  ly2,  EADI_LADDER);
        tft.drawLine(lx1b, ly1b, lx2b, ly2b, EADI_LADDER);

        if (!is_major) continue;   // only label 10deg multiples

        int16_t abs_p   = lad_p_x2 < 0 ? -lad_p_x2 : lad_p_x2;
        abs_p /= 2;   // back to degrees
        char    lbl[4];
        lbl[0] = '0' + (int8_t)(abs_p / 10);
        lbl[1] = '0' + (int8_t)(abs_p % 10);
        lbl[2] = '\0';
        uint8_t lw = (uint8_t)(strlen(lbl) * FONT_W);

        // Push each label away from the rung foot along the rung direction.
        float rung_cx = (cx1 + cx2) * 0.5f;  // rung foot screen x (midpoint of clipped ends)
        auto placeLabel = [&](float ex, float ey) {
            float dx = ex - rung_cx;
            float sign = (dx >= 0.0f) ? 1.0f : -1.0f;
            int16_t lx = (int16_t)(ex + (float)LBL_GAP * sign);
            if (sign > 0.0f && lx < (int16_t)ex)  lx = (int16_t)ex + LBL_GAP;
            if (sign < 0.0f && lx + lw > (int16_t)ex) lx = (int16_t)ex - LBL_GAP - lw;
            int16_t ly = (int16_t)(ey) - FONT_H/2;
            if (boxInDisc(lx, ly, lw, FONT_H)) {
                for (int16_t yd = ly; yd < ly + FONT_H; yd++) eadiLadderDirtySet(yd);
                tft.setCursor(lx, ly); tft.print(lbl);
            }
        };
        placeLabel(cx1, cy1);
        placeLabel(cx2, cy2);
    }

    eadiDrawExtremeChevrons(tft, BCX, BCY);
}


// ═══ ADI ball markers (prograde / target / maneuver) ═════════════════════════════════
static const int16_t EADI_ADI_MRK_HD = 32;   // marker extent (prograde ring 18 + spoke 12)

// eadiHdgDelta (shortest-arc heading delta) now lives in KerbalDisplayCommon.

// Draw one KSP navball marker on the ADI ball at the given world-space heading/pitch
// (relative to the current vessel attitude, read from `state`). Skips the draw if it
// would fall outside the visible cone. Marks the marker's scanlines into the caller's
// `dirty` bitmap so the next delta fill repaints them (prevents trails).
void eadiDrawAdiMarker(KCM_TFT &tft, float markerHdg, float markerPitch,
                       uint16_t fillCol, uint8_t kind) {
    // True boresight projection into the cockpit frame, shared with the reticles and the
    // re-entry retro ball (KerbalDisplayCommon). The ball's own horizon line and pitch
    // ladder are still drawn on the older flat model, so a marker can sit up to ~4 px
    // off the drawn horizon at the widest visible lateral offset — within the ±25° the
    // marker clip allows. Making the ball itself spherical is a separate job.
    const KspBodyAxes ax = kspBodyAxes(state.heading, state.pitch, state.roll);
    float degRight, degUp;
    kspBoresightAngles(ax, markerHdg, markerPitch, degRight, degUp);
    int16_t sx = (int16_t)(EADI_CX + degRight * EADI_SCALE);
    int16_t sy = (int16_t)(EADI_CY - degUp    * EADI_SCALE);

    // Clip: entire marker must fit inside ball. Use (R - HD) so outline doesn't cross rim.
    int16_t dx = sx - EADI_CX, dy = sy - EADI_CY;
    int32_t rInner = (int32_t)EADI_R - EADI_ADI_MRK_HD;
    if ((int32_t)dx*dx + (int32_t)dy*dy > rInner * rInner) return;

    // KSP navball symbol — dispatch to the shared KDC glyph for this kind.
    switch (kind) {
      case KSP_MK_TARGET:      drawTargetMarker(tft, sx, sy, 22, fillCol);     break;
      case KSP_MK_ANTITARGET:  drawAntiTargetMarker(tft, sx, sy, 20, fillCol); break;
      case KSP_MK_MANEUVER:    drawManeuverMarker(tft, sx, sy, 19, fillCol);   break;
      case KSP_MK_RETROGRADE:  drawRetrogradeMarker(tft, sx, sy, 18, fillCol); break;
      case KSP_MK_NORMAL:      drawNormalMarker(tft, sx, sy, 18, fillCol);     break;
      case KSP_MK_ANTINORMAL:  drawAntiNormalMarker(tft, sx, sy, 18, fillCol); break;
      case KSP_MK_RADIAL_IN:   drawRadialInMarker(tft, sx, sy, 20, fillCol);   break;
      case KSP_MK_RADIAL_OUT:  drawRadialOutMarker(tft, sx, sy, 20, fillCol);  break;
      case KSP_MK_LEVEL:       drawLevelIndicator(tft, sx, sy, 18, fillCol);   break;
      default:                 drawProgradeMarker(tft, sx, sy, 18, fillCol);   break;
    }

    // Tell next frame's delta fill to repaint these scanlines.
    for (int16_t y = sy - EADI_ADI_MRK_HD; y <= sy + EADI_ADI_MRK_HD; y++) {
        eadiLadderDirtySet(y);
    }
}


// ═══ Horizon fill: chord table, full draw, per-scanline delta fill ═══════════════════
// Build the chord half-width lookup (integer sqrt, 4 Newton iters). Idempotent.
void eadiBuildChordTable() {
    if (_eadiChordTableReady) return;
    for (uint16_t i = 0; i < EADI_SCANLINES; i++) {
        int16_t dy  = (int16_t)i - EADI_R;
        int32_t rem = (int32_t)EADI_R*EADI_R - (int32_t)dy*dy;
        if (rem <= 0) { _eadiChordTable[i] = 0; continue; }
        int32_t x = EADI_R;
        x = (x + rem/x) >> 1; x = (x + rem/x) >> 1;
        x = (x + rem/x) >> 1; x = (x + rem/x) >> 1;
        _eadiChordTable[i] = (int16_t)x;
    }
    _eadiChordTableReady = true;
}

// Full ball sky/ground fill. Records each row's split into _eadiPrevBx for the delta fill.
void eadiFullDraw(KCM_TFT &tft, float sinR, float cosR, float K) {
    tft.fillCircle(EADI_CX, EADI_CY, EADI_R, EADI_SKY);
    bool near_horiz = (fabsf(sinR) < 0.01f);
    float bx_f    = near_horiz ? 0.0f : (K + cosR * (float)EADI_BALL_Y0) / sinR;
    float bx_step = near_horiz ? 0.0f : cosR / sinR;
    bool  gl0     = (sinR > 0.0f);
    for (uint16_t i = 0; i < EADI_SCANLINES; i++) {
        int16_t chw = _eadiChordTable[i];
        if (chw <= 0) { _eadiPrevBx[i] = EADI_BX_ALLSKY; bx_f += bx_step; continue; }
        int16_t y  = EADI_BALL_Y0 + (int16_t)i;
        int16_t x0 = EADI_CX - chw, x1 = EADI_CX + chw;
        bool    gl;
        int16_t bx;
        if (near_horiz) {
            bool sky = (-cosR * (float)y > K);
            bx = sky ? EADI_BX_ALLSKY : EADI_BX_ALLGND;
            gl = !sky;
        } else {
            bx = (int16_t)bx_f;
            gl = gl0;
            if (sinR > 0.0f) {
                if (bx <= x0) { bx = EADI_BX_ALLSKY;  gl = false; }
                else if (bx >= x1) { bx = EADI_BX_ALLGND; }
            } else {
                if (bx >= x1) { bx = EADI_BX_ALLSKY;  gl = false; }
                else if (bx <= x0) { bx = EADI_BX_ALLGND; }
            }
        }
        _eadiPrevBx[i] = bx;
        eadiDrawScanline(tft, y, x0, x1, bx, gl);
        bx_f += bx_step;
    }
    _eadiPrevGroundLeft = gl0;
}

// Per-scanline delta fill. Repaints only rows whose split changed or that fall in the
// previous horizon-line / ladder dirty bands. Reads/writes _eadiPrevBx/_eadiPrevGroundLeft
// and _eadiPrevHoriz*/dirty-prev.
void eadiDeltaDraw(KCM_TFT &tft, float sinR, float cosR, float K) {
    bool  newGL      = (sinR > 0.0f);
    bool  near_horiz = (fabsf(sinR) < 0.01f);
    float bx_f       = near_horiz ? 0.0f : (K + cosR * (float)EADI_BALL_Y0) / sinR;
    float bx_step    = near_horiz ? 0.0f : cosR / sinR;

    int16_t split_lo = 0, split_hi = (int16_t)(EADI_SCANLINES - 1);
    if (!near_horiz) {
        float pitchPx = -(K - sinR * (float)EADI_CX + cosR * (float)EADI_CY);
        float hc2 = (float)EADI_R * EADI_R - pitchPx * pitchPx;
        if (hc2 >= 0.0f) {
            float BCY = (float)EADI_CY + pitchPx * cosR;
            float hc  = sqrtf(hc2);
            float ly1 = BCY - hc * sinR, ly2 = BCY + hc * sinR;
            float ylo = (ly1 < ly2 ? ly1 : ly2) - 2.0f;
            float yhi = (ly1 > ly2 ? ly1 : ly2) + 1.0f;
            split_lo = (int16_t)(ylo - (float)EADI_BALL_Y0);
            split_hi = (int16_t)(yhi - (float)EADI_BALL_Y0);
            if (split_lo < 0) split_lo = 0;
            if (split_hi >= (int16_t)EADI_SCANLINES) split_hi = (int16_t)(EADI_SCANLINES - 1);
        }
    }

    for (uint16_t i = 0; i < EADI_SCANLINES; i++) {
        bool in_split   = ((int16_t)i >= split_lo && (int16_t)i <= split_hi);
        bool in_prev_horiz  = ((int16_t)(EADI_BALL_Y0 + i) >= _eadiPrevHorizLo &&
                                (int16_t)(EADI_BALL_Y0 + i) <= _eadiPrevHorizHi);
        bool in_prev_ladder = eadiLadderDirtyTest(i);

        int16_t chw = _eadiChordTable[i];

        if (!in_split && !in_prev_horiz && !in_prev_ladder) {
            if (chw <= 0) { bx_f += bx_step; continue; }
            int16_t bx_new_s;
            if (near_horiz) {
                int16_t y = EADI_BALL_Y0 + (int16_t)i;
                bx_new_s = (-cosR * (float)y > K) ? EADI_BX_ALLSKY : EADI_BX_ALLGND;
            } else {
                int16_t x0 = EADI_CX - chw, x1 = EADI_CX + chw;
                int16_t bx = (int16_t)bx_f;
                if (sinR > 0.0f)
                    bx_new_s = (bx <= x0) ? EADI_BX_ALLSKY : (bx >= x1) ? EADI_BX_ALLGND : bx;
                else
                    bx_new_s = (bx >= x1) ? EADI_BX_ALLSKY : (bx <= x0) ? EADI_BX_ALLGND : bx;
            }
            bx_f += bx_step;
            if (bx_new_s == _eadiPrevBx[i] && newGL == _eadiPrevGroundLeft) continue;
            int16_t y  = EADI_BALL_Y0 + (int16_t)i;
            int16_t x0 = EADI_CX - chw, x1 = EADI_CX + chw;
            bool gl = (bx_new_s == EADI_BX_ALLSKY) ? false : newGL;
            eadiDrawScanline(tft, y, x0, x1, bx_new_s, gl);
            _eadiPrevBx[i] = bx_new_s;
            continue;
        }

        if (chw <= 0) { _eadiPrevBx[i] = EADI_BX_ALLSKY; bx_f += bx_step; continue; }

        int16_t y  = EADI_BALL_Y0 + (int16_t)i;
        int16_t x0 = EADI_CX - chw, x1 = EADI_CX + chw;
        bool    gl;
        int16_t bx_new;

        if (near_horiz) {
            bool sky = (-cosR * (float)y > K);
            bx_new = sky ? EADI_BX_ALLSKY : EADI_BX_ALLGND;
            gl = !sky;
        } else {
            bx_new = (int16_t)bx_f;
            gl = newGL;
            if (sinR > 0.0f) {
                if (bx_new <= x0) { bx_new = EADI_BX_ALLSKY;  gl = false; }
                else if (bx_new >= x1) { bx_new = EADI_BX_ALLGND; }
            } else {
                if (bx_new >= x1) { bx_new = EADI_BX_ALLSKY;  gl = false; }
                else if (bx_new <= x0) { bx_new = EADI_BX_ALLGND; }
            }
        }
        bx_f += bx_step;

        bool bx_changed = (bx_new != _eadiPrevBx[i] || newGL != _eadiPrevGroundLeft);

        if (!bx_changed && !in_prev_horiz && !in_prev_ladder) continue;

        eadiDrawScanline(tft, y, x0, x1, bx_new, gl);
        _eadiPrevBx[i] = bx_new;
    }
    _eadiPrevGroundLeft = newGL;
}

// Swap the ladder dirty bitmaps: prev = last frame's set (for the delta fill), current
// cleared for this frame's ladder/marker marks. Call once per frame before drawing them.
void eadiBallSwapDirty() {
    memcpy(_eadiLadderDirtyPrev, _eadiLadderDirty, sizeof(_eadiLadderDirty));
    memset(_eadiLadderDirty, 0, sizeof(_eadiLadderDirty));
}

// Record this frame's horizon-line dirty band (read by next frame's delta fill).
void eadiBallSetPrevHoriz(int16_t lo, int16_t hi) {
    _eadiPrevHorizLo = lo;
    _eadiPrevHorizHi = hi;
}

// Reset all shared ball delta-fill state. Each screen calls this in its chrome on entry.
void eadiBallResetState() {
    eadiBuildChordTable();
    memset(_eadiLadderDirty,     0, sizeof(_eadiLadderDirty));
    memset(_eadiLadderDirtyPrev, 0, sizeof(_eadiLadderDirtyPrev));
    _eadiChevronOn   = false;
    _eadiPrevHorizLo = INT16_MAX;
    _eadiPrevHorizHi = INT16_MIN;
}


// ═══ Master ball update ══════════════════════════════════════════════════════════════
// Renders one attitude-ball frame: sky/ground fill (full or delta), horizon line, pitch
// ladder, ADI markers, aircraft symbol. Vessel attitude and target/maneuver come from
// `state`; the prograde source differs per screen (SCFT orbital vs ACFT surface velocity)
// so it is passed in. The caller snapshots its ball-dirty trackers after this returns.
// Compute the orbital normal and radial-out marker directions (compass heading + pitch)
// from the velocity direction, using the local vertical as the radial reference:
//   normal    = up x velocity  (horizontal, perpendicular to the ground track)
//   radial-out= up orthogonalised to velocity  (points away from the body)
// Anti-normal / radial-in are the antipodes. Only meaningful for an orbital velocity.
static void eadiOrbitalDirs(float velHdg, float velPitch,
                            float &normHdg, float &normPitch, float &radHdg, float &radPitch) {
    float th = velHdg * (float)DEG_TO_RAD, ph = velPitch * (float)DEG_TO_RAD, cph = cosf(ph);
    float vE = cph * sinf(th), vN = cph * cosf(th), vU = sinf(ph);   // velocity in East/North/Up
    normHdg   = atan2f(-vN, vE) * (float)RAD_TO_DEG;                 // up x v (horizontal)
    normPitch = 0.0f;                                               // normal is always on the horizon
    float rE = -vU * vE, rN = -vU * vN, rU = 1.0f - vU * vU;         // up - (up.v) v
    float rlen = sqrtf(rE*rE + rN*rN + rU*rU); if (rlen < 1e-4f) rlen = 1e-4f;
    rU /= rlen; if (rU > 1.0f) rU = 1.0f; else if (rU < -1.0f) rU = -1.0f;
    radHdg   = atan2f(rE, rN) * (float)RAD_TO_DEG;
    radPitch = asinf(rU) * (float)RAD_TO_DEG;
}

void eadiDrawBall(KCM_TFT &tft, bool fullRedraw, float progradeHdg, float progradePitch, bool orbital) {
    eadiBuildChordTable();   // no-op after first call

    float pitch = state.pitch;
    float roll  = -state.roll;   // negate: KerbalSimpit sign convention

    float cosR    = cosf(roll * (float)DEG_TO_RAD);
    float sinR    = sinf(roll * (float)DEG_TO_RAD);
    float pitchPx = pitch * EADI_SCALE;

    float K   = sinR * (float)EADI_CX - cosR * (float)EADI_CY - pitchPx;
    float BCX = (float)EADI_CX - pitchPx * sinR;
    float BCY = (float)EADI_CY + pitchPx * cosR;
    float hc2 = (float)EADI_R * EADI_R - pitchPx * pitchPx;

    uint32_t _t0, _t1;

    // ── 1. Sky/ground fill ────────────────────────────────────────────────────────────
    _t0 = micros();
    if (fullRedraw) eadiFullDraw(tft, sinR, cosR, K);
    else            eadiDeltaDraw(tft, sinR, cosR, K);
    _t1 = micros();
    if (debugMode) { Serial.print(fullRedraw ? "  fill(FULL)=" : "  fill(DELTA)=");
                     Serial.print((_t1-_t0)/1000.0f, 2); Serial.print("ms"); }

    // ── 2. Horizon line ───────────────────────────────────────────────────────────────
    _t0 = micros();
    int16_t new_horiz_lo = INT16_MAX, new_horiz_hi = INT16_MIN;
    if (hc2 >= 0.0f) {
        float hc  = max(0.0f, sqrtf(hc2) - 3.0f);
        int16_t lx1 = (int16_t)(BCX - hc * cosR);
        int16_t ly1 = (int16_t)(BCY - hc * sinR);
        int16_t lx2 = (int16_t)(BCX + hc * cosR);
        int16_t ly2 = (int16_t)(BCY + hc * sinR);
        tft.drawLine(lx1, ly1, lx2, ly2, EADI_HORIZON);
        auto rnd = [](float v) -> int16_t {
            return (int16_t)(v + (v > 0.0f ? 0.5f : -0.5f));
        };
        int16_t px = rnd(sinR), py = rnd(-cosR);
        tft.drawLine(lx1+px, ly1+py, lx2+px, ly2+py, EADI_HORIZON);
        new_horiz_lo = min(min(ly1, ly2), min((int16_t)(ly1+py), (int16_t)(ly2+py)));
        new_horiz_hi = max(max(ly1, ly2), max((int16_t)(ly1+py), (int16_t)(ly2+py)));
    }
    eadiBallSetPrevHoriz(new_horiz_lo, new_horiz_hi);
    _t1 = micros();
    if (debugMode) { Serial.print("  horiz="); Serial.print((_t1-_t0)/1000.0f, 2); Serial.print("ms"); }

    // ── 3. Pitch ladder ───────────────────────────────────────────────────────────────
    // Swap bitmaps: prev = last frame's dirty set (used by delta fill above),
    // current = cleared for this frame's ladder draw.
    _t0 = micros();
    eadiBallSwapDirty();
    eadiDrawLadder(tft, BCX, BCY, sinR, cosR);
    _t1 = micros();
    if (debugMode) { Serial.print("  ladder="); Serial.print((_t1-_t0)/1000.0f, 2); Serial.print("ms"); }

    // ── 4. ADI markers — prograde + retrograde always; target if available; maneuver if
    //       active. (Retrograde is antipodal to prograde; it clips out of the visible cone
    //       when the nose is prograde-side, like the KSP navball.) ─────────────────────
    eadiDrawAdiMarker(tft, progradeHdg,          progradePitch,  TFT_NEON_GREEN, KSP_MK_PROGRADE);
    eadiDrawAdiMarker(tft, progradeHdg + 180.0f, -progradePitch, TFT_NEON_GREEN, KSP_MK_RETROGRADE);
    if (state.targetAvailable) {
        eadiDrawAdiMarker(tft, state.tgtHeading,          state.tgtPitch,  TFT_VIOLET, KSP_MK_TARGET);
        eadiDrawAdiMarker(tft, state.tgtHeading + 180.0f, -state.tgtPitch, TFT_VIOLET, KSP_MK_ANTITARGET);
    }
    if (state.mnvrTime > 0.0f)
        eadiDrawAdiMarker(tft, state.mnvrHeading, state.mnvrPitch, TFT_BLUE, KSP_MK_MANEUVER);

    // Orbital-frame markers (SCFT only): normal/anti-normal (magenta) and radial-out/in
    // (cyan), computed from the orbital velocity. Each clips to the visible cone.
    if (orbital) {
        float nH, nP, rH, rP;
        eadiOrbitalDirs(progradeHdg, progradePitch, nH, nP, rH, rP);
        eadiDrawAdiMarker(tft, nH,          nP,  TFT_MAGENTA, KSP_MK_NORMAL);
        eadiDrawAdiMarker(tft, nH + 180.0f, -nP, TFT_MAGENTA, KSP_MK_ANTINORMAL);
        eadiDrawAdiMarker(tft, rH,          rP,  TFT_CYAN,    KSP_MK_RADIAL_OUT);
        eadiDrawAdiMarker(tft, rH + 180.0f, -rP, TFT_CYAN,    KSP_MK_RADIAL_IN);
    }

    // ── 5. Aircraft symbol — drawn last so it is always on top ────────────────────────
    eadiDrawAircraftSymbol(tft);
}


// ═══ Shared PFD tapes / boxes / roll readout (SCFT + ACFT) ═══════════════════════════
// SCFT and ACFT draw pixel-identical pitch/heading tapes, pitch/heading value boxes, and
// a roll readout. Historically each screen carried its own near-identical copy; the only
// real differences are (a) which markers each tape draws and (b) the roll warn/alarm
// colouring. The scaffolding lives here; the differences are passed in as parameters.
// Geometry MUST equal the per-screen SCFT_*/ACFT_* constants — it is re-derived below
// from the same EADI_CX/CY/R single source of truth, using the identical formulas.

// ── Pitch tape geometry (== SCFT_PTAPE_* == ACFT_PTAPE_*) ────────────────────────────
static const int16_t EADI_PTAPE_W        = 36;
static const int16_t EADI_PTAPE_GAP      = 27;
static const int16_t EADI_PTAPE_X        = EADI_CX - EADI_R - EADI_PTAPE_GAP - EADI_PTAPE_W;
static const int16_t EADI_PTAPE_Y        = EADI_CY - EADI_R;
static const int16_t EADI_PTAPE_H        = EADI_CY + EADI_R + 8 - (EADI_CY - EADI_R);
static const float   EADI_PTAPE_SCALE    = EADI_SCALE;                       // R/30 px/deg
static const int16_t EADI_PTAPE_BOX_W    = 68;
static const int16_t EADI_PTAPE_BOX_H    = 38;
static const int16_t EADI_PTAPE_BOX_X    = EADI_PTAPE_X + EADI_PTAPE_W - 68;
static const int16_t EADI_PTAPE_BOX_Y    = EADI_CY - EADI_PTAPE_BOX_H / 2;
static const int16_t EADI_PTAPE_SUPP_LO  = EADI_PTAPE_BOX_Y - 10;
static const int16_t EADI_PTAPE_SUPP_HI  = EADI_PTAPE_BOX_Y + EADI_PTAPE_BOX_H + 10;
static const int16_t EADI_PTAPE_MRK_BASE_X = EADI_PTAPE_X + EADI_PTAPE_W - 2;
static const int16_t EADI_PTAPE_MRK_TIP_X  = EADI_PTAPE_X + EADI_PTAPE_W - 22;
static const int16_t EADI_PTAPE_MRK_HW     = 9;

// ── Heading tape geometry (== SCFT_HDG_* == ACFT_HDG_*) ──────────────────────────────
static const int16_t EADI_HDG_TAPE_W     = (EADI_R * 2) + 54;
static const int16_t EADI_HDG_TAPE_X     = EADI_CX - (EADI_HDG_TAPE_W / 2);
static const int16_t EADI_HDG_TAPE_Y     = EADI_CY + EADI_R + 8;
static const int16_t EADI_HDG_TAPE_H     = 32;
static const float   EADI_HDG_SCALE      = (float)(EADI_R * 2) / 60.0f;
static const int16_t EADI_HDG_LABEL_LO   = EADI_HDG_TAPE_X + 8;
static const int16_t EADI_HDG_LABEL_HI   = EADI_HDG_TAPE_X + EADI_HDG_TAPE_W - 8;
static const int16_t EADI_HDG_BOX_W      = 72;
static const int16_t EADI_HDG_BOX_H      = EADI_HDG_TAPE_H + 8;
static const int16_t EADI_HDG_BOX_X      = EADI_CX - (EADI_HDG_BOX_W / 2);
static const int16_t EADI_HDG_BOX_Y      = EADI_HDG_TAPE_Y;
static const int16_t EADI_HDG_SUPP_LO    = EADI_HDG_BOX_X - 18;
static const int16_t EADI_HDG_SUPP_HI    = EADI_HDG_BOX_X + EADI_HDG_BOX_W + 18;
static const int16_t EADI_HDG_MRK_BASE_Y = EADI_HDG_TAPE_Y + 2;
static const int16_t EADI_HDG_MRK_TIP_Y  = EADI_HDG_TAPE_Y + 24;
static const int16_t EADI_HDG_MRK_HW     = 9;

// ── Roll readout geometry (== SCFT_ROLL_* == ACFT_ROLL_*) ────────────────────────────
static const int16_t EADI_ROLL_ANCHOR_X  = EADI_CX + EADI_R - 54;
static const int16_t EADI_ROLL_ANCHOR_Y  = TITLE_TOP;
static const int16_t EADI_ROLL_W         = 80;
static const int16_t EADI_ROLL_TXT_W     = EADI_ROLL_W + 6;
static const int16_t EADI_ROLL_LABEL_H   = 30;
static const int16_t EADI_ROLL_VALUE_H   = 38;
static const int16_t EADI_ROLL_GAP       = 3;

// Draw/update the pitch value box — cached on integer change. Caller owns `prevBox`.
void eadiUpdatePitchBox(KCM_TFT &tft, float pitch, int16_t &prevBox) {
    int16_t iPitch = (int16_t)roundf(pitch);
    if (iPitch == prevBox) return;

    char newBuf[8];
    snprintf(newBuf, sizeof(newBuf), "%+d\xB0", iPitch);

    if (prevBox > -9000) {
        char oldBuf[8];
        snprintf(oldBuf, sizeof(oldBuf), "%+d\xB0", prevBox);
        eraseCenteredValue(tft, &Roboto_Black_28,
                   EADI_PTAPE_BOX_X, EADI_PTAPE_BOX_Y + 1,
                   EADI_PTAPE_BOX_W, EADI_PTAPE_BOX_H - 2,
                   oldBuf, TFT_BLACK);
    }
    textCenter(tft, &Roboto_Black_28,
               EADI_PTAPE_BOX_X, EADI_PTAPE_BOX_Y + 1,
               EADI_PTAPE_BOX_W, EADI_PTAPE_BOX_H - 2,
               newBuf, TFT_DARK_GREEN, TFT_BLACK);

    prevBox = iPitch;
}

// Draw the full pitch tape. `markers` (value = pitch°, colour) draws the per-screen
// marker set as left-pointing triangles on the tape's right edge.
void eadiDrawPitchTape(KCM_TFT &tft, float pitch,
                       const EadiTapeMarker *markers, uint8_t nMarkers) {
    // Clear tape in two passes, skipping the box area and staying 1px inside borders
    int16_t fillW  = EADI_PTAPE_W - 1;  // stop 1px short of right border
    int16_t aboveH = EADI_PTAPE_BOX_Y - EADI_PTAPE_Y;
    int16_t belowY = EADI_PTAPE_BOX_Y + EADI_PTAPE_BOX_H;
    int16_t belowH = (EADI_PTAPE_Y + EADI_PTAPE_H - 1) - belowY;  // stop 1px short of bottom border
    tft.fillRect(EADI_PTAPE_X, EADI_PTAPE_Y, fillW, aboveH, TFT_BLACK);
    tft.fillRect(EADI_PTAPE_X, belowY,       fillW, belowH, TFT_BLACK);

    // Redraw box border (sides may have been touched by above/below fills)
    tft.drawRect(EADI_PTAPE_BOX_X, EADI_PTAPE_BOX_Y, EADI_PTAPE_BOX_W, EADI_PTAPE_BOX_H, TFT_LIGHT_GREY);
    // Box interior not erased — no need to reset the caller's pitch-box cache

    tft.setFont(Roboto_Black_12);

    // Draw ticks from pitch-32 to pitch+32 (slightly beyond ±30° visible range)
    for (int16_t dp = -32; dp <= 32; dp++) {
        float deg = pitch + (float)dp;
        if (deg < -90.0f || deg > 90.0f) continue;  // KSP pitch clamped ±90°

        // Pixel y: current pitch stays at centre (EADI_CY), offset by dp degrees
        int16_t py = (int16_t)(EADI_CY - (float)dp * EADI_PTAPE_SCALE);

        // Clip to tape interior
        if (py <= EADI_PTAPE_Y || py >= EADI_PTAPE_Y + EADI_PTAPE_H) continue;

        // Suppress near value box
        if (py >= EADI_PTAPE_SUPP_LO && py <= EADI_PTAPE_SUPP_HI) continue;

        int16_t ideg = (int16_t)roundf(deg);

        if (ideg % 10 == 0) {
            // Major tick — right-aligned, stopping 1px short of right border
            int16_t tx0 = EADI_PTAPE_X + EADI_PTAPE_W - 11;
            int16_t tx1 = EADI_PTAPE_X + EADI_PTAPE_W - 2;
            tft.drawLine(tx0, py, tx1, py, TFT_LIGHT_GREY);

            // Label — left of tick, clamped to tape
            char lbl[8];
            snprintf(lbl, sizeof(lbl), "%+d", ideg);
            int16_t lx = EADI_PTAPE_X + 2;
            int16_t ly = py - 6;
            if (ly < EADI_PTAPE_Y + 1) ly = EADI_PTAPE_Y + 1;
            if (ly + 12 > EADI_PTAPE_Y + EADI_PTAPE_H - 3)
                ly = EADI_PTAPE_Y + EADI_PTAPE_H - 15;
            // Only draw if label y is not in suppress zone
            if (!(ly + 6 >= EADI_PTAPE_SUPP_LO && ly + 6 <= EADI_PTAPE_SUPP_HI)) {
                tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
                tft.setCursor(lx, ly);
                tft.print(lbl);
            }
        } else if (ideg % 2 == 0) {
            // Minor tick (every 2°) — stopping 1px short of right border
            int16_t tx0 = EADI_PTAPE_X + EADI_PTAPE_W - 7;
            int16_t tx1 = EADI_PTAPE_X + EADI_PTAPE_W - 2;
            tft.drawLine(tx0, py, tx1, py, TFT_DARK_GREY);
        }
    }

    // Redraw the tape's bottom border — the lowest number labels' opaque black
    // background can paint over it, and it is otherwise only drawn once in chrome.
    tft.drawLine(EADI_PTAPE_X - 1,                EADI_PTAPE_Y + EADI_PTAPE_H - 1,
                 EADI_PTAPE_X + EADI_PTAPE_W - 1, EADI_PTAPE_Y + EADI_PTAPE_H - 1, TFT_LIGHT_GREY);

    // Draw pitch markers (left-pointing triangles on right edge)
    auto drawPitchMarker = [&](float markerPitch, uint16_t col) {
        float diff = markerPitch - pitch;
        int16_t py = (int16_t)(EADI_CY - diff * EADI_PTAPE_SCALE);
        // Peg to tape edges rather than hiding
        int16_t pyMin = EADI_PTAPE_Y + EADI_PTAPE_MRK_HW + 1;
        int16_t pyMax = EADI_PTAPE_Y + EADI_PTAPE_H - EADI_PTAPE_MRK_HW - 2;
        if (py < pyMin) py = pyMin;
        if (py > pyMax) py = pyMax;
        if (py >= EADI_PTAPE_SUPP_LO && py <= EADI_PTAPE_SUPP_HI) return;
        tft.fillTriangle(EADI_PTAPE_MRK_TIP_X,  py,
                         EADI_PTAPE_MRK_BASE_X,  py - EADI_PTAPE_MRK_HW,
                         EADI_PTAPE_MRK_BASE_X,  py + EADI_PTAPE_MRK_HW,
                         col);
    };

    for (uint8_t i = 0; i < nMarkers; i++)
        drawPitchMarker(markers[i].value, markers[i].colour);
}

// Draw/update the heading number box — cached, only redraws when integer heading changes.
// Uses textCenter for flicker-free rendering: erase old value with black-on-black first.
void eadiUpdateHdgBox(KCM_TFT &tft, float hdg, int16_t &prevBox) {
    int16_t iHdg = (int16_t)roundf(hdg) % 360;
    if (iHdg < 0) iHdg += 360;
    if (iHdg == prevBox) return;

    char oldBuf[8], newBuf[8];
    snprintf(newBuf, sizeof(newBuf), "%03d\xB0", iHdg);

    // Erase previous value with black-on-black
    if (prevBox >= 0) {
        snprintf(oldBuf, sizeof(oldBuf), "%03d\xB0", prevBox);
        eraseCenteredValue(tft, &Roboto_Black_28,
                   EADI_HDG_BOX_X, EADI_HDG_BOX_Y + 1,
                   EADI_HDG_BOX_W, EADI_HDG_BOX_H - 2,
                   oldBuf, TFT_BLACK);
    }

    // Draw new value
    textCenter(tft, &Roboto_Black_28,
               EADI_HDG_BOX_X, EADI_HDG_BOX_Y + 1,
               EADI_HDG_BOX_W, EADI_HDG_BOX_H - 2,
               newBuf, TFT_DARK_GREEN, TFT_BLACK);

    prevBox = iHdg;
}

// Draw the full heading tape. Only the tape strip — box is handled separately. The fill
// blackens the box interior, so the caller's `prevHdgBox` cache is forced to -1 to make
// the next box update redraw. `markers` (value = heading°, colour) is the per-screen set.
void eadiDrawHeadingTape(KCM_TFT &tft, float hdg, int16_t &prevHdgBox,
                         const EadiTapeMarker *markers, uint8_t nMarkers) {
    while (hdg <   0.0f) hdg += 360.0f;
    while (hdg >= 360.0f) hdg -= 360.0f;

    tft.fillRect(EADI_HDG_TAPE_X, EADI_HDG_TAPE_Y, EADI_HDG_TAPE_W, EADI_HDG_TAPE_H, TFT_BLACK);

    // Redraw box border after fill (fill erases box sides where they overlap)
    tft.drawRect(EADI_HDG_BOX_X, EADI_HDG_BOX_Y, EADI_HDG_BOX_W, EADI_HDG_BOX_H, TFT_LIGHT_GREY);

    // Force box number to redraw — fill blackened the interior
    prevHdgBox = -1;

    tft.setFont(Roboto_Black_12);

    for (int16_t d = -32; d <= 32; d++) {
        float deg = hdg + (float)d;
        while (deg <   0.0f) deg += 360.0f;
        while (deg >= 360.0f) deg -= 360.0f;

        int16_t px  = (int16_t)(EADI_CX + d * EADI_HDG_SCALE);
        // Strict clip — exclude boundary pixels to prevent residual at edges
        if (px <= EADI_HDG_TAPE_X || px >= EADI_HDG_TAPE_X + EADI_HDG_TAPE_W) continue;

        // Suppress elements near the box (expanded to cover label text extents)
        if (px >= EADI_HDG_SUPP_LO && px <= EADI_HDG_SUPP_HI) continue;

        int16_t ideg = (int16_t)roundf(deg);
        if (ideg == 360) ideg = 0;

        if (ideg % 10 == 0) {
            tft.drawLine(px, EADI_HDG_TAPE_Y, px, EADI_HDG_TAPE_Y + 10, TFT_LIGHT_GREY);

            if (px >= EADI_HDG_LABEL_LO && px <= EADI_HDG_LABEL_HI) {
                const char *lbl;
                uint16_t    col;
                char        numbuf[8];
                if      (ideg ==   0) { lbl = "N";  col = TFT_YELLOW;  }
                else if (ideg ==  90) { lbl = "E";  col = TFT_WHITE;   }
                else if (ideg == 180) { lbl = "S";  col = TFT_WHITE;   }
                else if (ideg == 270) { lbl = "W";  col = TFT_WHITE;   }
                else {
                    snprintf(numbuf, sizeof(numbuf), "%d", ideg);
                    lbl = numbuf;
                    col = TFT_LIGHT_GREY;
                }
                tft.setTextColor(col, TFT_BLACK);
                uint8_t  lw  = strlen(lbl) * 8;
                // Clamp cursor so label never bleeds outside the tape area
                int16_t  cx  = px - (int16_t)(lw / 2);
                if (cx < EADI_HDG_TAPE_X + 1) cx = EADI_HDG_TAPE_X + 1;
                if (cx + lw > EADI_HDG_TAPE_X + EADI_HDG_TAPE_W - 1)
                    cx = EADI_HDG_TAPE_X + EADI_HDG_TAPE_W - 1 - lw;
                tft.setCursor(cx, EADI_HDG_TAPE_Y + 12);
                tft.print(lbl);
            }
        } else if (ideg % 2 == 0) {
            tft.drawLine(px, EADI_HDG_TAPE_Y, px, EADI_HDG_TAPE_Y + 6, TFT_DARK_GREY);
        }
    }

    // Draw heading markers after ticks so they render on top
    auto drawMarker = [&](float markerHdg, uint16_t col) {
        // Find angular offset with wrap
        float diff = markerHdg - hdg;
        while (diff >  180.0f) diff -= 360.0f;
        while (diff < -180.0f) diff += 360.0f;
        int16_t px = (int16_t)(EADI_CX + diff * EADI_HDG_SCALE);
        // Peg to tape edges (leave room for half-width) rather than hiding
        int16_t pxMin = EADI_HDG_TAPE_X + EADI_HDG_MRK_HW + 1;
        int16_t pxMax = EADI_HDG_TAPE_X + EADI_HDG_TAPE_W - EADI_HDG_MRK_HW - 1;
        if (px < pxMin) px = pxMin;
        if (px > pxMax) px = pxMax;
        // Skip if in suppress zone
        if (px >= EADI_HDG_SUPP_LO && px <= EADI_HDG_SUPP_HI) return;
        tft.fillTriangle(px,                    EADI_HDG_MRK_TIP_Y,
                         px - EADI_HDG_MRK_HW,  EADI_HDG_MRK_BASE_Y,
                         px + EADI_HDG_MRK_HW,  EADI_HDG_MRK_BASE_Y,
                         col);
    };

    for (uint8_t i = 0; i < nMarkers; i++)
        drawMarker(markers[i].value, markers[i].colour);
}

// Update the roll numeric readout — two lines right-justified toward the panel divider.
// `fg`/`bg` are computed per screen (SCFT: fixed dark-green; ACFT: roll warn/alarm).
// Caller owns `prevReadout`/`prevFg`.
void eadiUpdateRollReadout(KCM_TFT &tft, float roll, uint16_t fg, uint16_t bg,
                           int16_t &prevReadout, uint16_t &prevFg) {
    int16_t iRoll = (int16_t)roundf(roll);

    if (iRoll == prevReadout && fg == prevFg) return;

    // Erase previous value — right-justified glyph box (matches textRight below).
    if (prevReadout > -9000) {
        char oldBuf[8];
        snprintf(oldBuf, sizeof(oldBuf), "%+d\xB0", prevReadout);
        int16_t ow   = getFontStringWidth(&Roboto_Black_28, oldBuf);
        int16_t capH = (int16_t)Roboto_Black_28.cap_height;
        int16_t ex   = EADI_ROLL_ANCHOR_X + EADI_ROLL_TXT_W - ow - TEXT_BORDER;
        int16_t ey   = (EADI_ROLL_ANCHOR_Y + EADI_ROLL_LABEL_H + EADI_ROLL_GAP)
                       + (EADI_ROLL_VALUE_H - capH) / 2;
        tft.fillRect(ex - 1, ey, ow + 2, capH, TFT_BLACK);
    }

    // Line 1: "ROLL" — label row, right-justified toward the panel divider
    textRight(tft, &Roboto_Black_24,
              EADI_ROLL_ANCHOR_X, EADI_ROLL_ANCHOR_Y,
              EADI_ROLL_TXT_W, EADI_ROLL_LABEL_H,
              "ROLL", TFT_WHITE, TFT_BLACK);

    // Line 2: signed value — larger font, right-justified in value row
    char buf[8];
    snprintf(buf, sizeof(buf), "%+d\xB0", iRoll);
    textRight(tft, &Roboto_Black_28,
              EADI_ROLL_ANCHOR_X, EADI_ROLL_ANCHOR_Y + EADI_ROLL_LABEL_H + EADI_ROLL_GAP,
              EADI_ROLL_TXT_W, EADI_ROLL_VALUE_H,
              buf, fg, bg);

    prevReadout = iRoll;
    prevFg      = fg;
}

/***************************************************************************************
   I2CSlave.ino -- I2C slave interface for KCMk1 Info Display
   Exposes Info Display state to the KCMk1 master (Teensy 4.1) over I2C.

   Hardware:
     I2C bus    : Wire2 (pins 24/25 on Teensy 4.1) — KCM_I2C_BUS
     Slave addr : 0x12 (Info Display 1) or 0x13 (Info Display 2), selected at
                  compile time by INFO_DISP_UNIT in KCMk1_InfoDisp.h. Same firmware
                  image for both boards; only this address differs.
     INT pin    : pin 0 (KCM_I2C_INT_PIN), OUTPUT, active-LOW
                  InfoDisp asserts LOW when a fresh packet is ready.
                  Master reads via KCM_I2C_BUS.requestFrom(I2C_SLAVE_ADDR, I2C_PACKET_SIZE).
                  Pin returns HIGH after the onRequest handler fires.

   Outbound packet (InfoDisp -> Master), I2C_PACKET_SIZE = 10 bytes:
     Byte 0  : 0xAE  -- sync/magic byte for framing validation (was 0xAD; collision fix)
     Byte 1  : flags
                 bit 0 = simpitConnected
                 bit 1 = flightScene
                 bit 2 = demoMode
                 bits 3-7 reserved (0)
     Byte 2  : activeScreen  -- current ScreenType enum value
     Byte 3  : apCmdSeq   -- Ascent-AP command sequence (0 = no command pending;
                            otherwise 1..255, unique per queued command). The master
                            executes the command in bytes 4-8 exactly once, then echoes
                            this value back in the inbound ackSeq byte to pop the queue.
     Byte 4  : apCmdOp    -- Ascent-AP command opcode (see AP_CMD_* in Screen_LNCH_AscentAP)
     Bytes 5-8 : apCmdPayload -- IEEE-754 float32, little-endian (command argument)
     Byte 9  : xsum       -- XOR of bytes 3..8 (command-frame integrity)

   Inbound command (Master -> InfoDisp), I2C_CMD_SIZE = 2 bytes:
     Byte 0  : controlByte
                 bits 7:4 = requestType
                   0x0 = NOP           -- no operation
                   0x1 = STATUS        -- request immediate status packet (asserts INT)
                   0x2 = PROCEED       -- proceed to main loop (release boot hold)
                   0x3 = MCU_RESET     -- soft reboot the InfoDisp
                   0x4 = DISPLAY_RESET -- reset display state and redraw current screen
                 bit  3   = idle_state  (1 = switch to standby when not in flight)
                 bit  2   = trimEnabled (1 = trim hold engaged; shows "TRIM" on SCFT/ACFT)
                 bit  1   = demoMode    (1 = enable demo mode)
                 bit  0   = debugMode   (1 = enable Serial debug output)
     Byte 1  : ackSeq (0x00 = none) -- Ascent-AP command acknowledgement. The master sets
                                       this to the apCmdSeq it just executed; InfoDisp pops
                                       that command from its queue. 0 leaves the queue as-is.

   Inbound Ascent-AP status (Master -> InfoDisp), I2C_AP_STATUS_SIZE = 40 bytes:
     Master pushes the autopilot's AscentStatus so InfoDisp can render live guidance and
     confirm accepted parameters (clearing the pilot's pending "cyan" edits). Dispatched
     by sync byte in processStatusPush(); see processApStatus() for the field layout.
     Byte 0  : 0xA5 sync
     Byte 1  : flags (bit0 armed, bit1 southerly, bit2 rollEnable)
     Byte 2  : phase (0 IDLE .. 6 ABORT)
     Byte 3  : reserved (0x00)
     Bytes 4-39 : 9 IEEE-754 float32 LE — targetAlt, inclination, loft, rollDeg, maxG,
                  cmdPitch, cmdHeading, cmdThrottle, dynPressure

   Inbound autopilot status pushes (Master -> InfoDisp) are DISPATCHED BY SYNC BYTE
   (Mission_Autopilot.md §8.1): any write of 3 bytes or more lands in one buffer and the
   main thread looks at byte 0. Lengths are fixed per frame but need not be unique.
     0xA5  40 bytes  ascent     (Ascent_Autopilot_Interface.md §5)
     0xA6  48 bytes  aircraft   flags, pitch/lat/thr modes, reason, reasonAge, 10 floats
     0xA7  36 bytes  rover      flags, reason, reasonAge, 8 floats
     0xA8  52 bytes  orbital    flags, mode, phase, reason, reasonAge, 11 floats
     0xA9  44 bytes  landing    flags, mode, entry, reason, reasonAge, accelSource, 9 floats
   The master pushes only the frame the console on screen needs (activeScreen, byte 2 of
   the outbound packet). The 2-byte control write keeps its own path.

   Expanding the protocol:
     Outbound: increment I2C_PACKET_SIZE, add fields to fillI2CPacketBuffer().
     Inbound:  add a new packet length + branch in onI2CReceive(), process in loop.
     Update master sketch to match in both cases.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// Info Display unit -> I2C slave address. INFO_DISP_UNIT is set per board in
// KCMk1_InfoDisp.h (1 = Info Display 1, 2 = Info Display 2), which also validates it.
// Same firmware image; the address differs so the master can talk to each board on
// the shared bus, and the unit additionally selects the panel's role — see the header.
#if INFO_DISP_IS_PFD_UNIT
#define I2C_SLAVE_ADDR   KCM_I2C_ADDR_INFODISP      // 0x12 (Info Display 1)
#else
#define I2C_SLAVE_ADDR   KCM_I2C_ADDR_INFODISP_2    // 0x13 (Info Display 2)
#endif
#define I2C_INT_PIN      KCM_I2C_INT_PIN             // #3C from SystemConfig
#define I2C_PACKET_SIZE  10     // outbound: InfoDisp -> Master (panel-specific; 3 status + AP cmd frame)
#define I2C_CMD_SIZE     2      // inbound:  Master -> InfoDisp control/ack (panel-specific)
#define I2C_AP_STATUS_SIZE 40   // inbound:  Master -> InfoDisp Ascent-AP status push
#define I2C_AP_STATUS_SYNC 0xA5 // framing byte for the AP status push
#define I2C_HA_STATUS_SIZE 48   // inbound:  Master -> InfoDisp aircraft hold-mode status push
#define I2C_HA_STATUS_SYNC 0xA6
#define I2C_RA_STATUS_SIZE 36   // inbound:  Master -> InfoDisp rover hold-mode status push
#define I2C_RA_STATUS_SYNC 0xA7
#define I2C_OB_STATUS_SIZE 52   // inbound:  Master -> InfoDisp orbital autopilot status push
#define I2C_OB_STATUS_SYNC 0xA8
#define I2C_LD_STATUS_SIZE 44   // inbound:  Master -> InfoDisp landing autopilot status push
#define I2C_LD_STATUS_SYNC 0xA9
#define I2C_PUSH_MAX       64   // one buffer for every status push; dispatched by sync byte
#define I2C_SYNC_BYTE    KCM_I2C_SYNC_INFODISP      // #3C from SystemConfig (0xAE, collision fix)

// requestType values (bits 7:4 of controlByte)
#define I2C_REQ_NOP           0x0
#define I2C_REQ_STATUS        0x1
#define I2C_REQ_PROCEED       0x2
#define I2C_REQ_MCU_RESET     0x3
#define I2C_REQ_DISPLAY_RESET 0x4


/***************************************************************************************
   PACKET BUFFER
   Built by buildI2CPacket() and consumed by onI2CRequest().
   Declared volatile because it is written on the main thread and read
   from the Wire interrupt context.
****************************************************************************************/
static volatile uint8_t i2cPacket[I2C_PACKET_SIZE];
static volatile bool i2cPacketReady = false;

// Set to true when the master sends I2C_REQ_PROCEED. setup() spins on this
// flag after initialisation before entering loop().
volatile bool i2cProceedReceived = false;


/***************************************************************************************
   PACKET FILL HELPER (#21)
   Writes current state into any I2C_PACKET_SIZE (10-byte) buffer. Used by both buildI2CPacket()
   and the change-detection path in updateI2CState() to avoid duplicated assembly.
****************************************************************************************/
static void fillI2CPacketBuffer(uint8_t *buf) {
  uint8_t flags = 0;
  if (simpitConnected) flags |= (1 << 0);
  if (flightScene)     flags |= (1 << 1);
  if (demoMode)        flags |= (1 << 2);
  buf[0] = I2C_SYNC_BYTE;
  buf[1] = flags;
  buf[2] = (uint8_t)activeScreen;
  apFillOutboundCmd(&buf[3]);            // bytes 3..8 : [seq][op][payload float LE]
  uint8_t xsum = 0;
  for (uint8_t i = 3; i < 9; i++) xsum ^= buf[i];
  buf[9] = xsum;                         // command-frame integrity check
}

/***************************************************************************************
   BUILD PACKET
   Thin wrapper around fillI2CPacketBuffer() — writes into the live packet buffer.
****************************************************************************************/
static void buildI2CPacket() {
  fillI2CPacketBuffer((uint8_t *)i2cPacket);
}


/***************************************************************************************
   PROCESS I2C COMMAND
   Called from loop() to apply a received command packet.
   Runs on the main thread -- safe to modify state, globals, and call Serial.
   Takes a snapshot of the command, copied out of the ISR buffer under noInterrupts by
   updateI2CState(), so a command arriving mid-read cannot be torn.
****************************************************************************************/
static volatile uint8_t i2cCmdBuf[I2C_CMD_SIZE];
static volatile bool i2cCmdReady = false;

// Inbound autopilot status push (Master -> InfoDisp), any console. Filled in the Wire
// ISR, snapshotted and dispatched on its sync byte by the main thread.
static volatile uint8_t pushBuf[I2C_PUSH_MAX];
static volatile uint8_t pushLen = 0;
static volatile bool    pushReady = false;

static void processI2CCommand(const uint8_t *cmd) {
  uint8_t controlByte = cmd[0];

  // --- Ascent-AP command acknowledgement (byte 1) ---
  // Master echoes the apCmdSeq it just executed; pop that command from the AP queue.
  apAckCommand(cmd[1]);

  // --- Lower nibble: mode configuration bits ---
  bool newDebug = (controlByte >> 0) & 1;
  bool newDemo  = (controlByte >> 1) & 1;
  bool newTrim  = (controlByte >> 2) & 1;   // trim-hold enabled (SCFT/ACFT "TRIM" annunciation)
  bool newIdle  = (controlByte >> 3) & 1;
  state.trimEnabled = newTrim;

  if (newDebug != debugMode) {
    debugMode = newDebug;
    setKDCDebugMode(debugMode);
    if (debugMode) Serial.println(F("InfoDisp: I2C -- debugMode on"));
  }

  if (newDemo != demoMode) {
    demoMode = newDemo;
    if (demoMode) {
      initDemoMode();
      if (debugMode) Serial.println(F("InfoDisp: I2C -- demoMode on"));
    } else {
      if (debugMode) Serial.println(F("InfoDisp: I2C -- demoMode off"));
      // #24 runtime demo->live: connect Simpit if not already connected
      if (!simpitConnected) {
        initSimpit();
      } else {
        simpit.requestMessageOnChannel(0);
      }
      // Standby splash drawn by loop() _wasDemo transition block
    }
  }

  if (newIdle != idleState) {
    idleState = newIdle;
    if (idleState && !flightScene) {
      drawStandbyScreen(infoDisp);   // #4 show standby immediately when idle asserted
    }
    if (debugMode) {
      Serial.print(F("InfoDisp: I2C -- idleState="));
      Serial.println(idleState);
    }
  }

  // --- Upper nibble: requestType ---
  uint8_t reqType = (controlByte >> 4) & 0x0F;
  switch (reqType) {

    case I2C_REQ_NOP:
      break;

    case I2C_REQ_STATUS:
      publishI2CPacket();
      if (debugMode) Serial.println(F("InfoDisp: I2C -- status requested"));
      break;

    case I2C_REQ_PROCEED:
      i2cProceedReceived = true;
      if (debugMode) Serial.println(F("InfoDisp: I2C -- proceed"));
      break;

    case I2C_REQ_MCU_RESET:
      if (debugMode) {
        Serial.println(F("InfoDisp: I2C -- MCU reset"));
        Serial.flush();
      }
      disconnectUSB();
      executeReboot();
      break;

    case I2C_REQ_DISPLAY_RESET:
      // switchToScreen() only — unlike the Annunciator, InfoDisp has no per-flight
      // boolean flags that need clearing on a display-only reset.
      if (debugMode) Serial.println(F("InfoDisp: I2C -- display reset"));
      switchToScreen(activeScreen);
      break;

    default:
      if (debugMode) {
        Serial.print(F("InfoDisp: I2C -- unknown reqType 0x"));
        Serial.println(reqType, HEX);
      }
      break;
  }

  if (debugMode) {
    Serial.print(F("InfoDisp: I2C cmd ctrl=0x"));
    Serial.println(controlByte, HEX);
  }
}


/***************************************************************************************
   PUBLISH PACKET
   Assembles the current state into a scratch buffer, then copies it into the live
   packet under noInterrupts() and asserts INT. The guarded copy is what keeps
   onI2CRequest() from transmitting a half-written packet: bytes 0-2 sit outside the
   byte-9 command checksum, so a torn packet would pass the master's framing check.
   Every path that raises INT goes through here.
****************************************************************************************/
static void publishI2CPacket() {
  uint8_t candidate[I2C_PACKET_SIZE];
  fillI2CPacketBuffer(candidate);
  noInterrupts();
  memcpy((uint8_t *)i2cPacket, candidate, I2C_PACKET_SIZE);
  i2cPacketReady = true;
  interrupts();
  digitalWriteFast(I2C_INT_PIN, LOW);
}

/***************************************************************************************
   BUILD PACKET AND ASSERT INT
   Public helper called from setup() after initialisation is complete.
****************************************************************************************/
void buildI2CPacketAndAssert() {
  publishI2CPacket();
  if (debugMode) Serial.println(F("InfoDisp: I2C -- init packet ready, asserting INT"));
}


/***************************************************************************************
   ON RECEIVE HANDLER -- interrupt context, keep short
****************************************************************************************/
static void onI2CReceive(int numBytes) {
  if (numBytes == I2C_CMD_SIZE) {
    for (int i = 0; i < I2C_CMD_SIZE; i++) {
      i2cCmdBuf[i] = KCM_I2C_BUS.read();
    }
    i2cCmdReady = true;
  } else if (numBytes >= 3 && numBytes <= I2C_PUSH_MAX) {
    for (int i = 0; i < numBytes; i++) {
      pushBuf[i] = KCM_I2C_BUS.read();
    }
    pushLen = (uint8_t)numBytes;
    pushReady = true;
  } else {
    while (KCM_I2C_BUS.available()) KCM_I2C_BUS.read();
  }
}


/***************************************************************************************
   PROCESS ASCENT-AP STATUS
   Applies a received AscentStatus push into the shared `state` struct so the Ascent
   Autopilot screen renders live guidance and confirms accepted parameters. Runs on the
   main thread. Skipped in demo mode (demo drives state.ap* locally).
****************************************************************************************/
static void processApStatus(const uint8_t *buf) {
  if (buf[0] != I2C_AP_STATUS_SYNC) return;   // framing guard

  uint8_t fl = buf[1];
  state.apArmed      = (fl & 0x01) != 0;
  state.apSoutherly  = (fl & 0x02) != 0;
  state.apRollEnable = (fl & 0x04) != 0;
  state.apPhase      = buf[2];

  float f[9];
  memcpy(f, &buf[4], sizeof(f));   // 9 floats, bytes 4..39
  state.apTargetAlt   = f[0];
  state.apInclination = f[1];
  state.apLoft        = f[2];
  state.apRollDeg     = f[3];
  state.apMaxG        = f[4];
  state.apCmdPitch    = f[5];
  state.apCmdHeading  = f[6];
  state.apCmdThrottle = f[7];
  state.apDynPressure = f[8];
}


/***************************************************************************************
   PROCESS HOLD-MODE STATUS (aircraft / rover)
   Applies the master's HoldStatus pushes into `state` so the AIRCRAFT AUTOPILOT and
   ROVER AUTOPILOT consoles render modes, setpoint echoes and disconnect reasons.
   Main thread; skipped in demo mode (Demo.ino drives state.hp* / state.rv* locally).
****************************************************************************************/
static void processHaStatus(const uint8_t *buf) {
  state.hpFlags     = buf[1];
  state.hpPitchMode = buf[2];
  state.hpLatMode   = buf[3];
  state.hpThrMode   = buf[4];
  state.hpReason    = buf[5];
  state.hpReasonAge = buf[6];
  float f[10];
  memcpy(f, &buf[8], sizeof(f));   // 10 floats, bytes 8..47
  state.hpAtt = f[0]; state.hpAoa = f[1]; state.hpVs = f[2]; state.hpAlt = f[3];
  state.hpRoll = f[4]; state.hpHdg = f[5]; state.hpIas = f[6]; state.hpMach = f[7];
  state.hpGs = f[8]; state.hpCmdThrottle = f[9];
}

static void processRaStatus(const uint8_t *buf) {
  state.rvFlags     = buf[1];
  state.rvReason    = buf[2];
  state.rvReasonAge = buf[3];
  float f[8];
  memcpy(f, &buf[4], sizeof(f));   // 8 floats, bytes 4..35
  state.rvCruise = f[0]; state.rvHdg = f[1]; state.rvMaxSpeed = f[2];
  state.rvMaxSlope = f[3]; state.rvMaxRoll = f[4]; state.rvFollowRange = f[5];
  state.rvStopDist = f[6]; state.rvCmdWheel = f[7];
}

static void processObStatus(const uint8_t *buf) {
  state.obFlags = buf[1]; state.obMode = buf[2]; state.obPhase = buf[3];
  state.obReason = buf[4]; state.obReasonAge = buf[5];
  float f[11];
  memcpy(f, &buf[8], sizeof(f));   // 11 floats, bytes 8..51
  state.obTargetAp = f[0]; state.obTargetPe = f[1]; state.obTargetInc = f[2];
  state.obApprRate = f[3]; state.obApprDist = f[4]; state.obDvTotal = f[5]; state.obDvRemaining = f[6];
  state.obTIgnition = f[7]; state.obBurnDuration = f[8]; state.obAccelEst = f[9]; state.obCmdThrottle = f[10];
}

static void processLdStatus(const uint8_t *buf) {
  state.ldFlags = buf[1]; state.ldMode = buf[2]; state.ldEntry = buf[3];
  state.ldReason = buf[4]; state.ldReasonAge = buf[5]; state.ldAccelSource = buf[6];
  float f[9];
  memcpy(f, &buf[8], sizeof(f));   // 9 floats, bytes 8..43
  state.ldDescRate = f[0]; state.ldHovrAlt = f[1]; state.ldTwr = f[2]; state.ldMargin = f[3];
  state.ldEntryAoa = f[4]; state.ldEntryRoll = f[5]; state.ldIgnAlt = f[6]; state.ldAccelEst = f[7]; state.ldCmdThrottle = f[8];
}

// Dispatch a status push on its sync byte; a length mismatch is a framing error and is dropped.
static void processStatusPush(const uint8_t *buf, uint8_t len) {
  switch (buf[0]) {
    case I2C_AP_STATUS_SYNC: if (len == I2C_AP_STATUS_SIZE) processApStatus(buf); break;
    case I2C_HA_STATUS_SYNC: if (len == I2C_HA_STATUS_SIZE) processHaStatus(buf); break;
    case I2C_RA_STATUS_SYNC: if (len == I2C_RA_STATUS_SIZE) processRaStatus(buf); break;
    case I2C_OB_STATUS_SYNC: if (len == I2C_OB_STATUS_SIZE) processObStatus(buf); break;
    case I2C_LD_STATUS_SYNC: if (len == I2C_LD_STATUS_SIZE) processLdStatus(buf); break;
    default: break;
  }
}


/***************************************************************************************
   ON REQUEST HANDLER -- interrupt context, keep short
****************************************************************************************/
static void onI2CRequest() {
  KCM_I2C_BUS.write((uint8_t *)i2cPacket, I2C_PACKET_SIZE);
  digitalWriteFast(I2C_INT_PIN, HIGH);
  i2cPacketReady = false;
}


/***************************************************************************************
   SETUP I2C SLAVE
   Call from setup() after display and touch are initialised.
****************************************************************************************/
void setupI2CSlave() {
  pinMode(I2C_INT_PIN, OUTPUT);
  digitalWriteFast(I2C_INT_PIN, HIGH);   // idle high

  KCM_I2C_BUS.begin(I2C_SLAVE_ADDR);
  KCM_I2C_BUS.onRequest(onI2CRequest);
  KCM_I2C_BUS.onReceive(onI2CReceive);

  buildI2CPacket();

  if (debugMode) {
    Serial.print(F("InfoDisp: I2C slave ready at 0x"));
    Serial.println(I2C_SLAVE_ADDR, HEX);
  }
}


/***************************************************************************************
   UPDATE I2C STATE
   Call from loop(). Applies pending inbound commands and detects outbound
   state changes, asserting INT when a fresh packet is ready.

   Both inbound buffers are snapshotted under noInterrupts() before use. The Wire ISR
   can land a new write at any point of a main-thread read; the 40-byte status push
   in particular would otherwise be read half old, half new, and its floats torn.
****************************************************************************************/
void updateI2CState() {
  uint8_t cmd[I2C_CMD_SIZE];
  uint8_t push[I2C_PUSH_MAX];
  uint8_t pushN = 0;
  bool haveCmd = false, havePush = false;
  noInterrupts();
  if (i2cCmdReady) {
    for (uint8_t i = 0; i < I2C_CMD_SIZE; i++) cmd[i] = i2cCmdBuf[i];
    i2cCmdReady = false;
    haveCmd = true;
  }
  if (pushReady) {
    pushN = pushLen;
    for (uint8_t i = 0; i < pushN; i++) push[i] = pushBuf[i];
    pushReady = false;
    havePush = true;
  }
  interrupts();
  if (haveCmd) processI2CCommand(cmd);

  // --- Apply inbound Ascent-AP status push (live mode only) ---
  if (havePush && !demoMode) processStatusPush(push, pushN);

  // --- Console command queue: expose next command, retire confirmed edits ---
  apPumpCommandQueue();
  apReconcilePending();    // ascent console
  hpReconcilePending();    // aircraft + rover consoles

  // --- Detect outbound state changes (#21) ---
  if (!i2cPacketReady) {
    uint8_t candidate[I2C_PACKET_SIZE];
    fillI2CPacketBuffer(candidate);
    if (memcmp((uint8_t *)i2cPacket, candidate, I2C_PACKET_SIZE) != 0) {
      publishI2CPacket();
      if (debugMode) Serial.println(F("InfoDisp: I2C packet ready"));
    }
  }
}

/***************************************************************************************
   Screen_ACFT.ino  --  Aircraft screen  (EADI style)

   EADI GEOMETRY
   -------------
   The aircraft symbol is FIXED at screen centre (CX, CY), always horizontal.
   The ball moves behind it:
     Ball centre:  BCX = CX - pitchPx*sinR
                   BCY = CY + pitchPx*cosR
   The horizon passes through (BCX, BCY), tilted at roll angle R.
   Horizon line equation:  sinR*x - cosR*y = K
     where K = sinR*CX - cosR*CY - pitchPx  (independent of roll)
   Sky side:    sinR*x - cosR*y > K
   Ground side: sinR*x - cosR*y <= K

   The perpendicular distance from (CX,CY) to the horizon = pitchPx always.
   At lad_p=pitch: rung foot = (CX,CY) exactly at all roll angles.

   PITCH LADDER
   ------------
   Rung at lad_p degrees:
     foot = (BCX + lad_p*SCALE*sinR,  BCY - lad_p*SCALE*cosR)
   Rung line direction = (cosR, sinR)  (parallel to horizon).
   Sky-ward normal = (sinR, -cosR).

   DISC
   ----
   Fixed on screen, centred at (CX, CY), radius R.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Geometry ──────────────────────────────────────────────────────────────────────────
// ONE PFD, ONE SET OF NUMBERS. This screen, SPACECRAFT and the shared EADIBall renderer
// all draw the same instrument, so they have to agree pixel for pixel about where the
// disc, the tapes and the value boxes sit. They used to say so three times over, each
// re-deriving the whole layout from its own copy of CX/CY/R -- 84 constants that were
// equal only because nobody had yet edited one of the three. The comments had already
// drifted: seven of them still quoted values from before the disc was enlarged, and two
// layout decisions in this repo were made off those stale numbers and came out wrong.
//
// EADIBall.ino now holds the single definition. The ACFT_* names below are kept, as
// aliases, so this screen's own chrome still reads in its own vocabulary -- but there is
// nothing left here that can disagree with the renderer.
static const int16_t  ACFT_CX        = EADI_CX;
static const int16_t  ACFT_CY        = EADI_CY;
static const int16_t  ACFT_R         = EADI_R;      // sized so the derived panel
                                                    //   (PANEL_X = CX+R+29) lands at x=580,
                                                    //   giving a 360px readout panel that
                                                    //   matches the reticle/launch screens
static const float    ACFT_SCALE     = EADI_SCALE;  // R/30 px/deg

// ── Right panel geometry ───────────────────────────────────────────────────────────────
// Panel left = HDG tape right + 2. HDG tape right = CX + (R*2+54)/2 = 345+233 = 578.
static const int16_t  ACFT_PANEL_X       = ACFT_CX - (ACFT_R*2+54)/2 + (ACFT_R*2+54) + 2; // 580
static const int16_t  ACFT_PANEL_RIGHT   = CONTENT_W;   // 940 — dividers/buttons reach x=939,
                                                        //   abutting the sidebar divider at x=940
static const int16_t  ACFT_PANEL_W       = ACFT_PANEL_RIGHT - ACFT_PANEL_X;  // 360 (= reticle panel)
static const uint8_t  ACFT_PANEL_NR      = 8;

// ── Right panel state ──────────────────────────────────────────────────────────────────
// Cache managed by rowCache[screen_ACFT] / printState[screen_ACFT] slots 0-11.
// No additional state variables needed — printValue handles dirty detection.



// ── Per-frame state ───────────────────────────────────────────────────────────────────

static float    _acftPrevPitch   = -9999.0f;
static float    _acftPrevRoll    = -9999.0f;

static bool     _acftFullRedrawNeeded = true;
static bool     _acftTrimShown        = false;   // TRIM flag is on screen (reset by chrome)


// ── Row 0: the altimeter, and when radar altitude takes it over ───────────────────────
// This screen had no barometric altitude at all. Row 0 was Alt.Rdr full-time, and its
// partner does not cover for it -- NAVIGATION carries Trk, Drift, Brg, Dist, V.Close,
// T+Int and Hdg -- so you could fly a KSP aeroplane on this controller and read your
// clearance over the ridge you were about to hit, but never the altitude you were
// cruising at.
//
// Real practice is the other way round and settles both halves at once. The PFD's
// altitude tape is barometric, always, on every aircraft built since the basic T; radio
// altitude is a separate and strictly conditional readout, appearing on the A320 only
// below 2,500 ft and stepping its resolution up as the ground comes closer (10 ft, then
// 5 ft below 50 ft, then 1 ft below 10 ft). It exists for the last few hundred metres,
// not the cruise.
//
// So row 0 is Alt.SL, handing over to Alt.Rdr below the switch height, with the same
// hysteresis idiom the SPACECRAFT rows use and the same pilot override.
//
// ONE DELIBERATE DEPARTURE. The A320 turns radio altitude amber below 400 ft. Not copied:
// this panel reserves yellow for caution, and a normal landing would paint the row yellow
// every single time -- the always-on alarm that teaches a pilot to ignore the colour.
// It is the same objection that kept V.Vrt out of the alarm tiers on SPACECRAFT row 5.
// The existing radar-altitude alarm tiers stay, because those are a real GPWS-style
// alarm about ground proximity rather than a mode annunciation.
ModeOverride _acftAltRefOverride;
static int8_t _acftChipShown = -1;   // -1 unknown, 0 auto-SL, 1 auto-RDR, 2 held-SL, 3 held-RDR
static int8_t _acftPrevAltRef = -1;   // last label painted on row 0 (-1 = none yet)
// IAS trend state. Up here rather than beside _acftDrawIasTrend because chromeScreen_ACFT
// resets it, and the Arduino builder hoists prototypes but not variables.
static float    _acftTrendPrevIas = -9999.0f;
static uint32_t _acftTrendPrevMs  = 0;
static float    _acftTrendAccel   = 0.0f;   // m/s^2, smoothed
static int8_t   _acftTrendShown   = 0;      // -3..+3, 0 = nothing drawn

static bool _acftAutoRdr() {
    // Hysteresis so the row cannot chatter while levelling off at the switch height.
    static bool rdr = false;
    const float a = state.radarAlt;
    if (rdr) { if (a > ACFT_ALT_RDR_OFF_M) rdr = false; }
    else     { if (a < ACFT_ALT_RDR_ON_M)  rdr = true;  }
    return rdr;
}

// true = show radar altitude.
static bool _acftAltRef() { return modeResolve(_acftAltRefOverride, _acftAutoRdr()); }

// Vertical speed is coloured on POWERED DESCENT's landing tiers (caution below -5 m/s,
// alarm below -8) only when the aircraft is on an approach: gear down, or below the
// radar-altimeter handover height. In cruise a normal descent runs well past both, and
// an always-on alarm is the one that teaches a pilot to ignore the colour.
static bool _acftLandingTiers() { return state.gear_on || _acftAutoRdr(); }

// Radar altitude with resolution rising as the ground approaches, the way a real radio
// altimeter reads. Metric equivalents of the A320's 10 ft / 5 ft / 1 ft steps.
static String _acftFmtRdr(float m) {
    char buf[16];
    if (m < 10.0f)       snprintf(buf, sizeof(buf), "%.1f m", (double)m);
    else if (m < 100.0f) snprintf(buf, sizeof(buf), "%d m", (int)lroundf(m));
    else                 snprintf(buf, sizeof(buf), "%d m", ((int)lroundf(m / 5.0f)) * 5);
    return String(buf);
}

void acftToggleAltRef() {
    modeToggle(_acftAltRefOverride, _acftAutoRdr());
    _acftChipShown = -1;
}






// Scanline fill, aircraft symbol, and disc clip are shared with SCFT — see EADIBall.ino
// (eadiDrawScanline / eadiDrawAircraftSymbol / eadiClipToDisk).








// ── ADI marker state (ball-side tracking — separate from tape-side state) ─────────────
// When any of these changes meaningfully, the ball must be redrawn so markers can be
// repositioned. Ball markers are drawn as the last layer of the ball (just before the
// aircraft symbol), so they're naturally wiped and re-rendered on any ball redraw.
static float _acftPrevHeadingBall    = -9999.0f;
static float _acftPrevVelHdgBall     = -9999.0f;
static float _acftPrevVelPitchBall   = -9999.0f;
static float _acftPrevMnvrHdgBall    = -9999.0f;
static float _acftPrevMnvrPitchBall  = -9999.0f;
static float _acftPrevTgtHdgBall     = -9999.0f;
static float _acftPrevTgtPitchBall   = -9999.0f;
static bool  _acftPrevMnvrActiveBall = false;
static bool  _acftPrevTgtAvailBall   = false;





// ── Roll indicator state ──────────────────────────────────────────────────────────────
static int16_t  _acftPrevRollReadout   = -9999;      // last drawn roll readout (integer degrees)
static uint16_t _acftPrevRollReadoutFg = 0;          // last drawn foreground colour

// ── Pitch readout state ───────────────────────────────────────────────────────────────


// Roll readout — geometry is EADI_ROLL_* in EADIBall.ino, which is what actually draws
// it. This screen only chooses the colour.

// Update the roll numeric readout — aircraft applies roll warn/alarm colouring (unlike
// spacecraft). Scaffolding/geometry live in the shared eadiUpdateRollReadout().
static void _acftUpdateRollReadout(KCM_TFT &tft, float roll) {
    float    absRoll = fabsf(roll);
    uint16_t fg = (absRoll > ROLL_ALARM_DEG) ? TFT_WHITE      :
                  (absRoll > ROLL_WARN_DEG)  ? TFT_YELLOW     : TFT_DARK_GREEN;
    uint16_t bg = (absRoll > ROLL_ALARM_DEG) ? TFT_RED        : TFT_BLACK;
    eadiUpdateRollReadout(tft, roll, fg, bg,
                          _acftPrevRollReadout, _acftPrevRollReadoutFg);
}

// ── Pitch tape ────────────────────────────────────────────────────────────────────────
// Shared availability state (also used by heading tape)
// Vertical tape on the left side of the disc. Same scale as the pitch ladder.
// ±30° visible, ticks at every 5° (minor) and 10° (major).
// Current value box centred on disc centre (pitch=0 line).
// Markers: left-pointing triangles on the right edge for vel/tgt/mnvr pitch.

// Only the outer frame and the value box are drawn here (in chromeScreen_ACFT); the
// ticks, labels, markers and suppress zone belong to eadiDrawPitchTape.
static const int16_t  ACFT_PTAPE_W       = EADI_PTAPE_W;       // 36
static const int16_t  ACFT_PTAPE_X       = EADI_PTAPE_X;       // 76
static const int16_t  ACFT_PTAPE_Y       = EADI_PTAPE_Y;       // 94  — top of disc
static const int16_t  ACFT_PTAPE_H       = EADI_PTAPE_H;       // 420 — bottom meets the HDG tape
static const int16_t  ACFT_PTAPE_BOX_W   = EADI_PTAPE_BOX_W;   // 68
static const int16_t  ACFT_PTAPE_BOX_H   = EADI_PTAPE_BOX_H;   // 38
static const int16_t  ACFT_PTAPE_BOX_X   = EADI_PTAPE_BOX_X;   // 44
static const int16_t  ACFT_PTAPE_BOX_Y   = EADI_PTAPE_BOX_Y;   // 281 — centred on pitch = 0

// State
static float   _acftPrevPitch2      = -9999.0f;   // pitch tape (distinct from ball state)
static int16_t _acftPrevPitchBox    = -9999;
static float   _acftPrevVelPitch    = -9999.0f;

// Draw/update the pitch value box — delegated to the shared helper (see EADIBall.ino).
static void _acftUpdatePitchBox(KCM_TFT &tft, float pitch) {
    eadiUpdatePitchBox(tft, pitch, _acftPrevPitchBox);
}

// Draw the full pitch tape. Aircraft markers: surface velocity pitch only — no target or
// maneuver markers. Scaffolding lives in the shared helper.
static void _acftDrawPitchTape(KCM_TFT &tft, float pitch) {
    EadiTapeMarker mk[1] = { { state.srfVelPitch, TFT_NEON_GREEN } };
    eadiDrawPitchTape(tft, pitch, mk, 1);
}

// Update pitch tape — redraws when pitch or velocity pitch changes.
static void _acftUpdatePitchTape(KCM_TFT &tft, float pitch) {
    bool dirty = fabsf(pitch - _acftPrevPitch2)                        >= 0.2f
              || fabsf(state.srfVelPitch - _acftPrevVelPitch)          >= 0.2f;

    if (dirty) {
        _acftDrawPitchTape(tft, pitch);
        _acftPrevPitch2   = pitch;
        _acftPrevVelPitch = state.srfVelPitch;
    }
    _acftUpdatePitchBox(tft, pitch);
}

// ── Heading tape state ────────────────────────────────────────────────────────────────
static float   _acftPrevHeading    = -9999.0f;
static int16_t _acftPrevHdgBox     = -9999;
static float   _acftPrevVelHdg     = -9999.0f;

// ── Heading tape geometry ─────────────────────────────────────────────────────────────
// As above: frame and box only. Ticks, labels, markers and the suppress zone are
// eadiDrawHeadingTape's.
static const int16_t  ACFT_HDG_TAPE_W    = EADI_HDG_TAPE_W;    // 466 — ±35° visible
static const int16_t  ACFT_HDG_TAPE_X    = EADI_HDG_TAPE_X;    // 112
static const int16_t  ACFT_HDG_TAPE_Y    = EADI_HDG_TAPE_Y;    // 514 — 8 px below the disc
static const int16_t  ACFT_HDG_TAPE_H    = EADI_HDG_TAPE_H;    // 32
static const int16_t  ACFT_HDG_BOX_W     = EADI_HDG_BOX_W;     // 72
static const int16_t  ACFT_HDG_BOX_H     = EADI_HDG_BOX_H;     // 40 — 8 px taller than the tape,
static const int16_t  ACFT_HDG_BOX_X     = EADI_HDG_BOX_X;     //   so its bottom border sits
static const int16_t  ACFT_HDG_BOX_Y     = EADI_HDG_BOX_Y;     //   outside the fill and can't flicker

// Draw/update the heading number box — delegated to the shared helper (see EADIBall.ino).
static void _acftUpdateHdgBox(KCM_TFT &tft, float hdg) {
    eadiUpdateHdgBox(tft, hdg, _acftPrevHdgBox);
}

// Draw the full heading tape. Aircraft markers: surface velocity heading only — no target
// or maneuver markers. Scaffolding lives in the shared helper, which also forces
// _acftPrevHdgBox to -1 (the fill blackens the box interior).
static void _acftDrawHeadingTape(KCM_TFT &tft, float hdg) {
    EadiTapeMarker mk[1] = { { state.srfVelHeading, TFT_NEON_GREEN } };
    eadiDrawHeadingTape(tft, hdg, _acftPrevHdgBox, mk, 1);
}

// Update heading — tape redraws when heading or velocity heading changes.
static void _acftUpdateHeadingTape(KCM_TFT &tft, float hdg) {
    bool dirty = fabsf(hdg - _acftPrevHeading)                     >= 0.5f
              || fabsf(state.srfVelHeading - _acftPrevVelHdg)      >= 0.5f;

    if (dirty) {
        _acftDrawHeadingTape(tft, hdg);
        _acftPrevHeading = hdg;
        _acftPrevVelHdg  = state.srfVelHeading;
    }
    _acftUpdateHdgBox(tft, hdg);
}




// ── Screen chrome ─────────────────────────────────────────────────────────────────────

// ── VSI, slip ball, AoA arc ───────────────────────────────────────────────────────────

// VSI tape — vertical velocity bar, left strip, zero at ACFT_CY
static const int16_t VSI_X       = 2;
static const int16_t VSI_BAR_W   = 18;
static const int16_t VSI_ZERO_Y  = ACFT_CY;
static const int16_t VSI_TICK_X0 = VSI_X + VSI_BAR_W;
static float   _acftPrevVSI      = -9999.0f;

static const int16_t VSI_LABEL_H  = 62;   // height reserved at bottom for "VSI" label (Roboto_Black_16 rotated)

static void _acftDrawVSIChrome(KCM_TFT &tft) {
    tft.drawLine(VSI_TICK_X0 + 1, TITLE_TOP, VSI_TICK_X0 + 1, SCREEN_H - 1, TFT_GREY);
    tft.drawLine(VSI_X, VSI_ZERO_Y,     VSI_TICK_X0 + 10, VSI_ZERO_Y,     TFT_LIGHT_GREY);
    tft.drawLine(VSI_X, VSI_ZERO_Y + 1, VSI_TICK_X0 + 10, VSI_ZERO_Y + 1, TFT_LIGHT_GREY);
    tft.setFont(Roboto_Black_12);
    for (int16_t v = -30; v <= 30; v += 5) {
        if (v == 0) continue;
        int16_t ty = VSI_ZERO_Y - (int16_t)(v * ACFT_SCALE);
        if (ty < TITLE_TOP + 2 || ty > SCREEN_H - VSI_LABEL_H - 4) continue;
        bool major = (v % 10 == 0);
        tft.drawLine(VSI_TICK_X0, ty, VSI_TICK_X0 + (major ? 10 : 6), ty,
                     major ? TFT_LIGHT_GREY : TFT_GREY);
        if (major) {
            tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);  // grey, matching pitch/hdg tapes
            tft.setCursor(VSI_TICK_X0 + 12, ty - 6);
            char lbl[4]; snprintf(lbl, sizeof(lbl), "%d", abs(v));
            tft.print(lbl);
        }
    }
    // "VSI" label — vertical, in bar at bottom, matching Pitch/Hdg label style
    drawVerticalText(tft, VSI_X, SCREEN_H - VSI_LABEL_H, VSI_BAR_W, VSI_LABEL_H,
                     &Roboto_Black_16, "VSI", TFT_WHITE, TFT_BLACK);
}

static void _acftUpdateVSI(KCM_TFT &tft, float vVrt) {
    if (fabsf(vVrt - _acftPrevVSI) < 0.1f) return;
    _acftPrevVSI = vVrt;
    float clamped = constrain(vVrt, -30.0f, 30.0f);
    int16_t fillH = (int16_t)fabsf(clamped * ACFT_SCALE);
    // Clear bar area — stop VSI_LABEL_H px short of bottom to preserve "VSI" label
    int16_t barTop = TITLE_TOP;
    int16_t barH   = SCREEN_H - TITLE_TOP - VSI_LABEL_H;
    tft.fillRect(VSI_X, barTop, VSI_BAR_W, barH, TFT_BLACK);
    if (fillH > 0) {
        uint16_t col = !_acftLandingTiers()        ? TFT_DARK_GREEN :
                       (vVrt < LNDG_VVRT_ALARM_MS) ? TFT_RED :
                       (vVrt < LNDG_VVRT_WARN_MS)  ? TFT_YELLOW : TFT_DARK_GREEN;
        int16_t fillY = (clamped > 0.0f) ? VSI_ZERO_Y - fillH : VSI_ZERO_Y + 2;
        // Clamp fill to bar area (don't paint over label)
        int16_t fillBot = fillY + fillH;
        int16_t barBot  = SCREEN_H - VSI_LABEL_H;
        if (fillBot > barBot) fillH = barBot - fillY;
        if (fillH > 0) tft.fillRect(VSI_X, fillY, VSI_BAR_W, fillH, col);
    }
    tft.drawLine(VSI_X, VSI_ZERO_Y,     VSI_TICK_X0 + 10, VSI_ZERO_Y,     TFT_LIGHT_GREY);
    tft.drawLine(VSI_X, VSI_ZERO_Y + 1, VSI_TICK_X0 + 10, VSI_ZERO_Y + 1, TFT_LIGHT_GREY);
}

// Slip ball — short strip pinned to the bottom of the screen, same x/width as the
// heading tape and the same HEIGHT as the heading tape. Centred on ACFT_CX.
static const int16_t SLIP_X       = ACFT_HDG_TAPE_X;
static const int16_t SLIP_W       = ACFT_HDG_TAPE_W;
static const int16_t SLIP_H       = ACFT_HDG_TAPE_H;                     // 32 — matches HDG tape
static const int16_t SLIP_Y       = SCREEN_H - 1 - SLIP_H;               // 567 — bottom border on row 598
                                                                         //   (row 599 is lost to overscan)
static const int16_t SLIP_BALL_R  = SLIP_H * 2 / 5;                      // 12 → 25px dia ≈ 80% of height
static const int16_t SLIP_CY      = SLIP_Y + SLIP_H / 2;
static const float   SLIP_SCALE   = (float)(SLIP_W / 2 - SLIP_BALL_R - 4) / 20.0f;
static int16_t _acftPrevSlipX     = 9999;

static void _acftDrawSlipChrome(KCM_TFT &tft) {
    tft.drawRect(SLIP_X, SLIP_Y, SLIP_W, SLIP_H, TFT_GREY);

    int16_t m5  = (int16_t)(SLIP_WARN_DEG  * SLIP_SCALE);
    int16_t m10 = (int16_t)(10.0f          * SLIP_SCALE);
    int16_t m15 = (int16_t)(SLIP_ALARM_DEG * SLIP_SCALE);

    // Range reference ticks at ±5, ±10, ±15 — drawn in the light-grey label colour
    // (matching the numeric labels), inset 1px from the top/bottom borders.
    const int16_t TLEN = 7;   // 80% of the previous 9px height
    int16_t topY0 = SLIP_Y + 1,              topY1 = SLIP_Y + 1 + TLEN;
    int16_t botY1 = SLIP_Y + SLIP_H - 2,     botY0 = botY1 - TLEN;
    const int markDx[] = { -m15, -m10, -m5, m5, m10, m15 };  // int: unary minus promotes
    for (uint8_t i = 0; i < 6; i++) {
        int16_t mx = ACFT_CX + markDx[i];
        tft.drawLine(mx, topY0, mx, topY1, TFT_LIGHT_GREY);
        tft.drawLine(mx, botY0, mx, botY1, TFT_LIGHT_GREY);
    }

    // Signed numeric labels centred above each tick, in the clear space above the
    // strip. All drawn in the standard light-grey label colour (not the tick colour).
    tft.setFont(Roboto_Black_12);
    const char *markTxt[] = { "-15", "-10", "-5", "+5", "+10", "+15" };
    int16_t lblY = SLIP_Y - 16;
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    for (uint8_t i = 0; i < 6; i++) {
        int16_t mx = ACFT_CX + markDx[i];
        int16_t w  = getFontStringWidth(&Roboto_Black_12, markTxt[i]);
        tft.setCursor(mx - w / 2, lblY);
        tft.print(markTxt[i]);
    }

    // "SLIP" label — right-justified in the space left of the strip, matching the
    // Pitch/Hdg label style
    textRight(tft, &Roboto_Black_24,
               VSI_TICK_X0 + 2, SLIP_Y, SLIP_X - VSI_TICK_X0 - 2, SLIP_H,
               "SLIP", TFT_WHITE, TFT_BLACK);
}

static void _acftUpdateSlipBall(KCM_TFT &tft, float slip) {
    float sc = constrain(slip, -20.0f, 20.0f);
    int16_t ballX = ACFT_CX + (int16_t)(sc * SLIP_SCALE);
    ballX = constrain(ballX, SLIP_X + SLIP_BALL_R + 2, SLIP_X + SLIP_W - SLIP_BALL_R - 2);
    if (_acftPrevSlipX != 9999 && abs(ballX - _acftPrevSlipX) <= 1) return;
    if (_acftPrevSlipX != 9999)
        tft.fillCircle(_acftPrevSlipX, SLIP_CY, SLIP_BALL_R + 1, TFT_BLACK);
    _acftDrawSlipChrome(tft);
    float absSlip = fabsf(slip);
    uint16_t col = (absSlip > SLIP_ALARM_DEG) ? TFT_RED :
                   (absSlip > SLIP_WARN_DEG)  ? TFT_YELLOW : TFT_DARK_GREEN;
    tft.fillCircle(ballX, SLIP_CY, SLIP_BALL_R, col);
    tft.drawCircle(ballX, SLIP_CY, SLIP_BALL_R, TFT_LIGHT_GREY);
    _acftPrevSlipX = ballX;
}

// ── AoA arc indicator ────────────────────────────────────────────────────────────────
// Solid arc on the left bezel. Zero AoA = 9 o'clock (180°).
// Arc angle = AOA_ZERO_DEG + aoa (see _acftUpdateAoAArc), so POSITIVE AoA (nose above
// velocity) INCREASES the screen angle from 180° toward 205°.
// Arc spans AOA_ANG_LO..AOA_ANG_HI in screen-angle degrees.
// Safe range: stays clear of bank=±60 roll ticks (which live at 210° and 330°).
// Drawn as solid colour bands using fillTriangle pairs — no float drift, no gaps.
static const int16_t  AOA_R_INNER  = ACFT_R + 4;    // 210 — just outside the bezel (R+2)
static const int16_t  AOA_R_OUTER  = ACFT_R + 18;   // 224 — 14 px band
static const float    AOA_ZERO_DEG = 180.0f;         // 9 o'clock
static const int16_t  AOA_ANG_LO   = 155;            // low screen angle  (= AoA -25°)
static const int16_t  AOA_ANG_HI   = 205;            // high screen angle (= AoA +25°)
// AoA thresholds in arc-angle space (1:1 scale: 1° AoA = 1° arc)
// Positive AoA → arc angle increases from 180°
// warn zone:  arc 190°..200°  (AoA +10°..+20°)
// alarm zone: arc 200°..205°  (AoA +20°..+25°)
// (negative AoA occupies 180°..155° symmetrically)

// Precomputed integer-degree cos/sin table for the arc range (155..206 inclusive)
static const uint8_t  AOA_STEPS     = (uint8_t)(AOA_ANG_HI - AOA_ANG_LO + 2); // 52 entries
static int16_t _aoaIX[AOA_STEPS];   // inner x at each degree
static int16_t _aoaIY[AOA_STEPS];   // inner y
static int16_t _aoaOX[AOA_STEPS];   // outer x
static int16_t _aoaOY[AOA_STEPS];   // outer y
static bool    _aoaTableReady = false;

static void _aoaBuildTable() {
    if (_aoaTableReady) return;
    for (uint8_t i = 0; i < AOA_STEPS; i++) {
        float rad = (AOA_ANG_LO + (int16_t)i) * DEG_TO_RAD;
        float ca = cosf(rad), sa = sinf(rad);
        _aoaIX[i] = (int16_t)(ACFT_CX + AOA_R_INNER * ca);
        _aoaIY[i] = (int16_t)(ACFT_CY + AOA_R_INNER * sa);
        _aoaOX[i] = (int16_t)(ACFT_CX + AOA_R_OUTER * ca);
        _aoaOY[i] = (int16_t)(ACFT_CY + AOA_R_OUTER * sa);
    }
    _aoaTableReady = true;
}

// Fill a solid arc segment [degLo..degHi] with colour col.
// Uses fillTriangle pairs on precomputed integer-degree vertices — no gaps, no drift.
static void _aoaFillSegment(KCM_TFT &tft, int16_t degLo, int16_t degHi, uint16_t col) {
    for (int16_t d = degLo; d < degHi; d++) {
        uint8_t i = (uint8_t)(d - AOA_ANG_LO);
        tft.fillTriangle(_aoaIX[i], _aoaIY[i], _aoaOX[i], _aoaOY[i],
                         _aoaOX[i+1], _aoaOY[i+1], col);
        tft.fillTriangle(_aoaIX[i], _aoaIY[i], _aoaIX[i+1], _aoaIY[i+1],
                         _aoaOX[i+1], _aoaOY[i+1], col);
    }
}

// Draw the full arc background (chrome). Call once on screen entry.
// Orientation: 155° = lower arc (7 o'clock) = NEGATIVE AoA
//              180° = exact left  (9 o'clock) = zero AoA
//              205° = upper arc (11 o'clock)  = HIGH POSITIVE AoA
// So warn/alarm zones must be at the HIGH end of the angle range.
static void _acftDrawAoAChrome(KCM_TFT &tft) {
    _aoaBuildTable();
    // Zone boundaries derived from config thresholds — stays in sync with text field colours
    int16_t warnAng  = (int16_t)(AOA_ZERO_DEG + AOA_WARN_DEG);   // 180+10 = 190
    int16_t alarmAng = (int16_t)(AOA_ZERO_DEG + AOA_ALARM_DEG);  // 180+20 = 200
    // Grey base covers full arc, coloured zones painted on top
    _aoaFillSegment(tft, AOA_ANG_LO,  AOA_ANG_HI, TFT_DARK_GREY);
    _aoaFillSegment(tft, warnAng,      alarmAng,    TFT_YELLOW);
    _aoaFillSegment(tft, alarmAng,     AOA_ANG_HI,  TFT_RED);
    // Zero tick — white radial at 180°, drawn last
    uint8_t zi = (uint8_t)(180 - AOA_ANG_LO);
    tft.drawLine(_aoaIX[zi], _aoaIY[zi], _aoaOX[zi], _aoaOY[zi], TFT_WHITE);

    // "AoA" label centred just below the arc's lower end. The arc spans 155..205°
    // at radius R+18, so its lowest point is at y = CY + (R+18)*sin(25°) ≈ CY+92.
    // Place the label ~4px below that, in the clear slot between the pitch tape
    // (right edge 118) and the ball's left rim.
    textCenter(tft, &Roboto_Black_20,
               ACFT_CX - ACFT_R - 25, ACFT_CY + 100, 50, 26,
               "AoA", TFT_WHITE, TFT_BLACK);
}

// Pointer state — tracked in integer degrees to avoid float drift
static int16_t _acftPrevAoADeg = INT16_MIN;

// Restore background colour at a ±1° band around arcDeg
static void _aoaErasePointer(KCM_TFT &tft, int16_t arcDeg) {
    int16_t lo = max((int16_t)AOA_ANG_LO, (int16_t)(arcDeg - 1));
    int16_t hi = min((int16_t)(AOA_ANG_HI - 1), (int16_t)(arcDeg + 1));
    for (int16_t d = lo; d < hi; d++) {
        // Positive AoA = higher screen angle (d > 180). Only positive side has warn/alarm.
        int16_t aoaDeg = d - (int16_t)AOA_ZERO_DEG;
        uint16_t col = (aoaDeg >= (int16_t)AOA_ALARM_DEG) ? TFT_RED :
                       (aoaDeg >= (int16_t)AOA_WARN_DEG)  ? TFT_YELLOW : TFT_DARK_GREY;
        _aoaFillSegment(tft, d, d + 1, col);
    }
    // Restore zero tick if erased
    if (arcDeg >= 179 && arcDeg <= 181) {
        uint8_t zi = (uint8_t)(180 - AOA_ANG_LO);
        tft.drawLine(_aoaIX[zi], _aoaIY[zi], _aoaOX[zi], _aoaOY[zi], TFT_WHITE);
    }
}

// Draw pointer — 1° wide (≈3px at outer edge), bold white fill
static void _aoaDrawPointer(KCM_TFT &tft, int16_t arcDeg) {
    int16_t lo = max((int16_t)AOA_ANG_LO,       arcDeg);
    int16_t hi = min((int16_t)(AOA_ANG_HI - 1), (int16_t)(arcDeg + 1));
    _aoaFillSegment(tft, lo, hi, TFT_WHITE);
}

static void _acftUpdateAoAArc(KCM_TFT &tft, float aoa) {
    _aoaBuildTable();
    // Positive AoA → higher screen angle (toward 205° = 11 o'clock = upper arc)
    float arcF = AOA_ZERO_DEG + constrain(aoa, (float)(AOA_ANG_LO - 180), (float)(AOA_ANG_HI - 180));
    int16_t arcDeg = (int16_t)roundf(arcF);
    arcDeg = (int16_t)constrain((int32_t)arcDeg, (int32_t)AOA_ANG_LO, (int32_t)(AOA_ANG_HI - 1));

    if (arcDeg == _acftPrevAoADeg) return;

    // Erase old pointer
    if (_acftPrevAoADeg != INT16_MIN)
        _aoaErasePointer(tft, _acftPrevAoADeg);

    // Draw new pointer
    _aoaDrawPointer(tft, arcDeg);
    _acftPrevAoADeg = arcDeg;
}




// ── Screen update ─────────────────────────────────────────────────────────────────────

static void chromeScreen_ACFT(KCM_TFT &tft) {
    _acftTrimShown = false;
    _acftChipShown  = -1;
    _acftPrevAltRef = -1;
    _acftTrendPrevIas = -9999.0f;
    _acftTrendAccel = 0.0f;
    _acftTrendShown = 0;
    eadiBallResetState();
    _acftFullRedrawNeeded      = true;
    eadiResetRollIndicator();
    _acftPrevRollReadout       = -9999;
    _acftPrevRollReadoutFg     = 0;
    _acftPrevPitch2            = -9999.0f;
    _acftPrevPitchBox          = -9999;
    _acftPrevVelPitch          = -9999.0f;
    _acftPrevHeading           = -9999.0f;
    _acftPrevHdgBox            = -9999;
    _acftPrevVelHdg            = -9999.0f;
    // Panel values reset via rowCache invalidation (row cache cleared on screen switch)
    // Ball delta-fill state (chord table, dirty bitmaps, prev horizon) reset above.
    _acftPrevPitch        = -9999.0f;
    _acftPrevRoll         = -9999.0f;
    _acftPrevVSI          = -9999.0f;
    _acftPrevSlipX        = 9999;
    _acftPrevAoADeg       = INT16_MIN;

    // Ball-side marker trackers (distinct from tape-side; see _acftDrawAdiMarker)
    _acftPrevHeadingBall       = -9999.0f;
    _acftPrevVelHdgBall        = -9999.0f;
    _acftPrevVelPitchBall      = -9999.0f;
    _acftPrevMnvrHdgBall       = -9999.0f;
    _acftPrevMnvrPitchBall     = -9999.0f;
    _acftPrevTgtHdgBall        = -9999.0f;
    _acftPrevTgtPitchBall      = -9999.0f;
    _acftPrevMnvrActiveBall    = false;
    _acftPrevTgtAvailBall      = false;

    // Bezel ring
    tft.drawCircle(ACFT_CX, ACFT_CY, ACFT_R,     TFT_LIGHT_GREY);
    tft.drawCircle(ACFT_CX, ACFT_CY, ACFT_R + 1, TFT_WHITE);
    tft.drawCircle(ACFT_CX, ACFT_CY, ACFT_R + 2, TFT_DARK_GREY);

    // Bank scale tick marks outside the disc circumference (upper arc)
    static const int16_t ticks[] = {-60,-45,-30,-20,-10,0,10,20,30,45,60};
    for (uint8_t i = 0; i < 11; i++) eadiDrawBankTick(tft, ticks[i]);

    // Labels at ±30° and ±60° — drawn at R+28 along the tick radial (Roboto_Black_16)
    static const int16_t labelTicks[] = {-60, -30, 30, 60};
    for (uint8_t i = 0; i < 4; i++) eadiDrawBankLabel(tft, labelTicks[i]);

    // Heading box border
    tft.drawRect(ACFT_HDG_BOX_X, ACFT_HDG_BOX_Y, ACFT_HDG_BOX_W, ACFT_HDG_BOX_H, TFT_LIGHT_GREY);

    // Pitch tape chrome — value box border and three-sided tape border (top, right, bottom)
    tft.drawRect(ACFT_PTAPE_BOX_X, ACFT_PTAPE_BOX_Y, ACFT_PTAPE_BOX_W, ACFT_PTAPE_BOX_H, TFT_LIGHT_GREY);
    // Top, right, bottom lines — right and bottom drawn 1px inward to align with HDG tape borders
    tft.drawLine(ACFT_PTAPE_X - 1,                  ACFT_PTAPE_Y - 1,
                 ACFT_PTAPE_X + ACFT_PTAPE_W - 1,    ACFT_PTAPE_Y - 1, TFT_LIGHT_GREY);
    tft.drawLine(ACFT_PTAPE_X + ACFT_PTAPE_W - 1,    ACFT_PTAPE_Y - 1,
                 ACFT_PTAPE_X + ACFT_PTAPE_W - 1,    ACFT_PTAPE_Y + ACFT_PTAPE_H - 1, TFT_GREY);
    tft.drawLine(ACFT_PTAPE_X - 1,                  ACFT_PTAPE_Y + ACFT_PTAPE_H - 1,
                 ACFT_PTAPE_X + ACFT_PTAPE_W - 1,    ACFT_PTAPE_Y + ACFT_PTAPE_H - 1, TFT_LIGHT_GREY);

    // "PITCH" right-justified to right edge of pitch value box (box widened left
    // so the larger _24 label — 75px — fits without clipping the pitch value box)
    textRight(tft, &Roboto_Black_24,
              ACFT_PTAPE_BOX_X - 24, ACFT_PTAPE_Y - 32,
              ACFT_PTAPE_BOX_W + 24, 30,
              "PITCH", TFT_WHITE, TFT_BLACK);

    // Heading tape border — top (light grey) and two sides (darker), open at bottom
    tft.drawLine(ACFT_HDG_TAPE_X - 1, ACFT_HDG_TAPE_Y - 1,
                 ACFT_HDG_TAPE_X + ACFT_HDG_TAPE_W, ACFT_HDG_TAPE_Y - 1, TFT_LIGHT_GREY);
    tft.drawLine(ACFT_HDG_TAPE_X - 1, ACFT_HDG_TAPE_Y - 1,
                 ACFT_HDG_TAPE_X - 1, ACFT_HDG_TAPE_Y + ACFT_HDG_TAPE_H, TFT_GREY);
    tft.drawLine(ACFT_HDG_TAPE_X + ACFT_HDG_TAPE_W, ACFT_HDG_TAPE_Y - 1,
                 ACFT_HDG_TAPE_X + ACFT_HDG_TAPE_W, ACFT_HDG_TAPE_Y + ACFT_HDG_TAPE_H, TFT_GREY);

    // "HDG" right-justified to same right edge as "PITCH" label
    textRight(tft, &Roboto_Black_24,
              ACFT_PTAPE_BOX_X, ACFT_HDG_BOX_Y + ACFT_HDG_BOX_H / 2 - 15,
              ACFT_PTAPE_BOX_W, 30,
              "HDG", TFT_WHITE, TFT_BLACK);

    // ── VSI tape chrome ───────────────────────────────────────────────────────────────
    _acftDrawVSIChrome(tft);

    // ── Slip ball chrome ──────────────────────────────────────────────────────────────
    _acftDrawSlipChrome(tft);

    // ── AoA arc chrome ────────────────────────────────────────────────────────────────
    _acftDrawAoAChrome(tft);

    // ── Right panel chrome ─────────────────────────────────────────────────────────────
    // Vertical divider (2px) between ADI and panel
    tft.drawLine(ACFT_PANEL_X - 2, TITLE_TOP, ACFT_PANEL_X - 2, SCREEN_H - 1, TFT_GREY);
    tft.drawLine(ACFT_PANEL_X - 1, TITLE_TOP, ACFT_PANEL_X - 1, SCREEN_H - 1, TFT_GREY);

    static const tFont *PF = &Roboto_Black_28;   // label font — matches reticle/launch panels

    // Rows 0-3: single-width labels
    printDispChrome(tft, PF, ACFT_PANEL_X, rowYFor(0, ACFT_PANEL_NR), ACFT_PANEL_W, rowHFor(ACFT_PANEL_NR),
                    _acftAltRef() ? "ALT.RDR" : "ALT.SL", COL_LABEL, COL_BACK, COL_NO_BDR);
    _acftPrevAltRef = (int8_t)_acftAltRef();   // record what chrome just painted
    printDispChrome(tft, PF, ACFT_PANEL_X, rowYFor(1, ACFT_PANEL_NR), ACFT_PANEL_W, rowHFor(ACFT_PANEL_NR), "V.SRF",   COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, PF, ACFT_PANEL_X, rowYFor(2, ACFT_PANEL_NR), ACFT_PANEL_W, rowHFor(ACFT_PANEL_NR), "IAS",     COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, PF, ACFT_PANEL_X, rowYFor(3, ACFT_PANEL_NR), ACFT_PANEL_W, rowHFor(ACFT_PANEL_NR), "V.VRT",   COL_LABEL, COL_BACK, COL_NO_BDR);

    // Row 4: Ma | G split.
    // "MA", not "MACH" as ASCENT and RE-ENTRY use, and this is measured rather than
    // careless: these split cells are 180 px, "MACH" is 101 px at the value font and the
    // widest Mach reading is 95, which overflows by 26. Dropping a decimal does not save
    // it either. The abbreviation is forced by the cell, and it is the one place in the
    // sketch where a quantity carries a second name.
    {
        uint16_t hw = ACFT_PANEL_W / 2;
        uint16_t y  = rowYFor(4, ACFT_PANEL_NR), h = rowHFor(ACFT_PANEL_NR);
        printDispChrome(tft, PF, ACFT_PANEL_X,      y, hw, h, "MA", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, PF, ACFT_PANEL_X + hw, y, hw, h, "G",  COL_LABEL, COL_BACK, COL_NO_BDR);
        tft.drawLine(ACFT_PANEL_X + hw,     y, ACFT_PANEL_X + hw,     y + h - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, y, ACFT_PANEL_X + hw + 1, y + h - 1, TFT_GREY);
    }

    // Row 5: AoA | Slip split. "SLIP" in full, matching the slip-ball label on the same
    // screen -- the panel row used to say "SL" while the ball said "SLIP", one quantity
    // with two names three inches apart. It fits: the value is already whole degrees, so
    // the widest case "+180deg" is 96 px against a 74 px label in a 174 px usable cell.
    {
        uint16_t hw = ACFT_PANEL_W / 2;
        uint16_t y  = rowYFor(5, ACFT_PANEL_NR), h = rowHFor(ACFT_PANEL_NR);
        printDispChrome(tft, PF, ACFT_PANEL_X,      y, hw, h, "AOA",  COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, PF, ACFT_PANEL_X + hw, y, hw, h, "SLIP", COL_LABEL, COL_BACK, COL_NO_BDR);
        tft.drawLine(ACFT_PANEL_X + hw,     y, ACFT_PANEL_X + hw,     y + h - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, y, ACFT_PANEL_X + hw + 1, y + h - 1, TFT_GREY);
    }

    // Row 6: Gear | Airbrk — buttons draw own labels, just draw the split divider.
    {
        uint16_t hw = ACFT_PANEL_W / 2;
        uint16_t y6 = TITLE_TOP + 6 * rowHFor(ACFT_PANEL_NR);
        uint16_t y7 = TITLE_TOP + 7 * rowHFor(ACFT_PANEL_NR);
        tft.drawLine(ACFT_PANEL_X + hw,     y6, ACFT_PANEL_X + hw,     y7 - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, y6, ACFT_PANEL_X + hw + 1, y7 - 1, TFT_GREY);
    }

    // Row 7: Brakes | SAS split divider (buttons drawn in update)
    {
        uint16_t hw = ACFT_PANEL_W / 2;
        tft.drawLine(ACFT_PANEL_X + hw,     TITLE_TOP + 7 * rowHFor(ACFT_PANEL_NR),
                     ACFT_PANEL_X + hw,     SCREEN_H - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, TITLE_TOP + 7 * rowHFor(ACFT_PANEL_NR),
                     ACFT_PANEL_X + hw + 1, SCREEN_H - 1, TFT_GREY);
    }
}



// ── IAS trend ─────────────────────────────────────────────────────────────────────────
// Garmin's trend vector is a magenta line up or down the speed tape whose end marks the
// airspeed predicted six seconds out at the current acceleration; it is a large part of
// why a glass PFD feels ahead of the aircraft. Its LENGTH is meaningful because it is
// commensurate with the tape's own scale -- it literally reaches the speed you will have.
//
// We have no speed tape, so any length would be an invented scale, and in the ~40 px this
// row can spare only about three lengths are actually distinguishable. A continuously
// scaled arrow would therefore degrade to three states while implying precision it does
// not have. So the three states are made honest instead: a stack of one to three
// chevrons, up or down, thresholded on the six-second predicted change.
//
// Drawn OUTSIDE printValue's fill rect. printValue repaints the value region on every
// change, which would erase anything inside it -- the same hazard the panels already
// guard against by redrawing their row dividers last.
static const float   ACFT_TREND_S      = 6.0f;    // prediction horizon, as Garmin's
static const float   ACFT_TREND_1_MS   = 2.0f;    // one chevron above this predicted delta
static const float   ACFT_TREND_2_MS   = 6.0f;    // two
static const float   ACFT_TREND_3_MS   = 12.0f;   // three
static const int16_t ACFT_TREND_W      = 13;      // chevron half-width
static const int16_t ACFT_TREND_H      = 7;       // chevron height (apex to base)
static const int16_t ACFT_TREND_THICK  = 3;       // stroke weight, in stacked scanlines
static const int16_t ACFT_TREND_STEP   = 10;      // vertical pitch of the stack
static const int16_t ACFT_TREND_X      = ACFT_PANEL_X + 92;   // clear of the "IAS" label
static const int16_t ACFT_TREND_BOX_W  = 2 * ACFT_TREND_W + 6;
static const int16_t ACFT_TREND_BOX_H  = 3 * ACFT_TREND_STEP + ACFT_TREND_H +
                                         ACFT_TREND_THICK + 4;
// Magenta, not green. The chevrons are the one thing in this row that is a PREDICTION
// rather than a measurement, and magenta is what a glass cockpit reserves for computed
// guidance (flight director bars, the magenta course line on a moving map) as against the
// green of live state. Colouring them like the IAS value they sit beside implied they
// were part of it. Keep this distinct from TFT_VIOLET, which is the target-marker colour
// on SCFT/ACFT/ROVR -- these are unrelated channels that must not read as one.
static const uint16_t ACFT_TREND_COL   = TFT_MAGENTA;

static void _acftDrawIasTrend(KCM_TFT &tft, float ias) {
    const uint32_t now = millis();
    if (_acftTrendPrevIas < -9000.0f) { _acftTrendPrevIas = ias; _acftTrendPrevMs = now; return; }
    const float dt = (float)(uint32_t)(now - _acftTrendPrevMs) / 1000.0f;
    if (dt >= 0.10f) {
        if (dt <= 2.0f) {
            const float a = (ias - _acftTrendPrevIas) / dt;
            const float k = dt / (0.8f + dt);         // ~0.8 s smoothing
            _acftTrendAccel += k * (a - _acftTrendAccel);
        }
        _acftTrendPrevIas = ias;
        _acftTrendPrevMs  = now;
    }

    const float d = _acftTrendAccel * ACFT_TREND_S;
    const float ad = fabsf(d);
    int8_t want = 0;
    if      (ad >= ACFT_TREND_3_MS) want = 3;
    else if (ad >= ACFT_TREND_2_MS) want = 2;
    else if (ad >= ACFT_TREND_1_MS) want = 1;
    if (d < 0.0f) want = (int8_t)-want;
    if (want == _acftTrendShown) return;
    _acftTrendShown = want;

    const int16_t y0 = rowYFor(2, ACFT_PANEL_NR) +
                       (rowHFor(ACFT_PANEL_NR) - ACFT_TREND_BOX_H) / 2;
    tft.fillRect(ACFT_TREND_X - ACFT_TREND_W - 3, y0, ACFT_TREND_BOX_W, ACFT_TREND_BOX_H, TFT_BLACK);
    if (want == 0) return;

    const bool up = (want > 0);
    const int8_t n = up ? want : (int8_t)-want;
    for (int8_t i = 0; i < n; i++) {
        // Stack from the pointing end back, so one chevron always sits in the same place.
        // The stroke is laid down as ACFT_TREND_THICK scanlines BELOW the nominal line, so
        // the down-stack has to start that much higher or the thickest chevron's base
        // would spill out of the erase box and survive the next repaint.
        const int16_t ty = up ? (y0 + 2 + i * ACFT_TREND_STEP)
                              : (y0 + ACFT_TREND_BOX_H - 2 - ACFT_TREND_H
                                    - (ACFT_TREND_THICK - 1) - i * ACFT_TREND_STEP);
        const int16_t apexY = up ? ty : (int16_t)(ty + ACFT_TREND_H);
        const int16_t baseY = up ? (int16_t)(ty + ACFT_TREND_H) : ty;
        for (int16_t o = 0; o < ACFT_TREND_THICK; o++) {
            tft.drawLine(ACFT_TREND_X - ACFT_TREND_W, baseY + o,
                         ACFT_TREND_X,                apexY + o, ACFT_TREND_COL);
            tft.drawLine(ACFT_TREND_X,                apexY + o,
                         ACFT_TREND_X + ACFT_TREND_W, baseY + o, ACFT_TREND_COL);
        }
    }
}


// ── Right panel update ─────────────────────────────────────────────────────────────────
// Row order: Alt.SL/Alt.Rdr(0), V.Srf(1), IAS(2), V.Vrt(3), Ma|G(4), AoA|Slip(5), Gear|Airbrk(6), Brakes|SAS(7)
// Cache slots: 0=Alt, 1=V.Srf, 2=IAS, 3=V.Vrt, 4=Ma, 5=G, 6=AoA, 7=Slip,
//              8=Gear, 9=Airbrk, 10=Brakes, 11=SAS
static void _acftUpdatePanel(KCM_TFT &tft) {
    static const tFont  *VF = &Roboto_Black_36;   // value font — matches reticle/launch panels
    static const uint8_t SC = (uint8_t)screen_ACFT;
    uint16_t fw = ACFT_PANEL_W;
    uint16_t hw = ACFT_PANEL_W / 2;
    uint16_t fg, bg;
    char buf[20];

    auto acftVal = [&](uint8_t row, uint8_t slot, const char *label,
                       const String &val, uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, SC, slot, row, ACFT_PANEL_X, fw, label, val, fgc, bgc, VF, ACFT_PANEL_NR, true);
    };

    // Row 0 — Alt.Rdr
    {
        const bool rdr = _acftAltRef();
        // The label follows the switch height, so like SPACECRAFT's row 5 it repaints its
        // own chrome rather than waiting for a screen re-entry, and clears its cache slot
        // because printDispChrome fills over the value.
        if ((int8_t)rdr != _acftPrevAltRef) {
            printDispChrome(tft, &Roboto_Black_28, ACFT_PANEL_X,
                            rowYFor(0, ACFT_PANEL_NR), ACFT_PANEL_W,
                            rowHFor(ACFT_PANEL_NR), rdr ? "ALT.RDR" : "ALT.SL",
                            COL_LABEL, COL_BACK, COL_NO_BDR);
            rowCache[SC][0] = RowCache();
            printState[SC][0] = PrintState();
            _acftPrevAltRef = (int8_t)rdr;
        }
        if (rdr) {
            fg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_WHITE  :
                 (state.radarAlt < ALT_RDR_WARN_M)  ? TFT_YELLOW : TFT_DARK_GREEN;
            bg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_RED    : TFT_BLACK;
            acftVal(0, 0, "ALT.RDR", _acftFmtRdr(state.radarAlt), fg, bg);
        } else {
            acftVal(0, 0, "ALT.SL", formatAlt(state.altitude), TFT_DARK_GREEN, TFT_BLACK);
        }
    }

    // Row 1 — V.Srf (surfaceVel is a magnitude, always >= 0)
    {
        acftVal(1, 1, "V.SRF", fmtMs(state.surfaceVel), TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 2 — IAS, with a trend indicator.
    //
    // NO SPEED-BASED STALL WARNING HERE, deliberately. This row used to branch on
    // STALL_SPEED_MS, which was 0.0f in AAA_Config.ino, so the threshold arm had never
    // once executed and the row was permanently dark green -- dead code implying a
    // feature the panel did not have. A real PFD gets low-speed awareness either from
    // V-speeds (the white/green/yellow/red bands, red at Vne) or from angle of attack.
    // KSP and Simpit give us no V-speeds at any price, so the banded version is not
    // available; AoA is, we already compute it, and it is the physically correct stall
    // predictor regardless of speed -- which is why AoA-based awareness is what modern
    // light-aircraft PFDs actually fit. The AoA arc and the AoA row below are therefore
    // the single stall channel, and colouring IAS from the same signal would just put
    // one warning on the screen twice. Do not re-add a speed threshold without a real
    // per-airframe stall speed to put in it.
    {
        float ias = state.IAS;
        acftVal(2, 2, "IAS", fmtMs(ias), TFT_DARK_GREEN, TFT_BLACK);
        _acftDrawIasTrend(tft, ias);
    }

    // Row 3 — V.Vrt — colours match VSI bar thresholds
    {
        float vv = state.verticalVel;
        if      (!_acftLandingTiers())     { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }   // cruise: reported, not alarmed
        else if (vv < LNDG_VVRT_ALARM_MS) { fg = TFT_WHITE;     bg = TFT_RED;   }
        else if (vv < LNDG_VVRT_WARN_MS)  { fg = TFT_YELLOW;    bg = TFT_BLACK; }
        else                               { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        acftVal(3, 3, "V.VRT", fmtMs(vv), fg, bg);
    }

    // Row 4 — Ma | G split
    {
        uint16_t y4 = rowYFor(4, ACFT_PANEL_NR), h4 = rowHFor(ACFT_PANEL_NR);
        float m = state.machNumber;
        snprintf(buf, sizeof(buf), "%.2f", m);
        bool transonic = (m >= MACH_TRANSONIC_LO && m <= MACH_TRANSONIC_HI);
        uint16_t mfg = transonic ? TFT_YELLOW : TFT_DARK_GREEN;
        {
            String ms = buf; RowCache &mc = rowCache[SC][4];
            if (mc.value != ms || mc.fg != mfg) {
                printValue(tft, VF, ACFT_PANEL_X, y4, hw, h4,
                           "MA", ms, mfg, TFT_BLACK, COL_BACK, printState[SC][4]);
                mc.value = ms; mc.fg = mfg; mc.bg = TFT_BLACK;
            }
        }
        float g = state.gForce;
        snprintf(buf, sizeof(buf), "%.2f", g);
        fg = (g > G_ALARM_POS || g < G_ALARM_NEG) ? TFT_WHITE  :
             (g > G_WARN_POS  || g < G_WARN_NEG)  ? TFT_YELLOW : TFT_DARK_GREEN;
        bg = (g > G_ALARM_POS || g < G_ALARM_NEG) ? TFT_RED    : TFT_BLACK;
        {
            String gs = buf; RowCache &gc = rowCache[SC][5];
            if (gc.value != gs || gc.fg != fg || gc.bg != bg) {
                printValue(tft, VF, ACFT_PANEL_X + hw, y4, hw, h4,
                           "G", gs, fg, bg, COL_BACK, printState[SC][5]);
                gc.value = gs; gc.fg = fg; gc.bg = bg;
            }
        }
    }

    // Row 5 — AoA | Slip split
    {
        uint16_t y5 = rowYFor(5, ACFT_PANEL_NR), h5 = rowHFor(ACFT_PANEL_NR);

        // AoA (slot 6) — warn/alarm only on positive AoA (stall risk), matching the arc indicator
        float aoa = (state.surfaceVel > 0.5f) ? (state.pitch - state.srfVelPitch) : 0.0f;
        if (state.surfaceVel < 0.5f)          { fg = TFT_DARK_GREY; bg = TFT_BLACK; }
        else if (aoa >= AOA_ALARM_DEG)        { fg = TFT_WHITE;     bg = TFT_RED;   }
        else if (aoa >= AOA_WARN_DEG)         { fg = TFT_YELLOW;    bg = TFT_BLACK; }
        else                                  { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        snprintf(buf, sizeof(buf), "%+.0f\xB0", aoa);
        {
            String av = (state.surfaceVel < 0.5f) ? String("---") : String(buf);
            RowCache &ac = rowCache[SC][6];
            if (ac.value != av || ac.fg != fg || ac.bg != bg) {
                printValue(tft, VF, ACFT_PANEL_X, y5, hw, h5,
                           "AOA", av, fg, bg, COL_BACK, printState[SC][6]);
                ac.value = av; ac.fg = fg; ac.bg = bg;
            }
        }

        // Slip (slot 7), re-derived here so the panel is self-contained.
        float slip = (state.surfaceVel > 0.5f) ? eadiHdgDelta(state.heading, state.srfVelHeading) : 0.0f;
        float absSlip = fabsf(slip);
        if (state.surfaceVel < 0.5f)           { fg = TFT_DARK_GREY; bg = TFT_BLACK; }
        else if (absSlip >= SLIP_ALARM_DEG)    { fg = TFT_WHITE;     bg = TFT_RED;   }
        else if (absSlip >= SLIP_WARN_DEG)     { fg = TFT_YELLOW;    bg = TFT_BLACK; }
        else                                   { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        snprintf(buf, sizeof(buf), "%+.0f\xB0", slip);
        {
            String sv = (state.surfaceVel < 0.5f) ? String("---") : String(buf);
            RowCache &sc2 = rowCache[SC][7];
            if (sc2.value != sv || sc2.fg != fg || sc2.bg != bg) {
                printValue(tft, VF, ACFT_PANEL_X + hw, y5, hw, h5,
                           "SLIP", sv, fg, bg, COL_BACK, printState[SC][7]);
                sc2.value = sv; sc2.fg = fg; sc2.bg = bg;
            }
        }
    }

    // Row 6 — Gear | Airbrk split buttons.
    // Buttons tile on the raw row grid (no ROW_PAD) so they abut row 7 seamlessly:
    // row 6 spans [6*rowH .. 7*rowH] and row 7 spans [7*rowH .. SCREEN_H].
    {
        uint16_t y6 = TITLE_TOP + 6 * rowHFor(ACFT_PANEL_NR);
        uint16_t h6 = (TITLE_TOP + 7 * rowHFor(ACFT_PANEL_NR)) - y6 + 1;  // shares bottom border with row 7 top
        bool gearGroundState = (state.situation == sit_Landed  ||
                                state.situation == sit_Splashed ||
                                state.situation == sit_PreLaunch);
        // Gear (slot 8) — label always "GEAR", state expressed through colour
        {
            const char *gv = state.gear_on ? "DOWN" : "UP";  // cache key only
            uint16_t gfg, gbg;
            if (gearGroundState) {
                gfg = TFT_WHITE;
                gbg = state.gear_on ? TFT_DARK_GREEN : TFT_RED;
            } else if (state.gear_on) {
                gfg = TFT_WHITE;
                gbg = (state.surfaceVel > GEAR_MAX_SPEED_MS) ? TFT_YELLOW : TFT_DARK_GREEN;
            } else { gfg = TFT_DARK_GREY; gbg = TFT_OFF_BLACK; }
            RowCache &gc = rowCache[SC][8]; String gs = gv;
            if (gc.value != gs || gc.fg != gfg || gc.bg != gbg) {
                ButtonLabel btn = { "GEAR", gfg, gfg, gbg, gbg, TFT_GREY, TFT_GREY };
                drawButton(tft, ACFT_PANEL_X - 2, y6, hw + 2, h6, btn, &Roboto_Black_28, false);
                gc.value = gs; gc.fg = gfg; gc.bg = gbg;
            }
        }
        // Airbrake (slot 9) — Custom Action Group AIRBRAKE_CAG (base 38, Function Control B4;
        // see Documents/Developer/Module_UI_Reference.md). Cyan when deployed, grey when stowed.
        {
            uint16_t afg, abg;
            if (state.airbrake_on) { afg = TFT_DARK_GREY; abg = TFT_CYAN; }
            else                   { afg = TFT_DARK_GREY; abg = TFT_OFF_BLACK; }
            RowCache &ac = rowCache[SC][9]; String as = state.airbrake_on ? "OUT" : "IN";  // cache key
            if (ac.value != as || ac.fg != afg || ac.bg != abg) {
                ButtonLabel btn = { "AIRBRK", afg, afg, abg, abg, TFT_GREY, TFT_GREY };
                drawButton(tft, ACFT_PANEL_X + hw, y6, hw, h6, btn, &Roboto_Black_28, false);
                ac.value = as; ac.fg = afg; ac.bg = abg;
            }
        }
    }

    // Row 7 — Brakes | SAS buttons
    {
        uint16_t ry  = TITLE_TOP + 7 * rowHFor(ACFT_PANEL_NR);
        uint16_t rh  = SCREEN_H - ry - 1;   // bottom border on row 598 (599 is lost to overscan)
        uint16_t sasX = ACFT_PANEL_X + hw;
        uint16_t sasW = ACFT_PANEL_RIGHT - sasX;

        // Brakes (slot 10) — context-aware
        {
            bool gearGroundState = (state.situation == sit_Landed  ||
                                    state.situation == sit_Splashed ||
                                    state.situation == sit_PreLaunch);
            const char *bv = state.brakes_on ? "ON" : "OFF";
            uint16_t bfg, bbg;
            if (state.brakes_on)       { bfg = TFT_WHITE;     bbg = TFT_DARK_GREEN; }
            else if (gearGroundState)  { bfg = TFT_WHITE;     bbg = TFT_RED;        }
            else                       { bfg = TFT_DARK_GREY; bbg = TFT_OFF_BLACK;  }
            RowCache &bc = rowCache[SC][10]; String bs = bv;
            if (bc.value != bs || bc.fg != bfg || bc.bg != bbg) {
                ButtonLabel btn = { "BRAKES", bfg, bfg, bbg, bbg, TFT_GREY, TFT_GREY };
                drawButton(tft, ACFT_PANEL_X - 2, ry, hw + 2, rh, btn, &Roboto_Black_28, false);
                bc.value = bs; bc.fg = bfg; bc.bg = bbg;
            }
        }

        // SAS (slot 11) — SCFT generic colour scheme
        {
            const char *v; uint16_t sfg, sbg;
            sasNavballLabel(state.sasMode, v, sfg, sbg);
            RowCache &rc = rowCache[SC][11];
            if (rc.value != v || rc.fg != sfg || rc.bg != sbg) {
                ButtonLabel btn = { v, sfg, sfg, sbg, sbg, TFT_GREY, TFT_GREY };
                drawButton(tft, sasX, ry, sasW, rh, btn, &Roboto_Black_28, false);
                rc.value = v; rc.fg = sfg; rc.bg = sbg;
            }
        }
    }

    // Redraw horizontal dividers last — printValue fillRects erase them
    // Between V.Vrt(3)/Ma|G(4), Ma|G(4)/AoA|Slip(5), AoA|Slip(5)/Gear(6)
    static const uint8_t divRows[] = { 4, 5, 6 };
    for (uint8_t i = 0; i < 3; i++) {
        uint16_t dy = TITLE_TOP + divRows[i] * rowHFor(ACFT_PANEL_NR);
        tft.drawLine(ACFT_PANEL_X, dy,     ACFT_PANEL_RIGHT - 1, dy,     TFT_GREY);
        tft.drawLine(ACFT_PANEL_X, dy + 1, ACFT_PANEL_RIGHT - 1, dy + 1, TFT_GREY);
    }
    // Ma|G split divider (row 4)
    {
        uint16_t y4 = rowYFor(4, ACFT_PANEL_NR);
        tft.drawLine(ACFT_PANEL_X + hw,     y4, ACFT_PANEL_X + hw,     y4 + rowHFor(ACFT_PANEL_NR) - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, y4, ACFT_PANEL_X + hw + 1, y4 + rowHFor(ACFT_PANEL_NR) - 1, TFT_GREY);
    }
    // AoA|Slip split divider (row 5)
    {
        uint16_t y5 = rowYFor(5, ACFT_PANEL_NR);
        tft.drawLine(ACFT_PANEL_X + hw,     y5, ACFT_PANEL_X + hw,     y5 + rowHFor(ACFT_PANEL_NR) - 1, TFT_GREY);
        tft.drawLine(ACFT_PANEL_X + hw + 1, y5, ACFT_PANEL_X + hw + 1, y5 + rowHFor(ACFT_PANEL_NR) - 1, TFT_GREY);
    }
}



// "TRIM" annunciation (cyan) in the graphical area's bottom-right corner: right-aligned to
// the heading-tape right edge, bottom just above the heading-tape top. Redrawn each frame
// while trim is enabled; erased once when it clears.
// ── Altitude datum chip ───────────────────────────────────────────────────────────────
// SL or RDR, mirrored from TRIM. Same helper, colour rule and hit box as SPACECRAFT's
// velocity-reference chip -- see drawRefChip in AAA_Screens.ino.
static void _acftUpdateRefChip(KCM_TFT &tft) {
    const bool rdr  = _acftAltRef();
    const bool held = _acftAltRefOverride.manual;
    const int8_t want = (int8_t)((held ? 2 : 0) + (rdr ? 1 : 0));
    if (want == _acftChipShown) return;
    _acftChipShown = want;
    drawRefChip(tft, rdr ? "RDR" : "SL", held);
}

// Drawn on the edges only: the frame copy carries the flag between them.
static void _acftDrawTrim(KCM_TFT &tft) {
    if (state.trimEnabled == _acftTrimShown) return;
    int16_t tw = getFontStringWidth(&Roboto_Black_24, "TRIM");
    int16_t x  = (ACFT_HDG_TAPE_X + ACFT_HDG_TAPE_W) - tw - 8;
    int16_t y  = ACFT_HDG_TAPE_Y - (int16_t)Roboto_Black_24.cap_height - 2 - 8;
    if (state.trimEnabled) {
        tft.setFont(Roboto_Black_24);
        tft.setTextColor(TFT_CYAN, TFT_BLACK);
        tft.setCursor(x, y);
        tft.print("TRIM");
    } else {
        tft.fillRect(x - 2, y - 2, tw + 4, (int16_t)Roboto_Black_24.cap_height + 6, TFT_BLACK);
    }
    _acftTrimShown = state.trimEnabled;
}

static void drawScreen_ACFT(KCM_TFT &tft) {
    uint32_t _t0 = micros();

    bool mnvrActive = (state.mnvrTime > 0.0f);
    bool tgtAvail   = state.targetAvailable;

    // Attitude dirty — pitch/roll as before, plus heading (which now affects ball
    // because ADI markers project relative to it).
    bool ballDirty = _acftFullRedrawNeeded                                         ||
                     fabsf(state.pitch - _acftPrevPitch)                   >= 0.2f ||
                     fabsf(state.roll  - _acftPrevRoll)                    >= 0.2f ||
                     fabsf(eadiHdgDelta(state.heading, _acftPrevHeadingBall)) >= 0.5f;

    // Marker dirty — any visible marker's world position changed, or a marker's
    // availability toggled (target acquired/lost, maneuver set/cleared).
    if (!ballDirty) {
        ballDirty = fabsf(eadiHdgDelta(state.srfVelHeading, _acftPrevVelHdgBall)) >= 0.5f ||
                    fabsf(state.srfVelPitch - _acftPrevVelPitchBall)               >= 0.5f ||
                    mnvrActive != _acftPrevMnvrActiveBall                                  ||
                    tgtAvail   != _acftPrevTgtAvailBall;
    }
    if (!ballDirty && mnvrActive) {
        ballDirty = fabsf(eadiHdgDelta(state.mnvrHeading, _acftPrevMnvrHdgBall)) >= 0.5f ||
                    fabsf(state.mnvrPitch - _acftPrevMnvrPitchBall)               >= 0.5f;
    }
    if (!ballDirty && tgtAvail) {
        ballDirty = fabsf(eadiHdgDelta(state.tgtHeading, _acftPrevTgtHdgBall)) >= 0.5f ||
                    fabsf(state.tgtPitch - _acftPrevTgtPitchBall)               >= 0.5f;
    }

    if (ballDirty) {
        bool full = _acftFullRedrawNeeded;
        uint32_t t0 = micros();
        eadiDrawBall(tft, full, state.srfVelHeading, state.srfVelPitch, false);  // atmospheric: no orbital markers
        // Snapshot ball-dirty trackers for next frame's dirty check.
        _acftPrevPitch = state.pitch;
        _acftPrevRoll  = state.roll;
        _acftPrevHeadingBall    = state.heading;
        _acftPrevVelHdgBall     = state.srfVelHeading;
        _acftPrevVelPitchBall   = state.srfVelPitch;
        _acftPrevMnvrHdgBall    = state.mnvrHeading;
        _acftPrevMnvrPitchBall  = state.mnvrPitch;
        _acftPrevTgtHdgBall     = state.tgtHeading;
        _acftPrevTgtPitchBall   = state.tgtPitch;
        _acftPrevMnvrActiveBall = (state.mnvrTime > 0.0f);
        _acftPrevTgtAvailBall   = state.targetAvailable;
        _acftFullRedrawNeeded = false;
        if (debugMode) {
            uint32_t dt = micros() - t0;
            Serial.print(full ? "ACFT_FULL total=" : "ACFT_DELTA total=");
            Serial.print((float)dt / 1000.0f, 2);
            Serial.print("ms  pitch="); Serial.print(state.pitch, 1);
            Serial.print("  roll=");    Serial.println(state.roll, 1);
        }
    }

    // Compute AoA and slip — suppress below 0.5 m/s
    float aoa = 0.0f, slip = 0.0f;
    if (state.surfaceVel > 0.5f) {
        aoa  = state.pitch - state.srfVelPitch;
        slip = eadiHdgDelta(state.heading, state.srfVelHeading);
    }

    eadiUpdateRollIndicator(tft, state.roll);
    _acftUpdateRollReadout(tft, state.roll);
    _acftUpdatePitchTape(tft, state.pitch);
    _acftUpdateHeadingTape(tft, state.heading);
    _acftUpdateVSI(tft, state.verticalVel);
    _acftUpdateSlipBall(tft, slip);
    _acftUpdateAoAArc(tft, aoa);
    _acftUpdatePanel(tft);

    _acftUpdateRefChip(tft);
    _acftDrawTrim(tft);

    if (debugMode) {
        uint32_t _dt = micros() - _t0;
        Serial.print("ACFT frame=");
        Serial.print((float)_dt / 1000.0f, 2);
        Serial.print("ms  hdg=");  Serial.print(state.heading, 1);
        Serial.print("  vvrt=");   Serial.print(state.verticalVel, 1);
        Serial.print("  slip=");   Serial.print(slip, 2);
        Serial.print("  aoa=");    Serial.println(aoa, 2);
    }
}

/***************************************************************************************
   Screen_ACFT_AP.ino — Aircraft Autopilot console (chrome + draw + touch)

   Touch console for the hold-mode autopilot's aircraft modes, which run on
   Controller_Main. Renders the status echoed over I2C (state.hp*, the 48-byte
   aircraft frame) and lets the pilot engage / disengage modes, edit setpoints and
   tap LVL / A/P OFF. Design: Hold_Mode_Autopilot.md §4, Mission_Autopilot.md §6.

   LAYOUT (content 0..CONTENT_W, the shared console grid — ConsoleShared.ino):
     banner: <engaged modes | A/P OFF>  <reason>      body · vessel  <ENGAGED / A/P OFF>
     PITCH            | LATERAL / THRUST   | FLIGHT DATA
     [ATT] [setpoint] | [ROLL] [setpoint]  | PITCH  live
     [AOA] [setpoint] | [HDG]  [setpoint]  | ROLL   live
     [V/S] [setpoint] | [NAV]  BRG xxx°    | HDG    live
     [ALT] [setpoint] | [IAS]  [setpoint]  | V/S    live
     [GS]  [setpoint] | [MACH] [setpoint]  | ALT    live
     [LVL] [A/P OFF]  | hint, legend       | DIST   live (target)
                      |                    | TGT EL live (elevation to target)

   NAV and GS fly an approach to the targeted flag: NAV banks to its bearing, GS holds
   the depression angle to it. Both need a target. Mode buttons are three-state (off /
   pending / engaged); tapping a mode engages it and the master captures the current
   value as the setpoint. Commanded throttle is deliberately not shown: while the
   autothrottle is engaged the physical lever IS the throttle readout.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

static const uint16_t HA_LBL = KDC_LABEL_COLOR;
static const uint16_t HA_VAL = TFT_DARK_GREEN;
static const uint16_t HA_EDT = TFT_SKY;
#define HA_F_LBL  (&Roboto_Black_24)
#define HA_F_BANN (&Roboto_Black_36)

// group: 0 pitch, 1 lateral, 2 thrust. modeVal: the value the group's mode byte takes
// when this mode is engaged (HpPitchMode / HpLatMode / HpThrMode on the master).
struct HaMode {
  int16_t     x;
  uint8_t     row;
  const char *label;
  uint8_t     engageOp, setOp;     // setOp 0 = no setpoint box to edit
  const char *name;
  const char *units;
  float       mn, mx;
  bool        sign;
  uint8_t     dec;
  uint8_t     group, modeVal;
};
static const uint8_t HA_MODES = 10;
static const HaMode HA[HA_MODES] = {
  { CON_C1X, 0, "ATT",  HP_CMD_ENGAGE_ATT,  HP_CMD_SET_ATT,  "PITCH ATTITUDE",     "\xB0",  -45.0f,   45.0f, true,  1, 0, 1 },
  { CON_C1X, 1, "AOA",  HP_CMD_ENGAGE_AOA,  HP_CMD_SET_AOA,  "ANGLE OF ATTACK",    "\xB0",  -10.0f,   25.0f, true,  1, 0, 2 },
  { CON_C1X, 2, "V/S",  HP_CMD_ENGAGE_VS,   HP_CMD_SET_VS,   "VERTICAL SPEED",     "m/s",  -100.0f,  100.0f, true,  0, 0, 3 },
  { CON_C1X, 3, "ALT",  HP_CMD_ENGAGE_ALT,  HP_CMD_SET_ALT,  "ALTITUDE (ASL)",     "m",       0.0f, 70000.0f, false, 0, 0, 4 },
  { CON_C1X, 4, "GS",   HP_CMD_ENGAGE_GS,   HP_CMD_SET_GS,   "GLIDE SLOPE",        "\xB0",    1.0f,   10.0f, false, 1, 0, 5 },
  { CON_C2X, 0, "ROLL", HP_CMD_ENGAGE_ROLL, HP_CMD_SET_ROLL, "BANK ANGLE",         "\xB0",  -60.0f,   60.0f, true,  1, 1, 1 },
  { CON_C2X, 1, "HDG",  HP_CMD_ENGAGE_HDG,  HP_CMD_SET_HDG,  "HEADING",            "\xB0",    0.0f,  359.9f, false, 0, 1, 2 },
  { CON_C2X, 2, "NAV",  HP_CMD_ENGAGE_NAV,  0,               "",                   "",        0.0f,    0.0f, false, 0, 1, 3 },
  { CON_C2X, 3, "IAS",  HP_CMD_ENGAGE_IAS,  HP_CMD_SET_IAS,  "INDICATED AIRSPEED", "m/s",    20.0f, 1500.0f, false, 0, 2, 1 },
  { CON_C2X, 4, "MACH", HP_CMD_ENGAGE_MACH, HP_CMD_SET_MACH, "MACH NUMBER",        "",        0.10f,    6.0f, false, 2, 2, 2 },
};

// Row-cache slots (ROW_COUNT = 32)
static const uint8_t HA_SLOT_BTN  = 0;    // 0..9   mode buttons
static const uint8_t HA_SLOT_VAL  = 10;   // 10..19 setpoint boxes
static const uint8_t HA_SLOT_DATA = 20;   // 20..26 flight data
static const uint8_t HA_SLOT_BANN = 27;

// LVL / A/P OFF sit under the pitch column (both columns take five rows).
static const int16_t HA_BIG_W = 145;
static const int16_t HA_BIG_Y = CON_BIG_Y + 4;
static const int16_t HA_BIG_H = CON_BIG_H - 4;
static const int16_t HA_LVL_X = CON_C1X;
static const int16_t HA_OFF_X = CON_C1X + 153;

static const uint32_t HA_PENDING_TIMEOUT_MS = 3000;      // a refused engage is never echoed

static int8_t   haPend[HA_MODES];        // -1 none, 0 disengage sent, 1 engage sent
static uint32_t haPendMs[HA_MODES];
static bool     haDirty[HA_MODES];       // setpoint edit awaiting echo
static float    haPendVal[HA_MODES];
static bool     haScreenRefresh = false;

static uint8_t haGroupMode(uint8_t group) {
  return group == 0 ? state.hpPitchMode : group == 1 ? state.hpLatMode : state.hpThrMode;
}
static bool haEngaged(uint8_t i)   { return haGroupMode(HA[i].group) == HA[i].modeVal; }
static bool haCommanded(uint8_t i) { return haPend[i] >= 0 ? (haPend[i] == 1) : haEngaged(i); }

static float haEcho(uint8_t i) {
  switch (i) {
    case 0: return state.hpAtt;  case 1: return state.hpAoa;  case 2: return state.hpVs;   case 3: return state.hpAlt;
    case 4: return state.hpGs;   case 5: return state.hpRoll; case 6: return state.hpHdg;
    case 8: return state.hpIas;  case 9: return state.hpMach; default: return 0.0f;
  }
}
static float haTol(uint8_t i) {
  switch (i) { case 2: case 8: return 0.1f; case 3: return 0.5f; case 9: return 0.005f; default: return 0.05f; }
}
static float haShown(uint8_t i) { return haDirty[i] ? haPendVal[i] : haEcho(i); }

// Any autopilot flying the vehicle, as the master reports it: drives the sidebar key colour.
bool hpAnyEngagedAnnunciated() {
  return (state.hpFlags & 0x01) != 0 || (state.rvFlags & 0x47) != 0 ||
         (state.obFlags & 0x43) != 0 || (state.ldFlags & 0x01) != 0;
}

const char *hpReasonLabel(uint8_t r) {
  switch (r) {
    case HP_REASON_STICK: return "STICK";  case HP_REASON_LEVER: return "A/T OFF: LEVER";
    case HP_REASON_BRAKES: return "BRAKES"; case HP_REASON_AIRBORNE: return "AIRBORNE";
    case HP_REASON_ROLL_LIMIT: return "ROLL LIMIT"; case HP_REASON_NO_ATMO: return "NO ATMO";
    case HP_REASON_TELEMETRY: return "TELEMETRY"; case HP_REASON_ASCENT: return "ASCENT ARMED";
    case HP_REASON_REFUSED: return "REFUSED";
    case HP_REASON_NO_NODE: return "NO NODE"; case HP_REASON_NO_TARGET: return "NO TARGET";
    case HP_REASON_SOI: return "SOI CHANGE"; case HP_REASON_FUEL: return "FUEL";
    case HP_REASON_LANDED: return "LANDED"; case HP_REASON_OTHER_AP: return "OTHER AP";
    case HP_REASON_FLARE: return "FLARE"; case HP_REASON_ARRIVED: return "ARRIVED";
    case HP_REASON_ALIGN: return "ALIGN"; case HP_REASON_HANDOFF: return "HANDOFF";
    case HP_REASON_REPLAN: return "REPLANNED"; default: return "";
  }
}

// Retire pending cues once the master's echo agrees. Called each loop from
// updateI2CState() for every hold-mode console.
static void haReconcile() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < HA_MODES; i++) {
    if (haPend[i] >= 0) {
      if (haEngaged(i) == (haPend[i] == 1)) haPend[i] = -1;
      else if (now - haPendMs[i] > HA_PENDING_TIMEOUT_MS) haPend[i] = -1;   // refused / lost
    }
    if (haDirty[i] && fabsf(haEcho(i) - haPendVal[i]) < haTol(i)) haDirty[i] = false;
  }
}
static void rvReconcile();   // Screen_ROVR_AP.ino
static void obReconcile();   // Screen_ORBT_AP.ino
static void ldReconcile();   // Screen_LNDG_AP.ino
void hpReconcilePending() { haReconcile(); rvReconcile(); obReconcile(); ldReconcile(); }

static void haFmtSetpoint(uint8_t i, float v, char *buf, size_t n) {
  switch (i) {
    case 0: case 1: case 5: snprintf(buf, n, "%+.1f\xB0", v); break;
    case 2: snprintf(buf, n, "%+.0f m/s", v); break;
    case 3: formatAltBuf(v, buf, n); break;
    case 4: snprintf(buf, n, "%.1f\xB0", v); break;
    case 6: { int16_t h = (int16_t)roundf(v) % 360; if (h < 0) h += 360; snprintf(buf, n, "%03d\xB0", h); break; }
    case 8: snprintf(buf, n, "%.0f m/s", v); break;
    default: snprintf(buf, n, "%.2f", v); break;
  }
}

// ── Chrome ───────────────────────────────────────────────────────────────────────────
void chromeScreen_ACFTAP(KCM_TFT &tft) {
  kpForceClose();
  conDrawColumns(tft, "PITCH", "LATERAL / THRUST", "FLIGHT DATA");
  for (uint8_t i = 0; i < HA_MODES; i++) conDrawValueBox(tft, HA[i].x, HA[i].row);
  static const char *const DATA_LBL[7] = { "PITCH", "ROLL", "HDG", "V/S", "ALT", "DIST", "TGT EL" };
  for (uint8_t r = 0; r < 7; r++)
    textLeft(tft, HA_F_LBL, CON_C3X + 4, conRowY(r), CON_COLW - CON_VALW, CON_ROW_H, DATA_LBL[r], HA_LBL, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C2X + 4, conRowY(5) + 8,  CON_COLW - 8, 20, "NAV flies to the targeted flag; GS holds", TFT_DARK_GREY, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C2X + 4, conRowY(5) + 28, CON_COLW - 8, 20, "the depression angle to it.", TFT_DARK_GREY, TFT_BLACK);
  int16_t ly = conRowY(6) + 12, lx = CON_C2X + 2;
  tft.drawRect(lx, ly, 92, 28, TFT_GREY);             textCenter(tft, &Roboto_Black_16, lx, ly, 92, 28, "OFF", TFT_WHITE, TFT_BLACK);
  tft.drawRect(lx + 100, ly, 92, 28, TFT_CYAN);       textCenter(tft, &Roboto_Black_16, lx + 100, ly, 92, 28, "PENDING", TFT_CYAN, TFT_BLACK);
  tft.fillRect(lx + 200, ly, 92, 28, TFT_DARK_GREEN); textCenter(tft, &Roboto_Black_16, lx + 200, ly, 92, 28, "ENGAGED", TFT_WHITE, TFT_DARK_GREEN);
  { ButtonLabel b = { "LVL", TFT_WHITE, TFT_WHITE, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
    drawButton(tft, HA_LVL_X, HA_BIG_Y, HA_BIG_W, HA_BIG_H, b, &Roboto_Black_28, false);
    textCenter(tft, &Roboto_Black_16, HA_LVL_X, HA_BIG_Y + HA_BIG_H - 26, HA_BIG_W, 18, "wings level, V/S 0", TFT_GREY, TFT_OFF_BLACK); }
  { ButtonLabel b = { "A/P OFF", TFT_WHITE, TFT_WHITE, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
    drawButton(tft, HA_OFF_X, HA_BIG_Y, HA_BIG_W, HA_BIG_H, b, &Roboto_Black_28, false);
    textCenter(tft, &Roboto_Black_16, HA_OFF_X, HA_BIG_Y + HA_BIG_H - 26, HA_BIG_W, 18, "disconnect all", TFT_GREY, TFT_OFF_BLACK); }
}

// ── Draw ─────────────────────────────────────────────────────────────────────────────
void drawScreen_ACFTAP(KCM_TFT &tft) {
  if (kpTakeClosed()) haScreenRefresh = true;
  if (haScreenRefresh) {
    tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
    chromeScreen_ACFTAP(tft);
    invalidateRowCache(screen_ACFTAP);
    haScreenRefresh = false;
  }
  if (kpIsOpen()) { kpDraw(tft); return; }

  char buf[48];
  bool anyPending = false;
  for (uint8_t i = 0; i < HA_MODES; i++) if (haPend[i] >= 0) anyPending = true;

  // Banner
  {
    char modes[48] = "";
    for (uint8_t i = 0; i < HA_MODES; i++)
      if (haEngaged(i)) { if (modes[0]) strlcat(modes, "  ", sizeof(modes)); strlcat(modes, HA[i].label, sizeof(modes)); }
    bool engaged = modes[0] != '\0';
    bool showReason = (state.hpReason != HP_REASON_NONE && state.hpReasonAge <= 5);
    const char *reason = showReason ? hpReasonLabel(state.hpReason)
                       : ((state.hpFlags & 0x02) && !(state.hpFlags & 0x08)) ? "LEVER OFF" : "";
    uint16_t reasonCol = showReason ? TFT_ORANGE : TFT_GREY;
    char key[112];
    snprintf(key, sizeof(key), "%s|%s|%s|%d|%s", engaged ? modes : "A/P OFF", reason, state.gameSOI.c_str(), anyPending, state.vesselName.c_str());
    RowCache &rc = rowCache[screen_ACFTAP][HA_SLOT_BANN];
    if (rc.value != key) {
      tft.fillRect(0, CON_BANNER_Y, CONTENT_W, CON_BANNER_H, TFT_BLACK);
      textLeft(tft, HA_F_BANN, 8, CON_BANNER_Y, 316, CON_BANNER_H, engaged ? modes : "A/P OFF",
               engaged ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
      if (reason[0]) textLeft(tft, &Roboto_Black_24, 330, CON_BANNER_Y, 300, CON_BANNER_H, reason, reasonCol, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s \xB7 %s", state.gameSOI.c_str(), state.vesselName.c_str());
      textRight(tft, &Roboto_Black_20, 648, CON_BANNER_Y + 4,  CONTENT_W - 648 - 6, 24, buf, HA_LBL, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s%s", engaged ? "ENGAGED" : "A/P OFF", anyPending ? "..." : "");
      textRight(tft, &Roboto_Black_28, 648, CON_BANNER_Y + 30, CONTENT_W - 648 - 6, 30, buf,
                engaged ? TFT_NEON_GREEN : TFT_DARK_GREY, TFT_BLACK);
      rc.value = key;
    }
  }

  // Mode buttons + setpoints
  for (uint8_t i = 0; i < HA_MODES; i++) {
    ConBtnState st = haEngaged(i) ? CON_BTN_ON : (haPend[i] >= 0 ? CON_BTN_PENDING : CON_BTN_OFF);
    RowCache &rc = rowCache[screen_ACFTAP][HA_SLOT_BTN + i];
    char k[4]; snprintf(k, sizeof(k), "%d", (int)st);
    if (rc.value != k) {
      conDrawModeButton(tft, HA[i].x + 2, conRowY(HA[i].row) + 4, CON_BTN_W, CON_VALH, HA[i].label, st);
      rc.value = k;
    }
    uint16_t fg;
    if (HA[i].setOp == 0) {   // NAV: the box shows the live target bearing
      if (state.targetAvailable) { int16_t h = (int16_t)roundf(state.tgtHeading) % 360; if (h < 0) h += 360; snprintf(buf, sizeof(buf), "BRG %03d\xB0", h); }
      else                       snprintf(buf, sizeof(buf), "NO TGT");
      fg = haEngaged(i) ? HA_VAL : TFT_DARK_GREY;
    } else {
      haFmtSetpoint(i, haShown(i), buf, sizeof(buf));
      fg = haDirty[i] ? HA_EDT : (haEngaged(i) ? HA_VAL : TFT_DARK_GREY);
    }
    conPut(tft, screen_ACFTAP, HA_SLOT_VAL + i, conValX(HA[i].x) + 6, conRowY(HA[i].row) + 4, CON_VALW - 10, CON_VALH, buf, fg);
  }

  // Flight data
  int16_t dx = conValX(CON_C3X) + 6, dw = CON_VALW - 10;
  snprintf(buf, sizeof(buf), "%+.1f\xB0", state.pitch);        conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 0, dx, conRowY(0) + 4, dw, CON_VALH, buf, HA_VAL);
  snprintf(buf, sizeof(buf), "%+.1f\xB0", state.roll);         conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 1, dx, conRowY(1) + 4, dw, CON_VALH, buf, HA_VAL);
  { int16_t h = (int16_t)roundf(state.heading) % 360; if (h < 0) h += 360;
    snprintf(buf, sizeof(buf), "%03d\xB0", h);                  conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 2, dx, conRowY(2) + 4, dw, CON_VALH, buf, HA_VAL); }
  snprintf(buf, sizeof(buf), "%+.1f m/s", state.verticalVel);  conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 3, dx, conRowY(3) + 4, dw, CON_VALH, buf, HA_VAL);
  formatAltBuf(state.altitude, buf, sizeof(buf));              conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 4, dx, conRowY(4) + 4, dw, CON_VALH, buf, HA_VAL);
  if (state.targetAvailable) formatAltBuf(state.tgtDistance, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 5, dx, conRowY(5) + 4, dw, CON_VALH, buf, state.targetAvailable ? HA_VAL : TFT_DARK_GREY);
  if (state.targetAvailable) snprintf(buf, sizeof(buf), "%+.1f\xB0", state.tgtPitch); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ACFTAP, HA_SLOT_DATA + 6, dx, conRowY(6) + 4, dw, CON_VALH, buf, state.targetAvailable ? HA_VAL : TFT_DARK_GREY);
}

// ── Keypad commit ────────────────────────────────────────────────────────────────────
static void haKeypadCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx < 0 || idx >= HA_MODES || HA[idx].setOp == 0) return;
  haPendVal[idx] = v;
  haDirty[idx] = apEnqueueCmd(HA[idx].setOp, v);   // cue only for a command that went out
}

// ── Touch ────────────────────────────────────────────────────────────────────────────
void acftApScreenTouch(uint16_t x, uint16_t y) {
  if (kpIsOpen()) { kpTouch(x, y); return; }
  uint32_t now = millis();

  if (y >= HA_BIG_Y && y < HA_BIG_Y + HA_BIG_H) {
    if (x >= HA_LVL_X && x < HA_LVL_X + HA_BIG_W) {
      if (apEnqueueCmd(HP_CMD_LVL, 0.0f)) {
        haPend[5] = 1; haPendMs[5] = now;   // ROLL
        haPend[2] = 1; haPendMs[2] = now;   // V/S
      }
      return;
    }
    if (x >= HA_OFF_X && x < HA_OFF_X + HA_BIG_W) {
      if (apEnqueueCmd(HP_CMD_AP_OFF, 0.0f))
        for (uint8_t i = 0; i < HA_MODES; i++) if (haEngaged(i)) { haPend[i] = 0; haPendMs[i] = now; }
      return;
    }
  }

  for (uint8_t i = 0; i < HA_MODES; i++) {
    int16_t cy = conRowY(HA[i].row);
    if (y < cy || y >= cy + CON_ROW_H) continue;
    if (x >= HA[i].x + 2 && x < HA[i].x + 2 + CON_BTN_W) {
      bool want = !haCommanded(i);
      if (apEnqueueCmd(HA[i].engageOp, want ? 1.0f : 0.0f)) { haPend[i] = want ? 1 : 0; haPendMs[i] = now; }
      return;
    }
    if (HA[i].setOp != 0 && x >= conValX(HA[i].x) && x < conValX(HA[i].x) + CON_VALW) {
      KpField f = { HA[i].name, HA[i].units, HA[i].mn, HA[i].mx, false, HA[i].sign, HA[i].dec };
      kpOpen(f, (int8_t)i, haKeypadCommit);
      return;
    }
  }
}

/***************************************************************************************
   Screen_DOCK.ino  —  Docking screen: graphical approach reticle + critical numbers

   LAYOUT (1024×600, content area 940×538 below title bar; reticle R=210)
   ┌────────────────────────────────┬──────────────────────────────────────┐
   │                                │ DIST:         247 m                  │
   │   Approach Reticle             │ T+DOCK:       3:42                   │
   │   (black disc, R=210)          │ V.CLOSE:    -1.4 m/s                 │
   │                                │ V.LAT:      0.24 m/s                 │
   │   ● velocity vector (green)    │ BRG:    +2°  │ ELV:    -1°           │
   │   ◆ target port (magenta)      │ V.BRG:  +1°  │ V.ELV:  -0°           │
   │   + fixed crosshair (grey)     │ NOS.OFF:      2.3°                   │
   │                                │ [RCS]        [SAS: TARGET]           │
   └────────────────────────────────┴──────────────────────────────────────┘

   RETICLE SEMANTICS
   ─────────────────
   Fixed crosshair  = your nose direction (always at centre)
   Green dot (VEL)  = the direction of the RELATIVE velocity between your craft and the
                      target port, drawn relative to your nose
                      At centre → you are translating straight along the boresight
   Magenta dot (PORT) = where the port is relative to your nose
                      At centre → your nose is pointing at the port (aligned)
   Perfect approach = both dots at centre simultaneously

   A marker DIMMED to half brightness is pinned at the scope boundary: it is further off
   the nose than the outer ring can show, so its direction is still honest but its
   distance understates the real angle. Nos.Off carries the true value.

   FLYING THE VELOCITY MARKER
   ──────────────────────────
   The marker layer is referenced to the craft's BODY axes, so screen up/right is always
   the craft's up/right — the same axes as the RCS translation keys. A marker's distance
   from the crosshair is its TRUE angular offset from the nose at any attitude, so the
   ring labels mean what they say.
   An RCS translation pulls the relative velocity toward the direction you thrust, so the
   marker moves the way you thrust:

       marker up + right of the crosshair  →  thrust LEFT and DOWN to centre it
       marker down + left of the crosshair →  thrust RIGHT and UP to centre it

   Kill lateral drift by walking the green marker onto the crosshair; put the green
   marker ON the magenta PORT marker to fly straight down the approach axis (that gap is
   what V.Brg / V.Elv read out in degrees). Both frames are one and the same when the
   nose is already on the port.

   PANEL: 360 px wide at x=580, NR=8 rows of 67 px, labels Black_28, values Black_36
   Row 0: Dist            Row 1: T+Dock
   Row 2: V.Close         Row 3: V.Lat
   Row 4: Brg | Elv split — the port relative to the nose (informational)
   Row 5: V.Brg | V.Elv split — approach-path error, colour-banded, "---" past 90°
   Row 6: Nos.Off — total nose offset from the port, colour-banded
   Row 7: RCS | SAS buttons (to screen bottom)
   Rows 4 and 5 mirror TGT exactly, so the same four angles read the same way on both
   screens. The split cells cannot hold a decimal, so both pairs are whole degrees;
   V.Lat (m/s, two decimals) is the precision instrument at docking range.

   RETICLE GEOMETRY (rev-2, 1024×600)
   ──────────────────────────────────
   Centre: (289, 300)  Radius: 210px  Scale: 10.5 px/deg (±20° full scale)
   Rings: ±5° r=52, ±10° r=105, ±15° r=157, ±20° r=210. Centred in the left
   region x=[0,578]; approach bar centred under it.
   Right panel: 360 px at x=580 (matches ascent/MNVR), labels 28 / values 36

   DOT UPDATE STRATEGY
   ────────────────────
   prevDot stored in screen coords. On change > 1px:
     fillRect(prev - R_ERASE, prev - R_ERASE, 2*R_ERASE+1, 2*R_ERASE+1, TFT_BLACK)
     fillCircle(new, R_DOT, colour)
   Erase radius slightly larger than draw radius to clean up anti-alias edge.
   Background of reticle is always solid black — safe to fillRect-erase.

   THREE STATES
   ─────────────
   DOCKED:      "DOCKED" splash (handled by state machine, unchanged)
   NO TARGET:   "NO TARGET SET" splash (unchanged)
   APPROACH:    Graphical reticle + right panel numbers
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

static const uint8_t DOCK_SC = (uint8_t)screen_DOCK;   // row-cache / print-state index


// ── State flags (extern linkage matches KCMk1_InfoDisp.h declarations) ───────────────
bool     _dockChromDrawn  = false;
bool     _vesselDocked    = false;
uint32_t _dockedTimestamp = 0;


// ── Reticle geometry — centred and stretched to fill the left region (matches MNVR) ──
// The readout panel now sits on the far right (x=580), leaving x=[0,578] for the
// reticle. It is centred there, enlarged, and the approach bar is centred below.
static const uint16_t RET_CX   = RETICLE_CX;   // centre of the left region x=[0,578]
static const uint16_t RET_CY   = RETICLE_CY;
static const uint16_t RET_R    = RETICLE_R;    // reticle radius (px)
static const float    RET_SCALE = (float)RET_R / 20.0f;  // 10.5 px/deg — ±20° full scale

// Ring radii for ±5°, ±10°, ±15°, ±20°
static const uint16_t RING_5  = RET_R / 4;         // 52
static const uint16_t RING_10 = RET_R / 2;         // 105
static const uint16_t RING_15 = (RET_R * 3) / 4;   // 157
static const uint16_t RING_20 = RET_R;             // 210 — ±20° boundary

// Dot display sizes — scaled up with the larger reticle
static const uint8_t DOT_R_PORT  = 22;   // target port marker radius
static const uint8_t DOT_R_VEL   = 19;   // velocity vector marker radius
static const uint8_t DOT_R_ERASE = 33;   // erase rect half-size (covers prograde ring 19 + spoke 12)

// Right panel geometry — matches the ascent/circ readout panel (360 px wide,
// right-aligned to the content edge, labels Black_28, values Black_36).
static const uint16_t RP_W   = RETICLE_RP_W;
static const uint16_t RP_X   = CONTENT_W - RP_W;              // 580
static const uint8_t  RP_NR  = 8;       // number of rows
static const tFont   *RP_LBL = &Roboto_Black_28;  // label font (chrome)
static const tFont   *RP_F   = &Roboto_Black_36;  // value font

// Approach bar geometry — centred under the reticle
static const uint16_t BAR_W  = RETICLE_BAR_W;
static const uint16_t BAR_X  = RET_CX - BAR_W / 2;   // 64
static const uint16_t BAR_H  = 26;
static const float    BAR_MAX_DIST = 250.0f;   // full bar = 250m (docking approach range)


// ── Shared dot-layer geometry + per-screen erase cache ───────────────────────────────
// The moving marker layer is shared with MNVR/TGT (reticleUpdateDots, KerbalDisplayCommon).
// Only the angular SCALE and the four ring labels differ; both are captured here. Built
// from the existing named constants above so values never diverge from the chrome/bar.
static const char *const DOCK_RING_LBL[4] = { "5", "10", "15", "20" };
// Body-referenced, like every other boresight display in the project: screen up/right
// always means the craft's up/right, so the RCS translation keys move the markers the
// way the pilot expects at any roll attitude.
static const ReticleGeom DOCK_GEOM = {
    (int16_t)RET_CX, (int16_t)RET_CY, (int16_t)RET_R, RET_SCALE,
    DOT_R_PORT, DOT_R_VEL, DOT_R_ERASE,
    DOT_R_VEL * 3 / 2 + 2,          // clampMargin — widest symbol is the prograde ring + spoke
    DOCK_RING_LBL, &Roboto_Black_16
};
// Per-screen erase-before-redraw cache (9999 = marker not shown). Reset on entry.
static ReticleDotCache _dockDots;
static float   _dockPrevDist  = -999.0f;   // dist-bar dedup; reset in chrome on re-entry


// ── Draw the static reticle chrome ───────────────────────────────────────────────────
static void _dockDrawReticleChrome(KCM_TFT &tft) {
    // Shared disc + rings + cardinals + crosshair + ticks + bezel (MNVR/DOCK gap 18, tick 14)
    reticleDrawBase(tft, RET_CX, RET_CY, RET_R, 18, 14);

    // Ring degree labels (positioned just inside each ring, in the NE quadrant).
    // Single-arg setTextColor = transparent background.
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_LIGHT_GREY);
    tft.setCursor(RET_CX + 3, RET_CY - RING_5  + 3);  tft.print("5");
    tft.setCursor(RET_CX + 3, RET_CY - RING_10 + 3);  tft.print("10");
    tft.setCursor(RET_CX + 3, RET_CY - RING_15 + 3);  tft.print("15");
    tft.setCursor(RET_CX + 3, RET_CY - RING_20 + 3);  tft.print("20");

    // Legend: 3 rows stacked in top-left corner, above/beside the circle top
    // y=68,88,108 — all safely left of circle edge at those y positions
    static const uint16_t LEG_X  = 6;
    static const uint16_t LEG_Y0 = TITLE_TOP + 6;  // 68
    static const uint16_t LEG_DY = 20;              // row spacing

    tft.setFont(Roboto_Black_16);

    // Row 0: VEL — green prograde marker (target-RELATIVE velocity; the PFD ball
    //         uses the same glyph for orbital/surface velocity — context tells
    //         them apart, the legend names this one)
    drawProgradeMarker(tft, LEG_X + 6, LEG_Y0 + 6, 5, TFT_NEON_GREEN);
    tft.setTextColor(TFT_SAP_GREEN, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0);
    tft.print("VEL");

    // Row 1: PORT — magenta target marker
    drawTargetMarker(tft, LEG_X + 6, LEG_Y0 + LEG_DY + 7, 6, TFT_VIOLET);
    tft.setTextColor(TFT_VIOLET, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0 + LEG_DY);
    tft.print("PORT");

    // Row 2: NOSE — crosshair symbol
    tft.drawLine(LEG_X+1,  LEG_Y0+LEG_DY*2+6, LEG_X+4,  LEG_Y0+LEG_DY*2+6, TFT_GREY);
    tft.drawLine(LEG_X+8,  LEG_Y0+LEG_DY*2+6, LEG_X+11, LEG_Y0+LEG_DY*2+6, TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+LEG_DY*2+1, LEG_X+6,  LEG_Y0+LEG_DY*2+4, TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+LEG_DY*2+8, LEG_X+6,  LEG_Y0+LEG_DY*2+11,TFT_GREY);
    tft.fillCircle(LEG_X+6, LEG_Y0+LEG_DY*2+6, 1, TFT_GREY);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0 + LEG_DY * 2);
    tft.print("NOSE");

    // Bottom-left: APPROACH bar (90% width, centred, with label row above).
    // Bar label/value font matches LNCH_Circ ΔV Burn bar and MNVR ΔV Burn bar
    // (Black_24); the label row sits between the reticle bottom and the bar.
    uint16_t barY = RET_CY + RET_R + 42;   // 552 — bar top
    uint16_t lblY = barY - 34;              // 518 — label row above bar
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(BAR_X, lblY);
    tft.print("APPROACH");
    tft.drawRect(BAR_X, barY, BAR_W, BAR_H, TFT_GREY);
}


// ── Draw right-panel chrome (static labels) ───────────────────────────────────────────
static void _dockDrawRightChrome(KCM_TFT &tft) {
    // Rows 0–1: range and time
    printDispChrome(tft, RP_LBL, RP_X, rowYFor(0,RP_NR), RP_W, rowHFor(RP_NR), "DIST",    COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, RP_LBL, RP_X, rowYFor(1,RP_NR), RP_W, rowHFor(RP_NR), "T+DOCK",  COL_LABEL, COL_BACK, COL_NO_BDR);

    // Divider between T+Dock(1) and V.Close(2)
    { uint16_t dy = rowYFor(2,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }

    // Rows 2–3: speed
    printDispChrome(tft, RP_LBL, RP_X, rowYFor(2,RP_NR), RP_W, rowHFor(RP_NR), "V.CLOSE", COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, RP_LBL, RP_X, rowYFor(3,RP_NR), RP_W, rowHFor(RP_NR), "V.LAT",   COL_LABEL, COL_BACK, COL_NO_BDR);

    // Divider between V.Lat(3) and Brg|Elv(4)
    { uint16_t dy = rowYFor(4,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }

    // Rows 4–5: the same two split pairs TGT carries — where the port is relative to the
    // nose, then where the velocity is relative to the approach axis.
    {
        uint16_t hw = RP_W / 2, h = rowHFor(RP_NR);

        // Row 4: Brg | Elv — the port relative to the nose (informational, like TGT).
        uint16_t y4 = rowYFor(4, RP_NR);
        printDispChrome(tft, RP_LBL, RP_X,      y4, hw - ROW_PAD, h, "BRG", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, RP_LBL, RP_X + hw, y4, hw - ROW_PAD, h, "ELV", COL_LABEL, COL_BACK, COL_NO_BDR);
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(RP_X + hw + dx, y4, RP_X + hw + dx, y4 + h - 1, TFT_GREY);

        // Row 5: V.Brg | V.Elv — approach-path error about the target axis.
        uint16_t y5 = rowYFor(5, RP_NR);
        printDispChrome(tft, RP_LBL, RP_X,      y5, hw - ROW_PAD, h, "V.BRG", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, RP_LBL, RP_X + hw, y5, hw - ROW_PAD, h, "V.ELV", COL_LABEL, COL_BACK, COL_NO_BDR);
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(RP_X + hw + dx, y5, RP_X + hw + dx, y5 + h - 1, TFT_GREY);
    }

    // Divider between V.Brg|V.Elv(5) and Nos.Off(6)
    { uint16_t dy = rowYFor(6,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }

    // Row 6: nose total angular offset from port (combined bearing + elevation)
    printDispChrome(tft, RP_LBL, RP_X, rowYFor(6,RP_NR), RP_W, rowHFor(RP_NR), "NOS.OFF", COL_LABEL, COL_BACK, COL_NO_BDR);

    // Divider before RCS/SAS button row (row 7)
    { uint16_t dy = rowYFor(7, RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X + RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X + RP_W, dy+1, TFT_GREY); }

    // Row 7: RCS | SAS split divider (buttons drawn in update function)
    uint16_t hw = RP_W / 2;
    tft.drawLine(RP_X + hw,     TITLE_TOP + 7 * rowHFor(RP_NR), RP_X + hw,     SCREEN_H - 1, TFT_GREY);
    tft.drawLine(RP_X + hw + 1, TITLE_TOP + 7 * rowHFor(RP_NR), RP_X + hw + 1, SCREEN_H - 1, TFT_GREY);
}


// Dot-layer machinery (project / clamp / erase / chrome-repair / update) lives in
// KerbalDisplayCommon ≥ 3.2.0 and is shared with MNVR and TGT. DOCK drives it via
// DOCK_GEOM (scale = r/20, ring labels 5/10/15/20) and _dockDots, with the angle
// block called body-referenced.


static void _dockDrawDistBar(KCM_TFT &tft, float dist) {
    // barY must match what _dockDrawReticleChrome drew (Black_24 label).
    static const uint16_t barY = RET_CY + RET_R + 42;  // 552
    static const uint16_t lblY = barY - 34;             // 518 — label row above bar

    // Threshold gate: only redraw when distance changes by > 1m
    if (fabsf(dist - _dockPrevDist) < 1.0f) return;
    _dockPrevDist = dist;

    float clamped = fminf(fmaxf(dist, 0.0f), BAR_MAX_DIST);
    uint16_t barCol = (dist < DOCK_DIST_ALARM_M) ? TFT_RED :
                      (dist < DOCK_DIST_WARN_M)  ? TFT_YELLOW :
                                                    TFT_DARK_GREEN;

    // Bar fill from RIGHT (close = right side lit)
    float fraction = 1.0f - (clamped / BAR_MAX_DIST);
    uint16_t fillW = (uint16_t)(fraction * (BAR_W - 2));
    uint16_t fillX = BAR_X + 1 + (BAR_W - 2 - fillW);
    tft.fillRect(BAR_X + 1, barY + 1, BAR_W - 2, BAR_H - 2, TFT_OFF_BLACK);
    if (fillW > 0)
        tft.fillRect(fillX, barY + 1, fillW, BAR_H - 2, barCol);

    // Distance value: right-aligned at right edge of bar, on the label row above bar.
    // Black_24 — matches the "APPROACH" label font for visual unity.
    char buf[12];
    if      (dist >= 1000.0f) snprintf(buf, sizeof(buf), "%.1fkm", dist/1000.0f);
    else if (dist >= 100.0f)  snprintf(buf, sizeof(buf), "%.0fm",  dist);
    else                      snprintf(buf, sizeof(buf), "%.1fm",  dist);

    tft.setFont(Roboto_Black_24);
    tft.setTextColor(barCol, TFT_BLACK);
    // Clear right half of label row (30 px tall for Black_24) then right-align distance text
    tft.fillRect(BAR_X + BAR_W/2, lblY, BAR_W/2, 30, TFT_BLACK);
    int16_t tw = getFontStringWidth(&Roboto_Black_24, buf);   // measure in the draw font, not RP_LBL (Black_28)
    tft.setCursor(BAR_X + BAR_W - tw, lblY);
    tft.print(buf);
}

// ── CHROME ────────────────────────────────────────────────────────────────────────────
static void chromeScreen_DOCK(KCM_TFT &tft) {
    if (_vesselDocked) {
        _dockChromDrawn = false;
        tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
        textCenter(tft, &Roboto_Black_72, 0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP,
                   "DOCKED", TFT_WHITE, TFT_DARK_GREEN);
        return;
    }

    if (!state.targetAvailable) {
        _dockChromDrawn = false;
        tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
        textCenter(tft, &Roboto_Black_72, 0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP,
                   "NO TARGET SET", TFT_WHITE, TFT_RED);
        return;
    }

    _dockChromDrawn = true;

    // Reset dot positions so first draw doesn't try to erase stale coords
    _dockDots = ReticleDotCache{};
    _dockPrevDist  = -999.0f;   // force the approach-distance bar to repaint on entry

    // Left panel: clear + reticle chrome
    tft.fillRect(0, TITLE_TOP, RP_X, SCREEN_H - TITLE_TOP, TFT_BLACK);
    _dockDrawReticleChrome(tft);

    // Divider between panels
    tft.drawLine(RP_X - 2, TITLE_TOP, RP_X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(RP_X - 1, TITLE_TOP, RP_X - 1, SCREEN_H, TFT_GREY);

    // Right panel chrome
    _dockDrawRightChrome(tft);

    // Reset the print states — forces a full clear on the first value draw. (The row
    // cache itself is invalidated by drawStaticScreen() after this chrome.)
    for (uint8_t r = 0; r < ROW_COUNT; r++) printState[DOCK_SC][r] = PrintState{};
    // (the approach-distance bar's _dockPrevDist sentinel is reset above so it
    //  repaints on screen entry.)
}


// ── DRAW (called every loop) ──────────────────────────────────────────────────────────
static void drawScreen_DOCK(KCM_TFT &tft) {
    uint32_t _t0 = micros();
    // Docked: nothing to update
    if (_vesselDocked) return;

    // State transitions
    if (!state.targetAvailable) {
        if (_dockChromDrawn) { _dockChromDrawn = false; switchToScreen(screen_DOCK); }
        return;
    }
    if (!_dockChromDrawn) { switchToScreen(screen_DOCK); return; }

    // ── Compute derived values ────────────────────────────────────────────────────────
    // Shared derived-angle block (identical to TGT): nose→port, velocity→target and both
    // antipodal directions, bearings wrapped to ±180°.
    ReticleAngles ang = reticleComputeAngles();
    // Approach-path error about the target axis — drives rows 4 and 5.
    float appRight = ang.appRight, appUp = ang.appUp;
    // Beyond 90 deg the craft is travelling away from the port and the signed pair
    // stops being actionable, so the rows show "---" (the same idiom T+Dock uses
    // when not closing) rather than a large number nobody can fly.
    bool appValid = (sqrtf(appRight*appRight + appUp*appUp) <= 90.0f);

    // Lateral drift magnitude — off-axis speed component perpendicular to approach axis
    float v_lat_mag = 0.0f;
    {
        auto toUnit = [](float hdg_deg, float pit_deg, float out[3]) {
            float h = hdg_deg * DEG_TO_RAD, p = pit_deg * DEG_TO_RAD;
            out[0] = cosf(p)*sinf(h);
            out[1] = cosf(p)*cosf(h);
            out[2] = sinf(p);
        };
        float vel_unit[3], tgt_unit[3];
        toUnit(state.tgtVelHeading, state.tgtVelPitch, vel_unit);
        toUnit(state.tgtHeading,    state.tgtPitch,    tgt_unit);
        float speed = fabsf(state.tgtVelocity);
        float vel_vec[3] = { vel_unit[0]*speed, vel_unit[1]*speed, vel_unit[2]*speed };
        float v_app = vel_vec[0]*tgt_unit[0] + vel_vec[1]*tgt_unit[1] + vel_vec[2]*tgt_unit[2];
        float v_lat[3] = { vel_vec[0]-v_app*tgt_unit[0],
                           vel_vec[1]-v_app*tgt_unit[1],
                           vel_vec[2]-v_app*tgt_unit[2] };
        v_lat_mag = sqrtf(v_lat[0]*v_lat[0] + v_lat[1]*v_lat[1] + v_lat[2]*v_lat[2]);
        if (v_lat_mag < 0.005f) v_lat_mag = 0.0f;
    }

    // ── Update reticle dots ───────────────────────────────────────────────────────────
    // Shared marker layer (KerbalDisplayCommon); the angles are already body-referenced.
    reticleUpdateDots(tft, DOCK_GEOM, _dockDots, ang);

    // ── Right panel values ────────────────────────────────────────────────────────────
    char buf[20];
    uint16_t fg, bg;

    auto dockVal = [&](uint8_t row, uint8_t slot, const char *label, const String &val,
                        uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, DOCK_SC, slot, row, RP_X, RP_W, label, val, fgc, bgc, RP_F, RP_NR, false);
    };

    // Half-width cells for the two split rows, independent cache slots (as TGT does).
    const uint16_t RP_HW = RP_W / 2;
    auto dockValH = [&](uint8_t row, uint8_t slot, uint16_t x, const char *label,
                        const String &val, uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, DOCK_SC, slot, row, x, RP_HW - ROW_PAD, label, val, fgc, bgc, RP_F, RP_NR, false);
    };

    auto angCol = [](float e, uint16_t &fg, uint16_t &bg) {
        float ae = fabsf(e);
        if      (ae >= DOCK_BRG_ALARM_DEG) { fg = TFT_WHITE;     bg = TFT_RED;   }
        else if (ae >= DOCK_BRG_WARN_DEG)  { fg = TFT_YELLOW;    bg = TFT_BLACK; }
        else                                { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    };

    // Row 0 — Distance  (cache slot 0)
    if      (state.tgtDistance < DOCK_DIST_ALARM_M) { fg = TFT_WHITE;     bg = TFT_RED;   }
    else if (state.tgtDistance < DOCK_DIST_WARN_M)  { fg = TFT_YELLOW;    bg = TFT_BLACK; }
    else                                              { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    dockVal(0, 0, "DIST", formatAlt(state.tgtDistance), fg, bg);

    // Row 1 — Time to docking  (cache slot 1)
    {
        float vc = state.tgtVelocity;
        bool closing = (vc < -0.01f);
        if (!closing) {
            dockVal(1, 1, "T+DOCK", "---", TFT_DARK_GREY, TFT_BLACK);
        } else {
            float tDock = state.tgtDistance / fabsf(vc);
            if      (tDock < DOCK_TDOCK_ALARM_S) { fg = TFT_WHITE;     bg = TFT_RED;   }
            else if (tDock < DOCK_TDOCK_WARN_S)  { fg = TFT_YELLOW;    bg = TFT_BLACK; }
            else                     { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
            dockVal(1, 1, "T+DOCK", formatTimeCompact(tDock), fg, bg);
        }
    }

    // Row 2 — Closure velocity  (cache slot 2)
    {
        float vc = state.tgtVelocity;
        bool closing = (vc < 0.0f);
        bool tooFast = fabsf(vc) > DOCK_VCLOSURE_ALARM_MS && state.tgtDistance < DOCK_VCLOSURE_ALARM_DIST_M;
        if (tooFast) { fg = TFT_WHITE; bg = TFT_RED; }
        else         { fg = closing ? TFT_DARK_GREEN : TFT_YELLOW; bg = TFT_BLACK; }
        snprintf(buf, sizeof(buf), "%+.2f m/s", vc);
        dockVal(2, 2, "V.CLOSE", buf, fg, bg);
    }

    // Row 3 — V.Lat total lateral drift magnitude  (cache slot 3)
    {
        float av = v_lat_mag;
        if      (av >= DOCK_DRIFT_ALARM_MS) { fg = TFT_WHITE;      bg = TFT_RED;   }
        else if (av >= DOCK_DRIFT_WARN_MS)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                                 { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        dockVal(3, 3, "V.LAT", fmtMs(v_lat_mag), fg, bg);
    }

    // Row 4 — Brg | Elv: where the port sits relative to the NOSE (cache slots 4, 5).
    // The signed pair behind Nos.Off, and literally where the violet marker is on the
    // reticle. Informational dark green, matching TGT — Nos.Off carries the colour band.
    // Whole degrees: the half-width cell cannot hold a decimal (measured), and the full
    // +/-180 range has to fit when the port swings behind you.
    {
        snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.priRight);
        dockValH(4, 4, RP_X,         "BRG", buf, TFT_DARK_GREEN, TFT_BLACK);
        snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.priUp);
        dockValH(4, 5, RP_X + RP_HW, "ELV", buf, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 5 — V.Brg | V.Elv: approach-path error about the target axis (slots 6, 7).
    // Target-referenced, not the nose-referenced angle the markers are plotted at: on the
    // reticle this is the gap between the green velocity marker and the violet port
    // marker. Zero = flying straight down the approach axis, whatever the nose is doing.
    if (!appValid) {
        dockValH(5, 6, RP_X,         "V.BRG", "---", TFT_DARK_GREY, TFT_BLACK);
        dockValH(5, 7, RP_X + RP_HW, "V.ELV", "---", TFT_DARK_GREY, TFT_BLACK);
    } else {
        angCol(appRight, fg, bg);
        snprintf(buf, sizeof(buf), "%+.0f\xB0", appRight);
        dockValH(5, 6, RP_X,         "V.BRG", buf, fg, bg);

        angCol(appUp, fg, bg);
        snprintf(buf, sizeof(buf), "%+.0f\xB0", appUp);
        dockValH(5, 7, RP_X + RP_HW, "V.ELV", buf, fg, bg);
    }

    // Row 6 — Nos.Off: total angular offset of nose from port (cache slot 10)
    // The boresight projection makes this exact rather than a Pythagorean approximation:
    // the plotted radius IS the angular separation, so this is literally how far from
    // the crosshair the PORT marker sits. Always positive — unsigned offset, and the one
    // row of the three still colour-banded, so alignment status stays signalled.
    {
        float noseOff = sqrtf(ang.priRight * ang.priRight + ang.priUp * ang.priUp);
        angCol(noseOff, fg, bg);
        snprintf(buf, sizeof(buf), "%.1f\xB0", noseOff);
        dockVal(6, 10, "NOS.OFF", buf, fg, bg);
    }

    // Row 7 — RCS | SAS buttons (full height to screen bottom)
    {
        uint16_t ry  = TITLE_TOP + 7 * rowHFor(RP_NR);
        uint16_t rh  = SCREEN_H - ry;
        uint16_t hw  = RP_W / 2;
        uint16_t sasX = RP_X + hw;
        uint16_t sasW = RP_X + RP_W - sasX;

        // RCS button (slot 8)
        {
            bool rcsOn = state.rcs_on;
            String rcsStr = rcsOn ? "ON" : "OFF";
            RowCache &rc = rowCache[DOCK_SC][8];
            if (rc.value != rcsStr) {
                ButtonLabel btn = rcsOn
                    ? ButtonLabel{ "RCS", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
                    : ButtonLabel{ "RCS", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
                drawButton(tft, RP_X, ry, hw, rh, btn, RP_LBL, false);
                rc.value = rcsStr;
            }
        }

        // SAS button (slot 9)
        {
            const char *v; uint16_t sasFg, sasBg;
            switch (state.sasMode) {
                case 255: v = "SAS";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 0:   v = "STAB"; sasFg = TFT_BLACK;     sasBg = TFT_SKY;        break;
                case 1:   v = "PRO";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 2:   v = "RETR"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 3:   v = "NRM";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 4:   v = "ANRM"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 5:   v = "RAD+"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 6:   v = "RAD-"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 7:   v = "TGT";  sasFg = TFT_WHITE;     sasBg = TFT_DARK_GREEN; break;
                case 8:   v = "ATGT"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 9:   v = "MNVR"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                default:  v = "SAS";  sasFg = TFT_DARK_GREY; sasBg = TFT_OFF_BLACK;  break;
            }
            RowCache &rc = rowCache[DOCK_SC][9];
            String sv = v;
            if (rc.value != sv || rc.fg != sasFg || rc.bg != sasBg) {
                ButtonLabel btn = { v, sasFg, sasFg, sasBg, sasBg, TFT_GREY, TFT_GREY };
                drawButton(tft, sasX, ry, sasW, rh, btn, RP_LBL, false);
                rc.value = sv; rc.fg = sasFg; rc.bg = sasBg;
            }
        }
    }

    // Approach bar — left panel bottom (threshold-gated internally)
    _dockDrawDistBar(tft, state.tgtDistance);

    // Redraw all dividers last — printValue fills can erase them
    // Between T+Dock(1) and V.Close(2)
    { uint16_t dy = rowYFor(2,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }
    // Between V.Lat(3) and Brg|Elv(4)
    { uint16_t dy = rowYFor(4,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }
    // Between V.Brg|V.Elv(5) and Nos.Off(6)
    { uint16_t dy = rowYFor(6,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }
    // Before buttons(7)
    { uint16_t dy = rowYFor(7,RP_NR) - 1;
      tft.drawLine(RP_X, dy,   RP_X+RP_W, dy,   TFT_GREY);
      tft.drawLine(RP_X, dy+1, RP_X+RP_W, dy+1, TFT_GREY); }
    // Panel left border
    tft.drawLine(RP_X - 2, TITLE_TOP, RP_X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(RP_X - 1, TITLE_TOP, RP_X - 1, SCREEN_H, TFT_GREY);

    if (debugMode) {
        uint32_t _dt = micros() - _t0;
        Serial.print("DOCK total=");
        Serial.print((float)_dt / 1000.0f, 2);
        Serial.print("ms  dist="); Serial.print(state.tgtDistance, 1);
        Serial.print("m  vc=");    Serial.println(state.tgtVelocity, 2);
    }
}

/***************************************************************************************
   Screen_LNCH.ino -- Launch / Circularization screen — chromeScreen_LNCH, drawScreen_LNCH

   Three modes:
     - PRE-LAUNCH: static checklist board (text-style, unchanged)
     - ASCENT: graphical altitude ladder + V.Vrt bar + velocity dial (left panel),
               numeric readouts (right panel). Auto-enters when sit_PreLaunch ends.
     - ORBITAL (circularization): orbit-diagram view with Ap/Pe markers and vessel
               position (left panel), apsis convergence tape (right panel). Entered
               on the coast latch: throttle closed with apoapsis above the orbit-safe
               altitude (see drawScreen_LNCH).

   Phase switching:
     - sit_PreLaunch → PRE-LAUNCH (auto, via SimpitHandler)
     - sit_PreLaunch clears → ASCENT
     - coast latch set → ORBITAL; cleared on the surface or when apoapsis falls back
     - A repeat press on the LNCH sidebar key flips the mode and sets the manual
       override (TouchEvents.ino), which stops auto-switching until the vessel or
       scene changes.

****************************************************************************************/
#include "KCMk1_InfoDisp.h"


bool _lnchOrbitalMode      = false;
bool _lnchCoastLatched     = false;  // true once the ascent burn has ended (see below)
bool _lnchManualOverride   = false;  // true = pilot has overridden auto phase switch
bool _lnchPrelaunchMode    = false;  // true = sit_PreLaunch board is showing
bool _lnchPrelaunchDismissed = false; // true = pilot tapped to dismiss; don't re-enter

// ── Ascent phase geometry ─────────────────────────────────────────────────────────────
// Six panel constants used to live here describing a 717x417 content area split at
// x=453 -- the rev-1 720x480 screen. This panel has been 1024x600 since rev-2 and the
// live ASCENT layout is in Screen_LNCH_Ascent.ino, so every one of them was both unused
// and wrong. Only the title offset survives, and it is still correct.
static const int16_t LNCH_AS_PANEL_Y     = 63;   // just below the title bar


// ── Top-level dispatchers ──────────────────────────────────────────────────────────────
// chromeScreen_LNCH is called once on screen entry / SOI change, drawScreen_LNCH on
// every frame. Both delegate to the active phase's draw functions, which live in:
//   - Screen_LNCH_PreLaunch.ino (when sit_PreLaunch is set)
//   - Screen_LNCH_Ascent.ino    (when below switch altitude)
//   - Screen_LNCH_Circ.ino      (when above switch altitude)
// The phase-mode flags _lnchPrelaunchMode and _lnchOrbitalMode are set by SimpitHandler
// (pre-launch transitions) and by drawScreen_LNCH itself (altitude hysteresis).

static void chromeScreen_LNCH(KCM_TFT &tft) {
  // _lnchOrbitalMode is set by drawScreen_LNCH from the coast latch before chrome is called.
  if (_lnchPrelaunchMode) {
    // ── PRE-LAUNCH board (see Screen_LNCH_PreLaunch.ino) ──
    _lnchPrelaunchDrawChrome(tft);
    return;
  }

  if (!_lnchOrbitalMode) {
    // ── Ascent phase (graphical) ──
    // Left panel: altitude ladder + V.Vrt bar + V.Orb bar + FPA dial + atmosphere gauge
    // Right panel: 8 numeric readouts stacked vertically
    _lnchAsResetState();
    _lnchAsDrawLeftPanelChrome(tft);
    _lnchAsDrawRightPanelChrome(tft);

  } else {
    // ── Orbital (circularization) phase ──
    // Left panel: orbit diagram (Ap/Pe) — drawn per-frame by _lnchOrDrawLeftPanelValues,
    //   so it needs no static chrome here (drawStaticScreen already cleared to black).
    // Right panel: 8 numeric readouts — same layout style as ascent but with
    //   orbital-specific row set (Alt.SL / V.Orb / ApA / PeA / T+Ap / Thrtl /
    //   T.Brn / ΔV.Stg) and orbital change-detection state.
    _lnchOrResetState();
    _lnchOrDrawRightPanelChrome(tft);
  }
}


static void drawScreen_LNCH(KCM_TFT &tft) {
  // ── PRE-LAUNCH board (see Screen_LNCH_PreLaunch.ino) ──
  if (_lnchPrelaunchMode) {
    _lnchPrelaunchDrawValues(tft);
    return;
  }

  // ── Phase detection: ASCENT until the coast begins, CIRCULARISATION after ──────────
  //
  // The launch arc has three ordered stages and this screen has two modes, so ASCENT is
  // the powered ascent and CIRCULARISATION is everything from the coast onward.
  //
  // This used to switch on altitude, at 6% of body radius — 36 km on Kerbin. Altitude
  // is the wrong axis for it. A spaceplane can have its apoapsis parked above the
  // atmosphere while still burning at 35 km, and a Mun ascent finishes below the Kerbin
  // threshold entirely, so one number cannot serve both. What actually separates the
  // stages is the engine: you are ascending while you are pushing apoapsis up, and
  // coasting once you stop.
  //
  // Two conditions, because throttle alone is not enough:
  //
  //   Throttle closed. The direct signal, and the only one that works on an airless
  //   body, where there is no atmosphere boundary to cross.
  //
  //   Apoapsis already at or above the orbit-safe altitude — the ascent burn has done
  //   its job. Without this a throttle-down through max Q, or a staging gap, would read
  //   as a coast a minute after liftoff.
  //
  // And it latches. The circularisation burn re-opens the throttle, so a live test would
  // drop back to ASCENT for the one burn CIRCULARISATION exists to fly. Once the coast
  // has started the ascent is over.
  //
  // It clears on the surface and whenever apoapsis falls back below the line. The
  // surface test is what makes a Mun ascent start in ASCENT: SimpitHandler clears the
  // latch on leaving the pad, which covers a launch from KSC but not a departure from
  // another body's surface, where the vessel is sit_Landed rather than sit_PreLaunch --
  // and a lander parked high on the Mun can have an apoapsis above minSafe while
  // standing still. Sitting on the ground is not a coast.
  const float orbitSafeAlt = (currentBody.minSafe > currentBody.lowSpace)
                               ? currentBody.minSafe : currentBody.lowSpace;
  const bool  apoapsisParked = (orbitSafeAlt > 0.0f && state.apoapsis >= orbitSafeAlt);
  const bool  onSurface      = (state.situation & (sit_Landed | sit_Splashed | sit_PreLaunch)) != 0;

  if (onSurface || !apoapsisParked)               _lnchCoastLatched = false;
  else if (state.throttle <= LNCH_COAST_THROTTLE) _lnchCoastLatched = true;

  bool orbMode = _lnchCoastLatched;

  // Phase switch — auto only if not manually overridden
  if (!_lnchManualOverride && orbMode != _lnchOrbitalMode) {
    _lnchOrbitalMode = orbMode;
    switchToScreen(screen_LNCH);   // full chrome; drawStaticScreen invalidates the row cache
    return;
  }

  // The per-frame manual-override dot that lived here is gone — the panel-level
  // AUTO/MAN chip (updateModeChip) annunciates this screen's phase override too,
  // and it occupies the same corner of the title bar.

  if (!_lnchOrbitalMode) {
    // =========================================================
    // ASCENT PHASE (graphical)
    // Left panel: altitude ladder + V.Vrt + V.Orb bars + FPA dial + atmosphere gauge
    // Right panel: 8 numeric readouts, each with its own change detection
    //
    // Uses _lnchOrbitalMode (persistent state) rather than the freshly-computed
    // `orbMode` (the coast latch), so that manual override mode correctly draws
    // the ascent visuals even while the latch says coast.
    // =========================================================
    _lnchAsDrawLeftPanelValues(tft);
    _lnchAsDrawRightPanelValues(tft);
    return;
  }

  // =========================================================
  // ORBITAL PHASE (circularization)
  // Left panel: orbit graphic (ellipse + body + Ap/Pe markers + target circle)
  // Right panel: 8 numeric readouts with orbital-specific row set
  // =========================================================
  _lnchOrDrawLeftPanelValues(tft);
  _lnchOrDrawRightPanelValues(tft);
}

/***************************************************************************************
   Screen_LNCH_Ascent.ino -- Ascent phase of the LNCH screen.

   Active when state.altitude is below ~6% of bodyR (with hysteresis at 5.5% on the
   way back down). This is the "graphical flight instrument" view used during the
   gravity-turn ascent.

   LEFT PANEL (x=0..452):
     - Altitude ladder (x=0..155): vertical altitude scale with vessel + apoapsis
       markers, ground/atmosphere/orbit reference lines
     - V.Vrt bar (x=180..220): vertical velocity bar, ±500 m/s scale
     - V.Orb bar (x=240..280): orbital velocity bar
     - FPA dial (x=287, R=80): flight path angle indicator with target marker
     - Atmosphere gauge (x=287..440, y=394..434): atmospheric density bar with
       triangle indicator showing current altitude's atmo fraction

   RIGHT PANEL (x=453..720):
     - 8 numeric readouts: Alt.SL, ApA, T+Ap, V.Srf/V.Orb, V.Vrt, Thrtl, T.Brn, ΔV.Stg
     - Grouped horizontal dividers between altitude / velocity / propulsion groups

   Phase membership (LNCH screen has three phases):
     - PRE-LAUNCH (Screen_LNCH_PreLaunch.ino)  — auto, when sit_PreLaunch is set
     - ASCENT     (this file)                   — when below switch altitude
     - CIRC       (Screen_LNCH_Circ.ino)       — when above switch altitude

   Top-level dispatcher Screen_LNCH.ino selects which of these to draw.

   Shared with the rest of the LNCH screen (defined in Screen_LNCH.ino):
     - LNCH_AS_PANEL_Y, LNCH_AS_LP_LEFT       (left graphics panel geometry)
     The ascent-specific code below references these freely (single Arduino TU).
     The rev-2 right (numeric readout) panel uses its own LNCH_AS2_* geometry and
     _lnchAs2RowY() — right-aligned to the content edge, 400 px wide, full height,
     larger fonts. Circularization still uses the shared LNCH_AS_RPANEL_* / ROW_H.

   Public-to-the-sketch entry points (called by the LNCH dispatcher):
     - _lnchAsResetState()              — clear all change-detection state
     - _lnchAsDrawLeftPanelChrome(tft)  — initial graphics chrome (ladder, dial, etc.)
     - _lnchAsDrawRightPanelChrome(tft) — initial labels + dividers for right panel
     - _lnchAsDrawLeftPanelValues(tft)  — per-frame left panel value updates
     - _lnchAsDrawRightPanelValues(tft) — per-frame right panel value updates
****************************************************************************************/

// ═══════════════════════════════════════════════════════════════════════════
//  ASCENT LAYOUT ANCHORS — resize the whole screen from here.
//  Every element below derives its position from these anchors, so changing the
//  readout width, the shared vertical band, or the panel split reflows all
//  gauges without touching their individual positioning code.
// ═══════════════════════════════════════════════════════════════════════════

// Right-hand numeric readout column (right-aligned to the content edge).
//
// Seven rows, not the eight this panel carried before. V.Srf and V.Vrt moved onto the
// two bars that draw them; Alt.SL and ApA were dropped outright. T+Ap, Thrtl, Q, Mach,
// G, Stg.Brn and dV.Stg are what is left, every one a value with no picture anywhere on
// this screen. Fewer rows, so each is taller. ASCENT is the only user of this panel --
// the circularisation phase replaced its copy with the apsis tape.
//
// Alt.SL and ApA are position-only on this screen now: the altitude ladder marks both
// against a labelled tick scale, and there is nowhere to put their digits. The left
// panel is packed to 573 px of 576; the ladder strip is erased out to x=156 (its marker
// labels reach x=124) and the atmosphere column's left triangle starts at x=166, so the
// free space between them is 10 px, where "101 km" needs about 60. The PFD on the other panel carries both in the great majority of
// ascent phases; the exception is a spaceplane still in the atmosphere, where that panel
// is AIRCRAFT and has neither -- a deliberate, accepted cost rather than an oversight.
//
// Declared up here with the other anchors because the PrintState array and the label
// table size themselves from it a thousand lines above the readout geometry block, and
// the Arduino builder hoists function prototypes but not constants.
static const uint8_t LNCH_AS2_NROWS    = 7;

// The readout column is LNCH_AS2_RPANEL_W/X, declared with the rest of the row table
// further down. A second, identical pair (LNCH_AS_READOUT_W/X) used to be declared here
// -- same 360 px, same CONTENT_W - 360 -- and nothing read it.

// Left graphics panel: everything left of the readout column.
static const int16_t LNCH_AS_LP_LEFT   = 0;

// Shared vertical band for the ladder and all gauges. Move them together here.
static const int16_t LNCH_AS_BAND_TOP  = TITLE_TOP + 18;            // 80  (~18px under title bar)
static const int16_t LNCH_AS_BAND_BOT  = SCREEN_H  - 18;            // 582 (~18px above screen bottom)

// Gauge label rows within the band (name label on top; endpoint labels flank
// the gauge body). The bars/FPA/atmosphere bodies sit between BODY_TOP/BOT; the
// ladder uses the full band (it carries its own inline labels).
static const int16_t LNCH_AS_GAUGE_NAME_H   = 24;   // name label height (Black_20)
static const int16_t LNCH_AS_GAUGE_ENDLBL_H = 18;   // endpoint label height (Black_16)
static const int16_t LNCH_AS_GAUGE_NAME_Y   = LNCH_AS_BAND_TOP;                                                     // 80

// Digital window row, between the gauge name and its top endpoint label. Each bar
// carries its own value here rather than in the readout column 400 px to the right:
// a tape whose digits are at the other end of the display is two half-instruments,
// and reading magnitude and precision costs a saccade every time. Shifting BODY_TOP
// is all it takes to make room -- every gauge derives from it, which is what the
// anchor block above exists for.
static const int16_t LNCH_AS_GAUGE_VAL_H    = 26;
static const int16_t LNCH_AS_GAUGE_VAL_Y    = LNCH_AS_BAND_TOP + LNCH_AS_GAUGE_NAME_H;                              // 104
static const int16_t LNCH_AS_GAUGE_BODY_TOP = LNCH_AS_BAND_TOP + LNCH_AS_GAUGE_NAME_H + LNCH_AS_GAUGE_VAL_H
                                              + LNCH_AS_GAUGE_ENDLBL_H + 6;                                         // 154
static const int16_t LNCH_AS_GAUGE_BODY_BOT = LNCH_AS_BAND_BOT - LNCH_AS_GAUGE_ENDLBL_H - 2;                        // 562

// Horizontal spacing: COL_GAP = whitespace between element bounding boxes;
// LBL_OVERHANG = how far each bar's endpoint-label box extends beyond the bar.
static const int16_t LNCH_AS_COL_GAP      = 10;   // compact whitespace to fit the larger FPA
static const int16_t LNCH_AS_LBL_OVERHANG = 14;

// Left panel — altitude ladder (first column).
// Vertical strip showing altitude scale with tick labels, reference lines
