static const int16_t LNCH_AS_STAGE_Y = (LNCH_AS_FPA_VAL_Y + LNCH_AS_FPA_VAL_H + LNCH_AS_HDG_NAME_Y) / 2
                                       - LNCH_AS_STAGE_H / 2;
