static const uint16_t LNCH_AS_ATMO_TICK_SKY_COLOR = TFT_DARK_GREY;

// ── Ascent phase change-detection state ───────────────────────────────────────────────
// Cached last-drawn values for each row. Re-draw only on change.
// Alt.SL, ApA, V.Srf and V.Vrt moved onto their gauges, and their caches with them --
// the gauge windows keep last-drawn strings instead. What is left is the readout
// column's own seven rows.
static int32_t _lnchAsPrevTimeToAp   = -1 << 30;  // seconds
static int16_t _lnchAsPrevThrottle   = -1;        // percent (0-100)
static int32_t _lnchAsPrevQ          = -1 << 30;  // tenths of a kPa
static int32_t _lnchAsPrevMach       = -9999;     // hundredths, -9999 = "---"
static int32_t _lnchAsPrevG          = -1 << 30;  // tenths of a g
static int32_t _lnchAsPrevTBurn      = -1 << 30;  // seconds
static int32_t _lnchAsPrevDVStg      = -1 << 30;  // m/s (as tenths? or int)
// Track colors too (threshold changes don't alter the numeric value but still require redraw)
static uint16_t _lnchAsPrevTimeToApFg= 0xFFFF;
static uint16_t _lnchAsPrevThrFg     = 0xFFFF; static uint16_t _lnchAsPrevThrBg  = 0xFFFF;
static uint16_t _lnchAsPrevQFg       = 0xFFFF; static uint16_t _lnchAsPrevQBg    = 0xFFFF;
static uint16_t _lnchAsPrevGFg       = 0xFFFF; static uint16_t _lnchAsPrevGBg    = 0xFFFF;
static uint16_t _lnchAsPrevTBurnFg   = 0xFFFF; static uint16_t _lnchAsPrevTBurnBg = 0xFFFF;
static uint16_t _lnchAsPrevDVStgFg   = 0xFFFF; static uint16_t _lnchAsPrevDVStgBg = 0xFFFF;

// Ladder / V.Vrt bar state.
// Auto-scaling: scale top grows as vessel climbs. When it changes, the entire
// ladder is redrawn (chrome re-runs). _lnchAsLastDrawnScaleTop tracks what
// value was last rendered, so we know when to redraw.
static int16_t _lnchAsPrevVesselPx   = -1;       // last vessel marker y-pixel
static int16_t _lnchAsPrevApAPx      = -1;       // last apoapsis marker y-pixel
static bool    _lnchAsPrevApAValid   = false;    // was apoapsis marker drawn last frame?
static int16_t _lnchAsPrevVVrtFillPx = 0;        // last V.Vrt bar fill height (signed)
static int16_t _lnchAsPrevVOrbFillPx = 0;        // last V.Orb bar fill height (unsigned, pixels from bottom)
static float   _lnchAsLastDrawnScaleTop = 0.0f;  // scale top last rendered on screen
static float   _lnchAsCurrScaleTop      = 0.0f;  // current (grow-only) scale top target (m)

// FPA dial state.
static int16_t _lnchAsPrevFpaReadout   = -9999;  // last FPA value shown (integer degrees)
static int16_t _lnchAsPrevFpaTarget    = -9999;  // last target FPA marker position (integer degrees)

// Atmosphere gauge state.
// Tracks previous triangle indicator center x-coordinate for flicker-free
// incremental updates. Sentinel -1 = "not yet drawn" (first frame).
// With the four-zone design (including OFF_BLACK parking), the triangle
// position alone encodes whether we're in a no-atmosphere or atmospheric
// state — no separate NoAtm flag is needed.
static int16_t _lnchAsPrevAtmoTriY   = -1;

// Heading tape state.
static float   _lnchAsPrevHdg    = -9999.0f;   // last tape-center heading
static int16_t _lnchAsPrevHdgBox = -9999;      // last integer heading in the box
static float   _lnchAsPrevVelHdg = -9999.0f;   // last velocity-vector heading

// STAGE indicator button state (-1 = not yet drawn).
static int8_t  _lnchAsPrevStageActive = -1;

// ── Ascent phase helpers ──────────────────────────────────────────────────────────────
//
// Right panel uses library printDispChrome (for labels/borders in chrome) and
// printValue (for the value in updates), matching the pattern used by every other
// screen. PrintState tracking handles flicker-free redraws and correct erase of
// prior values (including when string width or background colour changes).
//
// Each row is a full-width cell in the right panel; the label is drawn on the
// left and the value is right-aligned. Labels are short ("V.SRF", "ΔV.STG")
// and don't carry units since the unit ("m/s") is implicit from KSP convention.

static PrintState _lnchAsPs[LNCH_AS2_NROWS];   // PrintState tracking, one per readout row


// ── Altitude ladder ───────────────────────────────────────────────────────────────────
//
// AUTO-SCALED, GROW-ONLY: the scale top grows through a fixed ladder of snap
// levels as the vessel climbs (or apoapsis grows). Once a level is reached, the
// scale stays there or grows higher — never shrinks. This gives fine-grained
// visibility of low altitudes early in the ascent (e.g. gravity-turn zone at
// 1-2 km) while still showing the full orbital range later.
//
// Snap levels (km): 2, 5, 10, 20, 40, 80, max
//   where max = target orbit altitude + 30 km (body-aware ceiling).
//
// Body parameter interpretation:
//   currentBody.flyHigh   — "Fly High" biome boundary (~18 km on Kerbin), low in atmosphere
//   currentBody.lowSpace  — atmosphere top / space boundary (~70 km on Kerbin)
//   currentBody.minSafe   — minimum safe orbital altitude (~72 km on Kerbin)
//
// For the ladder: ATMO line at lowSpace, ORBIT line at max(minSafe, lowSpace + 20 km).
//
// (_lnchAsCurrScaleTop is declared earlier in the state section so _lnchAsResetState
//  can reference it.)

// Compute the ceiling — the highest scale-top value we ever grow to for this body.
static float _lnchAsScaleCeiling() {
    float targetOrbit = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
    return targetOrbit + 30000.0f;
}

// Given a "desired minimum" scale top (m), snap UP to the next level in the
// fixed ladder. Returns the selected level in meters.
static float _lnchAsSnapScale(float desired) {
    static const float levels[] = {
        2000.0f, 5000.0f, 10000.0f, 20000.0f, 40000.0f, 80000.0f
    };
    static const uint8_t N = sizeof(levels) / sizeof(levels[0]);

    float ceiling = _lnchAsScaleCeiling();
    for (uint8_t i = 0; i < N; i++) {
        if (desired <= levels[i] && levels[i] < ceiling) return levels[i];
    }
    return ceiling;
}

// Compute the scale top we WANT right now, based on current vessel altitude
// and apoapsis. Called every frame; compared against the stored "current"
// scale top to decide if we need to redraw at a new scale.
static float _lnchAsDesiredScaleTop() {
    // Target: altitude × 2 so vessel sits roughly at mid-ladder as it climbs,
    //         apoapsis × 1.2 so it's always visible with headroom.
    float target = 0.0f;
    if (state.altitude * 2.0f > target) target = state.altitude * 2.0f;
    if (state.apoapsis > 0.0f && state.apoapsis * 1.2f > target) {
        target = state.apoapsis * 1.2f;
    }
    return _lnchAsSnapScale(target);
}

// Return the current effective scale top, growing as needed. GROW-ONLY: never
// returns a value smaller than the previous value stored in _lnchAsCurrScaleTop.
static float _lnchAsLadderScaleTop() {
    float desired = _lnchAsDesiredScaleTop();
    if (desired > _lnchAsCurrScaleTop) {
        _lnchAsCurrScaleTop = desired;
    }
    // Initial: if current is 0 (first call after reset), use at least the
    // smallest snap level so we have a sensible scale on the launch pad.
    if (_lnchAsCurrScaleTop < 2000.0f) {
        _lnchAsCurrScaleTop = _lnchAsSnapScale(2000.0f);
    }
    return _lnchAsCurrScaleTop;
}

// Map an altitude (m) to a Y pixel on the ladder. 0 -> Y_BOT, scaleTop -> Y_TOP.
// Values outside [0, scaleTop] are clamped.
static int16_t _lnchAsAltToY(float alt, float scaleTop) {
    if (scaleTop <= 0) return LNCH_AS_LADDER_Y_BOT;
    float frac = alt / scaleTop;
    if (frac < 0) frac = 0;
    if (frac > 1) frac = 1;
    int16_t y = LNCH_AS_LADDER_Y_BOT -
                (int16_t)roundf(frac * (float)LNCH_AS_LADDER_H);
    return y;
}

// Pick a nice tick interval based on scale range.
static float _lnchAsLadderTickInterval(float scaleTop) {
    if (scaleTop <=  3000)  return 500.0f;    // every 0.5 km  (2 km scale)
    if (scaleTop <=  6000)  return 1000.0f;   // every 1 km    (5 km scale)
    if (scaleTop <= 12000)  return 2000.0f;   // every 2 km    (10 km scale)
    if (scaleTop <= 25000)  return 5000.0f;   // every 5 km    (20 km scale)
    if (scaleTop <= 50000)  return 10000.0f;  // every 10 km   (40 km scale)
    if (scaleTop <= 100000) return 20000.0f;  // every 20 km   (80 km scale)
    if (scaleTop <= 150000) return 20000.0f;  // every 20 km   (120 km scale)
    if (scaleTop <= 500000) return 50000.0f;  // every 50 km
    return 100000.0f;
}

// Draw an altitude-marker triangle pointing left at altitude y, with a short label to
// the right. 'filled' selects vessel (filled, "ALT") vs apoapsis (hollow, "Ap") style;
// the label is drawn at Black_16 in the same color as the triangle.
// Tip at LADDER_LINE_X+3, base at MARKER_X + MARKER_W, label just past the base.
static const int16_t LNCH_AS_MARKER_LBL_X    = 100;   // x of the label (past the base)
static const int16_t LNCH_AS_MARKER_LBL_W    = 32;    // width reserved for the marker label
                                                     // "ALT" is 30 px at Black_16, so the
                                                     // cell is 32. This also sizes the
                                                     // marker ERASE, which is why it has
                                                     // to be measured rather than guessed.
// A marker's drawn extent and the erase box are both 19 rows tall, so erasing one
// marker clips the other whenever their centres are within 19 - 1 + 19 - 1 = 18 px.
// (That 19 was also spelled out as a constant here; nothing read it, and a number no
// code depends on is one that drifts from the geometry it claims to describe.)

static void _lnchAsDrawAltMarker(KCM_TFT &tft, int16_t y, uint16_t color,
                                 bool filled, const char *label) {
    int16_t tipX  = LNCH_AS_LADDER_LINE_X + 3;
    int16_t baseX = LNCH_AS_LADDER_MARKER_X + LNCH_AS_LADDER_MARKER_W;
    int16_t halfH = 5;
    if (filled) {
        tft.fillTriangle(tipX, y,
                         baseX, y - halfH,
                         baseX, y + halfH,
                         color);
    } else {
        tft.drawLine(tipX, y, baseX, y - halfH, color);
        tft.drawLine(tipX, y, baseX, y + halfH, color);
        tft.drawLine(baseX, y - halfH, baseX, y + halfH, color);
    }
    // Label to the right of the triangle. Drawn opaquely on black, so where a marker
    // sits on a reference line its label covers that line's label rather than
    // interleaving with it; the repair below puts the reference label back when the
    // marker moves off.
    if (!label || !*label) return;
    textLeft(tft, &Roboto_Black_16,
             LNCH_AS_MARKER_LBL_X - 8, y - 9,   // x0-8 because textLeft adds TEXT_BORDER=8
             LNCH_AS_MARKER_LBL_W, 18,
             label, color, TFT_BLACK);
}

// Erase a previously-drawn marker (triangle bounding box + label area).
static void _lnchAsEraseAltMarker(KCM_TFT &tft, int16_t y) {
    int16_t tipX  = LNCH_AS_LADDER_LINE_X + 3;
    int16_t rightX = LNCH_AS_MARKER_LBL_X + LNCH_AS_MARKER_LBL_W;
    tft.fillRect(tipX, y - 9, rightX - tipX + 1, 19, TFT_BLACK);
}

// Reference-line labels (GND / ATM / TGT+ORB). Their glyphs start at x=118 and the
// marker erase box reaches x=132, so a marker passing a reference line takes a bite out
// of its label. The lines were already repaired after an erase; the labels were not, and
// the bite stayed on screen until the next ladder scale change. Both the chrome and the
// repair go through these two helpers now, so the two cannot drift apart.
static const int16_t LNCH_AS_REF_LBL_X = LNCH_AS_LADDER_REF_X2 - 40;
static const int16_t LNCH_AS_REF_LBL_W = 44;
static const int16_t LNCH_AS_REF_LBL_H = 16;

static void _lnchAsDrawRefLabel(KCM_TFT &tft, int16_t y0, const char *s, uint16_t color) {
    textLeft(tft, &Roboto_Black_16,
             LNCH_AS_REF_LBL_X, y0, LNCH_AS_REF_LBL_W, LNCH_AS_REF_LBL_H,
             s, color, TFT_BLACK);
}

// The ORBIT line's label is "TGT" over "ORB" straddling the line, so the pilot reads it
// as an altitude being aimed for; it falls back to a single centred "ORB" when the line
// is too close to either end of the ladder for two rows.
static void _lnchAsDrawOrbRefLabel(KCM_TFT &tft, int16_t refY) {
    if (refY > LNCH_AS_LADDER_Y_TOP + 18 && refY < LNCH_AS_LADDER_Y_BOT - 18) {
        _lnchAsDrawRefLabel(tft, refY - 17, "TGT", TFT_DARK_GREEN);
        _lnchAsDrawRefLabel(tft, refY +  1, "ORB", TFT_DARK_GREEN);
    } else {
        _lnchAsDrawRefLabel(tft, refY -  8, "ORB", TFT_DARK_GREEN);
    }
}

// After erasing a marker, repair the reference lines (GND/ATM/ORB) and their labels
// where the erased region crossed them. markerY is the y-center of the erased bounding
// box (height 19, so the box spans y-9 to y+9).
//
// The line and the label have different reach. A line is one row, so it needs repair
// only when it falls inside the box. A label is 19 rows tall and the two-row ORB label
// straddles its line by 18, so a label is repainted whenever its line is within 28 rows
// -- generous on purpose: the labels are opaque and identical every time, so a redundant
// repaint costs nothing and a missed one leaves a hole.
static const int16_t LNCH_AS_REF_LBL_REACH = 28;

static void _lnchAsRepairRefLines(KCM_TFT &tft, int16_t markerY) {
    int16_t tipX   = LNCH_AS_LADDER_LINE_X + 3;
    int16_t rightX = LNCH_AS_MARKER_LBL_X + LNCH_AS_MARKER_LBL_W;
    int16_t top    = markerY - 9;
    int16_t bot    = markerY + 9;

    float scaleTop = _lnchAsLadderScaleTop();

    // Check GND (solid white at y = Y_BOT). Endpoint matches chrome (REF_X2-2)
    // to avoid the stray bright pixel near the GND label.
    {
        int16_t refY = LNCH_AS_LADDER_Y_BOT;
        if (refY >= top && refY <= bot) {
            int16_t x0 = max(tipX, (int16_t)(LNCH_AS_LADDER_LINE_X + 1));
            int16_t x1 = min(rightX, (int16_t)(LNCH_AS_LADDER_REF_X2 - 2));
            if (x1 >= x0) tft.drawLine(x0, refY, x1, refY, TFT_WHITE);
        }
        if (abs(refY - markerY) <= LNCH_AS_REF_LBL_REACH)
            _lnchAsDrawRefLabel(tft, refY - 8, "GND", TFT_LIGHT_GREY);
    }

    // Check ATM (dashed sky-blue at y = lowSpace altitude)
    if (currentBody.lowSpace > 0) {
        int16_t refY = _lnchAsAltToY(currentBody.lowSpace, scaleTop);
        if (refY >= top && refY <= bot &&
            refY < LNCH_AS_LADDER_Y_BOT - 2 && refY > LNCH_AS_LADDER_Y_TOP + 2) {
            int16_t x0 = max(tipX, (int16_t)(LNCH_AS_LADDER_LINE_X + 1));
            int16_t x1 = min(rightX, (int16_t)(LNCH_AS_LADDER_REF_X2 - 1));
            // Redraw dashes only in the overlap x-range. Walk the same 6-px
            // pattern used in chrome so dashes align.
            for (int16_t x = LNCH_AS_LADDER_LINE_X + 1; x < LNCH_AS_LADDER_REF_X2; x += 6) {
                int16_t sx = x;
                int16_t ex = x + 3;
                // Clip dash to repair region
                if (ex < x0 || sx > x1) continue;
                int16_t csx = max(sx, x0);
                int16_t cex = min(ex, x1);
                tft.drawLine(csx, refY, cex, refY, TFT_SKY);
            }
        }
        if (refY < LNCH_AS_LADDER_Y_BOT - 2 && refY > LNCH_AS_LADDER_Y_TOP + 2 &&
            abs(refY - markerY) <= LNCH_AS_REF_LBL_REACH)
            _lnchAsDrawRefLabel(tft, refY - 8, "ATM", TFT_SKY);
    }

    // Check ORB (dashed dark-green at target orbit altitude)
    {
        float targetOrbit = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
        int16_t refY = _lnchAsAltToY(targetOrbit, scaleTop);
        if (refY >= top && refY <= bot &&
            refY < LNCH_AS_LADDER_Y_BOT - 2 && refY > LNCH_AS_LADDER_Y_TOP + 2) {
            int16_t x0 = max(tipX, (int16_t)(LNCH_AS_LADDER_LINE_X + 1));
            int16_t x1 = min(rightX, (int16_t)(LNCH_AS_LADDER_REF_X2 - 1));
            for (int16_t x = LNCH_AS_LADDER_LINE_X + 1; x < LNCH_AS_LADDER_REF_X2; x += 6) {
                int16_t sx = x;
                int16_t ex = x + 3;
                if (ex < x0 || sx > x1) continue;
                int16_t csx = max(sx, x0);
                int16_t cex = min(ex, x1);
                tft.drawLine(csx, refY, cex, refY, TFT_DARK_GREEN);
            }
        }
        if (refY < LNCH_AS_LADDER_Y_BOT - 2 && refY > LNCH_AS_LADDER_Y_TOP + 2 &&
            abs(refY - markerY) <= LNCH_AS_REF_LBL_REACH)
            _lnchAsDrawOrbRefLabel(tft, refY);
    }

    // Also repair the main vertical ladder line if it crosses the erase region.
    // The line is at LINE_X; marker tipX = LINE_X + 3, so the line isn't inside
    // the erase region horizontally. Skip.
}

// Draw static chrome for the altitude ladder: main vertical line, tick marks,
// tick labels, and reference lines (ground, atmo, orbit) with their labels.
// Fixed scale — called once per chrome cycle.
static void _lnchAsDrawLadderChrome(KCM_TFT &tft) {
    float scaleTop = _lnchAsLadderScaleTop();
    float tickInt  = _lnchAsLadderTickInterval(scaleTop);

    // Main vertical line
    tft.drawLine(LNCH_AS_LADDER_LINE_X, LNCH_AS_LADDER_Y_TOP,
                 LNCH_AS_LADDER_LINE_X, LNCH_AS_LADDER_Y_BOT,
                 TFT_LIGHT_GREY);

    // Tick marks and labels. Major ticks (at each `tickInt`) get a full-length
    // mark + label. Minor ticks (4 between majors, at tickInt/5 spacing) get a
    // half-length mark with no label, providing visual subdivision.
    float minorInt = tickInt / 5.0f;
    int16_t minorTickW = LNCH_AS_LADDER_TICK_W / 2;  // 3 px
    for (float a = 0; a <= scaleTop + 0.5f * minorInt; a += minorInt) {
        int16_t y = _lnchAsAltToY(a, scaleTop);
        if (y < LNCH_AS_LADDER_Y_TOP - 1) break;
        if (y > LNCH_AS_LADDER_Y_BOT) continue;

        // Is this a major tick? (altitude is an integer multiple of tickInt)
        // Use rounding since floating-point stepping accumulates error.
        float major_mul = a / tickInt;
        bool isMajor = (fabsf(major_mul - roundf(major_mul)) < 0.05f);

        int16_t tickLen = isMajor ? LNCH_AS_LADDER_TICK_W : minorTickW;
        tft.drawLine(LNCH_AS_LADDER_LINE_X - tickLen, y,
                     LNCH_AS_LADDER_LINE_X - 1,        y,
                     TFT_LIGHT_GREY);

        if (!isMajor) continue;

        // Label at each major tick. Skip 0 — "GND" label drawn separately.
        if (a < 500.0f) continue;
        char buf[12];
        if (a < 1000.0f) {
            snprintf(buf, sizeof(buf), "%dm", (int)roundf(a));
        } else if (tickInt < 1000.0f) {
            // Sub-km tick spacing — show decimal
            snprintf(buf, sizeof(buf), "%.1fkm", a / 1000.0f);
        } else {
            snprintf(buf, sizeof(buf), "%d km", (int)roundf(a / 1000.0f));
        }
        textRight(tft, &Roboto_Black_16,
                  LNCH_AS_LADDER_LBL_X, y - 9,
                  LNCH_AS_LADDER_LBL_W, 18,
                  buf, TFT_LIGHT_GREY, TFT_BLACK);
    }

    // Reference lines — use short labels (GND/ATM/ORB) so they don't overflow
    // into the V.Vrt bar area.

    // GROUND at altitude 0 (bottom of scale) — solid white line.
    // End matches the dashed-line endpoint pattern used for ATM/ORB
    // (the loop "x += 6" from LINE_X+1 ends the last dash at x=148 for REF_X2=150),
    // avoiding a stray bright pixel at x=150 which would sit 2 px diagonally below
    // the "D" of the "GND" label.
    {
        int16_t y = LNCH_AS_LADDER_Y_BOT;
        tft.drawLine(LNCH_AS_LADDER_LINE_X + 1, y,
                     LNCH_AS_LADDER_REF_X2 - 2, y,
                     TFT_WHITE);
        // Label vertically centered on the ground line (matches ATM/ORB). There
        // is room below now that the ladder bottom sits ~18px above the screen edge.
        _lnchAsDrawRefLabel(tft, y - 8, "GND", TFT_LIGHT_GREY);
    }

    // ATMO — only for atmospheric bodies (lowSpace > 0). Drawn at the actual
    // atmosphere top (lowSpace), not the fly-high biome boundary (flyHigh).
    // Color is sky blue for high contrast against the dark ladder background.
    if (currentBody.lowSpace > 0) {
        int16_t y = _lnchAsAltToY(currentBody.lowSpace, scaleTop);
        if (y < LNCH_AS_LADDER_Y_BOT - 2 && y > LNCH_AS_LADDER_Y_TOP + 2) {
            // Dashed line
            for (int16_t x = LNCH_AS_LADDER_LINE_X + 1; x < LNCH_AS_LADDER_REF_X2; x += 6) {
                tft.drawLine(x, y, x + 3, y, TFT_SKY);
            }
            // Label vertically centered on the reference line
            _lnchAsDrawRefLabel(tft, y - 8, "ATM", TFT_SKY);
        }
    }

    // ORBIT — target orbit altitude (minSafe or lowSpace + 20 km, whichever higher).
    // This is also the target apoapsis altitude during ascent, labeled as "TGT /
    // ORB" stacked on two lines to emphasize the pilot is AIMING for this altitude.
    {
        float targetOrbit = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
        int16_t y = _lnchAsAltToY(targetOrbit, scaleTop);
        if (y < LNCH_AS_LADDER_Y_BOT - 2 && y > LNCH_AS_LADDER_Y_TOP + 2) {
            for (int16_t x = LNCH_AS_LADDER_LINE_X + 1; x < LNCH_AS_LADDER_REF_X2; x += 6) {
                tft.drawLine(x, y, x + 3, y, TFT_DARK_GREEN);
            }
            // "TGT" over "ORB" straddling the line, or a single centred "ORB" when
            // there is not room for two rows -- see _lnchAsDrawOrbRefLabel().
            _lnchAsDrawOrbRefLabel(tft, y);
        }
    }
}

// Dynamic update: check for scale change first (redraw entire ladder if so),
// then update vessel and apoapsis markers. On each marker erase, repair any
// reference line segments that were crossing the erased region.
static void _lnchAsUpdateLadderMarkers(KCM_TFT &tft) {
    float scaleTop = _lnchAsLadderScaleTop();

    // Scale-change detection: redraw entire ladder strip if the scale differs
    // from what was last drawn. This erases tick labels, tick marks, reference
    // lines, and markers — all of which will be re-chromed/redrawn below.
    if (scaleTop != _lnchAsLastDrawnScaleTop) {
        // Erase full ladder region (wider than any single label/mark).
        int16_t eraseTop = max((int16_t)(LNCH_AS_LADDER_Y_TOP - 12), (int16_t)LNCH_AS_PANEL_Y);
        int16_t eraseBot = min((int16_t)(LNCH_AS_LADDER_Y_BOT + 2),
                               (int16_t)(SCREEN_H - 1));
        // Erase from x=0 to LADDER_ERASE_X2, covering tick labels, ticks, line,
        // markers, and reference-line labels.
        tft.fillRect(LNCH_AS_LADDER_LBL_X, eraseTop,
                     LNCH_AS_LADDER_ERASE_X2 - LNCH_AS_LADDER_LBL_X + 1,
                     eraseBot - eraseTop + 1,
                     TFT_BLACK);

        // Redraw chrome and invalidate marker cache so they redraw below.
        _lnchAsDrawLadderChrome(tft);
        _lnchAsPrevVesselPx = -1;
        _lnchAsPrevApAPx    = -1;
        _lnchAsPrevApAValid = false;
        _lnchAsLastDrawnScaleTop = scaleTop;
    }

    // Vessel and apoapsis markers.
    //
    // Both are erased, then both are redrawn, whenever either has moved. The version
    // this replaces erased one marker and redrew the other only "if it was within 6 px",
    // which was a guess: the erase box is 19 rows tall and a marker's own drawn extent is
    // 19 rows, so one marker's erase clips the other up to 18 px away, and the reference-
    // label repair above reaches 28. A miss left a marker half erased on the ladder until
    // the next scale change, which is what the bench saw. Two triangles and two short
    // labels cost nothing per frame; the proximity arithmetic cost correctness.
    int16_t    vesselY   = _lnchAsAltToY(state.altitude, scaleTop);
    const bool apaValid  = (state.apoapsis > 0.0f);
    int16_t    apaY      = apaValid ? _lnchAsAltToY(state.apoapsis, scaleTop) : (int16_t)-1;

    const bool moved = (vesselY != _lnchAsPrevVesselPx) ||
                       (apaValid != _lnchAsPrevApAValid) ||
                       (apaValid && apaY != _lnchAsPrevApAPx);
    if (!moved) return;

    if (_lnchAsPrevVesselPx >= 0) {
        _lnchAsEraseAltMarker(tft, _lnchAsPrevVesselPx);
        _lnchAsRepairRefLines(tft, _lnchAsPrevVesselPx);
    }
    if (_lnchAsPrevApAValid && _lnchAsPrevApAPx >= 0) {
        _lnchAsEraseAltMarker(tft, _lnchAsPrevApAPx);
        _lnchAsRepairRefLines(tft, _lnchAsPrevApAPx);
    }

    // Apoapsis first, so where the two coincide the vessel marker is the one on top.
    if (apaValid) _lnchAsDrawAltMarker(tft, apaY, TFT_YELLOW, false, "Ap");
    _lnchAsDrawAltMarker(tft, vesselY, TFT_DARK_GREEN, true, "ALT");

    _lnchAsPrevVesselPx = vesselY;
    _lnchAsPrevApAPx    = apaValid ? apaY : (int16_t)-1;
    _lnchAsPrevApAValid = apaValid;
}

// ── V.Vrt bar ─────────────────────────────────────────────────────────────────────────
//
// Vertical bar with zero at middle. Positive V.Vrt fills upward (green),
// negative fills downward (red). Scale is fixed at ±LNCH_AS_VVRT_SCALE_MS m/s,
// saturates at the ends.
static void _lnchAsDrawVVrtChrome(KCM_TFT &tft) {
    // Label box spans LBL_OVERHANG px beyond each bar edge so the "±500 m/s"
    // endpoint labels fit around the widened bar.
    const int16_t LBL_X0 = LNCH_AS_VVRT_X_LEFT - LNCH_AS_LBL_OVERHANG;
    const int16_t LBL_W  = LNCH_AS_VVRT_W + 2 * LNCH_AS_LBL_OVERHANG;

    // Bar name "V.Vrt" (Black_20)
    textCenter(tft, &Roboto_Black_20,
               LBL_X0, LNCH_AS_GAUGE_NAME_Y,
               LBL_W, LNCH_AS_GAUGE_NAME_H,
               "V.Vrt", TFT_LIGHT_GREY, TFT_BLACK);

    // Endpoint labels (Black_16), a few px clear of the bar top/bottom borders.
    textCenter(tft, &Roboto_Black_16,
               LBL_X0, LNCH_AS_VVRT_Y_TOP - LNCH_AS_GAUGE_ENDLBL_H - 6,
               LBL_W, LNCH_AS_GAUGE_ENDLBL_H,
               "+500 m/s", TFT_LIGHT_GREY, TFT_BLACK);
    textCenter(tft, &Roboto_Black_16,
               LBL_X0, LNCH_AS_VVRT_Y_BOT + 5,
               LBL_W, LNCH_AS_GAUGE_ENDLBL_H,
               "-500 m/s", TFT_LIGHT_GREY, TFT_BLACK);

    // Border + zero line drawn LAST so a label glyph can never nibble the borders.
    tft.drawRect(LNCH_AS_VVRT_X_LEFT, LNCH_AS_VVRT_Y_TOP,
                 LNCH_AS_VVRT_W,
                 LNCH_AS_VVRT_Y_BOT - LNCH_AS_VVRT_Y_TOP + 1,
                 TFT_LIGHT_GREY);
    tft.drawLine(LNCH_AS_VVRT_X_LEFT + 1, LNCH_AS_VVRT_Y_MID,
                 LNCH_AS_VVRT_X_LEFT + LNCH_AS_VVRT_W - 2, LNCH_AS_VVRT_Y_MID,
                 TFT_LIGHT_GREY);
}

// Update V.Vrt bar fill using incremental drawing (no full-clear + redraw, so
// no flicker). Handles positive/negative fill separately. When signs change
// between frames, clears the old side and draws the new side.
//
// Positive fill: green, grows upward from the zero line (y=MID-1, MID-2, ...).
// Negative fill: red, grows downward from the zero line (y=MID+1, MID+2, ...).
// fillPx encodes both magnitude and direction as a signed pixel count.
static void _lnchAsUpdateVVrtBar(KCM_TFT &tft) {
    float vv = state.verticalVel;
    if (vv > LNCH_AS_VVRT_SCALE_MS)  vv = LNCH_AS_VVRT_SCALE_MS;
    if (vv < -LNCH_AS_VVRT_SCALE_MS) vv = -LNCH_AS_VVRT_SCALE_MS;

    int16_t halfH = LNCH_AS_VVRT_Y_MID - LNCH_AS_VVRT_Y_TOP - 1;
    int16_t fillPx = (int16_t)roundf((vv / LNCH_AS_VVRT_SCALE_MS) * (float)halfH);

    int16_t prev = _lnchAsPrevVVrtFillPx;
    if (fillPx == prev) return;

    int16_t innerX = LNCH_AS_VVRT_X_LEFT + 1;
    int16_t innerW = LNCH_AS_VVRT_W - 2;

    // Sign change: clear the opposite side entirely before drawing new fill.
    bool signChanged = (fillPx >= 0) != (prev >= 0);
    if (signChanged) {
        if (prev > 0) {
            // Was climbing, now zero or falling — clear the green area above zero
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID - prev,
                         innerW, prev, TFT_BLACK);
        } else if (prev < 0) {
            // Was falling, now zero or climbing — clear the red area below zero
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID + 1,
                         innerW, -prev, TFT_BLACK);
        }
        prev = 0;  // effective "old" fill on the new sign's side is zero
    }

    if (fillPx > 0) {
        if (fillPx > prev) {
            // Extend green upward — fill only the newly-covered strip
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID - fillPx,
                         innerW, fillPx - prev, TFT_DARK_GREEN);
        } else {
            // Retract — clear the top strip that's no longer filled
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID - prev,
                         innerW, prev - fillPx, TFT_BLACK);
        }
    } else if (fillPx < 0) {
        int16_t absNew  = -fillPx;
        int16_t absPrev = -prev;
        if (absNew > absPrev) {
            // Extend red downward
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID + absPrev + 1,
                         innerW, absNew - absPrev, TFT_RED);
        } else {
            // Retract — clear the bottom strip
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID + absNew + 1,
                         innerW, absPrev - absNew, TFT_BLACK);
        }
    } else {
        // fillPx == 0: clear any remaining fill on the previously-active side
        if (prev > 0) {
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID - prev,
                         innerW, prev, TFT_BLACK);
        } else if (prev < 0) {
            tft.fillRect(innerX, LNCH_AS_VVRT_Y_MID + 1,
                         innerW, -prev, TFT_BLACK);
        }
    }

    _lnchAsPrevVVrtFillPx = fillPx;
}

// ── V.Orb bar ─────────────────────────────────────────────────────────────────────────
//
// Shows orbital velocity (state.orbitalVel) as a fill from the bottom up, with
// 100% = target circular-orbit velocity. The pilot can glance to see "how close
// am I to orbital speed" without having to know the specific target number.

// Circular orbit velocity at target altitude (m/s).
// v_circ = sqrt(μ / r) where μ = g_surf × radius² (classic two-body).
static float _lnchAsCircularOrbitVelocity() {
    if (currentBody.radius <= 0.0f || currentBody.gravity <= 0.0f) return 1.0f;
    float targetOrbit = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
    float r    = currentBody.radius + targetOrbit;
    float g    = currentBody.gravity;            // rev-2: gravity is m/s² (was surfGrav in g)
    float mu   = g * currentBody.radius * currentBody.radius;
    return sqrtf(mu / r);
}

// V.Orb bar chrome — border + label. Fill is dynamic.
static void _lnchAsDrawVOrbChrome(KCM_TFT &tft) {
    const int16_t LBL_X0 = LNCH_AS_VORB_X_LEFT - LNCH_AS_LBL_OVERHANG;
    const int16_t LBL_W  = LNCH_AS_VORB_W + 2 * LNCH_AS_LBL_OVERHANG;

    // Bar name "V.Orb" (Black_20)
    textCenter(tft, &Roboto_Black_20,
               LBL_X0, LNCH_AS_GAUGE_NAME_Y,
               LBL_W, LNCH_AS_GAUGE_NAME_H,
               "V.Orb", TFT_LIGHT_GREY, TFT_BLACK);

    // Top endpoint label — v_circ at target orbit (body-aware), with unit.
    float vCirc = _lnchAsCircularOrbitVelocity();
    char topBuf[16];
    snprintf(topBuf, sizeof(topBuf), "%d m/s", (int)roundf(vCirc));
    textCenter(tft, &Roboto_Black_16,
               LBL_X0, LNCH_AS_VORB_Y_TOP - LNCH_AS_GAUGE_ENDLBL_H - 6,
               LBL_W, LNCH_AS_GAUGE_ENDLBL_H,
               topBuf, TFT_LIGHT_GREY, TFT_BLACK);

    // Bottom endpoint label "0 m/s"
    textCenter(tft, &Roboto_Black_16,
               LBL_X0, LNCH_AS_VORB_Y_BOT + 5,
               LBL_W, LNCH_AS_GAUGE_ENDLBL_H,
               "0 m/s", TFT_LIGHT_GREY, TFT_BLACK);

    // Border drawn LAST so a label glyph can never nibble the top/bottom borders.
    tft.drawRect(LNCH_AS_VORB_X_LEFT, LNCH_AS_VORB_Y_TOP,
                 LNCH_AS_VORB_W,
                 LNCH_AS_VORB_Y_BOT - LNCH_AS_VORB_Y_TOP + 1,
                 TFT_LIGHT_GREY);
}

// V.Orb bar update — incremental fill update (no full-clear + redraw, so no
// flicker). Fill grows upward from the bottom; we only modify the pixels that
// change between frames.
static void _lnchAsUpdateVOrbBar(KCM_TFT &tft) {
    float vo = state.orbitalVel;
    float vCirc = _lnchAsCircularOrbitVelocity();

    // Clamp to [0, v_circ] — negative orbital velocities saturate at zero,
    // overshoot saturates at full bar.
    float frac;
    if (vo <= 0.0f)         frac = 0.0f;
    else if (vo >= vCirc)   frac = 1.0f;
    else                    frac = vo / vCirc;

    int16_t innerX = LNCH_AS_VORB_X_LEFT + 1;
    int16_t innerW = LNCH_AS_VORB_W - 2;
    int16_t innerYBot = LNCH_AS_VORB_Y_BOT - 1;
    int16_t innerH = innerYBot - (LNCH_AS_VORB_Y_TOP + 1) + 1;

    int16_t fillPx = (int16_t)roundf(frac * (float)innerH);
    int16_t prev = _lnchAsPrevVOrbFillPx;

    if (fillPx == prev) return;

    if (fillPx > prev) {
        // Grow — fill only the newly-added strip at the top
        int16_t strip = fillPx - prev;
        tft.fillRect(innerX, innerYBot - fillPx + 1,
                     innerW, strip,
                     TFT_DARK_GREEN);
    } else {
        // Shrink — clear the strip that's no longer filled
        int16_t strip = prev - fillPx;
        tft.fillRect(innerX, innerYBot - prev + 1,
                     innerW, strip,
                     TFT_BLACK);
    }

    _lnchAsPrevVOrbFillPx = fillPx;
}

// ── FPA (Flight Path Angle) dial ──────────────────────────────────────────────────────
//
// Half-circle dial showing velocity vector orientation relative to the horizon.
// The horizon is a horizontal line across the middle; the arrow points from
// the center at the current FPA. Tick marks at 30° increments.
//
// FPA is computed from surface velocity components:
//     FPA = arctan2(V.Vrt, V.Hrz)  where V.Hrz = sqrt(V.Srf² - V.Vrt²)
//
// Conventions:
//     FPA =  0° → horizontal (prograde / right)
//     FPA = +90° → straight up
//     FPA = -90° → straight down
//
// Special cases:
//     On pad / stationary (|V.Srf| < 0.1) → arrow straight up (90°), no motion
//     V.Vrt > V.Srf (numerical error) → clamp to ±90°

// Compute FPA in degrees from state.
// Returns +90° when stationary (pre-launch) so the arrow defaults to "pointing up".
static float _lnchAsComputeFPA() {
    float vs = state.surfaceVel;
    float vv = state.verticalVel;

    if (vs < 0.1f) return 90.0f;   // stationary: arrow straight up

    // V.Hrz² = V.Srf² - V.Vrt²  (can go slightly negative from rounding)
    float vHrzSq = vs * vs - vv * vv;
    if (vHrzSq < 0.0f) {
        // Vertical component dominates — arrow is ±90° aligned with V.Vrt sign
        return (vv >= 0.0f) ? 90.0f : -90.0f;
    }
    float vHrz = sqrtf(vHrzSq);
    if (vHrz < 0.01f) return (vv >= 0.0f) ? 90.0f : -90.0f;
    return atan2f(vv, vHrz) / DEG_TO_RAD;  // radians → degrees
}

// Compute the target FPA for the current altitude — the "where should I be
// pointing" value for an optimal gravity turn. Starts at +90° (vertical) on
// the pad, smoothly decreases to 0° (horizontal) at target orbit altitude.
//
// Curve: target_FPA = 90 × (1 − √(alt / target_alt))
// Steeper pitch-over at low altitude, flatter near orbit. Matches the shape
// of a typical Kerbin gravity turn — most of the tilt happens in the first
// third of the ascent.
//
// Below 1500 m altitude: hold at 90° (vehicle is still clearing the pad and
// shouldn't tilt yet — matches real rocket launch profiles).
static float _lnchAsComputeTargetFPA() {
    float alt = state.altitude;
    if (alt < 1500.0f) return 90.0f;

    float targetOrbit = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
    if (targetOrbit <= 0.0f) return 0.0f;

    float frac = alt / targetOrbit;
    if (frac >= 1.0f) return 0.0f;   // already at/above target, aim horizontal

    return 90.0f * (1.0f - sqrtf(frac));
}

// Draw a radial tick at angle fpaDeg. tickOut = px outside R, tickIn = px inside.
static void _lnchAsDrawDialTick(KCM_TFT &tft, float fpaDeg,
                                int16_t tickOut, int16_t tickIn, uint16_t color) {
    float rad = fpaDeg * DEG_TO_RAD;
    float cs = cosf(rad), sn = sinf(rad);
    int16_t x0 = LNCH_AS_FPA_CX + (int16_t)roundf((LNCH_AS_FPA_R - tickIn)  * cs);
    int16_t y0 = LNCH_AS_FPA_CY - (int16_t)roundf((LNCH_AS_FPA_R - tickIn)  * sn);
    int16_t x1 = LNCH_AS_FPA_CX + (int16_t)roundf((LNCH_AS_FPA_R + tickOut) * cs);
    int16_t y1 = LNCH_AS_FPA_CY - (int16_t)roundf((LNCH_AS_FPA_R + tickOut) * sn);
    tft.drawLine(x0, y0, x1, y1, color);
}

// Draw the semicircle arc outline (right half, -90°..+90°).
static void _lnchAsDrawDialArc(KCM_TFT &tft, uint16_t color) {
    const int16_t STEP = 2;
    int16_t prevX = LNCH_AS_FPA_CX + LNCH_AS_FPA_R, prevY = LNCH_AS_FPA_CY;
    for (int16_t deg = STEP; deg <= 90; deg += STEP) {
        float rad = deg * DEG_TO_RAD;
        int16_t x = LNCH_AS_FPA_CX + (int16_t)roundf(LNCH_AS_FPA_R * cosf(rad));
        int16_t y = LNCH_AS_FPA_CY - (int16_t)roundf(LNCH_AS_FPA_R * sinf(rad));
        tft.drawLine(prevX, prevY, x, y, color);
        prevX = x; prevY = y;
    }
    prevX = LNCH_AS_FPA_CX + LNCH_AS_FPA_R; prevY = LNCH_AS_FPA_CY;
    for (int16_t deg = -STEP; deg >= -90; deg -= STEP) {
        float rad = deg * DEG_TO_RAD;
        int16_t x = LNCH_AS_FPA_CX + (int16_t)roundf(LNCH_AS_FPA_R * cosf(rad));
        int16_t y = LNCH_AS_FPA_CY - (int16_t)roundf(LNCH_AS_FPA_R * sinf(rad));
        tft.drawLine(prevX, prevY, x, y, color);
        prevX = x; prevY = y;
    }
}

// Draw the doubled (2 px) major ticks + single minor ticks in one place, reused
// by chrome and repair.
static void _lnchAsDrawDialTicks(KCM_TFT &tft) {
    for (int16_t deg = -90; deg <= 90; deg += 30) {
        if (deg == 0) continue;   // 0° is the horizon line
        _lnchAsDrawDialTick(tft, (float)deg, LNCH_AS_FPA_MAJ_OUT, LNCH_AS_FPA_MAJ_IN, TFT_LIGHT_GREY);
        float rad = (float)deg * DEG_TO_RAD, cs = cosf(rad), sn = sinf(rad);
        int16_t dx = (int16_t)roundf(sn), dy = (int16_t)roundf(cs);
        int16_t x0 = LNCH_AS_FPA_CX + (int16_t)roundf((LNCH_AS_FPA_R - LNCH_AS_FPA_MAJ_IN) * cs) + dx;
        int16_t y0 = LNCH_AS_FPA_CY - (int16_t)roundf((LNCH_AS_FPA_R - LNCH_AS_FPA_MAJ_IN) * sn) + dy;
        int16_t x1 = LNCH_AS_FPA_CX + (int16_t)roundf((LNCH_AS_FPA_R + LNCH_AS_FPA_MAJ_OUT) * cs) + dx;
        int16_t y1 = LNCH_AS_FPA_CY - (int16_t)roundf((LNCH_AS_FPA_R + LNCH_AS_FPA_MAJ_OUT) * sn) + dy;
        tft.drawLine(x0, y0, x1, y1, TFT_LIGHT_GREY);
    }
    static const int8_t minorDegs[] = {-75, -45, -15, 15, 45, 75};
    for (uint8_t i = 0; i < sizeof(minorDegs); i++)
        _lnchAsDrawDialTick(tft, (float)minorDegs[i], LNCH_AS_FPA_MIN_OUT, LNCH_AS_FPA_MIN_IN, TFT_LIGHT_GREY);
}

// Angle labels (Black_16, matching the V.Vrt "±500 m/s" endpoint labels), placed
// clear of the tick marks: +90 above the top tick, -90 below the bottom tick, 0 to
// the right of the arc edge. Split out so the target-marker erase can repair the
// label it sits on (the +90 marker overlaps the "+90°" text).
static void _lnchAsDrawDialLabels(KCM_TFT &tft) {
    textCenter(tft, &Roboto_Black_16,
               LNCH_AS_FPA_CX - 32, LNCH_AS_FPA_P90_Y,
               64, LNCH_AS_FPA_LBL_H, "+90\xB0", TFT_LIGHT_GREY, TFT_BLACK);
    textCenter(tft, &Roboto_Black_16,
               LNCH_AS_FPA_CX - 32, LNCH_AS_FPA_M90_Y,
               64, LNCH_AS_FPA_LBL_H, "-90\xB0", TFT_LIGHT_GREY, TFT_BLACK);
    textLeft(tft, &Roboto_Black_16,
             LNCH_AS_FPA_CX + LNCH_AS_FPA_R + LNCH_AS_FPA_MAJ_OUT + 4, LNCH_AS_FPA_CY - 10,
             30, LNCH_AS_FPA_LBL_H, "0\xB0", TFT_LIGHT_GREY, TFT_BLACK);
}

// Dial chrome: arc, horizon, ticks, pivot, "FPA" name, angle labels.
static void _lnchAsDrawDialChrome(KCM_TFT &tft) {
    _lnchAsDrawDialArc(tft, TFT_LIGHT_GREY);
    tft.drawLine(LNCH_AS_FPA_CX, LNCH_AS_FPA_CY,
                 LNCH_AS_FPA_CX + LNCH_AS_FPA_R, LNCH_AS_FPA_CY, TFT_LIGHT_GREY);   // horizon
    _lnchAsDrawDialTicks(tft);
    tft.fillCircle(LNCH_AS_FPA_CX, LNCH_AS_FPA_CY, LNCH_AS_FPA_PIVOT_R, TFT_DARK_GREEN);

    // "FPA" name (Black_20), centered over the dial, above the +90 label.
    textCenter(tft, &Roboto_Black_20,
               LNCH_AS_HDG_CX - 50, LNCH_AS_FPA_NAME_Y,
               100, LNCH_AS_GAUGE_NAME_H,
               "FPA", TFT_LIGHT_GREY, TFT_BLACK);

    _lnchAsDrawDialLabels(tft);

    // Numeric readout box border (matches the HDG number box aesthetic). The
    // value itself is painted inside it by _lnchAsUpdateFpaDial.
    tft.drawRect(LNCH_AS_FPA_VAL_X, LNCH_AS_FPA_VAL_Y,
                 LNCH_AS_FPA_VAL_W, LNCH_AS_FPA_VAL_H, TFT_LIGHT_GREY);
}

// Repair chrome the needle erase may have crossed (horizon + ticks + pivot).
static void _lnchAsRepairDialChrome(KCM_TFT &tft) {
    tft.drawLine(LNCH_AS_FPA_CX, LNCH_AS_FPA_CY,
                 LNCH_AS_FPA_CX + LNCH_AS_FPA_R, LNCH_AS_FPA_CY, TFT_LIGHT_GREY);
    _lnchAsDrawDialTicks(tft);
    tft.fillCircle(LNCH_AS_FPA_CX, LNCH_AS_FPA_CY, LNCH_AS_FPA_PIVOT_R, TFT_DARK_GREEN);
}

// Draw (or erase) the needle at angle fpaDeg: rotated-rectangle shaft + triangle head.
static void _lnchAsDrawDialArrow(KCM_TFT &tft, float fpaDeg, uint16_t color) {
    float rad = fpaDeg * DEG_TO_RAD;
    float cs = cosf(rad), sn = sinf(rad);
    float alongX = cs, alongY = -sn, perpX = sn, perpY = cs;
    float CX = (float)LNCH_AS_FPA_CX, CY = (float)LNCH_AS_FPA_CY;
    float hw = (float)LNCH_AS_FPA_SHAFT_W / 2.0f;
    float L  = (float)LNCH_AS_FPA_SHAFT_LEN;
    int16_t blX = (int16_t)roundf(CX + perpX * hw),        blY = (int16_t)roundf(CY + perpY * hw);
    int16_t brX = (int16_t)roundf(CX - perpX * hw),        brY = (int16_t)roundf(CY - perpY * hw);
    int16_t tlX = (int16_t)roundf(CX + alongX * L + perpX * hw), tlY = (int16_t)roundf(CY + alongY * L + perpY * hw);
    int16_t trX = (int16_t)roundf(CX + alongX * L - perpX * hw), trY = (int16_t)roundf(CY + alongY * L - perpY * hw);
    tft.fillTriangle(blX, blY, brX, brY, trX, trY, color);
    tft.fillTriangle(blX, blY, trX, trY, tlX, tlY, color);
    float R = (float)LNCH_AS_FPA_ARROW_R, hhw = (float)LNCH_AS_FPA_HEAD_W / 2.0f;
    int16_t tipX = (int16_t)roundf(CX + alongX * R),           tipY = (int16_t)roundf(CY + alongY * R);
    int16_t hblX = (int16_t)roundf(CX + alongX * L + perpX * hhw), hblY = (int16_t)roundf(CY + alongY * L + perpY * hhw);
    int16_t hbrX = (int16_t)roundf(CX + alongX * L - perpX * hhw), hbrY = (int16_t)roundf(CY + alongY * L - perpY * hhw);
    tft.fillTriangle(hblX, hblY, hbrX, hbrY, tipX, tipY, color);
}

// Draw (or erase) the target-FPA marker: small triangle just outside the arc,
// pointing inward.
static void _lnchAsDrawDialTargetMarker(KCM_TFT &tft, float fpaDeg, uint16_t color) {
    float rad = fpaDeg * DEG_TO_RAD;
    float cs = cosf(rad), sn = sinf(rad);
    float alongX = cs, alongY = -sn, perpX = sn, perpY = cs;
    const float OUT = 11.0f, DEPTH = 11.0f, HALF = 7.0f;   // enlarged target marker
    float CX = (float)LNCH_AS_FPA_CX, CY = (float)LNCH_AS_FPA_CY;
    float rTip = (float)LNCH_AS_FPA_R + OUT, rBase = rTip + DEPTH;
    int16_t tipX = (int16_t)roundf(CX + alongX * rTip),  tipY = (int16_t)roundf(CY + alongY * rTip);
    int16_t blX  = (int16_t)roundf(CX + alongX * rBase + perpX * HALF), blY = (int16_t)roundf(CY + alongY * rBase + perpY * HALF);
    int16_t brX  = (int16_t)roundf(CX + alongX * rBase - perpX * HALF), brY = (int16_t)roundf(CY + alongY * rBase - perpY * HALF);
    tft.fillTriangle(tipX, tipY, blX, blY, brX, brY, color);
}

// Update: needle, target marker, numeric readout (below the dial).
static void _lnchAsUpdateFpaDial(KCM_TFT &tft) {
    float fpa = _lnchAsComputeFPA();
    if (fpa >  90.0f) fpa =  90.0f;
    if (fpa < -90.0f) fpa = -90.0f;
    int16_t iFpa    = (int16_t)roundf(fpa);
    int16_t iTarget = (int16_t)roundf(_lnchAsComputeTargetFPA());
    bool arrowChanged  = (iFpa != _lnchAsPrevFpaReadout);
    bool targetChanged = (iTarget != _lnchAsPrevFpaTarget);
    if (!arrowChanged && !targetChanged) return;

    if (targetChanged && _lnchAsPrevFpaTarget != -9999) {
        _lnchAsDrawDialTargetMarker(tft, (float)_lnchAsPrevFpaTarget, TFT_BLACK);
        // The marker sits just outside the arc where the +90/0/-90 labels live, so
        // its black erase can nibble a label — repair them (cheap, target moves rarely).
        _lnchAsDrawDialLabels(tft);
    }
    if (arrowChanged && _lnchAsPrevFpaReadout != -9999) {
        _lnchAsDrawDialArrow(tft, (float)_lnchAsPrevFpaReadout, TFT_BLACK);
        _lnchAsRepairDialChrome(tft);
    }
    if (arrowChanged) {
        _lnchAsDrawDialArrow(tft, (float)iFpa, TFT_DARK_GREEN);
        tft.fillCircle(LNCH_AS_FPA_CX, LNCH_AS_FPA_CY, LNCH_AS_FPA_PIVOT_R, TFT_DARK_GREEN);
    }
    if (targetChanged || arrowChanged)
        _lnchAsDrawDialTargetMarker(tft, (float)iTarget, TFT_YELLOW);

    // Numeric readout inside the bordered box under the dial.
    if (arrowChanged) {
        char buf[8];
        snprintf(buf, sizeof(buf), "%+d\xB0", iFpa);
        tft.fillRect(LNCH_AS_FPA_VAL_X + 1, LNCH_AS_FPA_VAL_Y + 1,
                     LNCH_AS_FPA_VAL_W - 2, LNCH_AS_FPA_VAL_H - 2, TFT_BLACK);
        textCenter(tft, &Roboto_Black_24,
                   LNCH_AS_FPA_VAL_X, LNCH_AS_FPA_VAL_Y + 1,
                   LNCH_AS_FPA_VAL_W, LNCH_AS_FPA_VAL_H - 2, buf, TFT_DARK_GREEN, TFT_BLACK);
    }
    _lnchAsPrevFpaReadout = iFpa;
    _lnchAsPrevFpaTarget  = iTarget;
}

// ── Heading tape ──────────────────────────────────────────────────────────────────────

// Heading number box (cached) — current vessel heading, "NNN°".
static void _lnchAsUpdateHdgBox(KCM_TFT &tft, float hdg) {
    int16_t iHdg = (int16_t)roundf(hdg) % 360;
    if (iHdg < 0) iHdg += 360;
    if (iHdg == _lnchAsPrevHdgBox) return;

    char buf[8];
    if (_lnchAsPrevHdgBox >= 0) {           // erase previous value (black-on-black)
        snprintf(buf, sizeof(buf), "%03d\xB0", _lnchAsPrevHdgBox);
        eraseCenteredValue(tft, &Roboto_Black_24, LNCH_AS_HDG_BOX_X, LNCH_AS_HDG_BOX_Y + 1,
                   LNCH_AS_HDG_BOX_W, LNCH_AS_HDG_BOX_H - 2, buf, TFT_BLACK);
    }
    snprintf(buf, sizeof(buf), "%03d\xB0", iHdg);
    textCenter(tft, &Roboto_Black_24, LNCH_AS_HDG_BOX_X, LNCH_AS_HDG_BOX_Y + 1,
               LNCH_AS_HDG_BOX_W, LNCH_AS_HDG_BOX_H - 2, buf, TFT_DARK_GREEN, TFT_BLACK);
    _lnchAsPrevHdgBox = iHdg;
}

// Redraw the heading tape strip: ticks, N/E/S/W + degree labels, and markers
// (90° launch bug + velocity-vector heading). Tape center = current vessel heading.
static void _lnchAsDrawHdgTape(KCM_TFT &tft, float hdg) {
    while (hdg <   0.0f) hdg += 360.0f;
    while (hdg >= 360.0f) hdg -= 360.0f;

    tft.fillRect(LNCH_AS_HDG_X, LNCH_AS_HDG_TAPE_Y, LNCH_AS_HDG_W, LNCH_AS_HDG_TAPE_H, TFT_BLACK);
    tft.drawRect(LNCH_AS_HDG_BOX_X, LNCH_AS_HDG_BOX_Y, LNCH_AS_HDG_BOX_W, LNCH_AS_HDG_BOX_H, TFT_LIGHT_GREY);
    _lnchAsPrevHdgBox = -1;   // fill blackened the box interior — force number redraw

    int16_t halfDeg = (int16_t)(LNCH_AS_HDG_W / (2.0f * LNCH_AS_HDG_SCALE)) + 1;
    tft.setFont(Roboto_Black_12);
    for (int16_t d = -halfDeg; d <= halfDeg; d++) {
        float deg = hdg + (float)d;
        while (deg <   0.0f) deg += 360.0f;
        while (deg >= 360.0f) deg -= 360.0f;
        int16_t px = LNCH_AS_HDG_CX + (int16_t)roundf((float)d * LNCH_AS_HDG_SCALE);
        if (px <= LNCH_AS_HDG_X || px >= LNCH_AS_HDG_X + LNCH_AS_HDG_W) continue;
        if (px >= LNCH_AS_HDG_SUPP_LO && px <= LNCH_AS_HDG_SUPP_HI) continue;
        int16_t ideg = (int16_t)roundf(deg); if (ideg == 360) ideg = 0;

        if (ideg % 10 == 0) {
            tft.drawLine(px, LNCH_AS_HDG_TAPE_Y, px, LNCH_AS_HDG_TAPE_Y + 9, TFT_LIGHT_GREY);
            const char *lbl; uint16_t col; char nb[8];
            if      (ideg ==   0) { lbl = "N"; col = TFT_YELLOW; }
            else if (ideg ==  90) { lbl = "E"; col = TFT_WHITE;  }
            else if (ideg == 180) { lbl = "S"; col = TFT_WHITE;  }
            else if (ideg == 270) { lbl = "W"; col = TFT_WHITE;  }
            else { snprintf(nb, sizeof(nb), "%d", ideg); lbl = nb; col = TFT_LIGHT_GREY; }
            tft.setTextColor(col, TFT_BLACK);
            uint8_t lw = strlen(lbl) * 8;
            int16_t cx = px - (int16_t)(lw / 2);
            // Skip the label entirely if it would run off either edge — clamping it
            // to the edge makes labels stall and bunch up as the tape scrolls.
            if (cx >= LNCH_AS_HDG_X + 1 && cx + lw <= LNCH_AS_HDG_X + LNCH_AS_HDG_W - 1) {
                tft.setCursor(cx, LNCH_AS_HDG_TAPE_Y + 11);
                tft.print(lbl);
            }
        } else if (ideg % 2 == 0) {
            tft.drawLine(px, LNCH_AS_HDG_TAPE_Y, px, LNCH_AS_HDG_TAPE_Y + 5, TFT_DARK_GREY);
        }
    }

    // Markers — downward triangles inside the tape (pegged to the edges, hidden
    // behind the center box's suppress zone).
    auto drawMarker = [&](float mHdg, uint16_t col) {
        float diff = mHdg - hdg;
        while (diff >  180.0f) diff -= 360.0f;
        while (diff < -180.0f) diff += 360.0f;
        int16_t px = LNCH_AS_HDG_CX + (int16_t)roundf(diff * LNCH_AS_HDG_SCALE);
        int16_t pxMin = LNCH_AS_HDG_X + 7, pxMax = LNCH_AS_HDG_X + LNCH_AS_HDG_W - 7;
        if (px < pxMin) px = pxMin;
        if (px > pxMax) px = pxMax;
        if (px >= LNCH_AS_HDG_SUPP_LO && px <= LNCH_AS_HDG_SUPP_HI) return;
        tft.fillTriangle(px,     LNCH_AS_HDG_TAPE_Y + 18,
                         px - 6, LNCH_AS_HDG_TAPE_Y + 2,
                         px + 6, LNCH_AS_HDG_TAPE_Y + 2, col);
    };
    // Velocity-vector heading (green), only when actually moving.
    if (state.surfaceVel >= LNCH_AS_HDG_VEL_MIN_MS)
        drawMarker(state.srfVelHeading, TFT_NEON_GREEN);
    // 90° launch-azimuth bug (amber) drawn last so it sits on top.
    drawMarker(LNCH_AS_HDG_LAUNCH_AZ, TFT_YELLOW);
}

// Static chrome: "HDG" label + initial tape/box. Resets change-detection state.
static void _lnchAsDrawHdgTapeChrome(KCM_TFT &tft) {
    _lnchAsPrevHdg = -9999.0f; _lnchAsPrevHdgBox = -9999; _lnchAsPrevVelHdg = -9999.0f;
    textCenter(tft, &Roboto_Black_20, LNCH_AS_HDG_X, LNCH_AS_HDG_NAME_Y,
               LNCH_AS_HDG_W, 24, "HDG", TFT_LIGHT_GREY, TFT_BLACK);
    _lnchAsDrawHdgTape(tft, state.heading);
    _lnchAsUpdateHdgBox(tft, state.heading);
}

// Per-frame update — redraw the strip when heading or velocity heading changes.
static void _lnchAsUpdateHdgTape(KCM_TFT &tft) {
    float hdg = state.heading;
    bool dirty = fabsf(hdg - _lnchAsPrevHdg) >= 0.3f
              || fabsf(state.srfVelHeading - _lnchAsPrevVelHdg) >= 0.3f;
    if (dirty) {
        _lnchAsDrawHdgTape(tft, hdg);
        _lnchAsPrevHdg    = hdg;
        _lnchAsPrevVelHdg = state.srfVelHeading;
    }
    _lnchAsUpdateHdgBox(tft, hdg);
}

// ── Atmosphere gauge ──────────────────────────────────────────────────────────────────
//
// Vertical bar showing current atmospheric density as a fraction of the body's
// sea-level density (0..1). Sea level (dense) at the top, vacuum at the bottom;
// a white indicator slides down as the vessel climbs out of the atmosphere. On
// bodies with no atmosphere the indicator parks in the OFF_BLACK bottom segment.
//
// Data inputs from AppState:
//   state.airDensity   — current air density in kg/m³ (0 in vacuum)
//   state.inAtmo       — true if vessel is within body atmosphere
//   currentBody        — name-keyed lookup for sea-level reference density

// Body sea-level density lookup (kg/m³). Only atmosphere bodies listed; bodies
// not in the table are treated as non-atmospheric (gauge shows "NO ATM").
//
// Values are KSP stock sea-level densities per the Kerbal Space Program wiki
// entries. Simpit's atmoConditionsMessage doesn't expose sea-level reference
// density directly, so we maintain this per-body lookup. Atmosphere-gauge
// depth is then computed as (currentDensity / sealevelDensity)^0.25 to match
// KSP's in-game gauge.
static float _lnchAsBodySurfaceDensity() {
    // Early bail for bodies the body table explicitly flags as non-atmosphere.
    if (currentBody.cond && strcmp(currentBody.cond, "Vacuum") == 0) return 0.0f;

    const char *name = currentBody.soiName;
    if (!name || name[0] == '\0') return 0.0f;

    // Case-sensitive exact match against SOI name reported by Simpit.
    if      (strcmp(name, "Kerbin") == 0) return 1.225f;
    else if (strcmp(name, "Eve")    == 0) return 6.150f;
    else if (strcmp(name, "Duna")   == 0) return 0.0678f;
    else if (strcmp(name, "Jool")   == 0) return 14.00f;
    else if (strcmp(name, "Laythe") == 0) return 1.700f;

    // Non-atmosphere bodies (Mun, Minmus, Ike, Gilly, Dres, Moho, Eeloo,
    // Bop, Pol, Vall, Tylo) → return 0 to signal "no atmosphere".
    return 0.0f;
}

// Compute atmosphere fill fraction (0..1). Returns <0 to signal "no atmosphere"
// on this body, which the caller uses to draw the "NO ATM" overlay.
//
// Formula matches KSP's stock atmosphere gauge: depth = (ρ / ρ_SL)^0.25
// This is a 4th-root relationship (not linear) which makes the gauge emphasize
// the high end — e.g. on Kerbin ~90% at 1.8 km, ~50% at 11 km, 10% at ~55 km.
// Source: KerbalSimpit forum discussion (wile1411, Aug 2019) confirmed against
// KSP's in-game gauge.
static float _lnchAsAtmoFraction() {
    float maxD = _lnchAsBodySurfaceDensity();
    if (maxD <= 0.0f) return -1.0f;   // no atmosphere
    float ratio = state.airDensity / maxD;
    if (ratio <= 0.0f) return 0.0f;
    if (ratio >= 1.0f) return 1.0f;
    // depth = ratio^0.25 = sqrt(sqrt(ratio))  — two sqrtfs are cheaper than powf
    return sqrtf(sqrtf(ratio));
}

// Vertical atmospheric-scale geometry: atmYBot = the y at frac 0 (bottom of the
// atmospheric portion, just above the OFF_BLACK parking segment); atmH = scale
// height in px. Sea level (frac 1) is at the top interior row.
static void _lnchAsAtmoScaleGeom(int16_t &atmYBot, int16_t &atmH) {
    int16_t innerY0 = LNCH_AS_ATMO_Y_TOP + 1;
    int16_t innerY1 = LNCH_AS_ATMO_Y_BOT - 1;
    int16_t innerH  = innerY1 - innerY0 + 1;
    int16_t noAtmH  = (int16_t)roundf(LNCH_AS_ATMO_NOATM_H_FRAC * innerH);
    atmYBot = innerY1 - noAtmH;
    atmH    = atmYBot - innerY0 + 1;
}

// Map an atmospheric fraction (0..1) to a y-pixel on the vertical scale
// (0 = bottom / vacuum end, 1 = top / sea level).
static int16_t _lnchAsAtmoFracToY(float frac) {
    int16_t atmYBot, atmH;
    _lnchAsAtmoScaleGeom(atmYBot, atmH);
    if (frac < 0.0f) frac = 0.0f;
    if (frac > 1.0f) frac = 1.0f;
    return atmYBot - (int16_t)roundf(frac * (float)(atmH - 1));
}

// Draw the stable vertical zone fill (SKY top → NAVY, OFF_BLACK parking bottom)
// plus horizontal tick marks along the left of the bar.
static void _lnchAsDrawAtmoBackground(KCM_TFT &tft) {
    int16_t innerX0 = LNCH_AS_ATMO_X_LEFT + 1;
    int16_t innerY0 = LNCH_AS_ATMO_Y_TOP + 1;
    int16_t innerY1 = LNCH_AS_ATMO_Y_BOT - 1;
    int16_t innerW  = LNCH_AS_ATMO_W - 1;
    int16_t atmYBot, atmH;
    _lnchAsAtmoScaleGeom(atmYBot, atmH);

    int16_t y75 = _lnchAsAtmoFracToY(LNCH_AS_ATMO_ZONE2_FRAC);  // SKY ↔ FRENCH_BLUE
    int16_t y35 = _lnchAsAtmoFracToY(LNCH_AS_ATMO_ZONE1_FRAC);  // FRENCH_BLUE ↔ NAVY

    tft.fillRect(innerX0, innerY0, innerW, y75 - innerY0,        TFT_SKY);          // dense (top)
    tft.fillRect(innerX0, y75,     innerW, y35 - y75,            TFT_FRENCH_BLUE);  // medium
    tft.fillRect(innerX0, y35,     innerW, atmYBot - y35 + 1,    TFT_NAVY);         // near vacuum
    if (atmYBot + 1 <= innerY1)
        tft.fillRect(innerX0, atmYBot + 1, innerW, innerY1 - atmYBot, TFT_OFF_BLACK);  // parking

    int16_t tickWMajor = (int16_t)roundf(LNCH_AS_ATMO_TICK_W_FRAC_MAJOR * innerW);
    int16_t tickWMinor = (int16_t)roundf(LNCH_AS_ATMO_TICK_W_FRAC_MINOR * innerW);
    if (tickWMajor < 1) tickWMajor = 1;
    if (tickWMinor < 1) tickWMinor = 1;
    // Ticks in the bright SKY zone (above y75) use a darker color so they don't
    // wash out; NAVY/FRENCH_BLUE zones keep light-grey ticks.
    for (int16_t i = 0; i < LNCH_AS_ATMO_TICK_COUNT_MAJOR; i++) {
        int16_t ty = _lnchAsAtmoFracToY((float)i / (float)LNCH_AS_ATMO_TICK_COUNT_MAJOR);
        uint16_t tc = (ty < y75) ? LNCH_AS_ATMO_TICK_SKY_COLOR : TFT_LIGHT_GREY;
        tft.drawLine(innerX0, ty, innerX0 + tickWMajor - 1, ty, tc);
    }
    for (int16_t i = 0; i < LNCH_AS_ATMO_TICK_COUNT_MINOR; i++) {
        int16_t ty = _lnchAsAtmoFracToY(((float)i + 0.5f) / (float)LNCH_AS_ATMO_TICK_COUNT_MINOR);
        uint16_t tc = (ty < y75) ? LNCH_AS_ATMO_TICK_SKY_COLOR : TFT_LIGHT_GREY;
        tft.drawLine(innerX0, ty, innerX0 + tickWMinor - 1, ty, tc);
    }
}

// Which velocity is the meaningful one. Surface speed low down; orbital once the
// vessel is leaving the air, where that is the number an ascent is flown on. Altitude
// is the right axis for this question, with hysteresis so the value does not flicker
// at the boundary.
//
// This was once the same formula as the ASCENT/CIRCULARISATION phase switch. It no
// longer is -- that switch keys off the engine, since altitude could not tell a
// spaceplane still burning from one coasting -- and the two are independent decisions:
// which velocity to show, and which phase of the arc this is.
//
// It used to drive a label swap on a readout row. That row is now the V.Orb gauge's own
// digital window, and this drives the window instead.
static bool _lnchAsShowOrbitalVelocity() {
    float bodyRad  = (currentBody.radius > 0.0f) ? currentBody.radius : DEFAULT_BODY_RADIUS_M;
    bool  ascending = (state.verticalVel >= 0.0f);
    float switchAlt = ascending ? (bodyRad * ORB_SWITCH_ALT_FRAC_ASC)
                                : (bodyRad * ORB_SWITCH_ALT_FRAC_DESC);
    return (state.altitude > switchAlt);
}


// ── Gauge digital windows ─────────────────────────────────────────────────────────────
// One value per bar, centred in the row between the gauge name and its top endpoint
// label. Each keeps its own last-drawn string so an unchanged value costs nothing; the
// box is cleared and redrawn rather than tracked per glyph, which is cheap here because
// the row is 72 px wide and hardware fillRect is the fastest thing this driver does.
// Widest that fits the 72 px bar window at Black_20 is five digits and a sign
// ("-1,234" is 62 px); six digits ("123,456", 77 px) would not. That is 100 km/s, and
// this screen is only up below the coast latch, where V.Orb tops out near 3,000.
static String _lnchAsPrevVVrtVal, _lnchAsPrevVOrbVal;

static void _lnchAsGaugeValue(KCM_TFT &tft, int16_t lblX0, int16_t lblW,
                              const String &val, uint16_t fg, String &prev) {
    if (val == prev) return;
    // Boxed, so the window reads as part of its gauge rather than as loose text
    // floating above it. Border drawn every time: the fill that clears the old value
    // covers the inside only, so the frame is never touched, but drawing it here keeps
    // the window whole after a chrome repaint without a separate code path.
    tft.fillRect(lblX0 + 1, LNCH_AS_GAUGE_VAL_Y + 1,
                 lblW - 2, LNCH_AS_GAUGE_VAL_H - 2, TFT_BLACK);
    tft.drawRect(lblX0, LNCH_AS_GAUGE_VAL_Y, lblW, LNCH_AS_GAUGE_VAL_H, TFT_GREY);
    textCenter(tft, &Roboto_Black_20, lblX0, LNCH_AS_GAUGE_VAL_Y, lblW,
               LNCH_AS_GAUGE_VAL_H, val, fg, TFT_BLACK);
    prev = val;
}

// Dynamic pressure, from the density the ATMO gauge is already drawing and surface
// speed: q = 0.5 * rho * v^2, in pascals. Shown in kPa, which keeps a Kerbin ascent's
// 10-15 kPa peak to three characters instead of five.
//
// This is the number the ATMO gauge cannot show. Density falls monotonically from the
// pad; q rises to a peak around 5-8 km and then falls, and that peak is the one
// structural event of an ascent.
static float _lnchAsDynPressureKPa() {
    const float v = state.surfaceVel;
    return 0.5f * state.airDensity * v * v / 1000.0f;
}

// Chrome: name label + stable zone fill + border.
static void _lnchAsDrawAtmoChrome(KCM_TFT &tft) {
    // Name box matches the column's true extent (triangle to triangle), not a fixed
    // 100 px centred on the bar: the wider box reached x=252 and overlapped the V.Vrt
    // window at 248, so once both carried a border the two drew in the same four columns
    // and the shared edge flickered between them every frame.
    //
    // This column has a name and no value window. A percentage restating where the
    // triangle already points said nothing, and the time-to-vacuum that briefly replaced
    // it was a different quantity from the one the bar plots, which forced the column
    // name to label the number instead of the gauge. The bar is the instrument here --
    // sky-to-navy with a triangle on each side -- and it does not need a number under it
    // to be read. Q, on the right column, is the atmospheric number worth digits, and it
    // is the one the bar genuinely cannot show.
    const int16_t nameX0 = LNCH_AS_ATMO_X_LEFT - LNCH_AS_ATMO_TRI_GAP - LNCH_AS_ATMO_TRI_W;
    const int16_t nameW  = LNCH_AS_ATMO_RIGHT_EXT - nameX0;
    textCenter(tft, &Roboto_Black_20,
               nameX0, LNCH_AS_GAUGE_NAME_Y, nameW, LNCH_AS_GAUGE_NAME_H,
               "ATMO", TFT_LIGHT_GREY, TFT_BLACK);
    _lnchAsDrawAtmoBackground(tft);
    tft.drawRect(LNCH_AS_ATMO_X_LEFT, LNCH_AS_ATMO_Y_TOP,
                 LNCH_AS_ATMO_W + 1,
                 LNCH_AS_ATMO_Y_BOT - LNCH_AS_ATMO_Y_TOP + 1,
                 TFT_LIGHT_GREY);
}

// Twin triangle indicators: one each side of the bar, pointing toward it, at
// centerY. Pass TFT_BLACK to erase (both live on the black background outside the
// bar, so no zone/tick reconstruction is needed).
static void _lnchAsDrawAtmoTriangle(KCM_TFT &tft, int16_t centerY, uint16_t color) {
    // Left triangle — points right, tip just left of the bar.
    int16_t lTipX  = LNCH_AS_ATMO_X_LEFT - LNCH_AS_ATMO_TRI_GAP;
    int16_t lBaseX = lTipX - LNCH_AS_ATMO_TRI_W;
    tft.fillTriangle(lTipX,  centerY,
                     lBaseX, centerY - LNCH_AS_ATMO_TRI_HALF_H,
                     lBaseX, centerY + LNCH_AS_ATMO_TRI_HALF_H,
                     color);
    // Right triangle — points left, tip just right of the bar.
    int16_t rTipX  = LNCH_AS_ATMO_X_RIGHT + LNCH_AS_ATMO_TRI_GAP;
    int16_t rBaseX = rTipX + LNCH_AS_ATMO_TRI_W;
    tft.fillTriangle(rTipX,  centerY,
                     rBaseX, centerY - LNCH_AS_ATMO_TRI_HALF_H,
                     rBaseX, centerY + LNCH_AS_ATMO_TRI_HALF_H,
                     color);
}

// Update: slide the indicator to the current density fraction (or park it in the
// OFF_BLACK segment on a non-atmosphere body). The bar background is stable
// chrome; only the triangle moves.
static void _lnchAsUpdateAtmoGauge(KCM_TFT &tft) {
    float frac = _lnchAsAtmoFraction();
    // In vacuum (airDensity 0, frac == 0) or on a non-atmosphere body (frac < 0),
    // park the indicators centered in the dark OFF_BLACK segment at the bottom
    // rather than pegging them at the frac=0 line at the top of that segment.
    bool  vacuum = (frac <= 0.0f);

    int16_t innerY1 = LNCH_AS_ATMO_Y_BOT - 1;
    int16_t atmYBot, atmH;
    _lnchAsAtmoScaleGeom(atmYBot, atmH);

    int16_t triY = vacuum ? (int16_t)((atmYBot + 1 + innerY1) / 2)
                          : _lnchAsAtmoFracToY(frac);
    if (triY == _lnchAsPrevAtmoTriY) return;

    if (_lnchAsPrevAtmoTriY >= 0) {
        _lnchAsDrawAtmoTriangle(tft, _lnchAsPrevAtmoTriY, TFT_BLACK);
    }
    _lnchAsDrawAtmoTriangle(tft, triY, TFT_WHITE);
    _lnchAsPrevAtmoTriY = triY;
}

// ── STAGE indicator button ────────────────────────────────────────────────────
// Sits in the whitespace between the FPA readout and the HDG tape. Lights red
// (white text) when the current stage's ΔV is spent — a "time to stage" cue —
// and otherwise shows the standard off-look. Change-detected: redraws only when
// the active state flips.
static void _lnchAsUpdateStageButton(KCM_TFT &tft) {
    int8_t active = (state.stageDeltaV <= LNCH_AS_STAGE_EMPTY_MS) ? 1 : 0;
    if (active == _lnchAsPrevStageActive) return;

    static const ButtonLabel STAGE_LBL = {
        "STAGE",
        TFT_DARK_GREY,    // fontColorOff
        TFT_WHITE,        // fontColorOn
        TFT_OFF_BLACK,    // backgroundColorOff
        TFT_RED,          // backgroundColorOn
        TFT_GREY,         // borderColorOff
        TFT_GREY,         // borderColorOn
    };
    drawButton(tft, LNCH_AS_STAGE_X, LNCH_AS_STAGE_Y,
               LNCH_AS_STAGE_W, LNCH_AS_STAGE_H,
               STAGE_LBL, &Roboto_Black_28, active != 0);
    _lnchAsPrevStageActive = active;
}

// Left panel chrome — draw ladder (dynamic, dependent on current state),
// V.Vrt / V.Orb bars, FPA dial, heading tape, and atmosphere (static chrome).
static void _lnchAsDrawLeftPanelChrome(KCM_TFT &tft) {
    _lnchAsDrawLadderChrome(tft);
    _lnchAsDrawVVrtChrome(tft);
    _lnchAsDrawVOrbChrome(tft);
    _lnchAsDrawDialChrome(tft);
    _lnchAsDrawHdgTapeChrome(tft);
    _lnchAsDrawAtmoChrome(tft);
    // Record scale that was just drawn, so UpdateLadderMarkers doesn't trigger
    // an immediate spurious redraw on the first frame after chrome.
    _lnchAsLastDrawnScaleTop = _lnchAsLadderScaleTop();
}

// Called every frame: update the ladder markers, bars, dial, heading tape, atmo.
// The three bar gauges' digital windows. Their values used to be rows 0-4 of the
// readout column; they now sit on the gauges they belong to.
static void _lnchAsUpdateGaugeValues(KCM_TFT &tft) {
    // Two windows, not three: the atmosphere column carries a name and a bar only.
    // See _lnchAsDrawAtmoChrome() for why.
    // V.Vrt — signed, red descending, matching the bar's own fill colours.
    //
    // Bare number, no unit. The window is 72 px and fmtMs() carries " m/s", which makes
    // even "-12.0 m/s" 90 px wide; the bar's own endpoint labels already say +/-500 m/s
    // directly above and below it, so repeating the unit is what would not fit AND what
    // says nothing.
    {
        const int16_t x0 = LNCH_AS_VVRT_X_LEFT - LNCH_AS_LBL_OVERHANG;
        const int16_t w  = LNCH_AS_VVRT_W + 2 * LNCH_AS_LBL_OVERHANG;
        _lnchAsGaugeValue(tft, x0, w,
                          formatSepI64((int64_t)lroundf(state.verticalVel)),
                          (state.verticalVel < 0.0f) ? TFT_RED : TFT_DARK_GREEN,
                          _lnchAsPrevVVrtVal);
    }
    // V.Orb — surface speed low down, orbital once that is the meaningful number.
    // Same swap the readout row used to make, on the same test.
    {
        const int16_t x0 = LNCH_AS_VORB_X_LEFT - LNCH_AS_LBL_OVERHANG;
        const int16_t w  = LNCH_AS_VORB_W + 2 * LNCH_AS_LBL_OVERHANG;
        const bool orb = _lnchAsShowOrbitalVelocity();
        _lnchAsGaugeValue(tft, x0, w,
                          formatSepI64((int64_t)lroundf(orb ? state.orbitalVel
                                                            : state.surfaceVel)),
                          TFT_DARK_GREEN, _lnchAsPrevVOrbVal);
    }
}

static void _lnchAsDrawLeftPanelValues(KCM_TFT &tft) {
    _lnchAsUpdateLadderMarkers(tft);
    _lnchAsUpdateGaugeValues(tft);
    _lnchAsUpdateVVrtBar(tft);
    _lnchAsUpdateVOrbBar(tft);
    _lnchAsUpdateFpaDial(tft);
    _lnchAsUpdateHdgTape(tft);
    _lnchAsUpdateAtmoGauge(tft);
    _lnchAsUpdateStageButton(tft);
}


// Ascent/Circ velocity readouts use the shared fmtMs() (thousands-separated at
// >=1000, 1 decimal below) for cross-screen consistency. fmtMs is never wider
// than the old 1-decimal form here (it drops the decimal and adds a comma at
// >=1000), so it stays within the tight ~140 px value region for "ΔV.STG".

// Reset all ascent-phase change-detection state + PrintState. Called at chrome
// time to force a full redraw.
static void _lnchAsResetState() {
    _lnchAsPrevTimeToAp   = -1 << 30;
    _lnchAsPrevThrottle   = -1;
    _lnchAsPrevQ          = -1 << 30;
    _lnchAsPrevMach       = -9999;
    _lnchAsPrevG          = -1 << 30;
    _lnchAsPrevTBurn      = -1 << 30;
    _lnchAsPrevDVStg      = -1 << 30;
    _lnchAsPrevTimeToApFg = 0xFFFF;
    _lnchAsPrevThrFg      = 0xFFFF; _lnchAsPrevThrBg  = 0xFFFF;
    _lnchAsPrevQFg        = 0xFFFF; _lnchAsPrevQBg    = 0xFFFF;
    _lnchAsPrevGFg        = 0xFFFF; _lnchAsPrevGBg    = 0xFFFF;
    _lnchAsPrevTBurnFg    = 0xFFFF; _lnchAsPrevTBurnBg = 0xFFFF;
    _lnchAsPrevDVStgFg    = 0xFFFF; _lnchAsPrevDVStgBg = 0xFFFF;
    // Gauge digital windows: forget the last string so each redraws with its chrome.
    _lnchAsPrevVVrtVal = ""; _lnchAsPrevVOrbVal = "";
    for (uint8_t i = 0; i < LNCH_AS2_NROWS; i++) {
        _lnchAsPs[i].prevWidth  = 0;
        _lnchAsPs[i].prevBg     = 0x0001;  // sentinel
        _lnchAsPs[i].prevHeight = 0;
    }
    // Also invalidate the global printState[screen_LNCH][*] slots — these are
    // shared with the orbital phase's drawValue() calls. Stale state from a
    // prior orbital-mode chrome (which uses Roboto_Black_40) can otherwise
    // cause the first ascent-mode draw to paint an incorrect-height region.
    for (uint8_t i = 0; i < ROW_COUNT; i++) {
        printState[screen_LNCH][i].prevWidth  = 0;
        printState[screen_LNCH][i].prevBg     = 0x0001;
        printState[screen_LNCH][i].prevHeight = 0;
    }
    _lnchAsPrevVesselPx       = -1;
    _lnchAsPrevApAPx          = -1;
    _lnchAsPrevApAValid       = false;
    _lnchAsPrevVVrtFillPx     = 0;
    _lnchAsPrevVOrbFillPx     = 0;
    _lnchAsCurrScaleTop       = 0.0f;  // forces grow-from-zero on next query
    _lnchAsLastDrawnScaleTop  = 0.0f;
    _lnchAsPrevFpaReadout     = -9999;
    _lnchAsPrevFpaTarget      = -9999;
    _lnchAsPrevAtmoTriY       = -1;
    _lnchAsPrevStageActive    = -1;
}


// Row labels. The unit ("m/s") is included in labels for velocity rows to make
// the row purpose unambiguous. Other units follow KSP convention (formatAlt for
// altitudes, formatTime for time-based values, formatPerc for throttle).
// Row 3 ("V.Srf" / "V.Orb") is label-swapped by the update function based on
// altitude — at high altitude the value switches from surface velocity to
// orbital velocity.
// Stg.Brn, not T.Brn: it is Simpit's BURNTIME_MESSAGE -- seconds of thrust left in the
// stage, not a countdown of any particular burn. The old label read like a time-to.
// The circularisation phase uses the same name for the same field.
static const char *_lnchAsLabels[LNCH_AS2_NROWS] = {
    "T+AP", "THRTL", "Q", "MACH", "G", "STG.BRN", "\xCE\x94V.STG"
};

// Draw static chrome for the ascent-phase right panel: a border separating
// Draw static chrome for the ascent-phase right panel. One printDispChrome
// call per row draws the label + clears the cell interior. Label font is
// Roboto_Black_20 (matches SCFT right-panel standard); value font in the
// update functions is Roboto_Black_24. 52 px row height holds the 24-tall
// value comfortably.
//
// The vertical divider between panels sits at x=RPANEL_X-2..-1 (in the 2-px
// gap between the left graphics area and the right text area), matching the
// SCFT screen layout. Because it's outside the RPANEL_X..RPANEL_X+W-1 rect
// painted by printDispChrome's row borders, it isn't overwritten and can be
// drawn in any order.
// ── rev-2 Ascent right-panel geometry ──────────────────────────────────────
// Phase 2 redesign: the numeric readout column is right-aligned to the content
// edge (flush against the sidebar), widened to 400 px, and stretched to fill the
// full height below the title bar, with larger fonts than the letterboxed
// original. Ascent-only — the Circularization right panel keeps the shared
// LNCH_AS_* geometry until its own redesign pass.
static const int16_t LNCH_AS2_RPANEL_W = 360;
static const int16_t LNCH_AS2_RPANEL_X = CONTENT_W - LNCH_AS2_RPANEL_W;             // 580
static const int16_t LNCH_AS2_RPANEL_Y = LNCH_AS_PANEL_Y;                            // 63
static const int16_t LNCH_AS2_ROW_H    = (SCREEN_H - LNCH_AS_PANEL_Y) / LNCH_AS2_NROWS;  // 76
static const int16_t LNCH_AS2_RPANEL_H = LNCH_AS2_ROW_H * LNCH_AS2_NROWS;                 // 532
static const tFont  *LNCH_AS2_LBL_FONT = &Roboto_Black_28;
static const tFont  *LNCH_AS2_VAL_FONT = &Roboto_Black_36;
static inline int16_t _lnchAs2RowY(uint8_t row) {
    return LNCH_AS2_RPANEL_Y + row * LNCH_AS2_ROW_H;
}

// ── Shared LNCH right-panel readout plumbing ───────────────────────────────
// Both LNCH phases (Ascent + Circularization) render an identical 8-row numeric
// readout panel: same LNCH_AS2_* geometry, same Black_28 labels / Black_36
// values, same vertical divider, same 2-px horizontal group dividers. Only the
// row LABELS and the set of group-divider rows differ between the phases. These
// shared helpers hold the single implementation; each phase's public entry
// points delegate to them, passing their own label array, PrintState array, and
// divider-row list.
//
// Defined here in Screen_LNCH_Ascent.ino, which the Arduino build concatenates
// BEFORE Screen_LNCH_Circ.ino (alphabetical order), so these file-scope statics
// are visible to the Circularization phase's code as well.

// Shared right-panel chrome: vertical divider, one label cell per row, and the
// horizontal group dividers named in divRows. Font is LNCH_AS2_LBL_FONT
// (Roboto_Black_28) — identical in both phases.
static void _lnchAs2DrawPanelChrome(KCM_TFT &tft, const char *const *labels,
                                    const uint8_t *divRows, uint8_t divCount) {
    // Vertical divider in the 2-px gap before the right panel
    tft.drawLine(LNCH_AS2_RPANEL_X - 2, LNCH_AS2_RPANEL_Y,
                 LNCH_AS2_RPANEL_X - 2, LNCH_AS2_RPANEL_Y + LNCH_AS2_RPANEL_H - 1,
                 TFT_GREY);
    tft.drawLine(LNCH_AS2_RPANEL_X - 1, LNCH_AS2_RPANEL_Y,
                 LNCH_AS2_RPANEL_X - 1, LNCH_AS2_RPANEL_Y + LNCH_AS2_RPANEL_H - 1,
                 TFT_GREY);

    for (uint8_t i = 0; i < LNCH_AS2_NROWS; i++) {
        printDispChrome(tft, LNCH_AS2_LBL_FONT,
                        LNCH_AS2_RPANEL_X, _lnchAs2RowY(i),
                        LNCH_AS2_RPANEL_W, LNCH_AS2_ROW_H,
                        labels[i], COL_LABEL, TFT_BLACK, COL_NO_BDR);
    }

    // Horizontal group dividers — 2 px in TFT_GREY. Each divider sits in the
    // 2-px gap between row groups (at y=dy-1 and y=dy). These rows sit OUTSIDE
    // both adjacent rows' fillRect clear regions (printValue / printDispChrome
    // clear y0+1..y0+h-2 inclusive), so the divider can't be nibbled when a
    // value cell changes background colour (e.g. alarm state toggle).
    for (uint8_t i = 0; i < divCount; i++) {
        int16_t dy = _lnchAs2RowY(divRows[i]);
        tft.drawLine(LNCH_AS2_RPANEL_X, dy - 1,
                     LNCH_AS2_RPANEL_X + LNCH_AS2_RPANEL_W - 1, dy - 1,
                     TFT_GREY);
        tft.drawLine(LNCH_AS2_RPANEL_X, dy,
                     LNCH_AS2_RPANEL_X + LNCH_AS2_RPANEL_W - 1, dy,
                     TFT_GREY);
    }
}

static void _lnchAsDrawRightPanelChrome(KCM_TFT &tft) {
    // Groups: row 0 trajectory, row 1 the throttle setting, rows 2-4 air data
    // (Q / Mach / G rise and fall together through the ascent), rows 5-6 what is
    // left in the stage → dividers above rows 1, 2 and 5.
    static const uint8_t divRows[] = { 1, 2, 5 };
    _lnchAs2DrawPanelChrome(tft, _lnchAsLabels, divRows, sizeof(divRows));
}

// Shared: draw a value in a readout row using library printValue. The value is
// right-aligned in the cell; the label (already drawn by chrome) is used only
// for paramW calculation so the value region doesn't overlap the label. Font is
// LNCH_AS2_VAL_FONT (Roboto_Black_36) — identical in both LNCH phases.
static void _lnchAs2DrawRowValue(KCM_TFT &tft, uint8_t row, const String &val,
                                 uint16_t fg, uint16_t bg,
                                 const char *const *labels, PrintState *ps) {
    printValue(tft, LNCH_AS2_VAL_FONT,
               LNCH_AS2_RPANEL_X, _lnchAs2RowY(row),
               LNCH_AS2_RPANEL_W, LNCH_AS2_ROW_H,
               labels[row], val,
               fg, bg, TFT_BLACK,
               ps[row]);
}

// ── Shared LNCH row updaters ───────────────────────────────────────────────
// T+Ap and Stg.Brn use byte-identical threshold + formatter + suppress logic wherever
// they appear; only the target row index, label array, PrintState array, and
// change-detection caches differ, so those are passed as parameters.
//
// Alt and ApA had shared updaters here too. Both are gone: the circularisation phase
// replaced its readout column with the apsis tape, and on ascent both rows were dropped
// in favour of the altitude ladder's markers, so neither had a caller left.
//
// NOTE: Throttle and ΔV.Stg are deliberately NOT shared — they genuinely differ between
// the phases (Ascent flags a zero-throttle alarm while Circ treats coasting as normal;
// Ascent change-detects ΔV.Stg at tenths precision while Circ uses whole m/s). See
// their per-phase definitions.

static void _lnchAs2UpdateTimeToAp(KCM_TFT &tft, uint8_t row,
                                   const char *const *labels, PrintState *ps,
                                   int32_t &prevT, uint16_t &prevFg) {
    float ttAp = state.timeToAp;
    int32_t iTtAp = (int32_t)roundf(ttAp);

    bool suppress = (state.apoapsis <= 0.0f) ||
                    (state.situation & sit_PreLaunch) ||
                    (state.situation & sit_Landed);

    uint16_t fg;
    String val;
    if (suppress) {
        val = "---";
        fg = TFT_DARK_GREY;
        iTtAp = -1 << 29;
    } else {
        if      (ttAp < 0)                   fg = TFT_RED;
        else if (ttAp < LNCH_TOAPO_WARN_S)   fg = TFT_YELLOW;
        else                                 fg = TFT_DARK_GREEN;
        val = formatTimeCompact(ttAp);
    }

    if (iTtAp == prevT && fg == prevFg) return;

    _lnchAs2DrawRowValue(tft, row, val, fg, TFT_BLACK, labels, ps);
    prevT  = iTtAp;
    prevFg = fg;
}

static void _lnchAs2UpdateTBurn(KCM_TFT &tft, uint8_t row,
                                const char *const *labels, PrintState *ps,
                                int32_t &prevTB, uint16_t &prevFg, uint16_t &prevBg) {
    float tb = state.stageBurnTime;
    int32_t iTb = (int32_t)roundf(tb);

    uint16_t fg, bg;
    thresholdColor(tb,
                   LNCH_BURNTIME_ALARM_S, TFT_WHITE,  TFT_RED,
                   LNCH_BURNTIME_WARN_S,  TFT_YELLOW, TFT_BLACK,
                        TFT_DARK_GREEN, TFT_BLACK, fg, bg);

    if (iTb == prevTB && fg == prevFg && bg == prevBg) return;

    _lnchAs2DrawRowValue(tft, row, formatTimeCompact(tb), fg, bg, labels, ps);
    prevTB  = iTb;
    prevFg  = fg;
    prevBg  = bg;
}

// Per-phase wrapper: draws an Ascent readout value using the Ascent label and
// PrintState arrays. Kept so the non-shared updaters (V.Srf/V.Vrt/Thrtl/ΔV.Stg)
// call sites are unchanged.
static void _lnchAsDrawRowValue(KCM_TFT &tft, uint8_t row, const String &val,
                                 uint16_t fg, uint16_t bg) {
    _lnchAs2DrawRowValue(tft, row, val, fg, bg, _lnchAsLabels, _lnchAsPs);
}

// Update each row. Each checks its own change detection and returns early if
// unchanged. Order: Alt, ApA, T+Ap, V.Srf, V.Vrt, Throttle, T.Burn, ΔV.Stg.

// ── Readout column updaters ───────────────────────────────────────────────────────────
// Rows 0-4 of this column used to be Alt.SL, ApA, T+Ap, V.Srf and V.Vrt. Four of those
// five were the digits for a gauge on this same screen and now live on it; only T+Ap
// had no picture, and it stays. Q, Mach and G take the freed rows -- none of the three
// was anywhere on this screen, and all three are already in the telemetry.

// Row 0 — T+Ap. Shared with the circularisation phase.
static void _lnchAsUpdateTimeToAp(KCM_TFT &tft) {
    _lnchAs2UpdateTimeToAp(tft, 0, _lnchAsLabels, _lnchAsPs,
                           _lnchAsPrevTimeToAp, _lnchAsPrevTimeToApFg);
}

// Row 1 — throttle. White-on-red at zero: on an ascent a closed throttle is an event,
// not a resting state (the circularisation phase treats coasting as normal instead).
static void _lnchAsUpdateThrottle(KCM_TFT &tft) {
    uint8_t thrPct = (uint8_t)constrain(state.throttle * 100.0f, 0.0f, 100.0f);

    uint16_t fg, bg;
    if (thrPct == 0) { fg = TFT_WHITE;      bg = TFT_RED;   }
    else             { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }

    if ((int16_t)thrPct == _lnchAsPrevThrottle &&
        fg == _lnchAsPrevThrFg && bg == _lnchAsPrevThrBg) return;

    _lnchAsDrawRowValue(tft, 1, formatPerc(thrPct), fg, bg);
    _lnchAsPrevThrottle = thrPct;
    _lnchAsPrevThrFg = fg; _lnchAsPrevThrBg = bg;
}

// Row 2 — dynamic pressure. Yellow approaching the structural band, white-on-red past
// it: max Q is the one moment of an ascent where the airframe, not the trajectory, is
// the limit, and nothing else on either panel annunciates it.
static void _lnchAsUpdateQ(KCM_TFT &tft) {
    const float q = _lnchAsDynPressureKPa();
    const int32_t iQ = (int32_t)lroundf(q * 10.0f);          // tenths of a kPa

    const bool haveAir = (state.inAtmo && state.airDensity > 0.0f);

    uint16_t fg, bg;
    char buf[16];
    if (!haveAir) {
        strcpy(buf, "---");
        fg = TFT_DARK_GREY; bg = TFT_BLACK;
    } else {
        snprintf(buf, sizeof(buf), "%.1f kPa", q);
        if      (q >= LNCH_Q_ALARM_KPA) { fg = TFT_WHITE;      bg = TFT_RED;   }
        else if (q >= LNCH_Q_WARN_KPA)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                            { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    }

    // Colours settled before the change test: deciding them from the thresholds and then
    // overriding for the placeholder meant an out-of-atmosphere frame compared a green
    // threshold colour against a stored grey one and repainted every single frame.
    if (iQ == _lnchAsPrevQ && fg == _lnchAsPrevQFg && bg == _lnchAsPrevQBg) return;

    _lnchAsDrawRowValue(tft, 2, String(buf), fg, bg);
    _lnchAsPrevQ = iQ; _lnchAsPrevQFg = fg; _lnchAsPrevQBg = bg;
}

// Row 3 — Mach. Dashed outside an atmosphere, where it means nothing.
static void _lnchAsUpdateMach(KCM_TFT &tft) {
    const bool inAir = state.inAtmo;
    const int32_t iM = inAir ? (int32_t)lroundf(state.machNumber * 100.0f) : -9999;
    if (iM == _lnchAsPrevMach) return;

    char buf[12];
    if (!inAir) strcpy(buf, "---");
    else        snprintf(buf, sizeof(buf), "%.2f", state.machNumber);
    _lnchAsDrawRowValue(tft, 3, String(buf),
                        inAir ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
    _lnchAsPrevMach = iM;
}

// Row 4 — load factor. Yellow then white-on-red on the crew limits the Annunciator
// already uses, so the two panels cannot disagree about what a high-G ascent is.
static void _lnchAsUpdateG(KCM_TFT &tft) {
    const float g = state.gForce;
    const int32_t iG = (int32_t)lroundf(g * 10.0f);

    uint16_t fg, bg;
    if      (g >= LNCH_G_ALARM) { fg = TFT_WHITE;      bg = TFT_RED;   }
    else if (g >= LNCH_G_WARN)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
    else                        { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }

    if (iG == _lnchAsPrevG && fg == _lnchAsPrevGFg && bg == _lnchAsPrevGBg) return;

    char buf[12];
    snprintf(buf, sizeof(buf), "%.1f", g);
    _lnchAsDrawRowValue(tft, 4, String(buf), fg, bg);
    _lnchAsPrevG = iG; _lnchAsPrevGFg = fg; _lnchAsPrevGBg = bg;
}

// Row 5 — stage endurance. Shared with the circularisation phase.
static void _lnchAsUpdateTBurn(KCM_TFT &tft) {
    _lnchAs2UpdateTBurn(tft, 5, _lnchAsLabels, _lnchAsPs,
                        _lnchAsPrevTBurn, _lnchAsPrevTBurnFg, _lnchAsPrevTBurnBg);
}

// Row 6 — stage delta-V.
static void _lnchAsUpdateDVStg(KCM_TFT &tft) {
    float dv = state.stageDeltaV;
    int32_t iDv = (int32_t)roundf(dv);

    uint16_t fg, bg;
    thresholdColor(dv,
                   DV_STG_ALARM_MS, TFT_WHITE,  TFT_RED,
                   DV_STG_WARN_MS,  TFT_YELLOW, TFT_BLACK,
                   TFT_DARK_GREEN, TFT_BLACK, fg, bg);

    if (iDv == _lnchAsPrevDVStg &&
        fg == _lnchAsPrevDVStgFg && bg == _lnchAsPrevDVStgBg) return;

    _lnchAsDrawRowValue(tft, 6, fmtMs(dv), fg, bg);
    _lnchAsPrevDVStg = iDv;
    _lnchAsPrevDVStgFg = fg; _lnchAsPrevDVStgBg = bg;
}

static void _lnchAsDrawRightPanelValues(KCM_TFT &tft) {
    _lnchAsUpdateTimeToAp(tft);
    _lnchAsUpdateThrottle(tft);
    _lnchAsUpdateQ(tft);
    _lnchAsUpdateMach(tft);
    _lnchAsUpdateG(tft);
    _lnchAsUpdateTBurn(tft);
    _lnchAsUpdateDVStg(tft);
}


/***************************************************************************************
   Screen_LNCH_AscentAP.ino — Ascent Autopilot interface (chrome + draw + touch)

   Touch UI for the Simpit ascent autopilot. Renders the autopilot status echoed
   from Controller_Main (AscentStatus, in the shared `state` struct) and lets the
   pilot edit parameters (on-screen numeric keypad + toggles) and ARM/DISARM by
   touch, at any time.

   Pilot edits go to a local "pending" buffer that is shown in preference to the
   autopilot-confirmed value and staged on the outbound command channel; when the
   autopilot echoes the new value back, the pending flag is cleared.

   LAYOUT (1024x600, content 0..CONTENT_W, y from TITLE_TOP):
     banner: <PHASE, coloured>            body   <ARMED/DISARMED>
     MISSION (inputs) | VEH PROFILE (inputs) | GUIDANCE (outputs)
     Tgt Ap / Incl /  | Loft / Roll /        | Pitch Hdg Thr
     Launch           | Max-G  + [ARM]       | G q ApA PeA
   Boxed fields are the touch targets. Tapping one opens the keypad (or toggles).
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// ── Palette / fonts ─────────────────────────────────────────────────────────────────
static const uint16_t AP_LBL = KDC_LABEL_COLOR;
static const uint16_t AP_VAL = TFT_DARK_GREEN;
static const uint16_t AP_HDR = TFT_WHITE;
static const uint16_t AP_BOX = TFT_GREY;
static const uint16_t AP_EDT = TFT_SKY;          // pending (unconfirmed) value colour
static const uint16_t AP_GUARD = TFT_ORANGE;
#define AP_F_LBL  (&Roboto_Black_24)
#define AP_F_VAL  (&Roboto_Black_32)
#define AP_F_HDR  (&Roboto_Black_28)
#define AP_F_BANN (&Roboto_Black_36)
#define AP_F_ARM  (&Roboto_Black_28)

// ── Geometry ──────────────────────────────────────────────────────────────────────
static const int16_t AP_BANNER_Y = TITLE_TOP;
static const int16_t AP_BANNER_H = 64;
static const int16_t AP_COL_Y    = AP_BANNER_Y + AP_BANNER_H + 6;   // 132
static const int16_t AP_ROW_Y0   = AP_COL_Y + 40;                   // 172
static const int16_t AP_ROW_H    = 58;
static const int16_t AP_COL_BOT  = 590;
static const int16_t AP_C1X = 6,   AP_C2X = 322, AP_C3X = 638;
static const int16_t AP_COLW = 298;
static const int16_t AP_DIV1_X = 314, AP_DIV2_X = 630;
static const int16_t AP_VALW = 176;
static const int16_t AP_VALH = AP_ROW_H - 8;
static const int16_t AP_ARM_H = 136;
static const int16_t AP_ARM_Y = SCREEN_H - 4 - AP_ARM_H;           // 460
static const int16_t AP_ARM_X = AP_C2X, AP_ARM_W = AP_COLW;
static inline int16_t apRowY(uint8_t i) { return AP_ROW_Y0 + i * AP_ROW_H; }

// ── Field table ───────────────────────────────────────────────────────────────────
enum {
  AP_TGTALT = 0, AP_INCL, AP_DIR,                          // mission (inputs)
  AP_LOFT, AP_ROLL, AP_MAXG,                               // profile (inputs)
  AP_PITCH, AP_HDG, AP_THR, AP_G, AP_Q, AP_APA, AP_PE,     // guidance (outputs)
  AP_SLOT_COUNT
};
static const uint8_t AP_ARM_SLOT   = 20;
static const uint8_t AP_PHASE_SLOT = 21;
static const uint8_t AP_BODY_SLOT  = 22;

struct ApCell { int16_t x; uint8_t row; const char *label; bool edit; };
static const ApCell AP_CELLS[AP_SLOT_COUNT] = {
  { AP_C1X, 0, "TGT AP", true  },
  { AP_C1X, 1, "INC",    true  },
  { AP_C1X, 2, "LAUNCH", true  },
  { AP_C2X, 0, "LOFT",   true  },
  { AP_C2X, 1, "ROLL",   true  },
  { AP_C2X, 2, "MAX-G",  true  },
  { AP_C3X, 0, "PITCH",  false },
  { AP_C3X, 1, "HDG",    false },
  { AP_C3X, 2, "THRTL",  false },
  { AP_C3X, 3, "G",      false },
  { AP_C3X, 4, "Q",      false },
  { AP_C3X, 5, "APA",    false },
  { AP_C3X, 6, "PEA",    false },
};
static inline int16_t apValX(uint8_t slot) { return AP_CELLS[slot].x + AP_COLW - AP_VALW; }
static inline int16_t apValY(uint8_t slot) { return apRowY(AP_CELLS[slot].row) + 4; }

// Editable-field descriptors (indexed by AP_EDITS order). kind: 0 numeric, 1 toggle
// N/S, 2 numeric+OFF (roll hold), 3 numeric+OFF (max-G, 0=off).
struct ApEdit { uint8_t slot, kind; const char *name, *units; float mn, mx; };
static const ApEdit AP_EDITS[6] = {
  { AP_TGTALT, 0, "TARGET APOAPSIS",  "m",    0.0f, 2000000000.0f },
  { AP_INCL,   0, "INCLINATION",      "\xB0", 0.0f, 180.0f },
  { AP_DIR,    1, "LAUNCH DIRECTION", "",     0.0f, 0.0f },
  { AP_LOFT,   0, "LOFT EXPONENT",    "",     0.5f, 2.0f },
  { AP_ROLL,   2, "ROLL HOLD",        "\xB0", -180.0f, 180.0f },
  { AP_MAXG,   3, "MAX-G",            "g",    0.0f, 20.0f },
};

// ── Pending (pilot-entered) overrides — shown until the autopilot echoes back ────────
static bool  apDTgt=false;  static float apTgt;
static bool  apDInc=false;  static float apInc;
static bool  apDDir=false;  static bool  apDir;
static bool  apDLof=false;  static float apLof;
static bool  apDRol=false;  static bool  apRolEn;  static float apRolDeg;
static bool  apDMxg=false;  static float apMxg;
static int8_t apArmOvr = -1;   // -1 use state, 0 disarmed, 1 armed (commanded)

static float apGTgt(){ return apDTgt ? apTgt    : state.apTargetAlt; }
static float apGInc(){ return apDInc ? apInc    : state.apInclination; }
static bool  apGDir(){ return apDDir ? apDir    : state.apSoutherly; }
static float apGLof(){ return apDLof ? apLof    : state.apLoft; }
static bool  apGRolEn(){ return apDRol ? apRolEn  : state.apRollEnable; }
static float apGRolDeg(){ return apDRol ? apRolDeg : state.apRollDeg; }
static float apGMxg(){ return apDMxg ? apMxg    : state.apMaxG; }
static uint16_t apEditColor(bool dirty){ return dirty ? AP_EDT : AP_VAL; }

// Two different questions, deliberately kept apart — conflating them has produced a
// bug twice now.
//
//   apArmCommanded()  — what the pilot has asked for: the queued ARM/DISARM tap while
//                       one is in flight, the autopilot's state otherwise. Drives what
//                       the NEXT tap does, so a second tap reverses a pending command
//                       rather than repeating it, and a lost acknowledgement cannot
//                       lock the button out.
//   apArmedAnnunciated() — what the autopilot actually reports. Everything that TELLS
//                       the pilot whether the vehicle is armed reads this and only
//                       this: the ARM button, the ARMED/DISARMED banner, and the
//                       sidebar ASC key. An annunciation must never say DISARMED while
//                       the autopilot is still flying the vehicle, so a tap alone is
//                       not enough to change it — Controller_Main has to echo it back.
//                       The wait is shown as a pending cue, not by lying about state.
static bool apArmCommanded(){ return apArmOvr >= 0 ? (apArmOvr == 1) : state.apArmed; }
static bool apArmPending()  { return apArmOvr >= 0; }

bool apArmedAnnunciated() { return state.apArmed; }

// ── Outbound command channel ─────────────────────────────────────────────────────────
// The command queue (apEnqueueCmd / apPumpCommandQueue / apFillOutboundCmd /
// apAckCommand) and the numeric keypad moved to ConsoleShared.ino when the AIRCRAFT
// and ROVER autopilot consoles arrived; all three consoles share one queue and one
// keypad. Byte-level layout is in Documents/Developer/Ascent_Autopilot_Interface.md.

// Clear pending (cyan) flags once Controller_Main echoes the accepted value back in the
// AscentStatus frame. Called each loop from updateI2CState().
void apReconcilePending() {
  // Target uses a relative tolerance: a float32 ULP already exceeds 1 m above ~8.4e6 m,
  // so a fixed 1 m window would never close for high (interplanetary) target apoapses.
  float tgtTol = fmaxf(1.0f, fabsf(apTgt) * 5.0e-4f);
  if (apDTgt && fabsf(state.apTargetAlt   - apTgt)    < tgtTol)  apDTgt = false;
  if (apDInc && fabsf(state.apInclination - apInc)    < 0.05f)   apDInc = false;
  if (apDDir && state.apSoutherly == apDir)                      apDDir = false;
  if (apDLof && fabsf(state.apLoft        - apLof)    < 0.005f)  apDLof = false;
  if (apDRol && state.apRollEnable == apRolEn &&
      (!apRolEn || fabsf(state.apRollDeg  - apRolDeg) < 0.5f))   apDRol = false;
  if (apDMxg && fabsf(state.apMaxG        - apMxg)    < 0.05f)   apDMxg = false;
  // Clears the pending cue once Controller_Main reports the commanded armed state.
  if (apArmOvr >= 0 && state.apArmed == (apArmOvr == 1))         apArmOvr = -1;
}

static bool apScreenRefresh = false;

// ── Phase name / colour ─────────────────────────────────────────────────────────────
const char *apPhaseName(uint8_t p) {
  switch (p) {
    case 1: return "VERTICAL"; case 2: return "GRAVITY TURN"; case 3: return "COAST";
    case 4: return "CIRCULARIZE"; case 5: return "COMPLETE"; case 6: return "ABORT";
    default: return "IDLE";
  }
}
static uint16_t apPhaseColor(uint8_t p) {
  switch (p) {
    case 1: case 2: return TFT_DARK_GREEN;
    case 3: case 4: return TFT_CYAN;
    case 5:         return TFT_SKY;
    case 6:         return TFT_RED;
    default:        return TFT_DARK_GREY;
  }
}

// Pick a legible text colour for an arbitrary RGB565 background by its perceived
// luminance (Rec. 601). White washes out on the light phase colours (CYAN ~179,
// SKY ~177); on those we use TFT_DARK_GREY — the standard dark-on-light button text
// used elsewhere (AIRBRK on CYAN, ROVR REV on YELLOW). The dark phases (DARK_GREEN
// ~73, RED ~76) keep white. Threshold 140 splits the two groups with margin;
// channels are scaled 5/6/5 -> 0..255 before weighting.
static uint16_t apTextOn(uint16_t bg) {
  uint16_t r = ((bg >> 11) & 0x1F) * 255 / 31;
  uint16_t g = ((bg >> 5)  & 0x3F) * 255 / 63;
  uint16_t b = ( bg        & 0x1F) * 255 / 31;
  uint16_t lum = (uint16_t)((r * 299 + g * 587 + b * 114) / 1000);
  return (lum > 140) ? TFT_DARK_GREY : TFT_WHITE;
}

// ── CHROME (static) ─────────────────────────────────────────────────────────────────
static void chromeScreen_LNCHAP(KCM_TFT &tft) {
  // Any full repaint (screen entry, display reset) starts with the keypad closed — the
  // modal is transient and must never persist across a leave/return, or the panel would
  // come back frozen with taps misrouted into a stale keypad.
  kpForceClose();
  tft.fillRect(0, AP_BANNER_Y + AP_BANNER_H, CONTENT_W, 2, TFT_GREY);
  tft.drawLine(AP_DIV1_X, AP_COL_Y, AP_DIV1_X, AP_COL_BOT, TFT_GREY);
  tft.drawLine(AP_DIV2_X, AP_COL_Y, AP_DIV2_X, AP_COL_BOT, TFT_GREY);
  textLeft(tft, AP_F_HDR, AP_C1X, AP_COL_Y, AP_COLW, 32, "MISSION",     AP_HDR, TFT_BLACK);
  textLeft(tft, AP_F_HDR, AP_C2X, AP_COL_Y, AP_COLW, 32, "VEH PROFILE", AP_HDR, TFT_BLACK);
  textLeft(tft, AP_F_HDR, AP_C3X, AP_COL_Y, AP_COLW, 32, "GUIDANCE",    AP_HDR, TFT_BLACK);
  for (uint8_t s = 0; s < AP_SLOT_COUNT; s++) {
    const ApCell &c = AP_CELLS[s];
    int16_t y = apRowY(c.row);
    textLeft(tft, AP_F_LBL, c.x + 2, y, AP_COLW - AP_VALW, AP_ROW_H, c.label, AP_LBL, TFT_BLACK);
    if (c.edit) tft.drawRect(apValX(s), apValY(s), AP_VALW - 2, AP_VALH, AP_BOX);
  }
  textLeft(tft, &Roboto_Black_16, AP_C1X + 2, apRowY(3) + 8, AP_COLW - 8, 20,
           "Boxed fields - tap to edit", TFT_DARK_GREY, TFT_BLACK);
}

// ── Value helper (flicker-free) ─────────────────────────────────────────────────────
static void apPut(KCM_TFT &tft, uint8_t slot, const String &val, uint16_t fg) {
  RowCache &rc = rowCache[screen_LNCHAP][slot];
  if (rc.value == val && rc.fg == fg) return;
  printValue(tft, AP_F_VAL, apValX(slot), apValY(slot), AP_VALW - 2, AP_VALH,
             "", val, fg, TFT_BLACK, TFT_BLACK, printState[screen_LNCHAP][slot]);
  rc.value = val; rc.fg = fg; rc.bg = TFT_BLACK;
}
// C-string form: the cache compare allocates nothing; the String is built only for a
// value about to be drawn. Every per-frame value on the console comes through here.
static void apPut(KCM_TFT &tft, uint8_t slot, const char *val, uint16_t fg) {
  RowCache &rc = rowCache[screen_LNCHAP][slot];
  if (rc.fg == fg && rc.value == val) return;
  apPut(tft, slot, String(val), fg);
}

// ── DRAW (dynamic) ──────────────────────────────────────────────────────────────────
static void drawScreen_LNCHAP(KCM_TFT &tft) {
  if (kpTakeClosed()) apScreenRefresh = true;   // repaint the panel the modal covered
  if (apScreenRefresh) {
    tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
    chromeScreen_LNCHAP(tft);
    for (uint8_t r = 0; r < ROW_COUNT; r++) rowCache[screen_LNCHAP][r].value = "\x01";
    apScreenRefresh = false;
  }
  if (kpIsOpen()) {
    kpDraw(tft);
    return;                       // freeze the panel behind the modal while editing
  }

  char buf[48];

  // Phase banner
  {
    uint16_t pc = apPhaseColor(state.apPhase);
    const char *pn = apPhaseName(state.apPhase);
    RowCache &rc = rowCache[screen_LNCHAP][AP_PHASE_SLOT];
    if (rc.fg != pc || rc.value != pn) {
      tft.fillRect(0, AP_BANNER_Y, 640, AP_BANNER_H, TFT_BLACK);
      textLeft(tft, AP_F_BANN, 8, AP_BANNER_Y, 632, AP_BANNER_H, pn, pc, TFT_BLACK);
      rc.value = pn; rc.fg = pc;
    }
  }
  {
    bool armed = apArmedAnnunciated();
    const char *bs = state.gameSOI.c_str();
    // Truth, always. A queued tap appends "..." rather than flipping the word, so the
    // banner cannot read DISARMED while the autopilot is still armed.
    char as[16];
    snprintf(as, sizeof(as), "%s%s", armed ? "ARMED" : "DISARMED", apArmPending() ? "..." : "");
    uint16_t ac = armed ? TFT_NEON_GREEN : TFT_DARK_GREY;
    RowCache &rc = rowCache[screen_LNCHAP][AP_BODY_SLOT];
    char combo[64];
    snprintf(combo, sizeof(combo), "%s|%s", bs, as);
    if (rc.fg != ac || rc.value != combo) {
      tft.fillRect(648, AP_BANNER_Y, CONTENT_W - 648, AP_BANNER_H, TFT_BLACK);
      textRight(tft, &Roboto_Black_20, 648, AP_BANNER_Y + 4,  CONTENT_W - 648 - 6, 24, bs, AP_LBL, TFT_BLACK);
      textRight(tft, &Roboto_Black_28, 648, AP_BANNER_Y + 30, CONTENT_W - 648 - 6, 30, as, ac, TFT_BLACK);
      rc.value = combo; rc.fg = ac;
    }
  }

  // Mission (inputs — pending shown in AP_EDT colour)
  { formatAltBuf(apGTgt(), buf, sizeof(buf)); apPut(tft, AP_TGTALT, buf, apEditColor(apDTgt)); }
  { snprintf(buf, sizeof(buf), "%.1f\xB0", apGInc()); apPut(tft, AP_INCL, buf, apEditColor(apDInc)); }
  apPut(tft, AP_DIR, apGDir() ? "SOUTH" : "NORTH", apEditColor(apDDir));

  // Vehicle profile (inputs)
  { char b2[12]; dtostrf(apGLof(), 1, 2, b2); apPut(tft, AP_LOFT, b2, apEditColor(apDLof)); }
  if (apGRolEn()) { snprintf(buf, sizeof(buf), "%+.0f\xB0", apGRolDeg()); apPut(tft, AP_ROLL, buf, apEditColor(apDRol)); }
  else            { apPut(tft, AP_ROLL, "OFF", apDRol ? AP_EDT : TFT_DARK_GREY); }
  if (apGMxg() > 0.0f) { snprintf(buf, sizeof(buf), "%.1f g", apGMxg()); apPut(tft, AP_MAXG, buf, apEditColor(apDMxg)); }
  else                 { apPut(tft, AP_MAXG, "OFF", apDMxg ? AP_EDT : TFT_DARK_GREY); }

  // Guidance (outputs)
  { snprintf(buf, sizeof(buf), "%+.0f\xB0", state.apCmdPitch); apPut(tft, AP_PITCH, buf, AP_VAL); }
  { int16_t h = (int16_t)roundf(state.apCmdHeading) % 360; if (h < 0) h += 360;
    snprintf(buf, sizeof(buf), "%03d\xB0", h); apPut(tft, AP_HDG, buf, AP_VAL); }
  {
    int16_t pct = (int16_t)roundf(state.apCmdThrottle * 100.0f);
    if (pct < 0) pct = 0; if (pct > 100) pct = 100;
    RowCache &rc = rowCache[screen_LNCHAP][AP_THR];
    char v[8];
    snprintf(v, sizeof(v), "%d", pct);
    if (rc.value != v) {
      int16_t bx = apValX(AP_THR), by = apValY(AP_THR), bw = AP_VALW - 2, bh = AP_VALH;
      int16_t barW = 80, fillW = (int16_t)(barW * pct / 100);
      tft.fillRect(bx, by, bw, bh, TFT_BLACK);
      int16_t barY = by + (bh - 18) / 2;
      tft.drawRect(bx, barY, barW, 18, TFT_GREY);
      if (fillW > 2) tft.fillRect(bx + 1, barY + 1, fillW - 2, 16, TFT_DARK_GREEN);
      snprintf(buf, sizeof(buf), "%d%%", pct);
      textRight(tft, AP_F_VAL, bx + barW, by, bw - barW, bh, buf, AP_VAL, TFT_BLACK);
      rc.value = v;
    }
  }
  {
    uint16_t gc = AP_VAL;
    float mg = apGMxg();
    if (mg > 0.0f) { if (state.gForce >= mg) gc = TFT_RED; else if (state.gForce >= 0.9f * mg) gc = TFT_YELLOW; }
    snprintf(buf, sizeof(buf), "%.1f g", state.gForce);
    apPut(tft, AP_G, buf, gc);
  }
  if (state.apDynPressure >= 1000.0f) snprintf(buf, sizeof(buf), "%.1f kPa", state.apDynPressure / 1000.0f);
  else                                snprintf(buf, sizeof(buf), "%.0f Pa",  state.apDynPressure);
  apPut(tft, AP_Q, buf, AP_VAL);
  formatAltBuf(state.apoapsis,  buf, sizeof(buf)); apPut(tft, AP_APA, buf, TFT_LIGHT_GREY);
  formatAltBuf(state.periapsis, buf, sizeof(buf)); apPut(tft, AP_PE,  buf, TFT_LIGHT_GREY);

  // ARM control
  {
    bool armed   = apArmedAnnunciated();   // the autopilot's state, never the tap
    bool pending = apArmPending();         // a tap queued, not yet echoed back
    uint16_t pc = apPhaseColor(state.apPhase);
    const char *txt = armed ? apPhaseName(state.apPhase) : "ARM";
    // Armed: legible text auto-picked for the phase-colour background (white washes
    // out on the light CYAN/SKY phases). Disarmed: orange guard text on off-black.
    uint16_t fg  = armed ? apTextOn(pc) : AP_GUARD;
    uint16_t bg  = armed ? pc           : TFT_OFF_BLACK;
    // While a command is in flight the border goes to the pending colour the editable
    // fields already use, and the hint says which way it is going. The fill and legend
    // stay on the real state: the pilot gets immediate confirmation that the tap
    // registered — which a touchscreen owes them, having no detent — without the panel
    // claiming a state the autopilot has not reached.
    uint16_t bdr = pending ? AP_EDT : (armed ? TFT_WHITE : AP_GUARD);
    RowCache &rc = rowCache[screen_LNCHAP][AP_ARM_SLOT];
    char key[32];
    snprintf(key, sizeof(key), "%s%s%s", armed ? "A:" : "D:", pending ? "P:" : "-:", txt);
    if (rc.value != key) {
      ButtonLabel btn = { txt, fg, fg, bg, bg, bdr, bdr };
      drawButton(tft, AP_ARM_X, AP_ARM_Y, AP_ARM_W, AP_ARM_H, btn, AP_F_ARM, false);
      const char *hint = pending ? (apArmCommanded() ? "ARMING..." : "DISARMING...")
                                 : (armed ? "tap to DISARM" : "tap to ARM");
      textCenter(tft, &Roboto_Black_16, AP_ARM_X, AP_ARM_Y + AP_ARM_H - 24, AP_ARM_W, 18,
                 hint, pending ? AP_EDT : (armed ? apTextOn(pc) : AP_GUARD), bg);
      rc.value = key;
    }
  }
}

// ── Keypad open / commit ────────────────────────────────────────────────────────────
// Commit from the shared keypad: `off` is the OFF key (roll hold / max-G only); the
// value is already clamped to the field's range.
static void apKeypadCommit(int8_t idx, float v, bool off) {
  const ApEdit &e = AP_EDITS[idx];
  if (off) {
    if (e.kind == 2)      { apRolEn = false; apDRol = apEnqueueCmd(AP_CMD_SET_ROLL, AP_ROLL_OFF); }
    else if (e.kind == 3) { apMxg = 0.0f;    apDMxg = apEnqueueCmd(AP_CMD_SET_MAXG, 0.0f); }
    return;
  }
  switch (e.slot) {
    // The pending cue is raised only for a command that was actually queued (see
    // apEnqueueCmd): a cue for one that was not would never clear.
    case AP_TGTALT: apTgt = v; apDTgt = apEnqueueCmd(AP_CMD_SET_TARGET_ALT, v);  break;  // metres
    case AP_INCL:   apInc = v; apDInc = apEnqueueCmd(AP_CMD_SET_INCLINATION, v); break;
    case AP_LOFT:   apLof = v; apDLof = apEnqueueCmd(AP_CMD_SET_LOFT, v);        break;
    case AP_ROLL:   apRolDeg = v; apRolEn = true; apDRol = apEnqueueCmd(AP_CMD_SET_ROLL, v); break;
    case AP_MAXG:   apMxg = v; apDMxg = apEnqueueCmd(AP_CMD_SET_MAXG, v);        break;
  }
}

static void apOpenKeypad(int8_t editIdx) {
  const ApEdit &e = AP_EDITS[editIdx];
  KpField f = { e.name, e.units, e.mn, e.mx, (e.kind == 2 || e.kind == 3), true, 0 };
  kpOpen(f, editIdx, apKeypadCommit);
}

// Public: routed here for any content-area tap while the AP screen is active.
void apScreenTouch(uint16_t x, uint16_t y) {
  if (kpIsOpen()) { kpTouch(x, y); return; }

  // ARM / DISARM
  if (x >= AP_ARM_X && x < AP_ARM_X + AP_ARM_W && y >= AP_ARM_Y && y < AP_ARM_Y + AP_ARM_H) {
    // Toggle from the COMMANDED state, so a second tap while one is in flight reverses
    // that command instead of re-sending it, and a lost echo cannot lock the button.
    bool wantArm = !apArmCommanded();
    // The pending cue is raised only if a command really went out. In demo mode (and on
    // unit 1, where the command channel is compiled out) nothing is queued and nothing
    // will ever acknowledge it, so a cue raised here would sit on the button forever.
    if (apEnqueueCmd(wantArm ? AP_CMD_ARM : AP_CMD_DISARM, 0.0f)) {
      apArmOvr = wantArm ? 1 : 0;
      rowCache[screen_LNCHAP][AP_ARM_SLOT].value = "\x01";   // force ARM + banner redraw
      rowCache[screen_LNCHAP][AP_BODY_SLOT].value = "\x01";
    }
    return;
  }
  // Editable fields
  for (uint8_t i = 0; i < 6; i++) {
    const ApEdit &e = AP_EDITS[i];
    int16_t cx = AP_CELLS[e.slot].x, cy = apRowY(AP_CELLS[e.slot].row);
    if (x >= cx && x < cx + AP_COLW && y >= cy && y < cy + AP_ROW_H) {
      if (e.kind == 1) {                             // Launch N/S toggle
        apDir = !apGDir();
        apDDir = apEnqueueCmd(AP_CMD_SET_LAUNCH_DIR, apDir ? 1.0f : 0.0f);
        rowCache[screen_LNCHAP][e.slot].value = "\x01";
      } else {
        apOpenKeypad(i);
      }
      return;
    }
  }
}

/***************************************************************************************
   Screen_LNCH_Circ.ino -- Circularization (orbital) phase of the LNCH screen.

   Active when state.altitude exceeds ~6% of bodyR (with hysteresis), i.e. once the
   vessel has reached its apoapsis-stretching phase and the pilot is preparing to
   circularize. Layout summary:

   LEFT GRAPHICS PANEL (x=0..576):
     - Left rail (x≈0..145) — ATT indicator (alignment disc, R=58) with the Burn
       Dur readout beneath it
     - Orbit diagram (hero, CX=348 CY=272 MAX_R=175) — body, atmosphere ring, dashed
       target circle, current orbit curve, Pe/Ap markers, vessel dot, chevron
     - Bottom band (full width) — ΔV Burn bar + value text, then a prominent
       T+Ign countdown row (Black_36)

   RIGHT READOUT PANEL (x=580..940, LNCH_AS2_* — matches the ascent phase):
     - 8 numeric readouts: Alt.SL, V.Orb, ApA, PeA, T+Ap, Thrtl, T.Brn, ΔV.Stg
     - Grouped horizontal dividers between logical row groups

   Phase membership (LNCH screen has three phases):
     - PRE-LAUNCH (Screen_LNCH_PreLaunch.ino)  — auto, when sit_PreLaunch is set
     - ASCENT     (Screen_LNCH_Ascent.ino)     — when below switch altitude
     - CIRC       (this file)                   — when above switch altitude

   Top-level dispatcher Screen_LNCH.ino selects which of these to draw.

   Public-to-the-sketch entry points (called by the LNCH dispatcher):
     - _lnchOrResetState()              — clear all change-detection state
     - _lnchOrDrawRightPanelChrome(tft) — initial labels + dividers for right panel
     - _lnchOrDrawLeftPanelValues(tft)  — per-frame left panel updates (orbit + bar + ATT/IGN/BD)
     - _lnchOrDrawRightPanelValues(tft) — per-frame right panel value updates
****************************************************************************************/

// ── Orbital-phase left panel graphic ──────────────────────────────────────────────────
//
// Centred orbit curve with body at one focus, vessel marker (chevron pointing
// in direction of motion), Ap/Pe markers, and a dashed reference circle
// showing the target circular orbit altitude. A "Time to Apoapsis" progress
// bar sits below the diagram to give an at-a-glance countdown to the
// circularization burn point.
//
// Layout summary (left graphics panel x=0..576, y=TITLE_TOP..SCREEN_H):
//   orbit diagram: LNCH_OR_DIAG_MAX_R=175 centered on (LNCH_OR_DIAG_CX=348, CY=272)
//   y=440..459: T+Ap progress bar (20 px tall, labeled on the left)
//
// The vessel chevron points along the tangent of the drawn orbit curve at the
// vessel's true-anomaly position. Direction of travel (CCW vs CW) is inferred
// from `state.inclination` (< 90° = prograde/CCW, > 90° = retrograde/CW).
// Hero element: enlarged and centered in the graphics area to the right of the
// left "burn aids" rail (ATT + Burn Dur) and above the bottom ΔV/T+Ign band.
static const int16_t LNCH_OR_DIAG_CX    = 348;   // diagram center X (center-right of the widened panel)
static const int16_t LNCH_OR_DIAG_CY    = 272;   // diagram center Y (upper-center, above the bottom band)
static const int16_t LNCH_OR_DIAG_MAX_R = 175;   // max orbit half-extent (px) — was 140; leaves room for outboard Pe/Ap labels

// Maneuver ΔV bar layout. Matches the visual format of the MNVR screen's
// "ΔV Burn" bar: label "ΔV Burn" above-left, right-aligned ΔV value in m/s
// above-right, grey border, off-black background, green fill (yellow when
// stage ΔV is tight). Bar fills proportionally to mnvrDeltaV and drains
// from the cached arm-time max as the burn consumes ΔV.
//
// Full-width "burn timing" band across the bottom of the widened panel:
//   y = 483..512: bar label row ("ΔV Burn" left, ΔV value right — Black_24)
//   y = 518..544: ΔV bar (26 px incl. border) — 6 px below the label so the
//                 value's glyph rows don't clip the bar top
//   y = 551..591: T+Ign countdown row (Black_28, 40 px tall) — the "burn now" cue
// Horizontal: bar spans most of the 576-wide panel.
static const int16_t LNCH_OR_BAR_X      =  40;   // bar left edge
static const int16_t LNCH_OR_BAR_W      = 496;   // bar width (40..536)
static const int16_t LNCH_OR_BAR_H      =  26;   // bar height
static const int16_t LNCH_OR_BAR_Y      = 518;   // bar top
static const int16_t LNCH_OR_BAR_LBL_Y  = 483;   // bar label row top (Black_24 label; barY-35)
static const int16_t LNCH_OR_TIGN_Y     = 551;   // T+Ign row top (barY + barH + 7)
static const int16_t LNCH_OR_TIGN_H     =  40;   // T+Ign row height (Black_28=33 + margin)

// Attitude (ATT) indicator: a maneuver-alignment disc positioned to the
// right of the orbit diagram. Shows the vessel's current attitude error vs
// the maneuver's planned attitude (mnvrHeading, mnvrPitch) as a coloured
// dot within concentric rings.
//
// Scaled down from the LNDG attitude indicator: outer ring = 15° scale,
// rings at 5° / 10° / 15°, crosshairs at cardinal axes, dot clamped to
// outer ring. Dot colour: green (< 5°), yellow (< 15°), red (>= 15°).
// Inactive dark grey when no maneuver node is planned.
//
// The ATT/IGN/Burn-dur cluster sits on the LEFT side of the panel; the
// orbit diagram (LNCH_OR_DIAG_*) is on the RIGHT. Cluster CX=60 places
// the IGN button (widest at 104 px) at x=8..112, leaving ~28 px clearance
// to the orbit diagram's leftmost extent at x=140.
//
// ATT outer-ring radius matches the LNDG_Powered ATT indicator (R=52) for
// cross-screen visual consistency. CY=150 places the disc with a 7 px top
// margin below the panel, giving room for the Black_20 "ATT" label above.
static const int16_t LNCH_OR_ATT_CX    = 74;                     // indicator center X (left rail)
static const int16_t LNCH_OR_ATT_CY    = 172;                    // indicator center Y (top of the left rail)
static const int16_t LNCH_OR_ATT_R     = 58;                     // outer ring radius (= ±15°)
static const float   LNCH_OR_ATT_SCALE = (float)LNCH_OR_ATT_R / 15.0f;  // ~3.47 px/deg
static const float   LNCH_OR_ALIGN_GREEN_DEG  =  5.0f;   // < 5° = aligned (dot green)
static const float   LNCH_OR_ALIGN_YELLOW_DEG = 15.0f;   // < 15° = close (dot yellow)

// Burn-duration readout: a centered label+value block placed below the ATT
// disc. Both label and value horizontally-centered around LNCH_OR_ATT_CX.
//   Label: "BURN DUR" in Black_20 light grey
//   Value: formatTimeCompact(mnvrDuration) in Black_24 dark green
//          ("---" in dark grey when no maneuver node)
// First left-rail slot, below the ATT disc. Was the burn-duration readout; that moved
// to the right column, and this slot now carries eccentricity — how circular the orbit
// in the diagram beside it actually is.
static const int16_t LNCH_OR_ECC_LBL_Y = 258;                              // disc bottom 230 + margin
static const int16_t LNCH_OR_ECC_VAL_Y = LNCH_OR_ECC_LBL_Y + 27;           // 24 px label + 3 px gap

// ΔV-to-circularize readout: fills the left-rail whitespace below Burn Dur.
// Standalone vis-viva estimate of the ΔV needed to circularize at apoapsis (the
// key pre-burn planning number). Label + prominent value, centered on the ATT
// column. Vertically centered in the gap between Burn Dur and the bottom band.
// Second left-rail slot. Was the ΔV-to-circularise readout; that moved to the right
// column with the other two burn numbers, and this slot now carries the apsis gap —
// the number the orbit diagram directly above it is a picture of.
static const int16_t LNCH_OR_GAP_LBL_Y = 372;   // label row ("AP-PE", Black_20)
static const int16_t LNCH_OR_GAP_VAL_Y = 400;   // value row (Black_28)



// ── Orbital (circularization) phase change-detection state ────────────────────────────
// This was eight rows mirroring the ascent readout. T.Brn is the only one that stayed;
// the apsis tape further down owns the rest of the column now.
static int32_t _lnchOrPrevTBurn      = -1 << 30;  // seconds

// T.Brn is the one row that survived the eight-row readout this column used to be; the
// rest of that panel's change-detection state went with it. See the apsis tape below.
static uint16_t _lnchOrPrevTBurnFg   = 0xFFFF; static uint16_t _lnchOrPrevTBurnBg = 0xFFFF;


// ── Orbit graphic prev-frame state (for erase-then-redraw, no full wipe) ─────────────
// The static layer (body, atmosphere ring, dashed target circle) is drawn once
// at chrome time and doesn't need per-frame redraw unless the SOI changes.
// Dynamic elements (orbit curve, Pe/Ap markers, vessel) are erased individually
// at their prev pixel positions and redrawn in new positions each frame. This
// avoids the visible flicker caused by a fullRect black wipe every frame.
//
// ORBIT_CURVE_N = number of line segments in the orbit curve (same as N in the
// drawing loop). Array size = ORBIT_CURVE_N + 1 points (segments are between
// consecutive points).
static const uint8_t LNCH_OR_CURVE_N = 96;
static int16_t _lnchOrPrevCurveX[LNCH_OR_CURVE_N + 1];
static int16_t _lnchOrPrevCurveY[LNCH_OR_CURVE_N + 1];
static bool    _lnchOrPrevCurveValid = false;
static int16_t _lnchOrPrevPeX = -1;
static int16_t _lnchOrPrevPeY = -1;
static int16_t _lnchOrPrevPeLblX = -1;
static int16_t _lnchOrPrevPeLblY = -1;
static bool    _lnchOrPrevPeValid = false;
static int16_t _lnchOrPrevApX = -1;
static int16_t _lnchOrPrevApY = -1;
static int16_t _lnchOrPrevApLblX = -1;
static int16_t _lnchOrPrevApLblY = -1;
static bool    _lnchOrPrevApValid = false;
static int16_t _lnchOrPrevVslX = -1;
static int16_t _lnchOrPrevVslY = -1;
static bool    _lnchOrPrevVslValid = false;
// Direction-indicator chevron (embedded on orbit curve at ν=90° for prograde,
// ν=270° for retrograde). Shares lifecycle with the orbit curve — redrawn
// when orbit curve changes.
static int16_t _lnchOrPrevDirX = -1;
static int16_t _lnchOrPrevDirY = -1;
static bool    _lnchOrPrevDirValid = false;
// Previously-drawn orbit curve colour (for detecting colour-only changes).
static uint16_t _lnchOrPrevOrbitCol = 0;
// Previously-drawn static layer geometry. When atmo_px or target_px change
// (due to compressed-scaling recomputation as orbit drifts), we need to
// erase the OLD static layer rings first before redrawing at new radii —
// otherwise the old ring stays on screen and successive draws accumulate
// into a visibly thick line.
static int16_t _lnchOrPrevAtmoPx   = -1;
static int16_t _lnchOrPrevTargetPx = -1;
static int16_t _lnchOrPrevBodyPx   = -1;
// T+Ap progress bar prev-state (fill width in pixels, fill colour)
// Maneuver bar prev-state. Fill width in pixels, fill colour, and the
// cached "max ΔV" used to compute fill fraction (burn starts → lock max;
// burn progresses → mnvrDeltaV drains; ratio = current/max = fill fraction).
// Max is reset to 0 when the maneuver node disappears.
//
// prevBarDvRounded: mnvrDeltaV rounded to the nearest whole m/s for the
// right-aligned value text ("%.0fm/s"). When this changes (or colour
// changes), we re-render the value text. -9999 = not yet drawn.
static int16_t  _lnchOrPrevBarFill = -1;    // -1 = not drawn yet
static uint16_t _lnchOrPrevBarCol  = 0;
static int16_t  _lnchOrPrevBarDvRounded = -9999;
// Text colour of the value text (distinct from fill_col — the value text uses
// dim light grey in estimate mode even though the bar fill is dark grey).
// 0 = not yet drawn.
static uint16_t _lnchOrPrevBarTextCol = 0;
static bool     _lnchOrPrevBarEstimate = false;
static float    _lnchOrMnvrMaxDV   = 0.0f;  // cached maximum ΔV seen, m/s
// T+Ign countdown row (below the bar). Shows time-until-ignition for the
// upcoming maneuver burn (mnvrTime - mnvrDuration/2), with the same colour
// thresholds as the MNVR screen. Uses the library printValue helper (which
// manages its own change-detection via PrintState). prevTignSec is an
// additional rounded-seconds cache so we can skip the printValue call
// entirely when the rounded value and colours are unchanged (-9999 = not
// yet drawn, -9998 = currently showing "---" placeholder).
static int32_t   _lnchOrPrevTignSec = -9999;
static uint16_t  _lnchOrPrevTignFg  = 0;
static uint16_t  _lnchOrPrevTignBg  = 0;
static PrintState _lnchOrTignPs;
// ATT indicator prev-frame state (dot position + colour). The chrome (rings,
// crosshairs) is drawn once and not retracked — touch-up on dot move
// repairs any damage. 9999 = not drawn yet / needs first-frame init.
static int16_t   _lnchOrPrevAttDotX = 9999;
static int16_t   _lnchOrPrevAttDotY = 9999;
static uint16_t  _lnchOrPrevAttDotCol = 0;
// Burn-duration and ΔV-to-circularise readouts. Both now live in the right column
// beside stage burn time -- the three numbers that describe the burn, together --
// but their change detection is unchanged: rounded value, -9999 = not drawn,
// -9998 = showing the "---" placeholder.
static int32_t   _lnchOrPrevBurnDurSec = -9999;
static int32_t   _lnchOrPrevCircDvRounded = -9999;
// Left-rail readouts: eccentricity (x1000) and the apsis gap (metres). These describe
// the shape of the orbit, so they sit with the picture of it rather than with the burn.
static int32_t   _lnchOrPrevEccMilli = -9999;
static int32_t   _lnchOrPrevGapM     = -9999;
// SOI name we last drew the static layer for. If SOI changes mid-session, we
// need to redraw the static layer.
static char _lnchOrPrevSoi[24] = {0};

// ── Apsis convergence tape state ──────────────────────────────────────────────────────
// Up here rather than beside the tape's drawing code further down, because
// _lnchOrResetState() below clears it. The ApsisTape frame type lives in
// KCMk1_InfoDisp.h -- see the note there on why it cannot live in this file.
//
// Note the Tp prefix on these: _lnchOrPrevApY / _lnchOrPrevPeY are already the orbit
// diagram's own Ap/Pe marker pixels a hundred lines above, and _lnchOrPrevPeVal would
// have been a prefix of its _lnchOrPrevPeValid.
static ApsisTape  _lnchOrTape      = { 0.0f, 0.0f, 0.0f, false };
static bool       _lnchOrTapeDirty = true;   // scale changed -> static layer needs redraw
static int16_t    _lnchOrTpApY     = -9999;  // last-drawn marker rows (-9999 = never drawn)
static int16_t    _lnchOrTpPeY     = -9999;
static bool       _lnchOrTpPeLow   = false;  // periapsis was off the bottom of the scale
static int32_t    _lnchOrTpApVal   = -1 << 30;
static int32_t    _lnchOrTpPeVal   = -1 << 30;
static PrintState _lnchOrTpPs[3];


// Reset all orbital-phase change-detection state + PrintState. Called at
// chrome time to force a full redraw.
static void _lnchOrResetState() {
    _lnchOrPrevTBurn      = -1 << 30;
    _lnchOrPrevTBurnFg    = 0xFFFF; _lnchOrPrevTBurnBg = 0xFFFF;
    _lnchOrPrevEccMilli   = -9999;
    _lnchOrPrevGapM       = -9999;

    // Apsis tape: drop the frame so the first update recomputes and redraws the scale,
    // and forget the marker rows so nothing is erased at a stale position.
    _lnchOrTape.valid = false;
    _lnchOrTapeDirty  = true;
    _lnchOrTpApY      = -9999;     _lnchOrTpPeY   = -9999;
    _lnchOrTpPeLow    = false;
    _lnchOrTpApVal    = -1 << 30;  _lnchOrTpPeVal = -1 << 30;
    for (uint8_t i = 0; i < 3; i++) {
        _lnchOrTpPs[i].prevWidth  = 0;
        _lnchOrTpPs[i].prevBg     = 0x0001;
        _lnchOrTpPs[i].prevHeight = 0;
    }
    // Invalidate global printState slots (shared across phases).
    for (uint8_t i = 0; i < ROW_COUNT; i++) {
        printState[screen_LNCH][i].prevWidth  = 0;
        printState[screen_LNCH][i].prevBg     = 0x0001;
        printState[screen_LNCH][i].prevHeight = 0;
    }
    // Invalidate orbit-graphic prev-frame cache so the first frame does a
    // full draw (static layer + all dynamic elements) without trying to
    // erase stale previous pixels.
    _lnchOrPrevCurveValid = false;
    _lnchOrPrevPeValid    = false;
    _lnchOrPrevApValid    = false;
    _lnchOrPrevVslValid   = false;
    _lnchOrPrevDirValid   = false;
    _lnchOrPrevOrbitCol   = 0;
    _lnchOrPrevAtmoPx     = -1;
    _lnchOrPrevTargetPx   = -1;
    _lnchOrPrevBodyPx     = -1;
    _lnchOrPrevBarFill    = -1;
    _lnchOrPrevBarCol     = 0;
    _lnchOrPrevBarDvRounded = -9999;
    _lnchOrPrevBarTextCol = 0;
    _lnchOrPrevBarEstimate = false;
    _lnchOrPrevTignSec    = -9999;
    _lnchOrPrevTignFg     = 0;
    _lnchOrPrevTignBg     = 0;
    _lnchOrTignPs.prevWidth  = 0;
    _lnchOrTignPs.prevBg     = 0x0001;
    _lnchOrTignPs.prevHeight = 0;
    _lnchOrPrevAttDotX    = 9999;
    _lnchOrPrevAttDotY    = 9999;
    _lnchOrPrevAttDotCol  = 0;
    _lnchOrPrevBurnDurSec = -9999;
    _lnchOrPrevCircDvRounded = -9999;
    _lnchOrMnvrMaxDV      = 0.0f;
    _lnchOrPrevSoi[0]     = '\0';
}

// ── Orbital (circularization) phase — right panel ─────────────────────────────────────
//
/***************************************************************************************
   APSIS CONVERGENCE TAPE — the right third of the circularisation screen
****************************************************************************************

   This column used to be eight numeric rows mirroring the ascent phase: Alt.SL, V.Orb,
   ApA, PeA, T+Ap, Thrtl, T.Brn, dV.Stg. Seven of the eight also sit on the PFD on the
   other panel, in every phase this screen is up -- so 38% of the display was restating
   the display beside it, and the one relationship the pilot is actually flying appeared
   on neither.

   A circularisation burn is a single task: raise periapsis until it meets apoapsis. Both
   numbers are on the PFD, but the *gap between them* and the rate it is closing are not,
   and no readout can show a rate. So the column becomes a vertical altitude tape with
   apoapsis fixed near the top, periapsis climbing to meet it, and the orbit-safe altitude
   drawn as the floor the orbit has to clear. Three rows beneath carry the only numbers on
   this screen the PFD does not already have.

   Why the tape and not a bigger orbit diagram: the diagram is height-boxed, with 35 px of
   slack above it and 36 below. The freed space is 360 px of *width*, and a tape is the
   instrument that fits a tall narrow column.

   SCALE. Ends are quantised to whole tick steps, so the frame only moves when apoapsis
   crosses a step boundary rather than drifting every frame -- one rescale across a whole
   Kerbin circularisation burn, measured on the host. The step is chosen 1-2-5 and walked
   upward until the tape carries at most eight ticks, because quantising the ends widens
   the range and can otherwise ask for more labels than there is room to draw.

   A suborbital periapsis is hundreds of kilometres below the surface and cannot be framed
   with the apoapsis. Its marker clamps to the bottom of the scale and draws hollow, the
   way an off-scale value is annunciated on a real tape; it fills in as the burn brings the
   periapsis up into view. That transition -- hollow at the bottom, then rising -- is the
   burn starting to work.
****************************************************************************************/

static const int16_t LNCH_OR_TP_X       = 580;                          // column left edge
static const int16_t LNCH_OR_TP_W       = 360;
static const int16_t LNCH_OR_TP_RIGHT   = LNCH_OR_TP_X + LNCH_OR_TP_W;  // 940
static const int16_t LNCH_OR_TP_HDR_Y   = 68;                           // header label row
static const int16_t LNCH_OR_TP_Y       = 104;                          // scale top
static const int16_t LNCH_OR_TP_H       = 356;                          // scale height -> 104..460
static const int16_t LNCH_OR_TP_RAIL_X  = LNCH_OR_TP_X + 96;            // 676 — the scale line
static const int16_t LNCH_OR_TP_TICK_W  = 9;                            // tick length, left of rail
static const int16_t LNCH_OR_TP_MK_W    = 18;                           // marker triangle length
static const int16_t LNCH_OR_TP_MK_H    = 9;                            // marker half-height
static const int16_t LNCH_OR_TP_LBL_X   = LNCH_OR_TP_RAIL_X + LNCH_OR_TP_MK_W + 9;   // 703
static const int16_t LNCH_OR_TP_GAP_X   = LNCH_OR_TP_X + 30;            // 610 — gap bracket
static const int16_t LNCH_OR_TP_STRIP_H = 21;                           // marker erase half-height

// Numeric block under the tape — three rows, the only values here the PFD lacks.
static const int16_t LNCH_OR_TP_ROW_Y   = 476;
static const int16_t LNCH_OR_TP_ROW_H   = 41;                           // 3 rows -> 476..598



// Orbit-safe altitude: top of the atmosphere where there is one, highest terrain where
// there is not. The same max(minSafe, lowSpace) the mission ladder uses to decide whether
// an orbit exists yet, so the floor on this tape and the rule that put this screen up
// cannot disagree.
static float _lnchOrTapeFloor() {
    return (currentBody.minSafe > currentBody.lowSpace) ? currentBody.minSafe
                                                        : currentBody.lowSpace;
}

// Next 1-2-5 step above the given one, so the tick search can walk upward.
static float _lnchOrTapeStepUp(float step) {
    float mag = powf(10.0f, floorf(log10f(step * 1.0001f)));
    float n   = step / mag;
    return (n < 1.5f) ? 2.0f * mag : (n < 3.5f) ? 5.0f * mag : 10.0f * mag;
}

static float _lnchOrTapeStep(float span) {
    if (span <= 0.0f) return 1.0f;
    float raw = span / 6.0f;
    float mag = powf(10.0f, floorf(log10f(raw)));
    float n   = raw / mag;
    float m   = (n <= 1.5f) ? 1.0f : (n <= 3.5f) ? 2.0f : (n <= 7.5f) ? 5.0f : 10.0f;
    return m * mag;
}

static ApsisTape _lnchOrTapeScale() {
    ApsisTape t; t.valid = false; t.top = t.bottom = t.step = 0.0f;
    const float fl = _lnchOrTapeFloor();
    const float ap = state.apoapsis;
    if (ap <= 0.0f || fl <= 0.0f || ap <= fl) return t;   // no orbit to frame yet

    const float band = ap - fl;
    float rawTop = ap + band * 0.12f;                     // headroom above apoapsis
    float rawBot = fl - band * 0.18f;                     // a little air under the floor
    if (rawBot < 0.0f) rawBot = 0.0f;

    // Quantising the ends to whole steps widens the range, which can ask for more ticks
    // than the tape has room to label. Walk the step up until it fits.
    float step = _lnchOrTapeStep(rawTop - rawBot);
    for (uint8_t guard = 0; guard < 8; guard++) {
        t.top    = ceilf(rawTop / step) * step;
        t.bottom = floorf(rawBot / step) * step;
        if ((t.top - t.bottom) / step <= 8.5f) break;
        step = _lnchOrTapeStepUp(step);
    }
    t.step = step;
    if (t.top <= t.bottom) return t;
    t.valid = true;
    return t;
}

// Re-frame only when apoapsis is no longer comfortably inside the current scale. Holding
// the frame is what keeps the ticks still while the periapsis marker moves.
static void _lnchOrTapeEnsureScale() {
    const float ap = state.apoapsis;
    if (_lnchOrTape.valid) {
        const float span = _lnchOrTape.top - _lnchOrTape.bottom;
        if (ap > _lnchOrTape.bottom + 0.02f * span && ap < _lnchOrTape.top - 0.03f * span)
            return;
    }
    ApsisTape t = _lnchOrTapeScale();
    if (t.valid && (t.top != _lnchOrTape.top || t.bottom != _lnchOrTape.bottom)) {
        _lnchOrTape = t;
        _lnchOrTapeDirty = true;
    } else if (t.valid) {
        _lnchOrTape = t;
    } else if (_lnchOrTape.valid) {
        _lnchOrTape.valid = false;
        _lnchOrTapeDirty = true;
    }
}

// Altitude -> screen row, clamped to the tape. `below` reports an off-scale value, which
// the caller annunciates rather than drawing at a lie of a position.
static int16_t _lnchOrTapeYFor(float alt, bool &below) {
    const float span = _lnchOrTape.top - _lnchOrTape.bottom;
    float f = (span > 0.0f) ? (_lnchOrTape.top - alt) / span : 1.0f;
    below = (f > 1.0f);
    if (f < 0.0f) f = 0.0f; else if (f > 1.0f) f = 1.0f;
    return LNCH_OR_TP_Y + (int16_t)lroundf(f * (float)LNCH_OR_TP_H);
}

// Compact tick label: "70k", "1.2M" — the scale needs the magnitude, not the metres.
static void _lnchOrTapeTickText(float alt, char *buf, uint8_t n) {
    float a = fabsf(alt);
    if (a >= 1.0e6f)      snprintf(buf, n, "%.1fM", alt / 1.0e6f);
    else if (a >= 1000.0f) snprintf(buf, n, "%.0fk", alt / 1000.0f);
    else                   snprintf(buf, n, "%.0f", alt);
}

// ── Static layer: rail, ticks, tick labels, and the orbit-safe floor ──────────────────
// Redrawn only when the scale changes, which the quantised ends make rare.
// The divider between the tape and the three rows beneath it. Drawn by the rows
// chrome, and again by anything above it whose erase reaches it: the static wipe and
// a marker strip for a periapsis clamped at the bottom of the scale both do.
static void _lnchOrTapeDrawRowsDivider(KCM_TFT &tft) {
    tft.drawLine(LNCH_OR_TP_X + 6, LNCH_OR_TP_ROW_Y - 6,
                 LNCH_OR_TP_RIGHT - 6, LNCH_OR_TP_ROW_Y - 6, TFT_GREY);
}

static void _lnchOrTapeDrawStatic(KCM_TFT &tft) {
    tft.fillRect(LNCH_OR_TP_X, LNCH_OR_TP_HDR_Y - 4,
                 LNCH_OR_TP_W, (LNCH_OR_TP_Y + LNCH_OR_TP_H + 26) - (LNCH_OR_TP_HDR_Y - 4),
                 TFT_BLACK);
    _lnchOrTapeDrawRowsDivider(tft);

    textCenter(tft, &Roboto_Black_20, LNCH_OR_TP_X, LNCH_OR_TP_HDR_Y, LNCH_OR_TP_W, 26,
               "APSIS CONVERGENCE", TFT_LIGHT_GREY, TFT_BLACK);

    if (!_lnchOrTape.valid) {
        textCenter(tft, &Roboto_Black_24, LNCH_OR_TP_X, LNCH_OR_TP_Y + LNCH_OR_TP_H / 2 - 18,
                   LNCH_OR_TP_W, 36, "NO ORBIT", TFT_DARK_GREY, TFT_BLACK);
        return;
    }

    tft.drawLine(LNCH_OR_TP_RAIL_X, LNCH_OR_TP_Y,
                 LNCH_OR_TP_RAIL_X, LNCH_OR_TP_Y + LNCH_OR_TP_H, TFT_GREY);

    tft.setFont(Roboto_Black_16);
    for (float a = _lnchOrTape.bottom; a <= _lnchOrTape.top + _lnchOrTape.step * 0.01f;
         a += _lnchOrTape.step) {
        bool dummy;
        int16_t y = _lnchOrTapeYFor(a, dummy);
        tft.drawLine(LNCH_OR_TP_RAIL_X - LNCH_OR_TP_TICK_W, y, LNCH_OR_TP_RAIL_X, y, TFT_GREY);
        char buf[10];
        _lnchOrTapeTickText(a, buf, sizeof(buf));
        int16_t w = getFontStringWidth(&Roboto_Black_16, buf);
        tft.setTextColor(TFT_GREY, TFT_BLACK);
        tft.setCursor(LNCH_OR_TP_RAIL_X - LNCH_OR_TP_TICK_W - 5 - w, y - 10);
        tft.print(buf);
    }

    // The orbit-safe floor: below this line there is no orbit, only an aerobrake.
    bool below;
    int16_t yF = _lnchOrTapeYFor(_lnchOrTapeFloor(), below);
    if (!below) {
        for (int16_t x = LNCH_OR_TP_RAIL_X + 2; x < LNCH_OR_TP_RIGHT - 2; x += 8)
            tft.drawLine(x, yF, x + 3, yF, TFT_DARK_RED);
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_DARK_RED, TFT_BLACK);
        tft.setCursor(LNCH_OR_TP_LBL_X, yF + 5);
        tft.print(currentBody.hasAtmo ? "atmosphere" : "terrain");
    }
}

// Repair the floor's dashed line where a marker erase has just cut through it.
static void _lnchOrTapeRepairFloor(KCM_TFT &tft, int16_t yTop, int16_t yBot) {
    if (!_lnchOrTape.valid) return;
    bool below;
    int16_t yF = _lnchOrTapeYFor(_lnchOrTapeFloor(), below);
    if (below || yF < yTop || yF > yBot) return;
    for (int16_t x = LNCH_OR_TP_RAIL_X + 2; x < LNCH_OR_TP_RIGHT - 2; x += 8)
        tft.drawLine(x, yF, x + 3, yF, TFT_DARK_RED);
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_DARK_RED, TFT_BLACK);
    tft.setCursor(LNCH_OR_TP_LBL_X, yF + 5);
    tft.print(currentBody.hasAtmo ? "atmosphere" : "terrain");
}

// Erase the full-width strip a marker occupies, then repair what the wipe cut through.
//
// The strip starts ON the rail, not one pixel right of it: a marker's apex sits in the
// rail's own pixel column, so an erase that spared the rail would leave a coloured pixel
// behind at every position the marker had ever occupied. Wipe the column and redraw the
// rail segment instead.
static void _lnchOrTapeEraseStrip(KCM_TFT &tft, int16_t y) {
    int16_t y0 = y - LNCH_OR_TP_STRIP_H;
    int16_t h  = LNCH_OR_TP_STRIP_H * 2 + 1;
    if (y0 < LNCH_OR_TP_Y - LNCH_OR_TP_STRIP_H) y0 = LNCH_OR_TP_Y - LNCH_OR_TP_STRIP_H;

    tft.fillRect(LNCH_OR_TP_RAIL_X, y0, LNCH_OR_TP_RIGHT - LNCH_OR_TP_RAIL_X, h, TFT_BLACK);
    if (y0 + h > LNCH_OR_TP_ROW_Y - 6) _lnchOrTapeDrawRowsDivider(tft);

    int16_t r0 = (y0 < LNCH_OR_TP_Y) ? LNCH_OR_TP_Y : y0;
    int16_t r1 = (y0 + h > LNCH_OR_TP_Y + LNCH_OR_TP_H) ? LNCH_OR_TP_Y + LNCH_OR_TP_H
                                                        : (int16_t)(y0 + h);
    if (r1 >= r0) tft.drawLine(LNCH_OR_TP_RAIL_X, r0, LNCH_OR_TP_RAIL_X, r1, TFT_GREY);

    _lnchOrTapeRepairFloor(tft, y0, y0 + h);
}

// One marker: a triangle with its apex on the rail, and its label to the right. Hollow
// when the value is off the bottom of the scale.
static void _lnchOrTapeDrawMarker(KCM_TFT &tft, int16_t y, uint16_t col,
                                  const char *tag, float alt, bool low) {
    const int16_t ax = LNCH_OR_TP_RAIL_X,                    ay = y;
    const int16_t bx = LNCH_OR_TP_RAIL_X + LNCH_OR_TP_MK_W,  by = y - LNCH_OR_TP_MK_H;
    const int16_t cx = bx,                                   cy = y + LNCH_OR_TP_MK_H;
    if (low) {
        // Outline only. The display class exposes fillTriangle but not drawTriangle,
        // so the hollow form is three lines — the same reason the orbit diagram's
        // chevron below is drawn that way.
        tft.drawLine(ax, ay, bx, by, col);
        tft.drawLine(bx, by, cx, cy, col);
        tft.drawLine(cx, cy, ax, ay, col);
    } else {
        tft.fillTriangle(ax, ay, bx, by, cx, cy, col);
    }

    String txt = String(tag) + " " + (low ? String("---") : formatAlt(alt));
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(col, TFT_BLACK);
    tft.setCursor(LNCH_OR_TP_LBL_X, y - 14);
    tft.print(txt.c_str());
}

// The bracket spanning apoapsis to periapsis. This is the instrument's whole point: two
// markers say where the apsides are, the bracket says how far apart they still are.
static void _lnchOrTapeDrawGap(KCM_TFT &tft, int16_t yAp, int16_t yPe, uint16_t col) {
    if (yPe <= yAp + 3) return;
    tft.drawLine(LNCH_OR_TP_GAP_X, yAp, LNCH_OR_TP_GAP_X, yPe, col);
    tft.drawLine(LNCH_OR_TP_GAP_X, yAp, LNCH_OR_TP_GAP_X + 7, yAp, col);
    tft.drawLine(LNCH_OR_TP_GAP_X, yPe, LNCH_OR_TP_GAP_X + 7, yPe, col);
}

static void _lnchOrTapeEraseGap(KCM_TFT &tft, int16_t yAp, int16_t yPe) {
    if (yPe < yAp) { int16_t t = yAp; yAp = yPe; yPe = t; }
    tft.fillRect(LNCH_OR_TP_GAP_X - 1, yAp - 2, 10, (yPe - yAp) + 5, TFT_BLACK);
}


// ── Per-frame update ──────────────────────────────────────────────────────────────────
static void _lnchOrTapeUpdate(KCM_TFT &tft) {
    _lnchOrTapeEnsureScale();

    if (_lnchOrTapeDirty) {
        _lnchOrTapeDrawStatic(tft);
        _lnchOrTapeDirty = false;
        _lnchOrTpApY = _lnchOrTpPeY = -9999;      // markers were wiped with the layer
        _lnchOrTpApVal = _lnchOrTpPeVal = -1 << 30;
    }
    if (!_lnchOrTape.valid) return;

    bool apLow = false, peLow = false;
    const int16_t yAp = _lnchOrTapeYFor(state.apoapsis,  apLow);
    const int16_t yPe = _lnchOrTapeYFor(state.periapsis, peLow);

    // Round to whole metres so a jittering float does not repaint every frame.
    const int32_t apVal = (int32_t)lroundf(state.apoapsis);
    const int32_t peVal = (int32_t)lroundf(state.periapsis);
    const bool apMoved  = (yAp != _lnchOrTpApY) || (apVal != _lnchOrTpApVal);
    const bool peMoved  = (yPe != _lnchOrTpPeY) || (peVal != _lnchOrTpPeVal) ||
                          (peLow != _lnchOrTpPeLow);
    if (!apMoved && !peMoved) return;

    if (_lnchOrTpApY > -9000 && _lnchOrTpPeY > -9000)
        _lnchOrTapeEraseGap(tft, _lnchOrTpApY, _lnchOrTpPeY);
    // An erase strip can clip the other marker, so erase and redraw both rather than
    // track overlap.
    if (_lnchOrTpApY > -9000) _lnchOrTapeEraseStrip(tft, _lnchOrTpApY);
    if (_lnchOrTpPeY > -9000) _lnchOrTapeEraseStrip(tft, _lnchOrTpPeY);

    // Cyan apoapsis, magenta periapsis — the same two colours the orbit diagram gives
    // its Ap and Pe dots on the other half of this screen, so the marker on the tape and
    // the dot on the diagram read as the same apsis rather than two unrelated things.
    // State is annunciated by form instead of hue: the marker draws hollow while the
    // value is off the bottom of the scale, and the floor line says where the danger is.
    _lnchOrTapeDrawGap(tft, yAp, yPe, TFT_GREY);
    _lnchOrTapeDrawMarker(tft, yAp, TFT_CYAN,    "Ap", state.apoapsis,  apLow);
    _lnchOrTapeDrawMarker(tft, yPe, TFT_MAGENTA, "Pe", state.periapsis, peLow);

    _lnchOrTpApY = yAp; _lnchOrTpPeY = yPe; _lnchOrTpPeLow = peLow;
    _lnchOrTpApVal = apVal; _lnchOrTpPeVal = peVal;
}


// ── Numeric block: the burn, in three numbers ─────────────────────────────────────────
// How much velocity change the circularisation needs, how long the burn will take, and
// how long the stage can burn for. Read top to bottom they answer one question -- can
// this stage finish this burn -- which is why they sit together rather than scattered
// across the screen. The first two moved here from the left rail; the orbit-shape
// numbers that were here (Ecc, Ap-Pe) went the other way, to sit with the diagram.
//
// Stg.Brn is stage endurance from Simpit's BURNTIME_MESSAGE: seconds of thrust left in
// the tank, not a countdown of this burn. It was labelled T.Brn, which read like a
// time-to/through-burn beside two numbers that genuinely are about this burn.
static const char *const _lnchOrTpLabels[3] = { "\xCE\x94V.CIRC", "BURN DUR", "STG.BRN" };

// Row cell geometry. printValue reserves the label's width out of the same x0/w it is
// handed and does not repaint the label itself, so chrome and value share one cell.
static const int16_t LNCH_OR_TP_CELL_X = LNCH_OR_TP_X + 8;
static const int16_t LNCH_OR_TP_CELL_W = LNCH_OR_TP_W - 16;

static void _lnchOrTapeDrawRowsChrome(KCM_TFT &tft) {
    tft.fillRect(LNCH_OR_TP_X, LNCH_OR_TP_ROW_Y - 6, LNCH_OR_TP_W,
                 (SCREEN_H - 1) - (LNCH_OR_TP_ROW_Y - 6), TFT_BLACK);
    _lnchOrTapeDrawRowsDivider(tft);
    for (uint8_t r = 0; r < 3; r++)
        printDispChrome(tft, &Roboto_Black_24, LNCH_OR_TP_CELL_X,
                        LNCH_OR_TP_ROW_Y + r * LNCH_OR_TP_ROW_H,
                        LNCH_OR_TP_CELL_W, LNCH_OR_TP_ROW_H,
                        _lnchOrTpLabels[r], COL_LABEL, COL_BACK, COL_NO_BDR);
}

static void _lnchOrTapeDrawRowValue(KCM_TFT &tft, uint8_t row, const String &val,
                                    uint16_t fg, uint16_t bg) {
    printValue(tft, &Roboto_Black_28, LNCH_OR_TP_CELL_X,
               LNCH_OR_TP_ROW_Y + row * LNCH_OR_TP_ROW_H,
               LNCH_OR_TP_CELL_W, LNCH_OR_TP_ROW_H,
               _lnchOrTpLabels[row], val, fg, bg, TFT_BLACK, _lnchOrTpPs[row]);
}

static void _lnchOrTapeUpdateRows(KCM_TFT &tft) {
    // Row 0 — ΔV to circularise at apoapsis, from vis-viva (see _lnchOrCircDvEstimate).
    {
        const float dv = _lnchOrCircDvEstimate();
        const int32_t iDv = (dv > 0.0f) ? (int32_t)lroundf(dv) : -9998;
        if (iDv != _lnchOrPrevCircDvRounded) {
            char buf[16];
            uint16_t fg;
            if (iDv <= -9998) { strcpy(buf, "---"); fg = TFT_DARK_GREY; }
            else { snprintf(buf, sizeof(buf), "%dm/s", (int)iDv); fg = TFT_DARK_GREEN; }
            _lnchOrTapeDrawRowValue(tft, 0, String(buf), fg, TFT_BLACK);
            _lnchOrPrevCircDvRounded = iDv;
        }
    }
    // Row 1 — how long the planned burn runs. Dashed with no node.
    {
        const bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f) &&
                             state.mnvrDuration > 0.0f;
        const int32_t sec = hasMnvr ? (int32_t)lroundf(state.mnvrDuration) : -9998;
        if (sec != _lnchOrPrevBurnDurSec) {
            _lnchOrTapeDrawRowValue(tft, 1,
                hasMnvr ? formatTimeCompact(state.mnvrDuration) : String("---"),
                hasMnvr ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
            _lnchOrPrevBurnDurSec = sec;
        }
    }
    // Row 2 — stage endurance. Same thresholds as the ascent readout, but drawn on this
    // column's own geometry: _lnchAs2UpdateTBurn() lays its value out on the 67 px
    // ascent rows and would put this one 200 px up the screen.
    {
        const float tb = state.stageBurnTime;
        const int32_t iTb = (int32_t)lroundf(tb);
        uint16_t fg, bg;
        thresholdColor(tb,
                       LNCH_BURNTIME_ALARM_S, TFT_WHITE,  TFT_RED,
                       LNCH_BURNTIME_WARN_S,  TFT_YELLOW, TFT_BLACK,
                       TFT_DARK_GREEN, TFT_BLACK, fg, bg);
        if (iTb != _lnchOrPrevTBurn || fg != _lnchOrPrevTBurnFg || bg != _lnchOrPrevTBurnBg) {
            _lnchOrTapeDrawRowValue(tft, 2, formatTimeCompact(tb), fg, bg);
            _lnchOrPrevTBurn = iTb;
            _lnchOrPrevTBurnFg = fg; _lnchOrPrevTBurnBg = bg;
        }
    }
}



// Static chrome for the right column — header, scale and row labels.
static void _lnchOrDrawRightPanelChrome(KCM_TFT &tft) {
    tft.drawLine(LNCH_OR_TP_X - 2, TITLE_TOP, LNCH_OR_TP_X - 2, SCREEN_H - 1, TFT_GREY);
    tft.drawLine(LNCH_OR_TP_X - 1, TITLE_TOP, LNCH_OR_TP_X - 1, SCREEN_H - 1, TFT_GREY);
    _lnchOrTapeDirty = true;          // _lnchOrTapeUpdate draws the scale on the first frame
    _lnchOrTapeDrawRowsChrome(tft);
}

static void _lnchOrDrawRightPanelValues(KCM_TFT &tft) {
    _lnchOrTapeUpdate(tft);
    _lnchOrTapeUpdateRows(tft);
}


// ── Orbital phase — left-panel orbit graphic ──────────────────────────────────────────
//
// Shows the vessel's current orbit as a closed curve with the body at one
// focus, plus a dashed reference circle at the target circular orbit altitude.
// The vessel, apoapsis, and periapsis are marked.
//
// SCALING NOTE: A realistic 1:1 scale would make the body dominate the panel
// (e.g. a 90 km orbit around Kerbin's 600 km radius leaves a thin 15 % ring).
// Instead we use COMPRESSED RADIAL SCALING: body surface maps to 55 % of
// MAX_R, and the altitude band (surface..max radius) maps to the remaining
// 45 %. This exaggerates the visible orbit ring so Ap/Pe distances and
// eccentricity are much easier to read. The body still draws as a true circle
// (radial compression is symmetric); only the orbit curve is distorted from
// a true ellipse.
//
// Orbit radius as a function of true anomaly ν:
//   r(ν) = a·(1-e²) / (1 + e·cos(ν))
// At ν=0:  r = a·(1-e) = rPe  (periapsis)
// At ν=π:  r = a·(1+e) = rAp  (apoapsis)
// Vessel angle from body center = argOfPe + ν

// Body and atmosphere colors come from the shared lookups in AAA_Screens.ino
// (kspBodyColor, kspAtmoColor) so ORB and LNCH (Circularization) cannot drift
// apart on per-body visuals.

// Draw the full orbital graphic: body, atmosphere ring, target circle, orbit
// curve, vessel, Ap marker, Pe marker. Uses COMPRESSED RADIAL SCALING so the
// orbit ring (where all the interesting action is for circularization) gets
// most of the panel pixels: body is capped at 55 % of MAX_R, the altitude
// band gets the remaining 45 %. Orbit curve is no longer a true ellipse — it's
// a polar-parametric closed curve using r(nu) = a(1-e²)/(1+e·cos(nu)), with
// each radius remapped through the compression function. Markers and vessel
// use the same compression so they stay on the curve.
//
// Draw the static layer of the orbit graphic: body, atmosphere ring, dashed
// target circle. These do NOT change frame-to-frame (they depend only on the
// SOI) and don't need to be erased/redrawn every frame. Called once at entry
// to orbital mode, and again only if the SOI changes.
//
// Note: the drawing ORDER is atmosphere → target-circle → body so the body
// disc overlaps (hides) any atmosphere ring pixels that fall inside it (they
// shouldn't — atmo_px > body_px — but belt-and-braces).
static void _lnchOrDrawStaticLayer(KCM_TFT &tft,
                                   int16_t CX, int16_t CY,
                                   int16_t body_px, int16_t atmo_px, int16_t target_px,
                                   uint16_t bodyCol, uint16_t atmoCol) {
    // Atmosphere ring
    if (atmo_px > body_px && atmoCol != 0) {
        tft.drawCircle(CX, CY, atmo_px, atmoCol);
    }
    // Body disc
    tft.fillCircle(CX, CY, body_px, bodyCol);
    // Dashed target circle (40 segments, draw 1 of every 2 → dashed pattern)
    const int N = 40;
    const int skip = 2;
    float dtheta = 2.0f * (float)PI / N;
    int16_t px = CX + target_px;
    int16_t py = CY;
    for (int i = 1; i <= N; i++) {
        float theta = i * dtheta;
        int16_t nx = CX + (int16_t)roundf((float)target_px * cosf(theta));
        int16_t ny = CY - (int16_t)roundf((float)target_px * sinf(theta));
        if ((i % skip) == 0) {
            tft.drawLine(px, py, nx, ny, TFT_LIGHT_GREY);
        }
        px = nx; py = ny;
    }
}

// Check whether the vessel's current SOI differs from the last-drawn SOI.
// When it does (rare mid-flight event), we'll need to redraw the static layer.
static bool _lnchOrSoiChanged() {
    const char *name = currentBody.soiName;
    if (!name) name = "";
    return strncmp(_lnchOrPrevSoi, name, sizeof(_lnchOrPrevSoi)) != 0;
}

// Draw a small filled chevron (triangle) pointing along a heading. Used as
// the orbit-direction indicator — a compact arrow embedded on the orbit
// curve at ν=90° that shows which way the vessel travels.
// dx, dy = unit vector in direction of travel (screen coordinates, y grows down).
// Triangle is 12 px long × 10 px wide base, pointing forward.
static void _lnchOrDrawChevron(KCM_TFT &tft, int16_t cx, int16_t cy,
                                float dx, float dy, uint16_t col) {
    // Perpendicular (rotated 90° CW in screen coords: px=+dy, py=-dx)
    float px = dy;
    float py = -dx;
    // Tip: 10 px forward from (cx, cy)
    int16_t tip_x  = cx + (int16_t)roundf(10.0f * dx);
    int16_t tip_y  = cy + (int16_t)roundf(10.0f * dy);
    // Base corners: 7 px backward, ±7 px perpendicular
    int16_t bl_x   = cx - (int16_t)roundf(7.0f * dx + 7.0f * px);
    int16_t bl_y   = cy - (int16_t)roundf(7.0f * dy + 7.0f * py);
    int16_t br_x   = cx - (int16_t)roundf(7.0f * dx - 7.0f * px);
    int16_t br_y   = cy - (int16_t)roundf(7.0f * dy - 7.0f * py);
    tft.fillTriangle(tip_x, tip_y, bl_x, bl_y, br_x, br_y, col);
    // Dark outline for contrast against any background color. Drawn as three
    // drawLine calls rather than drawTriangle for library portability.
    tft.drawLine(tip_x, tip_y, bl_x, bl_y, TFT_BLACK);
    tft.drawLine(bl_x,  bl_y,  br_x, br_y, TFT_BLACK);
    tft.drawLine(br_x,  br_y,  tip_x, tip_y, TFT_BLACK);
}

// Draw the maneuver-bar chrome: "ΔV Burn" label above the bar (left-aligned),
// grey rectangular border, off-black interior background. Also draws the
// T+Ign row label ("T+IGN") via printDispChrome. Bar fill, bar ΔV value,
// and T+Ign time value are all handled by per-frame update functions with
// change detection.
static void _lnchOrDrawProgressBarChrome(KCM_TFT &tft) {
    // "ΔV Burn" label above the bar, left-aligned with the bar's left edge.
    // Black_20 (24 px) — matches the "ATT" and "BURN DUR" labels in the
    // left cluster for cluster/screen-wide label-hierarchy consistency.
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LNCH_OR_BAR_X, LNCH_OR_BAR_LBL_Y);
    tft.print("\xCE\x94V Burn");  // UTF-8 for "ΔV Burn"
    // Grey border + off-black interior (matches MNVR screen)
    tft.drawRect(LNCH_OR_BAR_X, LNCH_OR_BAR_Y,
                 LNCH_OR_BAR_W, LNCH_OR_BAR_H, TFT_GREY);
    tft.fillRect(LNCH_OR_BAR_X + 1, LNCH_OR_BAR_Y + 1,
                 LNCH_OR_BAR_W - 2, LNCH_OR_BAR_H - 2, TFT_OFF_BLACK);

    // T+Ign row label — use library printDispChrome so the cell geometry and
    // padding match the rest of the right-panel label convention. No border
    // (COL_NO_BDR). Background is black — the value's alarm background is
    // applied only to the value region by printValue.
    printDispChrome(tft, &Roboto_Black_28,
                    LNCH_OR_BAR_X, LNCH_OR_TIGN_Y,
                    LNCH_OR_BAR_W, LNCH_OR_TIGN_H,
                    "T+IGN", TFT_LIGHT_GREY, TFT_BLACK, COL_NO_BDR);
}

// Estimated ΔV (m/s) to circularize at apoapsis (vis-viva). Returns -1 if the
// orbit data isn't usable (sub-orbital, no apoapsis, negative result, etc.).
//   μ       = surfGrav × bodyR²        (standard gravitational parameter)
//   rAp     = apoapsis + bodyR
//   sma     = (rAp + (periapsis + bodyR)) / 2
//   v_circ  = sqrt(μ / rAp)            (target circular v at Ap)
//   v_curr  = sqrt(μ × (2/rAp − 1/sma))(current v at Ap, vis-viva)
//   ΔV_circ = v_circ − v_curr
static float _lnchOrCircDvEstimate() {
    float bodyR = currentBody.radius;
    float g     = currentBody.gravity;   // rev-2: m/s²
    if (bodyR <= 0.0f || g <= 0.0f || state.apoapsis <= 0.0f) return -1.0f;
    float mu   = g * bodyR * bodyR;
    float rAp  = state.apoapsis + bodyR;
    float rPe  = fmaxf(state.periapsis + bodyR, bodyR);   // clamp to surface
    float sma  = (rAp + rPe) * 0.5f;
    if (sma <= 0.0f || rAp <= 0.0f) return -1.0f;
    float v_circ_sq = mu / rAp;
    float v_curr_sq = mu * (2.0f / rAp - 1.0f / sma);
    if (v_circ_sq <= 0.0f || v_curr_sq <= 0.0f) return -1.0f;
    float dvEst = sqrtf(v_circ_sq) - sqrtf(v_curr_sq);
    if (dvEst <= 0.0f || dvEst >= 100000.0f) return -1.0f;   // guard sub-orbital / nonsense
    return dvEst;
}

// Update the maneuver-bar fill. Called each frame during orbital phase.
//
// Visual format matches the MNVR screen's "ΔV Burn" bar: grey border, off-
// black interior background, green fill (yellow when stage ΔV is tight —
// less than 110 % of node ΔV), with a right-aligned "%.0fm/s" value readout
// in the label row above the bar.
//
// Fill logic (intentionally different from MNVR — drains cleanly during the
// actual burn):
//   - No maneuver node (mnvrTime==0 && mnvrDeltaV==0): bar empty, value text
//     cleared. Cached max is reset to 0.
//   - Fresh maneuver node: cache mnvrDeltaV as max, draw bar full.
//   - mnvrDeltaV grows above cached max: re-arm (handles user adjusting node).
//   - mnvrDeltaV shrinks (burn in progress): fill fraction = current / max,
//     bar drains toward empty.
//
// Change detection on fill width, colour, and rounded value — skips redraws
// when nothing visually changed.
static void _lnchOrUpdateProgressBar(KCM_TFT &tft) {
    bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f);

    // Compute target fill width, colour, and value-text state.
    int16_t  fill_px;
    uint16_t fill_col;
    int16_t  dv_rounded;   // -9999 = no value text
    bool     estimate_mode = false;  // true → prefix "est " and use dim colour
    if (!hasMnvr) {
        // No maneuver planned. Reset the drain cache, show an empty inactive
        // bar, but display the estimated ΔV to circularize at apoapsis as a
        // pre-planning hint (same value the standalone ΔV Circ readout shows).
        _lnchOrMnvrMaxDV = 0.0f;
        fill_px    = 0;
        fill_col   = TFT_DARK_GREY;
        dv_rounded = -9999;

        float dvEst = _lnchOrCircDvEstimate();
        if (dvEst > 0.0f) {
            dv_rounded    = (int16_t)roundf(dvEst);
            estimate_mode = true;
        }
    } else {
        // Maneuver node active. Update cached max if this is the first time
        // we see the node, or if mnvrDeltaV has grown (user adjusted node).
        // Small tolerance (0.5 m/s) to avoid thrashing on noise.
        if (_lnchOrMnvrMaxDV <= 0.0f ||
            state.mnvrDeltaV > _lnchOrMnvrMaxDV + 0.5f) {
            _lnchOrMnvrMaxDV = state.mnvrDeltaV;
        }
        float frac = (_lnchOrMnvrMaxDV > 0.001f)
                     ? state.mnvrDeltaV / _lnchOrMnvrMaxDV : 0.0f;
        if (frac < 0.0f) frac = 0.0f;
        if (frac > 1.0f) frac = 1.0f;
        fill_px = (int16_t)roundf(frac * (float)(LNCH_OR_BAR_W - 2));
        // Tight-stage warning: if stageDeltaV < mnvrDeltaV * 1.1, the pilot
        // may run out of stage ΔV before completing the maneuver — flag with
        // yellow instead of green.
        bool tight = (state.stageDeltaV < state.mnvrDeltaV * 1.1f);
        fill_col   = tight ? TFT_YELLOW : TFT_DARK_GREEN;
        dv_rounded = (int16_t)roundf(state.mnvrDeltaV);
    }

    // Colour used for the VALUE TEXT — in estimate mode use a dim light-grey
    // so the estimate is distinct from a live maneuver's bright fill colour.
    uint16_t text_col = estimate_mode ? TFT_LIGHT_GREY : fill_col;

    bool fill_changed  = (fill_px != _lnchOrPrevBarFill) ||
                         (fill_col != _lnchOrPrevBarCol);
    bool value_changed = (dv_rounded != _lnchOrPrevBarDvRounded) ||
                         (text_col  != _lnchOrPrevBarTextCol)   ||
                         (estimate_mode != _lnchOrPrevBarEstimate);

    // ── Fill update ─────────────────────────────────────────────────────────────
    if (fill_changed) {
        int16_t inner_x = LNCH_OR_BAR_X + 1;
        int16_t inner_y = LNCH_OR_BAR_Y + 1;
        int16_t inner_w = LNCH_OR_BAR_W - 2;
        int16_t inner_h = LNCH_OR_BAR_H - 2;
        if (fill_col != _lnchOrPrevBarCol) {
            // Colour changed: repaint whole interior — off-black background,
            // then fill in new colour.
            tft.fillRect(inner_x, inner_y, inner_w, inner_h, TFT_OFF_BLACK);
            if (fill_px > 0) {
                tft.fillRect(inner_x, inner_y, fill_px, inner_h, fill_col);
            }
        } else {
            // Same colour — delta draw only.
            if (fill_px > _lnchOrPrevBarFill) {
                int16_t dx = _lnchOrPrevBarFill;
                int16_t dw = fill_px - _lnchOrPrevBarFill;
                tft.fillRect(inner_x + dx, inner_y, dw, inner_h, fill_col);
            } else if (fill_px < _lnchOrPrevBarFill) {
                int16_t dx = fill_px;
                int16_t dw = _lnchOrPrevBarFill - fill_px;
                tft.fillRect(inner_x + dx, inner_y, dw, inner_h, TFT_OFF_BLACK);
            }
        }
        _lnchOrPrevBarFill = fill_px;
    }

    // ── Value text (right-aligned in label row) ─────────────────────────────────
    // Normal mode:   "245m/s" in bar colour.
    // Estimate mode: "est 145m/s" in dim light grey.
    // No value:      blank (e.g. no mnvr and no valid orbital data).
    if (value_changed) {
        // Clear the value-text region: right half of the bar width, same
        // row as the label. Height 31 px to fit Black_24 glyphs.
        int16_t valRegionX = LNCH_OR_BAR_X + LNCH_OR_BAR_W / 2;
        int16_t valRegionW = LNCH_OR_BAR_W / 2;
        tft.fillRect(valRegionX, LNCH_OR_BAR_LBL_Y, valRegionW, 31, TFT_BLACK);
        if (dv_rounded != -9999) {
            char buf[18];
            if (estimate_mode) {
                snprintf(buf, sizeof(buf), "est %dm/s", dv_rounded);
            } else {
                snprintf(buf, sizeof(buf), "%dm/s", dv_rounded);
            }
            // Black_24 — matches the "ΔV Burn" label font for visual unity.
            tft.setFont(Roboto_Black_24);
            tft.setTextColor(text_col, TFT_BLACK);
            int16_t tw = getFontStringWidth(&Roboto_Black_24, buf);
            tft.setCursor(LNCH_OR_BAR_X + LNCH_OR_BAR_W - tw, LNCH_OR_BAR_LBL_Y);
            tft.print(buf);
        }
        _lnchOrPrevBarDvRounded = dv_rounded;
        _lnchOrPrevBarTextCol   = text_col;
        _lnchOrPrevBarEstimate  = estimate_mode;
    }

    _lnchOrPrevBarCol = fill_col;
}

// Update the T+Ign (time-to-ignition) countdown row below the bar.
//
// The "T+IGN" label was drawn at chrome time via printDispChrome; this
// function only updates the time VALUE, using the library printValue helper
// so region clearing, padding, and right-alignment are all handled
// consistently with the rest of the app's label+value rows.
//
// Formula: T+Ign = mnvrTime - mnvrDuration/2 (burn midpoint at node).
// Colours follow MNVR thresholds (value only — label stays light grey):
//   tIgn > 60 s       → dark green on black
//   tIgn 10..60 s     → yellow on black
//   tIgn < 10 s / neg → white on red (alarm)
//   No maneuver node  → "---" in dark grey on black
//
// A rounded-seconds cache + colour-pair cache skip the printValue call when
// nothing visibly changed. printValue's own PrintState still handles the
// bg-change repaint when the alarm red turns on/off.
static void _lnchOrUpdateTignRow(KCM_TFT &tft) {
    bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f);

    int32_t  newSec;       // rounded seconds value, or sentinel
    uint16_t valFg, valBg;
    String   val;
    if (!hasMnvr) {
        newSec = -9998;  // "---" placeholder sentinel
        valFg  = TFT_DARK_GREY;
        valBg  = TFT_BLACK;
        val    = "---";
    } else {
        float tIgn = state.mnvrTime - state.mnvrDuration * 0.5f;
        newSec = (int32_t)tIgn;   // truncated, as formatTimeCompact prints it
        if      (tIgn < MNVR_TIGN_ALARM_S) { valFg = TFT_WHITE;      valBg = TFT_RED;   }
        else if (tIgn < MNVR_TIGN_WARN_S)  { valFg = TFT_YELLOW;     valBg = TFT_BLACK; }
        else                               { valFg = TFT_DARK_GREEN; valBg = TFT_BLACK; }
        val = formatTimeCompact((int64_t)tIgn);
    }

    if (newSec == _lnchOrPrevTignSec &&
        valFg  == _lnchOrPrevTignFg  &&
        valBg  == _lnchOrPrevTignBg) return;

    // Delegate to the library helper. printValue handles region clearing
    // (using valBg for the value area, without touching the label on the
    // left), right-aligns the value within the cell, and tracks shrink
    // via PrintState so old wider strings get cleaned up.
    printValue(tft, &Roboto_Black_28,
               LNCH_OR_BAR_X, LNCH_OR_TIGN_Y,
               LNCH_OR_BAR_W, LNCH_OR_TIGN_H,
               "T+IGN", val,
               valFg, valBg, TFT_BLACK,
               _lnchOrTignPs);

    _lnchOrPrevTignSec = newSec;
    _lnchOrPrevTignFg  = valFg;
    _lnchOrPrevTignBg  = valBg;
}

// ── Left-rail readouts: eccentricity and the apsis gap ────────────────────────────────
//
// These two slots used to carry Burn Dur and ΔV Circ. Those are burn numbers, and the
// three burn numbers now sit together in the right column; these two describe the shape
// of the orbit, so they belong beside the picture of it. Eccentricity is how circular
// the diagram above them already is, and the apsis gap is the distance between the two
// dots drawn on it — a number the diagram shows but cannot state.
//
// Both slots draw the same way: a fixed label rendered once (its text and colour never
// change), and a value centred under it in a cleared box.
static void _lnchOrRailReadout(KCM_TFT &tft, int16_t lblY, int16_t valY,
                               const char *label, const String &val,
                               uint16_t fg, bool firstDraw) {
    if (firstDraw) {
        tft.setFont(Roboto_Black_20);
        tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
        int16_t lblW = getFontStringWidth(&Roboto_Black_20, label);
        tft.setCursor(LNCH_OR_ATT_CX - lblW / 2, lblY);
        tft.print(label);
    }
    // 130 wide, centred on the rail: x 9..139, which stays clear of the orbit diagram's
    // leftmost extent at x=140. This is the width the ΔV Circ readout used; Burn Dur's
    // 140 reached 144 and only got away with it because nothing was there.
    const int16_t regionW = 130;
    tft.fillRect(LNCH_OR_ATT_CX - regionW / 2, valY, regionW, 36, TFT_BLACK);
    tft.setFont(Roboto_Black_28);
    tft.setTextColor(fg, TFT_BLACK);
    int16_t vw = getFontStringWidth(&Roboto_Black_28, val.c_str());
    tft.setCursor(LNCH_OR_ATT_CX - vw / 2, valY);
    tft.print(val.c_str());
}

// Compact altitude for a narrow box.
//
// formatAlt() only switches to km above 1,000,000 m, so everything from 100 km to
// 1000 km renders as six digits and a separator: "513,000 m" measures 135 px and this
// rail box is 130. That band is not exotic -- a Kerbin circularisation begins in it,
// with apoapsis at 101 km and periapsis still hundreds of kilometres underground.
//
// Promoting a band early enough that the scaled value never reaches five digits caps
// the widest output at "9,999 Mm" (128 px). The 9999.5 thresholds are what keeps the
// rounding at the top of a band from producing that fifth digit: 9,999,999 m becomes
// "10 Mm", not "10,000 km". Metre precision on an apsis gap was false anyway.
//
// formatSep() renders two decimals below 1000, which would give "513.00 km" (134 px --
// still too wide), so the scaled value is rounded and passed to formatSepI64 instead.
//
// Fits to 9,999 Gm; beyond that (1e13 m, some forty times Kerbol's outer SOI) it would
// overflow again. A candidate to promote beside formatTimeCompact() in the shared
// library if a second caller ever wants it.
static String _lnchOrAltCompact(float v) {
    const bool  neg = (v < 0.0f);
    const float a   = neg ? -v : v;
    const char *unit; float scaled;
    if      (a < 9999.5f)   { unit = " m";  scaled = a;          }
    else if (a < 9999.5e3f) { unit = " km"; scaled = a / 1.0e3f; }
    else if (a < 9999.5e6f) { unit = " Mm"; scaled = a / 1.0e6f; }
    else                    { unit = " Gm"; scaled = a / 1.0e9f; }
    return String(neg ? "-" : "") + formatSepI64((int64_t)lroundf(scaled)) + String(unit);
}

// Eccentricity — the goal metric. Zero is a circle, and green says the burn is done.
static void _lnchOrUpdateEccReadout(KCM_TFT &tft) {
    const bool haveOrbit = (state.apoapsis > 0.0f);
    const int32_t milli = haveOrbit ? (int32_t)lroundf(state.eccentricity * 1000.0f) : -9998;
    const bool first = (_lnchOrPrevEccMilli == -9999);
    if (milli == _lnchOrPrevEccMilli && !first) return;

    char buf[12];
    uint16_t fg;
    if (!haveOrbit) { strcpy(buf, "---"); fg = TFT_DARK_GREY; }
    else {
        snprintf(buf, sizeof(buf), "%.3f", state.eccentricity);
        fg = (state.eccentricity < 0.02f) ? TFT_DARK_GREEN : TFT_YELLOW;
    }
    _lnchOrRailReadout(tft, LNCH_OR_ECC_LBL_Y, LNCH_OR_ECC_VAL_Y, "ECC", String(buf), fg, first);
    _lnchOrPrevEccMilli = milli;
}

// Apsis gap — the distance the burn is closing, and the thing the two dots on the
// diagram above are separated by. Sentinels match the other readouts on this rail:
// -9999 = never drawn, -9998 = showing the "---" placeholder.
static void _lnchOrUpdateGapReadout(KCM_TFT &tft) {
    const bool haveOrbit = (state.apoapsis > 0.0f);
    const int32_t gap = haveOrbit ? (int32_t)lroundf(state.apoapsis - state.periapsis) : -9998;
    const bool first = (_lnchOrPrevGapM == -9999);
    if (gap == _lnchOrPrevGapM && !first) return;

    _lnchOrRailReadout(tft, LNCH_OR_GAP_LBL_Y, LNCH_OR_GAP_VAL_Y, "AP-PE",
                       haveOrbit ? _lnchOrAltCompact(state.apoapsis - state.periapsis)
                                 : String("---"),
                       haveOrbit ? TFT_DARK_GREEN : TFT_DARK_GREY, first);
    _lnchOrPrevGapM = gap;
}


// Wrap a heading error into ±180° (for bearing differences on a 0..360°
// compass). Duplicated from Screen_MNVR.ino (which declares it static).
static inline float _lnchOrWrapBrgErr(float e) { return eadiHdgDelta(e, 0.0f); }

// Draw the ATT indicator chrome: concentric rings at 5°, 10°, 15°, plus
// centre crosshairs. Drawn once on first-draw / SOI change; the dot is
// updated dynamically by _lnchOrUpdateAttIndicator. Also called to "repair"
// the chrome when a moving dot passes over it (same approach as LNDG).
static void _lnchOrDrawAttChrome(KCM_TFT &tft) {
    const int16_t CX = LNCH_OR_ATT_CX;
    const int16_t CY = LNCH_OR_ATT_CY;
    const int16_t R  = LNCH_OR_ATT_R;

    // Black disc (slightly larger than the outer ring — clears any old dot
    // pixels that may have been drawn outside the outer ring area).
    tft.fillCircle(CX, CY, R + 2, TFT_BLACK);

    // Good-zone inner fill (subtle off-black highlight inside the 5° ring).
    int16_t r5  = (int16_t)(5.0f  * LNCH_OR_ATT_SCALE);  // ≈ 17 px (5° at SCALE 3.47)
    int16_t r10 = (int16_t)(10.0f * LNCH_OR_ATT_SCALE);  // ≈ 35 px
    tft.fillCircle(CX, CY, r5, TFT_OFF_BLACK);

    // Reference rings: 5° green, 10° dark grey, 15° grey bezel.
    tft.drawCircle(CX, CY, r5, TFT_DARK_GREEN);
    tft.drawCircle(CX, CY, r10, TFT_DARK_GREY);
    tft.drawCircle(CX, CY, R,   TFT_GREY);

    // Centre crosshairs (cardinal axes with small centre gap so the dot at
    // centre isn't obscured by lines).
    const int16_t gap = 4;
    tft.drawLine(CX, CY - R + 1, CX, CY - gap, TFT_DARK_GREY);
    tft.drawLine(CX, CY + gap,   CX, CY + R - 1, TFT_DARK_GREY);
    tft.drawLine(CX - R + 1, CY, CX - gap, CY,   TFT_DARK_GREY);
    tft.drawLine(CX + gap,   CY, CX + R - 1, CY, TFT_DARK_GREY);

    // "ATT" label above the disc, centered horizontally on the disc.
    // Black_20 (24 px tall) — matches the "BURN DUR" label below for
    // cluster-internal label-hierarchy consistency. Offset of 28 px above
    // disc keeps a 4 px gap between label bottom and disc top.
    tft.setFont(Roboto_Black_20);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    int16_t lblW = getFontStringWidth(&Roboto_Black_20, "ATT");
    tft.setCursor(CX - lblW / 2, CY - R - 28);
    tft.print("ATT");
}

// Update the ATT indicator dot: shows attitude error vs the planned
// maneuver. Dot position follows MNVR's convention (dot = where to point;
// crosshair at centre = current attitude):
//   sx = CX + (-brgErr × SCALE)     — dot moves toward target heading
//   sy = CY + ( elvErr × SCALE)     — dot moves toward target pitch
// Dot clamped to outer ring (at 15° max). Colour by error magnitude.
//   errMag < 5°   → green
//   errMag < 15°  → yellow
//   errMag >= 15° → red
//   no maneuver   → inactive — dot erased (or drawn in dark grey at centre)
//
// Uses erase-prev-then-redraw with chrome touch-up (same pattern as LNDG).
static void _lnchOrUpdateAttIndicator(KCM_TFT &tft) {
    bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f);

    int16_t newX, newY;
    uint16_t newCol;
    if (!hasMnvr) {
        // Inactive — park the dot at centre in dark grey.
        newX = LNCH_OR_ATT_CX;
        newY = LNCH_OR_ATT_CY;
        newCol = TFT_DARK_GREY;
    } else {
        float brgErr = _lnchOrWrapBrgErr(state.heading - state.mnvrHeading);
        float elvErr = state.pitch - state.mnvrPitch;
        float errMag = sqrtf(brgErr * brgErr + elvErr * elvErr);

        // Raw dot position (MNVR convention: dot is where you need to point).
        float fx = (float)LNCH_OR_ATT_CX + (-brgErr * LNCH_OR_ATT_SCALE);
        float fy = (float)LNCH_OR_ATT_CY + ( elvErr * LNCH_OR_ATT_SCALE);
        // Clamp to outer ring.
        float dx = fx - (float)LNCH_OR_ATT_CX;
        float dy = fy - (float)LNCH_OR_ATT_CY;
        float dist = sqrtf(dx * dx + dy * dy);
        if (dist > (float)LNCH_OR_ATT_R) {
            fx = (float)LNCH_OR_ATT_CX + dx * (float)LNCH_OR_ATT_R / dist;
            fy = (float)LNCH_OR_ATT_CY + dy * (float)LNCH_OR_ATT_R / dist;
        }
        newX = (int16_t)roundf(fx);
        newY = (int16_t)roundf(fy);

        if      (errMag < LNCH_OR_ALIGN_GREEN_DEG)  newCol = TFT_DARK_GREEN;
        else if (errMag < LNCH_OR_ALIGN_YELLOW_DEG) newCol = TFT_YELLOW;
        else                                        newCol = TFT_RED;
    }

    // Skip if nothing moved and colour is unchanged.
    if (newX == _lnchOrPrevAttDotX &&
        newY == _lnchOrPrevAttDotY &&
        newCol == _lnchOrPrevAttDotCol) return;

    // On first draw, paint the chrome (rings, crosshairs, label). On later
    // frames, erase the old dot by black-filling a slightly-larger circle
    // then repair the chrome over the erased pixels. Same approach as LNDG.
    if (_lnchOrPrevAttDotX == 9999) {
        _lnchOrDrawAttChrome(tft);
    } else {
        tft.fillCircle(_lnchOrPrevAttDotX, _lnchOrPrevAttDotY, 8, TFT_BLACK);
        _lnchOrDrawAttChrome(tft);
    }

    // Draw new dot: 6-px filled circle in the error-magnitude colour, with a
    // small bright centre pip for visibility.
    tft.fillCircle(newX, newY, 6, newCol);
    tft.fillCircle(newX, newY, 2, TFT_WHITE);

    _lnchOrPrevAttDotX   = newX;
    _lnchOrPrevAttDotY   = newY;
    _lnchOrPrevAttDotCol = newCol;
}

// Draw the full orbital graphic using erase-then-redraw on the dynamic layer
// (orbit curve, Pe/Ap markers, vessel) while leaving the static layer (body,
// atmosphere, target circle) untouched unless the SOI has changed. This
// eliminates the visible flicker that a full-rectangle black wipe every frame
// would cause.
//
// Order of operations:
//   1. Compute all new geometry.
//   2. If SOI changed (or first draw), clear the diagram area and draw the
//      static layer.
//   3. Erase previous dynamic elements (orbit curve segments, markers, vessel)
//      by redrawing them in black at their saved pixel positions.
//   4. Touch up the static layer over regions the erase may have blackened.
//   5. Draw new dynamic elements, saving pixel positions for next frame's erase.
static void _lnchOrDrawOrbitGraphic(KCM_TFT &tft) {
    const int16_t CX = LNCH_OR_DIAG_CX;
    const int16_t CY = LNCH_OR_DIAG_CY;
    const int16_t MAX_R = LNCH_OR_DIAG_MAX_R;

    // ── Body parameters ─────────────────────────────────────────────────────────
    float bodyR    = (currentBody.radius   > 0.0f) ? currentBody.radius   : DEFAULT_BODY_RADIUS_M;
    float atmoTop  = (currentBody.lowSpace > 0.0f) ? currentBody.lowSpace : 0.0f;
    float targetAlt = max(currentBody.minSafe, currentBody.lowSpace + 20000.0f);
    float rTarget  = targetAlt + bodyR;

    // ── Current orbit parameters ────────────────────────────────────────────────
    float apaAlt = fmaxf(0.0f, state.apoapsis);
    float peaAlt = fmaxf(0.0f, state.periapsis);
    float rAp    = apaAlt + bodyR;
    float rPe    = fmaxf(peaAlt + bodyR, bodyR);
    float sma    = (rAp + rPe) * 0.5f;
    float ecc    = (rAp > rPe + 1.0f) ? ((rAp - rPe) / (rAp + rPe)) : 0.0f;

    float argOfPe_rad = state.argOfPe * (float)(PI / 180.0f);
    float cos_w = cosf(argOfPe_rad);
    float sin_w = sinf(argOfPe_rad);
    float nu_rad = state.trueAnomaly * (float)(PI / 180.0f);

    // ── Compressed radial scaling (see header comment) ──────────────────────────
    const float BODY_CAP_FRAC = 0.55f;
    float rMax       = fmaxf(fmaxf(rAp, rTarget), bodyR + 1000.0f);
    float body_cap   = (float)MAX_R * BODY_CAP_FRAC;
    float alt_extent = rMax - bodyR;
    float alt_scale  = ((float)MAX_R - body_cap) / alt_extent;

    auto r_to_px = [&](float r) -> float {
        if (r <= bodyR) return (r / bodyR) * body_cap;
        return body_cap + (r - bodyR) * alt_scale;
    };

    int16_t body_px   = (int16_t)fmaxf(3.0f, body_cap);
    int16_t atmo_px   = (atmoTop > 0.0f) ? (int16_t)r_to_px(bodyR + atmoTop) : 0;
    int16_t target_px = (int16_t)r_to_px(rTarget);
    uint16_t bodyCol  = kspBodyColor(currentBody.soiName);
    uint16_t atmoCol  = kspAtmoColor(currentBody.soiName);

    // ── Static layer: draw once (or redraw if SOI changed) ──────────────────────
    bool soi_changed = _lnchOrSoiChanged();
    bool first_draw  = !_lnchOrPrevCurveValid;
    if (soi_changed || first_draw) {
        // Full clear of diagram area + progress-bar area, then draw static
        // elements. This is the ONE PLACE we use fillRect — and only on rare
        // events (entry to orbital mode, SOI change).
        const int16_t clearMargin = 20;
        tft.fillRect(CX - MAX_R - clearMargin, CY - MAX_R - clearMargin,
                     2 * (MAX_R + clearMargin), 2 * (MAX_R + clearMargin),
                     TFT_BLACK);
        // Clear the bar + label + T+Ign area. Width stops at RPANEL_X - 2
        // so it doesn't touch the vertical divider at x=RPANEL_X-2..-1
        // (451..452). Vertical span covers the bar label row, the bar itself,
        // and the T+Ign row below the bar.
        tft.fillRect(0, LNCH_OR_BAR_LBL_Y - 2, LNCH_AS2_RPANEL_X - 2,
                     (LNCH_OR_TIGN_Y + LNCH_OR_TIGN_H + 1) - (LNCH_OR_BAR_LBL_Y - 2),
                     TFT_BLACK);
        _lnchOrDrawStaticLayer(tft, CX, CY, body_px, atmo_px, target_px,
                               bodyCol, atmoCol);
        _lnchOrDrawProgressBarChrome(tft);
        // Record SOI we drew static layer for
        const char *soi = currentBody.soiName ? currentBody.soiName : "";
        strncpy(_lnchOrPrevSoi, soi, sizeof(_lnchOrPrevSoi) - 1);
        _lnchOrPrevSoi[sizeof(_lnchOrPrevSoi) - 1] = '\0';
        // Invalidate prev-frame dynamic state — nothing to erase (we just
        // blanked the area).
        _lnchOrPrevCurveValid = false;
        _lnchOrPrevPeValid    = false;
        _lnchOrPrevApValid    = false;
        _lnchOrPrevVslValid   = false;
        _lnchOrPrevDirValid   = false;
        _lnchOrPrevBarFill    = -1;
        _lnchOrPrevBarCol     = 0;
        _lnchOrPrevBarDvRounded = -9999;
        _lnchOrPrevBarTextCol = 0;
        _lnchOrPrevBarEstimate = false;
        _lnchOrPrevTignSec    = -9999;
        _lnchOrPrevTignFg     = 0;
        _lnchOrPrevTignBg     = 0;
        _lnchOrTignPs.prevWidth  = 0;
        _lnchOrTignPs.prevBg     = 0x0001;
        _lnchOrTignPs.prevHeight = 0;
        _lnchOrPrevAttDotX    = 9999;
        _lnchOrPrevAttDotY    = 9999;
        _lnchOrPrevAttDotCol  = 0;
        // This wipe clears the left rail, so the readouts drawn there lose their
        // labels and must redraw from scratch. The burn numbers are not among them
        // any more -- they live in the right column, which this does not touch.
        _lnchOrPrevEccMilli = -9999;
        _lnchOrPrevGapM     = -9999;
        // Record the static-layer geometry we just drew so that on future
        // frames we can detect radius drift (due to compressed-scaling
        // recomputation as orbit elements change) and cleanly erase before
        // redrawing.
        _lnchOrPrevAtmoPx   = atmo_px;
        _lnchOrPrevTargetPx = target_px;
        _lnchOrPrevBodyPx   = body_px;
    }

    // ── Compute new dynamic element positions ───────────────────────────────────
    // Orbit curve points (N+1 points, N segments between them)
    int16_t newCurveX[LNCH_OR_CURVE_N + 1];
    int16_t newCurveY[LNCH_OR_CURVE_N + 1];
    for (uint8_t i = 0; i <= LNCH_OR_CURVE_N; i++) {
        float nu = 2.0f * (float)PI * (float)i / (float)LNCH_OR_CURVE_N;
        float denom = 1.0f + ecc * cosf(nu);
        float r_m = (fabsf(denom) > 1e-5f) ? sma * (1.0f - ecc * ecc) / denom : sma;
        float r_px = r_to_px(r_m);
        float angle = argOfPe_rad + nu;
        newCurveX[i] = CX + (int16_t)roundf(r_px * cosf(angle));
        newCurveY[i] = CY - (int16_t)roundf(r_px * sinf(angle));
    }

    // Pe/Ap marker positions. The DOT sits ON the orbit curve at the
    // compressed pixel radius. The text LABEL is offset outward along the
    // major axis by LNCH_OR_LABEL_OFFSET_PX pixels so it sits beyond the
    // curve rather than overlapping the dot or the curve itself. This
    // matches the ORB screen's label-placement convention.
    const float LABEL_OFFSET_PX = 20.0f;   // outboard label gap (clears the larger Pe/Ap dots with margin)
    float rPe_px = r_to_px(rPe);                       // dot radius (on curve)
    float rAp_px = r_to_px(rAp);                       // dot radius (on curve)
    float rPe_lbl_px = rPe_px + LABEL_OFFSET_PX;       // label radius (outboard)
    float rAp_lbl_px = rAp_px + LABEL_OFFSET_PX;
    int16_t pe_x = CX + (int16_t)roundf(rPe_px * cos_w);
    int16_t pe_y = CY - (int16_t)roundf(rPe_px * sin_w);
    int16_t ap_x = CX - (int16_t)roundf(rAp_px * cos_w);
    int16_t ap_y = CY + (int16_t)roundf(rAp_px * sin_w);
    // Label anchor points (center of the 2-char label). We offset the cursor
    // from this by half the text width/height below for centering.
    int16_t pe_lbl_cx = CX + (int16_t)roundf(rPe_lbl_px * cos_w);
    int16_t pe_lbl_cy = CY - (int16_t)roundf(rPe_lbl_px * sin_w);
    int16_t ap_lbl_cx = CX - (int16_t)roundf(rAp_lbl_px * cos_w);
    int16_t ap_lbl_cy = CY + (int16_t)roundf(rAp_lbl_px * sin_w);

    // Vessel position (dot on the orbit curve).
    bool vessel_valid = false;
    int16_t vsl_x = 0, vsl_y = 0;
    if (apaAlt > 0.0f || peaAlt > 0.0f) {
        float denom = 1.0f + ecc * cosf(nu_rad);
        if (fabsf(denom) > 1e-5f) {
            float rVsl_m  = sma * (1.0f - ecc * ecc) / denom;
            float rVsl_px = r_to_px(rVsl_m);
            float angle   = argOfPe_rad + nu_rad;
            vsl_x = CX + (int16_t)roundf(rVsl_px * cosf(angle));
            vsl_y = CY - (int16_t)roundf(rVsl_px * sinf(angle));
            vessel_valid = true;
        }
    }

    // Direction indicator: small chevron embedded on the orbit curve at ν=90°
    // (a quarter orbit past Pe, on the way toward Ap). Points along the
    // tangent of the curve in the direction of travel:
    //   Prograde  (inclination < 90°): chevron at ν=90° pointing toward ν>90°
    //   Retrograde (inclination > 90°): chevron at ν=270° pointing toward ν<270°
    // Using different reference ν for the two cases so the chevron always sits
    // on the "far side" of the orbit from the vessel's approach direction,
    // making the visual meaning unambiguous.
    bool retrograde = (state.inclination > 90.0f);
    float dir_nu = retrograde ? (3.0f * (float)PI / 2.0f) : ((float)PI / 2.0f);
    // Position on compressed orbit curve at dir_nu.
    float dir_denom = 1.0f + ecc * cosf(dir_nu);
    float dir_r_m = (fabsf(dir_denom) > 1e-5f) ? sma * (1.0f - ecc * ecc) / dir_denom : sma;
    float dir_r_px = r_to_px(dir_r_m);
    float dir_angle = argOfPe_rad + dir_nu;
    int16_t dir_x = CX + (int16_t)roundf(dir_r_px * cosf(dir_angle));
    int16_t dir_y = CY - (int16_t)roundf(dir_r_px * sinf(dir_angle));
    // Tangent direction at dir_nu: small forward step, take vector.
    float dir_step = retrograde ? -0.03f : 0.03f;
    float nu2 = dir_nu + dir_step;
    float den2 = 1.0f + ecc * cosf(nu2);
    float r2_m = (fabsf(den2) > 1e-5f) ? sma * (1.0f - ecc * ecc) / den2 : sma;
    float r2_px = r_to_px(r2_m);
    float ang2  = argOfPe_rad + nu2;
    float dir_dx = ((float)CX + r2_px * cosf(ang2)) - (float)dir_x;
    float dir_dy = ((float)CY - r2_px * sinf(ang2)) - (float)dir_y;
    float dir_mag = sqrtf(dir_dx * dir_dx + dir_dy * dir_dy);
    if (dir_mag > 0.01f) {
        dir_dx /= dir_mag;
        dir_dy /= dir_mag;
    } else {
        dir_dx = 1.0f; dir_dy = 0.0f;
    }

    // Determine orbit colour: green if Pe safely above atmo, yellow if Pe in
    // atmosphere (orbit will decay), red if Pe at/below surface (impact).
    uint16_t orbitCol;
    if (peaAlt <= 0.0f)           orbitCol = TFT_RED;
    else if (peaAlt < atmoTop)    orbitCol = TFT_YELLOW;
    else                          orbitCol = TFT_DARK_GREEN;

    // ── Change detection: only erase+redraw elements that actually moved ────────
    // Comparing new positions to saved prev positions. Orbit curve comparison
    // uses max pixel deviation; if all points are within 0-1 px of prev, the
    // curve is visually unchanged and doesn't need to be erased/redrawn.
    bool orbit_changed = !_lnchOrPrevCurveValid;
    if (!orbit_changed) {
        // Check if any segment endpoint moved by more than 0 pixels (strict).
        // Even 1px would be visible as flicker, so only skip if exactly equal.
        for (uint8_t i = 0; i <= LNCH_OR_CURVE_N; i++) {
            if (newCurveX[i] != _lnchOrPrevCurveX[i] ||
                newCurveY[i] != _lnchOrPrevCurveY[i]) {
                orbit_changed = true;
                break;
            }
        }
    }
    // Also redraw the orbit if its colour changed (peaAlt crossed atmo threshold).
    if (orbitCol != _lnchOrPrevOrbitCol) {
        orbit_changed = true;
        _lnchOrPrevOrbitCol = orbitCol;
    }

    bool pe_changed = !_lnchOrPrevPeValid ||
                      pe_x != _lnchOrPrevPeX || pe_y != _lnchOrPrevPeY;
    bool ap_changed = !_lnchOrPrevApValid ||
                      ap_x != _lnchOrPrevApX || ap_y != _lnchOrPrevApY;
    bool vsl_changed = !_lnchOrPrevVslValid ||
                       (vessel_valid && (vsl_x != _lnchOrPrevVslX ||
                                         vsl_y != _lnchOrPrevVslY)) ||
                       (!vessel_valid && _lnchOrPrevVslValid);
    // Direction indicator position depends on argOfPe + eccentricity. Its
    // orientation depends on those + inclination sign. Any orbit-shape change
    // moves the indicator, so it shares the orbit_changed lifecycle.
    bool dir_changed = orbit_changed;

    // ── Erase previous dynamic elements (only if they changed) ──────────────────
    // Draw previous shapes in black to erase. Drawing a line in black over
    // exactly the same path is a clean erase (line algorithm is deterministic).
    if (orbit_changed && _lnchOrPrevCurveValid) {
        for (uint8_t i = 0; i < LNCH_OR_CURVE_N; i++) {
            tft.drawLine(_lnchOrPrevCurveX[i],     _lnchOrPrevCurveY[i],
                         _lnchOrPrevCurveX[i + 1], _lnchOrPrevCurveY[i + 1],
                         TFT_BLACK);
        }
    }
    if (pe_changed && _lnchOrPrevPeValid) {
        // Erase prev dot (r=5 → 6 for safety)
        tft.fillCircle(_lnchOrPrevPeX, _lnchOrPrevPeY, 6, TFT_BLACK);
        // Erase prev label — centered at _lnchOrPrevPeLbl{X,Y}, ~12×11 from center
        // (Black_16 is 19 px tall, "Pe" ~19 px wide).
        tft.fillRect(_lnchOrPrevPeLblX - 12, _lnchOrPrevPeLblY - 11,
                     24, 22, TFT_BLACK);
    }
    if (ap_changed && _lnchOrPrevApValid) {
        tft.fillCircle(_lnchOrPrevApX, _lnchOrPrevApY, 6, TFT_BLACK);
        tft.fillRect(_lnchOrPrevApLblX - 12, _lnchOrPrevApLblY - 11,
                     24, 22, TFT_BLACK);
    }
    if (vsl_changed && _lnchOrPrevVslValid) {
        // Erase prev vessel dot (r=6 filled + outline → extent 8 for safety).
        tft.fillCircle(_lnchOrPrevVslX, _lnchOrPrevVslY, 8, TFT_BLACK);
    }
    if (dir_changed && _lnchOrPrevDirValid) {
        // Erase prev direction chevron. Triangle tip 10 px forward, base ±7 px
        // perpendicular 7 back → max extent from center ≈ 10 px. Use 13 px
        // radius for safety incl. 1-px outline.
        tft.fillCircle(_lnchOrPrevDirX, _lnchOrPrevDirY, 13, TFT_BLACK);
    }

    // ── Touch-up static layer (only if erase happened) ─────────────────────────
    // If nothing was erased, the static layer is untouched and we don't need
    // to redraw it. This is the main flicker-avoidance optimisation.
    //
    // Special case: if the static-layer GEOMETRY (atmo_px, target_px, body_px)
    // drifted from the previously-drawn values — this happens because
    // compressed scaling depends on rMax which depends on the current orbit's
    // apoapsis — we must erase the OLD rings first, otherwise overdrawing at
    // the new radius leaves the old rings visible and the lines appear to
    // thicken over time.
    bool static_geom_changed = (atmo_px   != _lnchOrPrevAtmoPx)   ||
                               (target_px != _lnchOrPrevTargetPx) ||
                               (body_px   != _lnchOrPrevBodyPx);
    bool any_erase = (orbit_changed && _lnchOrPrevCurveValid) ||
                     (pe_changed    && _lnchOrPrevPeValid)    ||
                     (ap_changed    && _lnchOrPrevApValid)    ||
                     (vsl_changed   && _lnchOrPrevVslValid)   ||
                     (dir_changed   && _lnchOrPrevDirValid);
    if ((any_erase || static_geom_changed) && !first_draw && !soi_changed) {
        // If the static-layer geometry drifted, erase old rings at their
        // previous radii before redrawing at new radii.
        if (static_geom_changed) {
            if (_lnchOrPrevAtmoPx > 0 && atmoCol != 0) {
                tft.drawCircle(CX, CY, _lnchOrPrevAtmoPx, TFT_BLACK);
            }
            if (_lnchOrPrevTargetPx > 0) {
                // Erase dashed target circle by redrawing its 20 drawn
                // segments in black using the same loop logic.
                const int N = 40;
                const int skip = 2;
                float dtheta = 2.0f * (float)PI / N;
                int16_t px = CX + _lnchOrPrevTargetPx;
                int16_t py = CY;
                for (int i = 1; i <= N; i++) {
                    float theta = i * dtheta;
                    int16_t nx = CX + (int16_t)roundf((float)_lnchOrPrevTargetPx * cosf(theta));
                    int16_t ny = CY - (int16_t)roundf((float)_lnchOrPrevTargetPx * sinf(theta));
                    if ((i % skip) == 0) {
                        tft.drawLine(px, py, nx, ny, TFT_BLACK);
                    }
                    px = nx; py = ny;
                }
            }
            // Body rarely changes radius (body_cap is MAX_R * 0.55 constant),
            // but handle for completeness.
            if (_lnchOrPrevBodyPx > 0 && _lnchOrPrevBodyPx != body_px) {
                tft.fillCircle(CX, CY, _lnchOrPrevBodyPx, TFT_BLACK);
            }
        }
        _lnchOrDrawStaticLayer(tft, CX, CY, body_px, atmo_px, target_px,
                               bodyCol, atmoCol);
        _lnchOrPrevAtmoPx   = atmo_px;
        _lnchOrPrevTargetPx = target_px;
        _lnchOrPrevBodyPx   = body_px;
    }

    // ── Draw new dynamic elements (only if they changed) ────────────────────────
    if (orbit_changed) {
        for (uint8_t i = 0; i < LNCH_OR_CURVE_N; i++) {
            tft.drawLine(newCurveX[i],     newCurveY[i],
                         newCurveX[i + 1], newCurveY[i + 1],
                         orbitCol);
        }
        memcpy(_lnchOrPrevCurveX, newCurveX, sizeof(newCurveX));
        memcpy(_lnchOrPrevCurveY, newCurveY, sizeof(newCurveY));
        _lnchOrPrevCurveValid = true;
    }

    // Direction indicator — drawn after the curve so the chevron sits ON TOP.
    // Colour matches the orbit curve so it reads as a natural extension of it.
    if (dir_changed) {
        _lnchOrDrawChevron(tft, dir_x, dir_y, dir_dx, dir_dy, orbitCol);
        _lnchOrPrevDirX = dir_x;
        _lnchOrPrevDirY = dir_y;
        _lnchOrPrevDirValid = true;
    }

    // The Pe/Ap/vessel dots sit ON the orbit curve (and Pe can sit on the body
    // edge). Whenever the curve or the static layer was repainted this frame,
    // repaint the dots on TOP even if they didn't move — otherwise the freshly
    // drawn curve/body clips the dot that was left in place.
    bool markers_dirty = any_erase || static_geom_changed;

    if (pe_changed || markers_dirty) {
        // Dot ON the orbit curve (drawn last so it sits on top of the line/body)
        tft.fillCircle(pe_x, pe_y, 5, TFT_MAGENTA);
        // Label centered at outboard anchor. setCursor sets top-left of text;
        // "Pe" at Black_16 is ~19 px wide × 19 px tall → offset (-10, -10).
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
        tft.setCursor(pe_lbl_cx - 10, pe_lbl_cy - 10);
        tft.print("Pe");
        _lnchOrPrevPeX = pe_x; _lnchOrPrevPeY = pe_y;
        _lnchOrPrevPeLblX = pe_lbl_cx; _lnchOrPrevPeLblY = pe_lbl_cy;
        _lnchOrPrevPeValid = true;
    }
    if (ap_changed || markers_dirty) {
        tft.fillCircle(ap_x, ap_y, 5, TFT_CYAN);
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_CYAN, TFT_BLACK);
        tft.setCursor(ap_lbl_cx - 10, ap_lbl_cy - 10);
        tft.print("Ap");
        _lnchOrPrevApX = ap_x; _lnchOrPrevApY = ap_y;
        _lnchOrPrevApLblX = ap_lbl_cx; _lnchOrPrevApLblY = ap_lbl_cy;
        _lnchOrPrevApValid = true;
    }
    // Vessel: filled neon-green dot with black outline for contrast. Drawn last
    // so it sits on top of the curve and the Pe/Ap dots.
    if (vsl_changed || markers_dirty) {
        if (vessel_valid) {
            tft.fillCircle(vsl_x, vsl_y, 6, TFT_NEON_GREEN);
            tft.drawCircle(vsl_x, vsl_y, 6, TFT_BLACK);
            _lnchOrPrevVslX = vsl_x;
            _lnchOrPrevVslY = vsl_y;
            _lnchOrPrevVslValid = true;
        } else {
            _lnchOrPrevVslValid = false;
        }
    }
}

// Dispatcher: call this each frame during orbital phase. Runs every frame now —
// the former ~5 Hz cap existed to hide single-buffer redraw flicker, which the
// double buffer (draw to the hidden page, then flip) now handles. Each element
// is change-detected, so idle frames stay cheap.
static void _lnchOrDrawLeftPanelValues(KCM_TFT &tft) {
    _lnchOrDrawOrbitGraphic(tft);
    _lnchOrUpdateProgressBar(tft);
    _lnchOrUpdateTignRow(tft);
    _lnchOrUpdateAttIndicator(tft);
    _lnchOrUpdateEccReadout(tft);
    _lnchOrUpdateGapReadout(tft);
}

/***************************************************************************************
   Screen_LNCH_PreLaunch.ino -- Pre-launch board (one of three modes of the LNCH screen)

   Status board shown automatically when state.situation has sit_PreLaunch set.
   Eight rows of pre-flight readiness checks: vessel name + type, SAS/RCS,
   throttle/EC%, crew/CommNet, total ΔV, drogue+main deploy/cut arming.

   Phase membership (LNCH screen has three phases):
     - PRE-LAUNCH (this file)        — auto, when sit_PreLaunch is set
     - ASCENT     (Screen_LNCH_Ascent.ino)  — when not pre-launch and below ~6% bodyR
     - CIRC       (Screen_LNCH_Circ.ino)    — when above ~6% bodyR (with hysteresis)

   Top-level dispatcher Screen_LNCH.ino selects which of these to draw.

   Public-to-the-sketch entry points (called by the LNCH dispatcher):
     - _lnchPrelaunchDrawChrome(tft)  — labels, dividers, title bar
     - _lnchPrelaunchDrawValues(tft)  — per-frame value updates, change-detected
****************************************************************************************/

// ── Pre-launch layout constants ───────────────────────────────────────────────────────
// All Black_40 cells, 8 equal-height rows. Several rows split into left/right halves
// with a 2-px central vertical divider (drawn in chrome).
static const tFont   *_lnchPlFont   = &Roboto_Black_40;
static const uint8_t  _lnchPlNumRows = 8;
static const uint16_t _lnchPlSectW  = 26;                                    // section indent (matches other screens)
static const uint16_t _lnchPlAX     = ROW_PAD + _lnchPlSectW;                 // first cell X
static const uint16_t _lnchPlAW     = CONTENT_W - _lnchPlAX - ROW_PAD;        // full row width
static const uint16_t _lnchPlAHW    = _lnchPlAW / 2;                           // half-width for split rows


// ── Chrome ─────────────────────────────────────────────────────────────────────────────
// Draws labels, dividers, and title bar. Called once per screen-entry. Values are
// updated separately by _lnchPrelaunchDrawValues each frame.
static void _lnchPrelaunchDrawChrome(KCM_TFT &tft) {
    const uint8_t  NR   = _lnchPlNumRows;
    const tFont   *F    = _lnchPlFont;
    const uint16_t AX   = _lnchPlAX;
    const uint16_t AW   = _lnchPlAW;
    const uint16_t AHW  = _lnchPlAHW;
    uint16_t rowH       = rowHFor(NR);

    // No section labels — pure status board. 8 rows, all split except rows 0, 1, 5.
    drawTitleBar(tft, "PRE-LAUNCH");  // no toggle indicator

    printDispChrome(tft, F, AX, rowYFor(0,NR), AW, rowH, "VESSEL",  COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, F, AX, rowYFor(1,NR), AW, rowH, "TYPE",    COL_LABEL, COL_BACK, COL_NO_BDR);

    // Split rows 2-7: vertical dividers and left/right labels
    auto plSplit = [&](uint8_t row, const char *lLabel, const char *rLabel) {
        uint16_t y = rowYFor(row, NR), h = rowH;
        printDispChrome(tft, F, AX,                 y, AHW - ROW_PAD, h, lLabel, COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, F, AX + AHW + ROW_PAD, y, AHW - ROW_PAD, h, rLabel, COL_LABEL, COL_BACK, COL_NO_BDR);
        uint16_t nextY = (row < NR - 1) ? rowYFor(row + 1, NR) : SCREEN_H;
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(AX + AHW + dx, y, AX + AHW + dx, nextY - 1, TFT_GREY);
    };
    plSplit(2, "SAS",      "RCS");
    plSplit(3, "THRTL", "EC%");
    plSplit(4, "CREW",     "COMM");
    printDispChrome(tft, F, AX, rowYFor(5,NR), AW, rowH, "\xCE\x94V.TOT", COL_LABEL, COL_BACK, COL_NO_BDR);
    plSplit(6, "DROGUE",   "MAIN");
    plSplit(7, "D.CUT",    "M.CUT");

    // Horizontal dividers between every row — makes board easier to read as a checklist
    for (uint8_t row = 1; row < NR; row++) {
        uint16_t dy = TITLE_TOP + rowHFor(NR) * row;
        tft.drawLine(0, dy,   CONTENT_W, dy,   TFT_GREY);
        tft.drawLine(0, dy+1, CONTENT_W, dy+1, TFT_GREY);
    }
}


// ── Per-frame value updates ────────────────────────────────────────────────────────────
// Updates the eight rows of values with change detection. Horizontal dividers are
// repainted every frame because printValue's fillRect sometimes nibbles them (same
// pattern as ATT and ROVR screens).
static void _lnchPrelaunchDrawValues(KCM_TFT &tft) {
    const uint8_t  NR   = _lnchPlNumRows;
    const tFont   *F    = _lnchPlFont;
    const uint16_t AX   = _lnchPlAX;
    const uint16_t AW   = _lnchPlAW;
    const uint16_t AHW  = _lnchPlAHW;
    uint16_t fg, bg;

    // plVal -> drawValue() full-row variant (slot=cache idx, row=display row) (#6C/#44)
    auto plVal = [&](uint8_t row, uint8_t slot, const char *label, const char *val,
                     uint16_t fgc, uint16_t bgc) {
        RowCache &rc = rowCache[screen_LNCH][slot];
        if (rc.fg == fgc && rc.bg == bgc && rc.value == val) return;   // no allocation
        String v(val);
        printValue(tft, F, AX, rowYFor(row, NR), AW, rowHFor(NR),
                   label, v, fgc, bgc, COL_BACK, printState[screen_LNCH][slot]);
        rc.value = v; rc.fg = fgc; rc.bg = bgc;
    };

    // plValL -> left-half split, slot=cache idx (#6C/#44)
    auto plValL = [&](uint8_t row, uint8_t slot, const char *label, const char *val,
                      uint16_t fgc, uint16_t bgc) {
        uint16_t xL = AX, wL = AHW - ROW_PAD;
        RowCache &rc = rowCache[screen_LNCH][slot];
        if (rc.fg == fgc && rc.bg == bgc && rc.value == val) return;   // no allocation
        String v(val);
        printValue(tft, F, xL, rowYFor(row, NR), wL, rowHFor(NR),
                   label, v, fgc, bgc, COL_BACK, printState[screen_LNCH][slot]);
        rc.value = v; rc.fg = fgc; rc.bg = bgc;
    };

    // plValR -> right-half split, slot=cache idx (#6C/#44)
    auto plValR = [&](uint8_t row, uint8_t slot, const char *label, const char *val,
                      uint16_t fgc, uint16_t bgc) {
        uint16_t xR = AX + AHW + ROW_PAD, wR = AHW - ROW_PAD;
        RowCache &rc = rowCache[screen_LNCH][slot];
        if (rc.fg == fgc && rc.bg == bgc && rc.value == val) return;   // no allocation
        String v(val);
        printValue(tft, F, xR, rowYFor(row, NR), wR, rowHFor(NR),
                   label, v, fgc, bgc, COL_BACK, printState[screen_LNCH][slot]);
        rc.value = v; rc.fg = fgc; rc.bg = bgc;
    };

    // Row 0 — Vessel name (full width, always dark green)
    plVal(0, 14, "VESSEL", state.vesselName.c_str(), TFT_DARK_GREEN, TFT_BLACK);

    // Row 1 — Vessel type (full width, always dark green — informational confirmation)
    {
        const char *typeName;
        switch (state.vesselType) {
            case type_Ship:     typeName = "Ship";      break;
            case type_Probe:    typeName = "Probe";     break;
            case type_Relay:    typeName = "Relay";     break;
            case type_Rover:    typeName = "Rover";     break;
            case type_Lander:   typeName = "Lander";    break;
            case type_Plane:    typeName = "Plane";     break;
            case type_Station:  typeName = "Station";   break;
            case type_Base:     typeName = "Base";      break;
            case type_EVA:      typeName = "EVA";       break;
            default:            typeName = "Unknown";   break;
        }
        plVal(1, 15, "TYPE", typeName, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 2 — SAS (left) | RCS (right)
    {
        // SAS: green=STAB, yellow=other mode on, red=OFF
        const char *sasStr;
        if (state.sasMode == 255)     { sasStr = "OFF";  fg = TFT_WHITE;     bg = TFT_RED;   }
        else if (state.sasMode == 0)  { sasStr = "STAB"; fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        else {
            // Any other SAS mode — show mode name, yellow
            switch (state.sasMode) {
                case 1: sasStr = "PROGRADE"; break; case 2: sasStr = "RETRO";    break;
                case 3: sasStr = "NORMAL";   break; case 4: sasStr = "ANTI-NRM"; break;
                case 5: sasStr = "RAD-OUT";  break; case 6: sasStr = "RAD-IN";   break;
                case 7: sasStr = "TARGET";   break; case 8: sasStr = "ANTI-TGT"; break;
                case 9: sasStr = "MANEUVER"; break; default: sasStr = "OTHER";   break;
            }
            fg = TFT_YELLOW; bg = TFT_BLACK;
        }
        plValL(2, 2, "SAS", sasStr, fg, bg);

        // RCS: green=OFF, red=ON (no RCS during launch)
        const char *rcsStr = state.rcs_on ? "ON" : "OFF";
        uint16_t rcsFg     = state.rcs_on ? TFT_WHITE     : TFT_DARK_GREEN;
        uint16_t rcsBg     = state.rcs_on ? TFT_RED        : TFT_BLACK;
        plValR(2, 3, "RCS", rcsStr, rcsFg, rcsBg);
    }

    // Row 3 — Throttle (left) | EC% (right)
    {
        // Throttle: green=0%, red=any non-zero
        uint8_t thrPct = (uint8_t)constrain(state.throttle * 100.0f, 0.0f, 100.0f);
        char thrStr[8]; snprintf(thrStr, sizeof(thrStr), "%u%%", thrPct);
        if (thrPct == 0) { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        else             { fg = TFT_WHITE;       bg = TFT_RED;   }
        plValL(3, 4, "THRTL", thrStr, fg, bg);

        // EC%: pre-launch readiness — green when topped off, red when not ready.
        uint8_t ecPct = (uint8_t)constrain(state.electricChargePercent, 0.0f, 100.0f);
        char ecStr[8]; snprintf(ecStr, sizeof(ecStr), "%u%%", ecPct);
        if      (ecPct >= EC_PRELAUNCH_READY_PCT) { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        else if (ecPct >= EC_PRELAUNCH_LOW_PCT)   { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                                       { fg = TFT_WHITE;       bg = TFT_RED;   }
        plValR(3, 5, "EC%", ecStr, fg, bg);
    }

    // Row 4 — Crew (left) | CommNet (right)
    {
        // Crew: always dark green — pilot reads and confirms count
        char crewBuf[10];
        snprintf(crewBuf, sizeof(crewBuf), "%d / %d", state.crewCount, state.crewCapacity);
        plValL(4, 6, "CREW", crewBuf, TFT_DARK_GREEN, TFT_BLACK);

        // CommNet: green=>50%, yellow=10-50%, red=<10%
        uint8_t sig = (uint8_t)constrain(state.commNetSignal, 0, 100);
        char sigStr[8]; snprintf(sigStr, sizeof(sigStr), "%u%%", sig);
        if      (sig >= VEH_SIGNAL_WARN_PCT) { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        else if (sig >= 10) { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                { fg = TFT_WHITE;       bg = TFT_RED;   }
        plValR(4, 7, "COMMNET", sigStr, fg, bg);
    }

    // Row 5 — ΔV.Tot (full width) — total mission delta-V at a glance
    {
        thresholdColor(state.totalDeltaV,
                       DV_STG_ALARM_MS, TFT_WHITE, TFT_RED,
                       DV_TOT_WARN_MS,  TFT_YELLOW, TFT_BLACK,
                            TFT_DARK_GREEN, TFT_BLACK, fg, bg);
        char dv[32]; fmtMsBuf(state.totalDeltaV, dv, sizeof(dv));
        plVal(5, 16, "\xCE\x94V.TOT", dv, fg, bg);
    }

    // Row 6 — Drogue deploy (CAG 1) | Main deploy (CAG 3)
    {
        // Green = STOWED (CAG off), Red = ARMED! (CAG on)
        const char *dStr = state.drogueDeploy ? "ARMED!" : "STOWED";
        uint16_t dFg = state.drogueDeploy ? TFT_WHITE : TFT_DARK_GREEN;
        uint16_t dBg = state.drogueDeploy ? TFT_RED   : TFT_BLACK;
        plValL(6, 10, "DROGUE", dStr, dFg, dBg);

        const char *mStr = state.mainDeploy ? "ARMED!" : "STOWED";
        uint16_t mFg = state.mainDeploy ? TFT_WHITE : TFT_DARK_GREEN;
        uint16_t mBg = state.mainDeploy ? TFT_RED   : TFT_BLACK;
        plValR(6, 11, "MAIN", mStr, mFg, mBg);
    }

    // Row 7 — Drogue cut (CAG 2) | Main cut (CAG 4)
    {
        // Green = SAFE (CAG off), Red = FIRED! (CAG on)
        const char *dcStr = state.drogueCut ? "FIRED!" : "SAFE";
        uint16_t dcFg = state.drogueCut ? TFT_WHITE : TFT_DARK_GREEN;
        uint16_t dcBg = state.drogueCut ? TFT_RED   : TFT_BLACK;
        plValL(7, 12, "D.CUT", dcStr, dcFg, dcBg);

        const char *mcStr = state.mainCut ? "FIRED!" : "SAFE";
        uint16_t mcFg = state.mainCut ? TFT_WHITE : TFT_DARK_GREEN;
        uint16_t mcBg = state.mainCut ? TFT_RED   : TFT_BLACK;
        plValR(7, 13, "M.CUT", mcStr, mcFg, mcBg);
    }

    // Redraw horizontal dividers every frame — printValue fillRect overwrites them.
    // Same pattern as ATT and ROVR screens.
    {
        uint16_t rH = rowHFor(NR);
        for (uint8_t row = 1; row < NR; row++) {
            uint16_t dy = TITLE_TOP + rH * row;
            tft.drawLine(0, dy,   CONTENT_W, dy,   TFT_GREY);
            tft.drawLine(0, dy+1, CONTENT_W, dy+1, TFT_GREY);
        }
    }
}

/***************************************************************************************
   Screen_LNDG.ino -- Landing screen — chromeScreen_LNDG, drawScreen_LNDG

   Two modes:
     - POWERED DESCENT (Screen_LNDG_Powered.ino) — graphical altitude tape + X-Pointer +
       ATT + V.Vrt bar (default)
     - RE-ENTRY (Screen_LNDG_Reentry.ino)        — graphical: corridor tape, heat-shield/
       retrograde alignment ball, chute deploy envelope, VSI/G/thermal gauges + text panel

   The two are sibling sidebar screens (screen_LNDG / screen_LNDGRE): a repeat press
   on the LNDG key cycles them, and AAA_Screens.ino derives _lndgReentryMode from the
   active screen before dispatching here.

   On vessel switch, all mode flags + parachute state are reset (SimpitHandler.ino).
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Mode flags + re-entry row-label toggles ────────────────────────────────────────────
// Externally accessible (declared extern in KCMk1_InfoDisp.h). _lndgReentryMode is
// the master toggle; row toggles drive label-swapping in re-entry mode.
bool _lndgReentryMode    = false;
bool _lndgReentryRow0TPe  = false;
bool _lndgReentryRow1SL   = false;

// ── Parachute deploy/cut latched state ─────────────────────────────────────────────────
// These are EXTERN globals (declared in KCMk1_InfoDisp.h) because SimpitHandler resets
// them on vessel switch. They're only consumed by the re-entry mode for chute status
// rendering, but the canonical definitions live here so the dispatcher file owns them.
bool _drogueDeployed  = false;
bool _mainDeployed    = false;
bool _drogueCut       = false;
bool _mainCut         = false;
bool _drogueArmedSafe = false;
bool _mainArmedSafe   = false;


// ── Top-level dispatchers ──────────────────────────────────────────────────────────────
// chromeScreen_LNDG is called once on screen entry / mode change, drawScreen_LNDG on
// every frame. Both delegate to the active mode's draw functions, which live in:
//   - Screen_LNDG_Powered.ino (when _lndgReentryMode is false)
//   - Screen_LNDG_Reentry.ino (when _lndgReentryMode is true)

static void chromeScreen_LNDG(KCM_TFT &tft) {
    if (!_lndgReentryMode) _lndgChromePowered(tft);
    else                   _lndgChromeReentry(tft);
}


static void drawScreen_LNDG(KCM_TFT &tft) {
    if (!_lndgReentryMode) _lndgDrawPowered(tft);
    else                   _lndgDrawReentry(tft);
}

/***************************************************************************************
   Screen_LNDG_AP.ino — Landing Autopilot console (chrome + draw + touch)

   Touch console for the landing autopilot on Controller_Main: DESC (descent-rate hold),
   HOVR (radar-altitude hold), BRAKE (armed suicide burn) and ENTRY (re-entry attitude
   hold). Renders the 44-byte landing status frame (state.ld*). Design:
   Mission_Autopilot.md §5, §7.2.

   LAYOUT (the shared console grid — ConsoleShared.ino):
     banner: <engaged modes | A/P OFF>  <IGN IN m:ss / FIRING / reason>  body · vessel  <ENGAGED>
     DESCENT             | OPTIONS              | DESCENT DATA
     [DESC]  [rate]      | ATT REF [RETRO/RADIAL]| RDR ALT
     [HOVR]  [altitude]  | TWR     [MEAS|value] | V/S
     [BRAKE] ign alt     | MARGIN  [m]          | H SPD
     [ENTRY] [AOA]       | ROLL    [entry roll] | ACCEL (+ source)
     hint                |                      | IGN ALT (orange when marginal)
     legend              | [A/P OFF]            | T-IMP
                         |                      | THRTL
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

static const uint16_t LD_LBL = KDC_LABEL_COLOR;
static const uint16_t LD_VAL = TFT_DARK_GREEN;
static const uint16_t LD_EDT = TFT_SKY;
#define LD_F_LBL  (&Roboto_Black_24)
#define LD_F_BANN (&Roboto_Black_36)

// Modes: 0 DESC, 1 HOVR, 2 BRAKE (ldMode 1..3), 3 ENTRY (ldEntry).
static const uint8_t LD_MODES = 4;
static const char *const LD_MODE_LBL[LD_MODES]  = { "DESC", "HOVR", "BRAKE", "ENTRY" };
static const uint8_t     LD_ENGAGE_OP[LD_MODES] = { LD_CMD_ENGAGE_DESC, LD_CMD_ENGAGE_HOVR, LD_CMD_ENGAGE_BRAKE, LD_CMD_ENGAGE_ENTRY };
// Options: 0 ATT REF (toggle), 1 TWR, 2 MARGIN, 3 ROLL
static const char *const LD_OPT_LBL[4] = { "ATT REF", "TWR", "MARGIN", "ROLL" };
static const uint8_t     LD_OPT_OP[4]  = { LD_CMD_SET_ATT_REF, LD_CMD_SET_TWR, LD_CMD_SET_MARGIN, LD_CMD_SET_ENTRY_ROLL };

static const uint8_t LD_SLOT_BTN  = 0;    // 0..3
static const uint8_t LD_SLOT_VAL  = 4;    // 4..7  rate / alt / ign alt / aoa
static const uint8_t LD_SLOT_OPT  = 8;    // 8..11
static const uint8_t LD_SLOT_DATA = 12;   // 12..18
static const uint8_t LD_SLOT_BANN = 19;

static const uint32_t LD_PENDING_TIMEOUT_MS = 3000;

static int8_t   ldPend[LD_MODES];  static uint32_t ldPendMs[LD_MODES];
static bool     ldDirty[LD_MODES]; static float ldPendVal[LD_MODES];      // rate, alt, (none), aoa
static bool     ldOptDirty[4];     static float ldOptPend[4];
static int8_t   ldPendRef = -1;    static uint32_t ldPendRefMs = 0;
static bool     ldScreenRefresh = false;

static bool ldEngaged(uint8_t i)   { return i < 3 ? (state.ldMode == (uint8_t)(i + 1)) : (state.ldEntry != 0); }
static bool ldCommanded(uint8_t i) { return ldPend[i] >= 0 ? (ldPend[i] == 1) : ldEngaged(i); }
static bool ldRadial()             { return (state.ldFlags & 0x08) != 0; }
static float ldEcho(uint8_t i)     { return i == 0 ? state.ldDescRate : i == 1 ? state.ldHovrAlt : state.ldEntryAoa; }
static float ldOptEcho(uint8_t i)  { return i == 1 ? state.ldTwr : i == 2 ? state.ldMargin : state.ldEntryRoll; }

static void ldReconcile() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < LD_MODES; i++) {
    if (ldPend[i] >= 0 && (ldEngaged(i) == (ldPend[i] == 1) || now - ldPendMs[i] > LD_PENDING_TIMEOUT_MS)) ldPend[i] = -1;
    if (i != 2 && ldDirty[i] && fabsf(ldEcho(i) - ldPendVal[i]) < 0.1f) ldDirty[i] = false;
  }
  for (uint8_t i = 1; i < 4; i++) if (ldOptDirty[i] && fabsf(ldOptEcho(i) - ldOptPend[i]) < 0.05f) ldOptDirty[i] = false;
  if (ldPendRef >= 0 && (ldRadial() == (ldPendRef == 1) || now - ldPendRefMs > LD_PENDING_TIMEOUT_MS)) ldPendRef = -1;
}

static float ldHorizontalSpeed() {
  float h2 = state.surfaceVel * state.surfaceVel - state.verticalVel * state.verticalVel;
  return h2 > 0.0f ? sqrtf(h2) : 0.0f;
}
static void ldFmtTime(float s, char *buf, size_t n) {
  if (s < 0.0f || s > 35999.0f) { snprintf(buf, n, "---"); return; }
  uint32_t t = (uint32_t)(s + 0.5f);
  snprintf(buf, n, "%lu:%02lu", (unsigned long)(t / 60), (unsigned long)(t % 60));
}

// ── Chrome ───────────────────────────────────────────────────────────────────────────
void chromeScreen_LNDGAP(KCM_TFT &tft) {
  kpForceClose();
  conDrawColumns(tft, "DESCENT", "OPTIONS", "DESCENT DATA");
  for (uint8_t i = 0; i < LD_MODES; i++) conDrawValueBox(tft, CON_C1X, i);
  for (uint8_t i = 0; i < 4; i++) {
    textLeft(tft, LD_F_LBL, CON_C2X + 4, conRowY(i), CON_COLW - CON_VALW, CON_ROW_H, LD_OPT_LBL[i], LD_LBL, TFT_BLACK);
    if (i > 0) conDrawValueBox(tft, CON_C2X, i);
  }
  static const char *const DATA_LBL[7] = { "RDR ALT", "V/S", "H SPD", "ACCEL", "IGN ALT", "T-IMP", "THRTL" };
  for (uint8_t r = 0; r < 7; r++)
    textLeft(tft, LD_F_LBL, CON_C3X + 4, conRowY(r), CON_COLW - CON_VALW, CON_ROW_H, DATA_LBL[r], LD_LBL, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 8,  CON_COLW - 8, 20, "BRAKE fires at IGN altitude, then", TFT_DARK_GREY, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 28, CON_COLW - 8, 20, "hands the descent to DESC at its rate.", TFT_DARK_GREY, TFT_BLACK);
  int16_t ly = conRowY(5) + 12, lx = CON_C1X + 2;
  tft.drawRect(lx, ly, 92, 28, TFT_GREY);             textCenter(tft, &Roboto_Black_16, lx, ly, 92, 28, "OFF", TFT_WHITE, TFT_BLACK);
  tft.drawRect(lx + 100, ly, 92, 28, TFT_CYAN);       textCenter(tft, &Roboto_Black_16, lx + 100, ly, 92, 28, "PENDING", TFT_CYAN, TFT_BLACK);
  tft.fillRect(lx + 200, ly, 92, 28, TFT_DARK_GREEN); textCenter(tft, &Roboto_Black_16, lx + 200, ly, 92, 28, "ENGAGED", TFT_WHITE, TFT_DARK_GREEN);
  ButtonLabel b = { "A/P OFF", TFT_WHITE, TFT_WHITE, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
  drawButton(tft, CON_C2X, CON_BIG_Y, CON_COLW, CON_BIG_H, b, &Roboto_Black_28, false);
  textCenter(tft, &Roboto_Black_16, CON_C2X, CON_BIG_Y + CON_BIG_H - 26, CON_COLW, 18, "disconnect all, throttle stays as set", TFT_GREY, TFT_OFF_BLACK);
}

// ── Draw ─────────────────────────────────────────────────────────────────────────────
void drawScreen_LNDGAP(KCM_TFT &tft) {
  if (kpTakeClosed()) ldScreenRefresh = true;
  if (ldScreenRefresh) {
    tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
    chromeScreen_LNDGAP(tft);
    invalidateRowCache(screen_LNDGAP);
    ldScreenRefresh = false;
  }
  if (kpIsOpen()) { kpDraw(tft); return; }

  char buf[48];
  bool anyPending = ldPendRef >= 0;
  for (uint8_t i = 0; i < LD_MODES; i++) if (ldPend[i] >= 0) anyPending = true;
  bool brakeArmed = (state.ldFlags & 0x02) != 0, firing = (state.ldFlags & 0x04) != 0, marginal = (state.ldFlags & 0x40) != 0;
  float tImpact = (state.verticalVel < -0.1f) ? state.radarAlt / -state.verticalVel : -1.0f;
  float tIgn = (brakeArmed && state.verticalVel < -0.1f) ? (state.radarAlt - state.ldIgnAlt) / -state.verticalVel : -1.0f;

  // Banner
  {
    char modes[40] = "";
    for (uint8_t i = 0; i < LD_MODES; i++)
      if (ldEngaged(i)) { if (modes[0]) strlcat(modes, "  ", sizeof(modes)); strlcat(modes, LD_MODE_LBL[i], sizeof(modes)); }
    bool engaged = modes[0] != '\0';
    bool showReason = (state.ldReason != HP_REASON_NONE && state.ldReasonAge <= 5);
    char note[24] = "";
    if (showReason) strlcpy(note, hpReasonLabel(state.ldReason), sizeof(note));
    else if (firing) strlcpy(note, "FIRING", sizeof(note));
    else if (brakeArmed && tIgn >= 0.0f) { char t[12]; ldFmtTime(tIgn, t, sizeof(t)); snprintf(note, sizeof(note), "IGN IN %s", t); }
    char key[112];
    snprintf(key, sizeof(key), "%s|%s|%s|%d|%s", engaged ? modes : "A/P OFF", note, state.gameSOI.c_str(), anyPending, state.vesselName.c_str());
    RowCache &rc = rowCache[screen_LNDGAP][LD_SLOT_BANN];
    if (rc.value != key) {
      tft.fillRect(0, CON_BANNER_Y, CONTENT_W, CON_BANNER_H, TFT_BLACK);
      textLeft(tft, LD_F_BANN, 8, CON_BANNER_Y, 316, CON_BANNER_H, engaged ? modes : "A/P OFF", engaged ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
      if (note[0]) textLeft(tft, &Roboto_Black_24, 330, CON_BANNER_Y, 300, CON_BANNER_H, note, TFT_ORANGE, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s \xB7 %s", state.gameSOI.c_str(), state.vesselName.c_str());
      textRight(tft, &Roboto_Black_20, 648, CON_BANNER_Y + 4,  CONTENT_W - 648 - 6, 24, buf, LD_LBL, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s%s", engaged ? "ENGAGED" : "A/P OFF", anyPending ? "..." : "");
      textRight(tft, &Roboto_Black_28, 648, CON_BANNER_Y + 30, CONTENT_W - 648 - 6, 30, buf, engaged ? TFT_NEON_GREEN : TFT_DARK_GREY, TFT_BLACK);
      rc.value = key;
    }
  }

  // Mode buttons + boxes
  int16_t vx = conValX(CON_C1X) + 6, vw = CON_VALW - 10;
  for (uint8_t i = 0; i < LD_MODES; i++) {
    ConBtnState st = ldEngaged(i) ? CON_BTN_ON : (ldPend[i] >= 0 ? CON_BTN_PENDING : CON_BTN_OFF);
    RowCache &rc = rowCache[screen_LNDGAP][LD_SLOT_BTN + i];
    char k[4]; snprintf(k, sizeof(k), "%d", (int)st);
    if (rc.value != k) { conDrawModeButton(tft, CON_C1X + 2, conRowY(i) + 4, CON_BTN_W, CON_VALH, LD_MODE_LBL[i], st); rc.value = k; }
    uint16_t fg;
    switch (i) {
      case 0: snprintf(buf, sizeof(buf), "%+.1f m/s", ldDirty[0] ? ldPendVal[0] : state.ldDescRate); fg = ldDirty[0] ? LD_EDT : (ldEngaged(0) ? LD_VAL : TFT_DARK_GREY); break;
      case 1: formatAltBuf(ldDirty[1] ? ldPendVal[1] : state.ldHovrAlt, buf, sizeof(buf)); fg = ldDirty[1] ? LD_EDT : (ldEngaged(1) ? LD_VAL : TFT_DARK_GREY); break;
      case 2: if (state.ldIgnAlt > 0.0f) formatAltBuf(state.ldIgnAlt, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
              fg = marginal ? TFT_ORANGE : (ldEngaged(2) ? LD_VAL : TFT_DARK_GREY); break;
      default: snprintf(buf, sizeof(buf), "AOA %.0f\xB0", ldDirty[3] ? ldPendVal[3] : state.ldEntryAoa); fg = ldDirty[3] ? LD_EDT : (ldEngaged(3) ? LD_VAL : TFT_DARK_GREY); break;
    }
    conPut(tft, screen_LNDGAP, LD_SLOT_VAL + i, vx, conRowY(i) + 4, vw, CON_VALH, buf, fg);
  }

  // Options
  {
    bool radial = ldPendRef >= 0 ? (ldPendRef == 1) : ldRadial();
    RowCache &rc = rowCache[screen_LNDGAP][LD_SLOT_OPT];
    char k[8]; snprintf(k, sizeof(k), "%d%d", radial, ldPendRef >= 0);
    if (rc.value != k) {
      int16_t x = conValX(CON_C2X), y = conRowY(0) + 4, w = CON_VALW - 2, h = CON_VALH;
      tft.fillRect(x, y, w, h, TFT_DARK_GREEN);
      tft.drawRect(x, y, w, h, ldPendRef >= 0 ? TFT_CYAN : TFT_GREY);
      textCenter(tft, &Roboto_Black_24, x, y, w, h, radial ? "RADIAL" : "RETRO", ldPendRef >= 0 ? TFT_CYAN : TFT_WHITE, TFT_DARK_GREEN);
      rc.value = k;
    }
  }
  int16_t ox = conValX(CON_C2X) + 6;
  { float twr = ldOptDirty[1] ? ldOptPend[1] : state.ldTwr;
    if (twr > 0.0f) snprintf(buf, sizeof(buf), "%.2f", twr); else snprintf(buf, sizeof(buf), state.ldAccelSource == 1 ? "MEAS" : "EST");
    conPut(tft, screen_LNDGAP, LD_SLOT_OPT + 1, ox, conRowY(1) + 4, vw, CON_VALH, buf, ldOptDirty[1] ? LD_EDT : LD_VAL); }
  snprintf(buf, sizeof(buf), "%.0f m", ldOptDirty[2] ? ldOptPend[2] : state.ldMargin);
  conPut(tft, screen_LNDGAP, LD_SLOT_OPT + 2, ox, conRowY(2) + 4, vw, CON_VALH, buf, ldOptDirty[2] ? LD_EDT : LD_VAL);
  snprintf(buf, sizeof(buf), "%.0f\xB0", ldOptDirty[3] ? ldOptPend[3] : state.ldEntryRoll);
  conPut(tft, screen_LNDGAP, LD_SLOT_OPT + 3, ox, conRowY(3) + 4, vw, CON_VALH, buf, ldOptDirty[3] ? LD_EDT : LD_VAL);

  // Descent data
  int16_t dx = conValX(CON_C3X) + 6;
  formatAltBuf(state.radarAlt, buf, sizeof(buf));               conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 0, dx, conRowY(0) + 4, vw, CON_VALH, buf, LD_VAL);
  snprintf(buf, sizeof(buf), "%+.0f m/s", state.verticalVel);   conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 1, dx, conRowY(1) + 4, vw, CON_VALH, buf, (tImpact >= 0.0f && tImpact < 30.0f) ? TFT_ORANGE : LD_VAL);
  snprintf(buf, sizeof(buf), "%.0f m/s", ldHorizontalSpeed());  conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 2, dx, conRowY(2) + 4, vw, CON_VALH, buf, LD_VAL);
  { static const char *const SRC[3] = { "EST", "MEAS", "TWR" };
    if (state.ldAccelEst > 0.0f) snprintf(buf, sizeof(buf), "%.1f %s", state.ldAccelEst, SRC[state.ldAccelSource < 3 ? state.ldAccelSource : 0]); else snprintf(buf, sizeof(buf), "---");
    conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 3, dx, conRowY(3) + 4, vw, CON_VALH, buf, state.ldAccelEst > 0.0f ? LD_VAL : TFT_DARK_GREY); }
  if (state.ldIgnAlt > 0.0f) formatAltBuf(state.ldIgnAlt, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 4, dx, conRowY(4) + 4, vw, CON_VALH, buf, marginal ? TFT_ORANGE : (state.ldIgnAlt > 0.0f ? LD_VAL : TFT_DARK_GREY));
  ldFmtTime(tImpact, buf, sizeof(buf));                          conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 5, dx, conRowY(5) + 4, vw, CON_VALH, buf, (tImpact >= 0.0f && tImpact < 30.0f) ? TFT_ORANGE : (tImpact >= 0.0f ? LD_VAL : TFT_DARK_GREY));
  snprintf(buf, sizeof(buf), "%.0f %%", state.ldCmdThrottle * 100.0f);
  conPut(tft, screen_LNDGAP, LD_SLOT_DATA + 6, dx, conRowY(6) + 4, vw, CON_VALH, buf, state.ldMode ? LD_VAL : TFT_GREY);
}

// ── Keypad commits ───────────────────────────────────────────────────────────────────
static void ldModeCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx < 0 || idx >= LD_MODES || idx == 2) return;
  ldPendVal[idx] = v;
  uint8_t op = idx == 0 ? LD_CMD_SET_DESC_RATE : idx == 1 ? LD_CMD_SET_HOVR_ALT : LD_CMD_SET_ENTRY_AOA;
  ldDirty[idx] = apEnqueueCmd(op, v);
}
static void ldOptCommit(int8_t idx, float v, bool off) {
  if (idx < 1 || idx > 3) return;
  if (off && idx == 1) v = 0.0f;              // TWR OFF = measured / estimated
  ldOptPend[idx] = v;
  ldOptDirty[idx] = apEnqueueCmd(LD_OPT_OP[idx], v);
}

// ── Touch ────────────────────────────────────────────────────────────────────────────
void lndgApScreenTouch(uint16_t x, uint16_t y) {
  if (kpIsOpen()) { kpTouch(x, y); return; }
  uint32_t now = millis();

  if (y >= CON_BIG_Y && y < CON_BIG_Y + CON_BIG_H && x >= CON_C2X && x < CON_C2X + CON_COLW) {
    if (apEnqueueCmd(HP_CMD_AP_OFF, 0.0f))
      for (uint8_t i = 0; i < LD_MODES; i++) if (ldEngaged(i)) { ldPend[i] = 0; ldPendMs[i] = now; }
    return;
  }

  for (uint8_t r = 0; r < 4; r++) {
    int16_t cy = conRowY(r);
    if (y < cy || y >= cy + CON_ROW_H) continue;
    if (x >= CON_C1X + 2 && x < CON_C1X + 2 + CON_BTN_W) {
      bool want = !ldCommanded(r);
      if (apEnqueueCmd(LD_ENGAGE_OP[r], want ? 1.0f : 0.0f)) { ldPend[r] = want ? 1 : 0; ldPendMs[r] = now; }
      return;
    }
    if (x >= conValX(CON_C1X) && x < conValX(CON_C1X) + CON_VALW && r != 2) {
      KpField f = (r == 0) ? KpField{ "DESCENT RATE", "m/s", -50.0f, 20.0f, false, true, 1 }
                : (r == 1) ? KpField{ "HOVER ALTITUDE (AGL)", "m", 2.0f, 5000.0f, false, false, 0 }
                           : KpField{ "ENTRY ANGLE OF ATTACK", "\xB0", -30.0f, 40.0f, false, true, 0 };
      kpOpen(f, (int8_t)r, ldModeCommit);
      return;
    }
    if (x >= conValX(CON_C2X) && x < conValX(CON_C2X) + CON_VALW) {
      if (r == 0) {
        bool want = !(ldPendRef >= 0 ? (ldPendRef == 1) : ldRadial());
        if (apEnqueueCmd(LD_CMD_SET_ATT_REF, want ? 1.0f : 0.0f)) { ldPendRef = want ? 1 : 0; ldPendRefMs = now; }
        return;
      }
      KpField f = (r == 1) ? KpField{ "TWR OVERRIDE (OFF = MEAS)", "", 0.0f, 20.0f, true, false, 2 }
                : (r == 2) ? KpField{ "IGNITION MARGIN", "m", 0.0f, 5000.0f, false, false, 0 }
                           : KpField{ "ENTRY ROLL", "\xB0", -180.0f, 180.0f, false, true, 0 };
      kpOpen(f, (int8_t)r, ldOptCommit);
      return;
    }
  }
}

/***************************************************************************************
   Screen_LNDG_Powered.ino -- Powered descent (one of two modes of the LNDG screen).

   Active when _lndgReentryMode is FALSE: POWERED DESCENT and RE-ENTRY are sibling
   sidebar screens (a repeat press on the LNDG key cycles them), and the flag is
   derived from the active screen in AAA_Screens.ino.

   LAYOUT (rev-2 rebalance — graphics fill x=0..578, text panel x=580..940):
     - Altitude tape (x=0..70, full height)     — vertical 0-500m / 0-50m altitude scale
     - X-Pointer square (x=128..488, side 360)  — surface-drift centrepiece (lat/fwd velocity)
     - ATT bullseye (centred under XP, R=50)    — attitude alignment dot in concentric rings
     - V.Vrt bar (x=544..574, full height)      — vertical velocity 0-15 m/s gauge (far right)
     - Right panel (x=580..940, 360px)          — numeric readouts

   Phase membership (LNDG screen has two modes):
     - POWERED DESCENT (this file)             — default
     - RE-ENTRY (Screen_LNDG_Reentry.ino)     — its own sidebar screen (LNDG key cycle)

   Top-level dispatcher Screen_LNDG.ino selects which to draw based on
   _lndgReentryMode.

   Public-to-the-sketch entry points (called by the LNDG dispatcher):
     - _lndgChromePowered(tft) — initial chrome (tape, XP, ATT, V.Vrt, panel labels)
     - _lndgDrawPowered(tft)   — per-frame value updates
****************************************************************************************/

static const uint8_t LNDG_SC = (uint8_t)screen_LNDG;   // row-cache / print-state index

/***************************************************************************************
   LAYOUT CONSTANTS
   Altitude tape:  x=40..70,  y=TITLE_TOP+8..SCREEN_H  (full height = 0-500m / 0-50m)
   X-Pointer:      360×360,   x=128..488, y=88..448    (surface-drift centrepiece)
   ATT bullseye:   R=50,      centred under the X-Pointer
   V.Vrt bar:      x=544..574, full height             (descent rate 0-15 m/s)
   Right panel:    x=580..940 (360px, standardized)
****************************************************************************************/
// rev-2 rebalance: the text panel is standardized to the 360px right-panel used by
// every other screen (x=580..940), freeing the left ~578px for the graphical descent
// instruments. The X-Pointer (surface-drift) is the featured centrepiece, flanked by
// full-height altitude and vertical-speed tapes, with the attitude bullseye below it.
static const uint16_t LNDG_TEXT_X    = 580;              // right text panel left edge (360px wide)
static const uint16_t LNDG_DIV_X     = LNDG_TEXT_X - 2;  // 578 — graphical/text divider x

static const uint16_t LNDG_TAPE_X    = 40;
static const uint16_t LNDG_TAPE_W    = 44;   // matches the ascent-screen vertical bars
static const uint16_t LNDG_TAPE_Y    = TITLE_TOP + 8;
static const uint16_t LNDG_TAPE_H    = SCREEN_H - LNDG_TAPE_Y;
static const float    LNDG_TAPE_PPM  = (float)LNDG_TAPE_H / 500.0f;

// X-Pointer (surface-drift cross-pointer) — the featured instrument. Left/bottom
// margins carry the FWD/AFT and LATERAL axis ticks + labels, so it is inset from the
// altitude tape and leaves room below for the axis row and the attitude bullseye.
static const uint16_t LNDG_XP_X     = 136;
static const uint16_t LNDG_XP_Y     = TITLE_TOP + 26;               // 88 — below the SURF DRIFT title
static const uint16_t LNDG_XP_SIDE  = 332;                          // trimmed to give the ATT + ground-track
                                                                   //   compasses below more room
static const uint16_t LNDG_XP_CX    = LNDG_XP_X + LNDG_XP_SIDE / 2;  // 302
static const uint16_t LNDG_XP_CY    = LNDG_XP_Y + LNDG_XP_SIDE / 2;  // 254
static const float    LNDG_XP_SCALE = (float)(LNDG_XP_SIDE / 2) / 15.0f;  // 12 px/(m/s) — ±15 to edge

// X-Pointer field colours
static const uint16_t LNDG_XP_BG    = TFT_DARK_GREY;
static const uint16_t LNDG_XP_GRID  = TFT_LIGHT_GREY;
static const uint16_t LNDG_XP_INNER = TFT_GREY;

// Needle state
static int16_t _lndgPrevLatX  = -999;
static int16_t _lndgPrevFwdY  = -999;
static float   _lndgPrevAlt   = -1.0f;
static bool    _lndgLowAltMode = false;  // true when radarAlt < 50m (high-res tape)


/***************************************************************************************
   HORIZONTAL VELOCITY COLOUR
****************************************************************************************/
static void _lndgHorzColor(float v, float tGround, uint16_t &fg, uint16_t &bg) {
    float av = fabsf(v);
    float warnMs, alarmMs;
    if      (tGround < 0.0f || tGround > LNDG_HVEL_T_LOOSE_S)
        { warnMs = LNDG_HVEL_WARN_LOOSE_MS; alarmMs = LNDG_HVEL_ALARM_LOOSE_MS; }
    else if (tGround > LNDG_HVEL_T_MID_S)
        { warnMs = LNDG_HVEL_WARN_MID_MS;   alarmMs = LNDG_HVEL_ALARM_MID_MS;   }
    else if (tGround > LNDG_TGRND_ALARM_S)
        { warnMs = LNDG_HVEL_WARN_TIGHT_MS; alarmMs = LNDG_HVEL_ALARM_TIGHT_MS; }
    else
        { warnMs = LNDG_HVEL_WARN_FINAL_MS; alarmMs = LNDG_HVEL_ALARM_FINAL_MS; }
    if      (av >= alarmMs) { fg = TFT_WHITE;     bg = TFT_RED;   }
    else if (av >= warnMs)  { fg = TFT_YELLOW;    bg = TFT_BLACK; }
    else                    { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
}


/***************************************************************************************
   X-POINTER CHROME ELEMENTS
   Drawn at chrome time and re-applied after needle erase.
****************************************************************************************/
static void _lndgDrawXpChrome(KCM_TFT &tft) {
    uint16_t g5  = (uint16_t)(5.0f  * LNDG_XP_SCALE);
    uint16_t g10 = (uint16_t)(10.0f * LNDG_XP_SCALE);
    uint16_t g2  = (uint16_t)(2.0f  * LNDG_XP_SCALE);

    // Centre crosshairs (dim)
    tft.drawLine(LNDG_XP_CX, LNDG_XP_Y + 1,
                 LNDG_XP_CX, LNDG_XP_Y + LNDG_XP_SIDE - 1, LNDG_XP_GRID);
    tft.drawLine(LNDG_XP_X + 1, LNDG_XP_CY,
                 LNDG_XP_X + LNDG_XP_SIDE - 1, LNDG_XP_CY, LNDG_XP_GRID);

    // ±5 m/s dashed reference lines
    for (uint16_t y = LNDG_XP_Y + 2; y < LNDG_XP_Y + LNDG_XP_SIDE - 2; y += 8) {
        tft.drawPixel(LNDG_XP_CX - g5, y, LNDG_XP_GRID);
        tft.drawPixel(LNDG_XP_CX + g5, y, LNDG_XP_GRID);
    }
    for (uint16_t x = LNDG_XP_X + 2; x < LNDG_XP_X + LNDG_XP_SIDE - 2; x += 8) {
        tft.drawPixel(x, LNDG_XP_CY - g5, LNDG_XP_GRID);
        tft.drawPixel(x, LNDG_XP_CY + g5, LNDG_XP_GRID);
    }

    // ±10 m/s dashed reference lines
    for (uint16_t y = LNDG_XP_Y + 2; y < LNDG_XP_Y + LNDG_XP_SIDE - 2; y += 8) {
        tft.drawPixel(LNDG_XP_CX - g10, y, LNDG_XP_GRID);
        tft.drawPixel(LNDG_XP_CX + g10, y, LNDG_XP_GRID);
    }
    for (uint16_t x = LNDG_XP_X + 2; x < LNDG_XP_X + LNDG_XP_SIDE - 2; x += 8) {
        tft.drawPixel(x, LNDG_XP_CY - g10, LNDG_XP_GRID);
        tft.drawPixel(x, LNDG_XP_CY + g10, LNDG_XP_GRID);
    }

    // Inner ±2 m/s zone (slightly lighter fill)
    tft.fillRect(LNDG_XP_CX - g2, LNDG_XP_CY - g2, g2 * 2, g2 * 2, LNDG_XP_INNER);

    // Centre reference dot (fixed)
    tft.fillCircle(LNDG_XP_CX, LNDG_XP_CY, 5, TFT_BLACK);
    tft.fillCircle(LNDG_XP_CX, LNDG_XP_CY, 2, TFT_DARK_GREY);
}


// Low-altitude tape: covers 0-50m, same geometry as normal tape
static const float LNDG_TAPE_PPM_LOW = (float)LNDG_TAPE_H / 50.0f;

static void _lndgDrawTapeChrome(KCM_TFT &tft, bool lowAlt) {
    float ppm = lowAlt ? LNDG_TAPE_PPM_LOW : LNDG_TAPE_PPM;

    // Clear only the numeric label area (x=14..TAPE_X-1), preserving the ALTITUDE strip (x=0..13)
    tft.fillRect(14, LNDG_TAPE_Y, LNDG_TAPE_X - 14, LNDG_TAPE_H, TFT_BLACK);

    if (lowAlt) {
        // Low-alt: dark grey upper (unlit), light grey lower (lit) — draw function updates this
        // Chrome just paints the full tape dark grey as the baseline unlit state
        tft.fillRect(LNDG_TAPE_X, LNDG_TAPE_Y, LNDG_TAPE_W, LNDG_TAPE_H, TFT_DARK_GREY);
    } else {
        // Normal: three zone dim backgrounds
        uint16_t y200 = SCREEN_H - (uint16_t)(200.0f * ppm);
        uint16_t y50  = SCREEN_H - (uint16_t)( 50.0f * ppm);
        tft.fillRect(LNDG_TAPE_X, LNDG_TAPE_Y, LNDG_TAPE_W,
                     y200 - LNDG_TAPE_Y, TFT_JUNGLE);
        tft.fillRect(LNDG_TAPE_X, y200, LNDG_TAPE_W, y50 - y200,      TFT_OLIVE);
        tft.fillRect(LNDG_TAPE_X, y50,  LNDG_TAPE_W, SCREEN_H - y50,  TFT_DARK_RED);
    }

    // Ticks on both sides, inside border
    // Chrome paints the full tape as dim, so all ticks start light grey
    uint16_t tickCol = TFT_LIGHT_GREY;

    auto tapeTick = [&](uint16_t altM, uint8_t tickLen) {
        uint16_t ty = SCREEN_H - (uint16_t)(altM * ppm);
        if (ty < LNDG_TAPE_Y || ty >= (uint16_t)SCREEN_H) return;
        tft.drawLine(LNDG_TAPE_X + 1,                         ty,
                     LNDG_TAPE_X + tickLen,                    ty, tickCol);
        tft.drawLine(LNDG_TAPE_X + LNDG_TAPE_W - 1 - tickLen, ty,
                     LNDG_TAPE_X + LNDG_TAPE_W - 2,            ty, tickCol);
    };

    if (lowAlt) {
        // Major every 10m, minor every 5m
        for (uint16_t m = 10; m <= 50; m += 10) tapeTick(m, 8);
        for (uint16_t m =  5; m <= 45; m += 10) tapeTick(m, 4);
    } else {
        // Major every 100m, minor every 25m
        for (uint16_t m = 100; m <= 500; m += 100) tapeTick(m, 8);
        for (uint16_t m =  25; m <= 475; m +=  25)
            if (m % 100 != 0) tapeTick(m, 4);
    }

    tft.drawRect(LNDG_TAPE_X, LNDG_TAPE_Y, LNDG_TAPE_W, LNDG_TAPE_H, TFT_GREY);

    // Scale labels — right-aligned to x = LNDG_TAPE_X - 2
    // Normal: every 50m, range 50..450 (skip 0m=off-screen, 500m=clips top)
    // Low-alt: every 5m,  range 5..45  (skip 0m=off-screen, 50m=clips top)
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    uint16_t labelStep  = lowAlt ? 5  : 50;
    uint16_t labelStart = 0;                  // include 0m (clamped to bottom)
    uint16_t labelEnd   = lowAlt ? 50 : 500;  // include 50m/500m (clamped to top)
    for (uint16_t m = labelStart; m <= labelEnd; m += labelStep) {
        char buf[5];  snprintf(buf, sizeof(buf), "%u", m);
        uint16_t lw = strlen(buf) * 7;
        uint16_t lx = LNDG_TAPE_X - 2 - lw;
        // 0m would give ty=SCREEN_H (off screen) — clamp to SCREEN_H-1
        uint16_t ty = (m == 0) ? (uint16_t)(SCREEN_H - 1)
                                : (uint16_t)(SCREEN_H - (uint16_t)(m * ppm));
        uint16_t ly = (uint16_t)max((int)LNDG_TAPE_Y, min((int)(SCREEN_H - 14), (int)ty - 7));
        tft.setCursor(lx, ly);
        tft.print(buf);
    }
    // Redraw ALTITUDE vertical label — must come after label area clear.
    // Full-height box so the label is vertically centred on the tape.
    drawVerticalText(tft, 0, LNDG_TAPE_Y, 14, LNDG_TAPE_H,
                     &Roboto_Black_12, "ALTITUDE", TFT_LIGHT_GREY, TFT_BLACK);
}


/***************************************************************************************
   ATTITUDE BULLSEYE — constants and state
   Field: 120×120px, centred horizontally under X-Pointer
   Scale: ±15° full deflection, 3 reference rings at 5°/10°/15°
****************************************************************************************/
// In the band below the X-Pointer's lateral axis row. Shifted left of the
// X-Pointer centre (307) so the ground-track compass sits to its right, the pair
// balanced about the centre.
static const uint16_t LNDG_ATT_CX    = 216;          // left of the X-Pointer centre
static const uint16_t LNDG_ATT_CY    = 534;          // below the X-Pointer's lateral axis row
static const uint8_t  LNDG_ATT_R     = 58;           // outer ring radius (= ±15°)
static const float    LNDG_ATT_SCALE = (float)LNDG_ATT_R / 15.0f;

static int16_t _lndgPrevAttX = -999;
static int16_t _lndgPrevAttY = -999;


static void _lndgDrawAttChrome(KCM_TFT &tft) {
    // Black disc background (no bounding square)
    tft.fillCircle(LNDG_ATT_CX, LNDG_ATT_CY, LNDG_ATT_R + 2, TFT_BLACK);

    // Inner good-zone fill (subtle, inside ±5° ring)
    uint8_t r5  = (uint8_t)(5.0f  * LNDG_ATT_SCALE);
    uint8_t r10 = (uint8_t)(10.0f * LNDG_ATT_SCALE);
    tft.fillCircle(LNDG_ATT_CX, LNDG_ATT_CY, r5, TFT_OFF_BLACK);

    // Reference rings at 5°, 10°, 15°
    tft.drawCircle(LNDG_ATT_CX, LNDG_ATT_CY, r5,         TFT_DARK_GREEN);
    tft.drawCircle(LNDG_ATT_CX, LNDG_ATT_CY, r10,        TFT_DARK_GREY);
    tft.drawCircle(LNDG_ATT_CX, LNDG_ATT_CY, LNDG_ATT_R, TFT_GREY);

    // Centre crosshairs (cardinal lines with gap)
    uint8_t gap = 6, arm = LNDG_ATT_R - 1;
    tft.drawLine(LNDG_ATT_CX, LNDG_ATT_CY - arm, LNDG_ATT_CX, LNDG_ATT_CY - gap, TFT_DARK_GREY);
    tft.drawLine(LNDG_ATT_CX, LNDG_ATT_CY + gap, LNDG_ATT_CX, LNDG_ATT_CY + arm, TFT_DARK_GREY);
    tft.drawLine(LNDG_ATT_CX - arm, LNDG_ATT_CY, LNDG_ATT_CX - gap, LNDG_ATT_CY, TFT_DARK_GREY);
    tft.drawLine(LNDG_ATT_CX + gap, LNDG_ATT_CY, LNDG_ATT_CX + arm, LNDG_ATT_CY, TFT_DARK_GREY);

    // 30° tick marks on outer ring (skip cardinals 0/90/180/270)
    for (uint16_t deg = 0; deg < 360; deg += 30) {
        if (deg % 90 == 0) continue;
        float rad = (deg - 90) * DEG_TO_RAD;
        int16_t ox = LNDG_ATT_CX + (int16_t)(LNDG_ATT_R * cosf(rad));
        int16_t oy = LNDG_ATT_CY + (int16_t)(LNDG_ATT_R * sinf(rad));
        int16_t ix = LNDG_ATT_CX + (int16_t)((LNDG_ATT_R - 6) * cosf(rad));
        int16_t iy = LNDG_ATT_CY + (int16_t)((LNDG_ATT_R - 6) * sinf(rad));
        tft.drawLine(ox, oy, ix, iy, TFT_DARK_GREY);
    }

    // Bezel ring
    tft.drawCircle(LNDG_ATT_CX, LNDG_ATT_CY, LNDG_ATT_R,     TFT_GREY);
    tft.drawCircle(LNDG_ATT_CX, LNDG_ATT_CY, LNDG_ATT_R + 1, TFT_DARK_GREY);

    // Range label "15°" outboard of the outer ring, lower-right (clear of the border)
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LNDG_ATT_CX + LNDG_ATT_R + 6, LNDG_ATT_CY + LNDG_ATT_R / 2);
    tft.print("15\xb0");

    // "ATT" vertical label to the left of the circle, centred on ring height
    drawVerticalText(tft, LNDG_ATT_CX - LNDG_ATT_R - 20, LNDG_ATT_CY - 21, 14, 42,
                     &Roboto_Black_12, "ATT", TFT_LIGHT_GREY, TFT_BLACK);
}


static void _lndgDrawAtt(KCM_TFT &tft) {
    // Deviation of nose from vertical in body frame.
    // tilt = total angular distance from vertical (0 = pointing straight up).
    // Decomposed by roll into screen axes:
    //   dot_y (up on screen  = pitch fwd) = -tilt * cos(roll)  [−ve: nose fwd → dot up]
    //   dot_x (right on screen = yaw right) = tilt * sin(roll)
    float tilt    = 90.0f - state.pitch;
    float rollRad = state.roll * DEG_TO_RAD;
    int16_t dotX = (int16_t)(LNDG_ATT_CX +  tilt * sinf(rollRad) * LNDG_ATT_SCALE);
    int16_t dotY = (int16_t)(LNDG_ATT_CY -  tilt * cosf(rollRad) * LNDG_ATT_SCALE);

    // Clamp to outer ring
    float dx = (float)(dotX - (int16_t)LNDG_ATT_CX);
    float dy = (float)(dotY - (int16_t)LNDG_ATT_CY);
    float dist = sqrtf(dx * dx + dy * dy);
    if (dist > (float)LNDG_ATT_R) {
        dotX = (int16_t)(LNDG_ATT_CX + dx * LNDG_ATT_R / dist);
        dotY = (int16_t)(LNDG_ATT_CY + dy * LNDG_ATT_R / dist);
    }

    // Dot colour by tilt magnitude
    float absTilt = fabsf(tilt);
    uint16_t dotCol = (absTilt >= 5.0f) ? TFT_RED :
                      (absTilt >= 2.0f) ? TFT_YELLOW : TFT_DARK_GREEN;

    if (dotX != _lndgPrevAttX || dotY != _lndgPrevAttY) {
        // Erase old dot: fillCircle with black to restore background
        if (_lndgPrevAttX >= 0) {
            tft.fillCircle(_lndgPrevAttX, _lndgPrevAttY, 8, TFT_BLACK);
            _lndgDrawAttChrome(tft);  // restore rings/ticks erased by circle fill
        }

        // Draw new dot
        tft.fillCircle(dotX, dotY, 6, dotCol);
        tft.fillCircle(dotX, dotY, 2, TFT_WHITE);

        _lndgPrevAttX = dotX;
        _lndgPrevAttY = dotY;
    }
}


/***************************************************************************************
   GROUND-TRACK COMPASS — heading-up rose with a surface-velocity track marker.
   Right of the ATT bullseye, the pair balanced about the X-Pointer centre.
****************************************************************************************/
static const uint16_t LNDG_TRK_CX = 388;
static const uint16_t LNDG_TRK_CY = LNDG_ATT_CY;   // same row as the ATT bullseye
static const uint8_t  LNDG_TRK_R  = 58;
static float _lndgPrevTrkHdg = -9999.0f;
static float _lndgPrevTrkVel = -9999.0f;

static void _lndgDrawTrkChrome(KCM_TFT &tft) {
    tft.fillCircle(LNDG_TRK_CX, LNDG_TRK_CY, LNDG_TRK_R + 1, TFT_BLACK);
    tft.drawCircle(LNDG_TRK_CX, LNDG_TRK_CY, LNDG_TRK_R,     TFT_GREY);
    tft.drawCircle(LNDG_TRK_CX, LNDG_TRK_CY, LNDG_TRK_R + 1, TFT_DARK_GREY);

    // "GND TRK" vertical label to the RIGHT of the rose — mirrors the ATT label
    drawVerticalText(tft, LNDG_TRK_CX + LNDG_TRK_R + 6, LNDG_TRK_CY - 50, 14, 100,
                     &Roboto_Black_12, "GND TRK", TFT_LIGHT_GREY, TFT_BLACK);

    _lndgPrevTrkHdg = -9999.0f;   // force the rose to redraw on the next update
    _lndgPrevTrkVel = -9999.0f;
}

// Redraw the rotating rose + track marker when heading or the surface-velocity
// track moves. Heading-up: the vessel nose is fixed at the top (12 o'clock); a
// world direction wd appears at screen angle (wd - heading - 90)°.
static void _lndgDrawTrk(KCM_TFT &tft) {
    float hdg    = state.heading;
    float trk    = state.srfVelHeading;
    bool  moving = (state.surfaceVel > 1.0f);   // track meaningful only when moving

    if (_lndgPrevTrkHdg > -9000.0f &&
        fabsf(hdg - _lndgPrevTrkHdg) < 0.5f &&
        (!moving || fabsf(trk - _lndgPrevTrkVel) < 0.5f)) return;
    _lndgPrevTrkHdg = hdg;
    _lndgPrevTrkVel = trk;

    // Clear the rose interior (inside the bezel)
    tft.fillCircle(LNDG_TRK_CX, LNDG_TRK_CY, LNDG_TRK_R - 1, TFT_BLACK);

    // Compass ticks every 15° — long/bright at the cardinals, medium at the 30°
    // marks, short/dim at the intermediate 15° marks, so the finer cadence reads
    // clearly without crowding the rose.
    for (int16_t d = 0; d < 360; d += 15) {
        float   a    = (d - hdg - 90.0f) * (float)DEG_TO_RAD;
        bool    maj  = (d % 90 == 0);
        bool    med  = (d % 30 == 0);
        int16_t r0   = LNDG_TRK_R - 1;
        int16_t r1   = LNDG_TRK_R - (maj ? 9 : (med ? 6 : 4));
        float   ca = cosf(a), sa = sinf(a);
        tft.drawLine(LNDG_TRK_CX + (int16_t)(r0 * ca), LNDG_TRK_CY + (int16_t)(r0 * sa),
                     LNDG_TRK_CX + (int16_t)(r1 * ca), LNDG_TRK_CY + (int16_t)(r1 * sa),
                     (maj || med) ? TFT_LIGHT_GREY : TFT_GREY);
    }

    // Rotating cardinals
    tft.setFont(Roboto_Black_12);
    static const int16_t cwd[] = {0, 90, 180, 270};
    static const char *  ctx[] = {"N", "E", "S", "W"};
    for (uint8_t i = 0; i < 4; i++) {
        float   a  = (cwd[i] - hdg - 90.0f) * (float)DEG_TO_RAD;
        int16_t lx = LNDG_TRK_CX + (int16_t)((LNDG_TRK_R - 19) * cosf(a));
        int16_t ly = LNDG_TRK_CY + (int16_t)((LNDG_TRK_R - 19) * sinf(a));
        int16_t cw = getFontStringWidth(&Roboto_Black_12, ctx[i]);
        tft.setTextColor(cwd[i] == 0 ? TFT_YELLOW : TFT_LIGHT_GREY, TFT_BLACK);
        tft.setCursor(lx - cw / 2, ly - 7);
        tft.print(ctx[i]);
    }

    // Track marker — surface-velocity direction relative to the nose (green arrow
    // from centre to the rim). Suppressed when nearly stationary.
    if (moving) {
        float   ta = (trk - hdg - 90.0f) * (float)DEG_TO_RAD;
        int16_t tx = LNDG_TRK_CX + (int16_t)((LNDG_TRK_R - 6) * cosf(ta));
        int16_t ty = LNDG_TRK_CY + (int16_t)((LNDG_TRK_R - 6) * sinf(ta));
        tft.drawLine(LNDG_TRK_CX, LNDG_TRK_CY, tx, ty, TFT_NEON_GREEN);
        tft.fillCircle(tx, ty, 4, TFT_NEON_GREEN);
    }

    // Centre dot (vessel) + fixed nose marker at the top — a filled white triangle
    // pointing inward from the top rim, far more obvious than a thin lubber line.
    tft.fillCircle(LNDG_TRK_CX, LNDG_TRK_CY, 3, TFT_DARK_GREY);
    tft.fillTriangle(LNDG_TRK_CX,     LNDG_TRK_CY - LNDG_TRK_R + 12,
                     LNDG_TRK_CX - 6, LNDG_TRK_CY - LNDG_TRK_R + 1,
                     LNDG_TRK_CX + 6, LNDG_TRK_CY - LNDG_TRK_R + 1, TFT_WHITE);
}


/***************************************************************************************
   V.VRT BAR — 0-15 m/s descent rate gauge
   Geometry: equal left/right margins (~27px) with distinct label zones
   x=304..334 bar, numeric labels right-align to x=293, "V.Vrt" strip x=250..264
   Colours: green <5, yellow 5-8, red >8 m/s (matches text panel thresholds)
****************************************************************************************/
// Full-height descent-rate bar on the far right of the graphics zone, mirroring the
// altitude tape on the left and flanking the X-Pointer.
static const uint16_t LNDG_VV_W    = 44;                          // matches the ascent-screen vertical bars
static const uint16_t LNDG_VV_X    = 530;                         // bar x=[530,574]; divider at 578
static const uint16_t LNDG_VV_Y    = TITLE_TOP + 8;              // 70 — top, matching the altitude tape
static const uint16_t LNDG_VV_H    = SCREEN_H - LNDG_VV_Y - 3;   // bottom border on row 596 (clear of overscan)
static const float    LNDG_VV_MAX  = 15.0f;
static const float    LNDG_VV_PPM  = (float)LNDG_VV_H / LNDG_VV_MAX;
static const uint16_t LNDG_VV_BOT  = LNDG_VV_Y + LNDG_VV_H;      // 0 m/s baseline

static const uint16_t LNDG_VV_Y5   = LNDG_VV_BOT - (uint16_t)(5.0f  * LNDG_VV_PPM);
static const uint16_t LNDG_VV_Y8   = LNDG_VV_BOT - (uint16_t)(8.0f  * LNDG_VV_PPM);
static const uint16_t LNDG_VV_LBRT = LNDG_VV_X - 3;  // numeric labels right-align just left of the bar

static float _lndgPrevVV = -9999.0f;


static void _lndgDrawVvChrome(KCM_TFT &tft) {
    // Dim zone backgrounds
    tft.fillRect(LNDG_VV_X, LNDG_VV_Y,  LNDG_VV_W, LNDG_VV_Y8 - LNDG_VV_Y,  TFT_DARK_RED);
    tft.fillRect(LNDG_VV_X, LNDG_VV_Y8, LNDG_VV_W, LNDG_VV_Y5 - LNDG_VV_Y8, TFT_OLIVE);
    tft.fillRect(LNDG_VV_X, LNDG_VV_Y5, LNDG_VV_W, LNDG_VV_BOT - LNDG_VV_Y5, TFT_JUNGLE);

    // Ticks both sides — major 8px every 5 m/s, minor 4px every 1 m/s
    auto vvTick = [&](uint16_t vMs, uint8_t tickLen) {
        uint16_t ty = LNDG_VV_BOT - (uint16_t)(vMs * LNDG_VV_PPM);
        if (ty < LNDG_VV_Y || ty > LNDG_VV_BOT) return;
        tft.drawLine(LNDG_VV_X + 1,                         ty,
                     LNDG_VV_X + tickLen,                    ty, TFT_LIGHT_GREY);
        tft.drawLine(LNDG_VV_X + LNDG_VV_W - 1 - tickLen,   ty,
                     LNDG_VV_X + LNDG_VV_W - 2,             ty, TFT_LIGHT_GREY);
    };
    for (uint16_t v = 0; v <= 15; v += 5) vvTick(v, 8);
    for (uint16_t v = 1; v <= 14; v++)
        if (v % 5 != 0) vvTick(v, 4);

    tft.drawRect(LNDG_VV_X, LNDG_VV_Y, LNDG_VV_W, LNDG_VV_H, TFT_GREY);

    // Numeric labels every 5 m/s, right-aligned
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    for (uint16_t v = 0; v <= 15; v += 5) {
        char buf[4]; snprintf(buf, sizeof(buf), "%u", v);
        uint16_t lw = strlen(buf) * 7;
        uint16_t ty = LNDG_VV_BOT - (uint16_t)(v * LNDG_VV_PPM);
        uint16_t ly = (uint16_t)max((int)LNDG_VV_Y, min((int)(SCREEN_H - 14), (int)ty - 7));
        tft.setCursor(LNDG_VV_LBRT - lw, ly);
        tft.print(buf);
    }

    // "VERTICAL VELOCITY" vertical label — full-height box so it is vertically
    // centred on the bar, left of the numeric labels.
    drawVerticalText(tft, LNDG_VV_X - 34, LNDG_VV_Y, 14, LNDG_VV_H,
                     &Roboto_Black_12, "VERTICAL VELOCITY", TFT_LIGHT_GREY, TFT_BLACK);
}


static void _lndgDrawVv(KCM_TFT &tft) {
    float vv     = constrain(-state.verticalVel, 0.0f, LNDG_VV_MAX);
    uint16_t fillH = (uint16_t)(vv * LNDG_VV_PPM);
    uint16_t fillY = LNDG_VV_BOT - fillH;

    if (fabsf(vv - _lndgPrevVV) < 0.1f) return;
    _lndgPrevVV = vv;

    uint16_t tx = LNDG_VV_X + 1, tw = LNDG_VV_W - 2;

    // Full repaint: dim zones
    tft.fillRect(tx, LNDG_VV_Y + 1,   tw, LNDG_VV_Y8 - LNDG_VV_Y - 1,  TFT_DARK_RED);
    tft.fillRect(tx, LNDG_VV_Y8,       tw, LNDG_VV_Y5 - LNDG_VV_Y8,      TFT_OLIVE);
    tft.fillRect(tx, LNDG_VV_Y5,       tw, LNDG_VV_BOT - LNDG_VV_Y5 - 1, TFT_JUNGLE);

    // Bright fill zone-split from bottom up
    if (fillH > 0) {
        auto seg = [&](uint16_t top, uint16_t bot, uint16_t col) {
            top = (uint16_t)max((int)fillY,                (int)top);
            bot = (uint16_t)min((int)(LNDG_VV_BOT - 1),   (int)bot);
            if (top < bot) tft.fillRect(tx, top, tw, bot - top, col);
        };
        seg(LNDG_VV_Y + 1, LNDG_VV_Y8, TFT_RED);
        seg(LNDG_VV_Y8,    LNDG_VV_Y5, TFT_YELLOW);
        seg(LNDG_VV_Y5,    LNDG_VV_BOT, TFT_NEON_GREEN);
    }

    // Zone-aware ticks
    auto vvTick = [&](uint16_t vMs, uint8_t tickLen) {
        uint16_t ty  = LNDG_VV_BOT - (uint16_t)(vMs * LNDG_VV_PPM);
        uint16_t col = (ty >= fillY) ? TFT_DARK_GREY : TFT_LIGHT_GREY;
        tft.drawLine(LNDG_VV_X + 1,                         ty,
                     LNDG_VV_X + tickLen,                    ty, col);
        tft.drawLine(LNDG_VV_X + LNDG_VV_W - 1 - tickLen,   ty,
                     LNDG_VV_X + LNDG_VV_W - 2,             ty, col);
    };
    for (uint16_t v = 0; v <= 15; v += 5) vvTick(v, 8);
    for (uint16_t v = 1; v <= 14; v++)
        if (v % 5 != 0) vvTick(v, 4);

    // 3px white marker
    if (fillH > 0 && fillY > LNDG_VV_Y && fillY < LNDG_VV_BOT)
        tft.fillRect(LNDG_VV_X, fillY, LNDG_VV_W, 3, TFT_WHITE);

    tft.drawRect(LNDG_VV_X, LNDG_VV_Y, LNDG_VV_W, LNDG_VV_H, TFT_GREY);
}



/***************************************************************************************
   CHROME: POWERED DESCENT
****************************************************************************************/
static void _lndgChromePowered(KCM_TFT &tft) {

    // Select the tape regime from the current altitude BEFORE painting the tape
    // chrome, otherwise the background is drawn with the stale mode left over from
    // the previous screen visit while the per-frame strip update uses the correct
    // one — producing a mixed normal/low-alt colour scheme on the tape.
    _lndgLowAltMode = (state.radarAlt < 50.0f);

    // ── Altitude tape chrome ──
    _lndgDrawTapeChrome(tft, _lndgLowAltMode);

    tft.fillRect(LNDG_XP_X, LNDG_XP_Y, LNDG_XP_SIDE, LNDG_XP_SIDE, LNDG_XP_BG);
    _lndgDrawXpChrome(tft);
    tft.drawRect(LNDG_XP_X, LNDG_XP_Y, LNDG_XP_SIDE, LNDG_XP_SIDE, TFT_GREY);


    // ── Perimeter tick marks and labels outside XP boundary ──
    // Left edge  = Fwd/Aft axis (positive = forward = up)
    // Bottom edge = Lateral axis (positive = right)
    // Major ticks every 5 m/s (5px), minor every 1 m/s (2px)
    // Numeric labels every 5 m/s; axis name labels on both axes
    {
        static const uint8_t  MAJ = 5, MIN = 2;
        static const uint16_t COL = TFT_LIGHT_GREY;
        uint16_t botY = LNDG_XP_Y + LNDG_XP_SIDE;

        // ── FWD / AFT axis name labels — vertical strips on left ──
        // x=80..94: 10px gap from tape right (70), 4px gap to numeric labels (x=98)
        // FWD: top-aligned with XP top edge
        // AFT: bottom-aligned with XP bottom edge
        drawVerticalText(tft, LNDG_XP_X - 48, LNDG_XP_Y,   14, 42,
                         &Roboto_Black_12, "FWD", TFT_LIGHT_GREY, TFT_BLACK);
        drawVerticalText(tft, LNDG_XP_X - 48, botY - 42,   14, 42,
                         &Roboto_Black_12, "AFT", TFT_LIGHT_GREY, TFT_BLACK);

        // ── LATERAL axis label + L/R — all on the same row below bottom axis ──
        // L: left-aligned with XP left edge
        // LATERAL: centred on XP
        // R: right-aligned with XP right edge
        tft.setFont(Roboto_Black_12);
        tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
        tft.setCursor(LNDG_XP_X, botY + 24);                            tft.print("L");
        tft.setCursor(LNDG_XP_CX - 24, botY + 24);                      tft.print("LATERAL");
        tft.setCursor(LNDG_XP_X + LNDG_XP_SIDE - 7, botY + 24);        tft.print("R");

        for (int8_t v = -15; v <= 15; v++) {
            if (v == 0) continue;
            bool isMajor = (v % 5 == 0);
            uint8_t tlen = isMajor ? MAJ : MIN;

            // Left edge tick (fwd/aft): positive v = up
            int16_t ty = (int16_t)(LNDG_XP_CY - v * LNDG_XP_SCALE);
            if (ty >= LNDG_XP_Y && ty <= botY) {
                tft.drawLine(LNDG_XP_X - 1,       ty,
                             LNDG_XP_X - 1 - tlen, ty, COL);
            }

            // Bottom edge tick (lat): positive v = right
            int16_t tx = (int16_t)(LNDG_XP_CX + v * LNDG_XP_SCALE);
            if (tx >= LNDG_XP_X && tx <= LNDG_XP_X + LNDG_XP_SIDE) {
                tft.drawLine(tx, botY + 1,
                             tx, botY + 1 + tlen, COL);
            }

            // Numeric labels every 5 m/s
            if (isMajor) {
                char buf[4];
                snprintf(buf, sizeof(buf), "%d", abs(v));
                uint8_t  nch = strlen(buf);
                uint16_t lw  = nch * 7;

                // Left axis: right-aligned, leaving room for vertical axis label strip
                uint16_t lx = LNDG_XP_X - 8 - lw;
                uint16_t ly = (uint16_t)max((int16_t)LNDG_XP_Y, (int16_t)(ty - 7));
                tft.setFont(Roboto_Black_12);
                tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
                tft.setCursor(lx, ly);
                tft.print(buf);

                // Bottom axis: centred on tick
                uint16_t blx = (uint16_t)max(0, (int)(tx - (int)(lw / 2)));
                tft.setCursor(blx, botY + 8);
                tft.print(buf);
            }
        }

        // Zero tick + label on left axis
        tft.drawLine(LNDG_XP_X - 1, LNDG_XP_CY,
                     LNDG_XP_X - 1 - MAJ, LNDG_XP_CY, COL);
        tft.setFont(Roboto_Black_12);
        tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
        tft.setCursor(LNDG_XP_X - 8 - 7, LNDG_XP_CY - 7);
        tft.print("0");

        // Zero tick + label on bottom axis
        tft.drawLine(LNDG_XP_CX, botY + 1,
                     LNDG_XP_CX, botY + 1 + MAJ, COL);
        tft.setCursor(LNDG_XP_CX - 3, botY + 8);
        tft.print("0");
    }

    // ── Instrument title labels ──
    // "SURF DRIFT" — horizontal, centred above the XP field
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LNDG_XP_CX - 35, LNDG_XP_Y - 18);
    tft.print("SURF DRIFT");

    // ── Right panel chrome ──
    // 8 rows: full-width rows use Roboto_Black_28 labels / Roboto_Black_36 values
    // (reticle tier); split rows (Fwd/Lat/Thrtl) stay at Roboto_Black_20 labels.
    // x=360..720, y=TITLE_TOP..SCREEN_H
    {
        static const tFont   *RCF  = &Roboto_Black_28;  // full-width row labels — reticle tier
        static const tFont   *RCFS = &Roboto_Black_20;  // split-row labels (Fwd/Lat/Thrtl) stay one tier smaller
        static const uint16_t RX  = LNDG_TEXT_X;
        static const uint16_t RW  = CONTENT_W - RX;           // 360px
        static const uint8_t  RNR = 8;
        static const uint16_t RHW = RW / 2;                   // 180px — half width for split rows

        printDispChrome(tft, RCF, RX, rowYFor(0,RNR), RW,  rowHFor(RNR), "V.VRT",   COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, RCF, RX, rowYFor(1,RNR), RW,  rowHFor(RNR), "T+GRND",  COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, RCF, RX, rowYFor(2,RNR), RW,  rowHFor(RNR), "ALT.RDR", COL_LABEL, COL_BACK, COL_NO_BDR);
        // Stg.Brn, not V.Srf. V.Srf carried no information on this screen: the panel
        // already shows V.Vrt, and Fwd and Lat are the two components of the horizontal
        // speed, which is itself sqrt(V.Srf^2 - V.Vrt^2) -- so V.Srf was fully determined
        // by three numbers sitting beside it, and duplicated on SPACECRAFT besides.
        // Seconds of thrust left is the number a powered descent actually turns on, it
        // has no picture on either panel, and it is the same field and label ASCENT and
        // CIRCULARISATION already use.
        printDispChrome(tft, RCF, RX, rowYFor(3,RNR), RW,  rowHFor(RNR), "STG.BRN", COL_LABEL, COL_BACK, COL_NO_BDR);

        // Row 4: Fwd | Lat split
        {
            uint16_t y = rowYFor(4, RNR), h = rowHFor(RNR);
            printDispChrome(tft, RCFS, RX,        y, RHW - ROW_PAD, h, "FWD", COL_LABEL, COL_BACK, COL_NO_BDR);
            printDispChrome(tft, RCFS, RX + RHW,  y, RHW - ROW_PAD, h, "LAT", COL_LABEL, COL_BACK, COL_NO_BDR);
            tft.drawLine(RX + RHW,     y, RX + RHW,     rowYFor(5,RNR) - 1, TFT_GREY);
            tft.drawLine(RX + RHW + 1, y, RX + RHW + 1, rowYFor(5,RNR) - 1, TFT_GREY);
        }

        printDispChrome(tft, RCF, RX, rowYFor(5,RNR), RW, rowHFor(RNR), "\xCE\x94V.STG", COL_LABEL, COL_BACK, COL_NO_BDR);

        // Divider before VEH section
        uint16_t divY = rowYFor(6, RNR) - 1;
        // (VEH section horizontal divider kept, label omitted — sits in graphical area)
        tft.drawLine(LNDG_DIV_X, divY,   CONTENT_W, divY,   TFT_GREY);
        tft.drawLine(LNDG_DIV_X, divY+1, CONTENT_W, divY+1, TFT_GREY);

        // ── All 2px borders ──
        // VERTICAL: graphical | text section divider (full height)
        tft.drawLine(LNDG_DIV_X,     TITLE_TOP, LNDG_DIV_X,     SCREEN_H - 1, TFT_GREY);
        tft.drawLine(LNDG_DIV_X + 1, TITLE_TOP, LNDG_DIV_X + 1, SCREEN_H - 1, TFT_GREY);

        // Horizontal borders drawn in draw function (after value updates) to avoid being overwritten

        // Row 6: Throttle | RCS split — throttle keeps label, RCS is a button
        {
            uint16_t y = rowYFor(6, RNR), h = rowHFor(RNR);
            printDispChrome(tft, RCFS, RX, y, RHW - ROW_PAD, h, "THRTL", COL_LABEL, COL_BACK, COL_NO_BDR);
            tft.drawLine(RX + RHW,     y, RX + RHW,     rowYFor(7,RNR) - 1, TFT_GREY);
            tft.drawLine(RX + RHW + 1, y, RX + RHW + 1, rowYFor(7,RNR) - 1, TFT_GREY);
        }

        // Row 7: Gear | SAS split — both are buttons, no chrome labels needed
        {
            uint16_t y = rowYFor(7, RNR);
            tft.drawLine(RX + RHW,     y, RX + RHW,     SCREEN_H - 1, TFT_GREY);
            tft.drawLine(RX + RHW + 1, y, RX + RHW + 1, SCREEN_H - 1, TFT_GREY);
        }
    }

    // Attitude bullseye
    _lndgDrawAttChrome(tft);

    // Ground-track compass
    _lndgDrawTrkChrome(tft);

    // Redraw LATERAL row labels — bullseye fillCircle may overdraw them
    {
        uint16_t botY = LNDG_XP_Y + LNDG_XP_SIDE;
        tft.setFont(Roboto_Black_12);
        tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
        tft.setCursor(LNDG_XP_X,                           botY + 24); tft.print("L");
        tft.setCursor(LNDG_XP_CX - 24,                     botY + 24); tft.print("LATERAL");
        tft.setCursor(LNDG_XP_X + LNDG_XP_SIDE - 7,        botY + 24); tft.print("R");
    }

    // V.Vrt bar
    _lndgDrawVvChrome(tft);

    // Reset dirty flags — use SCREEN_H+1 as sentinel (invalid y, forces full first draw)
    _lndgPrevLatX   = -999;
    _lndgPrevFwdY   = -999;
    _lndgPrevAlt    = (float)(SCREEN_H + 1);
    _lndgPrevAttX   = -999;
    _lndgPrevAttY   = -999;
    _lndgPrevVV     = -9999.0f;
    // _lndgLowAltMode is set at the top of this function (before the tape chrome
    // is painted) so the initial background matches the per-frame strip regime.
    // (The right-panel row cache is invalidated by drawStaticScreen() after this chrome.)
}

/***************************************************************************************
   DRAW: POWERED DESCENT
****************************************************************************************/
static void _lndgDrawPowered(KCM_TFT &tft) {

    // Advance the shared vertical-accel filter exactly once per frame, before any
    // estimate*() read below (both the X-Pointer colour and the panel use tGround).
    ttgAdvanceAccel();

    // Regime-aware time-to-ground (Keplerian coast / thrust+drag kinematic / naive)
    float tGround = estimateTimeToGround();
    float vSq  = state.surfaceVel * state.surfaceVel - state.verticalVel * state.verticalVel;
    float hSpd = (vSq > 0.0f) ? sqrtf(vSq) : 0.0f;

    float headRad    = (state.heading + state.roll) * DEG_TO_RAD;
    float svelHdgRad = state.srfVelHeading * DEG_TO_RAD;
    float dHeadRad   = svelHdgRad - headRad;
    float vFwd = -hSpd * cosf(dHeadRad);
    float vLat = -hSpd * sinf(dHeadRad);
    if (fabsf(vFwd) < 0.05f) vFwd = 0.0f;
    if (fabsf(vLat) < 0.05f) vLat = 0.0f;

    // ── X-Pointer needles ──
    float latClamped = constrain(vLat, -15.0f, 15.0f);
    float fwdClamped = constrain(vFwd, -15.0f, 15.0f);
    int16_t latX = (int16_t)(LNDG_XP_CX + latClamped * LNDG_XP_SCALE);
    int16_t fwdY = (int16_t)(LNDG_XP_CY - fwdClamped * LNDG_XP_SCALE);
    // Keep the needle intersection at least 8px inside the field so the connecting
    // bars still draw, and the arrowhead/erase boxes (±7px) never spill past the edge.
    latX = constrain(latX, (int16_t)(LNDG_XP_X + 8), (int16_t)(LNDG_XP_X + LNDG_XP_SIDE - 8));
    fwdY = constrain(fwdY, (int16_t)(LNDG_XP_Y + 8), (int16_t)(LNDG_XP_Y + LNDG_XP_SIDE - 8));

    // Needle colour: dark green=safe, yellow=warn, red=alarm
    float driftMag = sqrtf(vLat * vLat + vFwd * vFwd) / 1.414f;
    uint16_t needleFg, needleBg;
    _lndgHorzColor(driftMag, tGround, needleFg, needleBg);
    uint16_t needleCol = (needleBg == TFT_RED) ? TFT_RED :
                         (needleFg == TFT_YELLOW) ? TFT_YELLOW : TFT_DARK_GREEN;

    if (latX != _lndgPrevLatX || fwdY != _lndgPrevFwdY) {
        // Erase old needles — 3px wide lines + arrowhead bounding boxes + circle
        if (_lndgPrevLatX >= 0) {
            tft.fillRect(_lndgPrevLatX - 1, LNDG_XP_Y + 1,
                         3, LNDG_XP_SIDE - 2, LNDG_XP_BG);
            tft.fillRect(_lndgPrevLatX - 6, LNDG_XP_Y + 1,
                         13, 18, LNDG_XP_BG);
            tft.fillRect(_lndgPrevLatX - 6, LNDG_XP_Y + LNDG_XP_SIDE - 18,
                         13, 18, LNDG_XP_BG);
        }
        if (_lndgPrevFwdY >= 0) {
            tft.fillRect(LNDG_XP_X + 1, _lndgPrevFwdY - 1,
                         LNDG_XP_SIDE - 2, 3, LNDG_XP_BG);
            tft.fillRect(LNDG_XP_X + 1,              _lndgPrevFwdY - 6,
                         18, 13, LNDG_XP_BG);
            tft.fillRect(LNDG_XP_X + LNDG_XP_SIDE - 18, _lndgPrevFwdY - 6,
                         18, 13, LNDG_XP_BG);
        }
        // Erase old intersection circle (15×15 box)
        if (_lndgPrevLatX >= 0 && _lndgPrevFwdY >= 0) {
            tft.fillRect(_lndgPrevLatX - 7, _lndgPrevFwdY - 7,
                         15, 15, LNDG_XP_BG);
        }

        // Restore chrome elements erased above
        _lndgDrawXpChrome(tft);

        // Draw new needles — 3px thick, clamped 2px inside border
        uint16_t nx1 = LNDG_XP_X + 2, nx2 = LNDG_XP_X + LNDG_XP_SIDE - 2;
        uint16_t ny1 = LNDG_XP_Y + 2, ny2 = LNDG_XP_Y + LNDG_XP_SIDE - 2;
        for (int8_t d = -1; d <= 1; d++) {
            int16_t lx = latX + d;
            if (lx >= (int16_t)nx1 && lx <= (int16_t)nx2)
                tft.drawLine(lx, ny1, lx, ny2, needleCol);
            int16_t fy = fwdY + d;
            if (fy >= (int16_t)ny1 && fy <= (int16_t)ny2)
                tft.drawLine(nx1, fy, nx2, fy, needleCol);
        }

        // Redraw the border FIRST (cleans up where the bars touched it) so the
        // arrowheads and intersection circle below always render on top of it.
        tft.drawRect(LNDG_XP_X, LNDG_XP_Y, LNDG_XP_SIDE, LNDG_XP_SIDE, TFT_GREY);

        // Arrowheads — lateral needle (top + bottom)
        tft.fillTriangle(latX,     LNDG_XP_Y + 4,
                         latX - 6, LNDG_XP_Y + 16,
                         latX + 6, LNDG_XP_Y + 16, needleCol);
        tft.fillTriangle(latX,     LNDG_XP_Y + LNDG_XP_SIDE - 4,
                         latX - 6, LNDG_XP_Y + LNDG_XP_SIDE - 16,
                         latX + 6, LNDG_XP_Y + LNDG_XP_SIDE - 16, needleCol);
        // Arrowheads — fwd needle (left + right)
        tft.fillTriangle(LNDG_XP_X + 4,              fwdY,
                         LNDG_XP_X + 16,             fwdY - 6,
                         LNDG_XP_X + 16,             fwdY + 6, needleCol);
        tft.fillTriangle(LNDG_XP_X + LNDG_XP_SIDE - 4,  fwdY,
                         LNDG_XP_X + LNDG_XP_SIDE - 16, fwdY - 6,
                         LNDG_XP_X + LNDG_XP_SIDE - 16, fwdY + 6, needleCol);

        // Intersection circle at needle crossing — solid fill, white centre dot
        tft.fillCircle(latX, fwdY, 7, needleCol);
        tft.fillCircle(latX, fwdY, 3, TFT_WHITE);

        // Centre reference dot always on top
        tft.fillCircle(LNDG_XP_CX, LNDG_XP_CY, 5, TFT_BLACK);
        tft.fillCircle(LNDG_XP_CX, LNDG_XP_CY, 2, TFT_DARK_GREY);

        _lndgPrevLatX = latX;
        _lndgPrevFwdY = fwdY;
    }


    // ── Altitude tape — incremental strip update ──
    // Detect low-alt mode transition (hysteresis: enter <50m, exit >55m)
    float rawAlt = state.radarAlt;
    bool wantLow = _lndgLowAltMode ? (rawAlt < 55.0f) : (rawAlt < 50.0f);
    if (wantLow != _lndgLowAltMode) {
        _lndgLowAltMode = wantLow;
        _lndgPrevAlt    = (float)(SCREEN_H + 1);  // force full redraw
        _lndgDrawTapeChrome(tft, _lndgLowAltMode);
    }

    bool   lowAlt = _lndgLowAltMode;
    float  ppm    = lowAlt ? LNDG_TAPE_PPM_LOW : LNDG_TAPE_PPM;
    float  alt    = constrain(rawAlt, 0.0f, lowAlt ? 50.0f : 500.0f);
    uint16_t newFillY = SCREEN_H - (uint16_t)(alt * ppm);

    if (newFillY != (uint16_t)_lndgPrevAlt) {
        uint16_t prevFillY = (uint16_t)_lndgPrevAlt;
        uint16_t tx = LNDG_TAPE_X + 1, tw = LNDG_TAPE_W - 2;
        static const uint8_t MRK = 5;

        uint16_t stripTop = min(newFillY, prevFillY);
        uint16_t stripBot = max(newFillY, prevFillY) + MRK;
        stripTop = max(stripTop, (uint16_t)(LNDG_TAPE_Y + 1));
        stripBot = min(stripBot, (uint16_t)(SCREEN_H - 1));

        if (lowAlt) {
            // Low-alt: dark grey = unlit (above marker), light grey = lit (below marker)
            uint16_t dimTop = stripTop;
            uint16_t dimBot = min(newFillY, stripBot);
            uint16_t litTop = max(newFillY, stripTop);
            uint16_t litBot = stripBot;
            if (dimTop < dimBot) tft.fillRect(tx, dimTop, tw, dimBot - dimTop, TFT_DARK_GREY);
            if (litTop < litBot) tft.fillRect(tx, litTop, tw, litBot - litTop, TFT_LIGHT_GREY);

            // Ticks — light grey in dim (upper) zone, dark grey in lit (lower) zone
            auto tapeTick = [&](uint16_t altM, uint8_t tickLen) {
                uint16_t ty = SCREEN_H - (uint16_t)(altM * ppm);
                if (ty < stripTop || ty > stripBot) return;
                uint16_t col = (ty < newFillY) ? TFT_LIGHT_GREY : TFT_DARK_GREY;
                tft.drawLine(LNDG_TAPE_X + 1,                         ty,
                             LNDG_TAPE_X + tickLen,                    ty, col);
                tft.drawLine(LNDG_TAPE_X + LNDG_TAPE_W - 1 - tickLen, ty,
                             LNDG_TAPE_X + LNDG_TAPE_W - 2,            ty, col);
            };
            for (uint16_t m = 10; m <= 50; m += 10) tapeTick(m, 8);
            for (uint16_t m =  5; m <= 45; m += 10) tapeTick(m, 4);

        } else {
            // Normal mode: three-zone dim/bright split
            uint16_t y200 = SCREEN_H - (uint16_t)(200.0f * ppm);
            uint16_t y50  = SCREEN_H - (uint16_t)( 50.0f * ppm);

            auto zoneCol = [&](uint16_t y, bool bright) -> uint16_t {
                if (bright) return (y < y200) ? TFT_NEON_GREEN : (y < y50) ? TFT_YELLOW : TFT_RED;
                else        return (y < y200) ? TFT_JUNGLE      : (y < y50) ? TFT_OLIVE  : TFT_DARK_RED;
            };

            uint16_t boundaries[] = {stripTop, y200, y50, stripBot};
            for (int i = 0; i < 3; i++) {
                uint16_t segTop = max(boundaries[i],   stripTop);
                uint16_t segBot = min(boundaries[i+1], stripBot);
                if (segTop >= segBot) continue;
                bool segBright = (segTop >= newFillY);
                tft.fillRect(tx, segTop, tw, segBot - segTop, zoneCol(segTop, segBright));
            }

            auto tapeTick = [&](uint16_t altM, uint8_t tickLen) {
                uint16_t ty = SCREEN_H - (uint16_t)(altM * ppm);
                if (ty < stripTop || ty > stripBot) return;
                uint16_t col = (ty < newFillY) ? TFT_LIGHT_GREY : TFT_DARK_GREY;
                tft.drawLine(LNDG_TAPE_X + 1,                         ty,
                             LNDG_TAPE_X + tickLen,                    ty, col);
                tft.drawLine(LNDG_TAPE_X + LNDG_TAPE_W - 1 - tickLen, ty,
                             LNDG_TAPE_X + LNDG_TAPE_W - 2,            ty, col);
            };
            for (uint16_t m = 100; m <= 500; m += 100) tapeTick(m, 8);
            for (uint16_t m =  25; m <= 475; m +=  25)
                if (m % 100 != 0) tapeTick(m, 4);
        }

        // Marker: 5px bar, inside borders
        // Low-alt: RED marker  Normal: WHITE marker
        uint16_t mrkCol = lowAlt ? TFT_RED : TFT_WHITE;
        tft.fillRect(LNDG_TAPE_X + 1, newFillY, LNDG_TAPE_W - 2, MRK, mrkCol);

        _lndgPrevAlt = (float)newFillY;
    }

    // Attitude bullseye + ground-track compass + V.Vrt bar
    _lndgDrawAtt(tft);
    _lndgDrawTrk(tft);
    _lndgDrawVv(tft);

    // ── Right panel values ──
    {
        static const tFont   *RF  = &Roboto_Black_36;   // full-width value font — reticle tier, matches the re-entry panel (both LNDG modes)
        static const uint16_t RX  = LNDG_TEXT_X;
        static const uint16_t RW  = CONTENT_W - RX;
        static const uint8_t  RNR = 8;
        static const uint16_t RHW = RW / 2;

        // The frame's time-to-ground and drift components (computed once at the top
        // of this function) are reused, so the panel values and the X-Pointer agree
        // and the shared accel filter is advanced only once per frame.

        uint16_t fg, bg;
        char buf[16];

        // Helper: draw a right-panel value with row-cache
        auto rpVal = [&](uint8_t row, const char *label, const String &val,
                         uint16_t fgc, uint16_t bgc, uint8_t cacheIdx) {
            drawPanelValue(tft, LNDG_SC, cacheIdx, row, RX, RW, label, val, fgc, bgc, RF, RNR, false);
        };

        // Row 0: V.Vrt
        {
            fg = (state.verticalVel < LNDG_VVRT_ALARM_MS) ? TFT_WHITE  :
                 (state.verticalVel < LNDG_VVRT_WARN_MS)  ? TFT_YELLOW : TFT_DARK_GREEN;
            bg = (state.verticalVel < LNDG_VVRT_ALARM_MS) ? TFT_RED    : TFT_BLACK;
            rpVal(0, "V.VRT", fmtMs(state.verticalVel), fg, bg, 0);
        }

        // Row 1: T.Grnd — colours via the shared hysteresis helper (anti-flicker)
        {
            lndgTGroundColors(tGround, fg, bg);
            if (tGround >= 0.0f) rpVal(1, "T+GRND", formatTimeCompact(tGround), fg, bg, 1);
            else                 rpVal(1, "T+GRND", "---", fg, bg, 1);
        }

        // Row 2: Alt.Rdr
        {
            fg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_WHITE  :
                 (state.radarAlt < LNDG_ALT_RDR_WARN_M) ? TFT_YELLOW : TFT_DARK_GREEN;
            bg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_RED    : TFT_BLACK;
            rpVal(2, "ALT.RDR", formatAlt(state.radarAlt), fg, bg, 2);
        }

        // Row 3: Stg.Brn — same thresholds as ASCENT's, so a burn-time warning means
        // the same thing on the way up and on the way down.
        {
            uint16_t sfg, sbg;
            thresholdColor(state.stageBurnTime,
                           LNCH_BURNTIME_ALARM_S, TFT_WHITE,  TFT_RED,
                           LNCH_BURNTIME_WARN_S,  TFT_YELLOW, TFT_BLACK,
                           TFT_DARK_GREEN, TFT_BLACK, sfg, sbg);
            rpVal(3, "STG.BRN", formatTimeCompact(state.stageBurnTime), sfg, sbg, 3);
        }

        // Row 4: Fwd | Lat (split)
        {
            uint16_t ffg, fbg, lfg, lbg;
            _lndgHorzColor(vFwd, tGround, ffg, fbg);
            _lndgHorzColor(vLat, tGround, lfg, lbg);
            uint16_t y = rowYFor(4,RNR), h = rowHFor(RNR);
            // Always show sign. One decimal for |v|<10, integer for |v|>=10.
            // Roboto_Black_24 used for value font — fits "+99.9 m/s" in split column.
            static const tFont *RFS = &Roboto_Black_24;
            // Clamp to ±99.9 m/s so fmtMs always fits in the split column
            float vFwdC = constrain(vFwd, -99.9f, 99.9f);
            float vLatC = constrain(vLat, -99.9f, 99.9f);
            {
                String fs = fmtMs(vFwdC);
                RowCache &fc = rowCache[LNDG_SC][4];
                if (fc.value != fs || fc.fg != ffg || fc.bg != fbg) {
                    printValue(tft, RFS, RX, y, RHW-ROW_PAD, h, "FWD", fs, ffg, fbg, COL_BACK, printState[LNDG_SC][4]);
                    fc.value = fs; fc.fg = ffg; fc.bg = fbg;
                }
            }
            {
                String ls = fmtMs(vLatC);
                RowCache &lc = rowCache[LNDG_SC][5];
                if (lc.value != ls || lc.fg != lfg || lc.bg != lbg) {
                    printValue(tft, RFS, RX+RHW, y, RHW-ROW_PAD, h, "LAT", ls, lfg, lbg, COL_BACK, printState[LNDG_SC][5]);
                    lc.value = ls; lc.fg = lfg; lc.bg = lbg;
                }
            }
        }

        // Row 5: ΔV.Stg (low-stage-fuel warning, matches VEH/LNCH)
        {
            uint16_t sfg, sbg;
            thresholdColor(state.stageDeltaV,
                           DV_STG_ALARM_MS, TFT_WHITE,  TFT_RED,
                           DV_STG_WARN_MS,  TFT_YELLOW, TFT_BLACK,
                           TFT_DARK_GREEN, TFT_BLACK, sfg, sbg);
            rpVal(5, "\xCE\x94V.STG", fmtMs(state.stageDeltaV), sfg, sbg, 6);
        }

        // Row 6: Throttle | RCS (split)
        {
            snprintf(buf, sizeof(buf), "%.0f%%", state.throttle * 100.0f);
            uint16_t y = rowYFor(6,RNR), h = rowHFor(RNR);
            {
                String ts = buf;
                RowCache &tc = rowCache[LNDG_SC][7];
                if (tc.value != ts) {
                    // Thrtl stays at 28 — it shares a half-cell with the RCS button, too tight for 32.
                    printValue(tft, &Roboto_Black_28, RX, y, RHW-ROW_PAD, h, "THRTL", ts, TFT_DARK_GREEN, TFT_BLACK, COL_BACK, printState[LNDG_SC][7]);
                    tc.value = ts; tc.fg = TFT_DARK_GREEN; tc.bg = TFT_BLACK;
                }
            }
            // RCS button
            {
                bool rcsOn = state.rcs_on;
                String rv = rcsOn ? "ON" : "OFF";
                RowCache &rc2 = rowCache[LNDG_SC][8];
                if (rc2.value != rv) {
                    ButtonLabel btn = rcsOn
                        ? ButtonLabel{ "RCS", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
                        : ButtonLabel{ "RCS", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
                    drawButton(tft, RX + RHW, y, RHW, h, btn, &Roboto_Black_28, false);
                    rc2.value = rv;
                }
            }
        }

        // Row 7: Gear | SAS (split) — both as buttons, extend to screen bottom
        {
            uint16_t y  = rowYFor(7,RNR);
            uint16_t rh = SCREEN_H - y;
            // Gear button
            {
                bool gearDown = state.gear_on;
                String gv = gearDown ? "DOWN" : "UP";
                RowCache &gc = rowCache[LNDG_SC][9];
                if (gc.value != gv) {
                    ButtonLabel btn = gearDown
                        ? ButtonLabel{ "GEAR", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
                        : ButtonLabel{ "GEAR", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
                    drawButton(tft, RX - 2, y, RHW + 2, rh, btn, &Roboto_Black_28, false);
                    gc.value = gv;
                }
            }
            // SAS button — landing context: STAB and RETR acceptable, others questionable
            {
                const char *sv; uint16_t sfg, sbg;
                switch (state.sasMode) {
                    case 255: sv = "SAS";  sfg = TFT_WHITE;     sbg = TFT_RED;        break; // off — alarm
                    case 0:   sv = "STAB"; sfg = TFT_WHITE;     sbg = TFT_DARK_GREEN; break; // good for landing
                    case 2:   sv = "RETR"; sfg = TFT_WHITE;     sbg = TFT_DARK_GREEN; break; // good for landing
                    default:  sv = "SAS";  sfg = TFT_DARK_GREY; sbg = TFT_OFF_BLACK;  break; // other — neutral
                }
                RowCache &sc = rowCache[LNDG_SC][10];
                String ssv = sv;
                if (sc.value != ssv || sc.fg != sfg || sc.bg != sbg) {
                    ButtonLabel btn = { sv, sfg, sfg, sbg, sbg, TFT_GREY, TFT_GREY };
                    drawButton(tft, RX + RHW, y, RHW, rh, btn, &Roboto_Black_28, false);
                    sc.value = ssv; sc.fg = sfg; sc.bg = sbg;
                }
            }
        }

        // Horizontal borders redrawn last — after all value updates so they're never overwritten
        // Alt.Rdr | Stg.Brn (rows 2→3)
        tft.drawLine(LNDG_DIV_X, rowYFor(3,RNR) - 2, CONTENT_W, rowYFor(3,RNR) - 2, TFT_GREY);
        tft.drawLine(LNDG_DIV_X, rowYFor(3,RNR) - 1, CONTENT_W, rowYFor(3,RNR) - 1, TFT_GREY);
        // Fwd/Lat | ΔV.Stg (rows 4→5)
        tft.drawLine(LNDG_DIV_X, rowYFor(5,RNR) - 2, CONTENT_W, rowYFor(5,RNR) - 2, TFT_GREY);
        tft.drawLine(LNDG_DIV_X, rowYFor(5,RNR) - 1, CONTENT_W, rowYFor(5,RNR) - 1, TFT_GREY);
        // ΔV.Stg | Thrtl/RCS (rows 5→6)
        tft.drawLine(LNDG_DIV_X, rowYFor(6,RNR) - 2, CONTENT_W, rowYFor(6,RNR) - 2, TFT_GREY);
        tft.drawLine(LNDG_DIV_X, rowYFor(6,RNR) - 1, CONTENT_W, rowYFor(6,RNR) - 1, TFT_GREY);
    }
}




/***************************************************************************************
   Screen_LNDG_Reentry.ino -- Re-entry mode (one of two modes of the LNDG screen).

   rev-2 Phase-2 redesign: RE-ENTRY is now a graphical instrument screen, a sibling of
   POWERED DESCENT. The left/centre zone carries the graphics; a condensed text board
   fills the right ~360px panel.

   Widgets (left/centre graphics zone, x < RE_DIV_X):
     Left cluster (three vertical bars):
     - Corridor tape      : full-height altitude tape whose coloured zones are the
                            re-entry corridor (NO RE-ENTRY / AEROBRAKE / SAFE / DANGER)
                            with the current altitude and periapsis markers. Zone
                            boundaries are anchored on the body table (flyHigh /
                            reentryAlt / lowSpace) and shift up with entry velocity.
     - ATMOSPHERE bar     : atmospheric density fraction (matches the ascent screen).
     - G meter            : zone-background load gauge with a numbered axis.
     Right cluster (centred, sized as large as the space allows):
     - Alignment ball     : heat-shield / retrograde alignment. Plots the surface
                            retrograde vector relative to the nose (boresight); when
                            centred the shield is square into the airflow. AoA readout.
     - CHUTE DEPLOY       : horizontal airspeed bar with live safe-deploy limits.
     - Skin / core temp   : two horizontal bars beneath the chute bar.

   Text panel (right, x >= RE_TXT_X): T+Grnd/T+Atm, Alt, V.Srf, PeA, Mach, V.Vrt, and the
   chute / gear / SAS status board. (G load is shown by the graphical G meter.)

   The graphics widgets are fully repainted every frame (the hardware double buffer
   BTE-copies the front page to the back each frame, so a full widget repaint simply
   overwrites the copy — no incremental erase bookkeeping needed). The text panel keeps
   the row-cache so values redraw only on change.

   Public-to-the-sketch entry points (called by the LNDG dispatcher):
     - _lndgChromeReentry(tft) — divider + static text-panel labels
     - _lndgDrawReentry(tft)   — per-frame widgets + panel values

   Re-entry row-toggle state (_lndgReentryRow0TPe, _lndgReentryRow1SL) and parachute
   deploy/cut state (_drogueDeployed etc.) are defined in Screen_LNDG.ino as externs.
****************************************************************************************/

/***************************************************************************************
   LAYOUT
****************************************************************************************/
static const uint16_t RE_DIV_X   = 578;                 // graphics | panel divider (standard 360px panel)
static const uint16_t RE_TXT_X   = 580;                 // text panel left edge (matches the other screens)
static const uint16_t RE_TXT_W   = CONTENT_W - RE_TXT_X;// 360

// ── Corridor tape (far left) ──
static const uint16_t RE_TAPE_X   = 44;
static const uint16_t RE_TAPE_W   = 35;   // ~80% of the original 44 to free horizontal room
static const uint16_t RE_TAPE_Y   = TITLE_TOP + 8;                  // 70
static const uint16_t RE_TAPE_H   = SCREEN_H - RE_TAPE_Y - 3;       // 527
static const uint16_t RE_TAPE_BOT = RE_TAPE_Y + RE_TAPE_H;         // 597
static const uint16_t RE_TAPE_GUT = 34;   // right-side marker gutter (erased each frame)
static const int16_t  RE_TAPE_M   = 8;    // marker half-height inset (= triangle half-height + 1);
                                          // the tape's VISIBLE rectangle is RE_TAPE_Y+M .. RE_TAPE_BOT-M

// ── ATMO density bar — matches the altitude tape's VISIBLE rectangle (same width and
//    same inset top/bottom) and sits just right of it, with a matching vertical label. ──
static const uint16_t RE_ATMO_LBL_X = 114;                          // vertical label column
static const uint16_t RE_ATMO_X   = 130;
static const uint16_t RE_ATMO_W   = RE_TAPE_W;                      // same width as the tape
static const uint16_t RE_ATMO_Y   = RE_TAPE_Y + RE_TAPE_M;          // 78  — same top as the tape's border
static const uint16_t RE_ATMO_BOT = RE_TAPE_BOT - RE_TAPE_M;        // 589 — same bottom as the tape's border
static const uint16_t RE_ATMO_H   = RE_ATMO_BOT - RE_ATMO_Y;

// ── G METER (left cluster — a third vertical bar just right of the ATMOSPHERE bar) ──
static const uint16_t RE_GA_Y   = RE_ATMO_Y;                // 78  — match the ATMO/altitude top
static const uint16_t RE_GA_H   = RE_ATMO_BOT - RE_GA_Y;    // 511 — match the ATMO height
static const uint16_t RE_GA_BOT = RE_GA_Y + RE_GA_H;        // 589
static const uint16_t RE_GF_X   = 218;  static const uint16_t RE_GF_W = 34;  // bar (left gutter carries axis numbers)
static const uint16_t RE_GLBL_X = RE_GF_X - 36;             // 182 — "G METER" vertical label column

// ── Right graphical cluster: alignment reticle (top) + CHUTE DEPLOY (mid) + TEMP
//    (bottom), all centred on RE_RCX and sized as large as the space allows. ──
static const int16_t  RE_RCX    = 428;                      // shared horizontal centre (nudged left for the 360px panel)

// Alignment ball
static const int16_t  RE_ATT_CX = RE_RCX;
static const int16_t  RE_ATT_CY = 212;
static const int16_t  RE_ATT_R  = 122;
static const float    RE_ATT_FS = (float)RE_ATT_R / 40.0f;  // px per degree (outer ring = 40°)

// Parachute deploy SPEED BAR (horizontal). The green/yellow/red zone boundaries are the
// altitude-corrected safe-deploy speeds derived from live dynamic pressure, so they
// slide left as you descend into denser air. Airspeed axis 0 (left) .. VMAX (right).
static const uint16_t RE_ENV_X    = 280;   // widget footprint (erased each frame)
static const uint16_t RE_ENV_Y    = 390;
static const uint16_t RE_ENV_W    = 296;
static const uint16_t RE_ENV_H    = 140;
static const uint16_t RE_CT_X     = 297;                // bar left edge
static const uint16_t RE_CT_W     = 262;                // bar width (airspeed axis)
static const uint16_t RE_CT_Y     = 436;                // bar top
static const uint16_t RE_CT_H     = 54;                 // bar height
static const uint16_t RE_CT_RIGHT = RE_CT_X + RE_CT_W;  // 559 — bar right edge
static const float    RE_CT_VMAX  = 1000.0f;            // airspeed axis max (m/s)

// Skin / core temperature — two horizontal bars beneath the chute bar.
static const uint16_t RE_TMP_LX = 282;                  // SKIN/CORE label column (right-aligned)
static const uint16_t RE_TMP_X  = 330;                  // bar left edge
static const uint16_t RE_TMP_W  = 229;                  // bar width -> right edge 559 (aligned with chute)
static const uint16_t RE_TMP_Y  = 552;                  // first (skin) bar top
static const uint16_t RE_TMP_BH = 18;                   // bar height
static const uint16_t RE_TMP_VS = 22;                   // row pitch (skin -> core)

/***************************************************************************************
   HELPERS
****************************************************************************************/

// ── Chute deployment (dynamic pressure) ──────────────────────────────────────────────
// Current dynamic pressure q = 0.5*rho*v^2 (Pa); 0 outside the atmosphere.
static inline float _reDynPressure() { return 0.5f * state.airDensity * state.surfaceVel * state.surfaceVel; }
// Altitude-corrected safe-deploy airspeed (m/s) for a chute with the given max q, at
// the current air density. Huge (effectively "any speed") in near-vacuum.
static inline float _reChuteSafeSpeed(float maxQ) {
  return (state.airDensity > 1e-6f) ? sqrtf(2.0f * maxQ / state.airDensity) : 1.0e6f;
}
// Deploy-safety tier for a chute: 0 = safe (green), 1 = caution (yellow), 2 = rip (red).
static inline uint8_t _reChuteTier(float maxQ) {
  float q = _reDynPressure();
  if (q >= maxQ)         return 2;
  if (q >= 0.85f * maxQ) return 1;
  return 0;
}

// Re-entry corridor boundaries (metres, ASL), velocity-adjusted. ReCorridor is
// declared in KCMk1_InfoDisp.h so the auto-prototype for this helper sees the type.
// Not static: the mission context ladder reuses this to decide when a re-entry is
// pending, so the rule and the screen agree on what counts as one by construction.
ReCorridor _reCorridor() {
  ReCorridor c; c.valid = false; c.dangerLine = c.safeTop = c.atmoTop = 0.0f;
  float atmoTop = currentBody.lowSpace;
  if (!currentBody.hasAtmo || atmoTop <= 0.0f) return c;
  float flyHigh    = currentBody.flyHigh;
  float reentryAlt = currentBody.reentryAlt;
  float escV       = currentBody.escapeVelocity;
  float vCirc      = (escV > 1.0f) ? escV / 1.41421356f : 1.0f;   // ~circular low-orbit speed
  float vFac       = constrain(state.surfaceVel / vCirc, 1.0f, 1.7f);
  c.dangerLine = flyHigh * vFac;
  c.safeTop    = min(reentryAlt * vFac, 0.92f * atmoTop);
  if (c.safeTop < c.dangerLine) c.safeTop = c.dangerLine;
  c.atmoTop = atmoTop;
  c.valid   = true;
  return c;
}

// Classify a periapsis (ASL) into a corridor regime: 0 danger, 1 safe, 2 aerobrake,
// 3 no-reentry, -1 n/a. Colours chosen to match the tape zones.
int8_t _rePeRegime(const ReCorridor &c, float pe) {
  if (!c.valid) return -1;
  if (pe >= c.atmoTop)    return 3;
  if (pe >= c.safeTop)    return 2;
  if (pe >= c.dangerLine) return 1;
  return 0;
}
static uint16_t _reRegimeColor(int8_t r) {
  switch (r) {
    case 3:  return TFT_LIGHT_GREY;   // no re-entry
    case 2:  return TFT_CYAN;         // aerobrake
    case 1:  return TFT_DARK_GREEN;   // safe
    case 0:  return TFT_RED;          // dangerous
    default: return TFT_DARK_GREY;
  }
}

// "Nice" label step (metres) for the tape scale — aims for ~5 labelled divisions.
static float _reNiceStep(float span) {
  float raw = span / 5.0f;
  static const float steps[] = { 5000, 10000, 20000, 25000, 50000, 100000, 200000, 500000 };
  for (uint8_t i = 0; i < 8; i++) if (steps[i] >= raw) return steps[i];
  return 500000.0f;
}

/***************************************************************************************
   WIDGET: CORRIDOR TAPE (altitude ladder + periapsis regime)
   Powered-descent tape style: km scale labels + ticks on the left, corridor zone
   fills in the bar, and the current-altitude (white) + periapsis (magenta) markers
   on the right. The whole footprint is repainted every frame so moving markers can't
   leave streaks.
****************************************************************************************/
static void _reDrawTape(KCM_TFT &tft) {
  ReCorridor c = _reCorridor();
  float atmoTop  = (c.valid ? c.atmoTop : (currentBody.lowSpace > 0 ? currentBody.lowSpace : 70000.0f));
  float scaleTop = atmoTop * 1.3f;
  if (scaleTop < 1.0f) scaleTop = 70000.0f;

  // The drawn bar is inset from the full footprint by the marker half-height so the
  // markers can reach the true 0 / scaleTop ends without their triangles overhanging
  // (no clamping — clamping would misreport the value at the extremes).
  const int16_t yTop = RE_TAPE_Y + RE_TAPE_M;
  const int16_t yBot = RE_TAPE_BOT - RE_TAPE_M;
  const int16_t usableH = yBot - yTop;
  auto altToY = [&](float alt) -> int16_t {
    float f = alt / scaleTop; if (f < 0) f = 0; if (f > 1) f = 1;
    return (int16_t)(yBot - f * usableH);
  };
  const uint16_t ix   = RE_TAPE_X + 1, iw = RE_TAPE_W - 2;
  const uint16_t barR = RE_TAPE_X + RE_TAPE_W;      // bar right edge (79)

  // Full-footprint erase (label gutter + bar + marker gutter) — kills streaks.
  tft.fillRect(14, RE_TAPE_Y, (barR + RE_TAPE_GUT) - 14, RE_TAPE_H + 2, TFT_BLACK);

  // Corridor zone fills (dim) inside the bar
  if (c.valid) {
    int16_t yDanger = altToY(c.dangerLine);
    int16_t ySafe   = altToY(c.safeTop);
    int16_t yAtmo   = altToY(c.atmoTop);
    tft.fillRect(ix, yDanger, iw, yBot - yDanger, TFT_DARK_RED);
    tft.fillRect(ix, ySafe,   iw, yDanger - ySafe, TFT_JUNGLE);
    tft.fillRect(ix, yAtmo,   iw, ySafe   - yAtmo, TFT_AQUA);
    tft.fillRect(ix, yTop,    iw, yAtmo   - yTop,  TFT_OFF_BLACK);
    tft.drawLine(ix, yAtmo, ix + iw - 1, yAtmo, TFT_LIGHT_GREY);
  } else {
    tft.fillRect(ix, yTop, iw, usableH, TFT_OFF_BLACK);
  }

  // Scale: km labels (left, right-aligned to the bar) + major ticks both edges
  float step = _reNiceStep(scaleTop);
  tft.setFont(Roboto_Black_12);
  tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
  for (float m = 0.0f; m <= scaleTop + 1.0f; m += step) {
    int16_t ty = altToY(m);
    tft.drawLine(RE_TAPE_X + 1, ty, RE_TAPE_X + 8, ty, TFT_LIGHT_GREY);
    tft.drawLine(barR - 9,      ty, barR - 2,      ty, TFT_LIGHT_GREY);
    char buf[6]; snprintf(buf, sizeof(buf), "%d", (int)(m / 1000.0f + 0.5f));
    int16_t lw = getFontStringWidth(&Roboto_Black_12, buf);
    int16_t ly = (int16_t)max((int)RE_TAPE_Y, min((int)(RE_TAPE_BOT - 14), (int)ty - 7));
    tft.setCursor(RE_TAPE_X - 3 - lw, ly);
    tft.print(buf);
  }
  // Minor ticks — 3 per major division (quarter-steps), skipping the major lines.
  float minor = step * 0.25f;
  int   nTicks = (int)(scaleTop / minor + 0.5f);
  for (int i = 1; i <= nTicks; i++) {
    if (i % 4 == 0) continue;            // coincides with a major tick
    int16_t ty = altToY(i * minor);
    tft.drawLine(RE_TAPE_X + 1, ty, RE_TAPE_X + 4, ty, TFT_GREY);
    tft.drawLine(barR - 5,      ty, barR - 2,      ty, TFT_GREY);
  }

  tft.drawRect(RE_TAPE_X, yTop, RE_TAPE_W, usableH, TFT_GREY);

  // ── Markers on the right ──
  // Markers use altToY directly (no clamp) so they read the true value at the ends;
  // the inset mapping keeps their triangles within the erased footprint. Periapsis is
  // drawn first so the current-altitude marker always sits on top of it.
  if (currentBody.hasAtmo) {
    int16_t yt = altToY(state.periapsis);
    tft.fillRect(ix, yt - 2, iw, 5, TFT_MAGENTA);
    tft.fillTriangle(barR + 1, yt, barR + 13, yt - 7, barR + 13, yt + 7, TFT_MAGENTA);
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
    tft.setCursor(barR + 16, yt - 7);
    tft.print("Pe");
  }
  {
    int16_t yt = altToY(state.altitude);
    tft.fillRect(ix, yt - 1, iw, 3, TFT_WHITE);
    tft.fillTriangle(barR + 1, yt, barR + 13, yt - 7, barR + 13, yt + 7, TFT_WHITE);
  }
}

/***************************************************************************************
   WIDGET: ATMO DENSITY BAR (same as the ascent screen — density fraction with SKY/
   FRENCH_BLUE/NAVY zones, a no-atmosphere parking segment, 10% ticks, and a marker).
****************************************************************************************/
// Body sea-level density (kg/m^3); 0 = airless. Mirrors the ascent-screen table.
static float _reBodySurfaceDensity() {
  if (currentBody.cond && strcmp(currentBody.cond, "Vacuum") == 0) return 0.0f;
  const char *n = currentBody.soiName;
  if (!n || n[0] == '\0') return 0.0f;
  if (!strcmp(n, "Kerbin")) return 1.225f;
  if (!strcmp(n, "Eve"))    return 6.150f;
  if (!strcmp(n, "Duna"))   return 0.0678f;
  if (!strcmp(n, "Jool"))   return 14.00f;
  if (!strcmp(n, "Laythe")) return 1.700f;
  return 0.0f;
}
// Atmospheric depth fraction (0 = vacuum, 1 = sea level); -1 if airless. ratio^0.25
// so the thin upper atmosphere still reads on the scale (matches ascent).
static float _reAtmoFraction() {
  float maxD = _reBodySurfaceDensity();
  if (maxD <= 0.0f) return -1.0f;
  float r = state.airDensity / maxD;
  if (r <= 0.0f) return 0.0f;
  if (r >= 1.0f) return 1.0f;
  return sqrtf(sqrtf(r));
}

static void _reDrawAtmo(KCM_TFT &tft) {
  const int16_t x0 = RE_ATMO_X, w = RE_ATMO_W;
  const int16_t innerX0 = x0 + 1, innerW = w - 2;
  const int16_t innerY0 = RE_ATMO_Y + 1, innerY1 = RE_ATMO_BOT - 1;
  const int16_t innerH  = innerY1 - innerY0 + 1;
  const int16_t noAtmH  = (int16_t)roundf(0.10f * innerH);   // bottom 10% = parking
  const int16_t atmYBot = innerY1 - noAtmH;
  const int16_t atmH    = atmYBot - innerY0 + 1;
  auto fracToY = [&](float f) -> int16_t {
    if (f < 0) f = 0; if (f > 1) f = 1;
    return atmYBot - (int16_t)roundf(f * (float)(atmH - 1));
  };

  // Erase the bar + right-side marker gutter each frame (the vertical "ATMO" label
  // lives left of the bar and is chrome, so it is not touched here).
  tft.fillRect(x0, RE_ATMO_Y, RE_ATMO_W + 14, RE_ATMO_H + 2, TFT_BLACK);

  int16_t y75 = fracToY(0.75f), y35 = fracToY(0.35f);
  tft.fillRect(innerX0, innerY0, innerW, y75 - innerY0,     TFT_SKY);          // dense (top)
  tft.fillRect(innerX0, y75,     innerW, y35 - y75,         TFT_FRENCH_BLUE);  // medium
  tft.fillRect(innerX0, y35,     innerW, atmYBot - y35 + 1, TFT_NAVY);         // near vacuum
  if (atmYBot + 1 <= innerY1)
    tft.fillRect(innerX0, atmYBot + 1, innerW, innerY1 - atmYBot, TFT_OFF_BLACK);  // parking

  int16_t tMaj = (int16_t)roundf(0.40f * innerW), tMin = (int16_t)roundf(0.20f * innerW);
  if (tMaj < 1) tMaj = 1; if (tMin < 1) tMin = 1;
  for (int16_t i = 0; i < 10; i++) {
    int16_t ty = fracToY((float)i / 10.0f);
    tft.drawLine(innerX0, ty, innerX0 + tMaj - 1, ty, (ty < y75) ? TFT_DARK_GREY : TFT_LIGHT_GREY);
  }
  for (int16_t i = 0; i < 10; i++) {
    int16_t ty = fracToY(((float)i + 0.5f) / 10.0f);
    tft.drawLine(innerX0, ty, innerX0 + tMin - 1, ty, (ty < y75) ? TFT_DARK_GREY : TFT_LIGHT_GREY);
  }

  tft.drawRect(x0, RE_ATMO_Y, w, RE_ATMO_BOT - RE_ATMO_Y, TFT_LIGHT_GREY);

  // Marker — right-side triangle pointing left at the current density fraction; parks
  // in the OFF_BLACK segment in vacuum / on airless bodies.
  float frac = _reAtmoFraction();
  bool  vac  = (frac <= 0.0f);
  int16_t triY = vac ? (int16_t)((atmYBot + 1 + innerY1) / 2) : fracToY(frac);
  int16_t tipX = x0 + w + 1, baseX = tipX + 12;
  tft.fillTriangle(tipX, triY, baseX, triY - 7, baseX, triY + 7, TFT_WHITE);
}

/***************************************************************************************
   WIDGET: HEAT-SHIELD / RETROGRADE ALIGNMENT BALL
****************************************************************************************/
static void _reDrawBall(KCM_TFT &tft) {
  const int16_t cx = RE_ATT_CX, cy = RE_ATT_CY, R = RE_ATT_R;

  // Shared reticle chrome (disc, good-zone ring, rings, cardinals, nose crosshair,
  // 30° ticks, bezel) — identical style to the MNVR / TGT / DOCK reticles.
  reticleDrawBase(tft, cx, cy, R, 12, 9);

  // Ring degree labels (NE quadrant, just inside each ring) — 10/20/30/40° scale.
  tft.setFont(Roboto_Black_12);
  tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
  static const char *ringL[4] = { "10", "20", "30", "40" };
  const int16_t ringR[4] = { R / 4, R / 2, (R * 3) / 4, R };
  for (uint8_t i = 0; i < 4; i++) { tft.setCursor(cx + 3, cy - ringR[i] + 2); tft.print(ringL[i]); }

  // Title
  const char *cap = "RETRO ALIGNMENT";
  int16_t cw = getFontStringWidth(&Roboto_Black_12, cap);
  tft.setCursor(cx - cw / 2, cy - R - 16);
  tft.print(cap);

  // Bank (roll) indicator — fixed scale at 0/±30/±60 + a moving sky-pointer, drawn
  // inside the top of the reticle (the disc fill erases it each frame, so it needs no
  // extra space). The pointer sits at the current bank angle on the fixed scale.
  {
    static const int16_t bankMarks[] = { 0, -30, 30, -60, 60 };
    for (uint8_t i = 0; i < 5; i++) {
      float ma = (-90.0f + bankMarks[i]) * (float)DEG_TO_RAD;
      int16_t r0 = R - 2, r1 = R - (bankMarks[i] == 0 ? 13 : 9);
      tft.drawLine(cx + (int16_t)(r0 * cosf(ma)), cy + (int16_t)(r0 * sinf(ma)),
                   cx + (int16_t)(r1 * cosf(ma)), cy + (int16_t)(r1 * sinf(ma)), TFT_LIGHT_GREY);
    }
    float ra = (-90.0f - state.roll) * (float)DEG_TO_RAD;
    int16_t px = cx + (int16_t)((R - 4)  * cosf(ra)), py = cy + (int16_t)((R - 4)  * sinf(ra));
    int16_t bx = cx + (int16_t)((R - 14) * cosf(ra)), by = cy + (int16_t)((R - 14) * sinf(ra));
    float pp = ra + 1.5708f;
    tft.fillTriangle(px, py,
                     bx + (int16_t)(6 * cosf(pp)), by + (int16_t)(6 * sinf(pp)),
                     bx - (int16_t)(6 * cosf(pp)), by - (int16_t)(6 * sinf(pp)), TFT_YELLOW);
  }

  // Retrograde marker — where the surface-retrograde vector (the airflow the heat
  // shield must face) sits relative to the nose; boresight = reticle centre.
  // The shared boresight projection makes AoA the TRUE nose-to-airflow angle at any
  // attitude; the old heading/pitch-difference form inflated it with pitch, and rotated
  // by +state.roll where the bank pointer above and the EADI ball both use the opposite
  // sense — so the marker spun the wrong way as bank built up. One definition now, in
  // kspBodyAxes (KerbalDisplayCommon).
  bool  moving = (state.surfaceVel > 1.0f);
  const KspBodyAxes _reAx = kspBodyAxes(state.heading, state.pitch, state.roll);
  float retroRight, retroUp;
  kspBoresightAngles(_reAx, state.srfVelHeading + 180.0f, -state.srfVelPitch,
                     retroRight, retroUp);
  float aoa    = sqrtf(retroRight * retroRight + retroUp * retroUp);
  uint16_t mc  = (aoa < 10.0f) ? TFT_NEON_GREEN : (aoa < 30.0f) ? TFT_YELLOW : TFT_RED;

  if (moving) {
    float rx =  retroRight * RE_ATT_FS;
    float ry = -retroUp    * RE_ATT_FS;
    float mag = sqrtf(rx * rx + ry * ry);
    float lim = R - 23;                          // keep the whole (r=14) symbol inside the disc
    if (mag > lim && mag > 0.0f) { float k = lim / mag; rx *= k; ry *= k; }
    drawRetrogradeMarker(tft, cx + (int16_t)rx, cy + (int16_t)ry, 14, mc);
  }

  // AoA (nose-to-airflow angle) readout below the reticle
  char buf[8];
  if (moving) snprintf(buf, sizeof(buf), "%d\xB0", (int)(aoa + 0.5f));
  else        snprintf(buf, sizeof(buf), "---");
  tft.setFont(Roboto_Black_20);
  tft.setTextColor(moving ? mc : TFT_DARK_GREY, TFT_BLACK);
  int16_t tw = getFontStringWidth(&Roboto_Black_20, buf);
  tft.fillRect(cx - 40, cy + R + 4, 80, 24, TFT_BLACK);
  tft.setCursor(cx - tw / 2, cy + R + 6);
  tft.print(buf);
}

/***************************************************************************************
   WIDGET: CHUTE DEPLOY SPEED TAPE (airspeed vs live safe-deploy limits)
   Horizontal airspeed bar. The green/yellow/red boundaries are the altitude-corrected
   safe-deploy speeds (from live dynamic pressure), so they slide left as the air
   thickens. The white marker is the current airspeed.
     green  : q < main limit        (main + drogue safe)
     yellow : main <= q < drogue     (drogue only)
     red    : q >= drogue limit      (nothing safe)
****************************************************************************************/
static void _reDrawEnvelope(KCM_TFT &tft) {
  const uint16_t iy = RE_CT_Y + 1, ih = RE_CT_H - 2;
  const uint16_t barBot = RE_CT_Y + RE_CT_H;

  // Live altitude-corrected safe-deploy speeds
  float vMain   = _reChuteSafeSpeed(LNDG_CHUTE_MAIN_MAX_Q);
  float vDrogue = _reChuteSafeSpeed(LNDG_CHUTE_DROGUE_MAX_Q);

  // Auto-range the airspeed axis so the current speed AND the drogue boundary always
  // fit. With a fixed max the safe speeds run off-scale at altitude (thin air), the
  // bar reads all-green, yet the q-based marker can be red — a contradiction. Grow the
  // axis 1000 -> 3000 m/s in 500 steps so marker position and colour always agree.
  float need    = fmaxf(state.surfaceVel, vDrogue) * 1.08f;
  float axisMax = RE_CT_VMAX;
  while (axisMax < need && axisMax < 3000.0f) axisMax += 500.0f;

  // Map speed to the bar INTERIOR [RE_CT_X+1 .. RE_CT_RIGHT-2] so ticks, boundaries
  // and the marker never draw on/over the border rectangle.
  auto spdToX = [&](float v) -> int16_t {
    float f = v / axisMax; if (f < 0) f = 0; if (f > 1) f = 1;
    return (int16_t)((RE_CT_X + 1) + f * (RE_CT_W - 3));
  };

  // Erase the widget footprint each frame (title + tags + bar + labels) — no streaks.
  tft.fillRect(RE_ENV_X, RE_ENV_Y - 16, RE_ENV_W, RE_ENV_H + 16, TFT_BLACK);

  int16_t xMain   = spdToX(vMain);
  int16_t xDrogue = spdToX(vDrogue);

  // Zone fills (dim): green 0..vMain (left), yellow vMain..vDrogue, red vDrogue..max
  int16_t gx0 = RE_CT_X + 1, rEnd = RE_CT_RIGHT - 1;
  if (xMain   > gx0)     tft.fillRect(gx0,     iy, xMain - gx0,     ih, TFT_JUNGLE);
  if (xDrogue > xMain)   tft.fillRect(xMain,   iy, xDrogue - xMain, ih, TFT_DARK_YELLOW);
  if (rEnd    > xDrogue) tft.fillRect(xDrogue, iy, rEnd - xDrogue,  ih, TFT_DARK_RED);

  // Boundary lines + tags above the bar
  tft.setFont(Roboto_Black_12);
  if (xMain > RE_CT_X && xMain < RE_CT_RIGHT) {
    tft.drawLine(xMain, iy, xMain, iy + ih - 1, TFT_NEON_GREEN);
    tft.setTextColor(TFT_NEON_GREEN, TFT_BLACK);
    tft.setCursor(xMain - 14, RE_CT_Y - 28); tft.print("MAIN");
  }
  if (xDrogue > RE_CT_X && xDrogue < RE_CT_RIGHT) {
    tft.drawLine(xDrogue, iy, xDrogue, iy + ih - 1, TFT_YELLOW);
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setCursor(xDrogue - 12, RE_CT_Y - 28); tft.print("DROG");
  }

  // Ticks INSIDE the bar on both edges (like the altitude tape) + centred numeric
  // labels below. Major ticks at each axisMax/5 step, minor at the half-steps.
  int step = (int)(axisMax / 5.0f + 0.5f);
  tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
  for (int v = 0; v <= (int)axisMax + 1; v += step) {
    int16_t tx = spdToX((float)v);
    tft.drawLine(tx, iy,             tx, iy + 7,        TFT_LIGHT_GREY);   // top edge, inward
    tft.drawLine(tx, barBot - 1 - 7, tx, barBot - 1,    TFT_LIGHT_GREY);   // bottom edge, inward
    char b[6]; snprintf(b, sizeof(b), "%d", v);
    int16_t lw = getFontStringWidth(&Roboto_Black_12, b);
    int16_t lx = (int16_t)constrain((int)(tx - lw / 2), (int)RE_ENV_X, (int)(RE_ENV_X + RE_ENV_W - lw));
    tft.setCursor(lx, barBot + 6); tft.print(b);
  }
  for (int v = step / 2; v <= (int)axisMax; v += step) {   // minor ticks (both edges)
    int16_t tx = spdToX((float)v);
    tft.drawLine(tx, iy,             tx, iy + 4,        TFT_GREY);
    tft.drawLine(tx, barBot - 1 - 4, tx, barBot - 1,    TFT_GREY);
  }

  tft.drawRect(RE_CT_X, RE_CT_Y, RE_CT_W, RE_CT_H, TFT_GREY);

  // Current-airspeed marker: white vertical line through the bar + a tier-coloured
  // triangle above it pointing down.
  float q = _reDynPressure();
  uint16_t vc = (q < LNDG_CHUTE_MAIN_MAX_Q) ? TFT_NEON_GREEN :
                (q < LNDG_CHUTE_DROGUE_MAX_Q) ? TFT_YELLOW : TFT_RED;
  int16_t xm = constrain(spdToX(state.surfaceVel), (int16_t)(RE_CT_X + 8), (int16_t)(RE_CT_RIGHT - 8));
  tft.fillRect(xm - 1, iy, 3, ih, TFT_WHITE);
  tft.fillTriangle(xm, RE_CT_Y - 1, xm - 8, RE_CT_Y - 11, xm + 8, RE_CT_Y - 11, vc);

  // Title + axis label, both centred on the bar (textCenter centres within the box).
  textCenter(tft, &Roboto_Black_12, RE_CT_X, RE_CT_Y - 44, RE_CT_W, 16, "CHUTE DEPLOY",   TFT_LIGHT_GREY, TFT_BLACK);
  textCenter(tft, &Roboto_Black_12, RE_CT_X, barBot + 22,   RE_CT_W, 16, "AIRSPEED (m/s)", TFT_LIGHT_GREY, TFT_BLACK);
}

/***************************************************************************************
   WIDGET: G METER (left cluster) — zone-background gauge with a numbered axis
   Green/yellow/red bands come from this controller's G thresholds (aligned to the
   annunciator, G_WARN/G_ALARM, ±); a neutral dark-grey band marks the -1..+2 g nominal
   range. Live white marker + numbered axis in the left gutter.
****************************************************************************************/
static void _reDrawGauges(KCM_TFT &tft) {
  const uint16_t gx = RE_GF_X, gw = RE_GF_W;
  const uint16_t gix = gx + 1, giw = gw - 2;
  const float gMin = -6.0f, gMax = 12.0f;
  auto gToY = [&](float g) -> int16_t {
    float f = (g - gMin) / (gMax - gMin); if (f < 0) f = 0; if (f > 1) f = 1;
    return (int16_t)(RE_GA_BOT - f * RE_GA_H);
  };
  tft.fillRect(gx - 20, RE_GA_Y, gw + 34, RE_GA_H + 1, TFT_BLACK); // erase axis numbers + bar + marker gutter
  int16_t yAN = gToY(G_ALARM_NEG), yWN = gToY(G_WARN_NEG), yWP = gToY(G_WARN_POS), yAP = gToY(G_ALARM_POS);
  tft.fillRect(gix, yAN,     giw, RE_GA_BOT - yAN, TFT_DARK_RED);     // g < alarm-neg
  tft.fillRect(gix, yWN,     giw, yAN - yWN,       TFT_DARK_YELLOW);  // warn-neg .. alarm-neg
  tft.fillRect(gix, yWP,     giw, yWN - yWP,       TFT_JUNGLE);       // caution-safe band
  tft.fillRect(gix, yAP,     giw, yWP - yAP,       TFT_DARK_YELLOW);  // warn-pos .. alarm-pos
  tft.fillRect(gix, RE_GA_Y, giw, yAP - RE_GA_Y,   TFT_DARK_RED);     // g > alarm-pos
  // Nominal band (-1 .. +2 g) — neutral dark-grey background over the green safe band.
  int16_t yP2 = gToY(2.0f), yN1 = gToY(-1.0f);
  tft.fillRect(gix, yP2, giw, yN1 - yP2, TFT_DARK_GREY);
  int16_t y0 = gToY(0.0f);
  tft.drawLine(gix, y0, gix + giw - 1, y0, TFT_LIGHT_GREY);          // 0-g reference
  // Numbered vertical axis: major tick + right-aligned value every 3 g in the left gutter.
  tft.setFont(Roboto_Black_12);
  for (int gv = (int)gMin; gv <= (int)gMax; gv += 3) {
    int16_t ty = gToY((float)gv);
    tft.drawLine(gx + 1, ty, gx + 5, ty, TFT_LIGHT_GREY);
    char nb[6]; snprintf(nb, sizeof(nb), "%d", gv);
    int16_t nw = getFontStringWidth(&Roboto_Black_12, nb);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(gx - 4 - nw, ty - 7);
    tft.print(nb);
  }
  for (int gv = (int)gMin + 1; gv < (int)gMax; gv++) {               // minor integer ticks
    if (((gv - (int)gMin) % 3) == 0) continue;
    int16_t ty = gToY((float)gv);
    tft.drawLine(gx + 1, ty, gx + 3, ty, TFT_GREY);
  }
  tft.drawRect(gx, RE_GA_Y, gw, RE_GA_H, TFT_GREY);
  float g = state.gForce;
  int16_t ym = constrain(gToY(g), (int16_t)(RE_GA_Y + 7), (int16_t)(RE_GA_BOT - 7));
  tft.fillRect(gix, ym - 1, giw, 3, TFT_WHITE);                      // white index line
  tft.fillTriangle(gx + gw + 1, ym, gx + gw + 12, ym - 7, gx + gw + 12, ym + 7, TFT_WHITE);
}

/***************************************************************************************
   WIDGET: SKIN / CORE TEMPERATURE (horizontal bars beneath the chute deploy bar)
****************************************************************************************/
// One horizontal temp bar: left tag, dim background, coloured fill, warn/alarm ticks.
static void _reHTempBar(KCM_TFT &tft, uint16_t y, const char *tag, uint8_t pct) {
  uint16_t col = (pct >= TEMP_ALARM_PCT) ? TFT_RED :
                 (pct >= TEMP_WARN_PCT)  ? TFT_YELLOW : TFT_NEON_GREEN;
  const uint16_t ix = RE_TMP_X + 1, iw = RE_TMP_W - 2;
  float f = pct / 100.0f; if (f < 0) f = 0; if (f > 1) f = 1;
  tft.setFont(Roboto_Black_12);
  tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
  int16_t lw = getFontStringWidth(&Roboto_Black_12, tag);
  tft.setCursor(RE_TMP_X - 8 - lw, y + (RE_TMP_BH - 14) / 2);
  tft.print(tag);
  tft.fillRect(ix, y + 1, iw, RE_TMP_BH - 2, TFT_OFF_BLACK);           // empty
  tft.fillRect(ix, y + 1, (uint16_t)(f * iw), RE_TMP_BH - 2, col);     // fill from the left
  int16_t xw = ix + (int16_t)(TEMP_WARN_PCT  / 100.0f * iw);
  int16_t xa = ix + (int16_t)(TEMP_ALARM_PCT / 100.0f * iw);
  tft.drawLine(xw, y + 1, xw, y + RE_TMP_BH - 2, TFT_YELLOW);          // warn threshold
  tft.drawLine(xa, y + 1, xa, y + RE_TMP_BH - 2, TFT_RED);             // alarm threshold
  tft.drawRect(RE_TMP_X, y, RE_TMP_W, RE_TMP_BH, TFT_GREY);
}
static void _reDrawTemp(KCM_TFT &tft) {
  tft.fillRect(RE_TMP_LX, RE_TMP_Y - 2, (RE_TMP_X + RE_TMP_W) - RE_TMP_LX + 2,
               RE_TMP_VS + RE_TMP_BH + 4, TFT_BLACK);
  _reHTempBar(tft, RE_TMP_Y,             "SKIN", state.skinTempPct);
  _reHTempBar(tft, RE_TMP_Y + RE_TMP_VS, "CORE", state.coreTempPct);
}

/***************************************************************************************
   CHROME: RE-ENTRY  (divider + static text-panel labels)
****************************************************************************************/
static const tFont   *RE_LF  = &Roboto_Black_28;   // panel label font (rows 0-5) — matches the reticle screens' 28pt labels
static const tFont   *RE_BTN = &Roboto_Black_28;   // SAS/Gear button font — matches the 28pt button labels on the other screens
static const tFont   *RE_VF  = &Roboto_Black_36;   // panel value font (rows 0-5) — matches the reticle screens' 36pt values
// Row 6 (Drog:/Main: split status) stays one tier smaller: the tight half-width value
// sub-cells cannot hold STOW/OPEN at 36pt, so this row keeps the original 20/32 fonts.
static const tFont   *RE_LF6 = &Roboto_Black_20;   // row-6 split label font
static const tFont   *RE_VF6 = &Roboto_Black_32;   // row-6 split value font
static const uint8_t  RE_NR  = 8;

static void _lndgChromeReentry(KCM_TFT &tft) {
  // Divider between graphics zone and text panel
  tft.drawLine(RE_DIV_X, TITLE_TOP, RE_DIV_X, SCREEN_H - 1, TFT_GREY);

  // Vertical labels for the two side-by-side bars — same format for both.
  drawVerticalText(tft, 0, RE_TAPE_Y, 14, RE_TAPE_H, &Roboto_Black_12,
                   "ALTITUDE", TFT_LIGHT_GREY, TFT_BLACK);
  drawVerticalText(tft, RE_ATMO_LBL_X, RE_ATMO_Y, 14, RE_ATMO_H, &Roboto_Black_12,
                   "ATMOSPHERE", TFT_LIGHT_GREY, TFT_BLACK);

  // G METER vertical label (left cluster, just right of the ATMOSPHERE bar).
  drawVerticalText(tft, RE_GLBL_X, RE_GA_Y, 14, RE_GA_H, &Roboto_Black_12,
                   "G METER", TFT_LIGHT_GREY, TFT_BLACK);

  const uint16_t RHW = RE_TXT_W / 2;
  // Decide both swappable row labels from the current state before painting them.
  // Painted from stale flags (a previous visit, the vessel-switch reset) the first draw
  // pass found the mismatch and re-entered the screen before writing a single value:
  // one frame of labels over empty rows. Same ordering Powered uses for its tape regime.
  {
    const float atmoAlt = (currentBody.lowSpace > 0.0f) ? currentBody.lowSpace : 70000.0f;
    _lndgReentryRow1SL  = !state.inAtmo;
    _lndgReentryRow0TPe = (!state.inAtmo && state.periapsis < atmoAlt);
  }
  // Panel row labels (values filled by the draw pass). Rows 0-5 full width.
  const char *r0 = _lndgReentryRow0TPe ? "T+ATM" : "T+GRND";
  const char *r1 = _lndgReentryRow1SL  ? "ALT.SL" : "ALT.RDR";
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(0, RE_NR), RE_TXT_W, rowHFor(RE_NR), r0, COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(1, RE_NR), RE_TXT_W, rowHFor(RE_NR), r1, COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(2, RE_NR), RE_TXT_W, rowHFor(RE_NR), "V.SRF", COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(3, RE_NR), RE_TXT_W, rowHFor(RE_NR), "V.VRT", COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(4, RE_NR), RE_TXT_W, rowHFor(RE_NR), "PEA",   COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, RE_LF, RE_TXT_X, rowYFor(5, RE_NR), RE_TXT_W, rowHFor(RE_NR), "MACH",  COL_LABEL, COL_BACK, COL_NO_BDR);

  // Horizontal separator above the Drogue/Main status board.
  tft.drawLine(RE_DIV_X, rowYFor(6, RE_NR) - ROW_PAD, CONTENT_W - 1, rowYFor(6, RE_NR) - ROW_PAD, TFT_GREY);

  // Rows 6 (Drogue|Main) and 7 (Gear|SAS) — split, with dividers
  auto splitLabels = [&](uint8_t row, const char *lbl, const char *rbl) {
    uint16_t y = rowYFor(row, RE_NR), h = rowHFor(RE_NR);
    printDispChrome(tft, RE_LF6, RE_TXT_X,            y, RHW - ROW_PAD, h, lbl, COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, RE_LF6, RE_TXT_X + RHW + ROW_PAD, y, RHW - ROW_PAD, h, rbl, COL_LABEL, COL_BACK, COL_NO_BDR);
    for (int8_t dx = -1; dx <= 1; dx++)
      tft.drawLine(RE_TXT_X + RHW + dx, y, RE_TXT_X + RHW + dx, rowYFor(row + 1, RE_NR) - 1, TFT_GREY);
  };
  splitLabels(6, "DROGUE", "MAIN");
  // Row 7 buttons are drawn in the update pass; only draw the divider here.
  {
    uint16_t y = rowYFor(7, RE_NR);
    for (int8_t dx = -1; dx <= 1; dx++)
      tft.drawLine(RE_TXT_X + RHW + dx, y, RE_TXT_X + RHW + dx, SCREEN_H - 1, TFT_GREY);
  }
}

/***************************************************************************************
   DRAW: RE-ENTRY
****************************************************************************************/
static void _lndgDrawReentry(KCM_TFT &tft) {
  const uint16_t RHW = RE_TXT_W / 2;
  uint16_t fg, bg;
  char buf[16];

  auto reVal = [&](uint8_t row, const char *label, const String &val, uint16_t fgc, uint16_t bgc) {
    drawValue(tft, screen_LNDGRE, row, RE_TXT_X, RE_TXT_W, label, val, fgc, bgc, RE_VF, RE_NR);
  };

  // Advance the shared vertical-accel filter once per frame before the estimates.
  ttgAdvanceAccel();
  float tGround = estimateTimeToGround();
  float atmoAlt = (currentBody.lowSpace > 0.0f) ? currentBody.lowSpace : 70000.0f;
  bool  aboveAtmo   = !state.inAtmo;
  bool  peaBelowAtm = (state.periapsis < atmoAlt);
  bool  wantTPe     = (aboveAtmo && peaBelowAtm);

  // ── Graphics widgets (full repaint each frame) ──
  // Left cluster: altitude tape, ATMOSPHERE bar, G meter.
  _reDrawTape(tft);
  _reDrawAtmo(tft);
  _reDrawGauges(tft);          // G meter, beside the ATMOSPHERE bar
  // Right cluster (top -> bottom): reticle, chute deploy, skin/core temp.
  _reDrawBall(tft);
  _reDrawEnvelope(tft);
  _reDrawTemp(tft);

  // ── Text panel row-label swaps (force a chrome redraw when a label changes) ──
  if (wantTPe != _lndgReentryRow0TPe) {
    _lndgReentryRow0TPe = wantTPe; rowCache[screen_LNDGRE][0].value = "\x01";
    switchToScreen(screen_LNDGRE); return;
  }
  if (aboveAtmo != _lndgReentryRow1SL) {
    _lndgReentryRow1SL = aboveAtmo; rowCache[screen_LNDGRE][1].value = "\x01";
    switchToScreen(screen_LNDGRE); return;
  }

  // Row 0: T+Atm (above atmo, Pe below atmo) or T+Grnd
  if (wantTPe) {
    float tAtmo = estimateTimeToAtmosphere();
    if      (tAtmo >= 0.0f)             reVal(0, "T+ATM", formatTimeCompact(tAtmo), TFT_DARK_GREEN, TFT_BLACK);
    else                               reVal(0, "T+ATM", "---", TFT_DARK_GREY, TFT_BLACK);
  } else if (!aboveAtmo) {
    lndgTGroundColors(tGround, fg, bg);
    if (tGround >= 0.0f) reVal(0, "T+GRND", formatTimeCompact(tGround), fg, bg);
    else                 reVal(0, "T+GRND", "---", fg, bg);
  } else {
    lndgTGroundColors(-1.0f, fg, bg);
    reVal(0, "T+GRND", "---", fg, bg);
  }

  // Row 1: Alt.SL (above atmo) or Alt.Rdr (in atmo, coloured by proximity)
  if (aboveAtmo) {
    reVal(1, "ALT.SL", formatAlt(state.altitude), TFT_DARK_GREEN, TFT_BLACK);
  } else {
    fg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_WHITE  :
         (state.radarAlt < ALT_RDR_WARN_M)  ? TFT_YELLOW : TFT_DARK_GREEN;
    bg = (state.radarAlt < ALT_RDR_ALARM_M) ? TFT_RED    : TFT_BLACK;
    reVal(1, "ALT.RDR", formatAlt(state.radarAlt), fg, bg);
  }

  // Row 2: V.Srf
  // surfaceVel is a magnitude, always >= 0
  reVal(2, "V.SRF", fmtMs(state.surfaceVel), TFT_DARK_GREEN, TFT_BLACK);

  // Row 3: V.Vrt (vertical descent rate). The G load now lives in the graphical G meter.
  // Hazard-coloured (landing thresholds) only near the ground; at altitude a high descent
  // rate is normal, so it reads neutral there.
  {
    float vv = state.verticalVel;
    if (state.inAtmo && state.radarAlt < ALT_RDR_WARN_M) {
      fg = (vv < LNDG_VVRT_ALARM_MS) ? TFT_WHITE  :
           (vv < LNDG_VVRT_WARN_MS)  ? TFT_YELLOW : TFT_DARK_GREEN;
      bg = (vv < LNDG_VVRT_ALARM_MS) ? TFT_RED    : TFT_BLACK;
    } else {
      fg = TFT_DARK_GREEN; bg = TFT_BLACK;
    }
    reVal(3, "V.VRT", fmtMs(vv), fg, bg);
  }

  // Row 4: PeA — coloured by re-entry corridor regime
  {
    ReCorridor c = _reCorridor();
    int8_t reg = _rePeRegime(c, state.periapsis);
    uint16_t pfg = _reRegimeColor(reg);
    if (reg == 0) { pfg = TFT_WHITE; bg = TFT_RED; } else bg = TFT_BLACK;
    reVal(4, "PEA", formatAlt(state.periapsis), pfg, bg);
  }

  // Row 5: Mach (transonic band highlighted)
  {
    float m = state.machNumber; snprintf(buf, sizeof(buf), "%.2f", m);
    bool transonic = (m >= MACH_TRANSONIC_LO && m <= MACH_TRANSONIC_HI);
    reVal(5, "MACH", String(buf), transonic ? TFT_YELLOW : TFT_DARK_GREEN, TFT_BLACK);
  }

  // ── Chute latch bookkeeping — armed-safe when deployed below the rip q ──
  if (state.drogueDeploy && !_drogueDeployed) { _drogueDeployed = true; _drogueArmedSafe = (!state.inAtmo || _reDynPressure() < LNDG_CHUTE_DROGUE_MAX_Q); }
  if (state.drogueCut    && !_drogueCut)      { _drogueCut = true; _drogueDeployed = false; _drogueArmedSafe = false; }
  if (state.mainDeploy   && !_mainDeployed)   { _mainDeployed = true; _mainArmedSafe = (!state.inAtmo || _reDynPressure() < LNDG_CHUTE_MAIN_MAX_Q); }
  if (state.mainCut      && !_mainCut)        { _mainCut = true; _mainDeployed = false; _mainArmedSafe = false; }

  // Chute status by dynamic-pressure tier vs the chute's rip limit (maxQ).
  auto chuteState = [&](bool dep, bool cut, bool safe, float maxQ, float fullAlt,
                        const char *&lbl, uint16_t &cfg, uint16_t &cbg) {
    uint8_t tier = _reChuteTier(maxQ);   // 0 safe, 1 caution, 2 rip
    if (cut) { lbl = "CUT"; cfg = TFT_RED; cbg = TFT_BLACK; return; }
    if (dep) {
      if (!safe && state.inAtmo && tier == 2) { lbl = "OPEN"; cfg = TFT_WHITE; cbg = TFT_RED; return; }
      if (state.airDensity < LNDG_CHUTE_SEMI_DENSITY) { lbl = "ARM"; cfg = TFT_SKY; cbg = TFT_BLACK; return; }
      lbl = "OPEN"; cfg = (state.radarAlt > fullAlt) ? TFT_YELLOW : TFT_DARK_GREEN; cbg = TFT_BLACK; return;
    }
    lbl = "STOW";
    if (!state.inAtmo)      { cfg = TFT_DARK_GREEN; cbg = TFT_BLACK; }
    else if (tier == 2)     { cfg = TFT_WHITE;      cbg = TFT_RED; }
    else if (tier == 1)     { cfg = TFT_YELLOW;     cbg = TFT_BLACK; }
    else                    { cfg = TFT_DARK_GREEN; cbg = TFT_BLACK; }
  };

  // Row 6: Drogue | Main (split values, cached). The "DROG"/"MAIN" labels are chrome;
  // the status right-aligns in a value sub-cell to the right of the label (empty param —
  // no redundant reservation). This row stays at the RE_VF6 (32pt) tier — the tight
  // half-width sub-cells cannot hold STOW/OPEN at the rows-0-5 36pt value font.
  {
    uint16_t xL = RE_TXT_X, xR = RE_TXT_X + RHW + ROW_PAD;
    uint16_t wL = RHW - ROW_PAD, wR = RHW - ROW_PAD;
    uint16_t xDV = xL + 70, wDV = wL - 70;   // drogue value sub-cell (widened so STOW/OPEN fit the RE_VF6 font — no left-spill ghost)
    uint16_t xMV = xR + 70, wMV = wR - 70;   // main value sub-cell (right of "MAIN")
    uint16_t y6 = rowYFor(6, RE_NR), h6 = rowHFor(RE_NR);
    const char *dv; uint16_t dfg, dbg;
    chuteState(_drogueDeployed, _drogueCut, _drogueArmedSafe, LNDG_CHUTE_DROGUE_MAX_Q, LNDG_DROGUE_FULL_ALT, dv, dfg, dbg);
    { String ds = dv; RowCache &dc = rowCache[screen_LNDGRE][6];
      if (dc.value != ds || dc.fg != dfg || dc.bg != dbg) {
        printValue(tft, RE_VF6, xDV, y6, wDV, h6, "", ds, dfg, dbg, COL_BACK, printState[screen_LNDGRE][6]);
        dc.value = ds; dc.fg = dfg; dc.bg = dbg; } }
    const char *mv; uint16_t mfg, mbg;
    chuteState(_mainDeployed, _mainCut, _mainArmedSafe, LNDG_CHUTE_MAIN_MAX_Q, LNDG_MAIN_FULL_ALT, mv, mfg, mbg);
    { String ms = mv; RowCache &mc = rowCache[screen_LNDGRE][11];
      if (mc.value != ms || mc.fg != mfg || mc.bg != mbg) {
        printValue(tft, RE_VF6, xMV, y6, wMV, h6, "", ms, mfg, mbg, COL_BACK, printState[screen_LNDGRE][11]);
        mc.value = ms; mc.fg = mfg; mc.bg = mbg; } }
  }

  // Row 7: Gear | SAS buttons
  {
    uint16_t y = rowYFor(7, RE_NR);
    uint16_t rh = SCREEN_H - y;
    uint16_t xL = RE_TXT_X - 2, wL = RHW + 2;
    uint16_t xR = RE_TXT_X + RHW, wR = CONTENT_W - xR;
    // Gear
    {
      bool gearDown = state.gear_on;
      String gv = gearDown ? "DOWN" : "UP";
      RowCache &gc = rowCache[screen_LNDGRE][13];
      if (gc.value != gv) {
        ButtonLabel btn = gearDown
            ? ButtonLabel{ "GEAR", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
            : ButtonLabel{ "GEAR", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
        drawButton(tft, xL, y, wL, rh, btn, RE_BTN, false);
        gc.value = gv;
      }
    }
    // SAS (re-entry context: STAB/RETRO good; OFF alarm above aero-stable Mach)
    {
      const char *ss; uint16_t sfg, sbg;
      if (state.sasMode == 255) {
        ss = "SAS";
        bool aeroUnstable = (state.machNumber > REENTRY_SAS_AERO_STABLE_MACH);
        sfg = aeroUnstable ? TFT_WHITE : TFT_DARK_GREY;
        sbg = aeroUnstable ? TFT_RED   : TFT_OFF_BLACK;
      } else {
        switch (state.sasMode) {
          case 0:  ss = "STAB"; sfg = TFT_WHITE; sbg = TFT_DARK_GREEN; break;
          case 2:  ss = "RETR"; sfg = TFT_WHITE; sbg = TFT_DARK_GREEN; break;
          case 1:  ss = "PRO";  sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 3:  ss = "NRM";  sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 4:  ss = "ANRM"; sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 5:  ss = "RAD+"; sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 6:  ss = "RAD-"; sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 7:  ss = "TGT";  sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 8:  ss = "ATGT"; sfg = TFT_WHITE; sbg = TFT_RED;        break;
          case 9:  ss = "MNVR"; sfg = TFT_WHITE; sbg = TFT_RED;        break;
          default: ss = "SAS";  sfg = TFT_DARK_GREY; sbg = TFT_OFF_BLACK; break;
        }
      }
      RowCache &sc = rowCache[screen_LNDGRE][14];
      String ssv = ss;
      if (sc.value != ssv || sc.fg != sfg || sc.bg != sbg) {
        ButtonLabel btn = { ss, sfg, sfg, sbg, sbg, TFT_GREY, TFT_GREY };
        drawButton(tft, xR, y, wR, rh, btn, RE_BTN, false);
        sc.value = ssv; sc.fg = sfg; sc.bg = sbg;
      }
    }
  }
}

/***************************************************************************************
   Screen_MNVR.ino  —  Maneuver screen: burn alignment reticle + node data

   LAYOUT (1024×600, content area 940×538 below title bar; reticle R=210)
   ┌────────────────────────────────┬──────────────────────────────────────┐
   │                                │ ΔV.Mnvr:      847 m/s                │
   │   Alignment Reticle            │ ΔV.Plan:     1204 m/s               │
   │   (black disc, R=210)          │ ΔV.Stg:       923 m/s                │
   │                                │ T+Ign:        4:32                   │
   │   ◆ maneuver marker (blue)     │ T+Mnvr:       5:19                   │
   │   □ green box when aligned     │ Burn dur:     1:47                   │
   │   + fixed crosshair (grey)     │ Brg: +2.1°      Elv: -1.4°          │
   │                                │ [RCS]        [SAS: MNVR]             │
   └────────────────────────────────┴──────────────────────────────────────┘

   RETICLE SEMANTICS
   ─────────────────
   Fixed crosshair  = your nose direction (always at centre)
   Marker (MNVR)    = where the burn vector points relative to your nose.
                      At centre → aligned for the burn.
   Marker colour    = maneuver blue (TFT_BLUE), half-brightness TFT_NAVY while pinned.
   Alignment box    = neon-green square drawn around diamond when
                      error magnitude < ATT_ERR_WARN_DEG (5°).
   Dimmed marker (TFT_NAVY) = pinned at the scope boundary, i.e. the node is further
                      off the nose than the outer ring can show. Direction honest,
                      distance understated; Brg/Elv carry the true value.

   RETICLE GEOMETRY (rev-2, 1024×600)
   ─────────────────
   Centre: (289, 300)  Radius: 210px  Scale: 10.5 px/deg (±20° full scale)
   Rings: 5°=52px  10°=105px  15°=157px  20°=210px. Centred in the left region
   x=[0,578]; ΔV bar centred under it. Centre/radius are the shared RETICLE_*
   constants, identical to DOCK and TGT.

   PANEL: 360 px wide at x=580 (matches ascent/circ), NR=8 rows of 67 px,
   labels Black_28, values Black_36
   Row 0: ΔV.Mnvr        Row 1: ΔV.Plan
   Row 2: ΔV.Stg         Row 3: T+Ign
   Row 4: T+Mnvr         Row 5: Burn dur
   Row 6: Brg | Elv split
   Row 7: RCS | SAS buttons (to screen bottom)

   SAS COLOUR SCHEME
   ──────────────────
   MNVR (9)  = dark green  ← correct mode for burn
   STAB (0)  = cyan/sky    ← acceptable (holding attitude manually)
   SAS  (255)= grey        ← off
   All others= red         ← wrong for a burn
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── State flags ───────────────────────────────────────────────────────────────────────
static bool _mnvrChromDrawn  = false;


// ── Reticle geometry — centred and stretched to fill the left region ─────────────────
// The readout panel now sits on the far right (x=580, matching the ascent/circ
// panel), leaving x=[0,578] for the reticle. The reticle is centred in that band
// using the shared RETICLE_* constants; the ΔV bar is centred under it.
static const uint16_t MNVR_CX    = RETICLE_CX;   // centre of the left region x=[0,578]
static const uint16_t MNVR_CY    = RETICLE_CY;   // shared disc centre y (DOCK/TGT match)
static const uint16_t MNVR_R     = RETICLE_R;    // shared disc radius (DOCK/TGT match)
static const float    MNVR_SCALE = (float)MNVR_R / 20.0f;   // 10.5 px/deg, ±20° full scale

static const uint16_t MNVR_RING_5  = MNVR_R / 4;         // 52
static const uint16_t MNVR_RING_10 = MNVR_R / 2;         // 105
static const uint16_t MNVR_RING_15 = (MNVR_R * 3) / 4;   // 157
static const uint16_t MNVR_RING_20 = MNVR_R;             // 210

// Marker sizing — diamond and box scaled up with the larger reticle
static const uint8_t MNVR_MRK_DS  = 26;   // maneuver marker prong length
static const uint8_t MNVR_BOX_R   = 23;   // alignment box half-size (DS + ~7px clearance)
static const uint8_t MNVR_ERASE_R = 29;   // erase rect half-size (covers prong 26 + cap)

// Right panel geometry — matches the ascent/circ readout panel: 360 px wide,
// right-aligned to the content edge, labels Black_28, values Black_36.
static const uint16_t MNVR_RP_W   = RETICLE_RP_W;
static const uint16_t MNVR_RP_X   = CONTENT_W - MNVR_RP_W;              // 580
static const uint8_t  MNVR_RP_NR  = 8;
static const tFont   *MNVR_RP_LBL = &Roboto_Black_28;   // row labels (chrome)
static const tFont   *MNVR_RP_F   = &Roboto_Black_36;   // row values

// ΔV bar geometry — centred under the reticle
static const uint16_t MNVR_BAR_W = RETICLE_BAR_W;
static const uint16_t MNVR_BAR_X = MNVR_CX - MNVR_BAR_W / 2;   // 64
static const uint16_t MNVR_BAR_H = 26;

// Screen cache index
static const uint8_t MNVR_SC = (uint8_t)screen_MNVR;   // 3

// ── Shared marker-layer geometry ─────────────────────────────────────────────────────
// MNVR draws a single marker rather than DOCK/TGT's four, so it does not call
// reticleUpdateDots — but the clamp, the erase-rect chrome repair and the angle→screen
// projection are the same code, and now come from KerbalDisplayCommon rather than from
// per-screen copies. dotRPrimary/dotRVel carry the maneuver diamond's prong length;
// The marker is body-referenced like every other boresight display in the project, so
// pitch and yaw move it the way the pilot expects at any roll attitude.
static const char *const MNVR_RING_LBL[4] = { "5", "10", "15", "20" };
static const ReticleGeom MNVR_GEOM = {
    (int16_t)MNVR_CX, (int16_t)MNVR_CY, (int16_t)MNVR_R, MNVR_SCALE,
    MNVR_MRK_DS, MNVR_MRK_DS, MNVR_ERASE_R,
    MNVR_MRK_DS + 2,                // clampMargin
    MNVR_RING_LBL, &Roboto_Black_16
};


// ── Previous marker state ─────────────────────────────────────────────────────────────
static int16_t _mnvrPrevMrkX    = 9999, _mnvrPrevMrkY = 9999;
static bool    _mnvrPrevAligned = false;
static bool    _mnvrPrevPinned  = false;   // marker clamped at the scope boundary
static float   _mnvrPrevDV      = -999.0f;   // ΔV-bar dedup; reset in chrome on re-entry
static uint16_t _mnvrPrevBarCol = 0;         // and its colour, which stage ΔV also drives


// ── Draw reticle chrome ───────────────────────────────────────────────────────────────
static void _mnvrDrawReticleChrome(KCM_TFT &tft) {
    // Shared disc + rings + cardinals + crosshair + ticks + bezel (MNVR/DOCK gap 18, tick 14)
    reticleDrawBase(tft, MNVR_CX, MNVR_CY, MNVR_R, 18, 14);

    // Ring degree labels (NE quadrant, just inside each ring). Transparent bg.
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_LIGHT_GREY);
    tft.setCursor(MNVR_CX + 3, MNVR_CY - MNVR_RING_5  + 3);  tft.print("5");
    tft.setCursor(MNVR_CX + 3, MNVR_CY - MNVR_RING_10 + 3);  tft.print("10");
    tft.setCursor(MNVR_CX + 3, MNVR_CY - MNVR_RING_15 + 3);  tft.print("15");
    tft.setCursor(MNVR_CX + 3, MNVR_CY - MNVR_RING_20 + 3);  tft.print("20");

    // Legend — top-left corner
    static const uint16_t LEG_X  = 6;
    static const uint16_t LEG_Y0 = TITLE_TOP + 6;
    tft.setFont(Roboto_Black_16);

    // MANEUVER — blue maneuver marker
    drawManeuverMarker(tft, LEG_X + 6, LEG_Y0 + 6, 5, TFT_BLUE);
    tft.setTextColor(TFT_SKY, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0);
    tft.print("MANEUVER");

    // NOSE — crosshair symbol
    tft.drawLine(LEG_X+1,  LEG_Y0+26, LEG_X+4,  LEG_Y0+26, TFT_GREY);
    tft.drawLine(LEG_X+8,  LEG_Y0+26, LEG_X+11, LEG_Y0+26, TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+21, LEG_X+6,  LEG_Y0+24, TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+28, LEG_X+6,  LEG_Y0+31, TFT_GREY);
    tft.fillCircle(LEG_X+6, LEG_Y0+26, 1, TFT_GREY);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0 + 20);
    tft.print("NOSE");

    // ΔV bar chrome — label/value in Black_24, centred under the reticle. lblY
    // gives the Black_24 text (cap 29) ~5 px of clearance above the bar border.
    uint16_t barY = MNVR_CY + MNVR_R + 42;
    uint16_t lblY = barY - 34;
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(MNVR_BAR_X, lblY);
    tft.print("\xCE\x94V Burn");
    tft.drawRect(MNVR_BAR_X, barY, MNVR_BAR_W, MNVR_BAR_H, TFT_GREY);
}


// ── Draw right-panel chrome ───────────────────────────────────────────────────────────
static void _mnvrDrawRightChrome(KCM_TFT &tft) {
    uint8_t  NR = MNVR_RP_NR;
    uint16_t X  = MNVR_RP_X;
    uint16_t W  = MNVR_RP_W;

    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(0,NR), W, rowHFor(NR), "\xCE\x94V.MNVR",  COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(1,NR), W, rowHFor(NR), "\xCE\x94V.PLAN",  COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(2,NR), W, rowHFor(NR), "\xCE\x94V.STG",   COL_LABEL, COL_BACK, COL_NO_BDR);

    // Divider: ΔV block / timing block
    { uint16_t dy = rowYFor(3,NR) - 1;
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }

    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(3,NR), W, rowHFor(NR), "T+IGN",   COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(4,NR), W, rowHFor(NR), "T+MNVR",  COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, MNVR_RP_LBL, X, rowYFor(5,NR), W, rowHFor(NR), "BURN DUR",COL_LABEL, COL_BACK, COL_NO_BDR);

    // Divider: timing block / alignment block
    { uint16_t dy = rowYFor(6,NR) - 1;
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }

    // Row 6: Nos.Brg | Nos.Elv split
    {
        uint16_t y = rowYFor(6,NR), h = rowHFor(NR), hw = W / 2;
        printDispChrome(tft, MNVR_RP_LBL, X,      y, hw - ROW_PAD, h, "BRG", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, MNVR_RP_LBL, X + hw, y, hw - ROW_PAD, h, "ELV", COL_LABEL, COL_BACK, COL_NO_BDR);
        tft.drawLine(X + hw,     y, X + hw,     y + h - 1, TFT_GREY);
        tft.drawLine(X + hw + 1, y, X + hw + 1, y + h - 1, TFT_GREY);
    }

    // Divider: alignment block / buttons
    { uint16_t dy = rowYFor(7,NR) - 1;
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }

    // RCS | SAS button split line
    uint16_t hw = W / 2;
    tft.drawLine(X + hw,     rowYFor(7,NR), X + hw,     SCREEN_H - 1, TFT_GREY);
    tft.drawLine(X + hw + 1, rowYFor(7,NR), X + hw + 1, SCREEN_H - 1, TFT_GREY);

    // Panel left border
    tft.drawLine(X - 2, TITLE_TOP, X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(X - 1, TITLE_TOP, X - 1, SCREEN_H, TFT_GREY);
}


// ── Update burn vector marker ─────────────────────────────────────────────────────────
// Diamond TFT_BLUE, or TFT_NAVY (half brightness) while pinned at the scope boundary.
// Neon-green alignment box appears when the error is under 5°.
static void _mnvrUpdateMarker(KCM_TFT &tft, float nodeRight, float nodeUp) {
    float errMag  = sqrtf(nodeRight*nodeRight + nodeUp*nodeUp);
    bool  aligned = (errMag < ATT_ERR_WARN_DEG);

    int16_t sx, sy;
    reticleProject(MNVR_GEOM, nodeRight, nodeUp, sx, sy);
    // Pinned = the node is further off the nose than the outer ring can show, so the
    // marker's direction is still honest but its distance understates the real angle.
    // It is drawn at half brightness so it cannot be read as a live value; Brg/Elv
    // carry the true number, now up to +/-180 deg.
    const bool pinned = reticleClampDot(MNVR_GEOM, sx, sy);

    static const uint8_t EH = MNVR_ERASE_R;
    static const uint8_t DS = MNVR_MRK_DS;
    static const uint8_t BX = MNVR_BOX_R;

    bool moved        = (_mnvrPrevMrkX == 9999 ||
                         abs(sx - _mnvrPrevMrkX) > 1 ||
                         abs(sy - _mnvrPrevMrkY) > 1);
    bool alignChanged = (aligned != _mnvrPrevAligned);
    bool pinChanged   = (pinned  != _mnvrPrevPinned);

    if (moved || alignChanged || pinChanged) {
        if (_mnvrPrevMrkX != 9999) {
            tft.fillRect(_mnvrPrevMrkX - EH, _mnvrPrevMrkY - EH, EH*2+1, EH*2+1, TFT_BLACK);
            reticleRepairDotChrome(tft, MNVR_GEOM, _mnvrPrevMrkX - EH, _mnvrPrevMrkY - EH, EH);
        }
        // KSP maneuver marker: dot + three T-capped prongs
        drawManeuverMarker(tft, sx, sy, DS, pinned ? TFT_NAVY : TFT_BLUE);
        // Alignment box — neon green when within 5°
        if (aligned) {
            tft.drawRect(sx - BX,     sy - BX,     BX*2+1, BX*2+1, TFT_NEON_GREEN);
            tft.drawRect(sx - BX - 1, sy - BX - 1, BX*2+3, BX*2+3, TFT_DARK_GREEN);
        }
        _mnvrPrevMrkX    = sx;
        _mnvrPrevMrkY    = sy;
        _mnvrPrevAligned = aligned;
        _mnvrPrevPinned  = pinned;
    }

    // Crosshair always on top
    static const uint16_t g = 18;
    tft.drawLine(MNVR_CX - g + 2, MNVR_CY,       MNVR_CX - 4,       MNVR_CY,       TFT_GREY);
    tft.drawLine(MNVR_CX + 4,     MNVR_CY,       MNVR_CX + g - 2,   MNVR_CY,       TFT_GREY);
    tft.drawLine(MNVR_CX,         MNVR_CY - g+2, MNVR_CX,           MNVR_CY - 4,   TFT_GREY);
    tft.drawLine(MNVR_CX,         MNVR_CY + 4,   MNVR_CX,           MNVR_CY + g-2, TFT_GREY);
    tft.fillCircle(MNVR_CX, MNVR_CY, 2, TFT_GREY);
}


// ── ΔV remaining bar ──────────────────────────────────────────────────────────────────
static void _mnvrDrawDVBar(KCM_TFT &tft, float dvNode, float dvStage) {
    // Layout matches chrome: barY = CY+R+42, lblY = barY-34 (Black_24 label).
    static const uint16_t barY = MNVR_CY + MNVR_R + 42;
    static const uint16_t lblY = barY - 34;

    float    maxDV    = fmaxf(dvStage, dvNode);
    bool     tight    = (dvStage < dvNode * MNVR_DV_MARGIN);
    uint16_t barCol   = tight ? TFT_YELLOW : TFT_DARK_GREEN;
    // The colour depends on stage ΔV as well as the node's, so a staging event with an
    // unchanged node has to repaint too, or the bar and the ΔV.STG row disagree.
    if (fabsf(dvNode - _mnvrPrevDV) < 1.0f && barCol == _mnvrPrevBarCol) return;
    _mnvrPrevDV     = dvNode;
    _mnvrPrevBarCol = barCol;
    float    fraction = (maxDV > 0.0f) ? fminf(dvNode / maxDV, 1.0f) : 0.0f;
    uint16_t fillW    = (uint16_t)(fraction * (MNVR_BAR_W - 2));

    tft.fillRect(MNVR_BAR_X + 1, barY + 1, MNVR_BAR_W - 2, MNVR_BAR_H - 2, TFT_OFF_BLACK);
    if (fillW > 0)
        tft.fillRect(MNVR_BAR_X + 1, barY + 1, fillW, MNVR_BAR_H - 2, barCol);

    // Right-aligned value text in Black_24 (matches "ΔV Burn" label font).
    char buf[14];
    snprintf(buf, sizeof(buf), "%.0fm/s", dvNode);
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(barCol, TFT_BLACK);
    // Clear the value-text region: right half of bar width, 30 px tall (Black_24).
    tft.fillRect(MNVR_BAR_X + MNVR_BAR_W/2, lblY, MNVR_BAR_W/2, 30, TFT_BLACK);
    int16_t tw = getFontStringWidth(&Roboto_Black_24, buf);
    tft.setCursor(MNVR_BAR_X + MNVR_BAR_W - tw, lblY);
    tft.print(buf);
}


// ── CHROME ────────────────────────────────────────────────────────────────────────────
void chromeScreen_MNVR(KCM_TFT &tft) {
    bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f);

    if (!hasMnvr) {
        _mnvrChromDrawn = false;
        tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
        textCenter(tft, &Roboto_Black_72, 0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP,
                   "NO MANEUVER", TFT_WHITE, TFT_RED);
        return;
    }

    _mnvrChromDrawn  = true;
    _mnvrPrevMrkX    = 9999; _mnvrPrevMrkY = 9999;
    _mnvrPrevAligned = false;
    _mnvrPrevPinned  = false;
    _mnvrPrevDV      = -999.0f;   // force ΔV bar + value to repaint on screen entry
    _mnvrPrevBarCol = 0;

    tft.fillRect(0, TITLE_TOP, MNVR_RP_X, SCREEN_H - TITLE_TOP, TFT_BLACK);
    _mnvrDrawReticleChrome(tft);
    _mnvrDrawRightChrome(tft);

    for (uint8_t r = 0; r < ROW_COUNT; r++) printState[MNVR_SC][r] = PrintState{};   // row cache: drawStaticScreen()
}


// ── DRAW (called every loop) ──────────────────────────────────────────────────────────
void drawScreen_MNVR(KCM_TFT &tft) {
    uint32_t _t0 = micros();

    bool hasMnvr = (state.mnvrTime > 0.0f || state.mnvrDeltaV > 0.0f);

    if (!hasMnvr) {
        if (_mnvrChromDrawn) { _mnvrChromDrawn = false; switchToScreen(screen_MNVR); }
        return;
    }
    if (!_mnvrChromDrawn) { switchToScreen(screen_MNVR); return; }

    // ── Derived values ────────────────────────────────────────────────────────────────
    // One boresight projection drives the marker, the alignment box AND the Brg/Elv
    // readouts, so the numbers say exactly where the marker is. These were horizon-frame
    // heading/pitch differences, which inflated with pitch: a node 10 deg off the nose
    // printed 13.8 deg at 45 deg pitch and 62.9 deg at 80 deg while the marker sat
    // correctly on the 10 deg ring.
    const KspBodyAxes _ax = kspBodyAxes(state.heading, state.pitch, state.roll);
    float brgErr, elvErr;
    kspBoresightAngles(_ax, state.mnvrHeading, state.mnvrPitch, brgErr, elvErr);
    float tIgn   = state.mnvrTime - state.mnvrDuration * 0.5f;

    // ── Update reticle marker ─────────────────────────────────────────────────────────
    _mnvrUpdateMarker(tft, brgErr, elvErr);

    // ── Right panel values ────────────────────────────────────────────────────────────
    uint8_t  NR = MNVR_RP_NR;
    uint16_t X  = MNVR_RP_X;
    uint16_t W  = MNVR_RP_W;
    char buf[20];
    uint16_t fg, bg;

    auto mnvrVal = [&](uint8_t row, uint8_t slot, const char *label, const String &val,
                       uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, MNVR_SC, slot, row, X, W, label, val, fgc, bgc, MNVR_RP_F, NR, false);
    };

    // Threshold colouring, matching DOCK/TGT and the reticle rings: green inside the
    // inner ring, yellow out to the middle ring, red beyond. This lambda previously
    // ignored its argument and returned the plain value colour, so MNVR was the one
    // reticle screen whose angle readouts never changed colour at all.
    auto angCol = [](float e, uint16_t &fg, uint16_t &bg) {
        float ae = fabsf(e);
        if      (ae >= ATT_ERR_ALARM_DEG) { fg = TFT_WHITE;      bg = TFT_RED;   }
        else if (ae >= ATT_ERR_WARN_DEG)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                               { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    };

    // Row 0 — ΔV.Mnvr
    mnvrVal(0, 0, "\xCE\x94V.MNVR", fmtMs(state.mnvrDeltaV), TFT_DARK_GREEN, TFT_BLACK);

    // Row 1 — ΔV.Plan (total ΔV across all planned nodes; distinct from vessel total)
    mnvrVal(1, 1, "\xCE\x94V.PLAN", fmtMs(state.mnvrTotalDeltaV), TFT_DARK_GREEN, TFT_BLACK);

    // Row 2 — ΔV.Stg (yellow if stage ΔV is tight relative to node)
    {
        bool tight = (state.stageDeltaV < state.mnvrDeltaV * MNVR_DV_MARGIN);
        mnvrVal(2, 2, "\xCE\x94V.STG", fmtMs(state.stageDeltaV),
                tight ? TFT_YELLOW : TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 3 — T+Ign (time to ignition = node time minus half burn duration)
    {
        if      (tIgn < MNVR_TIGN_ALARM_S) { fg = TFT_WHITE;      bg = TFT_RED;   }   // includes a burn already due
        else if (tIgn < MNVR_TIGN_WARN_S)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                                { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        String val = (state.mnvrDeltaV > 0.0f) ? formatTimeCompact((int64_t)tIgn) : "---";
        mnvrVal(3, 3, "T+IGN", val, fg, bg);
    }

    // Row 4 — T+Mnvr (time to the node itself; yellow once burn should have started)
    {
        if      (state.mnvrTime < 0.0f)                      { fg = TFT_WHITE;      bg = TFT_RED;   }
        else if (state.mnvrTime < state.mnvrDuration * 0.5f) { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                                                   { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        String val = (state.mnvrDeltaV > 0.0f) ? formatTimeCompact((int64_t)state.mnvrTime) : "---";
        mnvrVal(4, 4, "T+MNVR", val, fg, bg);
    }

    // Row 5 — Burn dur
    {
        String val = (state.mnvrDuration > 0.0f) ? formatTimeCompact((int64_t)state.mnvrDuration) : "---";
        mnvrVal(5, 5, "BURN DUR", val, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 6 — Nos.Brg | Nos.Elv split
    {
        uint16_t y6 = rowYFor(6, NR), h6 = rowHFor(NR), hw = W / 2;

        angCol(brgErr, fg, bg);
        // Integer degrees so the value fits the half-cell at the panel's Black_36
        // (a decimal would overflow at large angles).
        snprintf(buf, sizeof(buf), "%+.0f\xB0", brgErr);
        {
            RowCache &rc = rowCache[MNVR_SC][6];
            String sv = buf;
            if (rc.value != sv || rc.fg != fg || rc.bg != bg) {
                printValue(tft, MNVR_RP_F, X,      y6, hw - ROW_PAD, h6,
                           "BRG", sv, fg, bg, COL_BACK, printState[MNVR_SC][6]);
                rc.value = sv; rc.fg = fg; rc.bg = bg;
            }
        }

        angCol(elvErr, fg, bg);
        snprintf(buf, sizeof(buf), "%+.0f\xB0", elvErr);
        {
            RowCache &rc = rowCache[MNVR_SC][7];
            String sv = buf;
            if (rc.value != sv || rc.fg != fg || rc.bg != bg) {
                printValue(tft, MNVR_RP_F, X + hw, y6, hw - ROW_PAD, h6,
                           "ELV", sv, fg, bg, COL_BACK, printState[MNVR_SC][7]);
                rc.value = sv; rc.fg = fg; rc.bg = bg;
            }
        }
    }

    // Row 7 — RCS | SAS buttons (to screen bottom, same height as DOCK)
    {
        uint16_t ry   = rowYFor(7, NR);
        uint16_t rh   = SCREEN_H - ry;
        uint16_t hw   = W / 2;
        uint16_t sasX = X + hw;
        uint16_t sasW = X + W - sasX;

        // RCS (slot 8)
        {
            bool rcsOn = state.rcs_on;
            String rcsStr = rcsOn ? "ON" : "OFF";
            RowCache &rc = rowCache[MNVR_SC][8];
            if (rc.value != rcsStr) {
                ButtonLabel btn = rcsOn
                    ? ButtonLabel{ "RCS", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
                    : ButtonLabel{ "RCS", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
                drawButton(tft, X, ry, hw, rh, btn, MNVR_RP_LBL, false);
                rc.value = rcsStr;
            }
        }

        // SAS (slot 9)
        {
            const char *v; uint16_t sasFg, sasBg;
            switch (state.sasMode) {
                case 255: v = "SAS";  sasFg = TFT_DARK_GREY; sasBg = TFT_OFF_BLACK;  break;
                case 0:   v = "STAB"; sasFg = TFT_BLACK;     sasBg = TFT_SKY;        break;  // acceptable not ideal
                case 1:   v = "PRO";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 2:   v = "RETR"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 3:   v = "NRM";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 4:   v = "ANRM"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 5:   v = "RAD+"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 6:   v = "RAD-"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 7:   v = "TGT";  sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 8:   v = "ATGT"; sasFg = TFT_WHITE;     sasBg = TFT_RED;        break;
                case 9:   v = "MNVR"; sasFg = TFT_WHITE;     sasBg = TFT_DARK_GREEN; break;  // correct
                default:  v = "SAS";  sasFg = TFT_DARK_GREY; sasBg = TFT_OFF_BLACK;  break;
            }
            RowCache &rc = rowCache[MNVR_SC][9];
            String sv = v;
            if (rc.value != sv || rc.fg != sasFg || rc.bg != sasBg) {
                ButtonLabel btn = { v, sasFg, sasFg, sasBg, sasBg, TFT_GREY, TFT_GREY };
                drawButton(tft, sasX, ry, sasW, rh, btn, MNVR_RP_LBL, false);
                rc.value = sv; rc.fg = sasFg; rc.bg = sasBg;
            }
        }
    }

    // ΔV burn remaining bar
    _mnvrDrawDVBar(tft, state.mnvrDeltaV, state.stageDeltaV);

    // Redraw dividers last (printValue fillRects can erase them)
    { uint16_t dy = rowYFor(3,NR) - 1;   // after ΔV block
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }
    { uint16_t dy = rowYFor(6,NR) - 1;
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }
    { uint16_t dy = rowYFor(7,NR) - 1;
      tft.drawLine(X, dy,   X+W, dy,   TFT_GREY);
      tft.drawLine(X, dy+1, X+W, dy+1, TFT_GREY); }
    // Nos.Brg | Nos.Elv vertical split
    { uint16_t hw = W / 2, y6 = rowYFor(6,NR);
      tft.drawLine(X + hw,     y6, X + hw,     y6 + rowHFor(NR) - 1, TFT_GREY);
      tft.drawLine(X + hw + 1, y6, X + hw + 1, y6 + rowHFor(NR) - 1, TFT_GREY); }
    // Panel left border
    tft.drawLine(X - 2, TITLE_TOP, X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(X - 1, TITLE_TOP, X - 1, SCREEN_H, TFT_GREY);

    if (debugMode) {
        uint32_t dt = micros() - _t0;
        Serial.print("MNVR total="); Serial.print((float)dt/1000.0f, 2);
        Serial.print("ms  brg=");    Serial.print(brgErr, 1);
        Serial.print("  elv=");      Serial.print(elvErr, 1);
        Serial.print("  tIgn=");     Serial.println(tIgn, 0);
    }
}

/***************************************************************************************
   Screen_NAV.ino -- Navigation display (mission panel, atmospheric flight)

   The other half of a glass-cockpit pair. Info Display 1 holds the PFD (attitude,
   altitude, speed); this is the plan view beside it — where the vessel is pointed,
   where it is actually going, and where the target is. That pairing is the standard
   airliner arrangement, and it is the one thing the mission panel had nothing to offer
   during atmospheric flight: its fallback was ORBIT, whose apsides and period mean
   nothing to an aircraft.

   Routed to when the vessel is in the atmosphere and its apoapsis is below the top of
   that atmosphere — i.e. flying in the air rather than climbing out of it. A spaceplane
   building apoapsis keeps ORBIT, which is what it wants; see missionContextScreen().

   Layout (940 x 538 content area):

     Compass card, centred        rotating rose, nose fixed at 12 o'clock
       nose triangle              vessel heading, always straight up
       green marker               ground track — where the vessel is actually moving
       violet marker              target bearing (matches the target colour elsewhere)
     Heading box, above the card  HDG, three digits
     Left column                  TRK (ground track), DRIFT (track minus heading)
     Right column                 DIST, V.CLS (closure) and T+INT, when a target is set

   Drift is the one number here that appears nowhere else on either panel: the angle
   between where the nose points and where the vessel is going. In an atmosphere that
   is the crab angle, and it is the difference between a heading that is holding and a
   heading that is quietly sliding off.

   Everything is derived from telemetry the panel already receives — heading,
   srfVelHeading, target bearing and distance, closure. No new Simpit channels.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Geometry ──────────────────────────────────────────────────────────────────────────
// ROVER's card at 1.12x. Every proportion is ROVER's, scaled by one factor, so the two
// screens still read as one instrument family and the shared renderer still drives both
// -- but this screen has no bottom strip to clear, so the card spends the height ROVER
// spends on target distance.
//
// The scale is not a preference, it is what the budget allows. The heading box has to
// clear the title rule (y=62) by 5 px and the ring has to clear the bottom edge, and the
// box hangs off the nose base, which scales with the radius:
//
//   box top    = cy - noseRBase - 6 - NAV_HDG_BOX_H = 370 - 245 - 58 = 67   (rule + 5)
//   ring bottom= cy + rRing                         = 370 + 224      = 594  (edge - 5)
//
// Sizing this card by eye rather than from that budget is how an earlier attempt put the
// heading box at y=57, four pixels into the title rule. Horizontally the ring spans
// 246..694, clearing both 190 px side columns by 56 px.
static const int16_t NAV_CX = CONTENT_W / 2;   // 470
static const int16_t NAV_CY = 370;
static const int16_t NAV_R  = 224;

static const CompassGeom NAV_GEOM = {
  NAV_CX, NAV_CY,
  NAV_R,
  219,          // tick outer  (inside the ring, so tick-erase never touches it)
  199,          // major tick inner
  207,          // minor tick inner
  176, 176,     // letter / numeric label centres
  228, 245, 13, // nose: tip just outside the ring, base beyond it
  143, 123, 13  // bearing markers: inside the label boxes (which reach in to ~152)
};

static const float NAV_HDG_THRESH_DEG = 0.5f;   // card rotates
static const float NAV_MK_THRESH_DEG  = 1.0f;   // marker moved

// Heading readout, above the nose triangle.
static const int16_t NAV_HDG_BOX_W = 110;
static const int16_t NAV_HDG_BOX_H = 52;
static const int16_t NAV_HDG_BOX_X = NAV_CX - (NAV_HDG_BOX_W / 2);
static const int16_t NAV_HDG_BOX_Y = NAV_CY - NAV_GEOM.noseRBase - 6 - NAV_HDG_BOX_H;

// Side columns, same widths as ROVER's so the compass centres between them.
static const int16_t NAV_COL_W    = 190;
static const int16_t NAV_LCOL_X   = 0;
static const int16_t NAV_RCOL_X   = CONTENT_W - NAV_COL_W;   // 750
static const int16_t NAV_COL_Y    = TITLE_TOP;
static const int16_t NAV_BLOCK_H  = 120;
static const int16_t NAV_LBL_H    = 32;
static const int16_t NAV_VAL_H    = 48;

// No bottom strip. It carried V.Srf and Alt.Rdr, and this screen's partner is always
// AIRCRAFT -- the routing rule is the same condition on both panels -- so both numbers
// were on the other display in every phase NAV can appear in, at the same size, while
// the instrument they sat under was 48 px smaller than it needed to be. There is no
// always-available number NAV can show that AIRCRAFT does not: the target group in the
// right column is the whole of what this screen knows and that panel does not.

// ── State ─────────────────────────────────────────────────────────────────────────────
// Reset sentinel for the change-detection caches. It has to differ from every value a
// cell can legitimately hold INCLUDING that cell's own "no value" marker. DRIFT used
// -9999 for both, so entering the screen with no ground track compared equal to the
// reset value and the "---" was never drawn at all -- the cell just stayed black. V.CLS
// had the same collision on -9999, and DIST and T+INT on -1. One sentinel that no cell
// can produce ends the whole class.
static const int16_t NAV_CACHE_RESET16 = INT16_MIN;
static const int32_t NAV_CACHE_RESET32 = INT32_MIN;

static CompassCache       _navCard;
static CompassMarkerCache _navTrkMk;    // ground-track marker
static CompassMarkerCache _navTgtMk;    // target-bearing marker
static int16_t _navPrevHdg      = NAV_CACHE_RESET16;
static int16_t _navPrevTrk      = NAV_CACHE_RESET16;
static int16_t _navPrevDrift    = NAV_CACHE_RESET16;
static int32_t _navPrevDist     = NAV_CACHE_RESET32;
static int16_t _navPrevClose    = NAV_CACHE_RESET16;
static int32_t _navPrevTInt     = NAV_CACHE_RESET32;  // whole seconds; -1 = not closing
static int16_t _navPrevBrg      = NAV_CACHE_RESET16;
static bool    _navTrkLineAvail = false;
static float   _navTrkLineDeg   = 0.0f;

// ── Ground track ──────────────────────────────────────────────────────────────────────
// Where the vessel is actually moving, as opposed to where it is pointed. Only
// meaningful once there is enough surface speed for the velocity vector's heading to be
// stable; below that KSP's reported heading wanders and the marker would spin.
static const float NAV_TRK_MIN_MS = 5.0f;

// ── Track line ────────────────────────────────────────────────────────────────────────
// A stalk from just outside the own-ship symbol out to the ground-track marker, so the
// crab angle is a visible wedge between the nose (fixed at 12 o'clock) and the track,
// rather than only the signed number in the DRIFT cell. DRIFT is the one value on this
// screen that appears nowhere else on either panel, and it was the only one with no
// picture.
//
// This is what the card's interior can carry. The free band is r=78 (the aeroplane's
// furthest painted pixel, a wingtip) to r=123 (where the bearing markers start), and it
// cannot be widened: the rose's label boxes are 33 px tall centred on r=176, so their
// inner corners reach r~150, which is why the markers top out at 143. 45 px is too
// little for range rings -- three decades of log scale would put them 11 px apart -- but
// it is ample for a stalk.
//
// Only the ground track gets one. Two radial lines from a common centre are collinear
// whenever their bearings match, so erasing one would erase the other exactly where they
// overlap and neither would be put back -- the same collision the two markers had. The
// target pointer is a bearing pointer, which conventionally carries no tail anyway.
// The stalk starts at the silhouette's edge ALONG ITS OWN BEARING, found by sampling the
// bitmap, not at a fixed radius. A fixed radius has to clear the wingtips at r=78, but
// along most bearings the aeroplane ends far sooner -- at 22 degrees it ends at r~33 --
// so a fixed start left a 53 px gap and the stalk read as a detached dash instead of a
// line coming off the aircraft. Sampling also guarantees the stalk never overlaps the
// silhouette at any bearing, which is what lets the erase be a plain black repaint: there
// is nothing of the aeroplane under it to repair.
static const int16_t NAV_TRK_LINE_GAP = 5;    // clearance between silhouette and stalk
static const int16_t NAV_TRK_LINE_R1  = 122;  // 1 px short of the marker base at r=123, so
                                              // the stem meets the triangle without ever
                                              // painting a pixel the marker also paints
static const float   NAV_TRK_LINE_HW  = 2.5f; // half width in px (so a 5 px stem)

// ── Own-ship symbol ───────────────────────────────────────────────────────────────────
// A plan-view aircraft at the card centre, nose up. The rose turns around it, which is
// what makes this a moving-map heading-up display rather than a dial: the vessel is
// always here, pointing there. Dimensions are in pixels from the centre.
// The silhouette is a 1-bit bitmap, not a stack of fillTriangles. Two hand-drawn
// attempts came out as arrowheads: a wing is a long thin swept shape and the primitives
// that can express it (quads built from pairs of triangles) still cannot give the
// rounded nose or a clean swept leading edge at this size. tools/nav_ship_bitmap.py
// holds the planform as one normalised outline, mirrors it, supersamples 8x and
// thresholds -- so the artwork is edited as geometry and regenerated, not nudged pixel
// by pixel. Row-major, MSB first, one bit per pixel, row 0 is the nose.
static const int16_t  NAV_SHIP_W      = 138;
static const int16_t  NAV_SHIP_H      = 152;
static const int16_t  NAV_SHIP_STRIDE = 18;
