// ── Marker legend ─────────────────────────────────────────────────────────────────────
// Bottom-left corner, below and outboard of everything else. The two coloured triangles
// on the rose are the only things on this screen with no name attached, and colour alone
// is not a label -- but a legend is reference material, read once and then not again, so
// it sits where the eye goes last and in the smallest font on the screen rather than
// competing with the readouts. The corner is free: at y=536 the ring's left edge is at
// x=313 and it only moves right from there as the rows go down.
static const int16_t NAV_KEY_X  = 10;
static const int16_t NAV_KEY_Y  = 536;
static const int16_t NAV_KEY_DY = 30;
static const int16_t NAV_KEY_H  = 28;
static const int16_t NAV_KEY_TRI_W = 13;
static const int16_t NAV_KEY_TRI_H = 11;

static inline bool _navHasTrack() { return state.surfaceVel >= NAV_TRK_MIN_MS; }


// Plan-view aircraft at the card centre. Static: the rose rotates around it, so it is
// chrome and never needs erasing. Own-ship is white by convention.
//
// The wings are quads, not triangles. A triangle from the fuselage out to the tip fills
// in toward the tip and reads as an arrowhead -- the first attempt looked like a dart.
// A wing is a long thin shape with a root chord, a tip chord and some sweep, and that is
// four points, so it is drawn as two triangles.
static void _navDrawOwnShip(KCM_TFT &tft) {
  const int16_t x0 = NAV_CX - NAV_SHIP_W / 2;
  const int16_t y0 = NAV_CY - NAV_SHIP_H / 2;
  // Blit as horizontal runs. Every row of this silhouette is one or three runs, so the
  // whole symbol is a couple of hundred hardware fills -- cheaper than a per-pixel loop
  // and it never touches the background, which the rotating card owns.
  for (int16_t row = 0; row < NAV_SHIP_H; row++) {
    const uint8_t *p = &NAV_SHIP_BMP[row * NAV_SHIP_STRIDE];
    int16_t run = -1;
    for (int16_t col = 0; col <= NAV_SHIP_W; col++) {
      const bool on = (col < NAV_SHIP_W) && ((p[col >> 3] >> (7 - (col & 7))) & 1u);
      if (on && run < 0) run = col;
      else if (!on && run >= 0) {
        tft.fillRect(x0 + run, y0 + row, col - run, 1, TFT_WHITE);
        run = -1;
      }
    }
  }
}

// Is (x, y) inside the own-ship silhouette? Screen coordinates in, bitmap bit out.
static bool _navShipPixel(int16_t x, int16_t y) {
  const int16_t bx = x - (NAV_CX - NAV_SHIP_W / 2);
  const int16_t by = y - (NAV_CY - NAV_SHIP_H / 2);
  if (bx < 0 || by < 0 || bx >= NAV_SHIP_W || by >= NAV_SHIP_H) return false;
  return (NAV_SHIP_BMP[by * NAV_SHIP_STRIDE + (bx >> 3)] >> (7 - (bx & 7))) & 1u;
}

// Radius at which the silhouette ends along a screen bearing: the LAST set pixel walking
// outward, not the first clear one, because a ray can leave the fuselage and re-enter at
// the wing.
static int16_t _navShipEdgeR(float screenDeg) {
  const int16_t rMax = (NAV_SHIP_W > NAV_SHIP_H ? NAV_SHIP_W : NAV_SHIP_H) / 2 + 2;
  int16_t last = 0;
  for (int16_t r = 4; r <= rMax; r++) {
    int16_t x, y;
    compassPolar(NAV_GEOM, screenDeg, r, x, y);
    if (_navShipPixel(x, y)) last = r;
  }
  return last;
}

// Draw or erase the track stalk at a screen bearing. Erasing repaints the identical
// Bresenham path in black, which is exact, and nothing else is painted in this band --
// the aeroplane stops at r=78 and the markers start at 123 -- so a black erase cannot
// damage anything it did not draw.
static void _navDrawTrackLine(KCM_TFT &tft, float screenDeg, bool erase) {
  const int16_t r0 = _navShipEdgeR(screenDeg) + NAV_TRK_LINE_GAP;
  if (r0 >= NAV_TRK_LINE_R1) return;
  int16_t x0, y0, x1, y1;
  compassPolar(NAV_GEOM, screenDeg, r0, x0, y0);
  compassPolar(NAV_GEOM, screenDeg, NAV_TRK_LINE_R1, x1, y1);

  // Filled quad, not a bundle of parallel lines. Offsetting several Bresenham lines by a
  // rounded perpendicular gives uneven spacing on a diagonal -- at 22 degrees the offsets
  // land on (1,0) and (2,1), so the stem came out stippled along both edges. Two
  // triangles give clean edges at any bearing and make the width a single float.
  const float dx = (float)(x1 - x0), dy = (float)(y1 - y0);
  const float len = sqrtf(dx * dx + dy * dy);
  if (len < 1.0f) return;
  const float ox = -dy / len * NAV_TRK_LINE_HW;
  const float oy =  dx / len * NAV_TRK_LINE_HW;
  const int16_t ax = (int16_t)lroundf((float)x0 + ox), ay = (int16_t)lroundf((float)y0 + oy);
  const int16_t bx = (int16_t)lroundf((float)x0 - ox), by = (int16_t)lroundf((float)y0 - oy);
  const int16_t cx2 = (int16_t)lroundf((float)x1 - ox), cy2 = (int16_t)lroundf((float)y1 - oy);
  const int16_t dx2 = (int16_t)lroundf((float)x1 + ox), dy2 = (int16_t)lroundf((float)y1 + oy);

  const uint16_t col = erase ? TFT_BLACK : TFT_NEON_GREEN;
  tft.fillTriangle(ax, ay, bx, by, cx2, cy2, col);
  tft.fillTriangle(ax, ay, cx2, cy2, dx2, dy2, col);
}


// Kept in step with the triangle it is the tail of.
//
// The angle comes from the marker's OWN cache, not from the live bearing, and the test is
// exact equality rather than a movement threshold. Both matter: compassUpdateMarkerPair()
// redraws BOTH markers whenever EITHER has changed, so the ground-track triangle follows
// sub-threshold bearing changes any time the target marker moves. The stalk, testing its
// own threshold against the live bearing, did not -- so the head walked away from the
// body by up to a degree, which at r=123 is two pixels of lateral offset. That is the
// separation the bench saw.
//
// `force` covers the other half: a marker's erase box is padded 3 px past its triangle
// and so reaches r~120, one pixel into the stalk's top. Whenever the pair redrew anything
// the stalk is redrawn too, whether or not its own angle changed.
static void _navUpdateTrackLine(KCM_TFT &tft, bool avail, float screenDeg, bool force) {
  const bool moved = _navTrkLineAvail && (screenDeg != _navTrkLineDeg);
  if (avail == _navTrkLineAvail && !moved && !force) return;

  if (_navTrkLineAvail) _navDrawTrackLine(tft, _navTrkLineDeg, true);
  if (avail) { _navDrawTrackLine(tft, screenDeg, false); _navTrkLineDeg = screenDeg; }
  _navTrkLineAvail = avail;
}

// One legend row: the marker's own triangle, then its name in the marker's colour.
static void _navKeyRow(KCM_TFT &tft, int16_t y, uint16_t colour, const char *name) {
  const int16_t w = NAV_KEY_TRI_W, h = NAV_KEY_TRI_H;
  const int16_t cyRow = y + NAV_KEY_H / 2;
  tft.fillTriangle(NAV_KEY_X + w / 2, cyRow - h / 2,
                   NAV_KEY_X,         cyRow + h / 2,
                   NAV_KEY_X + w,     cyRow + h / 2, colour);
  textLeft(tft, &Roboto_Black_16, NAV_KEY_X + w - 6, y, 160, NAV_KEY_H, name, colour, TFT_BLACK);
}

/***************************************************************************************
   CHROME — drawn once on screen entry
****************************************************************************************/
void chromeScreen_NAV(KCM_TFT &tft) {
  compassDrawRing(tft, NAV_GEOM);
  compassDrawNose(tft, NAV_GEOM);
  _navDrawOwnShip(tft);

  // Heading box: border is chrome, the value redraws on change.
  tft.drawRect(NAV_HDG_BOX_X, NAV_HDG_BOX_Y, NAV_HDG_BOX_W, NAV_HDG_BOX_H, TFT_GREY);

  // Column labels.
  textCenter(tft, &Roboto_Black_24, NAV_LCOL_X, NAV_COL_Y, NAV_COL_W, NAV_LBL_H,
             "TRK", KDC_LABEL_COLOR, TFT_BLACK);
  textCenter(tft, &Roboto_Black_24, NAV_LCOL_X, NAV_COL_Y + NAV_BLOCK_H, NAV_COL_W, NAV_LBL_H,
             "DRIFT", KDC_LABEL_COLOR, TFT_BLACK);
  // BRG completes the set: every marker on the card has a number. The nose is HDG in the
  // box above it, the green marker is TRK, the violet one is BRG. Column headings are all
  // the panel-wide label grey -- the legend in the corner is what ties a name to a marker
  // colour, so the headings do not have to carry it too.
  textCenter(tft, &Roboto_Black_24, NAV_LCOL_X, NAV_COL_Y + 2 * NAV_BLOCK_H, NAV_COL_W, NAV_LBL_H,
             "BRG", KDC_LABEL_COLOR, TFT_BLACK);
  textCenter(tft, &Roboto_Black_24, NAV_RCOL_X, NAV_COL_Y, NAV_COL_W, NAV_LBL_H,
             "DIST", KDC_LABEL_COLOR, TFT_BLACK);
  // V.CLOSE, not V.CLS: this screen's column heads are all-caps, but the token itself is
  // the one SPACECRAFT, DOCKING and TARGET already use for closure rate. Case is a
  // layout choice; a different abbreviation would be a second name.
  textCenter(tft, &Roboto_Black_24, NAV_RCOL_X, NAV_COL_Y + NAV_BLOCK_H, NAV_COL_W, NAV_LBL_H,
             "V.CLOSE", KDC_LABEL_COLOR, TFT_BLACK);
  // Third block completes the target group: how far, how fast, how long.
  textCenter(tft, &Roboto_Black_24, NAV_RCOL_X, NAV_COL_Y + 2 * NAV_BLOCK_H, NAV_COL_W, NAV_LBL_H,
             "T+INT", KDC_LABEL_COLOR, TFT_BLACK);

  // Marker legend, under the left column.
  _navKeyRow(tft, NAV_KEY_Y,              TFT_NEON_GREEN, "TRK  GND TRACK");
  _navKeyRow(tft, NAV_KEY_Y + NAV_KEY_DY, TFT_VIOLET,     "BRG  TO TARGET");

  // Force every value to repaint on the first frame after entry.
  _navCard = CompassCache();
  _navTrkMk = CompassMarkerCache();
  _navTgtMk = CompassMarkerCache();
  _navTrkLineAvail = false;
  _navPrevHdg = _navPrevTrk = _navPrevDrift = NAV_CACHE_RESET16;
  _navPrevClose = _navPrevBrg = NAV_CACHE_RESET16;
  _navPrevDist  = _navPrevTInt = NAV_CACHE_RESET32;
}


/***************************************************************************************
   PER-FRAME UPDATE
****************************************************************************************/
void drawScreen_NAV(KCM_TFT &tft) {
  const float hdg = state.heading;

  // ── Compass card ───────────────────────────────────────────────────────────────────
  // The markers are NOT re-stamped when the card rotates, and their caches are left
  // alone. An earlier version cleared prevAvail here, on the premise that the card's
  // tick and label redraw passes through the band the markers occupy. It does not: the
  // ticks erase along r=199..219 and the label boxes are centred on r=176 (so ~164..188),
  // while the markers live at r=123..143 -- a clear 21 px inside the nearest of them.
  // Clearing prevAvail therefore suppressed compassUpdateMarker()'s erase of a marker
  // that nothing else was erasing, and every rotation left one behind. That is where the
  // green and violet trails came from.
  compassUpdateCard(tft, NAV_GEOM, _navCard, hdg, NAV_HDG_THRESH_DEG);

  // ── Bearing markers ────────────────────────────────────────────────────────────────
  // Updated as a pair. They share one annulus, so one's erase box passes over the other
  // as the card turns -- see compassUpdateMarkerPair().
  const bool  hasTrk = _navHasTrack();
  const float trkScreenDeg = hasTrk ? eadiHdgDelta(state.srfVelHeading, hdg) : 0.0f;
  const bool  hasTgt = state.targetAvailable;
  const float tgtScreenDeg = hasTgt ? eadiHdgDelta(state.tgtHeading, hdg) : 0.0f;
  const bool markersRedrawn =
      compassUpdateMarkerPair(tft, NAV_GEOM,
                              _navTrkMk, hasTrk, trkScreenDeg, TFT_NEON_GREEN,
                              _navTgtMk, hasTgt, tgtScreenDeg, TFT_VIOLET,
                              NAV_MK_THRESH_DEG);
  _navUpdateTrackLine(tft, _navTrkMk.prevAvail, _navTrkMk.prevScreenDeg, markersRedrawn);

  // ── Heading readout ────────────────────────────────────────────────────────────────
  {
    int16_t h = (int16_t)lroundf(hdg) % 360;
    if (h < 0) h += 360;
    if (h != _navPrevHdg) {
      _navPrevHdg = h;
      char buf[8];
      snprintf(buf, sizeof(buf), "%03d\xB0", h);
      tft.fillRect(NAV_HDG_BOX_X + 2, NAV_HDG_BOX_Y + 2,
                   NAV_HDG_BOX_W - 4, NAV_HDG_BOX_H - 4, TFT_BLACK);
      // Dark green, the house colour for a nominal readout -- the same colour ASCENT's
      // heading box uses. White here was the odd one out across the panel.
      textCenter(tft, &Roboto_Black_36, NAV_HDG_BOX_X, NAV_HDG_BOX_Y,
                 NAV_HDG_BOX_W, NAV_HDG_BOX_H, buf, TFT_DARK_GREEN, TFT_BLACK);
    }
  }

  // ── TRK — ground track, or dashes when too slow to be meaningful ───────────────────
  {
    int16_t t = -1;
    if (hasTrk) {
      t = (int16_t)lroundf(state.srfVelHeading) % 360;
      if (t < 0) t += 360;
    }
    if (t != _navPrevTrk) {
      _navPrevTrk = t;
      char buf[8];
      if (t < 0) snprintf(buf, sizeof(buf), "---");
      else       snprintf(buf, sizeof(buf), "%03d\xB0", t);
      tft.fillRect(NAV_LCOL_X, NAV_COL_Y + NAV_LBL_H, NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_LCOL_X, NAV_COL_Y + NAV_LBL_H,
                 NAV_COL_W, NAV_VAL_H, buf,
                 (t < 0) ? TFT_DARK_GREY : TFT_NEON_GREEN, TFT_BLACK);
    }
  }

  // ── DRIFT — track minus heading, the crab angle ────────────────────────────────────
  // Yellow past NAV_DRIFT_WARN_DEG: in an atmosphere a large crab angle is either a
  // strong crosswind-equivalent or a vessel that is not going where it is pointed.
  {
    int16_t d = -9999;
    if (hasTrk) d = (int16_t)lroundf(eadiHdgDelta(state.srfVelHeading, hdg));
    if (d != _navPrevDrift) {
      _navPrevDrift = d;
      char buf[10];
      if (d == -9999) snprintf(buf, sizeof(buf), "---");
      else            snprintf(buf, sizeof(buf), "%+d\xB0", d);
      uint16_t fg = (d == -9999)             ? TFT_DARK_GREY
                  : (abs(d) >= NAV_DRIFT_WARN_DEG) ? TFT_YELLOW
                                             : TFT_DARK_GREEN;
      tft.fillRect(NAV_LCOL_X, NAV_COL_Y + NAV_BLOCK_H + NAV_LBL_H,
                   NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_LCOL_X, NAV_COL_Y + NAV_BLOCK_H + NAV_LBL_H,
                 NAV_COL_W, NAV_VAL_H, buf, fg, TFT_BLACK);
    }
  }

  // ── BRG — bearing to target, the violet marker's own number ────────────────────────
  {
    int16_t b = -1;
    if (hasTgt) {
      b = (int16_t)lroundf(state.tgtHeading) % 360;
      if (b < 0) b += 360;
    }
    if (b != _navPrevBrg) {
      _navPrevBrg = b;
      char buf[8];
      if (b < 0) snprintf(buf, sizeof(buf), "---");
      else       snprintf(buf, sizeof(buf), "%03d\xB0", b);
      const int16_t y = NAV_COL_Y + 2 * NAV_BLOCK_H + NAV_LBL_H;
      tft.fillRect(NAV_LCOL_X, y, NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_LCOL_X, y, NAV_COL_W, NAV_VAL_H, buf,
                 (b < 0) ? TFT_DARK_GREY : TFT_VIOLET, TFT_BLACK);
    }
  }

  // ── DIST — range to target ─────────────────────────────────────────────────────────
  {
    int32_t dist = hasTgt ? (int32_t)lroundf(state.tgtDistance) : -1;
    if (dist != _navPrevDist) {
      _navPrevDist = dist;
      tft.fillRect(NAV_RCOL_X, NAV_COL_Y + NAV_LBL_H, NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_RCOL_X, NAV_COL_Y + NAV_LBL_H,
                 NAV_COL_W, NAV_VAL_H,
                 hasTgt ? formatAlt(state.tgtDistance) : String("---"),
                 hasTgt ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
    }
  }

  // ── V.CLS — closure rate, negative closing (same sign convention as TGT/DOCK) ──────
  {
    // Keyed on tenths, which is what fmtMs prints; a whole-metre key froze the decimal.
    int16_t c = hasTgt ? (int16_t)lroundf(state.tgtVelocity * 10.0f) : -9999;
    if (c != _navPrevClose) {
      _navPrevClose = c;
      tft.fillRect(NAV_RCOL_X, NAV_COL_Y + NAV_BLOCK_H + NAV_LBL_H,
                   NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_RCOL_X, NAV_COL_Y + NAV_BLOCK_H + NAV_LBL_H,
                 NAV_COL_W, NAV_VAL_H,
                 hasTgt ? fmtMs(state.tgtVelocity) : String("---"),
                 hasTgt ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
    }
  }

  // ── T+INT — time to intercept, distance over closure rate ──────────────────────────
  // The same quantity, the same formula and the same label as TARGET's T+Int row: only
  // meaningful while actually closing, dashed otherwise. DIST and V.CLS were already
  // here and neither answers "how long"; on an approach that is the number being flown
  // to, and it is nowhere on this panel's partner.
  {
    const bool closing = hasTgt && (state.tgtVelocity < -0.5f);
    int32_t t = closing ? (int32_t)(state.tgtDistance / fabsf(state.tgtVelocity)) : -1;
    if (t != _navPrevTInt) {
      _navPrevTInt = t;
      const int16_t y = NAV_COL_Y + 2 * NAV_BLOCK_H + NAV_LBL_H;
      tft.fillRect(NAV_RCOL_X, y, NAV_COL_W, NAV_VAL_H, TFT_BLACK);
      textCenter(tft, &Roboto_Black_36, NAV_RCOL_X, y, NAV_COL_W, NAV_VAL_H,
                 closing ? formatTimeCompact((float)t) : String("---"),
                 closing ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
    }
  }

}

/***************************************************************************************
   Screen_ORB.ino  —  Orbit display (left panel) + Inclination display (right panel)

   ── Architecture (v2 — three-layer redraw) ─────────────────────────────────────────
   Three layers, three different update strategies. Trying to use one strategy for all
   of them is what broke the previous implementation.

     LAYER 1 — Static chrome
       Panel divider, title labels, readout strip labels. Drawn once in
       chromeScreen_ORB, never touched again.

     LAYER 2 — Orbit scene (ellipse/hyperbola, body, atmosphere, Pe/Ap/AN/DN markers,
                            SOI ring, INCL orbit line + body)
       Treated as a single indivisible unit. A "scene signature" is computed each
       frame from the parameters that affect drawing. When the signature changes,
       the entire panel rect is fillRect-ed to black and the whole scene is redrawn
       from scratch. No per-element erase, no cached pixel positions for markers, no
       black-tracing ellipses.

       Quantization is the hysteresis — scene changes fire only when a quantized
       field flips, not on floating-point jitter. (A minimum repaint interval used
       to sit on top of that; the double buffer made it unnecessary.)

       PLAN panel and INCL panel share one signature and repaint together.

     LAYER 3 — Vessel dot (both panels)
       Small filled circle — the one shape where sprite-erase works cleanly.
       fillCircle(TFT_BLACK) on the cached previous position, redraw a short
       3-segment arc of the orbit curve locally to patch the erased line, then
       draw the new dot. Updates every frame independently of Layer 2.

   ── Geometry (unchanged from v1) ───────────────────────────────────────────────────
   Left panel — Orbit shape (ORBIT):
     Ellipse CENTRE at (ORB_PCX, ORB_CY). a_px = MAX_R always.
     b_px = MAX_R * sqrt(1-e²).  Body (focus) offset from centre by a*ecc toward Pe.
     Pe always MAX_R from centre (in argOfPe direction).
     Ap always MAX_R from centre (in argOfPe+180 direction).
     Body position: focusX = ORB_PCX + MAX_R*ecc*cos(argOfPe)
                    focusY = ORB_CY  - MAX_R*ecc*sin(argOfPe)
     Body pixel scale: body_px = (bodyR_m / sma_m) * MAX_R

   Escape geometry:
     Body at (ORB_PCX, ORB_CY). Scale = 3x body radius = panel half-extent.
     Switches to SOI view when altSL > 2*bodyR.

   Right panel — Orbital inclination (INCL):
     Edge-on view. Equatorial plane = dashed horizontal at ORB_CY.
     Orbit line through body centre at angle = inclination. Draw order is
     equator -> body disc -> orbit line, so the line runs unbroken in front of
     the body — the same "orbit line on top" rule the planar panel follows.
     AN (TFT_CYAN) at upper-right end (matches planar view where AN is east/right).
     DN (TFT_YELLOW) at lower-left end.
     Vessel (TFT_NEON_GREEN) at sin(argPe+nu)*INC_L along the orbit line.

   Orbit colour:  Green=normal  Yellow=Pe/Ap in atmo or underground  Orange=escape
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// ── Layout ────────────────────────────────────────────────────────────────────────────
static const uint16_t ORB_TITLE_TOP  = TITLE_TOP;
static const uint16_t ORB_SCREEN_H   = SCREEN_H;  // full panel height (rev-2 1024x600)
static const uint16_t ORB_MAX_R      = 170;   // orbit half-extent (pixels)

// rev-2: the two graphical elements each fill half of the 940px-wide content
// area. Divider at x=470. PLAN occupies x=[0,470] (centre 235); INCL occupies
// x=[470,940] (centre 705). Shared vertical centre at y=265, below the header
// strip and above the bottom readout strip (y=448..). The graphics were
// trimmed again to make room for the larger (Roboto_Black_28) readout text at
// the bottom and the larger (Roboto_Black_32) SOI body name up top.
static const int16_t  ORB_PCX = 235;
static const int16_t  ORB_CY  = 265;

// Header strip — protected from scene repaints, which fillRect below it. Holds the
// SOI body name. Laid at y=62..92.
static const int16_t  HDR_Y0   = TITLE_TOP;   // top of header strip
static const int16_t  HDR_Y1   = 92;   // bottom of header strip

// PLAN panel drawing bounds vs. erase bounds:
//   PLAN_Y0/PLAN_Y1      — drawing bounds (markers, dots, visibility checks).
//   PLAN_FILL_Y0         — erase top edge for scene repaint (= HDR_Y0).
//                          Wider than the drawing bounds so atmo/body pixels
//                          that naturally extend up into the header strip get
//                          erased cleanly. The chrome labels are re-drawn
//                          inside the repaint function after the fillRect.
//   PLAN_CLIP_Y0/Y1      — inset for marker LABEL placement so labels don't
//                          drift above the drawing area.
static const int16_t  PLAN_X0  = 6,   PLAN_X1 = 468;
static const int16_t  PLAN_Y0  = HDR_Y1;       // 92 — drawing bound
// 441, the same bound the INCL panel uses, so the two halves stop level. This is not a
// free constant: the PLAN scene repaint fillRects from PLAN_FILL_Y0 down to PLAN_Y1, and
// marker labels are clamped to PLAN_Y1-6 and drawn 9 px above their anchor with a 19 px
// cap, so the lowest label pixel lands at PLAN_Y1+4. It was 478 because the readout strip
// used to start at 485. The strip now starts at 448, so the bound moves with it -- left
// at 478 the repaint wiped the new top row's label on every scene change, which is
// exactly what the harness caught. The ellipse itself only reaches y=435 (ORB_CY + MAX_R),
// so nothing graphical is lost.
static const int16_t  PLAN_Y1  = 441;
static const int16_t  PLAN_FILL_Y0 = HDR_Y0;   // 62 — wide erase bound
static const int16_t  PLAN_CLIP_Y0 = HDR_Y1 + 2;   // 94
static const int16_t  PLAN_CLIP_Y1 = PLAN_Y1 - 2;  // 439

// Readout strip (bottom-left of PLAN panel, Roboto_Black_28, rows 37px apart)
// PLAN readout strip. Four rows now, matching the INCL side -- the top slot at y=448
// was simply empty before, while the right-hand strip already used it for Inc.
//
// SMA and Ecc are promoted from ORBIT ADVANCED, and they are not arbitrary picks: they
// are the PLAN diagram's own two parameters. The ellipse is drawn with a_px = MAX_R
// ALWAYS -- the picture is normalised, so it deliberately cannot show orbit size -- and
// b_px = MAX_R * sqrt(1-e^2), so eccentricity is literally what gives it its shape. SMA
// restores the dimension the normalisation throws away; Ecc names the one it draws.
//
// They replace Alt.SL, which was duplicated on this panel's partner. ORBIT is the mission
// panel's resting state, so its partner is SPACECRAFT in every phase it appears in, and
// that screen carries Alt.SL at the same size. PeA and ApA are duplicated there too and
// stay regardless: they are the magenta and blue LABELS for the two apsis markers, drawn
// in the markers' own colours, and a picture of an orbit with unnamed apsides is worse
// than a repeated number. Alt.SL had no such pairing -- its white label named the green
// vessel dot only by inference.
//
// Same labels and same formats as ORBIT ADVANCED (formatAlt / four decimal places), and
// the same order as that screen's left column, so one quantity does not acquire a second
// name or a second precision by moving one screen over.
static const uint16_t ORB_RDY0 = 448;  // SMA row
static const uint16_t ORB_RDY1 = 485;  // Ecc row
static const uint16_t ORB_RDY2 = 522;  // Pe row
static const uint16_t ORB_RDY3 = 559;  // Ap row

// ── INCL panel layout (right half, x=[470,940]) ───────────────────────────────────────
static const int16_t  INC_CX   = 705;  // panel centre x
// Orbit line half-length. At 90° inclination the line extends bodyCY ± INC_L =
// 265 ± 160 = 105..425, clearing both the header strip (bottom y=92) and the
// 4-row readout strip below (top row = Inc at y=448).
static const uint16_t INC_L    = 160;
static const uint16_t INC_BR   =  24;  // body disc radius (px)

static const int16_t  INCL_X0 = 476, INCL_X1 = 938;
static const int16_t  INCL_Y0 = HDR_Y1;
// INCL panel extends down only to y=441 to leave space for the 4-row readout
// strip below (top row = Inc at y=448). PLAN panel has 3 rows (y=485..559).
static const int16_t  INCL_Y1 = 441;
// The INCL graphic never rises above y=105 near centre, but the enlarged SOI
// body name (Roboto_Black_32) now reaches down to ~y=102 on the right; it is
// re-drawn after every INCL scene repaint (see _orbRepaintIncl) so the fillRect
// can't leave it clipped.
static const int16_t  INCL_FILL_Y0 = INCL_Y0;
static const int16_t  INCL_CLIP_Y0 = HDR_Y1 + 2;
static const int16_t  INCL_CLIP_Y1 = INCL_Y1 - 2;

// Readout strip (bottom-right, Roboto_Black_28, rows 37px apart)
// Order: Inc (4th row, top) / PRD / Arg.Pe / T+Pe or T+Ap
static const uint16_t INC_RDY0 = 448;  // Inc (inclination) row — top
static const uint16_t INC_RDY1 = 485;  // PRD (period) row
static const uint16_t INC_RDY2 = 522;  // Arg.Pe row
static const uint16_t INC_RDY3 = 559;  // T+Pe or T+Ap row
static const uint16_t INC_LABEL_X = 480;
static const uint16_t INC_VALUE_X = 590;

// ── Body parameters ───────────────────────────────────────────────────────────────────
// Body colors are NOT stored here — see kspBodyColor() / kspAtmoColor() in
// AAA_Screens.ino. ORB and LNCH (Circularization) both use those shared lookups,
// so a body-color tweak only needs to happen in one place.
struct OrbBody {
    const char *name;
    float    radius_m;
    float    atmo_m;
    float    soi_m;       // sphere of influence radius (0 = no limit, e.g. Kerbol)
};

static const OrbBody ORB_BODIES[] = {
    { "Kerbol",261600000.0f,     0.0f,          0.0f },  // 0
    { "Moho",    250000.0f,     0.0f,    9646663.0f },  // 1
    { "Eve",     700000.0f, 90000.0f,   85109365.0f },  // 2
    { "Gilly",    13000.0f,     0.0f,     126123.0f },  // 3
    { "Kerbin",  600000.0f, 70000.0f,   84159286.0f },  // 4
    { "Mun",     200000.0f,     0.0f,    2429559.0f },  // 5
    { "Minmus",   60000.0f,     0.0f,    2247428.0f },  // 6
    { "Duna",    320000.0f, 50000.0f,   47921949.0f },  // 7
    { "Ike",     130000.0f,     0.0f,    1049599.0f },  // 8
    { "Dres",    138000.0f,     0.0f,   32832840.0f },  // 9
    { "Jool",   6000000.0f,200000.0f, 2455985200.0f },  // 10
    { "Laythe",  500000.0f, 50000.0f,    3723645.0f },  // 11
    { "Vall",    300000.0f,     0.0f,    2406401.0f },  // 12
    { "Tylo",    600000.0f,     0.0f,   10856518.0f },  // 13
    { "Bop",      65000.0f,     0.0f,    1221061.0f },  // 14
    { "Pol",      44000.0f,     0.0f,    1042138.0f },  // 15
    { "Eeloo",   210000.0f,     0.0f,  119082942.0f },  // 16
};

// ── Tuning constants ──────────────────────────────────────────────────────────────────
// Scene-signature quantization bin sizes (produce hysteresis).
static const float SIG_ARGPE_DEG  = 1.0f;     // 1° bins
static const float SIG_ECC        = 0.01f;    // 0.01 bins
static const float SIG_INCL_DEG   = 0.5f;     // 0.5° bins
static const float SIG_APS_FRAC   = 0.01f;    // 1% of SMA bins

// rev-2: the minimum-interval (2 Hz) scene-repaint throttle was removed. The
// scene now repaints as soon as the quantized signature above changes; the bins
// still provide dead-band hysteresis so float jitter alone won't trigger it.

// Vessel-dot pixel movement threshold before redraw.
static const int VESSEL_PX_THRESH = 2;

// Debug timing output — one line per scene repaint, one line per N vessel updates.
static const uint32_t DBG_VESSEL_EVERY = 20;  // log one vessel timing per 20 updates

// ── Scene signature ───────────────────────────────────────────────────────────────────
// All fields that can affect what gets drawn in a given panel.
// Quantized where continuous so signature equality = "nothing visually different".
struct OrbSceneSig {
    uint8_t  bodyIdx;
    bool     isEscape;
    bool     useSoiView;
    uint16_t orbitCol;
    int16_t  argPe_q;     // argOfPe / SIG_ARGPE_DEG
    int16_t  ecc_q;       // ecc     / SIG_ECC
    int16_t  incl_q;      // incl    / SIG_INCL_DEG
    int16_t  rPe_q;       // (rPe / sma) / SIG_APS_FRAC, clamped
    int16_t  rAp_q;       // (rAp / sma) / SIG_APS_FRAC, clamped  (-1 for escape)

    bool operator==(const OrbSceneSig &o) const {
        return bodyIdx == o.bodyIdx && isEscape == o.isEscape
            && useSoiView == o.useSoiView && orbitCol == o.orbitCol
            && argPe_q == o.argPe_q && ecc_q == o.ecc_q
            && incl_q == o.incl_q && rPe_q == o.rPe_q && rAp_q == o.rAp_q;
    }
    bool operator!=(const OrbSceneSig &o) const { return !(*this == o); }
};

// Full numeric scene state — everything the draw functions need.
// Recomputed each frame from AppState. Stored on a scene repaint so vessel
// updates can reference the same geometry that the scene was drawn with.
struct OrbScene {
    // Derived shape
    float    ecc;
    float    argOfPe_rad;
    float    sma_m;
    float    rPe_m;
    float    bodyR_m;
    float    atmoH_m;
    float    r_pe_px;       // Pe radius in pixels (escape only; ORB_MAX_R for ellipse)
    uint16_t body_px;
    uint16_t atmo_px;
    int16_t  focusX, focusY;
    bool     isEscape;
    bool     useSoiView;
    float    soi_m;
    uint16_t bodyCol;
    uint16_t atmoCol;
    uint16_t orbitCol;
    uint8_t  bodyIdx;
    // INCL geometry
    float    incl_deg;
    int16_t  bodyCY;        // INCL body centre y (matched to planar focusY)
    float    dx, dy;        // INCL orbit line half-extents
};

// ── Forward declarations ──────────────────────────────────────────────────────────────
// Arduino IDE's auto-prototype generator (ctags) runs BEFORE the types above are
// visible, so any function that takes OrbScene / OrbSceneSig by reference will
// have a broken auto-generated prototype. Providing explicit prototypes here
// suppresses the auto-generation. Do not remove.
static void        _orbComputeScene(OrbScene &sc);
static OrbSceneSig _orbSceneSig(const OrbScene &sc);
static void        _orbDrawSOIView(KCM_TFT &tft, const OrbScene &sc);
static void        _orbDrawMarkers(KCM_TFT &tft, const OrbScene &sc);
static void        _orbDrawMarkerDotsOnly(KCM_TFT &tft, const OrbScene &sc);
static void        _orbDrawIncl(KCM_TFT &tft, const OrbScene &sc);
static bool        _orbVesselPxPlan(const OrbScene &sc, float nu_rad,
                                    int16_t &out_x, int16_t &out_y);
static void        _orbPatchArcPlan(KCM_TFT &tft, const OrbScene &sc, float nu_rad);
static void        _orbRepaintPlan(KCM_TFT &tft, const OrbScene &sc);
static void        _orbRepaintIncl(KCM_TFT &tft, const OrbScene &sc);

// ── Geometry helpers ──────────────────────────────────────────────────────────────────
static void _orbEllipseShape(float PeA_m, float ApA_m, float bodyR_m,
                              float &sma_m, float &ecc) {
    float rPe = fmaxf(PeA_m + bodyR_m, 1.0f);
    float rAp = fmaxf(ApA_m + bodyR_m, rPe);
    sma_m = (rPe + rAp) * 0.5f;
    ecc   = (rAp - rPe) / (rAp + rPe);
}

static void _orbEscapeShape(float PeA_m, float ecc, float bodyR_m,
                             float &sma_m) {
    float rPe = fmaxf(PeA_m + bodyR_m, 1.0f);
    sma_m = rPe / (ecc - 1.0f);
}

// Body lookup by SOI name. Returns index into ORB_BODIES or 4 (Kerbin) fallback.
static uint8_t _orbBodyIdx() {
    const char *soi = state.gameSOI.c_str();
    for (uint8_t i = 0; i < sizeof(ORB_BODIES)/sizeof(ORB_BODIES[0]); i++) {
        if (strcmp(ORB_BODIES[i].name, soi) == 0) return i;
    }
    return 4;
}

// Compute the complete scene state from AppState. Returns by out-parameter so
// drawScreen_ORB can compute once and pass to all draw functions.
static void _orbComputeScene(OrbScene &sc) {
    uint8_t          bodyIdx = _orbBodyIdx();
    const OrbBody   &body    = ORB_BODIES[bodyIdx];

    sc.bodyIdx  = bodyIdx;
    sc.bodyR_m  = body.radius_m;
    sc.atmoH_m  = body.atmo_m;
    sc.soi_m    = body.soi_m;
    // Body colors come from the shared lookups in AAA_Screens.ino so ORB and
    // LNCH (Circularization) cannot drift apart.
    sc.bodyCol  = kspBodyColor(body.name);
    sc.atmoCol  = kspAtmoColor(body.name);

    float ecc   = fmaxf(0.0f, state.eccentricity);
    bool isEsc  = (ecc >= 1.0f) || (state.apoapsis < 0.0f);
    float PeA_m = fmaxf(0.0f, state.periapsis);
    float ApA_m = fmaxf(0.0f, state.apoapsis);

    if (isEsc) {
        ecc = fmaxf(ecc, 1.001f);
        _orbEscapeShape(PeA_m, ecc, sc.bodyR_m, sc.sma_m);
    } else {
        _orbEllipseShape(PeA_m, ApA_m, sc.bodyR_m, sc.sma_m, ecc);
    }

    sc.ecc         = ecc;
    sc.isEscape    = isEsc;
    sc.argOfPe_rad = state.argOfPe * (PI / 180.0f);
    sc.rPe_m       = fmaxf(PeA_m + sc.bodyR_m, 1.0f);
    sc.incl_deg    = state.inclination;

    const float PRE_SCALE_PX = 190.0f;
    sc.r_pe_px = isEsc
                 ? (sc.rPe_m / (3.0f * sc.bodyR_m)) * PRE_SCALE_PX
                 : (float)ORB_MAX_R;

    float bodyCapPx = (sc.bodyR_m / sc.rPe_m) * sc.r_pe_px;
    float body_px_f, atmo_px_f;
    if (isEsc) {
        body_px_f = fmaxf(4.0f, bodyCapPx);
        atmo_px_f = (sc.atmoH_m > 0.0f)
                    ? fmaxf(body_px_f + 4.0f,
                            body_px_f * (sc.bodyR_m + sc.atmoH_m) / sc.bodyR_m)
                    : 0.0f;
    } else {
        float bodyCapPxEll = (sc.bodyR_m / sc.rPe_m) * (float)ORB_MAX_R;
        body_px_f = fmaxf(4.0f,
                          fminf((sc.bodyR_m / sc.sma_m) * (float)ORB_MAX_R, bodyCapPxEll));
        atmo_px_f = (sc.atmoH_m > 0.0f)
                    ? fminf((sc.bodyR_m + sc.atmoH_m) / sc.sma_m * (float)ORB_MAX_R,
                            bodyCapPxEll * (sc.bodyR_m + sc.atmoH_m) / sc.bodyR_m)
                    : 0.0f;
    }
    sc.body_px = (uint16_t)body_px_f;
    sc.atmo_px = (uint16_t)atmo_px_f;

    if (isEsc) {
        sc.focusX = ORB_PCX;
        sc.focusY = ORB_CY;
    } else {
        float f_px = (float)ORB_MAX_R * ecc;
        sc.focusX = ORB_PCX + (int16_t)(f_px * cosf(sc.argOfPe_rad));
        sc.focusY = ORB_CY  - (int16_t)(f_px * sinf(sc.argOfPe_rad));
    }

    // Altitude at current true anomaly — for useSoiView gate.
    float nu_rad = state.trueAnomaly * (PI / 180.0f);
    while (nu_rad >  PI) nu_rad -= 2.0f * PI;
    while (nu_rad < -PI) nu_rad += 2.0f * PI;
    float altSL_m = -1.0f;
    if (isEsc) {
        float asymAng = acosf(-1.0f / ecc);
        if (fabsf(nu_rad) < asymAng - 0.05f) {
            float l_m = sc.rPe_m * (ecc + 1.0f);
            altSL_m   = l_m / (1.0f + ecc * cosf(nu_rad)) - sc.bodyR_m;
        }
    } else {
        float l_m = sc.sma_m * (1.0f - ecc*ecc);
        altSL_m   = l_m / (1.0f + ecc * cosf(nu_rad)) - sc.bodyR_m;
    }

    sc.useSoiView = isEsc && sc.soi_m > 0.0f
                          && altSL_m >= 0.0f && altSL_m > 2.0f * sc.bodyR_m;

    // Orbit colour
    bool peInAtmo = !isEsc && ((sc.atmoH_m > 0.0f && PeA_m < sc.atmoH_m) || PeA_m < 0.0f);
    bool apInAtmo = !isEsc && ((sc.atmoH_m > 0.0f && ApA_m < sc.atmoH_m) || ApA_m < 0.0f);
    if      (isEsc)                sc.orbitCol = TFT_ORANGE;
    else if (peInAtmo || apInAtmo) sc.orbitCol = TFT_YELLOW;
    else                           sc.orbitCol = TFT_DARK_GREEN;

    // INCL geometry
    sc.bodyCY = (int16_t)constrain((int)sc.focusY,
                                   (int)(INCL_CLIP_Y0 + INC_L + 2),
                                   (int)(INCL_CLIP_Y1 - INC_L - 2));
    float i_rad = sc.incl_deg * (PI / 180.0f);
    sc.dx = INC_L * cosf(i_rad);
    sc.dy = INC_L * sinf(i_rad);
}

// Build the quantized signature for change-detection.
static OrbSceneSig _orbSceneSig(const OrbScene &sc) {
    OrbSceneSig sig;
    sig.bodyIdx    = sc.bodyIdx;
    sig.isEscape   = sc.isEscape;
    sig.useSoiView = sc.useSoiView;
    sig.orbitCol   = sc.orbitCol;

    // argOfPe: wrap to [0, 360) then quantize
    float argDeg = state.argOfPe;
    while (argDeg <   0.0f) argDeg += 360.0f;
    while (argDeg >= 360.0f) argDeg -= 360.0f;
    sig.argPe_q = (int16_t)(argDeg / SIG_ARGPE_DEG);

    sig.ecc_q  = (int16_t)(sc.ecc      / SIG_ECC);
    sig.incl_q = (int16_t)(sc.incl_deg / SIG_INCL_DEG);

    // Apsides as fraction of SMA — handles huge SOI range (Moho → Jool) uniformly.
    // Quantize the fraction, not the absolute distance.
    if (sc.sma_m > 1.0f) {
        sig.rPe_q = (int16_t)((sc.rPe_m / sc.sma_m) / SIG_APS_FRAC);
        if (sc.isEscape) {
            sig.rAp_q = -1;
        } else {
            float rAp_m = 2.0f * sc.sma_m - sc.rPe_m;
            sig.rAp_q = (int16_t)((rAp_m / sc.sma_m) / SIG_APS_FRAC);
        }
    } else {
        sig.rPe_q = 0; sig.rAp_q = 0;
    }
    return sig;
}

// ── PLAN panel draw — ellipse or hyperbola, focus-centred ─────────────────────────────
static void _orbDrawHyperbola(KCM_TFT &tft,
                               int16_t focusX, int16_t focusY,
                               float ecc, float argOfPe_rad,
                               float r_pe_px, uint16_t col) {
    float l       = r_pe_px * (ecc + 1.0f);
    float asymAng = acosf(-1.0f / ecc);
    float cosA    = cosf(argOfPe_rad), sinA = sinf(argOfPe_rad);

    // Sweep outward until arc endpoints exit panel bounds.
    float thetaMax = asymAng - 0.01f;
    for (uint16_t i = 1; i < 10000; i++) {
        float t = (float)i / 10000.0f * asymAng;
        float r = l / (1.0f + ecc * cosf(t));
        if (r <= 0.0f) break;
        bool hit = false;
        for (int8_t sign = -1; sign <= 1; sign += 2) {
            float phi = sign * t + argOfPe_rad;
            float sx  = focusX + r * cosf(phi);
            float sy  = focusY - r * sinf(phi);
            if (sx < PLAN_X0 || sx > PLAN_X1 || sy < PLAN_CLIP_Y0 || sy > PLAN_CLIP_Y1)
                { hit = true; break; }
        }
        if (hit) { thetaMax = (float)(i - 1) / 10000.0f * asymAng; break; }
    }
    if (thetaMax < 0.05f) thetaMax = 0.05f;

    const uint8_t STEPS = 120;
    float prevSX = 0, prevSY = 0;
    bool started = false;
    for (uint8_t i = 0; i <= STEPS; i++) {
        float theta = -thetaMax + (float)i / STEPS * 2.0f * thetaMax;
        float r = l / (1.0f + ecc * cosf(theta));
        if (r <= 0.0f || r > 500.0f) { started = false; continue; }
        float px = r * cosf(theta);
        float py = r * sinf(theta);
        float rx = px * cosA - py * sinA;
        float ry = px * sinA + py * cosA;
        float sx = focusX + rx;
        float sy = focusY - ry;
        if (started)
            tft.drawLine((int16_t)prevSX, (int16_t)prevSY,
                         (int16_t)sx,     (int16_t)sy, col);
        prevSX = sx; prevSY = sy;
        started = true;
    }

    // Asymptotes clipped to panel bounds
    for (uint8_t side = 0; side < 2; side++) {
        float aAng = (side == 0) ? asymAng : -asymAng;
        float dx0 = cosf(aAng);
        float dy0 = sinf(aAng);
        float dx  = dx0 * cosA - dy0 * sinA;
        float dys = -(dx0 * sinA + dy0 * cosA);
        float t_max = 300.0f;
        if (fabsf(dx)  > 1e-4f) t_max = fminf(t_max, dx  > 0 ? (PLAN_X1-focusX)/dx  : (PLAN_X0-focusX)/dx);
        if (fabsf(dys) > 1e-4f) t_max = fminf(t_max, dys > 0 ? (PLAN_Y1-focusY)/dys : (PLAN_Y0-focusY)/dys);
        t_max = fmaxf(0.0f, t_max);
        for (uint8_t seg = 0; seg < 6; seg++) {
            float t0 = (float)seg / 6.0f * t_max;
            float t1 = fminf((float)(seg + 0.4f) / 6.0f * t_max, t_max);
            tft.drawLine(
                (int16_t)(focusX + t0*dx), (int16_t)(focusY + t0*dys),
                (int16_t)(focusX + t1*dx), (int16_t)(focusY + t1*dys),
                TFT_DARK_GREY);
        }
    }
}

// Draw ellipse at ORB_PCX, ORB_CY, rotated by argOfPe.
// 120 steps = ~8 px chords at 150 px radius. Visually smooth without being
// wasteful. 90 steps showed visible waviness on the curvy side; 180 was
// smooth but added ~15 ms per repaint.
static void _orbDrawEllipse(KCM_TFT &tft, float ecc, float argOfPe_rad, uint16_t col) {
    float a_px = (float)ORB_MAX_R;
    float b_px = a_px * sqrtf(fmaxf(0.0f, 1.0f - ecc*ecc));
    float cosA = cosf(argOfPe_rad), sinA = sinf(argOfPe_rad);
    const uint16_t STEPS = 120;
    float prevSX = 0, prevSY = 0;
    bool started = false;
    for (uint16_t i = 0; i <= STEPS; i++) {
        float t  = (float)i / STEPS * 2.0f * PI;
        float px = a_px * cosf(t);
        float py = b_px * sinf(t);
        float rx = px * cosA - py * sinA;
        float ry = px * sinA + py * cosA;
        float sx = ORB_PCX + rx;
        float sy = ORB_CY  - ry;
        if (started)
            tft.drawLine((int16_t)prevSX, (int16_t)prevSY,
                         (int16_t)sx,     (int16_t)sy, col);
        prevSX = sx; prevSY = sy;
        started = true;
    }
}

// Draw SOI view — body at panel centre, SOI ring dashed, orbit arc, Pe marker.
// No vessel dot here — Layer 3 handles that uniformly.
static void _orbDrawSOIView(KCM_TFT &tft, const OrbScene &sc) {
    const float SOI_PX = 172.0f;
    const int16_t FX = ORB_PCX, FY = ORB_CY;

    float scale   = SOI_PX / sc.soi_m;
    float body_px = sc.bodyR_m * scale;
    float atmo_px = (sc.atmoH_m > 0.0f)
                    ? fmaxf(body_px + 2.0f, (sc.bodyR_m + sc.atmoH_m) * scale)
                    : 0.0f;
    float r_pe_px = sc.rPe_m * scale;

    // SOI boundary — dashed circle
    for (uint16_t deg = 0; deg < 360; deg += 8)
        tft.drawLine(
            FX + (int16_t)(SOI_PX * cosf(deg * PI/180.0f)),
            FY - (int16_t)(SOI_PX * sinf(deg * PI/180.0f)),
            FX + (int16_t)(SOI_PX * cosf((deg+4) * PI/180.0f)),
            FY - (int16_t)(SOI_PX * sinf((deg+4) * PI/180.0f)),
            TFT_GREY);

    // Atmosphere disc
    if (atmo_px > body_px && sc.atmoCol != 0)
        tft.fillCircle(FX, FY, (uint16_t)atmo_px, sc.atmoCol);

    // Orbit arc at SOI scale
    _orbDrawHyperbola(tft, FX, FY, sc.ecc, sc.argOfPe_rad, r_pe_px, TFT_ORANGE);

    // Body disc
    tft.fillCircle(FX, FY, (uint16_t)fmaxf(3.0f, body_px), sc.bodyCol);

    // Pe marker at SOI-scaled position
    float cosA = cosf(sc.argOfPe_rad), sinA = sinf(sc.argOfPe_rad);
    int16_t pe_x = FX + (int16_t)(r_pe_px * cosA);
    int16_t pe_y = FY - (int16_t)(r_pe_px * sinA);
    if (pe_x >= PLAN_X0 && pe_x <= PLAN_X1 && pe_y >= PLAN_CLIP_Y0 && pe_y <= PLAN_CLIP_Y1) {
        tft.fillCircle(pe_x, pe_y, 3, TFT_MAGENTA);
        int16_t lx = (int16_t)constrain((int)(pe_x + 20.0f * cosA),
                                        (int)PLAN_X0, (int)(PLAN_X1 - 8));
        int16_t ly = (int16_t)constrain((int)(pe_y - 20.0f * sinA),
                                        (int)PLAN_CLIP_Y0, (int)(PLAN_CLIP_Y1 - 4));
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
        tft.setCursor(lx - 10, ly - 9); tft.print("Pe");
    }
}

// Draw Pe / Ap / AN / DN markers on the planar orbit.
// No cached pixel positions stored — scene repaint always covers the full panel.
// Marker DOT bounds use PLAN_Y0/Y1 (panel interior, 92..441). Marker LABEL
// bounds use PLAN_CLIP_Y0/Y1 (slightly inset, 94..439) so label text doesn't
// print too close to panel edges. Dots can be at the very top of the panel
// (e.g. Pe at argOfPe=90° lives at y=83 which is above PLAN_CLIP_Y0=94 but
// within the panel drawing area because PLAN extends up into the header strip
// y=62..92 for graphic content — only chrome text is excluded there).
static void _orbDrawMarkers(KCM_TFT &tft, const OrbScene &sc) {
    const int8_t  DOT_R   = 4;
    // Dot visibility bounds — loose (panel interior plus header strip for top).
    const int16_t DOT_Y_MIN = HDR_Y0;       // 62 — dots can be at very top
    const int16_t DOT_Y_MAX = PLAN_Y1 - 2;  // 439
    // Label placement bounds. LY_MIN reaches up into the (empty, PLAN-side)
    // header strip so a Pe/Ap dot near the panel top still gets its label placed
    // outboard (above the dot) rather than clamped down on top of it.
    const int16_t LX_MIN = PLAN_X0,  LX_MAX = PLAN_X1 - 8;
    const int16_t LY_MIN = HDR_Y0 + 2,  LY_MAX = PLAN_CLIP_Y1 - 4;
    const float   OFFSET = 24.0f;

    float cosA = cosf(sc.argOfPe_rad), sinA = sinf(sc.argOfPe_rad);

    // ── AN / DN — only when inclined and not escape ──────────────────────────────────
    if (!sc.isEscape && sc.incl_deg > 0.5f) {
        float f_px_eq = (float)ORB_MAX_R * sc.ecc;
        int16_t fX_eq = ORB_PCX + (int16_t)(f_px_eq * cosA);
        int16_t fY_eq = ORB_CY  - (int16_t)(f_px_eq * sinA);
        float l = (float)ORB_MAX_R * (1.0f - sc.ecc*sc.ecc);

        int16_t pe_sx = ORB_PCX + (int16_t)((float)ORB_MAX_R * cosA);
        int16_t pe_sy = ORB_CY  - (int16_t)((float)ORB_MAX_R * sinA);
        int16_t ap_sx = ORB_PCX - (int16_t)((float)ORB_MAX_R * cosA);
        int16_t ap_sy = ORB_CY  + (int16_t)((float)ORB_MAX_R * sinA);

        auto nearMarker = [](int16_t ax, int16_t ay, int16_t bx, int16_t by) -> bool {
            int dx = ax-bx, dy = ay-by;
            return (dx*dx + dy*dy) < 144;
        };

        // AN on east side of focus along equatorial line
        float r_an = l / (1.0f + sc.ecc * cosf(sc.argOfPe_rad));
        int16_t an_x = fX_eq + (int16_t)(r_an);
        int16_t an_y = fY_eq;
        if (an_x >= PLAN_X0 && an_x <= PLAN_X1 && an_y >= DOT_Y_MIN && an_y <= DOT_Y_MAX) {
            tft.fillCircle(an_x, an_y, DOT_R, TFT_CYAN);
            if (!nearMarker(an_x, an_y, pe_sx, pe_sy) &&
                !nearMarker(an_x, an_y, ap_sx, ap_sy)) {
                int16_t lx = (int16_t)constrain(an_x + 12, (int)LX_MIN, (int)LX_MAX);
                int16_t ly = (int16_t)constrain(an_y - 16, (int)LY_MIN, (int)LY_MAX);
                tft.setFont(Roboto_Black_16);
                tft.setTextColor(TFT_CYAN, TFT_BLACK);
                tft.setCursor(lx, ly); tft.print("AN");
            }
        }

        // DN on west side of focus
        float denom_dn = 1.0f - sc.ecc * cosf(sc.argOfPe_rad);
        if (denom_dn > 0.01f) {
            float r_dn = l / denom_dn;
            int16_t dn_x = fX_eq - (int16_t)(r_dn);
            int16_t dn_y = fY_eq;
            if (dn_x >= PLAN_X0 && dn_x <= PLAN_X1 && dn_y >= DOT_Y_MIN && dn_y <= DOT_Y_MAX) {
                tft.fillCircle(dn_x, dn_y, DOT_R, TFT_YELLOW);
                if (!nearMarker(dn_x, dn_y, pe_sx, pe_sy) &&
                    !nearMarker(dn_x, dn_y, ap_sx, ap_sy)) {
                    int16_t lx = (int16_t)constrain(dn_x - 32, (int)LX_MIN, (int)LX_MAX);
                    int16_t ly = (int16_t)constrain(dn_y - 16, (int)LY_MIN, (int)LY_MAX);
                    tft.setFont(Roboto_Black_16);
                    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
                    tft.setCursor(lx, ly); tft.print("DN");
                }
            }
        }
    }

    // ── Pe ────────────────────────────────────────────────────────────────────────────
    float pe_r   = sc.isEscape ? sc.r_pe_px : (float)ORB_MAX_R;
    int16_t pe_x = ORB_PCX + (int16_t)(pe_r * cosA);
    int16_t pe_y = ORB_CY  - (int16_t)(pe_r * sinA);

    // Hide Pe only when it's inside the physical body (impact trajectory).
    // Compare in METRES, not pixels — the pixel form confused body and atmo
    // at certain eccentricities because body_px includes a scale term that
    // grows when rPe is near bodyR, making rPe_px ≤ body_px even for Pe
    // above the surface but inside the atmosphere. Using rPe_m > bodyR_m is
    // physically rigorous: Pe is visible iff the periapsis is above the
    // ground. (Atmosphere is just visual context — Pe inside atmo is still
    // a valid orbit.)
    bool  showPe = sc.isEscape || (sc.rPe_m > sc.bodyR_m);

    if (showPe && pe_x >= PLAN_X0 && pe_x <= PLAN_X1 &&
                  pe_y >= DOT_Y_MIN && pe_y <= DOT_Y_MAX) {
        tft.fillCircle(pe_x, pe_y, DOT_R, TFT_MAGENTA);
        int16_t lx = (int16_t)constrain((int)(pe_x + OFFSET * cosA),
                                        (int)LX_MIN, (int)LX_MAX);
        int16_t ly = (int16_t)constrain((int)(pe_y - OFFSET * sinA),
                                        (int)LY_MIN, (int)LY_MAX);
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
        tft.setCursor(lx - 10, ly - 9); tft.print("Pe");
    }

    // ── Ap ────────────────────────────────────────────────────────────────────────────
    if (!sc.isEscape) {
        int16_t ap_x = ORB_PCX - (int16_t)((float)ORB_MAX_R * cosA);
        int16_t ap_y = ORB_CY  + (int16_t)((float)ORB_MAX_R * sinA);
        if (ap_x >= PLAN_X0 && ap_x <= PLAN_X1 &&
            ap_y >= DOT_Y_MIN && ap_y <= DOT_Y_MAX) {
            tft.fillCircle(ap_x, ap_y, DOT_R, TFT_BLUE);
            int16_t lx = (int16_t)constrain((int)(ap_x - OFFSET * cosA),
                                            (int)LX_MIN, (int)LX_MAX);
            int16_t ly = (int16_t)constrain((int)(ap_y + OFFSET * sinA),
                                            (int)LY_MIN, (int)LY_MAX);
            tft.setFont(Roboto_Black_16);
            tft.setTextColor(TFT_BLUE, TFT_BLACK);
            tft.setCursor(lx - 10, ly - 9); tft.print("Ap");
        }
    }
}

// Restore just the 4 marker DOTS (no labels) at their current positions.
// Called after the arc-patch in the vessel-update path. When the vessel passes
// through a marker dot, the patch paints orbit-colour through the dot; this
// helper re-paints the dot on top. Labels are NOT touched because the patch
// can't reach them (labels are 14 px offset from dots, patch extends ~7 px
// from old dot) and we want to avoid the black-background-rectangle of text
// drawing stomping orbit-line pixels.
static void _orbDrawMarkerDotsOnly(KCM_TFT &tft, const OrbScene &sc) {
    const int8_t DOT_R = 4;
    // Match the loose bounds used by _orbDrawMarkers for the dots — the tight
    // PLAN_CLIP_Y0 was for labels, not dots. Using it here suppressed Pe/Ap
    // dots when argOfPe ≈ 90° put them near the panel top edge.
    const int16_t DOT_Y_MIN = HDR_Y0;
    const int16_t DOT_Y_MAX = PLAN_Y1 - 2;
    float cosA = cosf(sc.argOfPe_rad), sinA = sinf(sc.argOfPe_rad);

    // AN / DN dots (when inclined, not escape)
    if (!sc.isEscape && sc.incl_deg > 0.5f) {
        float f_px_eq = (float)ORB_MAX_R * sc.ecc;
        int16_t fX_eq = ORB_PCX + (int16_t)(f_px_eq * cosA);
        int16_t fY_eq = ORB_CY  - (int16_t)(f_px_eq * sinA);
        float l = (float)ORB_MAX_R * (1.0f - sc.ecc*sc.ecc);

        float r_an = l / (1.0f + sc.ecc * cosf(sc.argOfPe_rad));
        int16_t an_x = fX_eq + (int16_t)(r_an);
        int16_t an_y = fY_eq;
        if (an_x >= PLAN_X0 && an_x <= PLAN_X1 &&
            an_y >= DOT_Y_MIN && an_y <= DOT_Y_MAX)
            tft.fillCircle(an_x, an_y, DOT_R, TFT_CYAN);

        float denom_dn = 1.0f - sc.ecc * cosf(sc.argOfPe_rad);
        if (denom_dn > 0.01f) {
            float r_dn = l / denom_dn;
            int16_t dn_x = fX_eq - (int16_t)(r_dn);
            int16_t dn_y = fY_eq;
            if (dn_x >= PLAN_X0 && dn_x <= PLAN_X1 &&
                dn_y >= DOT_Y_MIN && dn_y <= DOT_Y_MAX)
                tft.fillCircle(dn_x, dn_y, DOT_R, TFT_YELLOW);
        }
    }

    // Pe dot. Same visibility rule as _orbDrawMarkers — show iff Pe is above
    // the body surface (rPe_m > bodyR_m) or trajectory is escape.
    float pe_r   = sc.isEscape ? sc.r_pe_px : (float)ORB_MAX_R;
    int16_t pe_x = ORB_PCX + (int16_t)(pe_r * cosA);
    int16_t pe_y = ORB_CY  - (int16_t)(pe_r * sinA);
    bool  showPe = sc.isEscape || (sc.rPe_m > sc.bodyR_m);
    if (showPe && pe_x >= PLAN_X0 && pe_x <= PLAN_X1 &&
                  pe_y >= DOT_Y_MIN && pe_y <= DOT_Y_MAX)
        tft.fillCircle(pe_x, pe_y, DOT_R, TFT_MAGENTA);

    // Ap dot
    if (!sc.isEscape) {
        int16_t ap_x = ORB_PCX - (int16_t)((float)ORB_MAX_R * cosA);
        int16_t ap_y = ORB_CY  + (int16_t)((float)ORB_MAX_R * sinA);
        if (ap_x >= PLAN_X0 && ap_x <= PLAN_X1 &&
            ap_y >= DOT_Y_MIN && ap_y <= DOT_Y_MAX)
            tft.fillCircle(ap_x, ap_y, DOT_R, TFT_BLUE);
    }
}

// ── INCL panel draw — tilted orbit line, body, Pe/Ap markers ─────────────────────────
// No vessel dot here — Layer 3 handles that uniformly.
static void _orbDrawIncl(KCM_TFT &tft, const OrbScene &sc) {
    int16_t n_x = (int16_t)(INC_CX + sc.dx), n_y = (int16_t)(sc.bodyCY - sc.dy);
    int16_t s_x = (int16_t)(INC_CX - sc.dx), s_y = (int16_t)(sc.bodyCY + sc.dy);

    // Dashed equatorial line
    for (int16_t x = INCL_X0; x < INCL_X1; x += 10)
        tft.drawLine(x, sc.bodyCY, min((int16_t)(x + 6), INCL_X1), sc.bodyCY, TFT_GREY);

    // Body disc, then the orbit line over it. Same draw order as the PLAN panel:
    // the orbit line is the readout and the body is context, so the line stays
    // unbroken across the disc instead of being cut into two stubs by it.
    tft.fillCircle(INC_CX, sc.bodyCY, INC_BR, sc.bodyCol);

    // Orbit line (2px thick) — drawn last so it is in front of the body
    tft.drawLine(s_x, s_y,     n_x, n_y,     sc.orbitCol);
    tft.drawLine(s_x, s_y + 1, n_x, n_y + 1, sc.orbitCol);

    // N / S labels
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(INC_CX - 5, sc.bodyCY - INC_BR - 20); tft.print("N");
    tft.setCursor(INC_CX - 5, sc.bodyCY + INC_BR + 3);  tft.print("S");

    // AN label on WEST side of body disc (only when inclined)
    if (sc.incl_deg > 0.5f) {
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_CYAN, TFT_BLACK);
        tft.setCursor(INC_CX - INC_BR - 28, sc.bodyCY - 8); tft.print("AN");
    }

    // Note: numeric inclination value was here; moved to the readout strip
    // (top row, "Inc: NN.N°" at INC_RDY0) so the inclination value updates
    // at the text cadence rather than requiring a scene repaint.

    // Pe on orbit line — suppressed if projects within body disc
    float argPe_rad = sc.argOfPe_rad;
    float t_pe = sinf(argPe_rad);
    int16_t pe_x = (int16_t)(INC_CX + t_pe * sc.dx);
    int16_t pe_y = (int16_t)(sc.bodyCY - t_pe * sc.dy);
    float pe_dist2 = (t_pe * sc.dx) * (t_pe * sc.dx) + (t_pe * sc.dy) * (t_pe * sc.dy);
    if (pe_dist2 > (float)((INC_BR+4)*(INC_BR+4)) &&
        pe_x >= INCL_X0 && pe_x <= INCL_X1 && pe_y >= INCL_CLIP_Y0 && pe_y <= INCL_CLIP_Y1) {
        tft.fillCircle(pe_x, pe_y, 4, TFT_MAGENTA);
        tft.setFont(Roboto_Black_16);
        tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
        int16_t lx = (pe_x >= INC_CX)
            ? (int16_t)constrain(pe_x + 12, INCL_X0+2, INCL_X1-22)
            : (int16_t)constrain(pe_x - 32, INCL_X0+2, INCL_X1-22);
        tft.setCursor(lx, (int16_t)constrain(pe_y - 18, INCL_CLIP_Y0+2, INCL_CLIP_Y1-14));
        tft.print("Pe");
    }

    // Ap on orbit line
    if (!sc.isEscape) {
        float t_ap = -t_pe;
        int16_t ap_x = (int16_t)(INC_CX + t_ap * sc.dx);
        int16_t ap_y = (int16_t)(sc.bodyCY - t_ap * sc.dy);
        float ap_dist2 = (t_ap * sc.dx) * (t_ap * sc.dx) + (t_ap * sc.dy) * (t_ap * sc.dy);
        if (ap_dist2 > (float)((INC_BR+4)*(INC_BR+4)) &&
            ap_x >= INCL_X0 && ap_x <= INCL_X1 && ap_y >= INCL_CLIP_Y0 && ap_y <= INCL_CLIP_Y1) {
            tft.fillCircle(ap_x, ap_y, 4, TFT_BLUE);
            tft.setFont(Roboto_Black_16);
            tft.setTextColor(TFT_BLUE, TFT_BLACK);
            int16_t lx = (ap_x >= INC_CX)
                ? (int16_t)constrain(ap_x + 12, INCL_X0+2, INCL_X1-22)
                : (int16_t)constrain(ap_x - 32, INCL_X0+2, INCL_X1-22);
            tft.setCursor(lx, (int16_t)constrain(ap_y - 18, INCL_CLIP_Y0+2, INCL_CLIP_Y1-14));
            tft.print("Ap");
        }
    }
}

// ── Layer 3 — Vessel dot with arc-patch erase (D1) ────────────────────────────────────
// Computes vessel pixel position on the PLAN panel. Returns false if vessel is
// hidden (inside body, past asymptote, or off panel).
static bool _orbVesselPxPlan(const OrbScene &sc, float nu_rad,
                              int16_t &out_x, int16_t &out_y) {
    float r_px;
    if (sc.isEscape) {
        float asymAng = acosf(-1.0f / sc.ecc);
        if (fabsf(nu_rad) >= asymAng - 0.05f) return false;
        float l = sc.r_pe_px * (sc.ecc + 1.0f);
        r_px = l / (1.0f + sc.ecc * cosf(nu_rad));
    } else {
        float a = (float)ORB_MAX_R;
        r_px = a * (1.0f - sc.ecc*sc.ecc) / (1.0f + sc.ecc * cosf(nu_rad));
    }
    if (r_px <= (float)sc.body_px + 1.0f) return false;

    float phi = nu_rad + sc.argOfPe_rad;
    int16_t sx = sc.focusX + (int16_t)(r_px * cosf(phi));
    int16_t sy = sc.focusY - (int16_t)(r_px * sinf(phi));
    if (sx < PLAN_X0 || sx > PLAN_X1 || sy < PLAN_CLIP_Y0 || sy > PLAN_CLIP_Y1) return false;

    out_x = sx; out_y = sy;
    return true;
}

// Patch the orbit line locally around true anomaly nu_rad.
// Used after erasing the old vessel dot to restore the orbit line underneath.
//
// Critical: the patch MUST retrace the same pixel path as _orbDrawEllipse
// so no orbit-colour stragglers are left behind. `_orbDrawEllipse` uses the
// parametric form `a*cos(t), b*sin(t)` (t = eccentric anomaly) with 120 fixed
// steps around the full 2π range; each drawLine produces a specific pixel
// set that differs slightly from any other parameterization's trace of the
// same geometric ellipse.
//
// So: for the ellipse case, we convert nu → E (eccentric anomaly), snap to
// the nearest ellipse step boundaries, and re-issue drawLines between those
// exact boundary points. This is pixel-identical to the original ellipse
// trace.
//
// For hyperbolic/SOI cases, there's no such periodic step structure — the
// hyperbola/SOI drawings are small and any mismatch is tolerable. Fall back
// to the focal-polar form for those.
static void _orbPatchArcPlan(KCM_TFT &tft, const OrbScene &sc, float nu_rad) {
    // ── Ellipse case: retrace ellipse's exact parametric vertices ────────────────────
    if (!sc.useSoiView && !sc.isEscape) {
        const uint16_t STEPS = 120;  // MUST match _orbDrawEllipse
        float a_px = (float)ORB_MAX_R;
        float e = sc.ecc;
        float b_px = a_px * sqrtf(fmaxf(0.0f, 1.0f - e*e));
        float cosA = cosf(sc.argOfPe_rad), sinA = sinf(sc.argOfPe_rad);

        // Convert true anomaly nu → eccentric anomaly E via the standard
        // Keplerian relation: tan(E/2) = sqrt((1-e)/(1+e)) * tan(nu/2).
        // The atan-based inversion gives the correct branch as long as nu is
        // already normalized to (-π, π] — which oldNu is, because atan2f
        // returns values in that range and subtracting argOfPe (in similar
        // range) gives a value within (-2π, 2π). For safety we normalize first.
        float nu_norm = nu_rad;
        while (nu_norm >  PI) nu_norm -= 2.0f * PI;
        while (nu_norm < -PI) nu_norm += 2.0f * PI;

        float E_center;
        if (e < 1e-6f) {
            E_center = nu_norm;  // circle — E == nu
        } else {
            float half = sqrtf((1.0f - e) / (1.0f + e)) * tanf(nu_norm * 0.5f);
            E_center = 2.0f * atanf(half);
            // Within nu_norm ∈ (-π, π], E_center from this formula is in the
            // same branch. No correction needed — both quantities wrap at ±π
            // together.
        }

        // Snap to the ellipse's step grid. The ellipse is drawn at:
        //   t_i = i * 2π / STEPS, i = 0..STEPS
        // Pick indices covering E_center ± 3 steps (6 segments of ~5-8 px each
        // at r=150, total ~30-48 px — well over the 10 px erase diameter plus
        // margin for integer-rounding jitter on the oldNu estimate).
        float step_rad = 2.0f * PI / STEPS;
        // Normalize E_center to [0, 2π)
        float E_norm = E_center;
        while (E_norm < 0.0f) E_norm += 2.0f * PI;
        while (E_norm >= 2.0f * PI) E_norm -= 2.0f * PI;
        int16_t center_idx = (int16_t)(E_norm / step_rad + 0.5f);
        const int16_t HALF_SEGS = 3;  // 6 segments total ≈ 30-48 px patch

        float prev_sx = 0, prev_sy = 0;
        bool  started = false;
        for (int16_t i = center_idx - HALF_SEGS; i <= center_idx + HALF_SEGS; i++) {
            // Wrap i to [0, STEPS] range. Using modulo to keep the trace valid
            // even if the vessel is near nu=π (i.e., near the Pe/Ap line at
            // the wrap boundary).
            int16_t idx = i;
            while (idx < 0) idx += STEPS;
            while (idx > (int16_t)STEPS) idx -= STEPS;
            float t = (float)idx * step_rad;

            // Exact same parametric form as _orbDrawEllipse
            float px = a_px * cosf(t);
            float py = b_px * sinf(t);
            float rx = px * cosA - py * sinA;
            float ry = px * sinA + py * cosA;
            float sx = (float)ORB_PCX + rx;
            float sy = (float)ORB_CY  - ry;

            if (started)
                tft.drawLine((int16_t)prev_sx, (int16_t)prev_sy,
                             (int16_t)sx,     (int16_t)sy,
                             sc.orbitCol);
            prev_sx = sx; prev_sy = sy;
            started = true;
        }
        return;
    }

    // ── Hyperbola / SOI-view case: focal-polar form, adaptive DELTA ──────────────────
    float scale_m_to_px = 0.0f;
    int16_t fx, fy;
    if (sc.useSoiView) {
        const float SOI_PX = 172.0f;
        scale_m_to_px = SOI_PX / sc.soi_m;
        fx = ORB_PCX; fy = ORB_CY;
    } else {
        fx = sc.focusX; fy = sc.focusY;
    }

    // Compute local r_px at nu_rad to choose DELTA adaptively.
    float r_px_local;
    if (sc.useSoiView) {
        float l_m = sc.rPe_m * (sc.ecc + 1.0f);
        float denom = 1.0f + sc.ecc * cosf(nu_rad);
        float r_m  = (fabsf(denom) > 0.01f) ? l_m / denom : sc.rPe_m;
        r_px_local = r_m * scale_m_to_px;
    } else {  // isEscape
        float l_px  = sc.r_pe_px * (sc.ecc + 1.0f);
        float denom = 1.0f + sc.ecc * cosf(nu_rad);
        r_px_local = (fabsf(denom) > 0.01f) ? l_px / denom : sc.r_pe_px;
    }
    if (r_px_local < 10.0f) r_px_local = 10.0f;

    const float TARGET_HALF_ARC_PX = 10.0f;
    float DELTA = TARGET_HALF_ARC_PX / r_px_local;
    if (DELTA < 0.05f) DELTA = 0.05f;
    if (DELTA > 0.30f) DELTA = 0.30f;

    auto pointAt = [&](float t, float &out_sx, float &out_sy) -> bool {
        float r_px;
        if (sc.useSoiView) {
            float asymAng = acosf(-1.0f / sc.ecc);
            if (fabsf(t) >= asymAng - 0.05f) return false;
            float l_m = sc.rPe_m * (sc.ecc + 1.0f);
            float r_m = l_m / (1.0f + sc.ecc * cosf(t));
            if (r_m <= 0.0f) return false;
            r_px = r_m * scale_m_to_px;
        } else {  // isEscape
            float asymAng = acosf(-1.0f / sc.ecc);
            if (fabsf(t) >= asymAng - 0.05f) return false;
            float l_px = sc.r_pe_px * (sc.ecc + 1.0f);
            r_px = l_px / (1.0f + sc.ecc * cosf(t));
            if (r_px <= 0.0f) return false;
        }
        float phi = t + sc.argOfPe_rad;
        out_sx = fx + r_px * cosf(phi);
        out_sy = fy - r_px * sinf(phi);
        return true;
    };

    const uint8_t SEGS = 3;
    float prev_sx = 0, prev_sy = 0;
    bool  started = false;
    for (uint8_t i = 0; i <= SEGS; i++) {
        float t = nu_rad - DELTA + (float)i * (2.0f * DELTA / SEGS);
        float sx, sy;
        if (!pointAt(t, sx, sy)) { started = false; continue; }
        if (started)
            tft.drawLine((int16_t)prev_sx, (int16_t)prev_sy,
                         (int16_t)sx,     (int16_t)sy,
                         sc.orbitCol);
        prev_sx = sx; prev_sy = sy;
        started = true;
    }
}

// ── Per-frame state ───────────────────────────────────────────────────────────────────
// Readout strip caching uses the shared rowCache[screen_ORB]/printState[screen_ORB]
// (slots 0..7; 6 = Inc on INCL, 7 = Ecc) — see the orbPut helper in drawScreen_ORB.

// Vessel dot cache (both panels).
static bool    _planDotValid = false;
static int16_t _planDotX     = 0;
static int16_t _planDotY     = 0;
static bool    _inclDotValid = false;
static int16_t _inclDotX     = 0;
static int16_t _inclDotY     = 0;

// Scene cache + signature for change detection.
static bool        _sceneValid = false;
static OrbScene    _lastScene;
static OrbSceneSig _lastSig;

// Body name cache — tracks last-drawn bodyIdx so the name is only redrawn when
// the SOI actually changes. The name lives in the header strip (above the
// scene repaint region), so scene repaints don't disturb it.
static int16_t     _lastBodyIdxDrawn = -1;

// Last-drawn T+Pe/T+Ap label: 0=Pe, 1=Ap, -1=never drawn.
static int8_t      _lastTLabel = -1;

// Diagnostics
static uint32_t    _vesselUpdateCount = 0;

// Draw (or refresh) the SOI body name in the header strip.
// Called from chromeScreen_ORB (initial draw) and from drawScreen_ORB when
// bodyIdx changes. Position: right-justified in a box over the INCL panel
// header area. Uses textRight which clears its own background — this gives
// a clean redraw when the body actually changes.
static void _orbDrawBodyName(KCM_TFT &tft, uint8_t bodyIdx) {
    // Roboto_Black_32 (cap 38): right-justified, top at y=63 so the name spans
    // y=63..101 — it reaches ~9px below the header strip into the INCL panel's
    // (empty) top-right corner. _orbRepaintIncl re-draws it after its fillRect so
    // a scene repaint can't leave the lower slice clipped.
    // Clear the name bbox first — names are right-justified and vary in width
    // (Eve → Minmus), so without this a shorter name would leave the left tail
    // of the previous (longer) name as a ghost.
    tft.fillRect(740, 62, 190, 40, TFT_BLACK);
    textRight(tft, &Roboto_Black_32,
              476, 63, 460, 38,
              String(ORB_BODIES[bodyIdx].name),
              TFT_LIGHT_GREY, TFT_BLACK);
    _lastBodyIdxDrawn = (int16_t)bodyIdx;
}

// ── Scene redraw — full panel clear + redraw from scratch ─────────────────────────────
static void _orbRepaintPlan(KCM_TFT &tft, const OrbScene &sc) {
    uint32_t t0 = micros();
    // Erase bound extends up into the header strip (y=62..92) so atmo/body
    // pixels that naturally draw above y=92 (e.g. argOfPe near 90°) get
    // cleared. No chrome text lives here anymore (ORBIT/INCL labels removed)
    // so we can wipe freely.
    tft.fillRect(PLAN_X0, PLAN_FILL_Y0,
                 (uint16_t)(PLAN_X1 - PLAN_X0),
                 (uint16_t)(PLAN_Y1 - PLAN_FILL_Y0), TFT_BLACK);
    uint32_t t1 = micros();

    if (sc.useSoiView) {
        _orbDrawSOIView(tft, sc);
    } else {
        // Draw order: atmo → body → orbit line → markers.
        // Orbit line drawn AFTER atmo and body so a sub-atmospheric Pe (impact
        // trajectory, orbit inside atmosphere) remains visible as a line
        // crossing through/over the atmosphere and body. The orbit line is
        // the key readout; it must be on top of the body graphics.
        if (sc.atmo_px > sc.body_px && sc.atmoCol != 0)
            tft.fillCircle(sc.focusX, sc.focusY, sc.atmo_px, sc.atmoCol);
        tft.fillCircle(sc.focusX, sc.focusY, sc.body_px, sc.bodyCol);
        if (sc.isEscape) {
            _orbDrawHyperbola(tft, sc.focusX, sc.focusY,
                              sc.ecc, sc.argOfPe_rad, sc.r_pe_px, sc.orbitCol);
        } else {
            _orbDrawEllipse(tft, sc.ecc, sc.argOfPe_rad, sc.orbitCol);
        }
        _orbDrawMarkers(tft, sc);
    }
    uint32_t t2 = micros();

    if (debugMode) {
        Serial.print(F("[ORB] PLAN repaint  fill="));
        Serial.print(t1 - t0);
        Serial.print(F("us  draw="));
        Serial.print(t2 - t1);
        Serial.print(F("us  total="));
        Serial.print(t2 - t0);
        Serial.print(F("us  soi="));
        Serial.print(sc.useSoiView ? 1 : 0);
        Serial.print(F("  esc="));
        Serial.println(sc.isEscape ? 1 : 0);
    }

    // Scene repaint erases the vessel dot along with everything else.
    _planDotValid = false;
}

static void _orbRepaintIncl(KCM_TFT &tft, const OrbScene &sc) {
    uint32_t t0 = micros();
    // INCL fillRect covers the graphics area (y=92..441). The enlarged SOI body
    // name (Roboto_Black_32) reaches ~9px below the header strip into this
    // region's top-right corner, so the fillRect clips its lower slice — we
    // re-draw the name below, after the graphic, to restore it every repaint.
    tft.fillRect(INCL_X0, INCL_FILL_Y0,
                 (uint16_t)(INCL_X1 - INCL_X0),
                 (uint16_t)(INCL_Y1 - INCL_FILL_Y0), TFT_BLACK);
    uint32_t t1 = micros();

    _orbDrawIncl(tft, sc);
    _orbDrawBodyName(tft, sc.bodyIdx);   // restore name slice erased by the fillRect
    uint32_t t2 = micros();

    if (debugMode) {
        Serial.print(F("[ORB] INCL repaint  fill="));
        Serial.print(t1 - t0);
        Serial.print(F("us  draw="));
        Serial.print(t2 - t1);
        Serial.print(F("us  total="));
        Serial.println(t2 - t0);
    }

    _inclDotValid = false;
}

// ── Public entry points ───────────────────────────────────────────────────────────────
static void chromeScreen_ORB(KCM_TFT &tft) {
    // Invalidate all caches on screen entry — force scene repaint and dot redraw
    // on the first updateScreen call.
    _sceneValid        = false;
    _planDotValid      = false;
    _inclDotValid      = false;
    _vesselUpdateCount = 0;
    _lastBodyIdxDrawn  = -1;
    _lastTLabel        = -1;
    for (uint8_t i = 0; i < 8; i++) { printState[screen_ORB][i] = PrintState{}; rowCache[screen_ORB][i].value = String("\x01"); }

    // Panel divider — centred at x=470 (half of the 940px content area)
    tft.drawLine(CONTENT_W / 2, ORB_TITLE_TOP, CONTENT_W / 2, ORB_SCREEN_H, TFT_GREY);
    tft.drawLine(CONTENT_W / 2 + 1, ORB_TITLE_TOP, CONTENT_W / 2 + 1, ORB_SCREEN_H, TFT_GREY);

    // Panel labels "ORBIT" and "INCL" are intentionally absent — the screen
    // title already says "ORBIT" and the left/right functional split is clear
    // from the readouts and graphics. Removing them also eliminates the body-
    // disc overlap problem at extreme argOfPe values.

    // Body name — right-justified over INCL panel, in the header strip.
    // Drawn once in chrome, refreshed only when bodyIdx changes. The body
    // graphic is at x=679..731 (INC_CX ± INC_BR) and never rises above y=102,
    // so this name in the header strip (y=67..91) is never overlapped.
    _orbDrawBodyName(tft, _orbBodyIdx());

    // Readout strip labels. Four rows a side now. All use Roboto_Black_28.
    // SMA / Ecc / PRD / Arg.Pe / T+Pe-T+Ap / Inc labels take the panel-wide label grey;
    // Pe and Ap use their dot colours (magenta / blue) as mnemonic colour coding.
    tft.setFont(Roboto_Black_28);
    tft.setTextColor(KDC_LABEL_COLOR, TFT_BLACK);
    tft.setCursor(6,   ORB_RDY0); tft.print("SMA");
    tft.setCursor(6,   ORB_RDY1); tft.print("ECC");
    tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
    tft.setCursor(6,   ORB_RDY2); tft.print("PEA");
    tft.setTextColor(TFT_BLUE, TFT_BLACK);
    tft.setCursor(6,   ORB_RDY3); tft.print("APA");

    // INCL readout labels — Inc (top), PRD, Arg.Pe. T+Pe/T+Ap is dynamic.
    tft.setTextColor(KDC_LABEL_COLOR, TFT_BLACK);
    tft.setCursor(INC_LABEL_X, INC_RDY0); tft.print("INC");
    tft.setCursor(INC_LABEL_X, INC_RDY1); tft.print("PERIOD");
    tft.setCursor(INC_LABEL_X, INC_RDY2); tft.print("ARG.PE");
    // T+Pe / T+Ap label is drawn on demand from drawScreen_ORB via _lastTLabel cache
}

static void drawScreen_ORB(KCM_TFT &tft) {
    uint32_t frameStart = debugMode ? micros() : 0;

    // ── Compute current scene + signature ────────────────────────────────────────────
    OrbScene    sc;
    _orbComputeScene(sc);
    OrbSceneSig sig = _orbSceneSig(sc);

    // ── Scene-change gating ──────────────────────────────────────────────────────────
    // Throttle removed (rev-2): repaint as soon as the quantized signature
    // changes — no minimum-interval / 2 Hz cap. The signature bins still give
    // dead-band hysteresis against floating-point jitter, so the scene only
    // repaints when something visually different actually happens (which under
    // the global double buffer means the repaint lands on the hidden page).
    bool sceneNeedsRepaint = (!_sceneValid) || (sig != _lastSig);

    // ── Layer 2: scene repaint ───────────────────────────────────────────────────────
    if (sceneNeedsRepaint) {
        // Split PLAN and INCL — both always repaint together for now since the
        // signature lumps both panels. Could be split later if profiling shows
        // INCL is cheap to repaint and benefits from more frequent updates.
        _orbRepaintPlan(tft, sc);
        _orbRepaintIncl(tft, sc);
        _lastScene        = sc;
        _lastSig          = sig;
        _sceneValid       = true;
    }

    // Body name — drawn once in chrome, then refreshed only when the SOI body
    // changes. Lives in the protected header strip (y=62..92), so scene
    // repaints never disturb it.
    if ((int16_t)sc.bodyIdx != _lastBodyIdxDrawn) {
        _orbDrawBodyName(tft, sc.bodyIdx);
    }

    // ── Layer 3: vessel dot on PLAN panel ────────────────────────────────────────────
    // The cached scene is the one on screen (a repaint just refreshed it), so the
    // vessel is placed against exactly what is drawn.
    const OrbScene &drawSc = _lastScene;

    float nu_rad = state.trueAnomaly * (PI / 180.0f);
    while (nu_rad >  PI) nu_rad -= 2.0f * PI;
    while (nu_rad < -PI) nu_rad += 2.0f * PI;

    uint32_t vt0 = 0, vt1 = 0, vt2 = 0, vt3 = 0;

    int16_t vx = 0, vy = 0;
    bool vesselVisiblePlan = _orbVesselPxPlan(drawSc, nu_rad, vx, vy);

    // Trigger redraw when: no dot currently drawn (covers hidden→visible AND first frame),
    // OR the vessel is hidden (so a dot that is up must be erased), OR the new position
    // differs from the drawn position by VESSEL_PX_THRESH in either axis.
    //
    // The !vesselVisiblePlan term is load-bearing, not belt-and-braces.
    // _orbVesselPxPlan() returns false on four paths -- past the asymptote, inside the
    // body, off the panel in x, off it in y -- and on every one of them it leaves vx and
    // vy untouched. The previous test read them anyway. Besides being undefined, it
    // decided whether a dot that had just passed behind the body got erased: if the
    // indeterminate values happened to land within VESSEL_PX_THRESH of the cached
    // position the block was skipped, and the stale dot sat on the orbit until something
    // else moved. Visibility is now its own trigger and the positions are only read when
    // they mean something. Hidden→hidden costs one no-op pass, since the branch below
    // clears _planDotValid.
    bool vesselMovedPlan = !_planDotValid
                        || !vesselVisiblePlan
                        || abs((int)vx - (int)_planDotX) >= VESSEL_PX_THRESH
                        || abs((int)vy - (int)_planDotY) >= VESSEL_PX_THRESH;

    if (vesselMovedPlan) {
        if (debugMode) vt0 = micros();

        // Erase old dot (if any), then restore markers and orbit line around
        // the erase region.
        if (_planDotValid) {
            tft.fillCircle(_planDotX, _planDotY, 6, TFT_BLACK);
            if (debugMode) vt1 = micros();

            // Order:
            //  1. Erase (above) — blacks out the 5-px-radius old-dot region.
            //     If the dot was on a marker label, the label pixels are
            //     erased; if on a marker dot, the dot pixels are erased.
            //  2. Redraw full markers (dot + label). If a label was partially
            //     erased, it's restored. The label's text-background rect may
            //     stomp orbit-line pixels where the label overlaps the orbit,
            //     but only inside the label's bbox.
            //  3. Arc patch. Paints orbit-colour over ~14 px of arc around
            //     the old dot, restoring the orbit line continuity across the
            //     erase region INCLUDING any black pixels the label's
            //     background rect just placed over the line.
            //  4. Dots-only marker restore. The patch in step 3 may have
            //     painted orbit-colour through a marker dot (if the vessel
            //     passed through the dot). Re-paint just the dots (no labels,
            //     to avoid re-triggering step 3's label-bbox issue). Dots are
            //     small and localised — this is cheap.
            float oldNu = atan2f((float)(drawSc.focusY - _planDotY),
                                  (float)(_planDotX - drawSc.focusX))
                        - drawSc.argOfPe_rad;
            if (!drawSc.useSoiView) _orbDrawMarkers(tft, drawSc);
            _orbPatchArcPlan(tft, drawSc, oldNu);
            if (!drawSc.useSoiView) _orbDrawMarkerDotsOnly(tft, drawSc);
            if (debugMode) vt2 = micros();
        } else {
            if (debugMode) { vt1 = vt0; vt2 = vt0; }
        }

        // Draw new dot
        if (vesselVisiblePlan) {
            tft.fillCircle(vx, vy, 5, TFT_NEON_GREEN);
            _planDotX     = vx;
            _planDotY     = vy;
            _planDotValid = true;
        } else {
            _planDotValid = false;
        }
        if (debugMode) vt3 = micros();
    }

    // ── Layer 3: vessel dot on INCL panel ────────────────────────────────────────────
    // INCL vessel is at t_v = sin(argPe + nu) along the tilted line.
    float u_rad = drawSc.argOfPe_rad + nu_rad;
    float t_v   = sinf(u_rad);
    int16_t ivx = (int16_t)(INC_CX + t_v * drawSc.dx);
    int16_t ivy = (int16_t)(drawSc.bodyCY - t_v * drawSc.dy);
    bool inclVisible = (ivx >= INCL_X0 && ivx <= INCL_X1 &&
                        ivy >= INCL_CLIP_Y0 && ivy <= INCL_CLIP_Y1);

    bool inclMoved = !_inclDotValid
                  || abs((int)ivx - (int)_inclDotX) >= VESSEL_PX_THRESH
                  || abs((int)ivy - (int)_inclDotY) >= VESSEL_PX_THRESH;

    if (inclMoved) {
        if (_inclDotValid) {
            // Erase old dot — on a 2-px-thick straight line, simplest is to
            // redraw the two parallel line segments locally across a small box
            // around the old dot. Full-line redraw is cheap for straight lines.
            tft.fillCircle(_inclDotX, _inclDotY, 6, TFT_BLACK);

            // Redraw the body disc if the patch area overlapped it — cheap safety.
            // Done before the line patch so the repair rebuilds the scene in the
            // same order _orbDrawIncl draws it (body first, line over it); patching
            // the line first and the disc second would punch a hole in the line.
            int dxb = _inclDotX - INC_CX, dyb = _inclDotY - drawSc.bodyCY;
            if (dxb*dxb + dyb*dyb < (INC_BR + 10) * (INC_BR + 10))
                tft.fillCircle(INC_CX, drawSc.bodyCY, INC_BR, drawSc.bodyCol);

            // Re-draw the local piece of the tilted 2-px line.
            // Project the old dot onto the line parameter to find the local span.
            // Simpler approach: redraw a small segment from (dot-6px) to (dot+6px)
            // along the line direction. This always restores the 2-px line.
            float lineLen = sqrtf(drawSc.dx*drawSc.dx + drawSc.dy*drawSc.dy);
            if (lineLen > 1e-3f) {
                float ux =  drawSc.dx / lineLen;
                float uy = -drawSc.dy / lineLen;
                int16_t a_x = _inclDotX - (int16_t)(8.0f * ux);
                int16_t a_y = _inclDotY - (int16_t)(8.0f * uy);
                int16_t b_x = _inclDotX + (int16_t)(8.0f * ux);
                int16_t b_y = _inclDotY + (int16_t)(8.0f * uy);
                tft.drawLine(a_x, a_y,     b_x, b_y,     drawSc.orbitCol);
                tft.drawLine(a_x, a_y + 1, b_x, b_y + 1, drawSc.orbitCol);
            }
        }
        if (inclVisible) {
            tft.fillCircle(ivx, ivy, 5, TFT_NEON_GREEN);
            _inclDotX     = ivx;
            _inclDotY     = ivy;
            _inclDotValid = true;
        } else {
            _inclDotValid = false;
        }
    }

    // Periodic vessel-update timing print
    if (debugMode && (vesselMovedPlan || inclMoved)) {
        _vesselUpdateCount++;
        if (_vesselUpdateCount % DBG_VESSEL_EVERY == 0) {
            Serial.print(F("[ORB] vessel #"));
            Serial.print(_vesselUpdateCount);
            if (vesselMovedPlan && _planDotValid) {
                Serial.print(F("  plan erase="));
                Serial.print(vt1 - vt0);
                Serial.print(F("us  patch="));
                Serial.print(vt2 - vt1);
                Serial.print(F("us  draw="));
                Serial.print(vt3 - vt2);
                Serial.print(F("us"));
            }
            Serial.println();
        }
    }

    // ── Readout values — cached to prevent per-frame redraw flicker ──────────────────
    // printValue with PrintState is flicker-free when the string changes width,
    // but when called every frame on an unchanged string the character-cell
    // erase flickers the glyphs visibly. Compare strings before calling.
    const tFont *F = &Roboto_Black_28;
    const uint16_t RH = 37;

    // Cache-checked readout draw backed by the shared rowCache[screen_ORB] (value-only
    // compare; dark green on black). Geometry is explicit per readout.
    // Values arrive as C strings in stack buffers; the cache compare allocates nothing
    // and a String is built only for the value about to be drawn.
    auto orbPut = [&](uint8_t slot, int16_t x, int16_t y, int16_t w, const char *v) {
        RowCache &rc = rowCache[screen_ORB][slot];
        if (rc.value == v) return;
        String s(v);
        printValue(tft, F, x, y, w, RH, "", s, TFT_DARK_GREEN, TFT_BLACK, TFT_BLACK,
                   printState[screen_ORB][slot]);
        rc.value = s;
    };
    char vb[48];

    float PeA_m  = fmaxf(0.0f, state.periapsis);
    float ApA_m  = fmaxf(0.0f, state.apoapsis);
    // timeToPe / timeToAp are used raw (not fmaxf-clamped) in the row-5 block
    // below, because a negative value there means "passed / unavailable" and
    // needs to be distinguishable from a small positive value.

    // Rows 0 and 7 — SMA and Ecc, exactly as ORBIT ADVANCED renders them. On an escape trajectory the
    // semi-major axis is negative and the eccentricity is at or above 1; both are still
    // the real elements, and formatAlt() carries the sign, so neither is special-cased.
    formatAltBuf(state.semiMajorAxis, vb, sizeof(vb));
    orbPut(0, 110, ORB_RDY0, 360, vb);
    {
        char ebuf[16];
        dtostrf(state.eccentricity, 1, 4, ebuf);
        orbPut(7, 110, ORB_RDY1, 360, ebuf);
    }
    // Row 1 — Pe
    // Hide when Pe is inside the body (impact trajectory, periapsis below
    // surface). Uses the same physical-altitude rule as the marker visibility
    // check: show iff rPe_m > bodyR_m, which is equivalent to state.periapsis
    // > 0 (the value here PeA_m is already state.periapsis clamped to ≥ 0).
    {
        bool  peHid  = !drawSc.isEscape && (drawSc.rPe_m <= drawSc.bodyR_m);
        if (peHid) orbPut(1, 110, ORB_RDY2, 360, "---");
        else { formatAltBuf(PeA_m, vb, sizeof(vb)); orbPut(1, 110, ORB_RDY2, 360, vb); }
    }
    // Row 2 — Ap
    if (drawSc.isEscape) orbPut(2, 110, ORB_RDY3, 360, "\x80");
    else { formatAltBuf(ApA_m, vb, sizeof(vb)); orbPut(2, 110, ORB_RDY3, 360, vb); }
    // Row 3 — PRD (orbital period)
    if (drawSc.isEscape)                 orbPut(3, INC_VALUE_X, INC_RDY1, 348, "\x80");
    else if (state.orbitalPeriod > 0.0f) { formatTimeCompactBuf(state.orbitalPeriod, vb, sizeof(vb)); orbPut(3, INC_VALUE_X, INC_RDY1, 348, vb); }
    else                                 orbPut(3, INC_VALUE_X, INC_RDY1, 348, "---");
    // Row 4 — Arg.Pe
    {
        char buf[10]; dtostrf(state.argOfPe, 1, 1, buf);
        snprintf(vb, sizeof(vb), "%s\xb0", buf);
        orbPut(4, INC_VALUE_X, INC_RDY2, 348, vb);
    }
    // Row 5 — T+Pe / T+Ap (dynamic label + value)
    // Pick whichever is next in time, i.e. whichever positive value is smaller.
    // If one is ≤ 0 (already passed or unavailable), use the other. If both
    // are ≤ 0, show "---". For escape orbits Ap doesn't exist, so always show
    // T+Pe regardless of its value.
    {
        // Use the RAW values here, not the fmaxf-clamped ones, so we can
        // distinguish "passed/unavailable" (≤0) from "future" (>0).
        float rawPe = state.timeToPe;
        float rawAp = state.timeToAp;

        bool showPe;
        if (drawSc.isEscape) {
            showPe = true;  // no Ap on escape
        } else if (rawPe > 0.0f && rawAp > 0.0f) {
            showPe = (rawPe <= rawAp);  // both valid — pick nearest
        } else if (rawPe > 0.0f) {
            showPe = true;   // only Pe valid
        } else if (rawAp > 0.0f) {
            showPe = false;  // only Ap valid
        } else {
            showPe = true;   // neither valid — default to Pe, will show "---"
        }

        int8_t nowLabel = showPe ? 0 : 1;
        if (nowLabel != _lastTLabel) {
            // Label flipped — redraw label. fillRect only fires on the flip,
            // not every frame, so no flicker.
            tft.fillRect(INC_LABEL_X, INC_RDY3, 100, RH, TFT_BLACK);
            tft.setFont(*F);
            tft.setTextColor(KDC_LABEL_COLOR, TFT_BLACK);
            tft.setCursor(INC_LABEL_X, INC_RDY3);
            tft.print(showPe ? "T+PE" : "T+AP");
            _lastTLabel = nowLabel;
        }
        float t = showPe ? rawPe : rawAp;
        if (t > 0.0f) { formatTimeCompactBuf(t, vb, sizeof(vb)); orbPut(5, INC_VALUE_X, INC_RDY3, 348, vb); }
        else          orbPut(5, INC_VALUE_X, INC_RDY3, 348, "---");
    }

    // Row 6 (INCL top) — Inc (inclination, degrees)
    // Label "INC" is grey chrome (drawn in chromeScreen_ORB). Value is the
    // inclination in degrees to 1 decimal place, dark-green like the other
    // readouts.
    {
        char buf[10]; dtostrf(drawSc.incl_deg, 1, 1, buf);
        snprintf(vb, sizeof(vb), "%s\xb0", buf);
        orbPut(6, INC_VALUE_X, INC_RDY0, 348, vb);
    }

    // Optional: total frame timing (very lightweight — only prints on scene repaint)
    if (debugMode && sceneNeedsRepaint) {
        uint32_t frameEnd = micros();
        Serial.print(F("[ORB] frame total="));
        Serial.print(frameEnd - frameStart);
        Serial.println(F("us"));
    }
}

/***************************************************************************************
   Screen_ORBT_AP.ino — Orbital Autopilot console (chrome + draw + touch)

   Touch console for the burn autopilot on Controller_Main: maneuver node executor,
   apoapsis / periapsis burns, plane change and the rendezvous approach-rate hold.
   Renders the 52-byte orbital status frame (state.ob*). Design: Mission_Autopilot.md §4.

   LAYOUT (the shared console grid — ConsoleShared.ino):
     banner: <armed mode | A/P OFF>  <phase / reason>   body · vessel  <ARMED / EXECUTING / A/P OFF>
     BURN               | TARGET / OPTIONS     | PLAN
     [NODE] node ΔV     | [APPR] [rate]        | ΔV TOT
     [AP]   [target Ap] | HOLD AT [distance]   | ΔV REM
     [PE]   [target Pe] | WARP    [AUTO/OFF]   | T-IGN
     [INC]  [target i]  | STAGE   [AUTO/OFF]   | BURN
     hint               |                      | ACCEL
     legend             | [EXEC/WARP] [A/P OFF]| STG ΔV
                        |                      | RANGE

   Burns are two-step: arming a mode plans it and fills the PLAN column; EXEC starts
   the executor. Once aligned with WARP on, the button reads WARP and a second tap
   warps to ignition minus the lead — the executor never warps unasked. A/P OFF aborts.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

static const uint16_t OB_LBL = KDC_LABEL_COLOR;
static const uint16_t OB_VAL = TFT_DARK_GREEN;
static const uint16_t OB_EDT = TFT_SKY;
#define OB_F_LBL  (&Roboto_Black_24)
#define OB_F_BANN (&Roboto_Black_36)

// Burn modes: 0 NODE, 1 AP, 2 PE, 3 INC (state.obMode 1..4). Approach is mode 4 here.
static const uint8_t OB_BURNS = 4;
static const char *const OB_BURN_LBL[OB_BURNS] = { "NODE", "AP", "PE", "INC" };
static const uint8_t     OB_ARM_OP[OB_BURNS]   = { OB_CMD_ARM_NODE, OB_CMD_ARM_AP, OB_CMD_ARM_PE, OB_CMD_ARM_INC };
static const uint8_t     OB_SET_OP[OB_BURNS]   = { 0, OB_CMD_SET_AP, OB_CMD_SET_PE, OB_CMD_SET_INC };

// Row-cache slots
static const uint8_t OB_SLOT_BTN   = 0;    // 0..3 burn buttons, 4 APPR
static const uint8_t OB_SLOT_VAL   = 5;    // 5..8 burn boxes, 9 appr rate, 10 hold at, 11 warp, 12 stage
static const uint8_t OB_SLOT_PLAN  = 13;   // 13..19
static const uint8_t OB_SLOT_EXEC  = 20;
static const uint8_t OB_SLOT_BANN  = 21;

static const int16_t OB_BIG_W = 145;
static const int16_t OB_EXEC_X = CON_C2X;
static const int16_t OB_OFF_X  = CON_C2X + 153;

static const uint32_t OB_PENDING_TIMEOUT_MS = 3000;

static int8_t   obPendArm[OB_BURNS];   // -1 none, 0 disarm sent, 1 arm sent
static uint32_t obPendArmMs[OB_BURNS];
static bool     obDirtyTgt[OB_BURNS];  static float obPendTgt[OB_BURNS];
static int8_t   obPendAppr = -1;       static uint32_t obPendApprMs = 0;
static bool     obDirtyRate = false, obDirtyDist = false; static float obPendRate = 0.0f, obPendDist = 0.0f;
static int8_t   obPendWarp = -1, obPendStage = -1; static uint32_t obPendWarpMs = 0, obPendStageMs = 0;
static uint8_t  obExecPendPhase = 0;   static uint32_t obExecPendMs = 0;   // phase we expect after EXEC
static bool     obScreenRefresh = false;

static bool obArmedMode(uint8_t i)  { return state.obMode == (uint8_t)(i + 1) && (state.obFlags & 0x01); }
static bool obApprEngaged()         { return (state.obFlags & 0x40) != 0; }
static bool obWarpAuto()            { return (state.obFlags & 0x04) != 0; }
static bool obStageAuto()           { return (state.obFlags & 0x08) != 0; }
static float obTgtEcho(uint8_t i)   { return i == 1 ? state.obTargetAp : i == 2 ? state.obTargetPe : state.obTargetInc; }

const char *obPhaseName(uint8_t p) {
  switch (p) {
    case 1: return "PLANNED"; case 2: return "ALIGNING"; case 3: return "WARP READY"; case 4: return "WARPING";
    case 5: return "BURNING"; case 6: return "DONE"; case 7: return "ABORT"; default: return "";
  }
}

static void obReconcile() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < OB_BURNS; i++) {
    if (obPendArm[i] >= 0 && (obArmedMode(i) == (obPendArm[i] == 1) || now - obPendArmMs[i] > OB_PENDING_TIMEOUT_MS)) obPendArm[i] = -1;
    if (obDirtyTgt[i] && fabsf(obTgtEcho(i) - obPendTgt[i]) < (i == 3 ? 0.05f : 0.5f)) obDirtyTgt[i] = false;
  }
  if (obPendAppr >= 0 && (obApprEngaged() == (obPendAppr == 1) || now - obPendApprMs > OB_PENDING_TIMEOUT_MS)) obPendAppr = -1;
  if (obDirtyRate && fabsf(state.obApprRate - obPendRate) < 0.05f) obDirtyRate = false;
  if (obDirtyDist && fabsf(state.obApprDist - obPendDist) < 0.5f) obDirtyDist = false;
  if (obPendWarp >= 0  && (obWarpAuto()  == (obPendWarp == 1)  || now - obPendWarpMs  > OB_PENDING_TIMEOUT_MS)) obPendWarp = -1;
  if (obPendStage >= 0 && (obStageAuto() == (obPendStage == 1) || now - obPendStageMs > OB_PENDING_TIMEOUT_MS)) obPendStage = -1;
  if (obExecPendPhase && (state.obPhase >= obExecPendPhase || state.obPhase == 7 || now - obExecPendMs > OB_PENDING_TIMEOUT_MS)) obExecPendPhase = 0;
}

static void obFmtTime(float s, char *buf, size_t n) {
  bool neg = s < 0.0f; if (neg) s = -s;
  uint32_t t = (uint32_t)(s + 0.5f);
  if (t >= 3600) snprintf(buf, n, "%s%lu:%02lu:%02lu", neg ? "-" : "", (unsigned long)(t / 3600), (unsigned long)((t / 60) % 60), (unsigned long)(t % 60));
  else           snprintf(buf, n, "%s%lu:%02lu", neg ? "-" : "", (unsigned long)(t / 60), (unsigned long)(t % 60));
}

// ── Chrome ───────────────────────────────────────────────────────────────────────────
void chromeScreen_ORBTAP(KCM_TFT &tft) {
  kpForceClose();
  conDrawColumns(tft, "BURN", "TARGET / OPTIONS", "PLAN");
  for (uint8_t i = 0; i < OB_BURNS; i++) conDrawValueBox(tft, CON_C1X, i);
  conDrawValueBox(tft, CON_C2X, 0);
  textLeft(tft, OB_F_LBL, CON_C2X + 4, conRowY(1), CON_COLW - CON_VALW, CON_ROW_H, "HOLD AT", OB_LBL, TFT_BLACK);
  conDrawValueBox(tft, CON_C2X, 1);
  textLeft(tft, OB_F_LBL, CON_C2X + 4, conRowY(2), CON_COLW - CON_VALW, CON_ROW_H, "WARP", OB_LBL, TFT_BLACK);
  textLeft(tft, OB_F_LBL, CON_C2X + 4, conRowY(3), CON_COLW - CON_VALW, CON_ROW_H, "STAGE", OB_LBL, TFT_BLACK);
  static const char *const PLAN_LBL[7] = { "\x94V TOT", "\x94V REM", "T-IGN", "BURN", "ACCEL", "STG \x94V", "RANGE" };
  for (uint8_t r = 0; r < 7; r++)
    textLeft(tft, OB_F_LBL, CON_C3X + 4, conRowY(r), CON_COLW - CON_VALW, CON_ROW_H, PLAN_LBL[r], OB_LBL, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 8,  CON_COLW - 8, 20, "Arm one burn, review the PLAN column,", TFT_DARK_GREY, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 28, CON_COLW - 8, 20, "then EXEC. A/P OFF aborts at any phase.", TFT_DARK_GREY, TFT_BLACK);
  int16_t ly = conRowY(5) + 12, lx = CON_C1X + 2;
  tft.drawRect(lx, ly, 92, 28, TFT_GREY);             textCenter(tft, &Roboto_Black_16, lx, ly, 92, 28, "OFF", TFT_WHITE, TFT_BLACK);
  tft.drawRect(lx + 100, ly, 92, 28, TFT_CYAN);       textCenter(tft, &Roboto_Black_16, lx + 100, ly, 92, 28, "PENDING", TFT_CYAN, TFT_BLACK);
  tft.fillRect(lx + 200, ly, 92, 28, TFT_DARK_GREEN); textCenter(tft, &Roboto_Black_16, lx + 200, ly, 92, 28, "ENGAGED", TFT_WHITE, TFT_DARK_GREEN);
  ButtonLabel b = { "A/P OFF", TFT_WHITE, TFT_WHITE, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
  drawButton(tft, OB_OFF_X, CON_BIG_Y, OB_BIG_W, CON_BIG_H, b, &Roboto_Black_28, false);
  textCenter(tft, &Roboto_Black_16, OB_OFF_X, CON_BIG_Y + CON_BIG_H - 26, OB_BIG_W, 18, "abort / disarm", TFT_GREY, TFT_OFF_BLACK);
}

// ── Draw ─────────────────────────────────────────────────────────────────────────────
static void obToggleBox(KCM_TFT &tft, uint8_t slot, uint8_t row, bool on, bool pending) {
  RowCache &rc = rowCache[screen_ORBTAP][slot];
  char k[8]; snprintf(k, sizeof(k), "%d%d", on, pending);
  if (rc.value == k) return;
  int16_t x = conValX(CON_C2X), y = conRowY(row) + 4, w = CON_VALW - 2, h = CON_VALH;
  tft.fillRect(x, y, w, h, on ? TFT_DARK_GREEN : TFT_BLACK);
  tft.drawRect(x, y, w, h, pending ? TFT_CYAN : TFT_GREY);
  textCenter(tft, &Roboto_Black_24, x, y, w, h, on ? "AUTO" : "OFF", pending ? TFT_CYAN : TFT_WHITE, on ? TFT_DARK_GREEN : TFT_BLACK);
  rc.value = k;
}

void drawScreen_ORBTAP(KCM_TFT &tft) {
  if (kpTakeClosed()) obScreenRefresh = true;
  if (obScreenRefresh) {
    tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
    chromeScreen_ORBTAP(tft);
    invalidateRowCache(screen_ORBTAP);
    obScreenRefresh = false;
  }
  if (kpIsOpen()) { kpDraw(tft); return; }

  char buf[48];
  bool armed = (state.obFlags & 0x01) != 0, executing = (state.obFlags & 0x02) != 0;
  bool anyPending = obPendAppr >= 0 || obExecPendPhase != 0;
  for (uint8_t i = 0; i < OB_BURNS; i++) if (obPendArm[i] >= 0) anyPending = true;

  // Banner
  {
    const char *modeName = armed ? OB_BURN_LBL[state.obMode ? state.obMode - 1 : 0] : (obApprEngaged() ? "APPR" : "A/P OFF");
    bool engaged = armed || obApprEngaged();
    bool showReason = (state.obReason != HP_REASON_NONE && state.obReasonAge <= 5);
    const char *note = showReason ? hpReasonLabel(state.obReason) : obPhaseName(state.obPhase);
    char key[112];
    snprintf(key, sizeof(key), "%s|%s|%s|%d|%d|%s", modeName, note, state.gameSOI.c_str(), anyPending, executing, state.vesselName.c_str());
    RowCache &rc = rowCache[screen_ORBTAP][OB_SLOT_BANN];
    if (rc.value != key) {
      tft.fillRect(0, CON_BANNER_Y, CONTENT_W, CON_BANNER_H, TFT_BLACK);
      textLeft(tft, OB_F_BANN, 8, CON_BANNER_Y, 316, CON_BANNER_H, modeName, engaged ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
      if (note[0]) textLeft(tft, &Roboto_Black_24, 330, CON_BANNER_Y, 300, CON_BANNER_H, note, showReason ? TFT_ORANGE : (state.obPhase == 6 ? TFT_SKY : TFT_ORANGE), TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s \xB7 %s", state.gameSOI.c_str(), state.vesselName.c_str());
      textRight(tft, &Roboto_Black_20, 648, CON_BANNER_Y + 4,  CONTENT_W - 648 - 6, 24, buf, OB_LBL, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s%s", executing ? "EXECUTING" : engaged ? (armed ? "ARMED" : "ENGAGED") : "A/P OFF", anyPending ? "..." : "");
      textRight(tft, &Roboto_Black_28, 648, CON_BANNER_Y + 30, CONTENT_W - 648 - 6, 30, buf, engaged ? TFT_NEON_GREEN : TFT_DARK_GREY, TFT_BLACK);
      rc.value = key;
    }
  }

  // Burn buttons + boxes
  int16_t vx = conValX(CON_C1X) + 6, vw = CON_VALW - 10;
  for (uint8_t i = 0; i < OB_BURNS; i++) {
    ConBtnState st = obArmedMode(i) ? CON_BTN_ON : (obPendArm[i] >= 0 ? CON_BTN_PENDING : CON_BTN_OFF);
    RowCache &rc = rowCache[screen_ORBTAP][OB_SLOT_BTN + i];
    char k[4]; snprintf(k, sizeof(k), "%d", (int)st);
    if (rc.value != k) { conDrawModeButton(tft, CON_C1X + 2, conRowY(i) + 4, CON_BTN_W, CON_VALH, OB_BURN_LBL[i], st); rc.value = k; }
    uint16_t fg;
    if (i == 0) {
      bool node = (state.obFlags & 0x20) != 0 || state.mnvrDeltaV > 0.01f;
      if (node) snprintf(buf, sizeof(buf), "%.0f m/s", state.mnvrDeltaV); else snprintf(buf, sizeof(buf), "NO NODE");
      fg = obArmedMode(0) ? OB_VAL : TFT_DARK_GREY;
    } else {
      float v = obDirtyTgt[i] ? obPendTgt[i] : obTgtEcho(i);
      if (i == 3) snprintf(buf, sizeof(buf), "%.1f\xB0", v); else formatAltBuf(v, buf, sizeof(buf));
      fg = obDirtyTgt[i] ? OB_EDT : (obArmedMode(i) ? OB_VAL : TFT_DARK_GREY);
    }
    conPut(tft, screen_ORBTAP, OB_SLOT_VAL + i, vx, conRowY(i) + 4, vw, CON_VALH, buf, fg);
  }

  // APPR + options
  {
    ConBtnState st = obApprEngaged() ? CON_BTN_ON : (obPendAppr >= 0 ? CON_BTN_PENDING : CON_BTN_OFF);
    RowCache &rc = rowCache[screen_ORBTAP][OB_SLOT_BTN + 4];
    char k[4]; snprintf(k, sizeof(k), "%d", (int)st);
    if (rc.value != k) { conDrawModeButton(tft, CON_C2X + 2, conRowY(0) + 4, CON_BTN_W, CON_VALH, "APPR", st); rc.value = k; }
  }
  int16_t ox = conValX(CON_C2X) + 6;
  snprintf(buf, sizeof(buf), "%+.1f m/s", obDirtyRate ? obPendRate : state.obApprRate);
  conPut(tft, screen_ORBTAP, OB_SLOT_VAL + 4, ox, conRowY(0) + 4, vw, CON_VALH, buf, obDirtyRate ? OB_EDT : (obApprEngaged() ? OB_VAL : TFT_DARK_GREY));
  snprintf(buf, sizeof(buf), "%.0f m", obDirtyDist ? obPendDist : state.obApprDist);
  conPut(tft, screen_ORBTAP, OB_SLOT_VAL + 5, ox, conRowY(1) + 4, vw, CON_VALH, buf, obDirtyDist ? OB_EDT : OB_VAL);
  obToggleBox(tft, OB_SLOT_VAL + 6, 2, obPendWarp  >= 0 ? (obPendWarp  == 1) : obWarpAuto(),  obPendWarp  >= 0);
  obToggleBox(tft, OB_SLOT_VAL + 7, 3, obPendStage >= 0 ? (obPendStage == 1) : obStageAuto(), obPendStage >= 0);

  // EXEC / WARP button: green outline when a tap does something, grey otherwise
  {
    bool canExec = (state.obPhase == 1), canWarp = (state.obPhase == 3 && obWarpAuto());
    const char *txt = canWarp ? "WARP" : "EXEC";
    const char *hint = canWarp ? "warp to ignition" : canExec ? "start the burn" : executing ? obPhaseName(state.obPhase) : "arm a burn first";
    bool pending = obExecPendPhase != 0;
    RowCache &rc = rowCache[screen_ORBTAP][OB_SLOT_EXEC];
    char key[40]; snprintf(key, sizeof(key), "%s|%s|%d", txt, hint, pending);
    if (rc.value != key) {
      uint16_t col = pending ? TFT_CYAN : (canExec || canWarp) ? TFT_NEON_GREEN : TFT_GREY;
      ButtonLabel b = { txt, col, col, TFT_OFF_BLACK, TFT_OFF_BLACK, col, col };
      drawButton(tft, OB_EXEC_X, CON_BIG_Y, OB_BIG_W, CON_BIG_H, b, &Roboto_Black_28, false);
      textCenter(tft, &Roboto_Black_16, OB_EXEC_X, CON_BIG_Y + CON_BIG_H - 26, OB_BIG_W, 18, hint, TFT_GREY, TFT_OFF_BLACK);
      rc.value = key;
    }
  }

  // PLAN
  int16_t px = conValX(CON_C3X) + 6;
  bool plan = armed && state.obDvTotal > 0.0f;
  if (plan) snprintf(buf, sizeof(buf), "%.0f m/s", state.obDvTotal); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 0, px, conRowY(0) + 4, vw, CON_VALH, buf, plan ? OB_VAL : TFT_DARK_GREY);
  if (plan) snprintf(buf, sizeof(buf), "%.0f m/s", state.obDvRemaining); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 1, px, conRowY(1) + 4, vw, CON_VALH, buf, plan ? (state.obPhase == 5 ? TFT_NEON_GREEN : OB_VAL) : TFT_DARK_GREY);
  if (plan) obFmtTime(-state.obTIgnition, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 2, px, conRowY(2) + 4, vw, CON_VALH, buf, plan ? (state.obTIgnition < 30.0f ? TFT_ORANGE : OB_VAL) : TFT_DARK_GREY);
  if (plan) obFmtTime(state.obBurnDuration, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 3, px, conRowY(3) + 4, vw, CON_VALH, buf, plan ? OB_VAL : TFT_DARK_GREY);
  if (state.obAccelEst > 0.0f) snprintf(buf, sizeof(buf), "%.1f m/s\xB2", state.obAccelEst); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 4, px, conRowY(4) + 4, vw, CON_VALH, buf, state.obAccelEst > 0.0f ? OB_VAL : TFT_DARK_GREY);
  snprintf(buf, sizeof(buf), "%.0f m/s", state.stageDeltaV);
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 5, px, conRowY(5) + 4, vw, CON_VALH, buf, (plan && state.stageDeltaV < state.obDvTotal) ? TFT_ORANGE : OB_VAL);
  if (state.targetAvailable) formatAltBuf(state.tgtDistance, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ORBTAP, OB_SLOT_PLAN + 6, px, conRowY(6) + 4, vw, CON_VALH, buf, state.targetAvailable ? OB_VAL : TFT_DARK_GREY);
}

// ── Keypad commits ───────────────────────────────────────────────────────────────────
static void obTargetCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx < 1 || idx >= OB_BURNS) return;
  obPendTgt[idx] = v;
  obDirtyTgt[idx] = apEnqueueCmd(OB_SET_OP[idx], v);
}
static void obApprCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx == 0) { obPendRate = v; obDirtyRate = apEnqueueCmd(OB_CMD_SET_APPR_RATE, v); }
  else          { obPendDist = v; obDirtyDist = apEnqueueCmd(OB_CMD_SET_APPR_DIST, v); }
}

// ── Touch ────────────────────────────────────────────────────────────────────────────
void orbtApScreenTouch(uint16_t x, uint16_t y) {
  if (kpIsOpen()) { kpTouch(x, y); return; }
  uint32_t now = millis();

  if (y >= CON_BIG_Y && y < CON_BIG_Y + CON_BIG_H) {
    if (x >= OB_EXEC_X && x < OB_EXEC_X + OB_BIG_W) {
      if (state.obPhase == 1 || (state.obPhase == 3 && obWarpAuto())) {
        if (apEnqueueCmd(OB_CMD_EXEC, 0.0f)) { obExecPendPhase = (state.obPhase == 1) ? 2 : 4; obExecPendMs = now; }
      }
      return;
    }
    if (x >= OB_OFF_X && x < OB_OFF_X + OB_BIG_W) {
      if (apEnqueueCmd(HP_CMD_AP_OFF, 0.0f)) {
        for (uint8_t i = 0; i < OB_BURNS; i++) if (obArmedMode(i)) { obPendArm[i] = 0; obPendArmMs[i] = now; }
        if (obApprEngaged()) { obPendAppr = 0; obPendApprMs = now; }
      }
      return;
    }
  }

  // Burn column
  for (uint8_t r = 0; r < OB_BURNS; r++) {
    int16_t cy = conRowY(r);
    if (y < cy || y >= cy + CON_ROW_H) continue;
    if (x >= CON_C1X + 2 && x < CON_C1X + 2 + CON_BTN_W) {
      bool want = !(obPendArm[r] >= 0 ? (obPendArm[r] == 1) : obArmedMode(r));
      if (apEnqueueCmd(OB_ARM_OP[r], want ? 1.0f : 0.0f)) { obPendArm[r] = want ? 1 : 0; obPendArmMs[r] = now; }
      return;
    }
    if (r >= 1 && x >= conValX(CON_C1X) && x < conValX(CON_C1X) + CON_VALW) {
      if (state.obPhase == 5) return;   // no edits during a burn
      KpField f = (r == 1) ? KpField{ "TARGET APOAPSIS", "m", 0.0f, 2000000000.0f, false, false, 0 }
                : (r == 2) ? KpField{ "TARGET PERIAPSIS", "m", 0.0f, 2000000000.0f, false, false, 0 }
                           : KpField{ "TARGET INCLINATION", "\xB0", 0.0f, 180.0f, false, false, 1 };
      kpOpen(f, (int8_t)r, obTargetCommit);
      return;
    }
  }
  // Target / options column
  for (uint8_t r = 0; r < 4; r++) {
    int16_t cy = conRowY(r);
    if (y < cy || y >= cy + CON_ROW_H || x < CON_C2X || x >= CON_C2X + CON_COLW) continue;
    if (r == 0 && x < CON_C2X + 2 + CON_BTN_W) {
      bool want = !(obPendAppr >= 0 ? (obPendAppr == 1) : obApprEngaged());
      if (apEnqueueCmd(OB_CMD_ENGAGE_APPR, want ? 1.0f : 0.0f)) { obPendAppr = want ? 1 : 0; obPendApprMs = now; }
      return;
    }
    if (x < conValX(CON_C2X)) return;
    switch (r) {
      case 0: { KpField f = { "APPROACH RATE", "m/s", -20.0f, 5.0f, false, true, 1 }; kpOpen(f, 0, obApprCommit); break; }
      case 1: { KpField f = { "HOLD DISTANCE", "m", 5.0f, 5000.0f, false, false, 0 }; kpOpen(f, 1, obApprCommit); break; }
      case 2: { bool want = !(obPendWarp  >= 0 ? (obPendWarp  == 1) : obWarpAuto());  if (apEnqueueCmd(OB_CMD_SET_WARP,      want ? 1.0f : 0.0f)) { obPendWarp  = want ? 1 : 0; obPendWarpMs  = now; } break; }
      case 3: { bool want = !(obPendStage >= 0 ? (obPendStage == 1) : obStageAuto()); if (apEnqueueCmd(OB_CMD_SET_AUTOSTAGE, want ? 1.0f : 0.0f)) { obPendStage = want ? 1 : 0; obPendStageMs = now; } break; }
    }
    return;
  }
}

/***************************************************************************************
   KCMk1 Information Display — ORB ADVANCED MODE
   --------------------------------------------------------------------------------------

   Purpose:
     Text-only full-numeric readout of every orbital element available from
     KerbalSimpit's ORBIT_INFO, APSIDES, APSIDES_TIME, ALTITUDE, and VELOCITY
     messages. Intended as a deep-dive view for orbital-mechanics work — the
     default APSIDES view (Screen_ORB.ino) remains the pilot-friendly graphic
     view.

   Access:
     Its own sidebar screen (screen_ORBADV), reached by cycling the ORB key:
     ORB -> ORB+ -> MNVR. AAA_Screens.ino dispatches its chrome and draw directly.

   Layout (rev-2, 940x600 content):
     Two columns of 7 rows each, Roboto_Black_36, 73 px row pitch starting at
     y=90 so the 7 rows fill the full height (last row bottom ~y=571). The
     panel divider sits at x=470 (matching the basic ORB screen); the left
     column fills x=[0,470], the right column x=[470,940]. Left column is
     shape/size quantities; right column is orientation/position quantities.
     Labels white, values dark-green, right-justified to an 8 px inset from
     each half's edge — matches the basic ORB screen's conventions.

   Flicker management:
     Each value uses its own PrintState + cached String so printValue only
     redraws when the displayed text changes (same pattern as basic ORB).
     No scene graphics = no repaint gate needed. Chrome draws all labels
     once; draw() only touches values.

   Formatting:
     - Distances (SMA, Pe, Ap, Alt): formatAlt() — auto-switches m/km/Mm.
     - Velocity: integer m/s, "m/s" suffix.
     - Angles (Inc, LAN, ArgPe, True Anom, Mean Anom): 1 decimal, "°" suffix.
     - Eccentricity: 4 decimal places.
     - Times (T+Pe, T+Ap, Period): formatTimeCompact() — MM:SS under 1h, compact Hh/Dd above.

   Hidden cases:
     - Escape orbit: Ap, Period, T+Ap show "\x80" (infinity glyph); T+Pe still
       valid and Mean Anom still defined.
     - Pe below surface: Pe shows "---".
     - T+Pe or T+Ap negative / unavailable: shows "---".

****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// ── Layout constants ─────────────────────────────────────────────────────────────────
// Font: Roboto_Black_36 (cap 43, line_space 48). Row pitch 73 px gives ~25 px
// between rows; 7 rows from y=90 span to a last-row bottom of ~571, filling the
// full 600 px height. Value columns are right-justified to an 8 px inset from
// each half's edge (left → x=462 at the divider, right → x=930 at the content
// edge). Widest labels: "SMA" 91 px (left), "ARG.PE" 159 px (right) — both
// clear their value columns.
static const int16_t ADV_TITLE_TOP  = TITLE_TOP;
static const int16_t ADV_ROW_PITCH  = 73;
static const int16_t ADV_ROW_H      = 48;   // printValue clear height (matches font)
static const int16_t ADV_ROW_Y0     = 90;   // first row top

// Column layout — divider at x=470 (matches basic ORB)
static const int16_t ADV_L_LABEL_X  = 14;
static const int16_t ADV_L_VALUE_X  = 150;
static const int16_t ADV_L_VALUE_W  = 320;  // right edge 150+320-8 = 462

static const int16_t ADV_R_LABEL_X  = 480;
// Value column shifted right so the widest labels ("TRUE ANOM" / "MEAN ANOM",
// ~207px, ending ~x=687) clear the value region (regionX = 690+9 = 699). The
// wide time values (T+Pe/T+Ap) belong to short labels, so they still fit.
static const int16_t ADV_R_VALUE_X  = 690;
static const int16_t ADV_R_VALUE_W  = 248;  // right edge 690+248-8 = 930

// Row slot indices (left column 0..6, right column 7..13)
enum {
    ADV_SMA = 0, ADV_ECC, ADV_PE_L, ADV_AP_L, ADV_ALT, ADV_VEL, ADV_PRD,
    ADV_INC = 7, ADV_LAN, ADV_ARGPE, ADV_TA, ADV_MA, ADV_TPE, ADV_TAP,
    ADV_SLOT_COUNT = 14
};

// ── Public entry points ──────────────────────────────────────────────────────────────
void chromeScreen_OrbAdv(KCM_TFT &tft) {
    // Reset the print states so every value gets a full clear on first draw. (The row
    // cache itself is invalidated by drawStaticScreen() after this chrome.)
    for (uint8_t i = 0; i < ADV_SLOT_COUNT; i++) printState[screen_ORBADV][i] = PrintState{};

    // Panel divider — matches basic ORB for visual continuity (x=470, full height)
    tft.drawLine(CONTENT_W / 2,     ADV_TITLE_TOP, CONTENT_W / 2,     SCREEN_H, TFT_GREY);
    tft.drawLine(CONTENT_W / 2 + 1, ADV_TITLE_TOP, CONTENT_W / 2 + 1, SCREEN_H, TFT_GREY);

    // Draw all labels once, in the panel-wide label grey; values are drawn by
    // drawScreen_OrbAdv on each update (dark green).
    tft.setFont(Roboto_Black_36);
    tft.setTextColor(KDC_LABEL_COLOR, TFT_BLACK);

    // Left column labels
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 0 * ADV_ROW_PITCH); tft.print("SMA");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 1 * ADV_ROW_PITCH); tft.print("ECC");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 2 * ADV_ROW_PITCH); tft.print("PEA");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 3 * ADV_ROW_PITCH); tft.print("APA");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 4 * ADV_ROW_PITCH); tft.print("ALT.SL");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 5 * ADV_ROW_PITCH); tft.print("V.ORB");
    tft.setCursor(ADV_L_LABEL_X, ADV_ROW_Y0 + 6 * ADV_ROW_PITCH); tft.print("PERIOD");

    // Right column labels
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 0 * ADV_ROW_PITCH); tft.print("INC");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 1 * ADV_ROW_PITCH); tft.print("LAN");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 2 * ADV_ROW_PITCH); tft.print("ARG.PE");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 3 * ADV_ROW_PITCH); tft.print("TRUE ANOM");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 4 * ADV_ROW_PITCH); tft.print("MEAN ANOM");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 5 * ADV_ROW_PITCH); tft.print("T+PE");
    tft.setCursor(ADV_R_LABEL_X, ADV_ROW_Y0 + 6 * ADV_ROW_PITCH); tft.print("T+AP");
}

void drawScreen_OrbAdv(KCM_TFT &tft) {
    const tFont *F = &Roboto_Black_36;

    // Cache-checked value draw backed by the shared row cache (rowCache[screen_ORBADV]).
    // Value-only compare — colour is always dark green on black. rowN selects the row Y.
    // Values arrive as C strings in stack buffers; the cache compare allocates nothing
    // and a String is built only for the value about to be drawn. Fourteen rows at the
    // frame rate used to be fourteen heap allocations a frame for a screen that mostly
    // shows the same figures.
    auto advPut = [&](uint8_t slot, uint16_t x, uint16_t w, uint8_t rowN, const char *v) {
        RowCache &rc = rowCache[screen_ORBADV][slot];
        if (rc.value == v) return;
        String s(v);
        printValue(tft, F, x, ADV_ROW_Y0 + rowN * ADV_ROW_PITCH, w, ADV_ROW_H, "",
                   s, TFT_DARK_GREEN, TFT_BLACK, TFT_BLACK, printState[screen_ORBADV][slot]);
        rc.value = s;
    };
    char vb[48];
    auto deg = [&](float d) { char t[12]; dtostrf(d, 1, 1, t); snprintf(vb, sizeof(vb), "%s\xb0", t); return (const char *)vb; };

    // Escape detection — matches basic ORB logic. An escape (open) trajectory
    // has no Ap and no period.
    bool isEscape = (state.eccentricity >= 1.0f) || (state.apoapsis < 0.0f);
    char buf[16];

    // ── Left column ──────────────────────────────────────────────────────────────────
    formatAltBuf(state.semiMajorAxis, vb, sizeof(vb));
    advPut(ADV_SMA, ADV_L_VALUE_X, ADV_L_VALUE_W, 0, vb);
    dtostrf(state.eccentricity, 1, 4, buf);
    advPut(ADV_ECC, ADV_L_VALUE_X, ADV_L_VALUE_W, 1, buf);
    if (state.periapsis >= 0.0f) { formatAltBuf(state.periapsis, vb, sizeof(vb)); advPut(ADV_PE_L, ADV_L_VALUE_X, ADV_L_VALUE_W, 2, vb); }
    else                         advPut(ADV_PE_L, ADV_L_VALUE_X, ADV_L_VALUE_W, 2, "---");   // below surface
    if (isEscape) advPut(ADV_AP_L, ADV_L_VALUE_X, ADV_L_VALUE_W, 3, "\x80");   // infinity on escape
    else { formatAltBuf(state.apoapsis, vb, sizeof(vb)); advPut(ADV_AP_L, ADV_L_VALUE_X, ADV_L_VALUE_W, 3, vb); }
    formatAltBuf(state.altitude, vb, sizeof(vb));
    advPut(ADV_ALT, ADV_L_VALUE_X, ADV_L_VALUE_W, 4, vb);
    fmtMsBuf(state.orbitalVel, vb, sizeof(vb));
    advPut(ADV_VEL, ADV_L_VALUE_X, ADV_L_VALUE_W, 5, vb);
    if (isEscape) advPut(ADV_PRD, ADV_L_VALUE_X, ADV_L_VALUE_W, 6, "\x80");
    else { formatTimeCompactBuf(state.orbitalPeriod, vb, sizeof(vb)); advPut(ADV_PRD, ADV_L_VALUE_X, ADV_L_VALUE_W, 6, vb); }

    // ── Right column ─────────────────────────────────────────────────────────────────
    advPut(ADV_INC,   ADV_R_VALUE_X, ADV_R_VALUE_W, 0, deg(state.inclination));
    advPut(ADV_LAN,   ADV_R_VALUE_X, ADV_R_VALUE_W, 1, deg(state.LAN));
    advPut(ADV_ARGPE, ADV_R_VALUE_X, ADV_R_VALUE_W, 2, deg(state.argOfPe));
    advPut(ADV_TA,    ADV_R_VALUE_X, ADV_R_VALUE_W, 3, deg(state.trueAnomaly));
    advPut(ADV_MA,    ADV_R_VALUE_X, ADV_R_VALUE_W, 4, deg(state.meanAnomaly));

    if (state.timeToPe > 0.0f) { formatTimeCompactBuf(state.timeToPe, vb, sizeof(vb)); advPut(ADV_TPE, ADV_R_VALUE_X, ADV_R_VALUE_W, 5, vb); }
    else                       advPut(ADV_TPE, ADV_R_VALUE_X, ADV_R_VALUE_W, 5, "---");
    if (isEscape)                   advPut(ADV_TAP, ADV_R_VALUE_X, ADV_R_VALUE_W, 6, "\x80");   // infinity on escape
    else if (state.timeToAp > 0.0f) { formatTimeCompactBuf(state.timeToAp, vb, sizeof(vb)); advPut(ADV_TAP, ADV_R_VALUE_X, ADV_R_VALUE_W, 6, vb); }
    else                            advPut(ADV_TAP, ADV_R_VALUE_X, ADV_R_VALUE_W, 6, "---");
}

/***************************************************************************************
   Screen_ROVR.ino -- Rover screen — chromeScreen_ROVR, drawScreen_ROVR
   Dedicated display for type_Rover vessels. contextScreen() routes here automatically.

   Layout (1024 × 600, content area x=0..939, sidebar at x=940..1023):
     LEFT COLUMN (x=0..190, 5 stacked boxes):
       V.Srf    — signed surface speed (m/s), 1 decimal, direction-colored
       ENDUR    — time to empty at the measured net discharge rate (coloured on time)
       BRAKES   — button: white on dark green when on, muted when off
       GEAR     — button: white on dark green when deployed, muted when up
       SAS      — button: navball-palette mode colors (STAB/PRO/RETR/...)

     FWD / REV BLOCKS (top corners of the compass area, flanking the heading box):
       Binary on/off: FWD block green when forward, REV block yellow when reverse,
       both muted (off-black) when neutral

     COMPASS (centered at 470, 344, R=200 — centred on the ROVER title):
       Rotating ring with cardinal letters (N/E/S/W) and numeric labels (03/06/...)
       Fixed nose triangle at top, rover icon at centre
       Heading readout box above (boxed "XXX°" in Roboto_Black_36)
       Target bearing triangle inside ring when state.targetAvailable

     TGT STATUS STRIP (within the compass region, along its bottom, y=552..600):
       DIST and T+TGT (range, and time to reach it at the current closing speed),
       shown only when state.targetAvailable

     RIGHT COLUMN (x=750..940, 3 stacked boxes):
       ALT.TRN  — terrain elevation (altitude ASL - radarAlt AGL), formatted via
                  formatAlt (auto-scales m/km/Mm/Gm with thousands separator)
       Pitch    — side-view tilting silhouette + 1-decimal signed angle
       Roll     — rear-view tilting silhouette + 1-decimal signed angle
                  Silhouettes always drawn in chrome colors; numeric values
                  take threshold color (green/yellow/red per AAA_Config).

   Anti-flicker: each sub-element has its own dirty threshold and incremental
   update. Stationary chrome (borders, labels, ring, nose, rover icon) is drawn
   once in chromeScreen_ROVR and never redrawn.

****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Geometry ──────────────────────────────────────────────────────────────────────────
// Compass ring sized to R=200 and centred at CX=470 (the ROVER title centre,
// CONTENT_W/2) with a taller heading readout box (Roboto_Black_36, cap_height=43).
// CY at 344 places the ring erase floor at y=551, just above the Tgt status strip
// to maintain roughly equal margins above the heading box (12 px) and below the
// ring (13 px).
static const int16_t ROVR_CX             = CONTENT_W / 2;  // centred on the title
static const int16_t ROVR_CY             = 344;
static const int16_t ROVR_R              = 200;   // outer ring radius
static const int16_t ROVR_R_TICK_OUTER   = 196;   // tick outer end (4 px inside outer ring)
                                                  //   so tick-erase can't reach the ring — lets
                                                  //   us skip re-stamping the ring every frame
static const int16_t ROVR_R_TICK_INNER   = 178;   // major tick inner end
static const int16_t ROVR_R_MINOR_INNER  = 185;   // minor tick inner end
static const int16_t ROVR_R_LETTER       = 157;   // cardinal letter centre
static const int16_t ROVR_R_NUMLABEL     = 157;   // numeric label centre — same

// Vessel heading indicator — triangle ABOVE the ring at 12 o'clock, pointing INWARD
// (toward the compass center). Tip closer to centre, base farther out.
static const int16_t ROVR_NOSE_R_TIP     = 204;   // inward tip (4 px outside ring)
static const int16_t ROVR_NOSE_R_BASE    = 219;   // outward base
static const int16_t ROVR_NOSE_HALF_W    = 12;

// Target bearing indicator — triangle INSIDE the ring, positioned just inside
// the compass labels. Labels (Roboto_Black_28) are centred at R=157; their
// opaque glyph boxes reach inward to R≈136. The tip is held at R=128 so that
// even with the 3-px erase-rect dilation (R≈131) the triangle never reaches the
// label boxes — previously the tip at R=135 let a label (e.g. "15") clip the
// triangle when the target bearing lined up with it. Tip points OUTWARD (toward
// the ring); when target heading == vessel heading the triangle sits at 12
// o'clock with its tip pointing up. TFT_VIOLET matches SCFT/ACFT target markers.
static const int16_t ROVR_TGT_R_TIP      = 128;   // outward tip (clears label boxes at R≈136)
static const int16_t ROVR_TGT_R_BASE     = 110;   // inward base (18 px tall triangle)
static const int16_t ROVR_TGT_HALF_W     = 12;   // same half-width as nose

// Target distance readout — shown only when a target is selected (targetAvailable).
// Status strip along the bottom of the compass region, between the two side
// columns and below the ring. Label "DIST" is flush-left against the left column
// (region left edge x=190) and the formatted distance value is flush-right against
// the right column (region right edge x=750). The strip sits just below the
// compass erase region (which ends at y=551), so the two never collide.
// Two pairs share the strip's 560 px (190..750), and at Roboto_Black_36 they did not fit.
// The first budget assumed the widest time was "59m 30s" at 142 px; the actual string is
// "59 m: 30 s" -- formatTimeCompact is IDENTICAL to formatTime below one hour, and that is
// formatTime's minutes form -- which is 171 px against a 155 px cell. textRight aligns to
// the cell's right edge and simply starts further left when the string overruns, so the
// value walked backwards into the "T+TGT" label and sat on top of it. Distance had the
// same defect and was worse: formatAlt/formatSep emit two decimals below 1000, so a plain
// "999.00 m" is 119 px and "999.99 km" is 134, with "999,999 km" at 150.
//
// Dropping the strip to Roboto_Black_28 fixes both with room to spare. Re-measured
// against the real glyph data at Black_28: "DIST" 58, "T+TGT" 85, widest distance 150
// ("999,999 km"), widest time 131 ("59 m: 30 s"). Each value cell is sized so that even a
// string filling it cannot reach back past its own left edge -- the label can then never
// be overwritten, whatever the value formats to.
static const tFont  *ROVR_TGTD_FONT      = &Roboto_Black_28;
static const int16_t ROVR_TGTD_LBL_X     = 190;
static const int16_t ROVR_TGTD_LBL_W     = 70;   // label ends at 256 (190 + 8 + 58)
static const int16_t ROVR_TGTD_VAL_X     = 260;
static const int16_t ROVR_TGTD_VAL_W     = 170;  // right edge = 430; fits 162 px of value
static const int16_t ROVR_TGTT_LBL_X     = 460;  // 30 px clear of the distance value cell
static const int16_t ROVR_TGTT_LBL_W     = 97;   // label ends at 553 (460 + 8 + 85)
static const int16_t ROVR_TGTT_VAL_X     = 560;
static const int16_t ROVR_TGTT_VAL_W     = 190;  // right edge = 750; fits 182 px of value
static const int16_t ROVR_TGTD_Y         = 552;
static const int16_t ROVR_TGTD_H         = 44;   // Roboto_Black_28 cap 33, vertically centred

// Heading readout — single-line boxed value above the nose triangle. The box
// border is stationary chrome; only the numeric value is redrawn on changes.
// Format: zero-padded 3-digit heading with ° symbol (e.g. "045°").
// Box is 38 tall to give the 28pt Roboto Black font (33 px font_height) room
// to render without the glyph cell's black background overwriting the border.
static const int16_t ROVR_HDG_BOX_W      = 110;  // widened slightly for the larger font
static const int16_t ROVR_HDG_BOX_H      = 52;   // Roboto_Black_36 cap 43 + padding
static const int16_t ROVR_HDG_BOX_X      = ROVR_CX - (ROVR_HDG_BOX_W / 2);
static const int16_t ROVR_HDG_BOX_Y      = ROVR_CY - ROVR_NOSE_R_BASE - 6 - ROVR_HDG_BOX_H;

// Rover silhouette (top-down view, stationary at compass centre — represents the
// vessel itself). Forward points up, matching the heading indicator at 12 o'clock.
//
//    ┌─────────┐
//    │  chassis │ ← front (with small notch)
//   [wh]       [wh]
//    │         │
//   [wh]       [wh]
//    └─────────┘
//
// All coordinates are offsets from (ROVR_CX, ROVR_CY).
static const int16_t ROVR_ICON_CHASS_W   = 54;   // chassis rect width
static const int16_t ROVR_ICON_CHASS_H   = 90;   // chassis rect height
static const int16_t ROVR_ICON_WHEEL_W   = 12;   // single wheel rect width
static const int16_t ROVR_ICON_WHEEL_H   = 24;   // single wheel rect height
static const int16_t ROVR_ICON_WHEEL_GAP = 12;   // wheel outer edge extends this far beyond chassis
static const int16_t ROVR_ICON_WHEEL_INSET = 8;  // wheel vertical inset from chassis top/bottom
static const int16_t ROVR_ICON_NOSE_W    = 20;   // nose notch base width (across chassis front)
static const int16_t ROVR_ICON_NOSE_H    = 12;   // nose notch height (extends above chassis)

// ── FWD / REV drive-state blocks ──────────────────────────────────────────────────────
// Two button-style blocks in the top-left and top-right corners of the compass
// area, flanking the heading readout box. Binary drive-state indicators:
//   FWD block — dark-green fill + white text when wheelThrottle > deadband
//   REV block — yellow fill + dark-grey text when wheelThrottle < -deadband
//   both muted (off-black fill) when neutral.
// Both sit at the top corners of the compass region, top-aligned with the title-bar
// rule (y=62, same as the side columns). FWD's left edge is flush with the left
// column's right edge (x=190); REV's right edge is flush with the right column's
// left edge (x=750, so REV_X = 750-168 = 582). The heading box sits between them.
// Boxes clear the ring: at their inner x-edges the ring peaks near y=178, below
// the box bottom at y=139.
static const int16_t ROVR_THRBLK_W       = 168;   // block width (20% larger than 140)
static const int16_t ROVR_THRBLK_H        = 77;   // block height (20% larger than 64)
static const int16_t ROVR_THRBLK_Y        = TITLE_TOP;  // top edge (flush with title-bar rule)
static const int16_t ROVR_FWD_BLK_X       = 190;  // left edge flush with left column
static const int16_t ROVR_REV_BLK_X       = 582;  // right edge flush with right column (582+168 = 750)
static const float   ROVR_THR_THRESH     = 0.01f; // deadband — |wt| under this reads as neutral

// ── Left column: V.Srf / EC% / BRAKE / GEAR / SAS ─────────────────────────────────────
// Five stacked blocks filling the full available height of the left column, from
// the title-bar rule (y=62) down to the screen bottom (y=600). Total height 538 px,
// split into five blocks (108/108/108/107/107). Column x=0..190 (width 190),
// matching the right column width so the compass centres cleanly between them.
static const int16_t ROVR_LCOL_X         = 0;
static const int16_t ROVR_LCOL_W         = 190;
static const int16_t ROVR_LCOL_Y_TOP     = TITLE_TOP;  // flush with the title-bar rule

static const int16_t ROVR_VSRF_H         = 108;
static const int16_t ROVR_EC_H           = 108;
static const int16_t ROVR_BRAKE_H        = 108;
static const int16_t ROVR_GEAR_H         = 107;
static const int16_t ROVR_SAS_H          = 107;

static const int16_t ROVR_VSRF_Y         = ROVR_LCOL_Y_TOP;                   // 62
static const int16_t ROVR_EC_Y           = ROVR_VSRF_Y  + ROVR_VSRF_H;        // 170
static const int16_t ROVR_BRAKE_Y        = ROVR_EC_Y    + ROVR_EC_H;          // 278
static const int16_t ROVR_GEAR_Y         = ROVR_BRAKE_Y + ROVR_BRAKE_H;       // 386
static const int16_t ROVR_SAS_Y          = ROVR_GEAR_Y  + ROVR_GEAR_H;        // 493
                                                                               //   end = 600

// Within V.Srf and EC% blocks: label on top, numeric value below. Both use the
// same internal layout metrics. textCenter is called with the block slot (x, y,
// w, h) so the two lines are centered within each block vertically.
static const int16_t ROVR_LBL_H          = 32;    // label strip height (Roboto_Black_24 cap=29)
static const int16_t ROVR_VAL_H          = 48;    // value strip height (Roboto_Black_36 cap=43)
static const int16_t ROVR_LBL_VAL_GAP    = 2;     // gap between label and value

// ── Right column: elevation / pitch / roll ───────────────────────────────────────────
// Three stacked boxes on the right side of the screen:
//   Elevation — surface ASL altitude (Alt.SL - Alt.Rdr), same block style as V.Srf
//   Pitch     — side-view tilt silhouette + numeric
//   Roll      — rear-view tilt silhouette + numeric
//
// Column x=750..940 (width 190), matching the left column width. Runs the full
// available height from the title-bar rule (y=62) down to the screen bottom (y=600).
static const int16_t ROVR_RCOL_X         = 750;
static const int16_t ROVR_RCOL_W         = 190;
static const int16_t ROVR_ELEV_Y         = TITLE_TOP;  // flush with the title-bar rule
static const int16_t ROVR_ELEV_H         = 108;   // matches left-column block height
static const int16_t ROVR_PITCH_Y        = ROVR_ELEV_Y + ROVR_ELEV_H;   // adjacent to Elev bottom
static const int16_t ROVR_PITCH_H        = 215;
static const int16_t ROVR_ROLL_Y         = ROVR_PITCH_Y + ROVR_PITCH_H;  // adjacent to Pitch bottom
static const int16_t ROVR_ROLL_H         = 215;   // ends at y=600 (screen bottom)

// Within each indicator box:
//   label at top (Roboto_Black_24, height 32)
//   silhouette area in middle (approx 130 px tall)
//   numeric value at bottom (Roboto_Black_36, height 48)
static const int16_t ROVR_TILT_LBL_H     = 32;
static const int16_t ROVR_TILT_VAL_H     = 48;
static const int16_t ROVR_TILT_TOP_PAD   = 4;
static const int16_t ROVR_TILT_GAP       = 2;

// Side-view silhouette dimensions (used for Pitch indicator) — base, unrotated.
// Wide low body with two round wheels beneath, like the side profile of a rover.
static const int16_t ROVR_SIL_BODY_W     = 100;    // pitch-view body width
static const int16_t ROVR_SIL_BODY_H     = 36;    // pitch-view body height
static const int16_t ROVR_SIL_WHEEL_R    = 13;    // pitch-view wheel radius (circle)
static const int16_t ROVR_SIL_WHEEL_DX   = 35;    // horiz offset of wheel centre from body centre
static const int16_t ROVR_SIL_WHEEL_DY   = 26;    // vert offset (below body centre)

// Rear-view silhouette dimensions (used for Roll indicator) — base, unrotated.
// Body height matches pitch silhouette body height (28) so the vehicle feels
// consistently sized across the two indicators. Body width is narrower (50)
// to convey rear-view perspective. Tires appear as rectangles on the SIDES of
// the body (visible tread face), with about half the tire height extending
// below the body.
static const int16_t ROVR_REAR_BODY_W    = 64;    // rear-view body width
static const int16_t ROVR_REAR_BODY_H    = 36;    // rear-view body height (matches pitch body)
static const int16_t ROVR_REAR_TIRE_W    = 13;    // each tire rect width (extends OUTWARD)
static const int16_t ROVR_REAR_TIRE_H    = 26;    // each tire rect height (≈pitch wheel dia)

// Dirty thresholds
static const float   ROVR_HDG_THRESH_DEG = 0.5f;  // compass rotates
static const float   ROVR_TGT_THRESH_DEG = 1.0f;  // target triangle screen position
static const float   ROVR_TILT_THRESH_DEG = 1.0f; // pitch/roll silhouette redraws

// ── State ─────────────────────────────────────────────────────────────────────────────
static float      _rovrPrevHeading      = -9999.0f;
static int16_t    _rovrPrevHdgVal       = -9999;    // last-drawn integer heading (readout)
static bool       _rovrPrevTgtAvail     = false;    // whether target triangle was last drawn
static float      _rovrPrevTgtScreenDeg = -9999.0f; // last-drawn target screen bearing
                                                    //   (targetHdg - vesselHdg wrapped to ±180°)
static int16_t    _rovrPrevThrFill      = -9999;    // last-drawn throttle state code
                                                    //   (+1 = forward, 0 = neutral, -1 = reverse)
static int16_t    _rovrPrevVSrf         = -9999;    // last-drawn signed speed in tenths m/s
                                                    //   (i.e. roundf(speed * 10.0f))
static String     _rovrPrevEndurVal     = "";       // last-drawn endurance text
// Endurance sentinels. Up here with the state rather than beside _rovrEnduranceSec
// because the target strip reads them and the Arduino builder hoists function
// prototypes but NOT constants -- same trap as ReCorridor and ApsisTape.
static const int32_t ROVR_ENDUR_UNKNOWN  = -1;   // no usable rate yet
static const int32_t ROVR_ENDUR_CHARGING = -2;   // net gain (solar)
static String     _rovrPrevTgtTimeVal   = "";       // last-drawn T+Tgt text
static uint16_t   _rovrPrevTgtTimeFg    = 0xFFFF;
static uint16_t   _rovrPrevTgtTimeBg    = 0xFFFF;
static uint16_t   _rovrPrevEcFg         = 0xFFFF;   // last-drawn EC% fg color (for threshold change)
static uint16_t   _rovrPrevEcBg         = 0xFFFF;   // last-drawn EC% bg color
static int8_t     _rovrPrevBrake        = -1;       // -1=never drawn, 0=off, 1=on
static int8_t     _rovrPrevGear         = -1;
static int16_t    _rovrPrevSasMode      = -1;       // -1=never drawn, else stored value
static float      _rovrPrevPitch        = -9999.0f; // last-drawn pitch angle
static float      _rovrPrevRoll         = -9999.0f; // last-drawn roll angle
static int16_t    _rovrPrevPitchVal     = -9999;    // last-drawn integer pitch (for readout)
static int16_t    _rovrPrevRollVal      = -9999;    // last-drawn integer roll (for readout)
static uint16_t   _rovrPrevPitchColor   = 0;        // last-drawn numeric-value color
static uint16_t   _rovrPrevRollColor    = 0;        // (silhouettes always drawn in chrome colors)
static int32_t    _rovrPrevElev         = -99999;   // last-drawn integer elevation (m ASL)
static bool       _rovrPrevTgtDistAvail  = false;    // whether the target-distance label/value were drawn
static int32_t    _rovrPrevTgtDistVal    = -1;       // last-drawn integer target distance in metres

// ── Shared compass card ───────────────────────────────────────────────────────────────
// The rose (ring, ticks, labels, nose, bearing marker) moved to Compass.ino when the
// NAV screen was added, so the two navigation screens run one implementation rather
// than two hand-maintained copies — the same consolidation the reticle layer and the
// EADI tape already went through. Every radius below is ROVER's original value; only
// the code that consumes them is now shared.
static const CompassGeom ROVR_GEOM = {
  ROVR_CX, ROVR_CY,
  ROVR_R,
  ROVR_R_TICK_OUTER, ROVR_R_TICK_INNER, ROVR_R_MINOR_INNER,
  ROVR_R_LETTER, ROVR_R_NUMLABEL,
  ROVR_NOSE_R_TIP, ROVR_NOSE_R_BASE, ROVR_NOSE_HALF_W,
  ROVR_TGT_R_TIP,  ROVR_TGT_R_BASE,  ROVR_TGT_HALF_W
};

// ── Shortest-arc delta helper ─────────────────────────────────────────────────────────
static inline float _rovrHdgDelta(float a, float b) { return eadiHdgDelta(a, b); }

// ── Compass drawing ───────────────────────────────────────────────────────────────────

// Erase the compass bounding box before redrawing. fillRect is hardware-accelerated
// on the RA8876 so this is cheap. Bounds cover outer ring, tick marks, labels,
// nose triangle, and the heading readout box above the triangle.
static void _rovrEraseCompass(KCM_TFT &tft) {
    int16_t x0 = ROVR_CX - ROVR_R - 8;
    int16_t y0 = ROVR_HDG_BOX_Y - 4;               // reach above heading box
    int16_t x1 = ROVR_CX + ROVR_R + 8;
    int16_t y1 = ROVR_CY + ROVR_R + 8;
    tft.fillRect(x0, y0, x1 - x0, y1 - y0, TFT_BLACK);
}

// Compass card, nose and target marker — thin adapters onto the shared renderer in
// Compass.ino. The geometry, colours and erase strategy are unchanged; ROVR_GEOM
// carries this screen's original radii, and each screen keeps its own prev-drawn
// cache so the redraw gating stays independent. Equivalence with the previous
// hand-rolled versions was verified on the host: every draw call, at every heading
// and every marker bearing, is identical.
static inline void _rovrDrawTicks(KCM_TFT &tft, float headingDeg, bool erase) {
    compassDrawTicks(tft, ROVR_GEOM, headingDeg, erase);
}

static inline void _rovrDrawLabels(KCM_TFT &tft, float headingDeg, bool erase) {
    compassDrawLabels(tft, ROVR_GEOM, headingDeg, erase);
}

static inline void _rovrDrawNose(KCM_TFT &tft) {
    compassDrawNose(tft, ROVR_GEOM);
}

// Target bearing marker — violet, matching the target colour used on SCFT/ACFT.
static inline void _rovrDrawTargetAt(KCM_TFT &tft, float screenDeg, bool erase) {
    compassDrawMarker(tft, ROVR_GEOM, screenDeg, TFT_VIOLET, erase);
}


// Target triangle update — called every frame. Decides whether the target
// triangle needs to be erased, redrawn, or both. Independent of the main
// compass redraw because the target triangle sits in an annular band (R=100..
// 115) that doesn't overlap with the ticks/labels/ring, so it can update on
// its own cadence.
//
// Triggers:
//   - target availability toggled — erase old if was visible, draw new if now
//   - target screen-bearing changed ≥ ROVR_TGT_THRESH_DEG — erase old, draw new
static void _rovrUpdateTarget(KCM_TFT &tft) {
    if (!state.targetAvailable) {
        // Target is not available. If one was previously drawn, erase it.
        if (_rovrPrevTgtAvail) {
            _rovrDrawTargetAt(tft, _rovrPrevTgtScreenDeg, true);
            _rovrPrevTgtAvail = false;
        }
        return;
    }

    // Target IS available. Compute new screen bearing.
    float screenDeg = _rovrHdgDelta(state.tgtHeading, state.heading);

    if (!_rovrPrevTgtAvail) {
        // Target just appeared — draw fresh, no erase needed.
        _rovrDrawTargetAt(tft, screenDeg, false);
        _rovrPrevTgtAvail     = true;
        _rovrPrevTgtScreenDeg = screenDeg;
        return;
    }

    // Target was available and still is — redraw only if the screen position
    // changed meaningfully.
    float deltaScreenDeg = _rovrHdgDelta(screenDeg, _rovrPrevTgtScreenDeg);
    if (fabsf(deltaScreenDeg) < ROVR_TGT_THRESH_DEG) return;

    // Erase at the old screen position, draw at the new one.
    _rovrDrawTargetAt(tft, _rovrPrevTgtScreenDeg, true);
    _rovrDrawTargetAt(tft, screenDeg, false);
    _rovrPrevTgtScreenDeg = screenDeg;
}

// Target-distance readout — status strip along the bottom of the compass region.
// "DIST" label flush-left against the left column, formatted distance value flush-
// right against the right column. Both are visible only when a target is selected;
// when no target, both strips are erased to black.
//
// Uses formatAlt() from the shared library for auto-scaled units (m/km/Mm/Gm)
// and thousands separators. Value is rendered in TFT_VIOLET to match the target
// triangle and the convention used on SCFT/ACFT target markers.
static void _rovrUpdateTgtDist(KCM_TFT &tft) {
    if (!state.targetAvailable) {
        // Target is not available. Erase both pairs if they were drawn.
        if (_rovrPrevTgtDistAvail) {
            tft.fillRect(ROVR_TGTD_LBL_X, ROVR_TGTD_Y,
                         ROVR_TGTT_VAL_X + ROVR_TGTT_VAL_W - ROVR_TGTD_LBL_X,
                         ROVR_TGTD_H, TFT_BLACK);
            _rovrPrevTgtDistAvail = false;
            _rovrPrevTgtDistVal   = -1;
            _rovrPrevTgtTimeVal   = "";
        }
        return;
    }

    // Both labels are static, so they are drawn once per availability transition.
    if (!_rovrPrevTgtDistAvail) {
        textLeft(tft, ROVR_TGTD_FONT,
                 ROVR_TGTD_LBL_X, ROVR_TGTD_Y, ROVR_TGTD_LBL_W, ROVR_TGTD_H,
                 "DIST", KDC_LABEL_COLOR, TFT_BLACK);
        textLeft(tft, ROVR_TGTD_FONT,
                 ROVR_TGTT_LBL_X, ROVR_TGTD_Y, ROVR_TGTT_LBL_W, ROVR_TGTD_H,
                 "T+TGT", KDC_LABEL_COLOR, TFT_BLACK);
        _rovrPrevTgtDistAvail = true;
        _rovrPrevTgtDistVal   = -1;   // force both values to redraw below
        _rovrPrevTgtTimeVal   = "";
    }

    // ── Distance ────────────────────────────────────────────────────────────────────
    int32_t iDist = (int32_t)roundf(state.tgtDistance);
    if (iDist != _rovrPrevTgtDistVal) {
        // fillRect rather than text overdraw: textRight's x depends on string length, so
        // the old and new strings may not cover the same pixels.
        if (_rovrPrevTgtDistVal >= 0)
            tft.fillRect(ROVR_TGTD_VAL_X, ROVR_TGTD_Y,
                         ROVR_TGTD_VAL_W, ROVR_TGTD_H, TFT_BLACK);
        textRight(tft, ROVR_TGTD_FONT,
                  ROVR_TGTD_VAL_X, ROVR_TGTD_Y, ROVR_TGTD_VAL_W, ROVR_TGTD_H,
                  formatAlt((float)iDist), TFT_VIOLET, TFT_BLACK);
        _rovrPrevTgtDistVal = iDist;
    }

    // ── Time to target, coloured by whether the charge will actually get you there ───
    // The compass carries the bearing and the strip carries the distance, so direction
    // and range are covered; a time is the thing the picture cannot draw. Closure comes
    // from state.tgtVelocity, which SimpitHandler resolves onto the line of sight -- a
    // rover's heading rarely points at the target, and dividing by ground speed would
    // flatter the arrival every time.
    //
    // The COLOUR is the useful part, and it is about reachability rather than about the
    // ETA itself (an ETA has no natural tiers of its own). Red means the charge runs out
    // before you arrive. The 0.8 factor is because arriving at zero is not arriving.
    //
    // ONE-WAY. This says nothing about getting home again: the return route is unknown
    // and the rover may recharge in sunlight. Do not read a green T+Tgt as "I can get
    // back". A round-trip variant would be 2 x T+Tgt against Endur, if it is ever wanted.
    {
        const bool closing = (state.tgtVelocity < -0.5f);
        String val; uint16_t fg = TFT_DARK_GREY, bg = TFT_BLACK;
        if (!closing) {
            val = "---";
        } else {
            const int32_t eta = (int32_t)(state.tgtDistance / fabsf(state.tgtVelocity));
            val = formatTimeCompact((int64_t)eta);
            const int32_t endur = _rovrEnduranceSec();
            if (endur == ROVR_ENDUR_UNKNOWN || endur == ROVR_ENDUR_CHARGING) {
                fg = TFT_DARK_GREEN;                       // unbounded or unknown: no claim
            } else if (eta >= endur)          { fg = TFT_WHITE;  bg = TFT_RED; }
            else if (eta >= (endur * 4) / 5)  { fg = TFT_YELLOW;               }
            else                              { fg = TFT_DARK_GREEN;           }
        }
        if (val != _rovrPrevTgtTimeVal || fg != _rovrPrevTgtTimeFg || bg != _rovrPrevTgtTimeBg) {
            tft.fillRect(ROVR_TGTT_VAL_X, ROVR_TGTD_Y,
                         ROVR_TGTT_VAL_W, ROVR_TGTD_H, TFT_BLACK);
            textRight(tft, ROVR_TGTD_FONT,
                      ROVR_TGTT_VAL_X, ROVR_TGTD_Y, ROVR_TGTT_VAL_W, ROVR_TGTD_H,
                      val, fg, bg);
            _rovrPrevTgtTimeVal = val;
            _rovrPrevTgtTimeFg  = fg;
            _rovrPrevTgtTimeBg  = bg;
        }
    }
}

// Rover silhouette (top-down) at compass centre. Stationary — the rover always
// points "up" (12 o'clock) since it represents the vessel's own frame, and the
// ring rotates around it to show world-frame cardinal directions.
//
// Drawing order: chassis first, then wheels on top (wheels overhang the chassis
// sides slightly), then nose notch at the front.
static void _rovrDrawIcon(KCM_TFT &tft) {
    // Chassis — centred rectangle
    int16_t chX = ROVR_CX - ROVR_ICON_CHASS_W / 2;
    int16_t chY = ROVR_CY - ROVR_ICON_CHASS_H / 2;
    tft.fillRect(chX, chY, ROVR_ICON_CHASS_W, ROVR_ICON_CHASS_H, TFT_GREY);
    tft.drawRect(chX, chY, ROVR_ICON_CHASS_W, ROVR_ICON_CHASS_H, TFT_LIGHT_GREY);

    // Wheels — 4 rectangles at corners, extending ROVR_ICON_WHEEL_GAP beyond chassis
    // sides. Each wheel is inset vertically from the chassis top/bottom.
    // Wheel outer edges at chX - WHEEL_GAP and chX + CHASS_W + WHEEL_GAP - WHEEL_W.
    int16_t wLX = chX - ROVR_ICON_WHEEL_GAP;
    int16_t wRX = chX + ROVR_ICON_CHASS_W + ROVR_ICON_WHEEL_GAP - ROVR_ICON_WHEEL_W;
    int16_t wTY = chY + ROVR_ICON_WHEEL_INSET;
    int16_t wBY = chY + ROVR_ICON_CHASS_H - ROVR_ICON_WHEEL_INSET - ROVR_ICON_WHEEL_H;

    // Front-left
    tft.fillRect(wLX, wTY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_DARK_GREY);
    tft.drawRect(wLX, wTY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_GREY);
    // Front-right
    tft.fillRect(wRX, wTY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_DARK_GREY);
    tft.drawRect(wRX, wTY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_GREY);
    // Rear-left
    tft.fillRect(wLX, wBY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_DARK_GREY);
    tft.drawRect(wLX, wBY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_GREY);
    // Rear-right
    tft.fillRect(wRX, wBY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_DARK_GREY);
    tft.drawRect(wRX, wBY, ROVR_ICON_WHEEL_W, ROVR_ICON_WHEEL_H, TFT_GREY);

    // Nose notch — small triangle at the front-centre, pointing forward (up).
    // Base sits on chassis top edge; tip extends ROVR_ICON_NOSE_H above it.
    int16_t noseTipX = ROVR_CX;
    int16_t noseTipY = chY - ROVR_ICON_NOSE_H;
    int16_t noseBLX  = ROVR_CX - ROVR_ICON_NOSE_W / 2;
    int16_t noseBLY  = chY;
    int16_t noseBRX  = ROVR_CX + ROVR_ICON_NOSE_W / 2;
    int16_t noseBRY  = chY;
    tft.fillTriangle(noseTipX, noseTipY, noseBLX, noseBLY, noseBRX, noseBRY, TFT_LIGHT_GREY);
}

// FWD / REV drive-state blocks — two button-style boxes in the top corners of the
// compass area, flanking the heading readout. Binary on/off, one of three states:
//   FWD (throttle > deadband)       — FWD block dark-green + white text, REV muted
//   REV (throttle < -deadband)      — REV block yellow + dark-grey text, FWD muted
//   NEUTRAL (|throttle| < deadband) — both blocks muted (off-black fill)
//
// Both blocks are redrawn together on every state transition (a change in one
// implies the other returns to muted). drawButton fills, borders, and centre-
// labels each block in a single call. State code: +1 forward, 0 neutral, -1 rev.
static void _rovrUpdateThrottle(KCM_TFT &tft) {
    float wt = state.wheelThrottle;
    int16_t newState;
    if      (wt >  ROVR_THR_THRESH) newState = +1;
    else if (wt < -ROVR_THR_THRESH) newState = -1;
    else                            newState =  0;

    if (newState == _rovrPrevThrFill) return;

    ButtonLabel fwd = (newState == +1)
        ? ButtonLabel{ "FWD", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
        : ButtonLabel{ "FWD", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
    drawButton(tft, ROVR_FWD_BLK_X, ROVR_THRBLK_Y,
               ROVR_THRBLK_W, ROVR_THRBLK_H, fwd, &Roboto_Black_36, false);

    ButtonLabel rev = (newState == -1)
        ? ButtonLabel{ "REV", TFT_DARK_GREY, TFT_DARK_GREY, TFT_YELLOW,    TFT_YELLOW,    TFT_GREY, TFT_GREY }
        : ButtonLabel{ "REV", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
    drawButton(tft, ROVR_REV_BLK_X, ROVR_THRBLK_Y,
               ROVR_THRBLK_W, ROVR_THRBLK_H, rev, &Roboto_Black_36, false);

    _rovrPrevThrFill = newState;
}

// Surface velocity readout — "V.SRF" label over signed speed (m/s) with 1 decimal.
// Label drawn once in chrome. Value updated via cached dirty check. Sign derived
// from comparing state.srfVelHeading to state.heading (>90° off-nose = reversing).
//
// The label and value are centered within the V.Srf block (y=ROVR_VSRF_Y, height
// ROVR_VSRF_H). Both strip rects are exactly `ROVR_LBL_H` and `ROVR_VAL_H` tall.
// (value-erase now uses the shared eraseCenteredValue() from KerbalDisplayCommon)

static inline int16_t _rovrVSrfLabelY() {
    int16_t totalContent = ROVR_LBL_H + ROVR_LBL_VAL_GAP + ROVR_VAL_H;
    return ROVR_VSRF_Y + (ROVR_VSRF_H - totalContent) / 2;
}
static inline int16_t _rovrVSrfValueY() {
    return _rovrVSrfLabelY() + ROVR_LBL_H + ROVR_LBL_VAL_GAP;
}

// Draw the stationary V.Srf chrome: bounding box border and label. Called once
// in chromeScreen_ROVR. The box border is drawn in light grey (matches the
// heading readout box on the compass).
static void _rovrDrawVSrfChrome(KCM_TFT &tft) {
    // Bounding box around the full V.Srf block
    tft.drawRect(ROVR_LCOL_X, ROVR_VSRF_Y,
                 ROVR_LCOL_W, ROVR_VSRF_H,
                 TFT_GREY);

    // Label centered in its strip
    textCenter(tft, &Roboto_Black_24,
               ROVR_LCOL_X, _rovrVSrfLabelY(),
               ROVR_LCOL_W, ROVR_LBL_H,
               "V.SRF", KDC_LABEL_COLOR, TFT_BLACK);
}

static void _rovrUpdateVSrf(KCM_TFT &tft) {
    // Magnitude (may be signed from demo mode; treat as unsigned magnitude)
    float mag = fabsf(state.surfaceVel);
    float speed;
    if (mag < 0.05f) {
        speed = 0.0f;   // below 1-decimal visibility
    } else {
        float d = _rovrHdgDelta(state.srfVelHeading, state.heading);
        speed = (fabsf(d) > 90.0f) ? -mag : mag;
    }

    // Clamp to ±99.9 m/s so the displayed value always fits the column width
    // ("+99.9 m/s" is the widest renderable string).
    if (speed >  99.9f) speed =  99.9f;
    if (speed < -99.9f) speed = -99.9f;

    // Cache by tenths (integer rounding of speed * 10). This triggers redraw
    // whenever the displayed 1-decimal value changes.
    int16_t iSpeed = (int16_t)roundf(speed * 10.0f);
    if (iSpeed == _rovrPrevVSrf) return;

    int16_t valueY = _rovrVSrfValueY();

    // Erase previous value (black-on-black)
    if (_rovrPrevVSrf > -9000) {
        char oldBuf[16];
        snprintf(oldBuf, sizeof(oldBuf), "%+.1f m/s", (float)_rovrPrevVSrf / 10.0f);
        eraseCenteredValue(tft, &Roboto_Black_36,
                                ROVR_LCOL_X, valueY, ROVR_LCOL_W, ROVR_VAL_H,
                                oldBuf, TFT_BLACK);
    }

    // Color: green forward, yellow reverse, grey neutral
    uint16_t fg;
    if      (iSpeed >  0) fg = TFT_DARK_GREEN;
    else if (iSpeed <  0) fg = TFT_YELLOW;
    else                   fg = TFT_DARK_GREY;

    char buf[16];
    snprintf(buf, sizeof(buf), "%+.1f m/s", speed);
    textCenter(tft, &Roboto_Black_36,
               ROVR_LCOL_X, valueY,
               ROVR_LCOL_W, ROVR_VAL_H,
               buf, fg, TFT_BLACK);

    _rovrPrevVSrf = iSpeed;
}

// ── Endurance readout ─────────────────────────────────────────────────────────────────
// This block used to be EC%, and a percentage was the wrong number to put here. No EV
// instrument cluster shows state of charge alone: SOC is always paired with estimated
// range, because SOC answers "how full" and range answers the question actually being
// asked, which is "can I get back". On a Mun rover 20% tells you nothing about whether
// that is four minutes or forty. The level itself is not lost -- the Resource Display
// carries EC%, and the Annunciator owns the low-charge alarm on the same thresholds.
//
// This is the rover's version of the change POWERED DESCENT already made, swapping a
// derivable velocity for Stg.Brn: convert a level into the time it buys you, because
// time is what the phase turns on.
//
// COLOURED BY TIME, NOT BY PERCENTAGE. Colouring from the EC_PCT_* tiers would put the
// problem straight back: 19% would show yellow beside "2h 14m", and 40% under a heavy
// load would show GREEN beside "4m". This cell is a different quantity from EC% and
// properly gets its own scale -- the same relationship Stg.Brn (seconds) has to
// dV.Stg (m/s).
//
// DERIVED, so the window is the whole design. electricChargePercent is computed from
// available/total and crawls on a large battery, so the rate comes from a ring buffer
// spanning tens of seconds rather than frame to frame. The ring is fed from loop() on
// every screen (rovrEnduranceService) and reset on a vessel switch, not on screen
// entry: a window that restarted with the chrome read "---" for the first seconds of
// every visit, and one that survived a vessel switch turned the step in charge into a
// spurious rate for the next 48 s. Three cases have to be designed rather than
// discovered on the bench:
//   - solar panels can make the net rate POSITIVE. That is "CHG", not a negative time.
//   - below a floor the figure is not decision-relevant (beyond ~10 h), so it reads
//     "---" rather than a fictitious precision.
//   - parked with nothing drawing, the rate is noise around zero, which the floor
//     catches for the same reason.
static const uint8_t ROVR_ENDUR_N   = 32;      // ring samples
static const uint16_t ROVR_ENDUR_MS = 1500;    // ~1.5 s apart -> ~48 s window
static const float   ROVR_ENDUR_FLOOR_PCT_S = 0.002f;  // ~14 h to empty; below this, "---"

static float    _rovrEcRing[ROVR_ENDUR_N];
static uint32_t _rovrEcRingMs[ROVR_ENDUR_N];
static uint8_t  _rovrEcRingHead  = 0;
static uint8_t  _rovrEcRingCount = 0;
static uint32_t _rovrEcLastMs    = 0;

void rovrEnduranceReset() {
    _rovrEcRingHead = 0; _rovrEcRingCount = 0; _rovrEcLastMs = 0;
}

// Net discharge rate in percent per second, POSITIVE while draining. Returns false until
// the window holds enough spread to mean anything.
static bool _rovrDischargeRate(float &pctPerSec) {
    if (_rovrEcRingCount < 4) return false;
    const uint8_t newest = (uint8_t)((_rovrEcRingHead + ROVR_ENDUR_N - 1) % ROVR_ENDUR_N);
    const uint8_t oldest = (uint8_t)((_rovrEcRingHead + ROVR_ENDUR_N - _rovrEcRingCount) % ROVR_ENDUR_N);
    const float dt = (float)(uint32_t)(_rovrEcRingMs[newest] - _rovrEcRingMs[oldest]) / 1000.0f;
    if (dt < 5.0f) return false;
    pctPerSec = (_rovrEcRing[oldest] - _rovrEcRing[newest]) / dt;
    return true;
}

static void _rovrEnduranceSample(float ecPct, uint32_t now) {
    if (_rovrEcRingCount != 0 && (uint32_t)(now - _rovrEcLastMs) < ROVR_ENDUR_MS) return;
    _rovrEcRing[_rovrEcRingHead]   = ecPct;
    _rovrEcRingMs[_rovrEcRingHead] = now;
    _rovrEcRingHead = (uint8_t)((_rovrEcRingHead + 1) % ROVR_ENDUR_N);
    if (_rovrEcRingCount < ROVR_ENDUR_N) _rovrEcRingCount++;
    _rovrEcLastMs = now;
}

// Called from loop() every frame; samples at ROVR_ENDUR_MS.
void rovrEnduranceService() {
    _rovrEnduranceSample(state.electricChargePercent, millis());
}

static int32_t _rovrEnduranceSec() {
    float rate;
    if (!_rovrDischargeRate(rate)) return ROVR_ENDUR_UNKNOWN;
    if (rate <= -ROVR_ENDUR_FLOOR_PCT_S) return ROVR_ENDUR_CHARGING;   // net gain
    if (rate <   ROVR_ENDUR_FLOOR_PCT_S) return ROVR_ENDUR_UNKNOWN;    // flat / noise
    float ec = state.electricChargePercent;
    if (ec < 0.0f) ec = 0.0f; else if (ec > 100.0f) ec = 100.0f;
    return (int32_t)(ec / rate);
}

static inline int16_t _rovrEcLabelY() {
    int16_t totalContent = ROVR_LBL_H + ROVR_LBL_VAL_GAP + ROVR_VAL_H;
    return ROVR_EC_Y + (ROVR_EC_H - totalContent) / 2;
}
static inline int16_t _rovrEcValueY() {
    return _rovrEcLabelY() + ROVR_LBL_H + ROVR_LBL_VAL_GAP;
}

static void _rovrDrawEcChrome(KCM_TFT &tft) {
    tft.drawRect(ROVR_LCOL_X, ROVR_EC_Y,
                 ROVR_LCOL_W, ROVR_EC_H,
                 TFT_GREY);

    textCenter(tft, &Roboto_Black_24,
               ROVR_LCOL_X, _rovrEcLabelY(),
               ROVR_LCOL_W, ROVR_LBL_H,
               "ENDUR", KDC_LABEL_COLOR, TFT_BLACK);
}

static void _rovrUpdateEc(KCM_TFT &tft) {
    const int32_t sec = _rovrEnduranceSec();

    uint16_t fg, bg = TFT_BLACK;
    String val;
    if (sec == ROVR_ENDUR_CHARGING)     { fg = TFT_DARK_GREEN; val = "CHG"; }
    else if (sec == ROVR_ENDUR_UNKNOWN) { fg = TFT_DARK_GREY;  val = "---"; }
    else {
        val = formatTimeCompact((int64_t)sec);
        if      (sec < ROVER_ENDUR_ALARM_S) { fg = TFT_WHITE;      bg = TFT_RED; }
        else if (sec < ROVER_ENDUR_WARN_S)  { fg = TFT_YELLOW;                   }
        else                                { fg = TFT_DARK_GREEN;               }
    }

    if (val == _rovrPrevEndurVal && fg == _rovrPrevEcFg && bg == _rovrPrevEcBg) return;

    const int16_t valueY = _rovrEcValueY();
    if (_rovrPrevEndurVal.length() > 0) {
        eraseCenteredValue(tft, &Roboto_Black_36,
                           ROVR_LCOL_X, valueY, ROVR_LCOL_W, ROVR_VAL_H,
                           _rovrPrevEndurVal.c_str(), _rovrPrevEcBg);
    }
    textCenter(tft, &Roboto_Black_36,
               ROVR_LCOL_X, valueY, ROVR_LCOL_W, ROVR_VAL_H,
               val.c_str(), fg, bg);

    _rovrPrevEndurVal = val;
    _rovrPrevEcFg     = fg;
    _rovrPrevEcBg     = bg;
}

// ── BRAKE / GEAR / SAS buttons ────────────────────────────────────────────────────────
// Button-style indicators using drawButton(). Each button fills its entire block
// slot — no padding — so adjacent buttons share borders for a tight stack.
// Uses Roboto_Black_24 to match the compass labels. SAS mode labels use the
// abbreviated short-form convention shared with SCFT and ACFT (STAB / PRO / RETR /
// NRM / ANRM / RAD+ / RAD- / TGT / ATGT / MNVR / SAS).

static void _rovrUpdateBrake(KCM_TFT &tft) {
    int8_t newState = state.brakes_on ? 1 : 0;
    if (newState == _rovrPrevBrake) return;

    ButtonLabel btn = state.brakes_on
        ? ButtonLabel{ "BRAKES", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
        : ButtonLabel{ "BRAKES", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
    drawButton(tft,
               ROVR_LCOL_X, ROVR_BRAKE_Y,
               ROVR_LCOL_W, ROVR_BRAKE_H,
               btn, &Roboto_Black_28, false);

    _rovrPrevBrake = newState;
}

static void _rovrUpdateGear(KCM_TFT &tft) {
    int8_t newState = state.gear_on ? 1 : 0;
    if (newState == _rovrPrevGear) return;

    // Rover wheels are deployed (gear_on) for normal driving — so "GEAR DOWN"
    // is the safe/active state (green bg), "GEAR UP" is unusual (muted).
    ButtonLabel btn = state.gear_on
        ? ButtonLabel{ "GEAR", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
        : ButtonLabel{ "GEAR", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
    drawButton(tft,
               ROVR_LCOL_X, ROVR_GEAR_Y,
               ROVR_LCOL_W, ROVR_GEAR_H,
               btn, &Roboto_Black_28, false);

    _rovrPrevGear = newState;
}

// SAS colors follow the navball palette (matches SCFT/ACFT usage):
//   OFF        — dark grey on off-black (muted, expected state for rover driving)
//   STAB (0)   — white on dark green
//   PRO (1)    — dark grey on neon green
//   RETR (2)   — dark grey on neon green
//   NRM (3)    — white on magenta
//   ANRM (4)   — white on magenta
//   RAD+ (5)   — dark grey on sky
//   RAD- (6)   — dark grey on sky
//   TGT (7)    — white on violet
//   ATGT (8)   — white on violet
//   MNVR (9)   — white on blue
static void _rovrUpdateSas(KCM_TFT &tft) {
    int16_t newMode = (int16_t)state.sasMode;
    if (newMode == _rovrPrevSasMode) return;

    const char *v; uint16_t fg, bg;
    sasNavballLabel(state.sasMode, v, fg, bg);

    ButtonLabel btn = { v, fg, fg, bg, bg, TFT_GREY, TFT_GREY };
    drawButton(tft,
               ROVR_LCOL_X, ROVR_SAS_Y,
               ROVR_LCOL_W, ROVR_SAS_H,
               btn, &Roboto_Black_28, false);

    _rovrPrevSasMode = newMode;
}

// ── Elevation readout ─────────────────────────────────────────────────────────────────
// "ALT.TRN" label over integer surface-altitude value in meters. Named for the Alt
// family (Alt.SL, Alt.Rdr) it belongs to, not "ELEV", which sat one letter away from
// the "ELV" that DOCKING, TARGET and MANEUVER use for an elevation ANGLE -- a different
// quantity in different units. Terrain elevation is
// computed as (altitude_ASL - radarAlt_AGL), giving the altitude of the terrain
// surface below the vessel — i.e. how high up the current terrain is above
// sea level. Same block style as V.Srf on the left side.
//
// Clamped to ≥ 0 (negative values would indicate telemetry anomalies, not real
// terrain below sea level, and KSP bodies don't have meaningful negative
// elevation in the rover-driving domain).
static inline int16_t _rovrElevLabelY() {
    int16_t totalContent = ROVR_LBL_H + ROVR_LBL_VAL_GAP + ROVR_VAL_H;
    return ROVR_ELEV_Y + (ROVR_ELEV_H - totalContent) / 2;
}
static inline int16_t _rovrElevValueY() {
    return _rovrElevLabelY() + ROVR_LBL_H + ROVR_LBL_VAL_GAP;
}

static void _rovrDrawElevChrome(KCM_TFT &tft) {
    tft.drawRect(ROVR_RCOL_X, ROVR_ELEV_Y,
                 ROVR_RCOL_W, ROVR_ELEV_H,
                 TFT_GREY);
    textCenter(tft, &Roboto_Black_24,
               ROVR_RCOL_X, _rovrElevLabelY(),
               ROVR_RCOL_W, ROVR_LBL_H,
               "ALT.TRN", KDC_LABEL_COLOR, TFT_BLACK);
}

static void _rovrUpdateElev(KCM_TFT &tft) {
    // Elevation = surface altitude above sea level = altitude (ASL) - radarAlt (AGL).
    // formatAlt() handles the sign and auto-scales units (m/km/Mm/Gm) for large values.
    float elev = state.altitude - state.radarAlt;
    int32_t iElev = (int32_t)roundf(elev);

    if (iElev == _rovrPrevElev) return;

    int16_t valueY = _rovrElevValueY();

    // Erase previous value by regenerating its formatted string from the cached int
    // and drawing it black-on-black.
    if (_rovrPrevElev > -90000) {
        String oldStr = formatAlt((float)_rovrPrevElev);
        eraseCenteredValue(tft, &Roboto_Black_36,
                                ROVR_RCOL_X, valueY, ROVR_RCOL_W, ROVR_VAL_H,
                                oldStr.c_str(), TFT_BLACK);
    }

    String newStr = formatAlt((float)iElev);
    textCenter(tft, &Roboto_Black_36,
               ROVR_RCOL_X, valueY,
               ROVR_RCOL_W, ROVR_VAL_H,
               newStr, TFT_DARK_GREEN, TFT_BLACK);

    _rovrPrevElev = iElev;
}


// ── Pitch / Roll tilt indicators ──────────────────────────────────────────────────────
//
// Two independent rover silhouettes that tilt with vessel attitude:
//   Pitch — side-view profile (wide body, round wheels below) rotated by -pitch.
//           Conventionally: nose up = right side of silhouette up on screen.
//   Roll  — rear-view profile (narrow tall body, rectangular tires on the sides)
//           rotated by +roll. Conventionally: bank right = right side down.
//
// The silhouettes themselves are always drawn in chrome colors (TFT_GREY body,
// TFT_DARK_GREY wheels/tires). Threshold state (good/warn/alarm) shows in the
// numeric value color below the silhouette:
//   normal  → TFT_DARK_GREEN
//   warn    → TFT_YELLOW
//   alarm   → TFT_RED
// This keeps the silhouette visually stable under all conditions while the
// text carries the warning semantics.


// Pitch silhouette — side-view rover profile (wide body, round wheels below).
// Colors match the compass-center rover icon: TFT_GREY body with
// TFT_LIGHT_GREY outline, TFT_DARK_GREY wheels with TFT_GREY outline.
// Sign convention: positive angle rotates silhouette counter-clockwise on
// screen (y-down coords: CCW = right-side-up). Caller passes -pitch for the
// conventional "nose up = right side up" orientation.
static void _rovrDrawPitchSilhouette(KCM_TFT &tft, int16_t cx, int16_t cy,
                                     float angleDeg) {
    float a = angleDeg * (float)DEG_TO_RAD;
    float ca = cosf(a);
    float sa = sinf(a);

    auto rot = [&](float px, float py, int16_t &outX, int16_t &outY) {
        float rx = px * ca - py * sa;
        float ry = px * sa + py * ca;
        outX = cx + (int16_t)roundf(rx);
        outY = cy + (int16_t)roundf(ry);
    };

    // Wheels first (drawn below body so body draws on top near overlap)
    int16_t wL_X, wL_Y, wR_X, wR_Y;
    rot(-(float)ROVR_SIL_WHEEL_DX, (float)ROVR_SIL_WHEEL_DY, wL_X, wL_Y);
    rot( (float)ROVR_SIL_WHEEL_DX, (float)ROVR_SIL_WHEEL_DY, wR_X, wR_Y);
    tft.fillCircle(wL_X, wL_Y, ROVR_SIL_WHEEL_R, TFT_DARK_GREY);
    tft.drawCircle(wL_X, wL_Y, ROVR_SIL_WHEEL_R, TFT_GREY);
    tft.fillCircle(wR_X, wR_Y, ROVR_SIL_WHEEL_R, TFT_DARK_GREY);
    tft.drawCircle(wR_X, wR_Y, ROVR_SIL_WHEEL_R, TFT_GREY);

    // Body rectangle — drawn as two filled triangles (fill), then edge lines (outline)
    int16_t halfW = ROVR_SIL_BODY_W / 2;
    int16_t halfH = ROVR_SIL_BODY_H / 2;
    int16_t tlX, tlY, trX, trY, brX, brY, blX, blY;
    rot(-halfW, -halfH, tlX, tlY);
    rot( halfW, -halfH, trX, trY);
    rot( halfW,  halfH, brX, brY);
    rot(-halfW,  halfH, blX, blY);
    tft.fillTriangle(tlX, tlY, trX, trY, brX, brY, TFT_GREY);
    tft.fillTriangle(tlX, tlY, brX, brY, blX, blY, TFT_GREY);
    // Outline the body (matching compass icon chassis outline)
    tft.drawLine(tlX, tlY, trX, trY, TFT_LIGHT_GREY);
    tft.drawLine(trX, trY, brX, brY, TFT_LIGHT_GREY);
    tft.drawLine(brX, brY, blX, blY, TFT_LIGHT_GREY);
    tft.drawLine(blX, blY, tlX, tlY, TFT_LIGHT_GREY);
}

// Roll silhouette — rear-view rover profile: body matching pitch body height,
// narrower width, with rectangular tires on the sides (visible tread face).
// Tires are centered on the body's bottom edge so about half of each tire
// extends below the body.
//
// Colors match the compass-center rover icon: TFT_GREY body with TFT_LIGHT_GREY
// outline, TFT_DARK_GREY tires with TFT_GREY outline.
//
// Unrotated layout (origin at silhouette centre):
//      ┌──────────┐    body: W=50, H=28 (same H as pitch body)
//      │          │
//    ┌─┤          ├─┐  tires: W=10, H=20, centered on body bottom edge
//    │ │          │ │
//    └─┴──────────┴─┘
//
// Sign convention: positive angle = bank right = right side goes down on screen.
// Caller passes +roll directly.
static void _rovrDrawRollSilhouette(KCM_TFT &tft, int16_t cx, int16_t cy,
                                    float angleDeg) {
    float a = angleDeg * (float)DEG_TO_RAD;
    float ca = cosf(a);
    float sa = sinf(a);

    auto rot = [&](float px, float py, int16_t &outX, int16_t &outY) {
        float rx = px * ca - py * sa;
        float ry = px * sa + py * ca;
        outX = cx + (int16_t)roundf(rx);
        outY = cy + (int16_t)roundf(ry);
    };

    int16_t halfBW = ROVR_REAR_BODY_W / 2;
    int16_t halfBH = ROVR_REAR_BODY_H / 2;
    int16_t halfTH = ROVR_REAR_TIRE_H / 2;

    // Tires first (drawn behind body edges where they overlap).
    // Left tire: x range [-halfBW - TIRE_W, -halfBW], y centered on body bottom
    // so y range is [halfBH - halfTH, halfBH + halfTH].
    auto drawTire = [&](float xL, float xR) {
        float yT = (float)(halfBH - halfTH);
        float yB = (float)(halfBH + halfTH);
        int16_t tlX, tlY, trX, trY, brX, brY, blX, blY;
        rot(xL, yT, tlX, tlY);
        rot(xR, yT, trX, trY);
        rot(xR, yB, brX, brY);
        rot(xL, yB, blX, blY);
        tft.fillTriangle(tlX, tlY, trX, trY, brX, brY, TFT_DARK_GREY);
        tft.fillTriangle(tlX, tlY, brX, brY, blX, blY, TFT_DARK_GREY);
        tft.drawLine(tlX, tlY, trX, trY, TFT_GREY);
        tft.drawLine(trX, trY, brX, brY, TFT_GREY);
        tft.drawLine(brX, brY, blX, blY, TFT_GREY);
        tft.drawLine(blX, blY, tlX, tlY, TFT_GREY);
    };
    drawTire((float)(-halfBW - ROVR_REAR_TIRE_W), (float)(-halfBW));
    drawTire((float)halfBW, (float)(halfBW + ROVR_REAR_TIRE_W));

    // Body rectangle on top
    int16_t btlX, btlY, btrX, btrY, bbrX, bbrY, bblX, bblY;
    rot(-halfBW, -halfBH, btlX, btlY);
    rot( halfBW, -halfBH, btrX, btrY);
    rot( halfBW,  halfBH, bbrX, bbrY);
    rot(-halfBW,  halfBH, bblX, bblY);
    tft.fillTriangle(btlX, btlY, btrX, btrY, bbrX, bbrY, TFT_GREY);
    tft.fillTriangle(btlX, btlY, bbrX, bbrY, bblX, bblY, TFT_GREY);
    tft.drawLine(btlX, btlY, btrX, btrY, TFT_LIGHT_GREY);
    tft.drawLine(btrX, btrY, bbrX, bbrY, TFT_LIGHT_GREY);
    tft.drawLine(bbrX, bbrY, bblX, bblY, TFT_LIGHT_GREY);
    tft.drawLine(bblX, bblY, btlX, btlY, TFT_LIGHT_GREY);
}

// Erase a previously-drawn silhouette by fillRect over a conservative bounding
// square. The pitch and roll silhouettes have different extents, but using the
// larger of the two guarantees coverage for either.
static void _rovrEraseSilhouette(KCM_TFT &tft, int16_t cx, int16_t cy) {
    // Pitch silhouette extent: wheel extreme at sqrt(WHEEL_DX² + (WHEEL_DY+WHEEL_R)²)
    float pHalfW  = (float)ROVR_SIL_BODY_W / 2.0f;
    float pHalfH  = (float)ROVR_SIL_BODY_H / 2.0f;
    float pBodyR  = sqrtf(pHalfW*pHalfW + pHalfH*pHalfH);
    float pWheelR = sqrtf((float)(ROVR_SIL_WHEEL_DX*ROVR_SIL_WHEEL_DX) +
                          (float)((ROVR_SIL_WHEEL_DY+ROVR_SIL_WHEEL_R) *
                                  (ROVR_SIL_WHEEL_DY+ROVR_SIL_WHEEL_R)));
    float pitchR = (pBodyR > pWheelR) ? pBodyR : pWheelR;

    // Roll silhouette extent: tire outer-bottom corner is farthest point.
    // Tire now centered on body bottom edge, so bottom extends to halfBH + halfTH.
    float rHalfOuterX = (float)(ROVR_REAR_BODY_W/2 + ROVR_REAR_TIRE_W);
    float rHalfOuterY = (float)(ROVR_REAR_BODY_H/2 + ROVR_REAR_TIRE_H/2);
    float rollR = sqrtf(rHalfOuterX*rHalfOuterX + rHalfOuterY*rHalfOuterY);

    float maxR = (pitchR > rollR) ? pitchR : rollR;
    int16_t R = (int16_t)ceilf(maxR + 2.0f);
    tft.fillRect(cx - R, cy - R, 2 * R, 2 * R, TFT_BLACK);
}

// Choose numeric-value color based on angle magnitude and threshold config.
//   below warn  → dark green (good)
//   warn..alarm → yellow
//   >= alarm    → red
static uint16_t _rovrTiltValueColor(float angleDeg, float warnDeg, float alarmDeg) {
    float a = fabsf(angleDeg);
    if      (a >= alarmDeg) return TFT_RED;
    else if (a >= warnDeg)  return TFT_YELLOW;
    else                     return TFT_DARK_GREEN;
}

// Silhouette layout within each tilt box:
//   top_pad(4) + label(32) + gap(2) + silhouette_area + value(48) + bot_pad(4) = box_H
// Silhouette area height is (box_H - 90); silhouette centre is in the middle of that.
static const int16_t ROVR_PITCH_SIL_AREA_TOP = ROVR_PITCH_Y + ROVR_TILT_TOP_PAD +
                                               ROVR_TILT_LBL_H + ROVR_TILT_GAP;
static const int16_t ROVR_PITCH_SIL_AREA_H   = ROVR_PITCH_H - 2 * ROVR_TILT_TOP_PAD -
                                               ROVR_TILT_LBL_H - ROVR_TILT_GAP -
                                               ROVR_TILT_VAL_H;
static const int16_t ROVR_PITCH_SIL_CY = ROVR_PITCH_SIL_AREA_TOP + ROVR_PITCH_SIL_AREA_H / 2;
static const int16_t ROVR_PITCH_SIL_CX = ROVR_RCOL_X + ROVR_RCOL_W / 2;
static const int16_t ROVR_PITCH_VAL_Y  = ROVR_PITCH_Y + ROVR_PITCH_H -
                                         ROVR_TILT_TOP_PAD - ROVR_TILT_VAL_H;

static const int16_t ROVR_ROLL_SIL_AREA_TOP  = ROVR_ROLL_Y + ROVR_TILT_TOP_PAD +
                                               ROVR_TILT_LBL_H + ROVR_TILT_GAP;
static const int16_t ROVR_ROLL_SIL_AREA_H    = ROVR_ROLL_H - 2 * ROVR_TILT_TOP_PAD -
                                               ROVR_TILT_LBL_H - ROVR_TILT_GAP -
                                               ROVR_TILT_VAL_H;
static const int16_t ROVR_ROLL_SIL_CY  = ROVR_ROLL_SIL_AREA_TOP + ROVR_ROLL_SIL_AREA_H / 2;
static const int16_t ROVR_ROLL_SIL_CX  = ROVR_RCOL_X + ROVR_RCOL_W / 2;
static const int16_t ROVR_ROLL_VAL_Y   = ROVR_ROLL_Y + ROVR_ROLL_H -
                                         ROVR_TILT_TOP_PAD - ROVR_TILT_VAL_H;

// Horizontal reference line dimensions — short ticks on left and right of the
// silhouette at its vertical centre, providing a visual "true horizontal"
// reference to compare the tilted silhouette against.
static const int16_t ROVR_TILT_REF_MARGIN = 4;    // inset from box inner edge
static const int16_t ROVR_TILT_REF_LEN    = 20;   // length of each reference line

static void _rovrDrawPitchChrome(KCM_TFT &tft) {
    tft.drawRect(ROVR_RCOL_X, ROVR_PITCH_Y,
                 ROVR_RCOL_W, ROVR_PITCH_H,
                 TFT_GREY);
    textCenter(tft, &Roboto_Black_24,
               ROVR_RCOL_X, ROVR_PITCH_Y + ROVR_TILT_TOP_PAD,
               ROVR_RCOL_W, ROVR_TILT_LBL_H,
               "PITCH", KDC_LABEL_COLOR, TFT_BLACK);

    // Horizontal reference lines at silhouette centre Y, inside the box edges
    int16_t refY  = ROVR_PITCH_SIL_CY;
    int16_t lxL   = ROVR_RCOL_X + ROVR_TILT_REF_MARGIN;
    int16_t lxR   = lxL + ROVR_TILT_REF_LEN - 1;
    int16_t rxR   = ROVR_RCOL_X + ROVR_RCOL_W - 1 - ROVR_TILT_REF_MARGIN;
    int16_t rxL   = rxR - ROVR_TILT_REF_LEN + 1;
    tft.drawLine(lxL, refY, lxR, refY, TFT_LIGHT_GREY);
    tft.drawLine(rxL, refY, rxR, refY, TFT_LIGHT_GREY);
}

static void _rovrDrawRollChrome(KCM_TFT &tft) {
    tft.drawRect(ROVR_RCOL_X, ROVR_ROLL_Y,
                 ROVR_RCOL_W, ROVR_ROLL_H,
                 TFT_GREY);
    textCenter(tft, &Roboto_Black_24,
               ROVR_RCOL_X, ROVR_ROLL_Y + ROVR_TILT_TOP_PAD,
               ROVR_RCOL_W, ROVR_TILT_LBL_H,
               "ROLL", KDC_LABEL_COLOR, TFT_BLACK);

    int16_t refY  = ROVR_ROLL_SIL_CY;
    int16_t lxL   = ROVR_RCOL_X + ROVR_TILT_REF_MARGIN;
    int16_t lxR   = lxL + ROVR_TILT_REF_LEN - 1;
    int16_t rxR   = ROVR_RCOL_X + ROVR_RCOL_W - 1 - ROVR_TILT_REF_MARGIN;
    int16_t rxL   = rxR - ROVR_TILT_REF_LEN + 1;
    tft.drawLine(lxL, refY, lxR, refY, TFT_LIGHT_GREY);
    tft.drawLine(rxL, refY, rxR, refY, TFT_LIGHT_GREY);
}

// Clamp angle to ±45° for display purposes (actual sign preserved). Beyond this
// range the silhouette is drawn at the clamped angle but the color indicates
// the real magnitude (which will be in the alarm zone by this point).
static inline float _rovrClampTilt(float a) {
    if (a >  45.0f) return  45.0f;
    if (a < -45.0f) return -45.0f;
    return a;
}

// Pitch update — redraws the side-view silhouette on significant angle change,
// and the numeric value on integer-degree change. The silhouette itself is
// always drawn in chrome colors; only the numeric value takes the threshold
// color (green normal / yellow warn / red alarm).
static void _rovrUpdatePitch(KCM_TFT &tft) {
    float pitch = state.pitch;
    float pitchClamped = _rovrClampTilt(pitch);

    // Silhouette redraw: only on sufficient angle change, NOT on threshold change
    // (since silhouette color is fixed).
    bool silDirty =
        (fabsf(pitch - _rovrPrevPitch) >= ROVR_TILT_THRESH_DEG) ||
        (_rovrPrevPitch < -9000.0f);

    if (silDirty) {
        _rovrEraseSilhouette(tft, ROVR_PITCH_SIL_CX, ROVR_PITCH_SIL_CY);
        // Nose-up pitch rotates the silhouette CCW on screen: pass -pitch.
        _rovrDrawPitchSilhouette(tft, ROVR_PITCH_SIL_CX, ROVR_PITCH_SIL_CY,
                                 -pitchClamped);
        _rovrPrevPitch = pitch;
    }

    // Numeric readout — threshold-colored, redraws on tenths change OR color change.
    // Cache by iPitch = round(pitch * 10) so the displayed value (1 decimal)
    // determines the dirty boundary.
    uint16_t valueColor = _rovrTiltValueColor(pitch, ROVER_PITCH_WARN_DEG,
                                                     ROVER_PITCH_ALARM_DEG);
    int16_t iPitch = (int16_t)roundf(pitch * 10.0f);
    if (iPitch != _rovrPrevPitchVal || valueColor != _rovrPrevPitchColor) {
        if (_rovrPrevPitchVal > -9000) {
            char oldBuf[12];
            snprintf(oldBuf, sizeof(oldBuf), "%+.1f\xB0", (float)_rovrPrevPitchVal / 10.0f);
            eraseCenteredValue(tft, &Roboto_Black_36,
                                    ROVR_RCOL_X, ROVR_PITCH_VAL_Y, ROVR_RCOL_W, ROVR_TILT_VAL_H,
                                    oldBuf, TFT_BLACK);
        }
        char buf[12];
        snprintf(buf, sizeof(buf), "%+.1f\xB0", pitch);
        textCenter(tft, &Roboto_Black_36,
                   ROVR_RCOL_X, ROVR_PITCH_VAL_Y,
                   ROVR_RCOL_W, ROVR_TILT_VAL_H,
                   buf, valueColor, TFT_BLACK);
        _rovrPrevPitchVal   = iPitch;
        _rovrPrevPitchColor = valueColor;
    }
}

// Roll update — rear-view silhouette. Positive roll (bank right) → right side
// of silhouette down on screen (rotation angle = +roll directly).
static void _rovrUpdateRoll(KCM_TFT &tft) {
    float roll = state.roll;
    float rollClamped = _rovrClampTilt(roll);

    bool silDirty =
        (fabsf(roll - _rovrPrevRoll) >= ROVR_TILT_THRESH_DEG) ||
        (_rovrPrevRoll < -9000.0f);

    if (silDirty) {
        _rovrEraseSilhouette(tft, ROVR_ROLL_SIL_CX, ROVR_ROLL_SIL_CY);
        _rovrDrawRollSilhouette(tft, ROVR_ROLL_SIL_CX, ROVR_ROLL_SIL_CY,
                                rollClamped);
        _rovrPrevRoll = roll;
    }

    uint16_t valueColor = _rovrTiltValueColor(roll, ROVER_ROLL_WARN_DEG,
                                                    ROVER_ROLL_ALARM_DEG);
    int16_t iRoll = (int16_t)roundf(roll * 10.0f);
    if (iRoll != _rovrPrevRollVal || valueColor != _rovrPrevRollColor) {
        if (_rovrPrevRollVal > -9000) {
            char oldBuf[12];
            snprintf(oldBuf, sizeof(oldBuf), "%+.1f\xB0", (float)_rovrPrevRollVal / 10.0f);
            eraseCenteredValue(tft, &Roboto_Black_36,
                                    ROVR_RCOL_X, ROVR_ROLL_VAL_Y, ROVR_RCOL_W, ROVR_TILT_VAL_H,
                                    oldBuf, TFT_BLACK);
        }
        char buf[12];
        snprintf(buf, sizeof(buf), "%+.1f\xB0", roll);
        textCenter(tft, &Roboto_Black_36,
                   ROVR_RCOL_X, ROVR_ROLL_VAL_Y,
                   ROVR_RCOL_W, ROVR_TILT_VAL_H,
                   buf, valueColor, TFT_BLACK);
        _rovrPrevRollVal   = iRoll;
        _rovrPrevRollColor = valueColor;
    }
}

// Heading readout — single-line value inside a bordered box above the nose
// triangle. Box border is drawn once in chrome; this function only touches
// the value text when the integer heading changes. The old value is erased with
// a hardware fillRect before the new value is drawn to handle digit-width changes.
//
// Format: zero-padded 3-digit unsigned heading with ° symbol (e.g. "045°").
static void _rovrUpdateHdgReadout(KCM_TFT &tft, float hdg) {
    int16_t iHdg = (int16_t)roundf(hdg) % 360;
    if (iHdg < 0) iHdg += 360;
    if (iHdg == _rovrPrevHdgVal) return;

    // Erase previous value (black-on-black) if one was drawn.
    // Inset by 2 px from the border on top and bottom so the glyph cell's
    // background fill doesn't overwrite the box border pixels.
    if (_rovrPrevHdgVal > -9000) {
        char oldBuf[8];
        snprintf(oldBuf, sizeof(oldBuf), "%03d\xB0", _rovrPrevHdgVal);
        eraseCenteredValue(tft, &Roboto_Black_36,
                                ROVR_HDG_BOX_X, ROVR_HDG_BOX_Y + 2,
                                ROVR_HDG_BOX_W, ROVR_HDG_BOX_H - 4,
                                oldBuf, TFT_BLACK);
    }

    // Draw new value, zero-padded to 3 digits
    char buf[8];
    snprintf(buf, sizeof(buf), "%03d\xB0", iHdg);
    textCenter(tft, &Roboto_Black_36,
               ROVR_HDG_BOX_X, ROVR_HDG_BOX_Y + 2,
               ROVR_HDG_BOX_W, ROVR_HDG_BOX_H - 4,
               buf, TFT_DARK_GREEN, TFT_BLACK);

    _rovrPrevHdgVal = iHdg;
}

// Full chrome draw — called once on screen entry. Erases the compass area (which
// includes the heading readout box region) and draws all stationary elements:
// outer ring, nose indicator, heading box border, rover silhouette. Then does the
// initial dynamic pass (ticks, labels, heading value, target triangle).
static void _rovrChromeCompass(KCM_TFT &tft) {
    _rovrEraseCompass(tft);

    // Stationary: outer ring
    compassDrawRing(tft, ROVR_GEOM);

    // Stationary: vessel heading indicator (triangle at top of ring, pointing inward)
    _rovrDrawNose(tft);

    // Stationary: heading readout box border (rectangle above the triangle).
    // The border is drawn here ONCE — _rovrUpdateHdgReadout only writes the value
    // text inside the box, never the border, so the border doesn't flicker.
    tft.drawRect(ROVR_HDG_BOX_X, ROVR_HDG_BOX_Y,
                 ROVR_HDG_BOX_W, ROVR_HDG_BOX_H, TFT_GREY);

    // Stationary: rover silhouette at compass centre
    _rovrDrawIcon(tft);

    // Initial dynamic pass
    _rovrDrawTicks(tft, state.heading, false);
    _rovrDrawLabels(tft, state.heading, false);
    _rovrPrevHdgVal = -9999;   // force readout to redraw from scratch
    _rovrUpdateHdgReadout(tft, state.heading);

    _rovrPrevHeading = state.heading;

    // Target triangle — use the independent update function so the previous-
    // position state variables are kept consistent.
    _rovrPrevTgtAvail     = false;
    _rovrPrevTgtScreenDeg = -9999.0f;
    _rovrUpdateTarget(tft);
}

// Incremental compass update — erases ticks and labels at the *previous* heading
// (by drawing them in black), then redraws them at the new heading. Stationary
// elements (outer ring, nose, rover icon, heading box border) are not touched by
// the erase — the tick ends sit 4 px inside the ring so it is never nibbled and
// needs no re-stamp. Heading readout updates via its own integer-change
// detection. Target triangle is handled separately by _rovrUpdateTarget because
// it sits in an annular band that doesn't overlap with ticks or labels.
//
// This avoids the large fillRect on every heading change that would otherwise
// cause visible flicker during continuous yaw.
static void _rovrUpdateCompass(KCM_TFT &tft) {
    // Erase old ticks and labels at previous heading
    _rovrDrawTicks(tft, _rovrPrevHeading, true);
    _rovrDrawLabels(tft, _rovrPrevHeading, true);

    // Draw new ticks and labels at current heading
    _rovrDrawTicks(tft, state.heading, false);
    _rovrDrawLabels(tft, state.heading, false);

    // (The outer ring is NOT re-stamped here: the tick ends sit 4 px inside it
    // (R_TICK_OUTER=196 vs R=200), so the tick-erase can't reach the ring. Skipping
    // the full software drawCircle every heading change saves ~1100 pixel writes.)

    // Update heading readout
    _rovrUpdateHdgReadout(tft, state.heading);

    _rovrPrevHeading = state.heading;
}


// ── Screen entry points ───────────────────────────────────────────────────────────────
static void chromeScreen_ROVR(KCM_TFT &tft) {
    // Reset all change-detection state.
    _rovrPrevHeading      = -9999.0f;
    _rovrPrevTgtAvail     = false;
    _rovrPrevTgtScreenDeg = -9999.0f;
    _rovrPrevThrFill      = -9999;
    _rovrPrevVSrf         = -9999;
    _rovrPrevEndurVal     = "";
    _rovrPrevTgtTimeVal   = "";
    _rovrPrevEcFg         = 0xFFFF;
    _rovrPrevEcBg         = 0xFFFF;
    _rovrPrevBrake        = -1;
    _rovrPrevGear         = -1;
    _rovrPrevSasMode      = -1;
    _rovrPrevPitch        = -9999.0f;
    _rovrPrevRoll         = -9999.0f;
    _rovrPrevPitchVal     = -9999;
    _rovrPrevRollVal      = -9999;
    _rovrPrevPitchColor   = 0;
    _rovrPrevRollColor    = 0;
    _rovrPrevElev         = -99999;
    _rovrPrevTgtDistAvail = false;
    _rovrPrevTgtDistVal   = -1;

    // Compass chrome + initial dynamic pass (erase compass area, draw stationary
    // elements, do first tick/label/heading/target pass).
    _rovrChromeCompass(tft);

    // FWD / REV drive-state blocks — drawn from scratch (both blocks) on the first
    // update since _rovrPrevThrFill was reset to a sentinel above.
    _rovrUpdateThrottle(tft);

    // Left column labels (stationary, drawn once) + initial value passes.
    _rovrDrawVSrfChrome(tft);
    _rovrUpdateVSrf(tft);
    _rovrDrawEcChrome(tft);
    _rovrUpdateEc(tft);
    _rovrUpdateBrake(tft);
    _rovrUpdateGear(tft);
    _rovrUpdateSas(tft);

    // Right column (elevation / pitch / roll)
    _rovrDrawElevChrome(tft);
    _rovrUpdateElev(tft);
    _rovrDrawPitchChrome(tft);
    _rovrUpdatePitch(tft);
    _rovrDrawRollChrome(tft);
    _rovrUpdateRoll(tft);

    // Target distance readout — below the compass, shown only when target is active.
    _rovrUpdateTgtDist(tft);
}

static void drawScreen_ROVR(KCM_TFT &tft) {
    // Heading readout updates whenever the integer degree value changes — may fire
    // at sub-threshold heading movements. Its own cache check is near-free.
    _rovrUpdateHdgReadout(tft, state.heading);

    // Compass redraw (ticks/labels/ring) only when heading has changed past threshold.
    if (fabsf(_rovrHdgDelta(state.heading, _rovrPrevHeading)) >= ROVR_HDG_THRESH_DEG) {
        _rovrUpdateCompass(tft);
    }

    // Target triangle — update on its own cadence, independent of compass redraw.
    _rovrUpdateTarget(tft);

    // Target distance — gated on targetAvailable internally, cheap when no target.
    _rovrUpdateTgtDist(tft);

    // Left column + throttle bar — each with internal change detection.
    _rovrUpdateThrottle(tft);
    _rovrUpdateVSrf(tft);
    _rovrUpdateEc(tft);
    _rovrUpdateBrake(tft);
    _rovrUpdateGear(tft);
    _rovrUpdateSas(tft);

    // Right column
    _rovrUpdateElev(tft);
    _rovrUpdatePitch(tft);
    _rovrUpdateRoll(tft);
}

/***************************************************************************************
   Screen_ROVR_AP.ino — Rover Autopilot console (chrome + draw + touch)

   Touch console for the hold-mode autopilot's rover modes (Controller_Main). Renders
   the 36-byte rover status frame (state.rv*) and lets the pilot engage CRUISE / HDG /
   TGT / FOLLOW, edit the cruise speed, heading, follow range and guard limits, and tap
   A/P OFF. Design: Hold_Mode_Autopilot.md §5, Mission_Autopilot.md §6.

   LAYOUT (the shared console grid — ConsoleShared.ino):
     banner: <CRUISE  TGT | A/P OFF>  <guard / reason>   body · vessel  <ENGAGED / A/P OFF>
     DRIVE               | GUARD LIMITS       | DRIVE DATA
     [CRUISE] [speed]    | SPEED  [limit]     | SPEED    live, signed
     [HDG]    [heading]  | SLOPE  [limit]     | HDG      live
     [TGT]    BRG xxx°   | ROLL   [limit]     | TGT BRG  live
     [FOLLOW] [range]    | STOP   [distance]  | DIST     live
     hint                |                    | PITCH    live
     legend              | [A/P OFF]          | WHL THR  commanded
                         |                    | BRAKES   live
   TGT drives to the target and stops at STOP with the brakes on; FOLLOW holds range to
   a moving target.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

static const uint16_t RA_LBL = KDC_LABEL_COLOR;
static const uint16_t RA_VAL = TFT_DARK_GREEN;
static const uint16_t RA_EDT = TFT_SKY;
#define RA_F_LBL  (&Roboto_Black_24)
#define RA_F_BANN (&Roboto_Black_36)

// Modes: 0 CRUISE, 1 HDG, 2 TGT (no setpoint), 3 FOLLOW. Guards: 0 SPEED, 1 SLOPE, 2 ROLL, 3 STOP.
static const uint8_t RA_MODES  = 4;
static const uint8_t RA_GUARDS = 4;
static const char *const RA_MODE_LBL[RA_MODES]   = { "CRUISE", "HDG", "TGT", "FOLLOW" };
static const uint8_t     RA_ENGAGE_OP[RA_MODES]  = { HP_CMD_ENGAGE_CRUISE, HP_CMD_ENGAGE_RHDG, HP_CMD_ENGAGE_RTGT, HP_CMD_ENGAGE_FOLLOW };
static const uint8_t     RA_FLAG_BIT[RA_MODES]   = { 0x01, 0x02, 0x04, 0x40 };
static const char *const RA_GUARD_LBL[RA_GUARDS] = { "SPEED", "SLOPE", "ROLL", "STOP" };
static const uint8_t     RA_GUARD_OP[RA_GUARDS]  = { HP_CMD_SET_MAXSPD, HP_CMD_SET_MAXSLOPE, HP_CMD_SET_MAXROLL, HP_CMD_SET_STOP_DIST };

// Row-cache slots
static const uint8_t RA_SLOT_BTN   = 0;    // 0..3
static const uint8_t RA_SLOT_VAL   = 4;    // 4..7   cruise speed / heading / target bearing / follow range
static const uint8_t RA_SLOT_GUARD = 8;    // 8..11
static const uint8_t RA_SLOT_DATA  = 12;   // 12..18
static const uint8_t RA_SLOT_BANN  = 19;

static const uint32_t RA_PENDING_TIMEOUT_MS = 3000;

static int8_t   raPend[RA_MODES];
static uint32_t raPendMs[RA_MODES];
static bool     raDirty[RA_MODES];       // setpoint edits: cruise speed, heading, (none), follow range
static float    raPendVal[RA_MODES];
static bool     raGuardDirty[RA_GUARDS];
static float    raGuardPend[RA_GUARDS];
static bool     raScreenRefresh = false;

static bool raEngaged(uint8_t i)   { return (state.rvFlags & RA_FLAG_BIT[i]) != 0; }
static bool raCommanded(uint8_t i) { return raPend[i] >= 0 ? (raPend[i] == 1) : raEngaged(i); }
static float raEcho(uint8_t i)     { return i == 0 ? state.rvCruise : i == 1 ? state.rvHdg : state.rvFollowRange; }
static float raGuardEcho(uint8_t i){ return i == 0 ? state.rvMaxSpeed : i == 1 ? state.rvMaxSlope : i == 2 ? state.rvMaxRoll : state.rvStopDist; }

static void rvReconcile() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < RA_MODES; i++) {
    if (raPend[i] < 0) continue;
    if (raEngaged(i) == (raPend[i] == 1) || now - raPendMs[i] > RA_PENDING_TIMEOUT_MS) raPend[i] = -1;
  }
  for (uint8_t i = 0; i < RA_MODES; i++)
    if (i != 2 && raDirty[i] && fabsf(raEcho(i) - raPendVal[i]) < 0.1f) raDirty[i] = false;
  for (uint8_t i = 0; i < RA_GUARDS; i++)
    if (raGuardDirty[i] && fabsf(raGuardEcho(i) - raGuardPend[i]) < 0.1f) raGuardDirty[i] = false;
}

// Signed ground speed: more than 90 deg between the nose and the surface-velocity
// vector means reverse (the ROVER screen's derivation, and the master's).
static float raSignedSpeed() {
  if (state.surfaceVel < 0.3f) return state.surfaceVel;
  float d = state.srfVelHeading - state.heading;
  while (d > 180.0f) d -= 360.0f;
  while (d < -180.0f) d += 360.0f;
  return (fabsf(d) > 90.0f) ? -state.surfaceVel : state.surfaceVel;
}

static void raHdgBuf(float v, char *buf, size_t n) {
  int16_t h = (int16_t)roundf(v) % 360; if (h < 0) h += 360;
  snprintf(buf, n, "%03d\xB0", h);
}

// ── Chrome ───────────────────────────────────────────────────────────────────────────
void chromeScreen_ROVRAP(KCM_TFT &tft) {
  kpForceClose();
  conDrawColumns(tft, "DRIVE", "GUARD LIMITS", "DRIVE DATA");
  for (uint8_t i = 0; i < RA_MODES; i++)  conDrawValueBox(tft, CON_C1X, i);
  for (uint8_t i = 0; i < RA_GUARDS; i++) {
    textLeft(tft, RA_F_LBL, CON_C2X + 4, conRowY(i), CON_COLW - CON_VALW, CON_ROW_H, RA_GUARD_LBL[i], RA_LBL, TFT_BLACK);
    conDrawValueBox(tft, CON_C2X, i);
  }
  static const char *const DATA_LBL[7] = { "SPEED", "HDG", "TGT BRG", "DIST", "PITCH", "WHL THR", "BRAKES" };
  for (uint8_t r = 0; r < 7; r++)
    textLeft(tft, RA_F_LBL, CON_C3X + 4, conRowY(r), CON_COLW - CON_VALW, CON_ROW_H, DATA_LBL[r], RA_LBL, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 8,  CON_COLW - 8, 20, "TGT stops at STOP; FOLLOW holds", TFT_DARK_GREY, TFT_BLACK);
  textLeft(tft, &Roboto_Black_16, CON_C1X + 4, conRowY(4) + 28, CON_COLW - 8, 20, "range to a moving target.", TFT_DARK_GREY, TFT_BLACK);
  int16_t ly = conRowY(5) + 12, lx = CON_C1X + 2;
  tft.drawRect(lx, ly, 92, 28, TFT_GREY);             textCenter(tft, &Roboto_Black_16, lx, ly, 92, 28, "OFF", TFT_WHITE, TFT_BLACK);
  tft.drawRect(lx + 100, ly, 92, 28, TFT_CYAN);       textCenter(tft, &Roboto_Black_16, lx + 100, ly, 92, 28, "PENDING", TFT_CYAN, TFT_BLACK);
  tft.fillRect(lx + 200, ly, 92, 28, TFT_DARK_GREEN); textCenter(tft, &Roboto_Black_16, lx + 200, ly, 92, 28, "ENGAGED", TFT_WHITE, TFT_DARK_GREEN);
  ButtonLabel b = { "A/P OFF", TFT_WHITE, TFT_WHITE, TFT_OFF_BLACK, TFT_OFF_BLACK, TFT_GREY, TFT_GREY };
  drawButton(tft, CON_C2X, CON_BIG_Y, CON_COLW, CON_BIG_H, b, &Roboto_Black_28, false);
  textCenter(tft, &Roboto_Black_16, CON_C2X, CON_BIG_Y + CON_BIG_H - 26, CON_COLW, 18, "disconnect all, brakes stay as set", TFT_GREY, TFT_OFF_BLACK);
}

// ── Draw ─────────────────────────────────────────────────────────────────────────────
void drawScreen_ROVRAP(KCM_TFT &tft) {
  if (kpTakeClosed()) raScreenRefresh = true;
  if (raScreenRefresh) {
    tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
    chromeScreen_ROVRAP(tft);
    invalidateRowCache(screen_ROVRAP);
    raScreenRefresh = false;
  }
  if (kpIsOpen()) { kpDraw(tft); return; }

  char buf[48];
  bool anyPending = false;
  for (uint8_t i = 0; i < RA_MODES; i++) if (raPend[i] >= 0) anyPending = true;
  bool slopeGuard = (state.rvFlags & 0x10) != 0;
  // Arriving: TGT is capping the speed below the cruise setpoint.
  bool stopping = raEngaged(0) && raEngaged(2) && state.targetAvailable &&
                  raSignedSpeed() < state.rvCruise - 0.5f && state.tgtDistance < 200.0f;

  // Banner
  {
    char modes[40] = "";
    for (uint8_t i = 0; i < RA_MODES; i++)
      if (raEngaged(i)) { if (modes[0]) strlcat(modes, "  ", sizeof(modes)); strlcat(modes, RA_MODE_LBL[i], sizeof(modes)); }
    bool engaged = modes[0] != '\0';
    bool showReason = (state.rvReason != HP_REASON_NONE && state.rvReasonAge <= 5);
    const char *note = showReason ? hpReasonLabel(state.rvReason) : (slopeGuard ? "SLOPE LIMIT" : stopping ? "STOPPING" : "");
    char key[112];
    snprintf(key, sizeof(key), "%s|%s|%s|%d|%s", engaged ? modes : "A/P OFF", note, state.gameSOI.c_str(), anyPending, state.vesselName.c_str());
    RowCache &rc = rowCache[screen_ROVRAP][RA_SLOT_BANN];
    if (rc.value != key) {
      tft.fillRect(0, CON_BANNER_Y, CONTENT_W, CON_BANNER_H, TFT_BLACK);
      textLeft(tft, RA_F_BANN, 8, CON_BANNER_Y, 316, CON_BANNER_H, engaged ? modes : "A/P OFF",
               engaged ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);
      if (note[0]) textLeft(tft, &Roboto_Black_24, 330, CON_BANNER_Y, 300, CON_BANNER_H, note, TFT_ORANGE, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s \xB7 %s", state.gameSOI.c_str(), state.vesselName.c_str());
      textRight(tft, &Roboto_Black_20, 648, CON_BANNER_Y + 4,  CONTENT_W - 648 - 6, 24, buf, RA_LBL, TFT_BLACK);
      snprintf(buf, sizeof(buf), "%s%s", engaged ? "ENGAGED" : "A/P OFF", anyPending ? "..." : "");
      textRight(tft, &Roboto_Black_28, 648, CON_BANNER_Y + 30, CONTENT_W - 648 - 6, 30, buf,
                engaged ? TFT_NEON_GREEN : TFT_DARK_GREY, TFT_BLACK);
      rc.value = key;
    }
  }

  // Mode buttons
  for (uint8_t i = 0; i < RA_MODES; i++) {
    ConBtnState st = raEngaged(i) ? CON_BTN_ON : (raPend[i] >= 0 ? CON_BTN_PENDING : CON_BTN_OFF);
    RowCache &rc = rowCache[screen_ROVRAP][RA_SLOT_BTN + i];
    char k[4]; snprintf(k, sizeof(k), "%d", (int)st);
    if (rc.value != k) {
      conDrawModeButton(tft, CON_C1X + 2, conRowY(i) + 4, CON_BTN_W, CON_VALH, RA_MODE_LBL[i], st);
      rc.value = k;
    }
  }
  int16_t vx = conValX(CON_C1X) + 6, vw = CON_VALW - 10;
  snprintf(buf, sizeof(buf), "%.1f m/s", raDirty[0] ? raPendVal[0] : state.rvCruise);
  conPut(tft, screen_ROVRAP, RA_SLOT_VAL + 0, vx, conRowY(0) + 4, vw, CON_VALH, buf, raDirty[0] ? RA_EDT : (raEngaged(0) ? RA_VAL : TFT_DARK_GREY));
  raHdgBuf(raDirty[1] ? raPendVal[1] : state.rvHdg, buf, sizeof(buf));
  conPut(tft, screen_ROVRAP, RA_SLOT_VAL + 1, vx, conRowY(1) + 4, vw, CON_VALH, buf, raDirty[1] ? RA_EDT : (raEngaged(1) ? RA_VAL : TFT_DARK_GREY));
  if (state.targetAvailable) { char h[12]; raHdgBuf(state.tgtHeading, h, sizeof(h)); snprintf(buf, sizeof(buf), "BRG %s", h); }
  else                       snprintf(buf, sizeof(buf), "NO TGT");
  conPut(tft, screen_ROVRAP, RA_SLOT_VAL + 2, vx, conRowY(2) + 4, vw, CON_VALH, buf, raEngaged(2) ? RA_VAL : TFT_DARK_GREY);
  snprintf(buf, sizeof(buf), "%.0f m", raDirty[3] ? raPendVal[3] : state.rvFollowRange);
  conPut(tft, screen_ROVRAP, RA_SLOT_VAL + 3, vx, conRowY(3) + 4, vw, CON_VALH, buf, raDirty[3] ? RA_EDT : (raEngaged(3) ? RA_VAL : TFT_DARK_GREY));

  // Guard limits
  int16_t gx = conValX(CON_C2X) + 6;
  for (uint8_t i = 0; i < RA_GUARDS; i++) {
    float v = raGuardDirty[i] ? raGuardPend[i] : raGuardEcho(i);
    if (i == 0) snprintf(buf, sizeof(buf), "%.1f m/s", v);
    else if (i == 3) snprintf(buf, sizeof(buf), "%.0f m", v);
    else snprintf(buf, sizeof(buf), "%.0f\xB0", v);
    conPut(tft, screen_ROVRAP, RA_SLOT_GUARD + i, gx, conRowY(i) + 4, vw, CON_VALH, buf, raGuardDirty[i] ? RA_EDT : RA_VAL);
  }

  // Drive data
  int16_t dx = conValX(CON_C3X) + 6;
  snprintf(buf, sizeof(buf), "%+.1f m/s", raSignedSpeed());   conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 0, dx, conRowY(0) + 4, vw, CON_VALH, buf, (slopeGuard || stopping) ? TFT_ORANGE : RA_VAL);
  raHdgBuf(state.heading, buf, sizeof(buf));                  conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 1, dx, conRowY(1) + 4, vw, CON_VALH, buf, RA_VAL);
  if (state.targetAvailable) raHdgBuf(state.tgtHeading, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 2, dx, conRowY(2) + 4, vw, CON_VALH, buf, state.targetAvailable ? RA_VAL : TFT_DARK_GREY);
  if (state.targetAvailable) formatAltBuf(state.tgtDistance, buf, sizeof(buf)); else snprintf(buf, sizeof(buf), "---");
  conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 3, dx, conRowY(3) + 4, vw, CON_VALH, buf, !state.targetAvailable ? TFT_DARK_GREY : stopping ? TFT_ORANGE : RA_VAL);
  snprintf(buf, sizeof(buf), "%+.1f\xB0", state.pitch);       conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 4, dx, conRowY(4) + 4, vw, CON_VALH, buf, slopeGuard ? TFT_ORANGE : RA_VAL);
  snprintf(buf, sizeof(buf), "%+.0f %%", state.rvCmdWheel * 100.0f);
  conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 5, dx, conRowY(5) + 4, vw, CON_VALH, buf, (raEngaged(0) || raEngaged(3)) ? RA_VAL : TFT_DARK_GREY);
  bool brakes = (state.rvFlags & 0x08) != 0 || state.brakes_on;
  conPut(tft, screen_ROVRAP, RA_SLOT_DATA + 6, dx, conRowY(6) + 4, vw, CON_VALH, brakes ? "ON" : "OFF", brakes ? TFT_YELLOW : TFT_GREY);
}

// ── Keypad commits ───────────────────────────────────────────────────────────────────
static void raSetpointCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx < 0 || idx >= RA_MODES || idx == 2) return;
  raPendVal[idx] = v;
  uint8_t op = idx == 0 ? HP_CMD_SET_CRUISE : idx == 1 ? HP_CMD_SET_RHDG : HP_CMD_SET_FOLLOW_RANGE;
  raDirty[idx] = apEnqueueCmd(op, v);
}
static void raGuardCommit(int8_t idx, float v, bool off) {
  (void)off;
  if (idx < 0 || idx >= RA_GUARDS) return;
  raGuardPend[idx] = v;
  raGuardDirty[idx] = apEnqueueCmd(RA_GUARD_OP[idx], v);
}

// ── Touch ────────────────────────────────────────────────────────────────────────────
void rovrApScreenTouch(uint16_t x, uint16_t y) {
  if (kpIsOpen()) { kpTouch(x, y); return; }
  uint32_t now = millis();

  if (y >= CON_BIG_Y && y < CON_BIG_Y + CON_BIG_H && x >= CON_C2X && x < CON_C2X + CON_COLW) {
    if (apEnqueueCmd(HP_CMD_AP_OFF, 0.0f))
      for (uint8_t i = 0; i < RA_MODES; i++) if (raEngaged(i)) { raPend[i] = 0; raPendMs[i] = now; }
    return;
  }

  for (uint8_t r = 0; r < 4; r++) {
    int16_t cy = conRowY(r);
    if (y < cy || y >= cy + CON_ROW_H) continue;
    if (x >= CON_C1X + 2 && x < CON_C1X + 2 + CON_BTN_W) {
      bool want = !raCommanded(r);
      if (apEnqueueCmd(RA_ENGAGE_OP[r], want ? 1.0f : 0.0f)) { raPend[r] = want ? 1 : 0; raPendMs[r] = now; }
      return;
    }
    if (x >= conValX(CON_C1X) && x < conValX(CON_C1X) + CON_VALW && r != 2) {
      KpField f = (r == 0) ? KpField{ "CRUISE SPEED", "m/s", -10.0f, 60.0f, false, true, 1 }
                : (r == 1) ? KpField{ "HEADING", "\xB0", 0.0f, 359.9f, false, false, 0 }
                           : KpField{ "FOLLOW RANGE", "m", 5.0f, 500.0f, false, false, 0 };
      kpOpen(f, (int8_t)r, raSetpointCommit);
      return;
    }
    if (x >= conValX(CON_C2X) && x < conValX(CON_C2X) + CON_VALW) {
      KpField f = (r == 0) ? KpField{ "SPEED LIMIT", "m/s", 1.0f, 60.0f, false, false, 1 }
                : (r == 1) ? KpField{ "SLOPE LIMIT", "\xB0", 5.0f, 45.0f, false, false, 0 }
                : (r == 2) ? KpField{ "ROLL LIMIT",  "\xB0", 5.0f, 60.0f, false, false, 0 }
                           : KpField{ "STOP DISTANCE", "m", 2.0f, 200.0f, false, false, 0 };
      kpOpen(f, (int8_t)r, raGuardCommit);
      return;
    }
  }
}

/***************************************************************************************
   Screen_SCFT.ino  --  Spacecraft screen  (EADI style)

   EADI GEOMETRY
   -------------
   The aircraft symbol is FIXED at screen centre (CX, CY), always horizontal.
   The ball moves behind it:
     Ball centre:  BCX = CX - pitchPx*sinR
                   BCY = CY + pitchPx*cosR
   The horizon passes through (BCX, BCY), tilted at roll angle R.
   Horizon line equation:  sinR*x - cosR*y = K
     where K = sinR*CX - cosR*CY - pitchPx  (independent of roll)
   Sky side:    sinR*x - cosR*y > K
   Ground side: sinR*x - cosR*y <= K

   The perpendicular distance from (CX,CY) to the horizon = pitchPx always.
   At lad_p=pitch: rung foot = (CX,CY) exactly at all roll angles.

   PITCH LADDER
   ------------
   Rung at lad_p degrees:
     foot = (BCX + lad_p*SCALE*sinR,  BCY - lad_p*SCALE*cosR)
   Rung line direction = (cosR, sinR)  (parallel to horizon).
   Sky-ward normal = (sinR, -cosR).

   DISC
   ----
   Fixed on screen, centred at (CX, CY), radius R.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Geometry ──────────────────────────────────────────────────────────────────────────
// ONE PFD, ONE SET OF NUMBERS -- see the same note at the head of Screen_ACFT.ino.
// This screen and AIRCRAFT draw the same instrument with the same renderer, and the
// geometry used to be written out in full three times over, each re-derived from its own
// copy of CX/CY/R. EADIBall.ino holds the single definition; these are aliases so the
// chrome below still reads in this screen's own vocabulary. SPACECRAFT differs from
// AIRCRAFT only in what it omits (VSI, slip, AoA) and in its row content, never in where
// anything sits.
static const int16_t  SCFT_CX        = EADI_CX;
static const int16_t  SCFT_CY        = EADI_CY;
static const int16_t  SCFT_R         = EADI_R;

// ── Right panel geometry ───────────────────────────────────────────────────────────────
static const int16_t  SCFT_PANEL_X       = SCFT_CX - (SCFT_R*2+54)/2 + (SCFT_R*2+54) + 2; // 580
static const int16_t  SCFT_PANEL_RIGHT   = CONTENT_W;   // 940 — abuts the sidebar divider
static const int16_t  SCFT_PANEL_W       = SCFT_PANEL_RIGHT - SCFT_PANEL_X;  // 360 (= reticle panel)
static const uint8_t  SCFT_PANEL_NR      = 8;

// ── Right panel state ──────────────────────────────────────────────────────────────────
// Cache managed by rowCache[screen_SCFT] / printState[screen_SCFT] slots 0-8.
// No additional state variables needed — printValue handles dirty detection.

// ── Per-frame state ───────────────────────────────────────────────────────────────────

static float    _scftPrevPitch   = -9999.0f;
static float    _scftPrevRoll    = -9999.0f;
bool            _scftPrevOrbMode = false;

// Active velocity vector — set each frame by drawScreen_SCFT based on orbMode.
// Both tapes and the panel V.Orb/V.Srf row read from these.
static float    _scftVelHdg   = 0.0f;
static float    _scftVelPitch = 0.0f;
static bool     _scftFullRedrawNeeded = true;



// ── Orbital mode helpers ──────────────────────────────────────────────────────────────
// One altitude test used to drive three different things: row 1's V.Orb/V.Srf, row 5's
// T+Ign/V.Vrt, and the prograde marker on the ball and both tapes. Only two of those are
// a REFERENCE choice. Row 5's swap is a PHASE decision -- am I near the ground, is
// descent rate the number being flown -- that merely happened to reuse the same test.
//
// The distinction did not matter while both were automatic, because they always agreed.
// It matters the moment the pilot can override the reference: forcing ORB at 10 km during
// a re-entry must not trade descent rate away for a meaningless ignition countdown. So
// the two are separate predicates, and only the reference one is overridable.
static bool _scftAutoOrb() {
    float bodyRad   = (currentBody.radius > 0.0f) ? currentBody.radius : DEFAULT_BODY_RADIUS_M;
    bool  ascending = (state.verticalVel >= 0.0f);
    float switchAlt = ascending ? (bodyRad * ORB_SWITCH_ALT_FRAC_ASC) : (bodyRad * ORB_SWITCH_ALT_FRAC_DESC);
    return state.altitude > switchAlt;
}

// The velocity reference actually in force: automatic unless the pilot has pinned one.
ModeOverride _scftVelRefOverride;
// Chip cache: -1 unknown, 0 auto-SRF, 1 auto-ORB, 2 held-SRF, 3 held-ORB. Declared here
// rather than beside its draw function because chromeScreen_SCFT resets it, and the
// Arduino builder hoists prototypes but not variables.
static int8_t _scftChipShown = -1;
static bool _scftVelRef() { return modeResolve(_scftVelRefOverride, _scftAutoOrb()); }

// ── EVA mode ──────────────────────────────────────────────────────────────────────────
// A Kerbal outside the craft is still a vessel as far as KSP and Simpit are concerned,
// so it lands here on the vehicle panel — and the attitude ball is genuinely the right
// instrument, because you do orient on EVA. The numeric panel beside it was not: a
// Kerbal has no stage, no burn and no apoapsis worth reading, so rows 2-6 were showing
// dV.Stg, ApA, PeA, T+Ap and T+Ign, none of which mean anything to a person holding a
// jetpack. Those five rows swap to what an EVA is actually flown on: how high above the
// surface, how fast relative to it, and how far from and how quickly closing on whatever
// you are trying to reach.
//
// Row 6 becomes suit charge. dV.Stg would read a flat green 0 m/s, and electric charge
// is the number that ends an EVA -- ROVER already reads the same field for the same
// reason.
static inline bool _scftEvaMode() { return state.vesselType == type_EVA; }
static bool _scftPrevEvaMode = false;


// ── Row 5: descent rate, ignition countdown, or the burn itself ───────────────────────
// Three states, not two. Below the mode switch the row is V.Vrt (see the chrome, which
// explains why altitude rate is phase-specific instrumentation on every real spacecraft
// that flies it). Above the switch it is T+Ign -- and, once that burn is actually under
// way, dV.Rem counting down.
//
// The countdown is Apollo's. The CSM Entry Monitor System's dV counter was set before a
// burn and counted to zero as the SPS thrust; the crew shut down on it, and it was the
// most-watched number in the burn. Nothing on this controller counted a burn down before
// this: MANEUVER carries Brg, Elv, Burn.Dur, T+Ign and T+Mnvr, and no dV at all.
//
// Row 5 is the right home because the fit is exact -- a countdown TO ignition is
// meaningless once ignition has happened, so the row is free precisely when the burn
// number is wanted. V.Vrt's claim below the switch is untouched: a noded burn under
// 36 km is rare, and descent rate still wins there if one happens.
//
// One difference from the EMS worth knowing. Apollo's counter integrated an accelerometer
// along the thrust axis, so it measured what the engine actually delivered and pointing
// error showed up as a residual that would not null. state.mnvrDeltaV is the guidance
// number -- what the node still needs -- which nulls correctly however the craft is
// pointed, and therefore hides that error. It is the better number to fly on; it is not
// the same instrument.
static const uint8_t SCFT_R5_VVRT  = 0;
static const uint8_t SCFT_R5_TIGN  = 1;
static const uint8_t SCFT_R5_DVREM = 2;

// Seconds until the burn should light, negative once it should already have.
static float _scftTIgn() {
    return (state.mnvrTime > 0.0f) ? (state.mnvrTime - state.mnvrDuration / 2.0f) : 1.0f;
}

static uint8_t _scftRow5Mode() {
    if (!_scftAutoOrb()) return SCFT_R5_VVRT;   // phase, not reference -- see above
    const bool hasNode  = (state.mnvrTime > 0.0f) && (state.mnvrDeltaV > 0.0f);
    const bool burning  = hasNode && (state.throttle > 0.01f) && (_scftTIgn() <= 0.0f);
    return burning ? SCFT_R5_DVREM : SCFT_R5_TIGN;
}

static const char *_scftRow5Label(uint8_t mode) {
    return (mode == SCFT_R5_VVRT)  ? "V.VRT"
         : (mode == SCFT_R5_DVREM) ? "\xCE\x94V.REM"
                                   : "T+IGN";
}

// The label follows the throttle, so it cannot wait for a full chrome repaint the way
// the orbMode swap does. Only row 5's chrome is redrawn, and its cache slot is cleared
// so printValue repaints the value that printDispChrome just filled over.
static uint8_t _scftPrevRow5Mode = 255;
static bool    _scftPrevRow4Pe   = false;   // row 4 label: false = T+AP (what chrome paints), true = T+PE
static bool    _scftTrimShown    = false;   // TRIM flag is on screen (reset by chrome)





// Scanline fill, aircraft symbol, and disc clip are shared with ACFT — see EADIBall.ino
// (eadiDrawScanline / eadiDrawAircraftSymbol / eadiClipToDisk).








// ── ADI marker state (ball-side tracking — separate from tape-side state) ─────────────
// When any of these changes meaningfully, the ball must be redrawn so markers can be
// repositioned. Ball markers are drawn as the last layer of the ball (just before the
// aircraft symbol), so they're naturally wiped and re-rendered on any ball redraw.
static float _scftPrevHeadingBall    = -9999.0f;
static float _scftPrevVelHdgBall     = -9999.0f;
static float _scftPrevVelPitchBall   = -9999.0f;
static float _scftPrevMnvrHdgBall    = -9999.0f;
static float _scftPrevMnvrPitchBall  = -9999.0f;
static float _scftPrevTgtHdgBall     = -9999.0f;
static float _scftPrevTgtPitchBall   = -9999.0f;
static bool  _scftPrevMnvrActiveBall = false;
static bool  _scftPrevTgtAvailBall   = false;





// ── Roll indicator state ──────────────────────────────────────────────────────────────
static int16_t  _scftPrevRollReadout   = -9999;      // last drawn roll readout (integer degrees)
static uint16_t _scftPrevRollReadoutFg = 0;          // last drawn foreground colour

// ── Pitch readout state ───────────────────────────────────────────────────────────────


// Roll readout — geometry is EADI_ROLL_* in EADIBall.ino, which is what actually draws
// it. This screen only chooses the colour (a fixed dark green -- no roll warnings).

// Update the roll numeric readout — spacecraft uses a fixed dark-green (no roll warnings).
// Scaffolding/geometry live in the shared eadiUpdateRollReadout(); see EADIBall.ino.
static void _scftUpdateRollReadout(KCM_TFT &tft, float roll) {
    uint16_t fg = TFT_DARK_GREEN;  // spacecraft — no roll warnings
    uint16_t bg = TFT_BLACK;
    eadiUpdateRollReadout(tft, roll, fg, bg,
                          _scftPrevRollReadout, _scftPrevRollReadoutFg);
}

// ── Pitch tape ────────────────────────────────────────────────────────────────────────
// Shared availability state (also used by heading tape)
static bool    _scftPrevTgtAvail   = false;
static bool    _scftPrevMnvrActive = false;
// Vertical tape on the left side of the disc. Same scale as the pitch ladder.
// ±30° visible, ticks at every 5° (minor) and 10° (major).
// Current value box centred on disc centre (pitch=0 line).
// Markers: left-pointing triangles on the right edge for vel/tgt/mnvr pitch.

// Only the outer frame and the value box are drawn here; the ticks, labels, markers and
// suppress zone belong to eadiDrawPitchTape.
static const int16_t  SCFT_PTAPE_W       = EADI_PTAPE_W;       // 36
static const int16_t  SCFT_PTAPE_X       = EADI_PTAPE_X;       // 76
static const int16_t  SCFT_PTAPE_Y       = EADI_PTAPE_Y;       // 94  — top of disc
static const int16_t  SCFT_PTAPE_H       = EADI_PTAPE_H;       // 420 — bottom meets the HDG tape
static const int16_t  SCFT_PTAPE_BOX_W   = EADI_PTAPE_BOX_W;   // 68
static const int16_t  SCFT_PTAPE_BOX_H   = EADI_PTAPE_BOX_H;   // 38
static const int16_t  SCFT_PTAPE_BOX_X   = EADI_PTAPE_BOX_X;   // 44
static const int16_t  SCFT_PTAPE_BOX_Y   = EADI_PTAPE_BOX_Y;   // 281 — centred on pitch = 0

// State
static float   _scftPrevPitch2      = -9999.0f;   // pitch tape (distinct from ball state)
static int16_t _scftPrevPitchBox    = -9999;
static float   _scftPrevVelPitch    = -9999.0f;
static float   _scftPrevTgtPitch    = -9999.0f;
static float   _scftPrevMnvrPitch   = -9999.0f;

// Draw/update the pitch value box — delegated to the shared helper (see EADIBall.ino).
static void _scftUpdatePitchBox(KCM_TFT &tft, float pitch) {
    eadiUpdatePitchBox(tft, pitch, _scftPrevPitchBox);
}

// Draw the full pitch tape. Spacecraft markers: velocity (prograde) always, target when
// available, maneuver when a node exists. Scaffolding lives in the shared helper.
static void _scftDrawPitchTape(KCM_TFT &tft, float pitch) {
    EadiTapeMarker mk[3];
    uint8_t n = 0;
    mk[n++] = { _scftVelPitch, TFT_NEON_GREEN };
    if (state.targetAvailable) mk[n++] = { state.tgtPitch,  TFT_VIOLET };
    if (state.mnvrTime > 0.0f) mk[n++] = { state.mnvrPitch, TFT_BLUE };
    eadiDrawPitchTape(tft, pitch, mk, n);
}

// Update pitch tape — redraws when pitch or any marker pitch changes.
static void _scftUpdatePitchTape(KCM_TFT &tft, float pitch) {
    bool mnvrActive = (state.mnvrTime > 0.0f);
    bool dirty = fabsf(pitch - _scftPrevPitch2)                   >= 0.2f
              || fabsf(_scftVelPitch         - _scftPrevVelPitch)  >= 0.2f
              || fabsf(state.tgtPitch       - _scftPrevTgtPitch)  >= 0.2f
              || fabsf(state.mnvrPitch      - _scftPrevMnvrPitch) >= 0.2f
              || state.targetAvailable != _scftPrevTgtAvail
              || mnvrActive           != _scftPrevMnvrActive;

    if (dirty) {
        _scftDrawPitchTape(tft, pitch);
        _scftPrevPitch2     = pitch;
        _scftPrevVelPitch   = _scftVelPitch;
        _scftPrevTgtPitch   = state.tgtPitch;
        _scftPrevMnvrPitch  = state.mnvrPitch;
        // Note: _scftPrevTgtAvail and _scftPrevMnvrActive shared with heading tape
    }
    _scftUpdatePitchBox(tft, pitch);
}

// ── Heading tape state ────────────────────────────────────────────────────────────────
static float   _scftPrevHeading    = -9999.0f;
static int16_t _scftPrevHdgBox     = -9999;
static float   _scftPrevVelHdg     = -9999.0f;
static float   _scftPrevTgtHdg     = -9999.0f;
static float   _scftPrevMnvrHdg    = -9999.0f;

// ── Heading tape geometry ─────────────────────────────────────────────────────────────
// As above: frame and box only. Ticks, labels, markers and the suppress zone are
// eadiDrawHeadingTape's.
static const int16_t  SCFT_HDG_TAPE_W    = EADI_HDG_TAPE_W;    // 466 — ±35° visible
static const int16_t  SCFT_HDG_TAPE_X    = EADI_HDG_TAPE_X;    // 112
static const int16_t  SCFT_HDG_TAPE_Y    = EADI_HDG_TAPE_Y;    // 514 — 8 px below the disc
static const int16_t  SCFT_HDG_TAPE_H    = EADI_HDG_TAPE_H;    // 32
static const int16_t  SCFT_HDG_BOX_W     = EADI_HDG_BOX_W;     // 72
static const int16_t  SCFT_HDG_BOX_H     = EADI_HDG_BOX_H;     // 40 — 8 px taller than the tape,
static const int16_t  SCFT_HDG_BOX_X     = EADI_HDG_BOX_X;     //   so its bottom border sits
static const int16_t  SCFT_HDG_BOX_Y     = EADI_HDG_BOX_Y;     //   outside the fill and can't flicker

// Draw/update the heading number box — delegated to the shared helper (see EADIBall.ino).
static void _scftUpdateHdgBox(KCM_TFT &tft, float hdg) {
    eadiUpdateHdgBox(tft, hdg, _scftPrevHdgBox);
}

// Draw the full heading tape. Spacecraft markers: velocity (prograde) always, target when
// available, maneuver when a node exists. Scaffolding lives in the shared helper, which
// also forces _scftPrevHdgBox to -1 (the fill blackens the box interior).
static void _scftDrawHeadingTape(KCM_TFT &tft, float hdg) {
    EadiTapeMarker mk[3];
    uint8_t n = 0;
    mk[n++] = { _scftVelHdg, TFT_NEON_GREEN };
    if (state.targetAvailable) mk[n++] = { state.tgtHeading,  TFT_VIOLET };
    if (state.mnvrTime > 0.0f) mk[n++] = { state.mnvrHeading, TFT_BLUE };
    eadiDrawHeadingTape(tft, hdg, _scftPrevHdgBox, mk, n);
}

// Update heading — tape redraws when heading or any marker heading changes.
static void _scftUpdateHeadingTape(KCM_TFT &tft, float hdg) {
    bool mnvrActive = (state.mnvrTime > 0.0f);
    bool dirty = fabsf(hdg - _scftPrevHeading)             >= 0.5f
              || fabsf(_scftVelHdg - _scftPrevVelHdg)       >= 0.5f
              || fabsf(state.tgtHeading - _scftPrevTgtHdg) >= 0.5f
              || fabsf(state.mnvrHeading - _scftPrevMnvrHdg) >= 0.5f
              || state.targetAvailable != _scftPrevTgtAvail
              || mnvrActive           != _scftPrevMnvrActive;

    if (dirty) {
        _scftDrawHeadingTape(tft, hdg);
        _scftPrevHeading    = hdg;
        _scftPrevVelHdg     = _scftVelHdg;
        _scftPrevTgtHdg     = state.tgtHeading;
        _scftPrevMnvrHdg    = state.mnvrHeading;
        _scftPrevTgtAvail   = state.targetAvailable;
        _scftPrevMnvrActive = mnvrActive;
    }
    _scftUpdateHdgBox(tft, hdg);
}




// ── Throttle bar (left strip — occupies the ACFT VSI slot) ────────────────────────────
// Vertical 0–100% gauge: 0% at the bottom, 100% at the top, filled bottom-up. No
// danger thresholds — throttle is a control input, so it uses a single amber fill.
static const int16_t THR_X       = 2;
static const int16_t THR_BAR_W   = 18;
static const int16_t THR_TICK_X0 = THR_X + THR_BAR_W;      // 20
static const int16_t THR_LABEL_H = 62;                     // rotated "THR" label at bottom
static const int16_t THR_TOP_Y   = SCFT_PTAPE_Y + 6;       // 100 — 100% mark sits below the
                                                           //   "PITCH" label (bottom y=92)
static const int16_t THR_BOT_Y   = SCREEN_H - THR_LABEL_H - 14; // 524 — 0% mark; range chosen so the
                                                           //   20% ticks bracket (not overlap) the
                                                           //   pitch value box (y 281..319)
static const int16_t THR_TRACK_H = THR_BOT_Y - THR_TOP_Y;       // 424
static float _scftPrevThrottle   = -9999.0f;

static void _scftDrawThrottleChrome(KCM_TFT &tft) {
    // Right border of the strip
    tft.drawLine(THR_TICK_X0 + 1, TITLE_TOP, THR_TICK_X0 + 1, SCREEN_H - 1, TFT_GREY);
    tft.setFont(Roboto_Black_12);
    for (int16_t p = 0; p <= 100; p += 5) {
        int16_t ty    = THR_BOT_Y - (int16_t)((float)p / 100.0f * THR_TRACK_H);
        bool    major = (p % 20 == 0);
        // Major ticks (every 20%) — long, light grey, labelled. Minor ticks
        // (every 5%) — short, dark grey, no label. Matches the VSI/pitch-tape style.
        tft.drawLine(THR_TICK_X0, ty, THR_TICK_X0 + (major ? 10 : 6), ty,
                     major ? TFT_LIGHT_GREY : TFT_GREY);
        if (major) {
            tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
            tft.setCursor(THR_TICK_X0 + 12, ty - 6);
            char lbl[4]; snprintf(lbl, sizeof(lbl), "%d", p);
            tft.print(lbl);
        }
    }
    // "THR" label — vertical, at the bottom, matching the Pitch/Hdg label style
    drawVerticalText(tft, THR_X, SCREEN_H - THR_LABEL_H, THR_BAR_W, THR_LABEL_H,
                     &Roboto_Black_16, "THR", TFT_WHITE, TFT_BLACK);
}

static void _scftUpdateThrottle(KCM_TFT &tft, float throttle) {
    if (fabsf(throttle - _scftPrevThrottle) < 0.005f) return;
    _scftPrevThrottle = throttle;
    float   clamped = constrain(throttle, 0.0f, 1.0f);
    int16_t fillH   = (int16_t)(clamped * THR_TRACK_H);
    tft.fillRect(THR_X, THR_TOP_Y, THR_BAR_W, THR_TRACK_H, TFT_BLACK);
    if (fillH > 0)
        tft.fillRect(THR_X, THR_BOT_Y - fillH, THR_BAR_W, fillH, TFT_ORANGE);
}


// ── Vitals strip (bottom — occupies the ACFT slip slot) ───────────────────────────────
// Three horizontal bars: Electric Charge %, hottest core temp %, hottest skin temp %.
// EC is green when high (low = bad); temps are green when low (high = bad).
static const int16_t VIT_Y         = SCFT_HDG_BOX_Y + SCFT_HDG_BOX_H + 2; // just below the HDG box
static const int16_t VIT_ROW_H     = 14;
static const int16_t VIT_BAR_H     = 10;
static const int16_t VIT_LBL_RIGHT = SCFT_PTAPE_X + SCFT_PTAPE_W;      // 112 — labels right-align here
                                                                      //   (= pitch tape right edge)
static const int16_t VIT_BAR_X     = VIT_LBL_RIGHT + 4;               // 116 — bars start just right of it
static const int16_t VIT_RIGHT     = SCFT_HDG_TAPE_X + SCFT_HDG_TAPE_W; // 578 — strip right edge (divider)
static const int16_t VIT_VAL_W     = 46;                              // value column ("100%")
static const int16_t VIT_BAR_RIGHT = VIT_RIGHT - VIT_VAL_W;           // 532 — bar track right edge
static int16_t _scftPrevEC   = -9999;
static int16_t _scftPrevCore = -9999;
static int16_t _scftPrevSkin = -9999;

static inline int16_t _scftVitBarX() { return VIT_BAR_X; }
static inline int16_t _scftVitBarW() { return VIT_BAR_RIGHT - VIT_BAR_X; }
static inline int16_t _scftVitBarY(uint8_t row) {
    return VIT_Y + row * VIT_ROW_H + (VIT_ROW_H - VIT_BAR_H) / 2;
}

static void _scftVitalsChrome(KCM_TFT &tft) {
    tft.setFont(Roboto_Black_12);
    static const char *labels[] = {"EC", "CORE", "SKIN"};
    for (uint8_t i = 0; i < 3; i++) {
        int16_t ry = VIT_Y + i * VIT_ROW_H;
        int16_t lw = getFontStringWidth(&Roboto_Black_12, labels[i]);
        tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
        tft.setCursor(VIT_LBL_RIGHT - lw, ry);   // right-aligned to the pitch tape edge
        tft.print(labels[i]);
        tft.drawRect(_scftVitBarX(), _scftVitBarY(i), _scftVitBarW(), VIT_BAR_H, TFT_GREY);
    }
}

// Draw one vitals bar fill + value. lowIsBad=true → low % is the alarm (EC).
// Thresholds are the shared annunciator-aligned values (EC: 20%/5%, temp: 75/90).
static void _scftDrawVitalBar(KCM_TFT &tft, uint8_t row, int16_t pct, bool lowIsBad) {
    pct = constrain(pct, (int16_t)0, (int16_t)100);
    uint16_t col;
    if (lowIsBad)   // electric charge — low charge is the alarm
        col = (pct < (int16_t)(EC_LOW_ALARM_FRAC * 100.0f)) ? TFT_RED :
              (pct < (int16_t)(EC_LOW_WARN_FRAC  * 100.0f)) ? TFT_YELLOW : TFT_DARK_GREEN;
    else            // temperature — high temp is the alarm
        col = (pct > TEMP_ALARM_PCT) ? TFT_RED :
              (pct > TEMP_WARN_PCT)  ? TFT_YELLOW : TFT_DARK_GREEN;
    int16_t bx = _scftVitBarX(), bw = _scftVitBarW(), by = _scftVitBarY(row);
    int16_t fillW = (int16_t)((float)pct / 100.0f * (bw - 2));
    tft.fillRect(bx + 1, by + 1, bw - 2, VIT_BAR_H - 2, TFT_OFF_BLACK);
    if (fillW > 0) tft.fillRect(bx + 1, by + 1, fillW, VIT_BAR_H - 2, col);
    // Warn/alarm threshold ticks — same treatment as the re-entry temp bars.
    float warnFrac  = lowIsBad ? EC_LOW_WARN_FRAC  : TEMP_WARN_PCT  / 100.0f;
    float alarmFrac = lowIsBad ? EC_LOW_ALARM_FRAC : TEMP_ALARM_PCT / 100.0f;
    int16_t xw = bx + 1 + (int16_t)(warnFrac  * (bw - 2));
    int16_t xa = bx + 1 + (int16_t)(alarmFrac * (bw - 2));
    tft.drawLine(xw, by + 1, xw, by + VIT_BAR_H - 2, TFT_YELLOW);
    tft.drawLine(xa, by + 1, xa, by + VIT_BAR_H - 2, TFT_RED);
    // Value text — right-aligned in the value column (right of the bar track)
    int16_t ry = VIT_Y + row * VIT_ROW_H;
    char buf[6]; snprintf(buf, sizeof(buf), "%d%%", pct);
    int16_t vw = getFontStringWidth(&Roboto_Black_12, buf);
    tft.fillRect(VIT_BAR_RIGHT, ry, VIT_VAL_W, VIT_ROW_H, TFT_BLACK);
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(col, TFT_BLACK);
    tft.setCursor(VIT_RIGHT - vw - 2, ry);
    tft.print(buf);
}

static void _scftUpdateVitals(KCM_TFT &tft) {
    int16_t ec   = (int16_t)roundf(state.electricChargePercent);
    int16_t core = (int16_t)state.coreTempPct;
    int16_t skin = (int16_t)state.skinTempPct;
    if (ec   != _scftPrevEC)   { _scftDrawVitalBar(tft, 0, ec,   true);  _scftPrevEC   = ec; }
    if (core != _scftPrevCore) { _scftDrawVitalBar(tft, 1, core, false); _scftPrevCore = core; }
    if (skin != _scftPrevSkin) { _scftDrawVitalBar(tft, 2, skin, false); _scftPrevSkin = skin; }
}


// ── Attitude rate pointers ────────────────────────────────────────────────────────────
// The one conspicuous thing both real attitude balls carry that this one did not. The
// Shuttle ADI has three rate pointers on the ball's edges (full scale selectable +/-1,
// +/-5 or +/-10 deg/s on the ADI RATE switch) and the Apollo FDAI has the same three
// needles, because a spacecraft is flown on rates: an RCS pulse is judged by the rate it
// produces, not by where the ball settles ten seconds later.
//
// Rates come from kcmRateUpdate (KerbalDisplayCommon), which differentiates the ROTATION
// rather than the Euler angles so it stays well conditioned near vertical -- see the
// header there, including the bench test that is still outstanding.
//
// PLACEMENT, and why it is not the Shuttle's. The Shuttle puts roll along the top of the
// ball and yaw along the bottom, so each pointer moves the way its axis moves. There is
// no room for that here, and the numbers say so rather than the eye: the throttle scale
// runs to x~54, the pitch tape occupies 75..112, the disc bezel is 137..553, the bank
// labels reach x=130 and x=556 at y=174..193, the heading tape starts at y=514 and the
// panel divider is at x=578. That leaves three usable columns -- 18 px, 23 px and 20 px
// wide -- and nothing horizontal wider than 23 px anywhere on the screen.
//
// So all three share one column to the right of the ball, stacked, all vertical, all
// reading the same way: UP IS POSITIVE, with positive meaning roll right, nose up, nose
// right. Consistency between the three is worth more than matching a layout we cannot
// fit, and keeping them together is how a rate cluster is actually scanned.
static const float   SCFT_RATE_FS     = 10.0f;   // deg/s at either end of every bar

static const int16_t SCFT_RATE_X      = 557;     // clear of the "60" bank label (556)
static const int16_t SCFT_RATE_W      = 20;      //   and the panel divider (578)
static const int16_t SCFT_RATE_LBL_H  = 14;      // single-letter name above each bar
// VERTICAL BUDGET. The column is boxed in at both ends and both numbers are measured
// against the real glyph data rather than guessed:
//   TOP  -- the roll readout is right-justified into x 497..583, so it lands squarely on
//           this column. Its value row paints y 97..130 ("+180" at Roboto_Black_28,
//           cap 33, centred in the 38 px value row below the 30 px label row from
//           TITLE_TOP=62). The first version started the stack at y=96, which put the "P"
//           label and the top 20 px of the pitch bar inside that box -- so every time the
//           roll digits changed they were erased. Start at 136 to clear it with margin.
//   BOTTOM-- the TRIM flag: "TRIM" is 59 px at Roboto_Black_24 (cap 29), right-aligned to
//           the heading tape's right edge (578) less 8, so x 511..570 -- squarely on this
//           column too -- and its erase rect starts at y=473. The stack must end above it.
// That leaves 136..471, i.e. 335 px for 3*(14 + BAR_H) + 2*8, so BAR_H <= 92.
static const int16_t SCFT_RATE_BAR_H  = 92;
static const int16_t SCFT_RATE_PITCH_Y = 136;                                   // R
static const int16_t SCFT_RATE_ROLL_Y  = SCFT_RATE_PITCH_Y + SCFT_RATE_LBL_H + SCFT_RATE_BAR_H + 8;
static const int16_t SCFT_RATE_YAW_Y   = SCFT_RATE_ROLL_Y  + SCFT_RATE_LBL_H + SCFT_RATE_BAR_H + 8;

static const uint16_t SCFT_RATE_FILL  = TFT_WHITE;

static KcmRateTracker _scftRates;
static const int16_t  SCFT_RATE_RESET = INT16_MIN;
static int16_t _scftPrevRollPx  = SCFT_RATE_RESET;
static int16_t _scftPrevPitchPx = SCFT_RATE_RESET;
static int16_t _scftPrevYawPx   = SCFT_RATE_RESET;

// Signed pixel offset from a bar's zero line, clamped to the track.
static int16_t _scftRatePx(float degPerSec) {
    const int16_t halfSpan = SCFT_RATE_BAR_H / 2 - 1;
    float f = degPerSec / SCFT_RATE_FS;
    if (f >  1.0f) f =  1.0f;
    if (f < -1.0f) f = -1.0f;
    return (int16_t)lroundf(f * (float)halfSpan);
}

static inline int16_t _scftRateBarY(int16_t rowY) { return rowY + SCFT_RATE_LBL_H; }

// Track outline, zero tick and single-letter name for all three bars.
static void _scftDrawRateChrome(KCM_TFT &tft) {
    static const char *names[3] = { "P", "R", "Y" };
    const int16_t rowY[3] = { SCFT_RATE_PITCH_Y, SCFT_RATE_ROLL_Y, SCFT_RATE_YAW_Y };
    tft.setFont(Roboto_Black_12);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    for (uint8_t i = 0; i < 3; i++) {
        const int16_t lw = getFontStringWidth(&Roboto_Black_12, names[i]);
        tft.setCursor(SCFT_RATE_X + (SCFT_RATE_W - lw) / 2, rowY[i]);
        tft.print(names[i]);
        const int16_t by = _scftRateBarY(rowY[i]);
        tft.drawRect(SCFT_RATE_X, by, SCFT_RATE_W, SCFT_RATE_BAR_H, TFT_GREY);
        const int16_t zy = by + SCFT_RATE_BAR_H / 2;
        tft.drawLine(SCFT_RATE_X - 3, zy, SCFT_RATE_X + SCFT_RATE_W + 2, zy, TFT_LIGHT_GREY);
    }
}

// Repaint one bar's fill. Only the union of the old and new extents is touched, so a
// pointer trembling around zero costs a few pixels rather than a full-track fill --
// these move on almost every frame, unlike the vitals bars they sit near.
static void _scftDrawRateFill(KCM_TFT &tft, int16_t rowY, int16_t oldPx, int16_t newPx) {
    const int16_t lo = (int16_t)min((int)(oldPx < 0 ? oldPx : 0), (int)(newPx < 0 ? newPx : 0));
    const int16_t hi = (int16_t)max((int)(oldPx > 0 ? oldPx : 0), (int)(newPx > 0 ? newPx : 0));
    if (lo == 0 && hi == 0) return;
    const int16_t zy = _scftRateBarY(rowY) + SCFT_RATE_BAR_H / 2;   // + is up
    tft.fillRect(SCFT_RATE_X + 1, zy - hi, SCFT_RATE_W - 2, (hi - lo), TFT_BLACK);
    if (newPx > 0)      tft.fillRect(SCFT_RATE_X + 1, zy - newPx, SCFT_RATE_W - 2, newPx,  SCFT_RATE_FILL);
    else if (newPx < 0) tft.fillRect(SCFT_RATE_X + 1, zy,         SCFT_RATE_W - 2, -newPx, SCFT_RATE_FILL);
}

static void _scftUpdateRates(KCM_TFT &tft) {
    const bool first = (_scftPrevPitchPx == SCFT_RATE_RESET);
    if (!kcmRateUpdate(_scftRates, state.heading, state.pitch, state.roll, millis()) && !first)
        return;

    const int16_t pp = _scftRatePx(_scftRates.pitch);
    const int16_t rp = _scftRatePx(_scftRates.roll);
    const int16_t yp = _scftRatePx(_scftRates.yaw);
    const int16_t pPrev = first ? 0 : _scftPrevPitchPx;
    const int16_t rPrev = first ? 0 : _scftPrevRollPx;
    const int16_t yPrev = first ? 0 : _scftPrevYawPx;

    if (pp != pPrev || first) _scftDrawRateFill(tft, SCFT_RATE_PITCH_Y, pPrev, pp);
    if (rp != rPrev || first) _scftDrawRateFill(tft, SCFT_RATE_ROLL_Y,  rPrev, rp);
    if (yp != yPrev || first) _scftDrawRateFill(tft, SCFT_RATE_YAW_Y,   yPrev, yp);

    _scftPrevPitchPx = pp; _scftPrevRollPx = rp; _scftPrevYawPx = yp;
}


// ── Screen chrome ─────────────────────────────────────────────────────────────────────
static void chromeScreen_SCFT(KCM_TFT &tft) {
    eadiBallResetState();
    _scftFullRedrawNeeded      = true;
    // The mode flags the draw pass compares against are set to what this chrome is
    // about to paint. Left stale (a vessel switch resets one, EVA can begin on another
    // screen) the first draw pass re-entered the screen before painting any value: one
    // frame of labels with empty rows, then a second full chrome pass.
    _scftPrevEvaMode           = _scftEvaMode();
    _scftPrevOrbMode           = _scftVelRef();
    _scftPrevRow4Pe            = false;
    _scftTrimShown             = false;
    eadiResetRollIndicator();
    _scftPrevRollReadout       = -9999;
    _scftPrevRollReadoutFg     = 0;
    _scftPrevPitch2            = -9999.0f;
    _scftPrevPitchBox          = -9999;
    _scftPrevVelPitch          = -9999.0f;
    _scftPrevTgtPitch          = -9999.0f;
    _scftPrevMnvrPitch         = -9999.0f;
    _scftPrevHeading           = -9999.0f;
    _scftPrevHdgBox            = -9999;
    _scftPrevVelHdg            = -9999.0f;
    _scftPrevTgtHdg            = -9999.0f;
    _scftPrevMnvrHdg           = -9999.0f;
    _scftPrevTgtAvail          = false;
    _scftPrevMnvrActive        = false;
    // Ball-side marker trackers (distinct from tape-side; see _scftDrawAdiMarker)
    _scftPrevHeadingBall       = -9999.0f;
    _scftPrevVelHdgBall        = -9999.0f;
    _scftPrevVelPitchBall      = -9999.0f;
    _scftPrevMnvrHdgBall       = -9999.0f;
    _scftPrevMnvrPitchBall     = -9999.0f;
    _scftPrevTgtHdgBall        = -9999.0f;
    _scftPrevTgtPitchBall      = -9999.0f;
    _scftPrevMnvrActiveBall    = false;
    _scftPrevTgtAvailBall      = false;
    // Panel values reset via rowCache invalidation (row cache cleared on screen switch)
    // Ball delta-fill state (chord table, dirty bitmaps, prev horizon) reset above.
    _scftPrevPitch        = -9999.0f;
    _scftPrevRoll         = -9999.0f;
    _scftPrevThrottle     = -9999.0f;
    _scftPrevEC           = -9999;
    _scftPrevCore         = -9999;
    _scftPrevSkin         = -9999;
    _scftChipShown = -1;
    kcmRateReset(_scftRates);
    _scftPrevRollPx       = SCFT_RATE_RESET;
    _scftPrevPitchPx      = SCFT_RATE_RESET;
    _scftPrevYawPx        = SCFT_RATE_RESET;

    // Bezel ring
    tft.drawCircle(SCFT_CX, SCFT_CY, SCFT_R,     TFT_LIGHT_GREY);
    tft.drawCircle(SCFT_CX, SCFT_CY, SCFT_R + 1, TFT_WHITE);
    tft.drawCircle(SCFT_CX, SCFT_CY, SCFT_R + 2, TFT_DARK_GREY);

    // Bank scale tick marks outside the disc circumference (upper arc)
    static const int16_t ticks[] = {-60,-45,-30,-20,-10,0,10,20,30,45,60};
    for (uint8_t i = 0; i < 11; i++) eadiDrawBankTick(tft, ticks[i]);

    // Labels at ±30° and ±60° — drawn at R+28 along the tick radial (Roboto_Black_16)
    static const int16_t labelTicks[] = {-60, -30, 30, 60};
    for (uint8_t i = 0; i < 4; i++) eadiDrawBankLabel(tft, labelTicks[i]);

    // Heading box border
    tft.drawRect(SCFT_HDG_BOX_X, SCFT_HDG_BOX_Y, SCFT_HDG_BOX_W, SCFT_HDG_BOX_H, TFT_LIGHT_GREY);

    // Pitch tape chrome — value box border and three-sided tape border (top, right, bottom)
    tft.drawRect(SCFT_PTAPE_BOX_X, SCFT_PTAPE_BOX_Y, SCFT_PTAPE_BOX_W, SCFT_PTAPE_BOX_H, TFT_LIGHT_GREY);
    // Top, right, bottom lines — right and bottom drawn 1px inward to align with HDG tape borders
    tft.drawLine(SCFT_PTAPE_X - 1,                  SCFT_PTAPE_Y - 1,
                 SCFT_PTAPE_X + SCFT_PTAPE_W - 1,    SCFT_PTAPE_Y - 1, TFT_LIGHT_GREY);
    tft.drawLine(SCFT_PTAPE_X + SCFT_PTAPE_W - 1,    SCFT_PTAPE_Y - 1,
                 SCFT_PTAPE_X + SCFT_PTAPE_W - 1,    SCFT_PTAPE_Y + SCFT_PTAPE_H - 1, TFT_GREY);
    tft.drawLine(SCFT_PTAPE_X - 1,                  SCFT_PTAPE_Y + SCFT_PTAPE_H - 1,
                 SCFT_PTAPE_X + SCFT_PTAPE_W - 1,    SCFT_PTAPE_Y + SCFT_PTAPE_H - 1, TFT_LIGHT_GREY);

    // "PITCH" right-justified to right edge of pitch value box (box widened left
    // so the larger _24 label — 75px — fits without clipping the pitch value box)
    textRight(tft, &Roboto_Black_24,
              SCFT_PTAPE_BOX_X - 24, SCFT_PTAPE_Y - 32,
              SCFT_PTAPE_BOX_W + 24, 30,
              "PITCH", TFT_WHITE, TFT_BLACK);

    // Heading tape border — top (light grey) and two sides (darker), open at bottom
    tft.drawLine(SCFT_HDG_TAPE_X - 1, SCFT_HDG_TAPE_Y - 1,
                 SCFT_HDG_TAPE_X + SCFT_HDG_TAPE_W, SCFT_HDG_TAPE_Y - 1, TFT_LIGHT_GREY);
    tft.drawLine(SCFT_HDG_TAPE_X - 1, SCFT_HDG_TAPE_Y - 1,
                 SCFT_HDG_TAPE_X - 1, SCFT_HDG_TAPE_Y + SCFT_HDG_TAPE_H, TFT_GREY);
    tft.drawLine(SCFT_HDG_TAPE_X + SCFT_HDG_TAPE_W, SCFT_HDG_TAPE_Y - 1,
                 SCFT_HDG_TAPE_X + SCFT_HDG_TAPE_W, SCFT_HDG_TAPE_Y + SCFT_HDG_TAPE_H, TFT_GREY);

    // "HDG" right-justified to same right edge as "PITCH" label
    textRight(tft, &Roboto_Black_24,
              SCFT_PTAPE_BOX_X, SCFT_HDG_BOX_Y + SCFT_HDG_BOX_H / 2 - 15,
              SCFT_PTAPE_BOX_W, 30,
              "HDG", TFT_WHITE, TFT_BLACK);

    // ── Throttle bar (left) + vitals strip (bottom) — fill the ACFT VSI/slip slots ─────
    _scftDrawThrottleChrome(tft);
    _scftVitalsChrome(tft);
    _scftDrawRateChrome(tft);

    // ── Right panel chrome ─────────────────────────────────────────────────────────────
    // Vertical divider (2px) between ADI and panel
    tft.drawLine(SCFT_PANEL_X - 2, TITLE_TOP, SCFT_PANEL_X - 2, SCREEN_H - 1, TFT_GREY);
    tft.drawLine(SCFT_PANEL_X - 1, TITLE_TOP, SCFT_PANEL_X - 1, SCREEN_H - 1, TFT_GREY);

    static const tFont *PF = &Roboto_Black_28;   // label font — matches reticle/launch panels

    // Rows 0-6: single-width rows. Rows 1 and 5 depend on orbMode (see below).
    static const char *panelLabels[] = {
        "ALT.SL", nullptr, "APA", "PEA", "T+AP", nullptr, "\xCE\x94V.STG"
    };
    // On EVA the same seven rows carry a different set — see _scftEvaMode(). Row 1 is
    // pinned to V.Orb here rather than following orbMode, so that V.Orb and V.Srf are
    // both always on the panel: the pair is how you tell station-keeping from drifting.
    static const char *evaPanelLabels[] = {
        "ALT.SL", "V.ORB", "ALT.RDR", "V.SRF", "DIST", "V.CLOSE", "EC"
    };
    const bool evaChrome = _scftEvaMode();
    for (uint8_t r = 0; r < 7; r++) {
        // Row 5 is T+Ign in orbit and V.Vrt below the mode-switch altitude. Real
        // spacecraft treat altitude rate as a phase-specific instrument rather than a
        // permanent one: the Shuttle's PFD carries a vertical-speed tape only in its
        // entry configuration (on orbit it shows the ADI ball alone) and its AVVI's
        // radar portion is live only in MM305; Apollo gave the LM a dedicated ALT RATE
        // tapemeter because the LM lands, while the CM had none and read altitude rate
        // from the DSKY on demand (V06 N62); Orion puts altitude rate on its entry
        // format. This row does the same thing with the switch the screen already runs.
        //
        // The trade is exact. Above the switch a node countdown is the useful half --
        // and the PFD is the ONLY place it appears outside MANEUVER's ten-minute window,
        // so it must not simply be dropped. Below the switch a node countdown is close
        // to meaningless and descent rate is the number being flown.
        const char *lbl = evaChrome ? evaPanelLabels[r]
                        : (r == 1) ? (_scftVelRef() ? "V.ORB" : "V.SRF")
                        : (r == 5) ? _scftRow5Label(_scftRow5Mode())
                        : panelLabels[r];
        printDispChrome(tft, PF, SCFT_PANEL_X, rowYFor(r, SCFT_PANEL_NR),
                        SCFT_PANEL_W, rowHFor(SCFT_PANEL_NR),
                        lbl, COL_LABEL, COL_BACK, COL_NO_BDR);
    }

    // Chrome has just painted row 5 with whichever label was current; record it so the
    // update below only relabels when it actually changes.
    _scftPrevRow5Mode = evaChrome ? (uint8_t)255 : _scftRow5Mode();

    // Row 7 — split divider (2px)
    {
        uint16_t hw = SCFT_PANEL_W / 2;
        tft.drawLine(SCFT_PANEL_X + hw,     TITLE_TOP + 7 * rowHFor(SCFT_PANEL_NR),
                     SCFT_PANEL_X + hw,     SCREEN_H - 1, TFT_GREY);
        tft.drawLine(SCFT_PANEL_X + hw + 1, TITLE_TOP + 7 * rowHFor(SCFT_PANEL_NR),
                     SCFT_PANEL_X + hw + 1, SCREEN_H - 1, TFT_GREY);
    }
}


// ── Right panel update ─────────────────────────────────────────────────────────────────
// Uses printValue + rowCache[screen_SCFT] exactly as LNDG/ORB screens do.
// Cache slots 0-9: Alt.SL, V.Orb, ApA, PeA, T+Ap/Pe, T+Ign, ΔV.Stg, RCS, SAS label, SAS value
static void _scftUpdatePanel(KCM_TFT &tft, bool orbMode) {
    static const tFont *VF  = &Roboto_Black_36;   // value font — matches reticle/launch panels
    static const uint8_t SC = (uint8_t)screen_SCFT;

    bool hasMnvr  = (state.mnvrTime > 0.0f);
    bool hasOrbit = (state.apoapsis > 0.0f || state.periapsis > 0.0f);
    bool evaMode  = _scftEvaMode();
    bool hasTgt   = state.targetAvailable;
    uint16_t fw = SCFT_PANEL_W;
    uint16_t hw = SCFT_PANEL_W / 2;

    auto attPanelVal = [&](uint8_t row, uint8_t slot, const char *label,
                           const String &val, uint16_t fg, uint16_t bg) {
        drawPanelValue(tft, SC, slot, row, SCFT_PANEL_X, fw, label, val, fg, bg, VF, SCFT_PANEL_NR, true);
    };

    // Row 0 — Alt.SL
    {
        uint16_t fg = TFT_DARK_GREEN;
        String val = hasOrbit ? formatAlt(state.altitude) : "---";
        attPanelVal(0, 0, "ALT.SL", val, fg, TFT_BLACK);
    }

    // Row 1 — V.Orb or V.Srf depending on orbital mode; pinned to V.Orb on EVA, where
    // row 3 carries V.Srf and the two are read as a pair.
    {
        uint16_t fg = TFT_DARK_GREEN;
        const char *lbl = (evaMode || orbMode) ? "V.ORB" : "V.SRF";
        float vel = (evaMode || orbMode) ? state.orbitalVel : state.surfaceVel;
        String val = hasOrbit ? fmtMs(vel) : "---";
        attPanelVal(1, 1, lbl, val, fg, TFT_BLACK);
    }

    // Rows 2-6 on EVA — height above the surface, drift, and the approach numbers.
    // Returns early: the split row 7 (RCS/SAS) and the dividers below are shared, so
    // they are drawn by the common tail, not duplicated here.
    if (evaMode) {
        // Row 2 — Alt.Rdr. The one altitude that matters when a Kerbal is near a surface.
        attPanelVal(2, 2, "ALT.RDR", formatAlt(state.radarAlt), TFT_DARK_GREEN, TFT_BLACK);

        // Row 3 — V.Srf. Beside V.Orb above: station-keeping vs drifting.
        attPanelVal(3, 3, "V.SRF", fmtMs(state.surfaceVel), TFT_DARK_GREEN, TFT_BLACK);

        // Row 4 — Dist to target, dashed when nothing is selected.
        attPanelVal(4, 4, "DIST", hasTgt ? formatAlt(state.tgtDistance) : String("---"),
                    hasTgt ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);

        // Row 5 — V.Close. Same sign convention as TGT/DOCK: negative is closing.
        attPanelVal(5, 5, "V.CLOSE", hasTgt ? fmtMs(state.tgtVelocity) : String("---"),
                    hasTgt ? TFT_DARK_GREEN : TFT_DARK_GREY, TFT_BLACK);

        // Row 6 — suit charge, on ROVER's thresholds (5% alarm, 20% caution).
        {
            float ec = constrain(state.electricChargePercent, 0.0f, 100.0f);
            uint16_t fg, bg;
            thresholdColor(ec,
                           EC_PCT_ALARM, TFT_WHITE,  TFT_RED,
                           EC_PCT_WARN,  TFT_YELLOW, TFT_BLACK,
                           TFT_DARK_GREEN, TFT_BLACK, fg, bg);
            char buf[8];
            snprintf(buf, sizeof(buf), "%d%%", (int)lroundf(ec));
            attPanelVal(6, 6, "EC", String(buf), fg, bg);
        }
    } else {

    // Row 2 — ApA
    {
        // Escape trajectory: apoapsis undefined (KSP reports it negative) -> infinity
        bool escape = hasOrbit && (state.apoapsis < 0.0f);
        String val  = !hasOrbit ? String("---") : (escape ? String("\x80") : formatAlt(state.apoapsis));
        attPanelVal(2, 2, "APA", val, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 3 — PeA
    {
        // Suborbital periapsis is informational here (not a launch/descent screen) -> neutral
        String val = hasOrbit ? formatAlt(state.periapsis) : "---";
        attPanelVal(3, 3, "PEA", val, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 4 — T+Ap or T+Pe (whichever is sooner and positive)
    {
        float tAp = state.timeToAp, tPe = state.timeToPe;
        float tNext; const char *lbl;
        if (!hasOrbit)                        { tNext = -1.0f; lbl = "T+AP"; }
        else if (tAp >= 0.0f && tPe >= 0.0f) { tNext = min(tAp,tPe); lbl = (tAp < tPe) ? "T+AP" : "T+PE"; }
        else if (tAp >= 0.0f)                 { tNext = tAp; lbl = "T+AP"; }
        else                                  { tNext = tPe; lbl = "T+PE"; }
        // The label is chrome and printValue never repaints it, so a swap between T+AP
        // and T+PE has to repaint this row's chrome itself, as row 5 does below.
        const bool pe = (lbl[2] == 'P');
        if (pe != _scftPrevRow4Pe) {
            printDispChrome(tft, &Roboto_Black_28, SCFT_PANEL_X,
                            rowYFor(4, SCFT_PANEL_NR), SCFT_PANEL_W,
                            rowHFor(SCFT_PANEL_NR), lbl,
                            COL_LABEL, COL_BACK, COL_NO_BDR);
            rowCache[SC][4] = RowCache();
            printState[SC][4] = PrintState();
            _scftPrevRow4Pe = pe;
        }
        String val = (tNext >= 0.0f) ? formatTimeCompact((int64_t)tNext) : "---";
        attPanelVal(4, 4, lbl, val, TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 5 — V.Vrt below the mode switch, T+Ign above it, dV.Rem once that burn is
    // actually under way. See _scftRow5Mode above for why all three live on one row.
    {
        const uint8_t r5 = _scftRow5Mode();
        // The label follows the throttle, so unlike the orbMode swap it cannot wait for
        // a screen re-entry. Repaint just this row's chrome and clear its cache slot,
        // since printDispChrome has filled over the value printValue last wrote.
        if (r5 != _scftPrevRow5Mode) {
            printDispChrome(tft, &Roboto_Black_28, SCFT_PANEL_X,
                            rowYFor(5, SCFT_PANEL_NR), SCFT_PANEL_W,
                            rowHFor(SCFT_PANEL_NR), _scftRow5Label(r5),
                            COL_LABEL, COL_BACK, COL_NO_BDR);
            rowCache[SC][5] = RowCache();
            printState[SC][5] = PrintState();
            _scftPrevRow5Mode = r5;
        }

        uint16_t fg = TFT_DARK_GREEN, bg = TFT_BLACK;
        String val;
        if (r5 == SCFT_R5_VVRT) {
            // Reported, not alarmed. LNDG's thresholds are LANDING thresholds -- alarm at
            // -8 m/s, caution at -5 -- and reusing them here would paint the row red for
            // the whole of a normal descent, which is the always-on alarm that teaches a
            // pilot to ignore the colour. POWERED DESCENT owns that alarm and has the
            // radar altitude to justify it; the Shuttle's AVVI is likewise unalarmed.
            val = fmtMs(state.verticalVel);
        } else if (r5 == SCFT_R5_DVREM) {
            // Unalarmed for the same reason the EMS counter was: it is watched, not
            // warned on. The pilot shuts down when it reaches zero.
            val = fmtMs(state.mnvrDeltaV);
        } else {
            const float tIgn = hasMnvr ? _scftTIgn() : -1.0f;
            if (!hasMnvr)                     { fg = TFT_DARK_GREY; val = "---"; }
            else if (tIgn < 0.0f)             { fg = TFT_WHITE; bg = TFT_RED;
                                                val = formatTimeCompact((int64_t)tIgn); }
            else if (tIgn < MNVR_TIGN_WARN_S) { fg = TFT_YELLOW;
                                                val = formatTimeCompact((int64_t)tIgn); }
            else                              { val = formatTimeCompact((int64_t)tIgn); }
        }
        attPanelVal(5, 5, _scftRow5Label(r5), val, fg, bg);
    }

    // Row 6 — ΔV.Stg (low-stage-fuel warning; the flat DV_STG_WARN_MS tier, as LAUNCH
    // and POWERED DESCENT use it. VEHICLE INFO alone raises the warn tier on the last
    // stage, where stage and total ΔV are the same number.)
    {
        uint16_t fg, bg;
        thresholdColor(state.stageDeltaV,
                       DV_STG_ALARM_MS, TFT_WHITE,  TFT_RED,
                       DV_STG_WARN_MS,  TFT_YELLOW, TFT_BLACK,
                       TFT_DARK_GREEN, TFT_BLACK, fg, bg);
        attPanelVal(6, 6, "\xCE\x94V.STG", fmtMs(state.stageDeltaV), fg, bg);
    }
    }   // end of the non-EVA rows 2-6

    // Row 7 split — RCS button (left half) | SAS button (right half).
    // Shared: RCS and SAS are exactly as meaningful for a Kerbal on a jetpack.
    {
        uint16_t ry  = TITLE_TOP + 7 * rowHFor(SCFT_PANEL_NR);  // full row top (no ROW_PAD)
        uint16_t rh  = SCREEN_H - ry - 1;                        // bottom border on row 598 (599 overscanned)
        uint16_t sasX = SCFT_PANEL_X + hw;
        uint16_t sasW = SCFT_PANEL_RIGHT - sasX;                 // fills remainder exactly

        // RCS button (slot 7)
        {
            bool rcsOn = state.rcs_on;
            String rcsStr = rcsOn ? "ON" : "OFF";
            RowCache &rc = rowCache[SC][7];
            if (rc.value != rcsStr) {
                ButtonLabel btn = rcsOn
                    ? ButtonLabel{ "RCS", TFT_WHITE,     TFT_WHITE,     TFT_DARK_GREEN, TFT_DARK_GREEN, TFT_GREY, TFT_GREY }
                    : ButtonLabel{ "RCS", TFT_DARK_GREY, TFT_DARK_GREY, TFT_OFF_BLACK,  TFT_OFF_BLACK,  TFT_GREY, TFT_GREY };
                drawButton(tft, SCFT_PANEL_X, ry, hw, rh, btn, &Roboto_Black_28, false);
                rc.value = rcsStr;
            }
        }

        // SAS button (slot 8)
        {
            const char *v; uint16_t fg, bg;
            sasNavballLabel(state.sasMode, v, fg, bg);
            RowCache &rc = rowCache[SC][8];
            if (rc.value != v || rc.fg != fg || rc.bg != bg) {
                ButtonLabel btn = { v, fg, fg, bg, bg, TFT_GREY, TFT_GREY };
                drawButton(tft, sasX, ry, sasW, rh, btn, &Roboto_Black_28, false);
                rc.value = v; rc.fg = fg; rc.bg = bg;
            }
        }
    }

    // Redraw horizontal dividers last — printValue fillRects erase them on value changes.
    // Same pattern as LNDG powered descent screen.
    static const uint8_t divRows[] = { 2, 4, 5, 6 };
    for (uint8_t i = 0; i < 4; i++) {
        uint16_t dy = TITLE_TOP + divRows[i] * rowHFor(SCFT_PANEL_NR);
        tft.drawLine(SCFT_PANEL_X, dy,     SCFT_PANEL_RIGHT - 1, dy,     TFT_GREY);
        tft.drawLine(SCFT_PANEL_X, dy + 1, SCFT_PANEL_RIGHT - 1, dy + 1, TFT_GREY);
    }
}


// ── Screen update ─────────────────────────────────────────────────────────────────────
// "TRIM" annunciation (cyan) in the graphical area's bottom-right corner: right-aligned to
// the heading-tape right edge, bottom just above the heading-tape top. Redrawn each frame
// while trim is enabled; erased once when it clears.
// ── Velocity reference chip ───────────────────────────────────────────────────────────
// SRF or ORB, mirrored from TRIM at the heading tape's left edge. See drawRefChip in
// AAA_Screens.ino for the colour rule and the hit box.
//
// It annunciates the VELOCITY reference only -- the prograde marker on the ball and both
// tapes, and row 1. It deliberately does not cover altitude: SRF and ORB differ by a
// rotation about the body's spin axis, and altitude is radial and unchanged by that
// rotation, so Alt.SL is the same number in both frames and there is no such thing as an
// orbital altitude. (The Shuttle mixed them freely for the same reason: its AMI showed
// Earth-relative velocity beside the AVVI's geodetic altitude, with nothing to
// annunciate.) Nor does it cover row 5, which is a phase choice -- see _scftAutoOrb.

static void _scftUpdateRefChip(KCM_TFT &tft) {
    const bool orb  = _scftVelRef();
    const bool held = _scftVelRefOverride.manual;
    const int8_t want = (int8_t)((held ? 2 : 0) + (orb ? 1 : 0));
    if (want == _scftChipShown) return;
    _scftChipShown = want;
    drawRefChip(tft, orb ? "ORB" : "SRF", held);
}

// One tap pins the other reference, or drops back to auto if that is what auto wants.
void scftToggleVelRef() {
    modeToggle(_scftVelRefOverride, _scftAutoOrb());
    _scftChipShown = -1;   // repaint on the next frame
}

// Drawn on the edges only: the frame copy carries the flag between them.
static void _scftDrawTrim(KCM_TFT &tft) {
    if (state.trimEnabled == _scftTrimShown) return;
    int16_t tw = getFontStringWidth(&Roboto_Black_24, "TRIM");
    int16_t x  = (SCFT_HDG_TAPE_X + SCFT_HDG_TAPE_W) - tw - 8;
    int16_t y  = SCFT_HDG_TAPE_Y - (int16_t)Roboto_Black_24.cap_height - 2 - 8;
    if (state.trimEnabled) {
        tft.setFont(Roboto_Black_24);
        tft.setTextColor(TFT_CYAN, TFT_BLACK);
        tft.setCursor(x, y);
        tft.print("TRIM");
    } else {
        tft.fillRect(x - 2, y - 2, tw + 4, (int16_t)Roboto_Black_24.cap_height + 6, TFT_BLACK);
    }
    _scftTrimShown = state.trimEnabled;
}

static void drawScreen_SCFT(KCM_TFT &tft) {
    // Boarding or leaving a craft changes which seven rows the panel carries, and the
    // row labels are chrome. Re-enter the screen so the chrome redraws with them --
    // exactly how the V.Orb/V.Srf swap below has always been handled.
    bool evaMode = _scftEvaMode();
    if (evaMode != _scftPrevEvaMode) {
        _scftPrevEvaMode      = evaMode;
        _scftFullRedrawNeeded = true;
        switchToScreen(screen_SCFT);
        return;
    }

    bool orbMode = _scftVelRef();
    if (orbMode != _scftPrevOrbMode) {
        _scftPrevOrbMode      = orbMode;
        _scftFullRedrawNeeded = true;
        switchToScreen(screen_SCFT);
        return;
    }

    // Select active velocity vector based on orbital mode — computed BEFORE the
    // ball dirty check since the ball's ADI markers depend on it.
    _scftVelHdg   = orbMode ? state.orbVelHeading : state.srfVelHeading;
    _scftVelPitch = orbMode ? state.orbVelPitch   : state.srfVelPitch;

    bool mnvrActive = (state.mnvrTime > 0.0f);
    bool tgtAvail   = state.targetAvailable;

    // Attitude dirty — pitch/roll as before, plus heading (which now affects ball
    // because ADI markers project relative to it).
    bool ballDirty = _scftFullRedrawNeeded                                        ||
                     fabsf(state.pitch - _scftPrevPitch)                  >= 0.2f ||
                     fabsf(state.roll  - _scftPrevRoll)                   >= 0.2f ||
                     fabsf(eadiHdgDelta(state.heading, _scftPrevHeadingBall)) >= 0.5f;

    // Marker dirty — any visible marker's world position changed, or a marker's
    // availability toggled (target acquired/lost, maneuver set/cleared).
    if (!ballDirty) {
        ballDirty = fabsf(eadiHdgDelta(_scftVelHdg, _scftPrevVelHdgBall)) >= 0.5f ||
                    fabsf(_scftVelPitch - _scftPrevVelPitchBall)           >= 0.5f ||
                    mnvrActive != _scftPrevMnvrActiveBall                         ||
                    tgtAvail   != _scftPrevTgtAvailBall;
    }
    if (!ballDirty && mnvrActive) {
        ballDirty = fabsf(eadiHdgDelta(state.mnvrHeading, _scftPrevMnvrHdgBall)) >= 0.5f ||
                    fabsf(state.mnvrPitch - _scftPrevMnvrPitchBall)               >= 0.5f;
    }
    if (!ballDirty && tgtAvail) {
        ballDirty = fabsf(eadiHdgDelta(state.tgtHeading, _scftPrevTgtHdgBall)) >= 0.5f ||
                    fabsf(state.tgtPitch - _scftPrevTgtPitchBall)               >= 0.5f;
    }

    if (ballDirty) {
        bool full = _scftFullRedrawNeeded;
        uint32_t t0 = micros();
        eadiDrawBall(tft, full, _scftVelHdg, _scftVelPitch, true);   // orbital-frame markers on
        // Snapshot ball-dirty trackers for next frame's dirty check.
        _scftPrevPitch = state.pitch;
        _scftPrevRoll  = state.roll;
        _scftPrevHeadingBall    = state.heading;
        _scftPrevVelHdgBall     = _scftVelHdg;
        _scftPrevVelPitchBall   = _scftVelPitch;
        _scftPrevMnvrHdgBall    = state.mnvrHeading;
        _scftPrevMnvrPitchBall  = state.mnvrPitch;
        _scftPrevTgtHdgBall     = state.tgtHeading;
        _scftPrevTgtPitchBall   = state.tgtPitch;
        _scftPrevMnvrActiveBall = (state.mnvrTime > 0.0f);
        _scftPrevTgtAvailBall   = state.targetAvailable;
        _scftFullRedrawNeeded = false;
        uint32_t dt = micros() - t0;
        if (debugMode) {
            Serial.print(full ? "SCFT_FULL total=" : "SCFT_DELTA total=");
            Serial.print((float)dt / 1000.0f, 2);
            Serial.print("ms  pitch="); Serial.print(state.pitch, 1);
            Serial.print("  roll=");    Serial.println(state.roll, 1);
        }
    }

    // Roll indicator — update whenever roll changes, independent of ball redraw
    eadiUpdateRollIndicator(tft, state.roll);
    _scftUpdateRollReadout(tft, state.roll);
    _scftUpdatePitchTape(tft, state.pitch);
    _scftUpdateHeadingTape(tft, state.heading);
    _scftUpdateThrottle(tft, state.throttle);
    _scftUpdateVitals(tft);
    _scftUpdateRates(tft);
    _scftUpdatePanel(tft, orbMode);
    _scftUpdateRefChip(tft);
    _scftDrawTrim(tft);
}


/***************************************************************************************
   Screen_TGT.ino  —  Target / Rendezvous screen  (RPOD display)

   LAYOUT (1024×600, content area 940×538 below title bar; reticle R=210)
   ┌─────────────────────────────────┬──────────────────────────────────────┐
   │   RPOD Scope                    │ DIST:           48.3 km             │
   │   (black disc, R=210, ±60°)     │                                      │
   │                                 │ V.CLOSE:         -1.4 m/s            │
   │   ◆ target (TFT_VIOLET)         │ BRG:  +22.0°  │ ELV:  -14.0°        │
   │   ○ velocity vector (NEON_GREEN)│ V.BRG:  +14.0° │ V.ELV:  -9.0°      │
   │   + nose crosshair (fixed)      │ T+INT:          6m 30s               │
   └─────────────────────────────────┴──────────────────────────────────────┘

   SCOPE SEMANTICS
   ───────────────
   Fixed crosshair (+) = your nose direction (always at screen centre)
   Violet diamond (TGT) = where the target is relative to your nose
                          Centre → nose is pointed at target
   Green circle (VEL)   = where your relative velocity points relative to your nose
                          Centre → you are flying straight along the boresight
   Dimmed marker        = pinned at the scope boundary (further off the nose than the
                          outer ring can show); direction honest, distance understated.
                          Brg/Elv carry the true value.
   Perfect intercept    = both dots converging on each other (VEL sitting on TGT means
                          the relative velocity is aimed at the target; V.Brg/V.Elv are
                          that error in degrees, measured about the target axis)

   SCOPE GEOMETRY (rev-2, 1024×600)
   ──────────────
   Centre: (289, 300)   Radius: 210px   Scale: 3.5 px/deg (±60° full scale)
   Field of view: ±60° (wider than DOCK ±20° — long-range ops need more range)
   Rings: 15°=r52, 30°=r105, 45°=r157, 60°=r210. Centre/radius match the
   MNVR and DOCK reticles.
   Right panel: 360 px at x=580 (matches MNVR/DOCK), labels 28 / values 36

   RIGHT PANEL — 5 rows, rowHFor(5) = 106px each
   Row 0  Dist     full-width, colour-coded by range (RNDZ_DIST thresholds)
   Row 1  V.Close  full-width — yellow when OPENING; white-on-red when closing fast and
                    already close (TGT_VCLOSURE_ALARM_MS gated on RNDZ_DIST_WARN_M)
   Row 2  Brg|Elv  split — bearing and elevation of the target from the NOSE
   Row 3  V.Brg|V.Elv split — approach-path error about the target axis, colour-coded
   Row 4  T+Int    full-width — estimated intercept time (dist / |vtgt|), closing only

   Alt.SL and V.Orb used to head this panel and are gone. Both were duplicated on this
   screen's partner -- TARGET is reached from three of the mission ladder's rules and
   SPACECRAFT is the vehicle panel in all of them -- and, unlike Dist and V.Close,
   neither related to anything on the scope. The scope is purely angular: it plots the
   bearing and elevation of the port and of the relative velocity vector, so range and
   closure are the two numbers it CANNOT show, which is what earns them their rows.
   Altitude above sea level and orbital speed are not about the target at all.
   Nothing replaces them: the closest-approach fields in AppState are KSP2-only stubs,
   and there is no relative inclination or phase angle in the telemetry. So the height
   goes to the five rows that are left, 76 px -> 106 px each.

   DOT UPDATE STRATEGY  (same as DOCK)
   ────────────────────
   prevDot stored in screen coords. On change > 1px:
     fillRect(prev - R_ERASE, ..., TFT_BLACK) → reticleRepairDotChrome() → draw new dot
   Erase rect is slightly larger than dot to clean up any anti-alias edge.
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// ── Chrome state ──────────────────────────────────────────────────────────────────────
bool _tgtChromDrawn = false;


// ── Scope geometry — same centre/radius as the MNVR and DOCK reticles ─────────────────
// The readout panel sits on the far right (x=580), leaving x=[0,578] for the
// scope. Centre and radius match MNVR/DOCK exactly for a consistent family look.
static const int16_t  TGT_SCX    = RETICLE_CX;   // centre of the left region x=[0,578]
static const int16_t  TGT_SCY    = RETICLE_CY;   // = MNVR/DOCK reticle centre y
static const int16_t  TGT_R      = RETICLE_R;    // = MNVR/DOCK reticle radius
static const float    TGT_SCALE  = (float)TGT_R / 60.0f;  // 3.5 px/deg — ±60° full scale

// Ring radii at ±15°, ±30°, ±45°, ±60°
static const uint16_t TGT_RING_15 = TGT_R / 4;        // 52
static const uint16_t TGT_RING_30 = TGT_R / 2;        // 105
static const uint16_t TGT_RING_45 = (TGT_R * 3) / 4;  // 157
static const uint16_t TGT_RING_60 = TGT_R;            // 210 — ±60° boundary

// Dot display sizes — scaled up with the larger scope
static const uint8_t TGT_DOT_R_TGT   = 22;  // target marker radius
static const uint8_t TGT_DOT_R_VEL   = 19;  // velocity marker radius
static const uint8_t TGT_DOT_R_ERASE = 33;  // erase rect half-size (covers prograde ring 19 + spoke 12)

// Right panel geometry — matches the ascent/circ readout panel (360 px wide,
// right-aligned to the content edge, labels Black_28, values Black_36).
static const uint16_t TGT_RP_W  = RETICLE_RP_W;
static const uint16_t TGT_RP_X  = CONTENT_W - TGT_RP_W;              // 580
static const uint8_t  TGT_RP_NR = 5;
static const tFont   *TGT_RP_LF = &Roboto_Black_28;  // label font (printDispChrome)
static const tFont   *TGT_RP_F  = &Roboto_Black_36;  // value font (printValue)

// Closure-velocity bar — centred under the scope (mirrors DOCK's approach bar so
// all three reticle screens share the reticle + bottom-bar layout).
static const uint16_t TGT_BAR_W      = RETICLE_BAR_W;
static const uint16_t TGT_BAR_X      = TGT_SCX - TGT_BAR_W / 2;   // 64
static const uint16_t TGT_BAR_H      = 26;
static const float    TGT_BAR_MAX_MS = 250.0f;   // full bar = 250 m/s closure
static float          _tgtPrevBarVC  = -9999.0f; // bar redraw cache (reset on entry)
static uint16_t       _tgtPrevBarCol = 0;        // and its colour, which range also drives


// ── Shared dot-layer geometry + per-screen erase cache ───────────────────────────────
// The moving marker layer is shared with MNVR/DOCK (reticleUpdateDots, KerbalDisplayCommon).
// Only the angular SCALE and the four ring labels differ; both are captured here. Built
// from the existing named constants above so values never diverge from the chrome/bar.
static const char *const TGT_RING_LBL[4] = { "15", "30", "45", "60" };
// Body-referenced, like every other boresight display in the project. TGT and DOCK are
// the same task at different ranges — they share a sidebar button, and the Dist row goes
// white-on-green below 200 m to say "switch to DOCK" — so a frame change between them
// would re-anchor every marker at exactly the moment the pilot crosses over.
static const ReticleGeom TGT_GEOM = {
    TGT_SCX, TGT_SCY, TGT_R, TGT_SCALE,
    TGT_DOT_R_TGT, TGT_DOT_R_VEL, TGT_DOT_R_ERASE,
    TGT_DOT_R_VEL * 3 / 2 + 2,      // clampMargin — widest symbol is the prograde ring + spoke
    TGT_RING_LBL, &Roboto_Black_16
};
// Per-screen erase-before-redraw cache (9999 = marker not shown). Reset on entry.
static ReticleDotCache _tgtDots;


// ── Draw static scope chrome ──────────────────────────────────────────────────────────
static void _tgtDrawScopeChrome(KCM_TFT &tft) {
    // Shared disc + rings + cardinals + crosshair + ticks + bezel (gap 18, tick 14
    // — same gap and tick length as MNVR/DOCK so the centre nose crosshair and
    // ticks are identical across all three reticle screens).
    reticleDrawBase(tft, TGT_SCX, TGT_SCY, TGT_R, 18, 14);

    // Ring degree labels — NE quadrant, just inside each ring.
    // Single-arg setTextColor = transparent background (no black rectangle under text).
    tft.setFont(Roboto_Black_16);
    tft.setTextColor(TFT_LIGHT_GREY);
    tft.setCursor(TGT_SCX + 3, TGT_SCY - TGT_RING_15 + 3);  tft.print("15");
    tft.setCursor(TGT_SCX + 3, TGT_SCY - TGT_RING_30 + 3);  tft.print("30");
    tft.setCursor(TGT_SCX + 3, TGT_SCY - TGT_RING_45 + 3);  tft.print("45");
    tft.setCursor(TGT_SCX + 3, TGT_SCY - TGT_RING_60 + 3);  tft.print("60");

    // Legend — top-left of scope area, above circle edge
    static const uint16_t LEG_X  = 6;
    static const uint16_t LEG_Y0 = TITLE_TOP + 6;
    static const uint16_t LEG_DY = 20;

    tft.setFont(Roboto_Black_16);

    // VEL — green prograde marker (target-RELATIVE velocity; the PFD ball uses the
    //       same glyph for orbital/surface velocity — context tells them apart,
    //       the legend names this one)
    drawProgradeMarker(tft, LEG_X + 6, LEG_Y0 + 6, 5, TFT_NEON_GREEN);
    tft.setTextColor(TFT_SAP_GREEN, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0);
    tft.print("VEL");

    // TGT — magenta target marker (same symbol as DOCK PORT dot)
    drawTargetMarker(tft, LEG_X + 6, LEG_Y0 + LEG_DY + 7, 6, TFT_VIOLET);
    tft.setTextColor(TFT_VIOLET, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0 + LEG_DY);
    tft.print("TGT");

    // NOSE — crosshair symbol matching the scope centre
    tft.drawLine(LEG_X+1,  LEG_Y0+LEG_DY*2+6,  LEG_X+4,  LEG_Y0+LEG_DY*2+6,  TFT_GREY);
    tft.drawLine(LEG_X+8,  LEG_Y0+LEG_DY*2+6,  LEG_X+11, LEG_Y0+LEG_DY*2+6,  TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+LEG_DY*2+1,  LEG_X+6,  LEG_Y0+LEG_DY*2+4,  TFT_GREY);
    tft.drawLine(LEG_X+6,  LEG_Y0+LEG_DY*2+8,  LEG_X+6,  LEG_Y0+LEG_DY*2+11, TFT_GREY);
    tft.fillCircle(LEG_X+6, LEG_Y0+LEG_DY*2+6, 1, TFT_GREY);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(LEG_X + 16, LEG_Y0 + LEG_DY * 2);
    tft.print("NOSE");

    // Closure bar chrome — label + empty bar, centred under the scope (Black_24,
    // same geometry math as the DOCK/MNVR bottom bars).
    uint16_t barY = TGT_SCY + TGT_R + 42;
    uint16_t lblY = barY - 34;
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(TFT_LIGHT_GREY, TFT_BLACK);
    tft.setCursor(TGT_BAR_X, lblY);
    tft.print("CLOSURE");
    tft.drawRect(TGT_BAR_X, barY, TGT_BAR_W, TGT_BAR_H, TFT_GREY);
}


// ── Closure-velocity bar (threshold-gated) ────────────────────────────────────────────
// Fill proportional to |closure| (full = TGT_BAR_MAX_MS); colour matches the V.Tgt row:
// green closing, yellow opening, white-on-red when closing too fast at short range.
static void _tgtDrawClosureBar(KCM_TFT &tft, float vc, float dist) {
    static const uint16_t barY = TGT_SCY + TGT_R + 42;
    static const uint16_t lblY = barY - 34;

    float    av      = fabsf(vc);
    bool     closing = (vc < 0.0f);
    bool     tooFast = (av > TGT_VCLOSURE_ALARM_MS && dist < RNDZ_DIST_WARN_M);
    uint16_t barCol  = tooFast ? TFT_RED : (!closing ? TFT_YELLOW : TFT_DARK_GREEN);
    // The colour depends on range as well as closure, so a range crossing at a steady
    // closure has to repaint too, or the bar and the V.CLOSE row disagree.
    if (fabsf(vc - _tgtPrevBarVC) < 0.5f && barCol == _tgtPrevBarCol) return;
    _tgtPrevBarVC  = vc;
    _tgtPrevBarCol = barCol;

    float    fraction = fminf(av / TGT_BAR_MAX_MS, 1.0f);
    uint16_t fillW    = (uint16_t)(fraction * (TGT_BAR_W - 2));
    tft.fillRect(TGT_BAR_X + 1, barY + 1, TGT_BAR_W - 2, TGT_BAR_H - 2, TFT_OFF_BLACK);
    if (fillW > 0)
        tft.fillRect(TGT_BAR_X + 1, barY + 1, fillW, TGT_BAR_H - 2, barCol);

    // Signed closure value, right-aligned on the label row.
    char buf[14];
    snprintf(buf, sizeof(buf), "%+.0fm/s", vc);
    tft.setFont(Roboto_Black_24);
    tft.setTextColor(barCol, TFT_BLACK);
    tft.fillRect(TGT_BAR_X + TGT_BAR_W / 2, lblY, TGT_BAR_W / 2, 30, TFT_BLACK);
    int16_t tw = getFontStringWidth(&Roboto_Black_24, buf);
    tft.setCursor(TGT_BAR_X + TGT_BAR_W - tw, lblY);
    tft.print(buf);
}


// Dot-layer machinery (project / clamp / erase / chrome-repair / update) lives in
// KerbalDisplayCommon ≥ 3.2.0 and is shared with MNVR and DOCK.
// TGT drives them via TGT_GEOM (scale = r/60, ring labels 15/30/45/60) and _tgtDots.


// ── CHROME ────────────────────────────────────────────────────────────────────────────
static void chromeScreen_TGT(KCM_TFT &tft) {
    if (!state.targetAvailable) {
        _tgtChromDrawn = false;
        tft.fillRect(0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP, TFT_BLACK);
        textCenter(tft, &Roboto_Black_72, 0, TITLE_TOP, CONTENT_W, SCREEN_H - TITLE_TOP,
                   "NO TARGET SET", TFT_WHITE, TFT_RED);
        return;
    }

    _tgtChromDrawn = true;

    // Reset dot positions — first draw must not try to erase stale coordinates
    _tgtDots = ReticleDotCache{};
    _tgtPrevBarVC  = -9999.0f;  // force the closure bar to redraw on entry
    _tgtPrevBarCol = 0;

    // Left panel: clear and draw scope chrome
    tft.fillRect(0, TITLE_TOP, TGT_RP_X, SCREEN_H - TITLE_TOP, TFT_BLACK);
    _tgtDrawScopeChrome(tft);

    // Panel divider
    tft.drawLine(TGT_RP_X - 2, TITLE_TOP, TGT_RP_X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(TGT_RP_X - 1, TITLE_TOP, TGT_RP_X - 1, SCREEN_H, TFT_GREY);

    // Right panel chrome — 5 rows
    const tFont *F   = TGT_RP_LF;   // label font for printDispChrome
    const uint8_t NR = TGT_RP_NR;
    uint16_t rowH    = rowHFor(NR);
    uint16_t HW      = TGT_RP_W / 2;

    // Rows 0–1: full-width labels
    printDispChrome(tft, F, TGT_RP_X, rowYFor(0,NR), TGT_RP_W, rowH, "DIST",   COL_LABEL, COL_BACK, COL_NO_BDR);
    printDispChrome(tft, F, TGT_RP_X, rowYFor(1,NR), TGT_RP_W, rowH, "V.CLOSE",  COL_LABEL, COL_BACK, COL_NO_BDR);

    // Row 2: Brg | Elv split
    {
        uint16_t y = rowYFor(2, NR), h = rowH;
        printDispChrome(tft, F, TGT_RP_X,        y, HW - ROW_PAD, h, "BRG", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, F, TGT_RP_X + HW,   y, HW - ROW_PAD, h, "ELV", COL_LABEL, COL_BACK, COL_NO_BDR);
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(TGT_RP_X + HW + dx, y, TGT_RP_X + HW + dx, y + h - 1, TFT_GREY);
    }

    // Row 3: V.Brg | V.Elv split (approach-path error about the target axis)
    {
        uint16_t y = rowYFor(3, NR), h = rowH;
        printDispChrome(tft, F, TGT_RP_X,        y, HW - ROW_PAD, h, "V.BRG", COL_LABEL, COL_BACK, COL_NO_BDR);
        printDispChrome(tft, F, TGT_RP_X + HW,   y, HW - ROW_PAD, h, "V.ELV", COL_LABEL, COL_BACK, COL_NO_BDR);
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(TGT_RP_X + HW + dx, y, TGT_RP_X + HW + dx, y + h - 1, TFT_GREY);
    }

    // Row 4: T+Int full-width
    printDispChrome(tft, F, TGT_RP_X, rowYFor(4,NR), TGT_RP_W, rowH, "T+INT", COL_LABEL, COL_BACK, COL_NO_BDR);

    // Horizontal dividers between rows 1/2 and 3/4 — the two angle pairs are set off
    // from the range/closure block above and the intercept time below.
    {
        uint16_t d1 = rowYFor(2,NR) - 1;
        tft.drawLine(TGT_RP_X, d1,   TGT_RP_X + TGT_RP_W, d1,   TFT_GREY);
        tft.drawLine(TGT_RP_X, d1+1, TGT_RP_X + TGT_RP_W, d1+1, TFT_GREY);
        uint16_t d2 = rowYFor(4,NR) - 1;
        tft.drawLine(TGT_RP_X, d2,   TGT_RP_X + TGT_RP_W, d2,   TFT_GREY);
        tft.drawLine(TGT_RP_X, d2+1, TGT_RP_X + TGT_RP_W, d2+1, TFT_GREY);
    }

    // Reset the print states — forces a full clear on the first value draw. (The row
    // cache itself is invalidated by drawStaticScreen() after this chrome.)
    for (uint8_t r = 0; r < ROW_COUNT; r++) printState[screen_TGT][r] = PrintState{};
}


// ── DRAW (called every loop) ──────────────────────────────────────────────────────────
static void drawScreen_TGT(KCM_TFT &tft) {

    // State transitions
    if (!state.targetAvailable) {
        if (_tgtChromDrawn) { _tgtChromDrawn = false; switchToScreen(screen_TGT); }
        return;
    }
    if (!_tgtChromDrawn) { switchToScreen(screen_TGT); return; }

    // ── Derived values ────────────────────────────────────────────────────────────────
    // Shared derived-angle block (identical to DOCK): nose→target, velocity→target and
    // both antipodal directions, bearings wrapped to ±180°.
    ReticleAngles ang = reticleComputeAngles();

    // ── Update scope dots ─────────────────────────────────────────────────────────────
    // Shared marker layer (KerbalDisplayCommon).
    reticleUpdateDots(tft, TGT_GEOM, _tgtDots, ang);

    // ── Right panel values ────────────────────────────────────────────────────────────
    const uint8_t NR = TGT_RP_NR;
    const uint16_t HW = TGT_RP_W / 2;
    uint16_t fg, bg;
    char buf[16];

    // Cache-checked draw helper — full-width right panel rows
    auto tgtVal = [&](uint8_t row, uint8_t slot, const char *label, const String &val,
                      uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, screen_TGT, slot, row, TGT_RP_X, TGT_RP_W, label, val, fgc, bgc, TGT_RP_F, NR, false);
    };

    // Cache-checked draw helper — half-width split rows, independent cache slots
    auto tgtValH = [&](uint8_t row, uint8_t slot, uint16_t x,
                       const char *label, const String &val,
                       uint16_t fgc, uint16_t bgc) {
        drawPanelValue(tft, screen_TGT, slot, row, x, HW - ROW_PAD, label, val, fgc, bgc, TGT_RP_F, NR, false);
    };

    // Row 0 — Dist  (cache slot 0)
    // White-on-green < DOCK_DIST_WARN_M: switch to DOCK screen.
    // Yellow < RNDZ_DIST_WARN_M: closing, pay attention.
    // Dark green otherwise: nominal long range.
    if      (state.tgtDistance < DOCK_DIST_WARN_M)  { fg = TFT_WHITE;      bg = TFT_DARK_GREEN; }
    else if (state.tgtDistance < RNDZ_DIST_WARN_M)  { fg = TFT_YELLOW;     bg = TFT_BLACK;      }
    else                                            { fg = TFT_DARK_GREEN; bg = TFT_BLACK;      }
    tgtVal(0, 0, "DIST", formatAlt(state.tgtDistance), fg, bg);

    // Row 1 — V.Close  (cache slot 1)
    // Speed of closure. Negative = closing (good), positive = opening (bad).
    // Two states, not three. Yellow means OPENING -- the range is growing, whatever the
    // speed. White-on-red means closing fast AND already close; the range gate is what
    // makes the alarm mean something, since 500 m/s of closure is routine at 40 km.
    // There is no "moderate closure" tier: on a rendezvous that is the whole approach.
    {
        float vc  = state.tgtVelocity;
        float avc = fabsf(vc);
        bool closing = (vc < 0.0f);
        bool tooFast = (avc > TGT_VCLOSURE_ALARM_MS &&
                        state.tgtDistance < RNDZ_DIST_WARN_M);
        if (tooFast)       { fg = TFT_WHITE;  bg = TFT_RED;   }
        else if (!closing) { fg = TFT_YELLOW; bg = TFT_BLACK; }
        else               { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
        tgtVal(1, 1, "V.CLOSE", fmtMs(vc), fg, bg);
    }

    // Row 2 — Brg | Elv  (cache slots 2, 3)
    // Where the target sits relative to the NOSE — the same quantity MNVR's Brg/Elv
    // shows, and literally where the violet TGT marker is on the scope. This used to
    // print state.tgtHeading wrapped to +/-180 under a comment claiming "positive =
    // target to the right", which was the vessel's compass bearing: with the target dead
    // ahead on heading 120 it read +120, not 0.
    {
        snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.priRight);
        tgtValH(2, 2, TGT_RP_X, "BRG", String(buf), TFT_DARK_GREEN, TFT_BLACK);

        snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.priUp);
        tgtValH(2, 3, TGT_RP_X + HW, "ELV", String(buf), TFT_DARK_GREEN, TFT_BLACK);
    }

    // Row 3 — V.Brg | V.Elv  (cache slots 4, 5)
    // Approach-path error about the TARGET axis: how far right and above the approach
    // path the relative velocity actually points. Same quantity DOCK shows under the
    // same labels. Colour bands are the scope rings (green inside 15 deg, yellow to
    // 30 deg, red beyond).
    auto errColor = [](float ae, uint16_t &fg, uint16_t &bg) {
        if      (ae >= TGT_BRG_ALARM_DEG) { fg = TFT_WHITE;      bg = TFT_RED;   }
        else if (ae >= TGT_BRG_WARN_DEG)  { fg = TFT_YELLOW;     bg = TFT_BLACK; }
        else                               { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    };
    {
        // Past 90 deg the craft is travelling away from the target and the signed pair
        // stops being flyable, so both cells show "---" (the idiom T+Int already uses
        // when not closing). It also keeps the value inside the half-width cell.
        bool appValid = (sqrtf(ang.appRight*ang.appRight + ang.appUp*ang.appUp) <= 90.0f);
        if (!appValid) {
            tgtValH(3, 4, TGT_RP_X,      "V.BRG", "---", TFT_DARK_GREY, TFT_BLACK);
            tgtValH(3, 5, TGT_RP_X + HW, "V.ELV", "---", TFT_DARK_GREY, TFT_BLACK);
        } else {
            errColor(fabsf(ang.appRight), fg, bg);
            snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.appRight);
            tgtValH(3, 4, TGT_RP_X, "V.BRG", String(buf), fg, bg);

            errColor(fabsf(ang.appUp), fg, bg);
            snprintf(buf, sizeof(buf), "%+.0f\xB0", ang.appUp);
            tgtValH(3, 5, TGT_RP_X + HW, "V.ELV", String(buf), fg, bg);
        }
    }

    // Row 4 — T+Int  (cache slot 6)
    // Estimated intercept time = distance / |closure rate|.
    // Only meaningful when closing; shows "---" otherwise.
    {
        bool closing = (state.tgtVelocity < -0.5f);
        String tIntStr;
        if (closing) {
            float t = state.tgtDistance / fabsf(state.tgtVelocity);
            tIntStr = formatTimeCompact((int64_t)t);
            fg = TFT_DARK_GREEN; bg = TFT_BLACK;
        } else {
            tIntStr = "---";
            fg = TFT_DARK_GREY; bg = TFT_BLACK;
        }
        tgtVal(4, 6, "T+INT", tIntStr, fg, bg);
    }

    // ── Closure-velocity bar (left panel, under the scope) ───────────────────────────
    _tgtDrawClosureBar(tft, state.tgtVelocity, state.tgtDistance);

    // ── Redraw dividers — printValue fillRect can overwrite them ─────────────────────
    {
        uint16_t d0 = rowYFor(2,NR) - 1;  // V.Close → Brg|Elv
        tft.drawLine(TGT_RP_X, d0,   TGT_RP_X + TGT_RP_W, d0,   TFT_GREY);
        tft.drawLine(TGT_RP_X, d0+1, TGT_RP_X + TGT_RP_W, d0+1, TFT_GREY);
        uint16_t d1 = rowYFor(4,NR) - 1;  // V.Brg|V.Elv → T+Int
        tft.drawLine(TGT_RP_X, d1,   TGT_RP_X + TGT_RP_W, d1,   TFT_GREY);
        tft.drawLine(TGT_RP_X, d1+1, TGT_RP_X + TGT_RP_W, d1+1, TFT_GREY);
    }
    // Split-row vertical dividers (rows 2 and 3 are the split rows; the loop used to
    // run over the old seven-row layout's 4..5 and put a line through T+INT)
    for (uint8_t row = 2; row <= 3; row++) {
        uint16_t y = rowYFor(row, NR), h = rowHFor(NR);
        for (int8_t dx = -1; dx <= 1; dx++)
            tft.drawLine(TGT_RP_X + HW + dx, y, TGT_RP_X + HW + dx, y + h - 1, TFT_GREY);
    }
    // Panel left border
    tft.drawLine(TGT_RP_X - 2, TITLE_TOP, TGT_RP_X - 2, SCREEN_H, TFT_GREY);
    tft.drawLine(TGT_RP_X - 1, TITLE_TOP, TGT_RP_X - 1, SCREEN_H, TFT_GREY);
}


// (A block of "AAA_Config.ino additions required" migration notes lived here: the
// screen_RNDZ -> screen_TGT rename and the constants it needed. The rename shipped long
// ago and the constants it listed no longer match the ones in use -- it quoted the
// pre-1.0.5 bearing thresholds of 5/15 deg, which are now 15/30. Removed: a checklist
// for a finished job is only a source of wrong numbers.)

/***************************************************************************************
   Screen_VEH.ino -- Vehicle Info screen — chromeScreen_VEH, drawScreen_VEH
****************************************************************************************/
#include "KCMk1_InfoDisp.h"

// Vessel-type icon (Type row) — cached so the 60x60 BMP is only re-read from SD
// when the type actually changes (SD reads are slow). Reset on screen entry by
// chromeScreen_VEH so the icon repaints when the screen is re-shown.
static VesselType _vehPrevIconType = (VesselType)0xFF;


static void chromeScreen_VEH(KCM_TFT &tft) {
  _vehPrevIconType = (VesselType)0xFF;   // force the type icon to redraw on entry
  static const tFont   *F      = &Roboto_Black_48;
  static const uint8_t  NR     = 8;
  static const uint16_t SECT_W = 26;
  static const uint16_t AX     = ROW_PAD + SECT_W;
  static const uint16_t AW     = CONTENT_W - AX - ROW_PAD;
  uint16_t rowH = rowHFor(NR);

  // Section labels: INFO(rows0-2), CREW(rows3-5), PROP(rows6-7)
  drawVerticalText(tft, 0, TITLE_TOP,          SECT_W, rowH*3, &Roboto_Black_16, "INFO", TFT_LIGHT_GREY, TFT_BLACK);
  drawVerticalText(tft, 0, TITLE_TOP + rowH*3, SECT_W, rowH*3, &Roboto_Black_16, "CREW", TFT_LIGHT_GREY, TFT_BLACK);
  drawVerticalText(tft, 0, TITLE_TOP + rowH*6, SECT_W, rowH*2, &Roboto_Black_16, "PROP", TFT_LIGHT_GREY, TFT_BLACK);

  // Row labels (right of section strip)
  printDispChrome(tft, F, AX, rowYFor(0,NR), AW, rowH, "VESSEL",    COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, F, AX, rowYFor(1,NR), AW, rowH, "TYPE",    COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, F, AX, rowYFor(2,NR), AW, rowH, "STATUS",  COL_LABEL, COL_BACK, COL_NO_BDR);

  printDispChrome(tft, F, AX, rowYFor(3,NR), AW, rowH, "CONTROL",          COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, F, AX, rowYFor(4,NR), AW, rowH, "COMM",           COL_LABEL, COL_BACK, COL_NO_BDR);

  printDispChrome(tft, F, AX, rowYFor(5,NR), AW, rowH, "CREW", COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, F, AX, rowYFor(6,NR), AW, rowH, "\xCE\x94V.STG", COL_LABEL, COL_BACK, COL_NO_BDR);
  printDispChrome(tft, F, AX, rowYFor(7,NR), AW, rowH, "\xCE\x94V.TOT", COL_LABEL, COL_BACK, COL_NO_BDR);

  // Dividers — drawn LAST, +1 offset to clear printValue fillRect boundary
  uint16_t d1 = TITLE_TOP + rowH*3 + 1;  // after Status  (row2/row3)
  uint16_t d2 = TITLE_TOP + rowH*6 + 1;  // after Crew    (row5/row6)
  tft.drawLine(0, d1,   CONTENT_W, d1,   TFT_GREY);
  tft.drawLine(0, d1+1, CONTENT_W, d1+1, TFT_GREY);
  tft.drawLine(0, d2,   CONTENT_W, d2,   TFT_GREY);
  tft.drawLine(0, d2+1, CONTENT_W, d2+1, TFT_GREY);
}


static void drawScreen_VEH(KCM_TFT &tft) {
  static const tFont   *F      = &Roboto_Black_48;
  static const uint8_t  NR     = 8;
  static const uint16_t SECT_W = 26;
  static const uint16_t AX     = ROW_PAD + SECT_W;
  static const uint16_t AW     = CONTENT_W - AX - ROW_PAD;
  uint16_t fg, bg;

  // Cache-checked draw helper using section-label-aware geometry
  // vehVal -> drawValue() split overload with AX/AW section geometry (#6B)
  auto vehVal = [&](uint8_t row, const char *label, const String &val,
                    uint16_t fgc, uint16_t bgc) {
    drawValue(tft, (uint8_t)screen_VEH, row, AX, AW, label, val, fgc, bgc, F, NR);
  };

  // ── INFO block (rows 0-2): identity ──

  // Row 0 — Vessel name
  vehVal(0, "VESSEL", state.vesselName, COL_VALUE, COL_BACK);

  // Row 1 — Vessel type with colour coding
  const char *typeName;
  uint16_t typeColor;
  switch (state.vesselType) {
    case type_Ship:     typeName = "Ship";      typeColor = TFT_DARK_GREEN; break;
    case type_Probe:    typeName = "Probe";     typeColor = TFT_MAGENTA;    break;
    case type_Relay:    typeName = "Relay";     typeColor = TFT_VIOLET;     break;
    case type_Rover:    typeName = "Rover";     typeColor = TFT_OLIVE;      break;
    case type_Lander:   typeName = "Lander";    typeColor = TFT_NAVY;       break;
    case type_Plane:    typeName = "Plane";     typeColor = TFT_SKY;        break;
    case type_Station:  typeName = "Station";   typeColor = TFT_MAROON;     break;
    case type_Base:     typeName = "Base";      typeColor = TFT_BROWN;      break;
    case type_EVA:      typeName = "EVA";       typeColor = TFT_JUNGLE;     break;
    case type_Debris:   typeName = "Debris";    typeColor = TFT_CORNELL;    break;
    case type_Object:   typeName = "Object";    typeColor = TFT_CORNELL;    break;
    case type_Unknown:  typeName = "Unknown";   typeColor = TFT_CORNELL;    break;
    case type_Flag:     typeName = "Flag";      typeColor = TFT_CORNELL;    break;
    case type_SciCtrlr: typeName = "Sci Ctrlr"; typeColor = TFT_CORNELL;   break;
    case type_SciPart:  typeName = "Sci Part";  typeColor = TFT_CORNELL;    break;
    case type_Part:     typeName = "Part";      typeColor = TFT_CORNELL;    break;
    case type_GndPart:  typeName = "Gnd Part";  typeColor = TFT_CORNELL;    break;
    default:            typeName = "---";       typeColor = TFT_DARK_GREY;  break;
  }
  // Draw the type name in a narrowed cell and the 60x60 vessel-type icon at the
  // row's right edge — the same icons the Annunciator uses, downscaled to
  // VIcon60_NN.bmp (NN = vesselType).
  static const uint16_t TICON_W   = 60;
  static const uint16_t TICON_GAP = 14;
  const uint16_t TICON_X = AX + AW - TICON_W - 8;                 // right edge = value text margin
  const uint16_t TICON_Y = rowYFor(1, NR) + (rowHFor(NR) - TICON_W) / 2;
  const uint16_t AW_TYPE = (uint16_t)(TICON_X - TICON_GAP - AX + 8);  // cell stops short of the icon
  drawValue(tft, (uint8_t)screen_VEH, 1, AX, AW_TYPE, "TYPE", typeName, typeColor, TFT_BLACK, F, NR);

  // The icon is re-read from SD only when the type changes (SD reads are slow);
  // between changes it rides along in the double-buffer's page copy.
  if (state.vesselType != _vehPrevIconType) {
    _vehPrevIconType = state.vesselType;
    tft.fillRect(TICON_X, TICON_Y, TICON_W, TICON_W, TFT_BLACK);
    if (state.vesselType <= type_GndPart) {
      char iconPath[24];
      snprintf(iconPath, sizeof(iconPath), "/VIcon60_%02u.bmp", (unsigned)state.vesselType);
      drawBMP(tft, iconPath, TICON_X, TICON_Y);
    }
  }

  // Row 2 — Flight status: the situation, and whether the vessel can be recovered.
  //
  // Both, not one or the other. Recoverable used to REPLACE the situation, which threw
  // away the more informative half exactly when it mattered: KSP reports a vessel on the
  // pad as recoverable -- the same quirk vehicleContextScreen() has to shield against --
  // so the pre-launch board's own summary read "RECOVERABLE" instead of "PRE-LAUNCH".
  // Splashed lost to it too, and being in the water is worth knowing before you press
  // recover. The row is 749 px wide against a worst case of 689, so there was never a
  // reason to choose.
  const char *condName;
  switch (state.situation) {
    case sit_PreLaunch: condName = "PRE-LAUNCH";   break;
    case sit_Flying:    condName = "IN FLIGHT";    break;
    case sit_SubOrb:    condName = "SUB-ORBITAL";  break;
    case sit_Orbit:     condName = "IN ORBIT";     break;
    case sit_Escaping:  condName = "ESCAPE ORBIT"; break;
    case sit_Landed:    condName = "LANDED";       break;
    case sit_Splashed:  condName = "SPLASHED";     break;
    case sit_Docked:    condName = "DOCKED";       break;
    default:            condName = "---";          break;
  }
  // Sky blue when recoverable, since that is the actionable state; otherwise nominal.
  // Separated by a middle dot (0xB7). That glyph was missing from every Roboto_Black
  // size until fonts_ili/add_middot.py added it -- 0xB7 sat two codepoints past
  // index2_last -- and a missing glyph measures zero and draws nothing, so this row
  // would have read "LANDED  RECOVERABLE" with an unexplained gap rather than failing.
  const String statusVal = state.isRecoverable
                             ? String(condName) + " \xB7 RECOVERABLE"
                             : String(condName);
  vehVal(2, "STATUS", statusVal,
         state.isRecoverable ? (uint16_t)TFT_SKY : (uint16_t)TFT_DARK_GREEN, TFT_BLACK);

  // ── CREW block (rows 3-5): crew, control, comms ──

  // Row 3 — Control level
  const char *ctrlName;
  uint16_t ctrlColor;
  switch (state.ctrlLevel) {
    case 0:  ctrlName = "No Control";     ctrlColor = TFT_WHITE;       bg = TFT_RED;   break;
    case 1:  ctrlName = "Limited Probe";  ctrlColor = TFT_INT_ORANGE;  bg = TFT_BLACK; break;
    case 2:  ctrlName = "Limited Manned"; ctrlColor = TFT_DULL_YELLOW; bg = TFT_BLACK; break;
    default: ctrlName = "Full Control";   ctrlColor = TFT_DARK_GREEN;  bg = TFT_BLACK; break;
  }
  vehVal(3, "CONTROL", ctrlName, ctrlColor, bg);

  // Row 4 — CommNet signal: white-on-red 0%, yellow <50%, green
  {
    uint8_t sig = state.commNetSignal;
    char sigStr[8];
    snprintf(sigStr, sizeof(sigStr), "%d%%", sig);
    if      (sig == 0) { fg = TFT_WHITE;     bg = TFT_RED;   }
    else if (sig < VEH_SIGNAL_WARN_PCT) { fg = TFT_YELLOW;    bg = TFT_BLACK; }
    else               { fg = TFT_DARK_GREEN; bg = TFT_BLACK; }
    vehVal(4, "COMM", sigStr, fg, bg);
  }

  // Row 5 — Crew count / capacity
  {
    char crewStr[12];
    snprintf(crewStr, sizeof(crewStr), "%d / %d", state.crewCount, state.crewCapacity);
    vehVal(5, "CREW", crewStr, COL_VALUE, COL_BACK);
  }

  // ── PROP block (rows 6-7): delta-V ──

  // When stage ΔV equals total ΔV the vessel is on its last stage — use the same
  // (higher, DV_TOT_WARN_MS) threshold for both so colours are always consistent.
  bool lastStage = (state.stageDeltaV >= state.totalDeltaV * 0.999f);
  float stgWarn  = lastStage ? DV_TOT_WARN_MS : DV_STG_WARN_MS;

  // Row 6 — Stage ΔV
  thresholdColor(state.stageDeltaV,
                 DV_STG_ALARM_MS, TFT_WHITE,  TFT_RED,
                 stgWarn, TFT_YELLOW, TFT_BLACK,
                      TFT_DARK_GREEN, TFT_BLACK, fg, bg);
  vehVal(6, "\xCE\x94V.STG", fmtMs(state.stageDeltaV), fg, bg);

  // Row 7 — Total ΔV: uses DV_TOT_WARN_MS (higher threshold than stage) since this
  // represents whole-mission reserve. Shown on its own row so different colouring is clear.
  thresholdColor(state.totalDeltaV,
                 DV_STG_ALARM_MS, TFT_WHITE,  TFT_RED,
                 DV_TOT_WARN_MS,  TFT_YELLOW, TFT_BLACK,
                      TFT_DARK_GREEN, TFT_BLACK, fg, bg);
  vehVal(7, "\xCE\x94V.TOT", fmtMs(state.totalDeltaV), fg, bg);
}

/***************************************************************************************
   SimpitHandler.ino -- KerbalSimpit message handling for Kerbal Controller Mk1 InfoDisp

   Channels subscribed:
     VESSEL_NAME, SOI, FLIGHT_STATUS, ALTITUDE, VELOCITY, AIRSPEED,
     APSIDES, APSIDESTIME, DELTAV, BURNTIME, ORBIT, ROTATION_DATA,
     MANEUVER, TARGETINFO, ATMO_CONDITIONS, ACTIONSTATUS, TEMP_LIMIT,
     CAGSTATUS, SAS_MODE_INFO, THROTTLE_CMD, WHEEL_CMD, ELECTRIC,
     SCENE_CHANGE, VESSEL_CHANGE
     (INTERSECTS is KSP2-only and intentionally not registered.)

   Phase 2: Simpit integration for live KSP telemetry. ✓
   Phase 3: I2C slave interface. ✓
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


// KerbalSimpit simpit object moved to AAA_Globals.ino (#9)


/***************************************************************************************
   SIMPIT MESSAGE HANDLER
   Called by simpit.update() on every subscribed message arrival.
   Populates state fields only — never draws directly. May call switchToScreen()
   on SCENE_CHANGE_MESSAGE and VESSEL_CHANGE_MESSAGE events.
****************************************************************************************/
/***************************************************************************************
   FLIGHT-SCENE ENTRY
   Shared by the explicit SCENE_CHANGE and by the inference in FLIGHT_STATUS below, so
   the two routes into a flight scene cannot drift apart.
****************************************************************************************/
static void enterFlightScene() {
  flightScene = true;
  demoMode    = false;
  // Entering a flight scene is a fresh start — release any held manual pick so the
  // panel opens on its context screen rather than wherever it was parked.
  clearManualScreenLatch();
  resetContextRouting();      // ladder history + press dwell belong to the old scene
  // Same for the reference overrides on the two attitude screens: a pinned SRF/ORB or
  // SL/RDR belongs to the flight it was pinned in.
  modeClearOverride(_scftVelRefOverride);
  modeClearOverride(_acftAltRefOverride);
  _lnchManualOverride = false;   // and the LAUNCH screen's ASC/CIRC phase override
  if (contextSwitchAllowed()) switchToScreen(contextScreen());
  simpit.requestMessageOnChannel(0);
}


void onSimpitMessage(byte messageType, byte msg[], byte msgSize) {

  if (debugMode) {
    const char *n;
    switch (messageType) {
      case VESSEL_NAME_MESSAGE:     n = "VESSEL_NAME";     break;
      case SOI_MESSAGE:             n = "SOI";             break;
      case FLIGHT_STATUS_MESSAGE:   n = "FLIGHT_STATUS";   break;
      case ALTITUDE_MESSAGE:        n = "ALTITUDE";        break;
      case VELOCITY_MESSAGE:        n = "VELOCITY";        break;
      case AIRSPEED_MESSAGE:        n = "AIRSPEED";        break;
      case APSIDES_MESSAGE:         n = "APSIDES";         break;
      case APSIDESTIME_MESSAGE:     n = "APSIDESTIME";     break;
      case DELTAV_MESSAGE:          n = "DELTAV";          break;
      case BURNTIME_MESSAGE:        n = "BURNTIME";        break;
      case ORBIT_MESSAGE:           n = "ORBIT";           break;
      case ROTATION_DATA_MESSAGE:   n = "ROTATION_DATA";   break;
      case MANEUVER_MESSAGE:        n = "MANEUVER";        break;
      case TARGETINFO_MESSAGE:      n = "TARGETINFO";      break;
      case INTERSECTS_MESSAGE:      n = "INTERSECTS";      break;
      case ATMO_CONDITIONS_MESSAGE: n = "ATMO_CONDITIONS"; break;
      case ACTIONSTATUS_MESSAGE:    n = "ACTION_STATUS";   break;
      case SAS_MODE_INFO_MESSAGE:   n = "SAS_MODE_INFO";   break;
      case CAGSTATUS_MESSAGE:       n = "CAG_STATUS";      break;
      case THROTTLE_CMD_MESSAGE:    n = "THROTTLE_CMD";    break;
      case WHEEL_CMD_MESSAGE:        n = "WHEEL_CMD";        break;
      case ELECTRIC_MESSAGE:        n = "ELECTRIC";        break;
      case TEMP_LIMIT_MESSAGE:      n = "TEMP_LIMIT";      break;
      case SCENE_CHANGE_MESSAGE:    n = "SCENE_CHANGE";    break;
      case VESSEL_CHANGE_MESSAGE:   n = "VESSEL_CHANGE";   break;
      default:                      n = "UNKNOWN";         break;
    }
    Serial.print(F("InfoDisp: Simpit msg="));
    Serial.println(n);
  }

  switch (messageType) {

    // ── Vessel identity ──────────────────────────────────────────────────────────────

    case VESSEL_NAME_MESSAGE:
      state.vesselName = "";
      for (uint8_t i = 0; i < msgSize; i++) state.vesselName += char(msg[i]);
      break;

    case SOI_MESSAGE:
      {
        String newSOI = "";
        for (uint8_t i = 0; i < msgSize; i++) newSOI += char(msg[i]);
        if (newSOI != state.gameSOI) {
          state.gameSOI = newSOI;
          currentBody = getBodyParams(state.gameSOI);
          // The ORB chrome draws the body itself, so repaint it when the body changes.
          if (activeScreen == screen_ORB) switchToScreen(screen_ORB);
        }
      }
      break;

    case FLIGHT_STATUS_MESSAGE:
      if (msgSize == sizeof(flightStatusMessage)) {
        flightStatusMessage fs = parseMessage<flightStatusMessage>(msg);
        state.situation     = (VesselSituation)fs.vesselSituation;
        state.vesselType    = (VesselType)fs.vesselType;
        state.crewCount     = fs.crewCount;
        state.crewCapacity  = fs.crewCapacity;
        state.ctrlLevel     = fs.getControlLevel();
        state.commNetSignal = fs.commNetSignalStrenghPercentage;
        state.isRecoverable = fs.isRecoverable();
        state.targetAvailable = fs.hasTarget();
        // state.inAtmo populated by ATMO_CONDITIONS_MESSAGE
        // state.sasMode — no field in KerbalSimpit 2.4.0 flightStatusMessage

        // Simpit sends FLIGHT_STATUS only from a flight scene, so receiving it while
        // we believe we are not in one means the SCENE_CHANGE that would have told us
        // never arrived. That is the normal case when a panel boots into a flight
        // already in progress — SCENE_CHANGE is an event, not a state you can ask for,
        // so a display powered up (or USB re-enumerated) mid-flight would otherwise sit
        // on the standby splash until the pilot happened to change scene or vessel.
        // Adopting it here rather than on an earlier channel is deliberate: this
        // message's vessel data is applied just above, so the context ladder routes on
        // the real vessel instead of on default state.
        if (!flightScene) {
          if (debugMode) Serial.println(F("InfoDisp: flight scene inferred from FLIGHT_STATUS"));
          enterFlightScene();
        }

        // If a vessel switch is pending, now we have the correct vesselType — switch screens
        if (_pendingContextSwitch) {
          _pendingContextSwitch = false;
          if (debugMode) {
            Serial.print(F("InfoDisp: VesselSwitch FLIGHT_STATUS - type="));
            Serial.print((int)state.vesselType);
            Serial.print(F(" tgtAvail="));
            Serial.print(state.targetAvailable);
            Serial.print(F(" tgtDist="));
            Serial.println(state.tgtDistance);
          }
          // A held manual pick and self-pinning screens (RE-ENTRY) stay put — don't
          // let an auto route steal them.
          if (contextSwitchAllowed()) switchToScreen(contextScreen());
          // TARGETINFO may not have arrived yet — set flag to re-check for docking context
          // once target distance is known (catches switching to a vessel near a dock target)
          _pendingDockCheck = true;
        }

        // Pre-launch board. The plane/rover exclusion this used to carry existed only
        // because vessel-type routing sat above the pre-launch rule on a single
        // display: a spaceplane on the pad went to ACFT, so arming the board would
        // have set a mode for a screen the pilot could not see. The two ladders no
        // longer compete — pre-launch is a phase, answered on the mission panel — so
        // the board is armed for every vessel type on the pad, spaceplanes included.
        bool isPreLaunch = (state.situation & sit_PreLaunch) != 0;
        if (isPreLaunch && !_lnchPrelaunchMode && !_lnchPrelaunchDismissed) {
          _lnchPrelaunchMode = true;
          if (activeScreen == screen_LNCH) switchToScreen(screen_LNCH);
        } else if (!isPreLaunch && _lnchPrelaunchMode) {
          // Launched — clear everything including dismissed flag
          _lnchPrelaunchMode      = false;
          _lnchPrelaunchDismissed = false;
          _lnchOrbitalMode        = false;
          _lnchCoastLatched       = false;
          _lnchManualOverride     = false;
          if (activeScreen == screen_LNCH) switchToScreen(screen_LNCH);
        } else if (!isPreLaunch) {
          // No longer pre-launch for any reason — clear dismissed flag for next time on pad
          _lnchPrelaunchDismissed = false;
        }
      }
      break;

    // ── Altitude & velocity ──────────────────────────────────────────────────────────

    case ALTITUDE_MESSAGE:
      if (msgSize == sizeof(altitudeMessage)) {
        altitudeMessage a = parseMessage<altitudeMessage>(msg);
        state.altitude  = a.sealevel;
        state.radarAlt  = a.surface;
      }
      break;

    case VELOCITY_MESSAGE:
      if (msgSize == sizeof(velocityMessage)) {
        velocityMessage v = parseMessage<velocityMessage>(msg);
        state.orbitalVel  = v.orbital;
        state.surfaceVel  = v.surface;
        state.verticalVel = v.vertical;
      }
      break;

    case AIRSPEED_MESSAGE:
      if (msgSize == sizeof(airspeedMessage)) {
        airspeedMessage a = parseMessage<airspeedMessage>(msg);
        state.IAS        = a.IAS;
        state.machNumber = a.mach;
        state.gForce     = a.gForces;
      }
      break;

    // ── Apsides ──────────────────────────────────────────────────────────────────────

    case APSIDES_MESSAGE:
      if (msgSize == sizeof(apsidesMessage)) {
        apsidesMessage a = parseMessage<apsidesMessage>(msg);
        state.apoapsis  = a.apoapsis;
        state.periapsis = a.periapsis;
      }
      break;

    case APSIDESTIME_MESSAGE:
      if (msgSize == sizeof(apsidesTimeMessage)) {
        apsidesTimeMessage a = parseMessage<apsidesTimeMessage>(msg);
        state.timeToAp = (float)a.apoapsis;
        state.timeToPe = (float)a.periapsis;
      }
      break;

    // ── Delta-V & burn ───────────────────────────────────────────────────────────────

    case DELTAV_MESSAGE:
      if (msgSize == sizeof(deltaVMessage)) {
        deltaVMessage dv = parseMessage<deltaVMessage>(msg);
        state.stageDeltaV = dv.stageDeltaV;
        state.totalDeltaV = dv.totalDeltaV;
      }
      break;

    case BURNTIME_MESSAGE:
      if (msgSize == sizeof(burnTimeMessage)) {
        burnTimeMessage b = parseMessage<burnTimeMessage>(msg);
        state.stageBurnTime = b.stageBurnTime;
      }
      break;

    case THROTTLE_CMD_MESSAGE:
      if (msgSize == sizeof(throttleMessage)) {
        throttleMessage t = parseMessage<throttleMessage>(msg);
        // Simpit throttle is 0..INT16_MAX; normalise to 0.0..1.0
        state.throttle = (float)t.throttle / (float)INT16_MAX;
      }
      break;

    case WHEEL_CMD_MESSAGE:
      // Outbound telemetry echo of combined wheel input (keyboard + Simpit).
      // wheelMessage struct: int16_t steering, int16_t throttle, uint8_t mask.
      // Note: WHEEL_THROTTLE_MASK is not defined in KerbalSimpit 2.4.0 — read directly.
      // Throttle is signed int16; clamp to 0.0..1.0 (negative = braking/reverse).
      if (msgSize == sizeof(wheelMessage)) {
        wheelMessage w = parseMessage<wheelMessage>(msg);
        // Store signed value: positive = forward, negative = reverse/braking.
        // Range is -1.0..1.0 (INT16_MIN..INT16_MAX scaled).
        state.wheelThrottle = (float)w.throttle / (float)INT16_MAX;
      }
      break;

    case ELECTRIC_MESSAGE:
      // resourceMessage struct: float total, float available
      if (msgSize == sizeof(resourceMessage)) {
        resourceMessage r = parseMessage<resourceMessage>(msg);
        if (r.total > 0.0f)
          state.electricChargePercent = (r.available / r.total) * 100.0f;
        else
          state.electricChargePercent = 0.0f;
      }
      break;

    case TEMP_LIMIT_MESSAGE:
      // tempLimitMessage: byte tempLimitPercentage (internal/core), byte skinTempLimitPercentage.
      // Both are the vessel's hottest part as a % of its temperature limit (0-100).
      if (msgSize == sizeof(tempLimitMessage)) {
        tempLimitMessage t = parseMessage<tempLimitMessage>(msg);
        state.coreTempPct = t.tempLimitPercentage;
        state.skinTempPct = t.skinTempLimitPercentage;
      }
      break;

    // ── Orbital elements ─────────────────────────────────────────────────────────────

    case ORBIT_MESSAGE:
      if (msgSize == sizeof(orbitInfoMessage)) {
        orbitInfoMessage o = parseMessage<orbitInfoMessage>(msg);
        state.eccentricity  = o.eccentricity;
        state.semiMajorAxis = o.semiMajorAxis;
        state.inclination   = o.inclination;
        state.LAN           = o.longAscendingNode;
        state.argOfPe       = o.argPeriapsis;
        state.trueAnomaly   = o.trueAnomaly;
        state.meanAnomaly   = o.meanAnomaly;
        state.orbitalPeriod = o.period;
      }
      break;

    // ── Attitude ─────────────────────────────────────────────────────────────────────

    case ROTATION_DATA_MESSAGE:
      if (msgSize == sizeof(vesselPointingMessage)) {
        vesselPointingMessage r = parseMessage<vesselPointingMessage>(msg);
        state.heading       = r.heading;
        state.pitch         = r.pitch;
        state.roll          = r.roll;
        state.orbVelHeading = r.orbitalVelocityHeading;
        state.orbVelPitch   = r.orbitalVelocityPitch;
        state.srfVelHeading = r.surfaceVelocityHeading;
        state.srfVelPitch   = r.surfaceVelocityPitch;
      }
      break;

    // ── Maneuver node ────────────────────────────────────────────────────────────────

    case MANEUVER_MESSAGE:
      if (msgSize == sizeof(maneuverMessage)) {
        maneuverMessage m = parseMessage<maneuverMessage>(msg);
        state.mnvrTime     = m.timeToNextManeuver;
        state.mnvrDeltaV   = m.deltaVNextManeuver;
        state.mnvrDuration = m.durationNextManeuver;
        // m.deltaVTotal is the dV remaining in the maneuver PLAN (all nodes),
        // distinct from the vessel's total propellant dV (owned by DELTAV_MESSAGE).
        state.mnvrTotalDeltaV = m.deltaVTotal;
        state.mnvrHeading  = m.headingNextManeuver;
        state.mnvrPitch    = m.pitchNextManeuver;
      }
      break;

    // ── Target ───────────────────────────────────────────────────────────────────────

    case TARGETINFO_MESSAGE:
      if (msgSize == sizeof(targetMessage)) {
        targetMessage t = parseMessage<targetMessage>(msg);
        state.tgtDistance   = t.distance;
        state.tgtHeading    = t.heading;
        state.tgtPitch      = t.pitch;
        state.tgtVelHeading = t.velocityHeading;
        state.tgtVelPitch   = t.velocityPitch;

        // Closure rate, signed: negative = closing. Simpit does NOT send a signed
        // value -- KerbalSimpitRevamped's TargetInfo.cs sets
        //     myTargetInfo.velocity = FlightGlobals.ship_tgtVelocity.magnitude;
        // which is never negative. Taking it as signed left every consumer's
        // "closing" test false forever: T+INT (NAV), T+Int (TARGET) and T+Dock
        // (DOCKING) all read "---" permanently, and V.Close on TARGET and DOCKING
        // could never reach nominal green. Demo mode hid it, because Demo.ino writes
        // state.tgtVelocity directly with a signed sine and never comes through here.
        //
        // The magnitude is the speed along the whole relative velocity vector, so it
        // also overstates closure whenever the craft is not heading straight at the
        // target. Both directions arrive as navball heading/pitch pairs from the same
        // Simpit encoder, so projecting one onto the other recovers the true
        // line-of-sight rate. Only the ANGLE between the two matters, which makes this
        // insensitive to any axis-ordering difference between kspDirUnit's ENU frame
        // and Simpit's -- both vectors are built by the same function here.
        {
          float vHat[3], dHat[3];
          kspDirUnit(t.velocityHeading, t.velocityPitch, vHat);
          kspDirUnit(t.heading,         t.pitch,         dHat);
          const float cosT = vHat[0]*dHat[0] + vHat[1]*dHat[1] + vHat[2]*dHat[2];
          // ship_tgtVelocity is the craft's velocity relative to the target, so it
          // points along craft->target while closing: cosT > 0. Negate for the
          // panel-wide "negative = closing" convention.
          state.tgtVelocity = -t.velocity * cosT;
        }

        // After a vessel switch, contextScreen() runs before tgtDistance is known,
        // so the docking distance check may fail even with a valid nearby target.
        // Re-run contextScreen() once when the first TARGETINFO arrives post-switch.
        // This correctly handles all priorities (plane/rover/lander/dock/orb).
        if (_pendingDockCheck) {
          _pendingDockCheck = false;
          if (debugMode) {
            Serial.print(F("InfoDisp: VesselSwitch TARGETINFO - tgtAvail="));
            Serial.print(state.targetAvailable);
            Serial.print(F(" tgtDist="));
            Serial.println(state.tgtDistance);
          }
          // Re-run the ladder now that target distance is known. The DOCK special
          // case the old code had here is redundant: the mission ladder tests the
          // same distance in rule 3, and on the vehicle-type unit DOCK is not a
          // destination at all, so routing there would have been wrong.
          // A held manual pick and self-pinning screens (RE-ENTRY) stay put.
          if (contextSwitchAllowed()) switchToScreen(contextScreen());
        }
      }
      break;

    // INTERSECTS_MESSAGE is KSP2-only — not registered for KSP1.

    // ── Atmosphere & environment ─────────────────────────────────────────────────────

    case ATMO_CONDITIONS_MESSAGE:
      if (msgSize == sizeof(atmoConditionsMessage)) {
        atmoConditionsMessage a = parseMessage<atmoConditionsMessage>(msg);
        state.airDensity = a.airDensity;
        state.inAtmo     = a.isVesselInAtmosphere();
      }
      break;

    // ── Action groups ────────────────────────────────────────────────────────────────

    case ACTIONSTATUS_MESSAGE:
      if (msgSize >= 1) {
        state.gear_on   = msg[0] & GEAR_ACTION;
        state.brakes_on = msg[0] & BRAKES_ACTION;
        state.rcs_on    = msg[0] & RCS_ACTION;
      }
      break;

    case SAS_MODE_INFO_MESSAGE:
      if (msgSize == sizeof(SASInfoMessage)) {
        SASInfoMessage s = parseSASInfoMessage(msg);
        state.sasMode = s.currentSASMode;  // 255 = SAS disabled, 0 = StabilityAssist, etc.
      }
      break;

    case CAGSTATUS_MESSAGE: {
      if (msgSize != sizeof(cagStatusMessage)) break;   // guard: match the other handlers
      // Cast msg directly to cagStatusMessage and use is_action_activated(n).
      // parseCAGStatusMessage() is deprecated — use the struct directly.
      cagStatusMessage *cag = (cagStatusMessage *)msg;
      if (DROGUE_DEPLOY_CAG >= 1)
        state.drogueDeploy = cag->is_action_activated(DROGUE_DEPLOY_CAG);
      if (DROGUE_CUT_CAG   >= 1)
        state.drogueCut    = cag->is_action_activated(DROGUE_CUT_CAG);
      if (MAIN_DEPLOY_CAG  >= 1)
        state.mainDeploy   = cag->is_action_activated(MAIN_DEPLOY_CAG);
      if (MAIN_CUT_CAG     >= 1)
        state.mainCut      = cag->is_action_activated(MAIN_CUT_CAG);
      if (AIRBRAKE_CAG     >= 1)
        state.airbrake_on  = cag->is_action_activated(AIRBRAKE_CAG);
      break;
    }

    // ── Scene and vessel lifecycle ───────────────────────────────────────────────────

    case SCENE_CHANGE_MESSAGE:
      if (msgSize < 1) break;   // guard: single-byte payload
      // msg[0] == 0 → flight scene; msg[0] == 1 → non-flight (menu, tracking, etc.)
      if (debugMode)
        Serial.println((msg[0] == 0) ? F("InfoDisp: Entering flight scene")
                                     : F("InfoDisp: Leaving flight scene"));
      if (msg[0] == 0) {
        enterFlightScene();
      } else {
        flightScene = false;
        // Non-flight (menus, tracking station, etc.) — show standby splash
        demoMode = false;
        drawStandbyScreen(infoDisp);
        switchToScreen(SCREEN_HOME);   // park on this panel's home screen behind the splash
      }
      break;

    case VESSEL_CHANGE_MESSAGE:
      if (msgSize < 1) break;   // guard: single-byte payload
      if (msg[0] == 1) {
        // Vessel switch (focus changed to another vessel).
        // Guard: if we just docked (within 2s), KSP sends a vessel switch immediately
        // as focus transfers to the combined vessel. Don't clear _vesselDocked in that case.
        bool recentDock = (_vesselDocked && (millis() - _dockedTimestamp < 2000UL));
        if (!recentDock) {
          _vesselDocked = false;
        }
        _pendingDockCheck = false;  // clear any stale dock check from previous switch
        if (debugMode) Serial.println(F("InfoDisp: Vessel switch"));
        // Reset per-vessel screen state. (_lndgReentryMode is not touched: it is derived
        // from the active screen by drawStaticScreen() / updateScreen().)
        _scftPrevOrbMode    = false;   // #50 reset SCFT orbital-mode state on vessel switch
        _pfdManualOverride  = false;   // reset the PFD sidebar-cycle override; use context for new vessel
        clearManualScreenLatch();      // new vessel — release the held manual pick
        resetContextRouting();         //   and the routing state with it
        modeClearOverride(_scftVelRefOverride);   // and the held attitude references
        modeClearOverride(_acftAltRefOverride);
        _lnchManualOverride = false;   // LAUNCH phase override and coast latch belong to
        _lnchOrbitalMode    = false;   //   the old vessel; the new one re-derives them
        _lnchCoastLatched   = false;
        rovrEnduranceReset();          // the charge window is the old vessel's
        _lndgReentryRow0TPe = false;
        _lndgReentryRow1SL  = false;
        _drogueDeployed  = false;
        _mainDeployed    = false;
        _drogueCut       = false;
        _mainCut         = false;
        _drogueArmedSafe = false;
        _mainArmedSafe   = false;
        // Invalidate all row caches so everything redraws on the new vessel
        invalidateAllRowCache();
        // Don't call contextScreen() here — state.vesselType is still the OLD vessel's
        // type at this point. FLIGHT_STATUS_MESSAGE with the new vessel's type will
        // arrive shortly; set a flag and do the context switch when it does.
        _pendingContextSwitch = true;
        // Request a full telemetry refresh so all fields repopulate immediately
        simpit.requestMessageOnChannel(0);
      } else if (msg[0] == 2) {
        // Docked
        if (debugMode) Serial.println(F("InfoDisp: Docked"));
        _vesselDocked = true;
        _dockedTimestamp = millis();
        // Force DOCK screen chrome to redraw so DOCKED splash appears
        if (activeScreen == screen_DOCK) switchToScreen(screen_DOCK);
      } else if (msg[0] == 3) {
        // Undocked
        if (debugMode) Serial.println(F("InfoDisp: Undocked"));
        _vesselDocked = false;
        // Force DOCK screen chrome to redraw so normal or NO TARGET state appears
        if (activeScreen == screen_DOCK) switchToScreen(screen_DOCK);
      }
      break;
  }
}


/***************************************************************************************
   INIT SIMPIT
   Connects to KSP via SerialUSB1 and registers all telemetry channels.
   Blocks until the handshake succeeds.
****************************************************************************************/
void initSimpit() {
  simpit.inboundHandler(onSimpitMessage);
  while (!simpit.init()) {
    if (debugMode) Serial.println(F("InfoDisp: Simpit handshake failed, retrying..."));
    delay(500);
  }
  if (debugMode) Serial.println(F("InfoDisp: Simpit connected."));
  simpitConnected = true;

  simpit.registerChannel(VESSEL_NAME_MESSAGE);
  simpit.registerChannel(SOI_MESSAGE);
  simpit.registerChannel(FLIGHT_STATUS_MESSAGE);
  simpit.registerChannel(ALTITUDE_MESSAGE);
  simpit.registerChannel(VELOCITY_MESSAGE);
  simpit.registerChannel(AIRSPEED_MESSAGE);
  simpit.registerChannel(APSIDES_MESSAGE);
  simpit.registerChannel(APSIDESTIME_MESSAGE);
  simpit.registerChannel(DELTAV_MESSAGE);
  simpit.registerChannel(BURNTIME_MESSAGE);
  simpit.registerChannel(ORBIT_MESSAGE);
  simpit.registerChannel(ROTATION_DATA_MESSAGE);
  simpit.registerChannel(MANEUVER_MESSAGE);
  simpit.registerChannel(TARGETINFO_MESSAGE);
  // INTERSECTS_MESSAGE omitted — KSP2 only, not available in KSP1
  simpit.registerChannel(ATMO_CONDITIONS_MESSAGE);
  simpit.registerChannel(ACTIONSTATUS_MESSAGE);
  simpit.registerChannel(SAS_MODE_INFO_MESSAGE);
  simpit.registerChannel(CAGSTATUS_MESSAGE);
  simpit.registerChannel(THROTTLE_CMD_MESSAGE);
  simpit.registerChannel(WHEEL_CMD_MESSAGE);
  simpit.registerChannel(ELECTRIC_MESSAGE);
  simpit.registerChannel(TEMP_LIMIT_MESSAGE);
  simpit.registerChannel(SCENE_CHANGE_MESSAGE);
  simpit.registerChannel(VESSEL_CHANGE_MESSAGE);
}

/***************************************************************************************
   TouchEvents.ino -- Touch input for Kerbal Controller Mk1 Information Display

   Touch is polled via KCM_Touch each processTouchEvents() call (rev-2 FT5316; no ISR --
   the rev-1 CTP_INT_PIN touchISR()/_touchPending latch is gone).

   Defence layers:
   1. Boot guard — nothing is accepted until the panel has once been seen untouched,
      so a settling touch from the FT5316 right after reset cannot fire a gesture.
   2. Count filter — accept only count == 1. Multi-finger events on a single-button
      sidebar are never intentional; count != 1 is a strong phantom signal. Applied to
      both the first read and the confirmation re-read.
   3. Bounds check — reject x >= SCREEN_W or y >= SCREEN_H.
   4. Double-read with coordinate stability — re-read after 8ms; reject if the re-read
      count != 1 OR if coordinates moved more than TOUCH_JITTER_MAX pixels.
      Phantom noise jumps around between reads; real touches are stable.
   5. Debounce — TOUCH_DEBOUNCE_MS between taps, shortened to TOUCH_CYCLE_DEBOUNCE_MS
      for a repeat press on the same sidebar key (see below).
   6. Require-release — set on ANY confirmed touch, suppressing the rest of a burst
      until the panel is seen untouched again.
   (The rev-1 bottom-row dead zone is gone: it was a GSL1680 edge-noise workaround, and
   the FT5316 does not ghost at the panel boundary.)
****************************************************************************************/
#include "KCMk1_InfoDisp.h"


static const uint32_t TOUCH_DEBOUNCE_MS  = KCM_TOUCH_DEBOUNCE_MS;     // #3B from SystemConfig
static const uint16_t TOUCH_JITTER_MAX   = KCM_TOUCH_JITTER_MAX_PX;   // #3B px — max coordinate movement across reads

// Repeat press on the SAME sidebar button — a deliberate mode cycle. The full 500 ms
// window is a phantom-rejection budget sized for an arbitrary tap anywhere on the
// panel; it makes cycling punitive, since reaching VEH from SPC costs three presses
// and therefore 1.5 s of enforced waiting. A second press on a button the pilot just
// pressed is the least ambiguous input the panel receives, and layer 7 (require-
// release) already guarantees the finger lifted in between, so it gets a shorter
// window. Every other tap — a first press, a different button, anything in the
// content area — keeps the full budget.
static const uint32_t TOUCH_CYCLE_DEBOUNCE_MS = 150;

static uint32_t lastTouchTime      = 0;
static bool     _waitForRelease    = false;
static uint8_t  _lastSidebarBtn    = 0xFF;   // last sidebar button pressed (0xFF = none)

// Boot phantom guard: require the panel to be seen untouched once before accepting
// any tap, so a settling touch from the FT5316 right after reset cannot fire a
// gesture. Cleared to true the first time the screen is observed untouched.
static bool _bootReleaseSeen = false;


void processTouchEvents() {
  if (!isTouched()) {
    _waitForRelease  = false;
    _bootReleaseSeen = true;   // panel seen untouched — real taps now allowed
    return;
  }
  if (!_bootReleaseSeen) return;   // ignore boot/settling phantom until first release

  // First read
  lastTouch = readTouch();
  if (lastTouch.count == 0) return;

  // Count filter — real single-button presses are always count=1
  if (lastTouch.count != 1) {
    if (debugMode) {
      Serial.print(F("InfoDisp: Touch discarded (count="));
      Serial.print(lastTouch.count);
      Serial.println(F(")"));
    }
    return;
  }

  if (_waitForRelease) return;

  uint16_t x1 = lastTouch.points[0].x;
  uint16_t y1 = lastTouch.points[0].y;

  // Pick the debounce window before spending 8 ms on the confirmation re-read. The
  // first-read coordinates are good enough to classify the tap; the confirmation
  // still has to agree with them, so a phantom cannot buy the shorter window.
  uint32_t now        = millis();
  uint32_t debounceMs = TOUCH_DEBOUNCE_MS;
  if (touchInSidebar(x1) && _lastSidebarBtn != 0xFF &&
      (uint8_t)(y1 / sbBtnH()) == _lastSidebarBtn) {
    debounceMs = TOUCH_CYCLE_DEBOUNCE_MS;
  }
  if (now - lastTouchTime < debounceMs) return;

  // Double-read after 8ms — confirm the touch is real and stable (phantom noise
  // jumps between reads; real touches hold position).
  delay(8);
  TouchResult confirm = readTouch();
  if (confirm.count != 1) {
    if (debugMode) Serial.println(F("InfoDisp: Touch discarded (phantom — count != 1 on reread)"));
    return;
  }
  uint16_t x2 = confirm.points[0].x;
  uint16_t y2 = confirm.points[0].y;
  uint16_t dx = (x2 > x1) ? x2 - x1 : x1 - x2;
  uint16_t dy = (y2 > y1) ? y2 - y1 : y1 - y2;
  if (dx > TOUCH_JITTER_MAX || dy > TOUCH_JITTER_MAX) {
    if (debugMode) {
      Serial.print(F("InfoDisp: Touch discarded (jitter dx="));
      Serial.print(dx);
      Serial.print(F(" dy="));
      Serial.print(dy);
      Serial.println(F(")"));
    }
    return;
  }
  lastTouch = confirm;

  // Bounds check — applied to final coordinates
  if (x2 >= SCREEN_W || y2 >= SCREEN_H) return;

  // Title-bar taps no longer switch modes — mode switching moved to the sidebar
  // buttons (see the sidebar hit test below). A tap on the title bar (y < TITLE_TOP,
  // x < CONTENT_W) simply falls through and is a no-op.

  // Stamp debounce and require-release immediately — suppresses burst tail
  lastTouchTime = now;
  _waitForRelease = true;
  // Cleared here and re-set below only if this tap lands on a sidebar button, so the
  // shortened cycle window is available strictly for a run of presses on one button.
  _lastSidebarBtn = 0xFF;

  if (debugMode) {
    Serial.print(F("InfoDisp: Touch count="));
    Serial.print(lastTouch.count);
    Serial.print(F(" x="));
    Serial.print(x2);
    Serial.print(F(" y="));
    Serial.println(y2);
  }

  // Pre-launch board: tap anywhere in content area to advance to ascent mode
  if (activeScreen == screen_LNCH && _lnchPrelaunchMode &&
      touchInContent(x2) && y2 >= TITLE_TOP) {
    _lnchPrelaunchMode      = false;
    _lnchPrelaunchDismissed = true;   // prevent FLIGHT_STATUS from re-entering
    _lnchOrbitalMode        = false;
    _lnchManualOverride     = false;
    switchToScreen(screen_LNCH);   // full chrome redraw
    if (debugMode) Serial.println(F("InfoDisp: Pre-launch board dismissed by tap"));
    return;
  }

  // Attitude screens: the reference chip. One tap pins the other reference (or drops
  // back to auto); the chip's colour says which state it is in. The ball itself is
  // deliberately NOT a target -- it is the primary instrument, and a stray touch
  // changing the reference mid-burn is a bad way to find that out.
  if ((activeScreen == screen_SCFT || activeScreen == screen_ACFT) &&
      touchInContent(x2) && y2 >= TITLE_TOP &&
      refChipHit(touchContentX(x2), y2)) {
    if (activeScreen == screen_SCFT) scftToggleVelRef();
    else                             acftToggleAltRef();
    if (debugMode) Serial.println(F("InfoDisp: reference chip tapped"));
    return;
  }

  // Ascent Autopilot: content-area taps drive its on-screen keypad / editable
  // fields / ARM button. Sidebar taps (x past the content area) fall through.
  if (activeScreen == screen_LNCHAP && touchInContent(x2) && y2 >= TITLE_TOP) {
    // apScreenTouch() lays its keypad out in content space — hand it the translated x.
    apScreenTouch(touchContentX(x2), y2);
    return;
  }
  // Hold-mode consoles: mode buttons, setpoint boxes, LVL / A/P OFF, shared keypad.
  if (activeScreen == screen_ACFTAP && touchInContent(x2) && y2 >= TITLE_TOP) {
    acftApScreenTouch(touchContentX(x2), y2);
    return;
  }
  if (activeScreen == screen_ROVRAP && touchInContent(x2) && y2 >= TITLE_TOP) {
    rovrApScreenTouch(touchContentX(x2), y2);
    return;
  }
  if (activeScreen == screen_ORBTAP && touchInContent(x2) && y2 >= TITLE_TOP) {
    orbtApScreenTouch(touchContentX(x2), y2);
    return;
  }
  if (activeScreen == screen_LNDGAP && touchInContent(x2) && y2 >= TITLE_TOP) {
    lndgApScreenTouch(touchContentX(x2), y2);
    return;
  }

  // Sidebar hit test — the SIDEBAR_W column on this unit's outboard edge (left on
  // unit 1, right on unit 2), 6 buttons (SB_BTN_SCREEN).
  // First press of a button (from another screen) goes to that button's context/
  // primary mode; pressing the button that already owns the active screen cycles
  // its modes. Context auto-select still runs on scene/vessel change; a press
  // latches a manual override for the multi-mode buttons.
  if (touchInSidebar(x2)) {
    uint8_t btn = (uint8_t)(y2 / sbBtnH());
    if (btn >= SB_BTN_COUNT) return;
    _lastSidebarBtn = btn;   // arms the shortened debounce for a repeat press

    bool       active   = (screenToButton(activeScreen) == btn);
    ScreenType target   = activeScreen;
    bool       doSwitch = false;

    if (!active) {
      // First press — jump to the button's context/primary screen.
      switch (btn) {
        case SB_PFD_BTN:
          target = pfdSelectedScreen();   // context or last manual PFD sub-screen
          break;
        case SB_TGTDOCK_BTN:
          // Context: docking screen when a target is within docking range, else target.
          target = (state.tgtDistance > 0.0f && state.tgtDistance <= DOCK_DIST_WARN_M)
                     ? screen_DOCK : screen_TGT;
          break;
        case SB_LNDG_BTN:
          target = screen_LNDG;           // primary = powered descent (DESC)
          break;
#if INFO_DISP_IS_MISSION_UNIT
        case SB_AP_BTN:
          target = apConsoleContextScreen();   // console for the vessel type
          break;
#endif
        default:
          target = SB_BTN_SCREEN[btn];    // LNCH (PRE/ASC/CIRC per flags), ORB, single-mode
          break;
      }
      doSwitch = (target != activeScreen);
    } else {
      // Already on this button — cycle its modes.
      switch (btn) {
        case SB_LNCH_BTN:
          if (_lnchPrelaunchMode) {
            // Dismiss the pre-launch board into the ascent view.
            _lnchPrelaunchMode      = false;
            _lnchPrelaunchDismissed = true;
            _lnchOrbitalMode        = false;
          } else {
            _lnchOrbitalMode = !_lnchOrbitalMode;   // ASC <-> CIRC
          }
          _lnchManualOverride = true;
          target = screen_LNCH; doSwitch = true;
          break;
        case SB_PFD_BTN: {
          // Ring depth is per unit: unit 1 promoted VEH to its own button, so its
          // ring is the three attitude screens (SPC -> ACFT -> ROVR). Unit 2, where
          // the PFD button is the off-role one, keeps all four in the ring.
          const uint8_t PFD_RING_LEN = INFO_DISP_IS_PFD_UNIT ? 3 : 4;
          uint8_t cur = (activeScreen == screen_VEH)  ? 3 :
                        (activeScreen == screen_ROVR) ? 2 :
                        (activeScreen == screen_ACFT) ? 1 : 0;
          _pfdManualSel      = (uint8_t)((cur + 1) % PFD_RING_LEN);
          _pfdManualOverride = true;
          target = pfdScreenForSel(_pfdManualSel); doSwitch = true;
          break;
        }
        case SB_ORB_BTN:
          // ORB -> ORB+ -> MNVR -> ORB
          target = (activeScreen == screen_ORB)    ? screen_ORBADV :
                   (activeScreen == screen_ORBADV) ? screen_MNVR   : screen_ORB;
          doSwitch = true;
          break;
        case SB_TGTDOCK_BTN:
          // TGT -> DOCK -> NAV. The boresight view of the target, the close-in
          // approach view, and the plan view — the same question at three ranges.
          target = (activeScreen == screen_TGT)  ? screen_DOCK
                 : (activeScreen == screen_DOCK) ? screen_NAV : screen_TGT;
          doSwitch = true;
          break;
        case SB_LNDG_BTN:
          target = (activeScreen == screen_LNDGRE) ? screen_LNDG : screen_LNDGRE;
          doSwitch = true;
          break;
#if INFO_DISP_IS_MISSION_UNIT
        case SB_AP_BTN:
          // The autopilot consoles, filtered by vessel type (apConsoleNext).
          target   = apConsoleNext(activeScreen);
          doSwitch = (target != activeScreen);
          break;
#endif
        default:
          doSwitch = false;   // single-mode button already active — nothing to cycle
          break;
      }
    }

    // Latch policy, applied whether or not the press changes the screen: pressing
    // through to the screen the ladder currently wants is an explicit return to
    // automatic; anything else is an override, recorded against the ladder's current
    // answer so it releases once that situation passes. See AAA_Globals.ino.
    if (target == contextScreen()) clearManualScreenLatch();
    else                           setManualScreenLatch();

    if (doSwitch) {
      switchToScreen(target);
      noteManualScreenSwitch();   // a press gets its own dwell — see updateContextScreen
      }
  }

}
